This section contains the contents of the repository's files.//! This module defines the interface of a Nickel configuration which is used to derive the
//! customize mode of the command-line.
use super::*;

use nickel_lang_core::eval::value::{Container, NickelValue};

/// The interface of a configuration (a Nickel program) which represents all nested field paths
/// that are accessible from the root term together with their associated metadata.
///
/// Interface is used to derive a command-line interface from a configuration when using the
/// `customize_mode` option.
#[derive(Debug, Clone, Default)]
pub(super) struct ValueInterface {
    pub(super) fields: HashMap<LocIdent, FieldInterface>,
}

/// The interface of a specific field. This field can be itself a record and contain subfields.
#[derive(Debug, Clone, Default)]
pub(super) struct FieldInterface {
    /// The interface of the subfields of this field, if it's a record itself.
    pub(super) subfields: Option<ValueInterface>,
    pub(super) field: Field,
}

impl Combine for ValueInterface {
    fn combine(first: Self, second: Self) -> Self {
        let ValueInterface { mut fields } = first;

        for (id, field) in second.fields.into_iter() {
            if let Some(prev) = fields.remove(&id) {
                fields.insert(id, Combine::combine(prev, field));
            } else {
                fields.insert(id, field);
            }
        }

        ValueInterface { fields }
    }
}

impl Combine for FieldInterface {
    fn combine(first: Self, second: Self) -> Self {
        FieldInterface {
            subfields: Combine::combine(first.subfields, second.subfields),
            field: Field {
                metadata: Combine::combine(first.field.metadata, second.field.metadata),
                // Value is used only to show a default value, and to determine if a field has a
                // definition. We don't bother actually merging the content, but just keep any
                // side that is defined.
                value: first.field.value.or(second.field.value),
                ..Default::default()
            },
        }
    }
}

impl From<&RecordData> for ValueInterface {
    fn from(value: &RecordData) -> Self {
        ValueInterface {
            fields: value
                .fields
                .iter()
                .map(|(id, field)| (*id, field.into()))
                .collect(),
        }
    }
}

impl From<&NickelValue> for ValueInterface {
    fn from(value: &NickelValue) -> Self {
        value.extract_interface().unwrap_or_default()
    }
}

trait ExtractInterface {
    fn extract_interface(&self) -> Option<ValueInterface>;
}

impl ExtractInterface for NickelValue {
    fn extract_interface(&self) -> Option<ValueInterface> {
        self.as_record().map(|container| match container {
            Container::Empty => ValueInterface {
                fields: HashMap::new(),
            },
            Container::Alloc(record) => record.into(),
        })
    }
}

impl ExtractInterface for Field {
    fn extract_interface(&self) -> Option<ValueInterface> {
        self.value.as_ref().map(ValueInterface::from)
    }
}

impl ExtractInterface for Type {
    fn extract_interface(&self) -> Option<ValueInterface> {
        match &self.typ {
            TypeF::Record(rrows) => Some(ValueInterface {
                fields: rrows
                    .iter()
                    .filter_map(|item| {
                        if let RecordRowsIteratorItem::Row(rrow) = item {
                            Some((rrow.id, FieldInterface::from(&rrow)))
                        } else {
                            None
                        }
                    })
                    .collect(),
            }),
            // Contract information is already extracted from runtime contracts, which are
            // evaluated. Here, we focus on pure static type annotations and ignore flat types as
            // well
            _ => None,
        }
    }
}

impl ExtractInterface for RuntimeContract {
    fn extract_interface(&self) -> Option<ValueInterface> {
        self.contract.extract_interface()
    }
}

impl ExtractInterface for LabeledType {
    fn extract_interface(&self) -> Option<ValueInterface> {
        self.typ.extract_interface()
    }
}

impl From<&Field> for FieldInterface {
    fn from(field: &Field) -> Self {
        // We collect field information from all the sources we can: static types and contracts
        // (both either as type annotations or contract annotations), and the value of the field if
        // it's a record.

        let subfields_from_types = field
            .pending_contracts
            .iter()
            .map(ExtractInterface::extract_interface);

        let subfields_from_contracts = field
            .metadata
            .iter_annots()
            .map(ExtractInterface::extract_interface);

        let subfields_from_value = std::iter::once(field.extract_interface());

        let subfields = subfields_from_types
            .chain(subfields_from_contracts)
            .chain(subfields_from_value)
            .reduce(Combine::combine)
            .flatten();

        FieldInterface {
            subfields,
            field: field.clone(),
        }
    }
}

impl From<&RecordRowF<&Type>> for FieldInterface {
    fn from(rrow: &RecordRowF<&Type>) -> Self {
        FieldInterface {
            subfields: rrow.typ.extract_interface(),
            ..Default::default()
        }
    }
}

impl FieldInterface {
    /// Define if a field is an input of a configuration that is intended to be filled. If the
    /// field is not an input, it can only be overridden via `--override`.
    ///
    /// Currently, the difference is mostly conceptual: in practice, we simply gather the arguments
    /// and their values, either via direct positional arguments or `--override` (although the
    /// latter sets a different priority), and then merge the elaborated record with original term.
    ///
    /// However, from a user experience point of view, we want to make a clear distinction between
    /// filling a bespoke input of a configuration and overriding an existing value. The latter is
    /// more "low-level" and should only be done knowingly.
    ///
    /// Currently, the logic is simply that a field is an input if it doesn't have a definition or
    /// it has a default priority. This definition might evolve, as there are ongoing discussions
    /// on what is the meaning of "input", "output", and if those concept should be made
    /// first-class ([related issue](https://github.com/tweag/nickel/issues/1505)). For now, this
    /// logic seems to be a reasonable first approximation.
    pub(super) fn is_input(&self) -> bool {
        !self.is_defined() || self.is_default()
    }

    /// Return `true` is the field has a value.
    pub(super) fn is_defined(&self) -> bool {
        self.field.value.is_some()
    }

    /// Return true is the field's merge priority is `default`.
    pub(super) fn is_default(&self) -> bool {
        matches!(self.field.metadata.priority(), MergePriority::Bottom)
    }

    pub(super) fn has_subfields(&self) -> bool {
        matches!(&self.subfields, Some(intf) if !intf.fields.is_empty())
    }

    /// Return the list of the type and contract annotations joined as a comma-separated string, if
    /// any.
    pub(super) fn type_and_contracts(&self) -> Option<String> {
        let annotation = &self.field.metadata.as_ref()?.annotation;

        (!annotation.is_empty()).then(|| {
            let anns: Vec<String> = annotation
                .iter()
                .map(|ctr| ctr.label.typ.to_string())
                .collect();

            anns.join(",")
        })
    }
}//! Customize mode parser and evaluation logic.
//!
//! The customize mode is a way to interact with a specific Nickel program on the command line by
//! setting or overriding values directly from the command line. It's currently enabled by the
//! freeform marker `--`.
use std::{collections::HashMap, ffi::OsString};

use clap::Parser;
use nickel_lang_core::{
    combine::Combine,
    eval::cache::CacheImpl,
    identifier::LocIdent,
    program::{FieldPath, Program},
    term::{
        LabeledType, MergePriority, RuntimeContract,
        record::{Field, RecordData},
    },
    typ::{RecordRowF, RecordRowsIteratorItem, Type, TypeF},
};

use crate::{
    error::{CliResult, CliUsageError, Error, UnknownFieldData},
    input::{PrepareError, PrepareResult},
};

pub mod interface;

use interface::{FieldInterface, ValueInterface};

/// The value name used through the CLI to indicate that an option accepts any Nickel expression as
/// a value.
const ASSIGNMENT_SYNTAX: &str = "FIELD_PATH=NICKEL_EXPRESSION";

const EXPERIMENTAL_MSG: &str =
    "WARNING: Customize mode is experimental. Its interface is subject to breaking changes.";

/// For commands where full customization is allowed, combining extracting a target field and
/// overriding arbitrary values of the configuration.
#[derive(clap::Parser, Debug)]
pub struct CustomizeMode {
    #[command(flatten)]
    extract_field: ExtractFieldOnly,

    /// WARNING: Customize mode is experimental. Its interface is subject to breaking changes.
    ///
    /// Customize mode turns the nickel invocation into a new CLI based on the configuration to be
    /// exported, where the value of fields can be set directly through CLI arguments. Print the
    /// corresponding help (`nickel [COMMAND] <file.ncl> -- --help`) to see available options.
    #[arg(last = true)]
    pub customize_mode: Vec<OsString>,
}

#[derive(clap::Parser)]
#[command(
    name = "customize-mode",
    after_help = EXPERIMENTAL_MSG,
    no_binary_name = true,
)]
/// Customize a Nickel configuration through the command line.
struct CustomizeOptions {
    /// Assign a valid Nickel expression to an input field of the configuration. The new value
    /// will be merged with the configuration with priority 0 (the one assigned by default in
    /// Nickel when no explicit merge priority is provided).
    ///
    /// Assignment can only set input fields, that is fields without definition or fields with
    /// a default value. To override an existing value, use `--override` instead.
    ///
    /// Note that you might have to escape special characters or enclose assignments in quotes to
    /// prevent shell interpretation.
    ///
    /// Example: `nickel eval config.ncl -- 'http.enabled="yes"' protocol=\'ftp`
    ///
    /// In addition to Nickel values, the left hand side of the assignment can be a special
    /// expression introduced by the `@` sigil, with the syntax
    /// `@<selector>[/<attribute>]:<argument>`.
    ///
    /// Example: `nickel eval config.ncl -- vars.home=@env:HOME vars.path=@env:PATH`
    #[clap(value_name = ASSIGNMENT_SYNTAX)]
    assignment: Vec<String>,

    /// Override any field of the configuration with a valid Nickel expression. The new value
    /// will be merged with the configuration with a `force` priority.
    ///
    /// Note that you might have to escape special characters or enclose assignments in quotes to
    /// prevent shell interpretation.
    ///
    /// Example: `-- input.value=false --override m.count=2 --override m.type=\'server`
    #[clap(long = "override", value_name = ASSIGNMENT_SYNTAX)]
    ovd: Vec<String>,

    #[command(subcommand)]
    pub command: Option<CustomizeCommand>,
}

#[derive(clap::Subcommand)]
enum CustomizeCommand {
    /// List the input fields and the overridable fields of the configuration.
    List(ListCommand),
}

#[derive(clap::Parser)]
struct ListCommand;

impl ListCommand {
    fn run(self, customize_fields: &CustomizableFields) -> CliResult<()> {
        let mut inputs = customize_fields
            .inputs
            .iter()
            .map(|(path, field)| {
                let extra = field
                    .type_and_contracts()
                    .map(|ctrs| format!(": <{ctrs}>"))
                    .unwrap_or_default();
                format!("{path}{extra}")
            })
            .collect::<Vec<_>>();

        inputs.sort();

        let mut overrides = customize_fields
            .overrides
            .iter()
            .map(|(path, field)| {
                let extra = field
                    .type_and_contracts()
                    .map(|ctrs| format!(": <{ctrs}>"))
                    .unwrap_or_default();
                format!("{path}{extra}")
            })
            .collect::<Vec<_>>();

        overrides.sort();

        println!("Input fields:");
        for input in inputs {
            println!("- {input}");
        }

        println!("\nOverridable fields (require `--override`):");
        for override_ in overrides {
            println!("- {override_}");
        }

        println!(
            "\nUse the `query` subcommand to print a detailed description of a specific field. \
            See `nickel help query`."
        );
        Ok(())
    }
}

#[derive(clap::Parser)]
struct DoCommand {
    /// Assign a valid Nickel expression to an input field of the configuration. The new value
    /// will be merged with the configuration with priority 0 (the one assigned by default in
    /// Nickel when no explicit merge priority is provided).
    ///
    /// Assignment can only set input fields, that is fields without definition or fields with
    /// a default value. To override an existing value, use `--override` instead.
    #[clap(value_name = ASSIGNMENT_SYNTAX)]
    assignment: Vec<String>,

    /// Override any field of the configuration with a valid Nickel expression. The new value
    /// will be merged with the configuration with a `force` priority.
    #[clap(long = "override", value_name = ASSIGNMENT_SYNTAX)]
    ovd: Vec<String>,
}

impl DoCommand {}

/// Fields of the configuration which aren't themselves records and can be assigned or overridden
/// through the customize mode.
#[derive(Clone, Debug, Default)]
struct CustomizableFields {
    inputs: HashMap<FieldPath, FieldInterface>,
    overrides: HashMap<FieldPath, FieldInterface>,
}

impl CustomizableFields {
    /// Create data from a term interface.
    fn new(term_iface: ValueInterface) -> Self {
        let mut this = Self::default();

        for (id, field_iface) in term_iface.fields {
            this.extend_with(field_iface, FieldPath(vec![id]));
        }

        this
    }

    /// Register a customizable field that can be assigned (input).
    fn register_input(&mut self, path: FieldPath, interface: FieldInterface) {
        debug_assert!(!self.inputs.contains_key(&path));
        debug_assert!(!self.overrides.contains_key(&path));

        self.inputs.insert(path, interface);
    }

    /// Register a customizable field that can be overridden.
    fn register_override(&mut self, path: FieldPath, interface: FieldInterface) {
        debug_assert!(!self.inputs.contains_key(&path));
        debug_assert!(!self.overrides.contains_key(&path));

        self.overrides.insert(path, interface);
    }

    /// Enrich the current list of customizable fields with the field(s) exposed by a given field
    /// interface.
    fn extend_with(&mut self, field_iface: FieldInterface, path: FieldPath) {
        // This is a terminal field, which gives rise to an argument or an overridable value.
        if !field_iface.has_subfields() {
            if field_iface.is_input() {
                self.register_input(path.clone(), field_iface);
            } else {
                self.register_override(path.clone(), field_iface);
            }
        } else {
            for (id, child_iface) in field_iface
                .subfields
                .into_iter()
                .flat_map(|intf| intf.fields.into_iter())
            {
                let mut path = path.clone();
                path.0.push(id);

                self.extend_with(child_iface, path);
            }
        }
    }

    /// Return a vector of all the paths of the input fields and the overridable fields. In case of
    /// a unknown field error, this list is used to suggest similar-looking field paths that the
    /// user could have meant instead.
    fn field_list(&self) -> Vec<FieldPath> {
        self.inputs
            .keys()
            .chain(self.overrides.keys())
            .cloned()
            .collect()
    }
}

pub trait Customize {
    /// Customize the program with the given options.
    fn customize(&self, program: Program<CacheImpl>) -> PrepareResult<Program<CacheImpl>>;
    /// Return the value of the `field` argument, if specified and if supported by the current
    /// customize variant.
    fn field(&self) -> Option<&String> {
        None
    }
}

impl CustomizeOptions {
    // Actually parse assignments and overrides from the command line and add them accordingly to
    // `program`, given an interface of customizable fields.
    fn do_customize(
        self,
        customizable_fields: CustomizableFields,
        mut program: Program<CacheImpl>,
    ) -> CliResult<Program<CacheImpl>> {
        let assignment_overrides: Result<Vec<_>, CliUsageError> = self
            .assignment
            .into_iter()
            .map(|assignment| {
                let ovd = program
                    .parse_override(assignment, MergePriority::default())
                    .map_err(|error| CliUsageError::AssignmentParseError { error })?;

                if !customizable_fields.inputs.contains_key(&ovd.path) {
                    if customizable_fields.overrides.contains_key(&ovd.path) {
                        Err(CliUsageError::CantAssignNonInput { ovd })
                    } else {
                        Err(CliUsageError::UnknownFieldAssignment(UnknownFieldData {
                            path: ovd.path,
                            field_list: customizable_fields.field_list(),
                        }))
                    }
                } else {
                    Ok(ovd)
                }
            })
            .collect();

        let assignment_overrides = match assignment_overrides {
            Ok(assignment_overrides) => assignment_overrides,
            Err(error) => {
                return CliResult::Err(Error::CliUsage {
                    error,
                    files: program.files(),
                });
            }
        };

        let force_overrides: Result<Vec<_>, CliUsageError> = self
            .ovd
            .into_iter()
            .map(|assignment| {
                let ovd = program
                    .parse_override(assignment, MergePriority::Top)
                    .map_err(|error| CliUsageError::AssignmentParseError { error })?;

                if !customizable_fields.inputs.contains_key(&ovd.path)
                    && !customizable_fields.overrides.contains_key(&ovd.path)
                {
                    Err(CliUsageError::UnknownFieldOverride(UnknownFieldData {
                        path: ovd.path,
                        field_list: customizable_fields.field_list(),
                    }))
                } else {
                    Ok(ovd)
                }
            })
            .collect();

        let force_overrides = match force_overrides {
            Ok(force_overrides) => force_overrides,
            Err(error) => {
                return CliResult::Err(Error::CliUsage {
                    error,
                    files: program.files(),
                });
            }
        };

        program.add_overrides(assignment_overrides.into_iter().chain(force_overrides));
        Ok(program)
    }
}

impl CustomizeMode {
    // Contains most of the actual implementation of the customizing logic for overriding, but
    // doesn't set the extracted field.
    fn customize_impl(&self, mut program: Program<CacheImpl>) -> PrepareResult<Program<CacheImpl>> {
        if self.customize_mode.is_empty() {
            return Ok(program);
        }

        let evaled = program
            .eval_record_spine()
            .map_err(|error| Error::Program {
                error,
                files: program.files(),
            })?;

        let customizable_fields = CustomizableFields::new(ValueInterface::from(&evaled));
        let opts = CustomizeOptions::parse_from(self.customize_mode.iter());

        match opts.command {
            None => Ok(opts.do_customize(customizable_fields, program)?),
            Some(CustomizeCommand::List(list_command)) => {
                list_command.run(&customizable_fields)?;
                Err(PrepareError::EarlyReturn)
            }
        }
    }
}

impl Customize for CustomizeMode {
    // XXX: we should give a nice error message when someone tries to evaluate some
    //      expression that has unset values, telling them they can set them using
    //      this method
    fn customize(&self, program: Program<CacheImpl>) -> PrepareResult<Program<CacheImpl>> {
        program_with_field(
            self.customize_impl(program)?,
            self.extract_field.field.clone(),
        )
    }

    fn field(&self) -> Option<&String> {
        self.extract_field.field.as_ref()
    }
}

/// For commands when no overriding is allowed, but a target field can still be specified, such as
/// `nickel query` or `nickel doc`.
#[derive(clap::Parser, Debug)]
pub struct ExtractFieldOnly {
    /// Only query or act on a specific field of the configuration. For example,
    /// `nickel export config.ncl --field machines.servers.remote_builder` will only evaluate and
    /// export the content of the `remote_builder` field.
    #[arg(long, value_name = "FIELD_PATH")]
    pub field: Option<String>,
}

impl Customize for ExtractFieldOnly {
    fn customize(&self, program: Program<CacheImpl>) -> PrepareResult<Program<CacheImpl>> {
        program_with_field(program, self.field.clone())
    }

    fn field(&self) -> Option<&String> {
        self.field.as_ref()
    }
}

/// For commands when no customization is allowed at all.
#[derive(clap::Args, Debug)]
pub struct NoCustomizeMode;

impl Customize for NoCustomizeMode {
    fn customize(&self, program: Program<CacheImpl>) -> PrepareResult<Program<CacheImpl>> {
        Ok(program)
    }
}

fn program_with_field(
    mut program: Program<CacheImpl>,
    field: Option<String>,
) -> PrepareResult<Program<CacheImpl>> {
    if let Some(field) = field {
        program.field = program
            .parse_field_path(field)
            .map_err(|error| Error::CliUsage {
                error: CliUsageError::FieldPathParseError { error },
                files: program.files(),
            })?;
    }

    Ok(program)
}//! Command-line options and subcommands.

