#[derive(Debug)]
pub enum FormatError {
    NotAFile {
        path: PathBuf,
    },
    FailedToFormat(nickel_lang_core::format::FormatError),
    /// This file needs formatting
    BadFormat(PathBuf),
    /// Data provided on stdin is badly formatted
    BadFormatStdin,
}

impl Display for FormatError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FormatError::NotAFile { path } => {
                write!(
                    f,
                    "The path {} does not refer to a file.",
                    path.to_string_lossy()
                )
            }
            FormatError::FailedToFormat(e) => e.fmt(f),
            FormatError::BadFormat(path) => {
                write!(
                    f,
                    "Bad format: {path:?}, run `nickel format {path:?}` to fix"
                )
            }
            FormatError::BadFormatStdin => {
                write!(f, "Bad format on stdin")
            }
        }
    }
}

#[derive(Debug)]
pub enum Output {
    Stdout,
    Disk {
        staged: NamedTempFile,
        output: PathBuf,
    },
}

impl Output {
    pub fn from_path(path: &Path) -> CliResult<Self> {
        let path = nickel_lang_core::cache::normalize_path(path)?;
        Ok(Self::Disk {
            staged: NamedTempFile::new_in(path.parent().ok_or_else(|| FormatError::NotAFile {
                path: path.to_owned(),
            })?)?,
            output: path.to_owned(),
        })
    }

    pub fn persist(self) {
        if let Self::Disk { staged, output } = self {
            staged.persist(output).unwrap();
        }
    }
}

impl Write for Output {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self {
            Output::Stdout => stdout().write(buf),
            Output::Disk { staged, output: _ } => staged.write(buf),
        }
    }

    fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Output::Stdout => stdout().flush(),
            Output::Disk { staged, output: _ } => staged.flush(),
        }
    }
}

#[derive(clap::Parser, Debug)]
pub struct FormatCommand {
    #[command(flatten)]
    input: InputOptions<NoCustomizeMode, NickelOnly>,

    /// Do not change the input files, instead return non-zero if any of the input file is badly formatted
    #[arg(long)]
    check: bool,
}

impl FormatCommand {
    pub fn run(self, ctxt: &mut GlobalContext) {
        fn format(input: impl Read, mut output: Output) -> CliResult<()> {
            nickel_lang_core::format::format(input, &mut output)
                .map_err(FormatError::FailedToFormat)?;
            output.persist();
            Ok(())
        }

        fn format_path(path: &Path) -> CliResult<()> {
            format(BufReader::new(File::open(path)?), Output::from_path(path)?)
        }

        fn check(mut input: impl Read, on_fmt_error: FormatError) -> CliResult<()> {
            let mut input_buf = vec![];
            input.read_to_end(&mut input_buf)?;
            let cursor = std::io::Cursor::new(&input_buf);
            let mut output = vec![];
            nickel_lang_core::format::format(cursor, &mut output)
                .map_err(FormatError::FailedToFormat)?;
            if input_buf != output {
                Err(on_fmt_error)?
            }
            Ok(())
        }

        fn check_path(path: &Path) -> CliResult<()> {
            check(
                BufReader::new(File::open(path)?),
                FormatError::BadFormat(path.into()),
            )
        }

        if self.input.files.is_empty() {
            if !self.check {
                ctxt.reporter.report_result(format(stdin(), Output::Stdout));
            } else {
                ctxt.reporter
                    .report_result(check(stdin(), FormatError::BadFormatStdin));
            }
        } else if !self.check {
            for file in self.input.files.iter() {
                ctxt.reporter.report_result(format_path(file));
            }
        } else {
            for file in self.input.files.iter() {
                ctxt.reporter.report_result(check_path(file));
            }
        }
    }
}//! Global state for the nickel CLI.

use std::{
    collections::HashSet,
    sync::mpsc::{Receiver, Sender, channel},
};

use nickel_lang_core::{
    error::Error as CoreError, error::Reporter, eval::cache::CacheImpl, files::Files,
    program::Program,
};

use crate::{
    cli::GlobalOptions,
    error::{Error, Warning},
    input::{Prepare, PrepareError},
};

/// Contains global state for the nickel CLI.
pub struct GlobalContext {
    /// The CLI arguments that are applicable to all commands.
    pub opts: GlobalOptions,
    /// Collects all errors that occur. Currently, there is at most one error but that
    /// might change.
    pub errors: Receiver<Error>,
    /// Collects all emitted warnings.
    pub warnings: Receiver<Warning>,
    /// Contains the sending ends of the `errors` and `warnings` channels. This can be
    /// cloned and passed to anything that needs to send errors.
    pub reporter: CliReporter,
}

/// An implementation of [`nickel_lang_core::error::Reporter`] that makes its errors
/// available on the [`GlobalContext`].
///
/// We use `mpsc` channels, not because we want to send errors across threads but so that
/// we can decouple the lifetimes between the sending and receiving ends.
#[derive(Clone)]
pub struct CliReporter {
    errors: Sender<Error>,
    warnings: Sender<Warning>,
}

impl GlobalContext {
    pub fn new(opts: GlobalOptions) -> Self {
        let (errors_tx, errors) = channel();
        let (warnings_tx, warnings) = channel();
        GlobalContext {
            opts,
            errors,
            warnings,
            reporter: CliReporter {
                errors: errors_tx,
                warnings: warnings_tx,
            },
        }
    }

    /// Creates a program and applies a callback to it.
    ///
    /// The program is run with this global context as its warning collector, so
    /// that all of the program's warnings will be available on the global context
    /// after the program has finished.
    ///
    /// If the callback returns an error, that error will also be available on the
    /// global context.
    pub fn with_program<
        T,
        P: Prepare,
        F: FnOnce(&mut Program<CacheImpl>) -> Result<T, CoreError>,
    >(
        &mut self,
        preparer: &P,
        f: F,
    ) -> Option<T> {
        let result = match preparer.prepare(self) {
            Ok(mut prog) => f(&mut prog).map_err(|error| {
                Error::Program {
                    error,
                    files: prog.files(),
                }
                .into()
            }),
            Err(e) => Err(e),
        };

        match result {
            Err(PrepareError::Error(error)) => {
                self.reporter.report(error);
                None
            }
            Err(PrepareError::EarlyReturn) => None,
            Ok(x) => Some(x),
        }
    }

    /// Drains all the warnings that have been received so far and deduplicates them.
    pub fn deduplicated_warnings(&mut self) -> Vec<Warning> {
        let mut seen: HashSet<Warning> = HashSet::new();
        let mut ret = Vec::new();
        for w in self.warnings.try_iter() {
            if seen.insert(w.clone()) {
                ret.push(w);
            }
        }
        ret
    }
}

impl CliReporter {
    // This is just an alias for the trait method, but having an inherent impl
    // makes type inference better because rust defaults to the inherent impl and
    // doesn't get confused between `Warning` and `Error`.
    pub fn report_result<T, E: Into<Error>>(&mut self, result: Result<T, E>) {
        <Self as Reporter<Error>>::report_result(self, result)
    }
}

impl Reporter<Error> for CliReporter {
    fn report(&mut self, e: Error) {
        // Ignore any errors, because if no one is listening for these diagnostics
        // then they aren't needed.
        let _ = self.errors.send(e);
    }
}

impl Reporter<Warning> for CliReporter {
    fn report(&mut self, w: Warning) {
        // Ignore any errors, because if no one is listening for these diagnostics
        // then they aren't needed.
        let _ = self.warnings.send(w);
    }
}

impl Reporter<(nickel_lang_core::error::Warning, Files)> for CliReporter {
    fn report(&mut self, (warning, files): (nickel_lang_core::error::Warning, Files)) {
        // Ignore any errors, because if no one is listening for these diagnostics
        // then they aren't needed.
        let _ = self.warnings.send(Warning::Program { warning, files });
    }
}use std::path::PathBuf;

use nickel_lang_core::{
    ast::InputFormat,
    eval::cache::CacheImpl,
    files::Files,
    program::{Program, ProgramBuilder},
