/// A `Reporter` is basically a callback function for reporting errors and/or warnings.
///
/// The error type `E` is a generic parameter, so the same object can be a `Reporter`
/// of various different things.
pub trait Reporter<E> {
    /// Called when there is something (`e`) for the reporter to report.
    fn report(&mut self, e: E);

    /// A utility function for reporting error variants.
    ///
    /// When this is called with an `Ok(_)` it does nothing; when called with an `Err(e)`
    /// it reports `e`.
    fn report_result<T, E2>(&mut self, result: Result<T, E2>)
    where
        Self: Sized,
        E2: Into<E>,
    {
        if let Err(e) = result {
            self.report(e.into());
        }
    }
}

impl<E, R: Reporter<E>> Reporter<E> for &mut R {
    fn report(&mut self, e: E) {
        R::report(*self, e)
    }
}

/// A [`Reporter`] that just collects errors.
pub struct Sink<E> {
    pub errors: Vec<E>,
}

impl<E> Default for Sink<E> {
    fn default() -> Self {
        Sink { errors: Vec::new() }
    }
}

impl<E> Reporter<E> for Sink<E> {
    fn report(&mut self, e: E) {
        self.errors.push(e);
    }
}

/// A [`Reporter`] that throws away all its errors.
pub struct NullReporter {}

impl<E> Reporter<E> for NullReporter {
    fn report(&mut self, _e: E) {}
}

/// A general error occurring during either parsing or evaluation.
#[derive(Debug, PartialEq, Clone)]
pub enum Error {
    EvalError(EvalError),
    TypecheckError(TypecheckError),
    ParseErrors(ParseErrors),
    ImportError(ImportError),
    ExportError(ExportError),
    IOError(IOError),
    ReplError(ReplError),
}

pub type EvalError = Box<EvalErrorData>;
pub type TypecheckError = Box<TypecheckErrorData>;
pub type ImportError = Box<ImportErrorKind>;
pub type ExportError = Box<ExportErrorData>;
pub type ReplError = Box<ReplErrorKind>;

impl Error {
    pub fn eval_error(ctxt: EvalCtxt, error: EvalErrorKind) -> Self {
        Error::EvalError(Box::new(EvalErrorData { ctxt, error }))
    }

    pub fn export_error(pos_table: PosTable, data: impl Into<PointedExportErrorData>) -> Self {
        Error::ExportError(Box::new(ExportErrorData {
            pos_table,
            data: data.into(),
        }))
    }

    pub fn import_error(kind: ImportErrorKind) -> Self {
        Error::ImportError(Box::new(kind))
    }
}

/// Runtime errors might need additional context to be properly reported. The most important one is
/// the position table, which is need to map position indices stored inside a [NickelValue] back to
/// a [TermPos]. Additional data is useful, such as the callstack.
#[derive(Default, PartialEq, Clone)]
pub struct EvalCtxt {
    pub pos_table: PosTable,
    pub call_stack: CallStack,
}

// Skip the pos table, because it's likely to be huge and uninformative.
impl std::fmt::Debug for EvalCtxt {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvalCtxt")
            .field("call_stack", &self.call_stack)
            .finish()
    }
}

/// An error occurring during evaluation with additional [context][EvalCtxt].
#[derive(Debug, PartialEq, Clone)]
pub struct EvalErrorData {
    pub ctxt: EvalCtxt,
    pub error: EvalErrorKind,
}

/// An error occurring during evaluation.
#[derive(Debug, PartialEq, Clone)]
pub enum EvalErrorKind {
    /// A blame occurred: a contract has been broken somewhere.
    BlameError {
        /// The argument failing the contract. If the argument has been forced by the contract,
        /// `evaluated_arg` provides the final value.
        evaluated_arg: Option<NickelValue>,
        /// The label of the corresponding contract.
        label: label::Label,
    },
    /// A field required by a record contract is missing a definition.
    MissingFieldDef {
        id: LocIdent,
        metadata: FieldMetadata,
        pos_record: PosIdx,
        pos_access: PosIdx,
    },
    /// Mismatch between the expected type and the actual type of an expression.
    TypeError {
        /// The expected type.
        expected: String,
        /// A freeform message.
        message: String,
        /// Position index of the original unevaluated expression.
        orig_pos: PosIdx,
        /// The evaluated expression.
        term: NickelValue,
    },
    /// `TypeError` when evaluating a unary primop
    UnaryPrimopTypeError {
        primop: String,
        expected: String,
        pos_arg: PosIdx,
        arg_evaluated: NickelValue,
    },
    /// `TypeError` when evaluating a binary primop
    NAryPrimopTypeError {
        primop: String,
        expected: String,
        arg_number: usize,
        pos_arg: PosIdx,
        arg_evaluated: NickelValue,
        pos_op: PosIdx,
    },
    /// Tried to evaluate a term which wasn't parsed correctly.
    ParseError(ParseError),
    /// A term which is not a function has been applied to an argument.
    NotAFunc(
        /* term */ NickelValue,
        /* arg */ NickelValue,
        /* app position */ PosIdx,
    ),
    /// A field access, or another record operation requiring the existence of a specific field,
    /// has been performed on a record missing that field.
    FieldMissing {
        // The name of the missing field.
        id: LocIdent,
        // The actual fields of the record used to suggest similar fields.
        field_names: Vec<LocIdent>,
        // The primitive operation that required the field to exist.
        operator: String,
        // The position of the record value which is missing the field.
        pos_record: PosIdx,
        // The position of the primitive operation application.
        pos_op: PosIdx,
    },
    /// Too few arguments were provided to a builtin function.
    NotEnoughArgs(
        /* required arg count */ usize,
        /* primitive */ String,
        PosIdx,
    ),
    /// Attempted to merge incompatible values: for example, tried to merge two distinct default
    /// values into one record field.
    MergeIncompatibleArgs {
        /// The left operand of the merge.
        left_arg: NickelValue,
        /// The right operand of the merge.
        right_arg: NickelValue,
        /// Additional error-reporting data.
        merge_label: MergeLabel,
    },
    /// An unbound identifier was referenced.
    UnboundIdentifier(LocIdent, TermPos),
    /// An element in the evaluation Cache was entered during its own update.
    InfiniteRecursion(CallStack, PosIdx),
    /// A serialization error occurred during a call to the builtin `serialize`.
    SerializationError(PointedExportErrorData),
    /// A parse error occurred during a call to the builtin `deserialize`.
    DeserializationError(
        String, /* format */
        String, /* error message */
        PosIdx, /* position of the call to deserialize */
    ),
    /// A parse error occurred during a call to the builtin `deserialize`.
    ///
    /// This differs from `DeserializationError` in that the inner error
    /// isn't just a string: it can refer to positions.
    DeserializationErrorWithInner {
        format: InputFormat,
        inner: ParseError,
        /// Position of the call to deserialize.
        pos: PosIdx,
    },
    /// A polymorphic record contract was broken somewhere.
    IllegalPolymorphicTailAccess {
        action: IllegalPolymorphicTailAction,
        evaluated_arg: Option<NickelValue>,
        label: label::Label,
    },
    /// Two non-equatable terms of the same type (e.g. functions) were compared for equality.
    IncomparableValues {
        eq_pos: PosIdx,
        left: NickelValue,
        right: NickelValue,
    },
    /// A value didn't match any branch of a `match` expression at runtime. This is a specialized
    /// version of [Self::NonExhaustiveMatch] when all branches are enum patterns. In this case,
    /// the error message is more informative than the generic one.
    NonExhaustiveEnumMatch {
        /// The list of expected patterns. Currently, those are just enum tags.
        expected: Vec<LocIdent>,
        /// The original term matched
        found: NickelValue,
        /// The position of the `match` expression
        pos: PosIdx,
    },
    NonExhaustiveMatch {
        /// The original term matched.
        value: NickelValue,
        /// The position of the `match` expression
        pos: PosIdx,
    },
    FailedDestructuring {
        /// The original term matched.
        value: NickelValue,
        /// The position of the pattern that failed to match.
        pattern_pos: PosIdx,
    },
    /// Tried to query a field of something that wasn't a record.
    QueryNonRecord {
        /// Position of the original unevaluated expression.
        pos: PosIdx,
        /// The identifier that we tried to query.
        id: LocIdent,
        /// Evaluated expression
        value: NickelValue,
    },
    /// An unexpected internal error.
    InternalError(String, PosIdx),
    /// Errors occurring rarely enough to not deserve a dedicated variant.
    Other(String, PosIdx),
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum IllegalPolymorphicTailAction {
    FieldAccess { field: String },
    Map,
    Merge,
    FieldRemove { field: String },
    Freeze,
}

impl IllegalPolymorphicTailAction {
    fn message(&self) -> String {
        use IllegalPolymorphicTailAction::*;

        match self {
            FieldAccess { field } => {
                format!("cannot access field `{field}` sealed by a polymorphic contract")
            }
            Map => "cannot map over a record sealed by a polymorphic contract".to_owned(),
            Merge => "cannot merge a record sealed by a polymorphic contract".to_owned(),
            FieldRemove { field } => {
                format!("cannot remove field `{field}` sealed by a polymorphic contract")
            }
            Freeze => "cannot freeze a record sealed by a polymorphic contract".to_owned(),
        }
    }
}

pub const UNKNOWN_SOURCE_NAME: &str = "<unknown> (generated by evaluation)";

/// An error occurring during the static typechecking phase.
#[self_referencing(pub_extras)]
#[derive(Debug)]
pub struct TypecheckErrorData {
    /// The allocator hosting the types and AST nodes.
    alloc: AstAlloc,
    /// The actual error data.
    #[borrows(alloc)]
    #[covariant]
    pub error: TypecheckErrorKind<'this>,
}

impl Clone for TypecheckErrorData {
    fn clone(&self) -> Self {
        TypecheckErrorData::new(AstAlloc::new(), |alloc| {
            // We must clone the "shallow" layer of the error data to satisfy the `CloneTo`
            // interface
            TypecheckErrorKind::clone_to(self.borrow_error().clone(), alloc)
        })
    }
}

impl PartialEq for TypecheckErrorData {
    fn eq(&self, other: &Self) -> bool {
        self.borrow_error() == other.borrow_error()
    }
}

/// The various kinds of typechecking errors.
#[derive(Debug, PartialEq, Clone)]
pub enum TypecheckErrorKind<'ast> {
    /// An unbound identifier was referenced.
    UnboundIdentifier(LocIdent),
    /// A specific row was expected to be in the type of an expression, but was not.
    MissingRow {
        id: LocIdent,
        kind: RowKind,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// A dynamic tail was expected to be in the type of an expression, but was not.
    MissingDynTail {
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// A specific row was not expected to be in the type of an expression.
    ExtraRow {
        id: LocIdent,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// A additional dynamic tail was not expected to be in the type of an expression.
    ExtraDynTail {
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// A parametricity violation involving a row-kinded type variable.
    ///
    /// For example, in a function like this:
    ///
    /// ```nickel
    /// let f : forall a. { x: String, y: String } -> { x: String; a } =
    ///   fun r => r
    /// in ...
    /// ```
    ///
    /// this error would be raised with `{ ; a }` as the `tail` type and
    /// `{ y : String }` as the `violating_type`.
    ForallParametricityViolation {
        kind: VarKindDiscriminant,
        tail: Type<'ast>,
        violating_type: Type<'ast>,
        pos: TermPos,
    },
    /// An unbound type variable was referenced.
    UnboundTypeVariable(LocIdent),
    /// The actual (inferred or annotated) type of an expression is incompatible with its expected
    /// type.
    TypeMismatch {
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// The actual (inferred or annotated) record row type of an expression is incompatible with
    /// its expected record row type. Specialized version of [Self::TypeMismatch] with additional
    /// row-specific information.
    RecordRowMismatch {
        id: LocIdent,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        cause: Box<TypecheckErrorKind<'ast>>,
        pos: TermPos,
    },
    /// Same as [Self::RecordRowMismatch] but for enum types.
    EnumRowMismatch {
        id: LocIdent,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        cause: Option<Box<TypecheckErrorKind<'ast>>>,
        pos: TermPos,
    },
    /// Two incompatible types have been deduced for the same identifier of a row type.
    ///
    /// This is similar to [Self::RecordRowMismatch] but occurs in a slightly different situation.
    /// Consider a unification variable `t`, which is a placeholder to be filled by a concrete type
    /// later in the typechecking phase.  If `t` appears as the tail of a row type, i.e. the type
    /// of some expression is inferred to be `{ field: Type; t}`, then `t` must not be unified
    /// later with a type including a different declaration for field, such as `field: Type2`.
    ///
    /// A [constraint][crate::typecheck::unif::RowConstrs] is added accordingly, and if this
    /// constraint is violated (that is if `t` does end up being unified with a type of the form `{
    /// .., field: Type2, .. }`), [Self::RecordRowConflict] is raised.  We do not necessarily have
    /// access to the original `field: Type` declaration, as opposed to [Self::RecordRowMismatch],
    /// which corresponds to the direct failure to unify `{ .. , x: T1, .. }` and `{ .., x: T2, ..
    /// }`.
    RecordRowConflict {
        /// The row that couldn't be added to the record type, because it already existed with a
        /// different type assignment.
        row: RecordRow<'ast>,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// Same as [Self::RecordRowConflict] but for enum types.
    EnumRowConflict {
        /// The row that couldn't be added to the record type, because it already existed with a
        /// different type assignment.
        row: EnumRow<'ast>,
        expected: Type<'ast>,
        inferred: Type<'ast>,
        pos: TermPos,
    },
    /// Type mismatch on a subtype of an an arrow type.
    ///
    /// The unification of two arrow types requires the unification of the domain and the codomain
    /// (and recursively so, if they are themselves arrow types). When the unification of a subtype
    /// fails, we want to report which part of the arrow types is problematic, and why, rather than
    /// a generic `TypeMismatch`. Indeed, failing to unify two arrow types is a common type error
    /// which deserves a good reporting, that can be caused e.g. by applying a function to an
    /// argument of a wrong type in some cases:
    ///
    /// ```text
    /// let id_mono = fun x => x in let _ign = id_mono true in id_mono 0 : Number
    /// ```
    ///
    /// This specific error stores additionally the [type path][crate::label::ty_path] that
    /// identifies the subtype where unification failed and the corresponding error.
    ArrowTypeMismatch {
        expected: Type<'ast>,
        inferred: Type<'ast>,
        /// The path to the incompatible type components
        type_path: ty_path::Path,
        cause: Box<TypecheckErrorKind<'ast>>,
        pos: TermPos,
    },
    /// Within statically typed code, the typechecker must reject terms containing nonsensical
    /// contracts such as `let C = { foo : (4 + 1) } in ({ foo = 5 } | C)`, which will fail at
    /// runtime.
    ///
    /// The typechecker is currently quite conservative and simply forbids to store any custom
    /// contract in a type that appears in term position. Note that this restriction
    /// doesn't apply to annotations, which aren't considered part of the statically typed block.
    /// For example, `{foo = 5} | {foo : (4 + 1)}` is accepted by the typechecker.
    CtrTypeInTermPos {
        /// The term that was in a flat type (the `(4 + 1)` in the example above).
        contract: Ast<'ast>,
        /// The position of the entire type (the `{foo : 5}` in the example above).
        pos_type: TermPos,
    },
    /// Unsound generalization.
    ///
    /// When typechecking polymorphic expressions, polymorphic variables introduced by a `forall`
    /// are substituted with rigid type variables, which can only unify with a free unification
    /// variable. However, the condition that the unification variable is free isn't enough.
    ///
    /// Consider the following example:
    ///
    /// ```nickel
    /// (fun x => let y : forall a. a = x in (y : Number)) : _
    /// ```
    ///
    /// This example must be rejected, as it is an identity function that casts any value to
    /// something of type `Number`. It will typically fail with a contract error if applied to a
    /// string, for example.
    ///
    /// But when `let y : forall a. a = x` is typechecked, `x` is affected to a free unification
    /// variable `_a`, which isn't determined yet. The unsoundess comes from the fact that `_a` was
    /// introduced **before** the block with the `forall a. a` annotation, and thus shouldn't be
    /// allowed to be generalized (unified with a rigid type variable) at this point.
    ///
    /// Nickel uses an algorithm coming from the OCaml implementation, recognizing that the
    /// discipline needed to reject those case is similar to region-based memory management. See
    /// [crate::typecheck] for more details. This error indicates that a case similar to the above
    /// example happened.
    VarLevelMismatch {
        /// The user-defined type variable (the rigid type variable during unification) that
        /// couldn't be unified.
        type_var: LocIdent,
        /// The position of the expression that was being typechecked as `type_var`.
        pos: TermPos,
    },
    /// Record-dict subtyping failed because the record was inhomogeneous.
    InhomogeneousRecord {
        /// One row of the record had this type.
        row_a: Type<'ast>,
        /// Another row of the record had this type.
        row_b: Type<'ast>,
        /// The position of the expression of record type.
        pos: TermPos,
    },
    /// Invalid or-pattern.
    ///
    /// This error is raised when the patterns composing an or-pattern don't have the precise
    /// same set of free variables. For example, `'Foo x or 'Bar y`.
    OrPatternVarsMismatch {
        /// A variable which isn't present in all the other patterns (there might be more of them,
        /// this is just a sample).
        var: LocIdent,
        /// The position of the whole or-pattern.
        pos: TermPos,
    },
    /// An error occurred during the resolution of an import.
    ///
    /// Since RFC007, imports aren't pre-processed anymore, and import resolution can happen
    /// interleaved with typechecking. In particular, in order to typecheck expressions of the form
    /// `import "file.ncl"`, the typechecker might ask to resolve the import, which can lead to any
    /// import error.
    ImportError(ImportErrorKind),
}

impl IntoDiagnostics for ParseErrors {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        self.errors
            .into_iter()
            .flat_map(|e| e.into_diagnostics(files))
            .collect()
    }
}

/// An error occurring during the resolution of an import.
#[derive(Debug, PartialEq, Eq, Clone)]
pub enum ImportErrorKind {
    /// An IO error occurred during an import.
    IOError(
        /* imported file */ String,
        /* error message */ String,
        /* import position */ TermPos,
    ),
    /// A parse error occurred during an import.
    ParseErrors(
        /* error */ ParseErrors,
        /* import position */ TermPos,
    ),
    /// A package dependency was not found.
    MissingDependency {
        /// The package that tried to import the missing dependency, if there was one.
        /// This will be `None` if the missing dependency was from the top-level
        parent: Option<std::path::PathBuf>,
        /// The name of the package that could not be resolved.
        missing: Ident,
        pos: TermPos,
    },
    /// They tried to import a file from a package, but no package manifest was supplied.
    NoPackageMap { pos: TermPos },
}

/// An error occurring during serialization.
#[derive(Debug, Clone, PartialEq)]
pub struct ExportErrorData {
    /// The position table, mapping position indices to spans.
    pub pos_table: PosTable,
    /// The cause of the error.
    pub data: PointedExportErrorData,
}

/// The type of an error occurring during serialization, together with  a path to the field that
/// contains a non-serializable value.
#[derive(Debug, Clone, PartialEq)]
pub struct PointedExportErrorData {
    /// The path to the field that contains a non-serializable value. This might be empty if the
    /// error occurred before entering any record.
    pub path: NickelPointer,
    /// The cause of the error.
    pub error: ExportErrorKind,
}

impl PointedExportErrorData {
    /// Pushes a [NickelPointerElem] to the end of the path of this export error.
    pub fn with_elem(mut self, elem: NickelPointerElem) -> PointedExportErrorData {
        self.path.0.push(elem);
        self
    }

    /// Attaches a position table to this error, producing a [ExportError].
    pub fn with_pos_table(self, pos_table: PosTable) -> ExportErrorData {
        ExportErrorData {
            data: self,
            pos_table,
        }
    }
}

impl From<ExportErrorKind> for PointedExportErrorData {
    fn from(error: ExportErrorKind) -> Self {
        PointedExportErrorData {
            error,
            path: NickelPointer::new(),
        }
    }
}

/// The type of error occurring during serialization.
#[derive(Debug, PartialEq, Clone)]
pub enum ExportErrorKind {
    /// Encountered a null value for a format that doesn't support them.
    UnsupportedNull(ExportFormat, NickelValue),
    /// Tried exporting something else than a `String` to raw format.
    NotAString(NickelValue),
    /// A term contains constructs that cannot be serialized.
    NonSerializable(NickelValue),
    /// No exportable documentation was found when requested.
    NoDocumentation(NickelValue),
    /// A number was too large (in absolute value) to be serialized as `f64`
    NumberOutOfRange {
        term: NickelValue,
        value: Number,
    },
    /// The YAML documents export format expects the value to be an array.
    ExpectedArray {
        value: NickelValue,
    },
    Other(String),
}

/// A general I/O error, occurring when reading a source file or writing an export.
#[derive(Debug, PartialEq, Eq, Clone)]
pub struct IOError(pub String);

/// An error occurring during an REPL session.
#[derive(Debug, PartialEq, Eq, Clone)]
pub enum ReplErrorKind {
    UnknownCommand(String),
    MissingArg {
        cmd: repl::command::CommandType,
        msg_opt: Option<String>,
    },
    InvalidQueryPath(ParseError),
}

impl From<EvalErrorData> for Error {
    fn from(error: EvalErrorData) -> Error {
        Error::EvalError(Box::new(error))
    }
}

impl From<EvalError> for Error {
    fn from(error: EvalError) -> Error {
        Error::EvalError(error)
    }
}

impl From<ParseError> for Error {
    fn from(error: ParseError) -> Error {
        Error::ParseErrors(ParseErrors {
            errors: vec![error],
        })
    }
}

impl From<ParseErrors> for Error {
    fn from(errors: ParseErrors) -> Error {
        Error::ParseErrors(errors)
    }
}

impl From<TypecheckErrorData> for Error {
    fn from(error: TypecheckErrorData) -> Error {
        Error::TypecheckError(Box::new(error))
    }
}

impl From<TypecheckError> for Error {
    fn from(error: TypecheckError) -> Self {
        Error::TypecheckError(error)
    }
}

impl From<ImportErrorKind> for Error {
    fn from(error: ImportErrorKind) -> Error {
        Error::ImportError(Box::new(error))
    }
}

impl From<ImportError> for Error {
    fn from(error: ImportError) -> Error {
        Error::ImportError(error)
    }
}

impl From<ExportErrorData> for Error {
    fn from(error: ExportErrorData) -> Error {
        Error::ExportError(Box::new(error))
    }
}

impl From<ExportError> for Error {
    fn from(error: ExportError) -> Error {
        Error::ExportError(error)
    }
}

impl From<IOError> for Error {
    fn from(error: IOError) -> Error {
        Error::IOError(error)
    }
}

impl From<std::io::Error> for IOError {
    fn from(error: std::io::Error) -> IOError {
        IOError(error.to_string())
    }
}

impl From<PointedExportErrorData> for EvalErrorKind {
    fn from(error: PointedExportErrorData) -> EvalErrorKind {
        EvalErrorKind::SerializationError(error)
    }
}

impl From<ImportErrorKind> for TypecheckError {
    fn from(error: ImportErrorKind) -> Self {
        Box::new(TypecheckErrorData::new(AstAlloc::new(), |_alloc| {
            TypecheckErrorKind::ImportError(error)
        }))
    }
}

impl From<BuilderError> for Error {
    fn from(error: BuilderError) -> Error {
        match error {
            BuilderError::NoInputs => Error::IOError(IOError(
                "ProgramBuilder::build: no inputs were added".to_owned(),
            )),
            BuilderError::Io {
                path: Some(p),
                error,
            } => Error::IOError(IOError(format!("source {}: {error}", p.display()))),
            BuilderError::Io { path: None, error } => Error::IOError(IOError(error.to_string())),
        }
    }
}

/// Return an escaped version of a string. Used to sanitize strings before inclusion in error
/// messages, which can contain ASCII code sequences, and in particular ANSI escape codes, that
/// could alter Nickel's error messages.
pub fn escape(s: &str) -> String {
    String::from_utf8(strip_ansi_escapes::strip(s))
        .expect("escape(): converting from a string should give back a valid UTF8 string")
}

impl From<ReplErrorKind> for Error {
    fn from(error: ReplErrorKind) -> Error {
        Error::ReplError(Box::new(error))
    }
}

pub const INTERNAL_ERROR_MSG: &str = "This error should not happen. This is likely a bug in the Nickel interpreter. Please consider \
 reporting it at https://github.com/tweag/nickel/issues with the above error message.";

/// A trait for converting an error to a diagnostic.
pub trait IntoDiagnostics {
    /// Convert an error to a list of printable formatted diagnostic.
    ///
    /// # Arguments
    ///
    /// - `pos_table`: the position table, mapping position indices stored in Nickel values to
    /// - `files`: this is a mutable reference to allow insertion of temporary snippets. Note that
    ///   `Files` is cheaply cloneable and copy-on-write, so you can easily get a mutable `Files` from
    ///   a non-mutable one, but bear in mind that the returned diagnostics may contains file ids that
    ///   refer to your mutated files.
    ///
    /// # Return
    ///
    /// Return a list of diagnostics. Most errors generate only one, but showing the callstack
    /// ordered requires to sidestep a limitation of codespan. The current solution is to generate
    /// one diagnostic per callstack element. See issue
    /// [#285](https://github.com/brendanzab/codespan/issues/285).
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>>;
}

// Allow the use of a single `Diagnostic` directly as an error that can be reported by Nickel.
impl IntoDiagnostics for Diagnostic<FileId> {
    fn into_diagnostics(self, _files: &mut Files) -> Vec<Diagnostic<FileId>> {
        vec![self]
    }
}

// Helpers for the creation of codespan `Label`s

/// Create a primary label from a span.
fn primary(span: &RawSpan) -> Label<FileId> {
    Label::primary(span.src_id, span.start.to_usize()..span.end.to_usize())
}

/// Create a secondary label from a span.
fn secondary(span: &RawSpan) -> Label<FileId> {
    Label::secondary(span.src_id, span.start.to_usize()..span.end.to_usize())
}

/// Create a label from an optional span, or fallback to annotating the alternative snippet
/// `alt_term` if the span is `None`.
///
/// When `span_opt` is `None`, the code snippet `alt_term` is added to `files` under a special name
/// and is referred to instead.
///
/// This is useful because during evaluation, some terms are the results of computations. They
/// correspond to nothing in the original source, and thus have a position set to `None`(e.g. the
/// result of `let x = 1 + 1 in x`).  In such cases it may still be valuable to print the term (or a
/// terse representation) in the error diagnostic rather than nothing, because if you have let `x =
/// 1 + 1 in` and then 100 lines later, `x arg` - causing a `NotAFunc` error - it may be helpful to
/// know that `x` holds the value `2`.
///
/// For example, if one wants to report an error on a record, `alt_term` may be defined as
/// `{ ... }`. Then, if this record has no position (`span_opt` is `None`), the error will be
/// reported as:
///
/// ```text
/// error: some error
///   -- <unknown> (generated by evaluation):1:2
///   |
/// 1 | { ... }
///     ^^^^^^^ some annotation
/// ```
///
/// The reason for the mutable reference to `files` is that codespan do no let you annotate
/// something that is not in `files`: you can't provide a raw snippet, you need to provide a
/// `FileId` referring to a file. This leaves the following possibilities:
///
/// 1. Do nothing: just elude annotations which refer to the term
/// 2. Print the term and the annotation as a note together with the diagnostic. Notes are
///    additional text placed at the end of diagnostic. What you lose:
///     - pretty formatting of annotations for such snippets
///     - style consistency: the style of the error now depends on the term being from the source or
///       a byproduct of evaluation
/// 3. Add the term to files, take 1: pass a reference to files so that the code building the
///    diagnostic can itself add arbitrary snippets if necessary, and get back their `FileId`. This
///    is what is done here.
/// 4. Add the term to files, take 2: make a wrapper around the `Files` and `FileId` structures of
///    codespan which handle source mapping. `FileId` could be something like
///    `Either<codespan::FileId, CustomId = u32>` so that `to_diagnostic` could construct and use
///    these separate ids, and return the corresponding snippets to be added together with the
///    diagnostic without modifying external state. Or even have `FileId = Either<codespan::FileId`,
///    `LoneCode = String or (Id, String)>` so we don't have to return the additional list of
///    snippets. This adds some boilerplate, that we wanted to avoid, but this stays on the
///    reasonable side of being an alternative.
fn label_alt(
    span_opt: Option<RawSpan>,
    alt_term: String,
    style: LabelStyle,
    files: &mut Files,
) -> Label<FileId> {
    match span_opt {
        Some(span) => Label::new(
            style,
            span.src_id,
            span.start.to_usize()..span.end.to_usize(),
        ),
        None => {
            let range = 0..alt_term.len();
            Label::new(style, files.add(UNKNOWN_SOURCE_NAME, alt_term), range)
        }
    }
}

/// Create a secondary label from an optional span, or fallback to annotating the alternative
/// snippet `alt_term` if the span is `None`.
///
/// See [`label_alt`].
fn primary_alt(span_opt: Option<RawSpan>, alt_term: String, files: &mut Files) -> Label<FileId> {
    label_alt(span_opt, alt_term, LabelStyle::Primary, files)
}

/// Create a primary label from a term, or fallback to annotating the shallow representation of this
/// term if its span is `None`.
///
/// See [`label_alt`].
fn primary_term(pos_table: &PosTable, term: &NickelValue, files: &mut Files) -> Label<FileId> {
    primary_alt(
        pos_table.get(term.pos_idx()).into_opt(),
        term.to_string(),
        files,
    )
}

/// Create a secondary label from an optional span, or fallback to annotating the alternative
/// snippet `alt_term` if the span is `None`.
///
/// See [`label_alt`].
fn secondary_alt(span_opt: TermPos, alt_term: String, files: &mut Files) -> Label<FileId> {
    label_alt(span_opt.into_opt(), alt_term, LabelStyle::Secondary, files)
}

/// Create a secondary label from a term, or fallback to annotating the shallow representation of
/// this term if its span is `None`.
///
/// See [`label_alt`].
fn secondary_term(pos_table: &PosTable, term: &NickelValue, files: &mut Files) -> Label<FileId> {
    secondary_alt(pos_table.get(term.pos_idx()), term.to_string(), files)
}

fn cardinal(number: usize) -> String {
    let suffix = if number % 10 == 1 {
        "st"
    } else if number % 10 == 2 {
        "nd"
    } else if number % 10 == 3 {
        "rd"
    } else {
        "th"
    };
    format!("{number}{suffix}")
}

impl<T: IntoDiagnostics> IntoDiagnostics for Box<T> {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        (*self).into_diagnostics(files)
    }
}

impl IntoDiagnostics for Error {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        match self {
            Error::ParseErrors(errs) => errs
                .errors
                .into_iter()
                .flat_map(|e| e.into_diagnostics(files))
                .collect(),
            Error::TypecheckError(err) => err.into_diagnostics(files),
            Error::EvalError(err) => err.into_diagnostics(files),
            Error::ImportError(err) => err.into_diagnostics(files),
            Error::ExportError(err) => err.into_diagnostics(files),
            Error::IOError(err) => err.into_diagnostics(files),
            Error::ReplError(err) => err.into_diagnostics(files),
        }
    }
}

impl IntoDiagnostics for EvalErrorData {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        let mut pos_table = self.ctxt.pos_table;

        match self.error {
            EvalErrorKind::BlameError {
                evaluated_arg,
                label,
            } => blame_error::blame_diagnostics(
                &mut pos_table,
                files,
                label,
                evaluated_arg,
                &self.ctxt.call_stack,
                "",
            ),
            EvalErrorKind::MissingFieldDef {
                id,
                metadata,
                pos_record,
                pos_access,
            } => {
                let mut labels = vec![];

                // If there's a contract attached to the missing field, point the error message
                // at the contract instead of the access. This seems like a more useful error,
                // because if someone hands you a `x | { fld | String }` and you call `x.fld`,
                // then the `x.fld` shouldn't be blamed if `fld` is missing: we should point
                // at the original `x` and at the `fld` in the record contract.
                if let Some(label) = metadata
                    .annotation
                    .first()
                    .map(|labeled_ty| labeled_ty.label.clone())
                {
                    if let Some(span) = label.field_name.and_then(|id| id.pos.into_opt()) {
                        labels.push(primary(&span).with_message("required here"));
                    }

                    if let Some(span) = pos_table.get(pos_record).into_opt() {
                        labels.push(secondary(&span).with_message("in this record"));
                    }

                    // In this branch, we don't point at the access location because it
                    // isn't to blame.
                } else {
                    if let Some(span) = id.pos.into_opt() {
                        labels.push(primary(&span).with_message("required here"));
                    }

                    if let Some(span) = pos_table.get(pos_record).into_opt() {
                        labels.push(secondary(&span).with_message("in this record"));
                    }

                    if let Some(span) = pos_table.get(pos_access).into_opt() {
                        labels.push(secondary(&span).with_message("accessed here"));
                    }
                }

                let diags = vec![
                    Diagnostic::error()
                        .with_message(format!("missing definition for `{id}`",))
                        .with_labels(labels),
                ];

                diags
            }
            EvalErrorKind::TypeError {
                expected,
                message,
                orig_pos,
                term: t,
            } => {
                let label = format!(
                    "this expression has type {}, but {} was expected",
                    t.type_of().unwrap_or("<unevaluated>").to_owned(),
                    expected,
                );

                let labels = match (
                    pos_table.get(orig_pos).into_opt(),
                    pos_table.get(t.pos_idx()).into_opt(),
                ) {
                    (Some(span_orig), Some(span_t)) if span_orig == span_t => {
                        vec![primary(&span_orig).with_message(label)]
                    }
                    (Some(span_orig), Some(t_pos)) if !files.is_stdlib(t_pos.src_id) => {
                        vec![
                            primary(&span_orig).with_message(label),
                            secondary_term(&pos_table, &t, files).with_message("evaluated to this"),
                        ]
                    }
                    (Some(span), _) => {
                        vec![primary(&span).with_message(label)]
                    }
                    (None, Some(span)) => {
                        vec![primary(&span).with_message(label)]
                    }
                    (None, None) => {
                        vec![primary_term(&pos_table, &t, files).with_message(label)]
                    }
                };

                vec![
                    Diagnostic::error()
                        .with_message("dynamic type error")
                        .with_labels(labels)
                        .with_notes(vec![message]),
                ]
            }
            EvalErrorKind::ParseError(parse_error) => parse_error.into_diagnostics(files),
            EvalErrorKind::NotAFunc(t, arg, pos_opt) => vec![
                Diagnostic::error()
                    .with_message("not a function")
                    .with_labels(vec![
                        primary_term(&pos_table, &t, files)
                            .with_message("this term is applied, but it is not a function"),
                        secondary_alt(pos_table.get(pos_opt), format!("({t}) ({arg})"), files)
                            .with_message("applied here"),
                    ]),
            ],
            EvalErrorKind::FieldMissing {
                id: name,
                field_names,
                operator,
                pos_record,
                pos_op,
            } => {
                let mut labels = Vec::new();
                let mut notes = Vec::new();
                let field = escape(name.as_ref());

                if let Some(span) = pos_table.get(pos_op).into_opt() {
                    labels.push(
                        Label::primary(span.src_id, span.start.to_usize()..span.end.to_usize())
                            .with_message(format!("this requires the field `{field}` to exist")),
                    );
                } else {
                    notes.push(format!(
                        "The field `{field}` was required by the operator {operator}"
                    ));
                }

                if let Some(span) = pos_table.get(pos_record).as_opt_ref() {
                    labels.push(
                        secondary(span)
                            .with_message(format!("this record lacks the field `{field}`")),
                    );
                }

                suggest::add_suggestion(&mut notes, &field_names, &name);

                vec![
                    Diagnostic::error()
                        .with_message(format!("missing field `{field}`"))
                        .with_labels(labels)
                        .with_notes(notes),
                ]
            }
            EvalErrorKind::NotEnoughArgs(count, op, span_opt) => {
                let mut labels = Vec::new();
                let mut notes = Vec::new();
                let msg = format!("{op} expects {count} arguments, but not enough were provided");

                if let Some(span) = pos_table.get(span_opt).into_opt() {
                    labels.push(
                        Label::primary(span.src_id, span.start.to_usize()..span.end.to_usize())
                            .with_message(msg),
                    );
                } else {
                    notes.push(msg);
                }

                vec![
                    Diagnostic::error()
                        .with_message("not enough arguments")
                        .with_labels(labels)
                        .with_notes(notes),
                ]
            }
            EvalErrorKind::MergeIncompatibleArgs {
                left_arg,
                right_arg,
                merge_label,
            } => {
                let mut labels = vec![
                    primary_term(&pos_table, &left_arg, files)
                        .with_message("cannot merge this expression"),
                    primary_term(&pos_table, &right_arg, files)
                        .with_message("with this expression"),
                ];

                let span_label = match merge_label.kind {
                    // For a standard merge, the span of the label indicates the position of the
                    // original merge expression
                    MergeKind::Standard => "originally merged here",
                    // For a piecewise definition, there isn't such merge expression (the merge has
                    // been generated by the parser). The spans thus point to the corresponding
                    // field identifier
                    MergeKind::PiecewiseDef => "when combining the definitions of this field",
                };

                if let Some(merge_label_span) = pos_table.get(merge_label.span).into_opt() {
                    labels.push(secondary(&merge_label_span).with_message(span_label));
                }

                fn push_merge_note(notes: &mut Vec<String>, typ: &str) {
                    notes.push(format!(
                        "Both values are of type {typ} but they aren't equal."
                    ));
                    notes.push(format!("{typ} values can only be merged if they are equal"));
                }

                let mut notes = vec![
                    "Merge operands have the same merge priority but they can't \
                    be combined."
                        .to_owned(),
                ];

                if let (Some(left_ty), Some(right_ty)) = (right_arg.type_of(), left_arg.type_of()) {
                    match left_ty {
                        _ if left_ty != right_ty => {
                            notes.push(format!(
                                "One value is of type {left_ty} \
                                while the other is of type {right_ty}"
                            ));
                            notes.push("Values of different types can't be merged".to_owned());
                        }
                        "String" | "Number" | "Bool" | "Array" | "EnumTag" => {
                            push_merge_note(&mut notes, left_ty);
                        }
                        "Function" | "MatchExpression" => {
                            notes.push(
                                "Both values are functions (or match expressions)".to_owned(),
                            );
                            notes.push(
                                "Functions can never be merged with anything else, \
                                even another function."
                                    .to_owned(),
                            );
                        }
                        "EnumVariant" => {
                            if let (
                                Some(EnumVariantData { tag: tag1, .. }),
                                Some(EnumVariantData { tag: tag2, .. }),
                            ) = (right_arg.as_enum_variant(), left_arg.as_enum_variant())
                            {
                                // The only possible cause of failure of merging two enum variants is a
                                // different tag (the arguments could fail to merge as well, but then
                                // the error would have them as the operands, not the enclosing enums).
                                notes.push(format!(
                                    "Both values are enum variants, \
                                    but their tags differ (`'{tag1}` vs `'{tag2}`)"
                                ));
                                notes.push(
                                    "Enum variants can only be \
                                    merged if they have the same tag"
                                        .to_owned(),
                                );
                            } else {
                                // This should not happen, but it's recoverable, so let's not fail
                                // in release mode.
                                debug_assert!(false);

                                notes.push(
                                    "Primitive values (Number, String, EnumTag and Bool) \
                                    and arrays can only be merged if they are equal"
                                        .to_owned(),
                                );
                                notes.push("Enum variants must have the same tag.".to_owned());
                                notes.push("Functions can never be merged.".to_owned());
                            }
                        }
                        _ => {
                            // In other cases, we print a generic message
                            notes.push(
                                "Primitive values (Number, String, EnumTag and Bool) \
                                    and arrays can only be merged if they are equal"
                                    .to_owned(),
                            );
                            notes.push("Enum variants must have the same tag.".to_owned());
                            notes.push("Functions can never be merged.".to_owned());
                        }
                    }
                }

                vec![
                    Diagnostic::error()
                        .with_message("non mergeable terms")
                        .with_labels(labels)
                        .with_notes(notes),
                ]
            }
            EvalErrorKind::UnboundIdentifier(ident, span_opt) => vec![
                Diagnostic::error()
                    .with_message(format!("unbound identifier `{ident}`"))
                    .with_labels(vec![
                        primary_alt(span_opt.into_opt(), ident.to_string(), files)
                            .with_message("this identifier is unbound"),
                    ]),
            ],
            EvalErrorKind::InfiniteRecursion(_call_stack, pos_idx) => {
                let labels = pos_table
                    .get(pos_idx)
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("recursive reference")])
                    .unwrap_or_default();

                vec![
                    Diagnostic::error()
                        .with_message("infinite recursion")
                        .with_labels(labels),
                ]
            }
            EvalErrorKind::Other(msg, span_opt) => {
                let labels = pos_table
                    .get(span_opt)
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("here")])
                    .unwrap_or_default();

                vec![Diagnostic::error().with_message(msg).with_labels(labels)]
            }
            EvalErrorKind::InternalError(msg, span_opt) => {
                let labels = pos_table
                    .get(span_opt)
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("here")])
                    .unwrap_or_default();

                vec![
                    Diagnostic::error()
                        .with_message(format!("internal error: {msg}"))
                        .with_labels(labels)
                        .with_notes(vec![String::from(INTERNAL_ERROR_MSG)]),
                ]
            }
            EvalErrorKind::SerializationError(err) => {
                err.with_pos_table(pos_table).into_diagnostics(files)
            }
            EvalErrorKind::DeserializationError(format, msg, span_opt) => {
                let labels = pos_table
                    .get(span_opt)
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("here")])
                    .unwrap_or_default();

                vec![
                    Diagnostic::error()
                        .with_message(format!("{format} parse error: {msg}"))
                        .with_labels(labels),
                ]
            }
            EvalErrorKind::DeserializationErrorWithInner { format, inner, pos } => {
                let mut diags = inner.into_diagnostics(files);
                if let Some(diag) = diags.first_mut() {
                    // TODO: should we really use a pos_idx here, or are those fresh TermPos coming
                    // out from the YAML parser?
                    if let Some(span) = pos_table.get(pos).as_opt_ref() {
                        diag.labels
                            .push(secondary(span).with_message("deserialized here"));
                    }
                    diag.notes.push(format!("while parsing {format}"));
                }
                diags
            }
            EvalErrorKind::IncomparableValues {
                eq_pos,
                left,
                right,
            } => {
                let mut labels = Vec::new();

                if let Some(span) = pos_table.get(eq_pos).as_opt_ref() {
                    labels.push(primary(span).with_message("in this equality comparison"));
                }

                // Push the label for the right or left argument and return the type of said
                // argument.
                let mut push_label = |prefix: &str, term: &NickelValue| -> &'static str {
                    let type_of = term.type_of().unwrap_or("<unevaluated>");

                    labels.push(
                        secondary_term(&pos_table, term, files)
                            .with_message(format!("{prefix} argument has type {type_of}")),
                    );

                    type_of
                };

                let left_type = push_label("left", &left);
                let right_type = push_label("right", &right);

                vec![
                    Diagnostic::error()
                        .with_message("cannot compare values for equality")
                        .with_labels(labels)
                        .with_notes(vec![format!(
                            "A {left_type} can't be meaningfully compared with a {right_type}"
                        )]),
                ]
            }
            EvalErrorKind::NonExhaustiveEnumMatch {
                expected,
                found,
                pos,
            } => {
                let tag_list = expected
                    .into_iter()
                    .map(|tag| {
                        // We let the pretty printer handle proper formatting
                        NickelValue::enum_variant_posless(tag, None).to_string()
                    })
                    .collect::<Vec<_>>()
                    .join(", ");

                let mut labels = Vec::new();

                if let Some(span) = pos_table.get(pos).into_opt() {
                    labels.push(primary(&span).with_message("in this match expression"));
                }

                labels.push(
                    secondary_term(&pos_table, &found, files)
                        .with_message("this value doesn't match any branch"),
                );

                vec![Diagnostic::error()
                    .with_message("unmatched pattern")
                    .with_labels(labels)
                    .with_notes(vec![
                        format!("This match expression isn't exhaustive, matching only the following pattern(s): `{tag_list}`"),
                        "But it has been applied to an argument which doesn't match any of those patterns".to_owned(),
                    ])]
            }
            EvalErrorKind::NonExhaustiveMatch { value, pos } => {
                let mut labels = Vec::new();

                if let Some(span) = pos_table.get(pos).into_opt() {
                    labels.push(primary(&span).with_message("in this match expression"));
                }

                labels.push(
                    secondary_term(&pos_table, &value, files)
                        .with_message("this value doesn't match any branch"),
                );

                vec![
                    Diagnostic::error()
                        .with_message("unmatched pattern")
                        .with_labels(labels),
                ]
            }
            EvalErrorKind::FailedDestructuring { value, pattern_pos } => {
                let mut labels = Vec::new();

                if let Some(span) = pos_table.get(pattern_pos).into_opt() {
                    labels.push(primary(&span).with_message("this pattern"));
                }

                labels.push(
                    secondary_term(&pos_table, &value, files)
                        .with_message("this value failed to match"),
                );

                vec![
                    Diagnostic::error()
                        .with_message("destructuring failed")
                        .with_labels(labels),
                ]
            }
            EvalErrorKind::IllegalPolymorphicTailAccess {
                action,
                label: contract_label,
                evaluated_arg,
            } => blame_error::blame_diagnostics(
                &mut pos_table,
                files,
                contract_label,
                evaluated_arg,
                &self.ctxt.call_stack,
                &format!(": {}", &action.message()),
            ),
            EvalErrorKind::UnaryPrimopTypeError {
                primop,
                expected,
                pos_arg,
                arg_evaluated,
            } => EvalErrorData {
                error: EvalErrorKind::TypeError {
                    message: format!("{primop} expects its argument to be a {expected}"),
                    expected,
                    orig_pos: pos_arg,
                    term: arg_evaluated,
                },
                ctxt: EvalCtxt {
                    pos_table,
                    call_stack: self.ctxt.call_stack,
                },
            }
            .into_diagnostics(files),
            EvalErrorKind::NAryPrimopTypeError {
                primop,
                expected,
                arg_number,
                pos_arg,
                arg_evaluated,
                pos_op,
            } => {
                // The parsing of binary subtraction vs unary negation has
                // proven confusing in practice; for example, `add 1 -1` is
                // parsed as `(add 1) - 1`, so the `-` is a subtraction and
                // triggers a type error because `(add 1)` is not a number.
                //
                // We attempt to provide a useful hint for this case.
                //
                // We don't currently attempt to give a good hint for
                // `add -1 1` (parsed as `add - (1 1)`) because the evaluation
                // error hits in a context (the `(1 1)`) where we don't see
                // the `-`.
                let minus_pos = if primop == "(-)"
                    && arg_number == 1
                    && matches!(arg_evaluated.type_of(), Some("Function"))
                {
                    pos_table.get(pos_op).into_opt()
                } else {
                    None
                };

                let diags = EvalErrorData {
                    ctxt: EvalCtxt {
                        pos_table,
                        call_stack: self.ctxt.call_stack,
                    },
                    error: EvalErrorKind::TypeError {
                        message: format!(
                            "{primop} expects its {} argument to be a {expected}",
                            cardinal(arg_number)
                        ),
                        expected,
                        orig_pos: pos_arg,
                        term: arg_evaluated,
                    },
                }
                .into_diagnostics(files);

                if let Some(minus_pos) = minus_pos {
                    let label = secondary(&minus_pos)
                        .with_message("this expression was parsed as a binary subtraction");
                    diags
                        .into_iter()
                        .map(|d| {
                            d.with_label(label.clone())
                                .with_note(
                                    "for unary negation, add parentheses: write `(-42)` instead of `-42`",
                                )
                        })
                        .collect()
                } else {
                    diags
                }
            }
            EvalErrorKind::QueryNonRecord { pos, id, value } => {
                let label = format!(
                    "tried to query field `{}`, but the expression has type {}",
                    id,
                    value.type_of().unwrap_or("<unevaluated>"),
                );

                let label = if let Some(span) = pos_table.get(pos).into_opt() {
                    primary(&span).with_message(label)
                } else {
                    primary_term(&pos_table, &value, files).with_message(label)
                };

                vec![
                    Diagnostic::error()
                        .with_message("tried to query field of a non-record")
                        .with_labels(vec![label]),
                ]
            }
        }
    }
}

/// Common functionality for formatting blame errors.
mod blame_error {
    use codespan_reporting::diagnostic::{Diagnostic, Label};

    use crate::{
        eval::{callstack::CallStack, value::NickelValue},
        files::{FileId, Files},
        label::{
            self, Polarity,
            ty_path::{self, PathSpan},
        },
        position::{PosIdx, PosTable, TermPos},
        typ::Type,
    };

    use super::{primary, secondary, secondary_term};

    /// Returns a title to be used by blame errors based on the `path` and `polarity`
    /// of the label.
    pub fn title(l: &label::Label) -> String {
        if ty_path::has_no_arrow(&l.path) {
            // An empty path or a path that contains only fields necessarily corresponds to
            // a positive blame
            assert_eq!(l.polarity, Polarity::Positive);
            match l.field_name {
                Some(ident) => format!("contract broken by the value of `{ident}`"),
                None => "contract broken by a value".to_owned(),
            }
        } else if l.polarity == Polarity::Positive {
            match l.field_name {
                Some(ident) => format!("contract broken by the function `{ident}`"),
                None => "contract broken by a function".to_owned(),
            }
        } else {
            match l.field_name {
                Some(ident) => format!("contract broken by the caller of `{ident}`"),
                None => "contract broken by the caller".to_owned(),
            }
        }
    }

    /// Constructs the diagnostic labels used when raising a blame error.
    pub fn build_diagnostic_labels(
        pos_table: &PosTable,
        evaluated_arg: Option<NickelValue>,
        blame_label: &label::Label,
        path_label: Label<FileId>,
        files: &mut Files,
    ) -> Vec<Label<FileId>> {
        let mut labels = vec![path_label];

        if let Some(ref arg_pos) = pos_table.get(blame_label.arg_pos).into_opt() {
            // In some cases, if the blame error is located in an argument or return value
            // of an higher order functions for example, the original argument position can
            // point to the builtin implementation contract like `func` or `record`, so
            // there's no good reason to show it. Note than even in that case, the
            // information contained at the argument index can still be useful.
            if !files.is_stdlib(arg_pos.src_id) {
                labels.push(primary(arg_pos).with_message("applied to this expression"));
            }
        }

        // If we have a reference to the element in the cache that was being tested,
        // we can try to show more information about the final, evaluated value that is
        // responsible for the blame.
        if let Some(mut evaluated_arg) = evaluated_arg {
            match (
                pos_table.get(evaluated_arg.pos_idx()),
                pos_table.get(blame_label.arg_pos).as_opt_ref(),
            ) {
                // Avoid showing a position inside builtin contracts, it's rarely
                // informative.
                (TermPos::Original(val_pos), _) if files.is_stdlib(val_pos.src_id) => {
                    evaluated_arg = evaluated_arg.with_pos_idx(PosIdx::NONE);
                    labels.push(
                        secondary_term(pos_table, &evaluated_arg, files)
                            .with_message("evaluated to this value"),
                    );
                }
                // Do not show the same thing twice: if arg_pos and val_pos are the same,
                // the first label "applied to this value" is sufficient.
                (TermPos::Original(ref val_pos), Some(arg_pos)) if val_pos == arg_pos => {}
                (TermPos::Original(ref val_pos), _) => {
                    labels.push(secondary(val_pos).with_message("evaluated to this expression"))
                }
                // If the final element is a direct reduct of the original value, rather
                // print the actual value than referring to the same position as
                // before.
                (TermPos::Inherited(ref val_pos), Some(arg_pos)) if val_pos == arg_pos => {
                    evaluated_arg = evaluated_arg.with_pos_idx(PosIdx::NONE);
                    labels.push(
                        secondary_term(pos_table, &evaluated_arg, files)
                            .with_message("evaluated to this value"),
                    );
                }
                // Finally, if the parameter reduced to a value which originates from a
                // different expression, show both the expression and the value.
                (TermPos::Inherited(ref val_pos), _) => {
                    if !files.is_stdlib(val_pos.src_id) {
                        labels
                            .push(secondary(val_pos).with_message("evaluated to this expression"));
                    }

                    evaluated_arg = evaluated_arg.with_pos_idx(PosIdx::NONE);
                    labels.push(
                        secondary_term(pos_table, &evaluated_arg, files)
                            .with_message("evaluated to this value"),
                    );
                }
                (TermPos::None, _) => labels.push(
                    secondary_term(pos_table, &evaluated_arg, files)
                        .with_message("evaluated to this value"),
                ),
            }
        }

        labels
    }

    pub trait ExtendWithCallStack {
        fn extend_with_call_stack(
            &mut self,
            pos_table: &PosTable,
            files: &Files,
            call_stack: &CallStack,
        );
    }

    impl ExtendWithCallStack for Vec<Diagnostic<FileId>> {
        fn extend_with_call_stack(
            &mut self,
            pos_table: &PosTable,
            files: &Files,
            call_stack: &CallStack,
        ) {
            let (calls, curr_call) = call_stack.group_by_calls(pos_table, files);
            let diag_curr_call = curr_call.map(|cdescr| {
                let name = cdescr
                    .head
                    .map(|ident| ident.to_string())
                    .unwrap_or_else(|| String::from("<func>"));
                Diagnostic::note().with_labels(vec![
                    primary(&cdescr.span).with_message(format!("While calling to {name}")),
                ])
            });
            let diags = calls.into_iter().enumerate().map(|(i, cdescr)| {
                let name = cdescr
                    .head
                    .map(|ident| ident.to_string())
                    .unwrap_or_else(|| String::from("<func>"));
                Diagnostic::note().with_labels(vec![secondary(&cdescr.span).with_message(format!(
                    "({}) calling {}",
                    i + 1,
                    name
                ))])
            });

            self.extend(diag_curr_call);
            self.extend(diags);
        }
    }

    /// Calls [`crate::label::ty_path::span`], but if the call returns `None` (the position of the
    /// subtype isn't defined), [path_span] pretty-prints the type inside a new source, parses it,
    /// and calls `ty_path::span`. This new type is guaranteed to have all of its positions set,
    /// providing a definite `PathSpan`. This is similar to the behavior of [`super::primary_alt`].
    pub fn path_span<'a, I>(
        pos_table: &mut PosTable,
        files: &mut Files,
        path: I,
        ty: &Type,
    ) -> PathSpan
    where
        I: Iterator<Item = &'a ty_path::Elem> + Clone,
    {
        use crate::parser::{ErrorTolerantParserCompat, grammar::FixedTypeParser, lexer::Lexer};

        ty_path::span(path.clone().peekable(), ty)
            .or_else(|| {
                let type_pprinted = format!("{ty}");
                let file_id = files.add(super::UNKNOWN_SOURCE_NAME, type_pprinted.clone());

                let (ty_with_pos, _) = FixedTypeParser::new()
                    .parse_tolerant_compat(pos_table, file_id, Lexer::new(&type_pprinted))
                    .unwrap();

                ty_path::span(path.peekable(), &ty_with_pos)
            })
            .expect(
                "path_span: we pretty-printed and parsed again the type of a label, \
                so it must have all of its position defined, but `ty_path::span` returned `None`",
            )
    }

    /// Generate a codespan label that describes the [type path][crate::label::ty_path::Path] of a
    /// (Nickel) label.
    pub fn report_ty_path(
        pos_table: &mut PosTable,
        files: &mut Files,
        l: &label::Label,
    ) -> Label<FileId> {
        let PathSpan {
            span,
            last,
            last_arrow_elem,
        } = path_span(pos_table, files, l.path.iter(), &l.typ);

        let msg = match (last, last_arrow_elem) {
            // The type path doesn't contain any arrow, and the failing subcontract is the
            // contract for the elements of an array
            (Some(ty_path::Elem::Array), None) => "expected array element type",
            // The type path doesn't contain any arrow, and the failing subcontract is the contract
            // for the fields of a dictionary
            (Some(ty_path::Elem::Dict), None) => "expected dictionary field type",
            // The type path doesn't contain any arrow, and the failing subcontract is the contract
            // for the field of a record
            (Some(ty_path::Elem::Field(_)), None) => "expected field type",
            // The original contract contains an arrow, and the path is only composed of codomains.
            // Then polarity is necessarily true and the cause of the blame is the return value of
            // the function
            (Some(_), Some(ty_path::Elem::Codomain)) if ty_path::has_no_dom(&l.path) => {
                "expected return type"
            }
            // The original contract contains an arrow, the subcontract is the domain of an
            // arrow, and the polarity is positive. The function is to be blamed for calling an
            // argument on a value of the wrong type.
            (Some(_), Some(ty_path::Elem::Domain)) if l.polarity == Polarity::Positive => {
                "expected type of an argument of an inner call"
            }
            // The original contract contains an arrow, the subcontract is the codomain of an
            // arrow, and the polarity is positive. The function is to be blamed for calling a
            // higher-order function argument on a function which returns a value of the wrong
            // type.
            (Some(_), Some(ty_path::Elem::Codomain)) if l.polarity == Polarity::Positive => {
                "expected return type of a sub-function passed as an argument of an inner call"
            }
            // The original contract contains an arrow, the subcontract is the domain of an arrow,
            // and the polarity is negative. The caller is to be blamed for providing an argument
            // of the wrong type.
            (Some(_), Some(ty_path::Elem::Domain)) => {
                "expected type of the argument provided by the caller"
            }
            // The original contract contains an arrow, the subcontract is the codomain of an
            // arrow, and the polarity is negative. The caller is to be blamed for providing a
            // higher-order function argument which returns a value of the wrong type.
            (Some(_), Some(ty_path::Elem::Codomain)) => {
                "expected return type of a function provided by the caller"
            }
            // If there is a last arrow element, then there must be last element
            (None, Some(_)) => panic!(
                "blame error reporting: inconsistent path analysis, last_elem\
is None but last_arrow_elem is Some"
            ),
            _ => "expected type",
        };

        secondary(&span).with_message(msg.to_owned())
    }

    /// Generate codespan diagnostics from blame data. Mostly used by `into_diagnostics`
    /// implementations.
    ///
    /// # Parameters
    ///
    /// The `msg_addendum` is used to customize the main error message. It's inserted between the
    /// leading "contract broken by .." and the custom contract diagnostic message in tail
    /// position.
    pub fn blame_diagnostics(
        pos_table: &mut PosTable,
        files: &mut Files,
        mut label: label::Label,
        evaluated_arg: Option<NickelValue>,
        call_stack: &CallStack,
        msg_addendum: &str,
    ) -> Vec<Diagnostic<FileId>> {
        use std::fmt::Write;

        let mut diagnostics = Vec::new();

        // Contract diagnostics are stacked up in order, which means the last one is
        // usually the latest/most precise/most relevant. We ignore empty diagnostics and
        // iterate in reverse order, to show the most relevant diagnostics first.
        let mut contract_diagnostics = std::mem::take(&mut label.diagnostics)
            .into_iter()
            .rev()
            .filter(|diag| !label::ContractDiagnostic::is_empty(diag));
        let head_contract_diagnostic = contract_diagnostics.next();

        // The addendum and the custom contract diagnostic are important, so we want to display
        // them as part of the main error message. However, they can make the message quite long.
        // To avoid clutter, we display each component on a new line, indented with respect to the
        // initial "error: "
        let new_msg_block = "\n       ";
        let mut msg = title(&label);

        if !msg_addendum.is_empty() {
            // unwrap(): write shouldn't fail on a String
            write!(&mut msg, "{new_msg_block}{msg_addendum}").unwrap();
        }

        if let Some(contract_msg) = head_contract_diagnostic
            .as_ref()
            .and_then(|diag| diag.message.as_ref())
        {
            // unwrap(): write shouldn't fail on a String
            write!(&mut msg, "{new_msg_block}{}", &super::escape(contract_msg)).unwrap();
        }

        let contract_notes = head_contract_diagnostic
            .map(|diag| diag.notes)
            .unwrap_or_default();
        let path_label = report_ty_path(pos_table, files, &label);

        let labels = build_diagnostic_labels(pos_table, evaluated_arg, &label, path_label, files);

        // If there are notes in the head contract diagnostic, we build the first
        // diagnostic using them and will put potential generated notes on higher-order
        // contracts in a following diagnostic.
        if !contract_notes.is_empty() {
            diagnostics.push(
                Diagnostic::error()
                    .with_message(msg)
                    .with_labels(labels)
                    .with_notes(contract_notes),
            );
        } else {
            diagnostics.push(Diagnostic::error().with_message(msg).with_labels(labels));
        }

        for ctr_diag in contract_diagnostics {
            let mut msg = String::from("from a parent contract violation");

            if let Some(msg_contract) = ctr_diag.message {
                msg.push_str(": ");
                msg.push_str(&super::escape(&msg_contract));
            }

            diagnostics.push(
                Diagnostic::note()
                    .with_message(msg)
                    .with_notes(ctr_diag.notes),
            );
        }

        if !ty_path::has_no_dom(&label.path) {
            diagnostics.extend_with_call_stack(pos_table, files, call_stack);
        }

        diagnostics
    }
}

impl IntoDiagnostics for ParseError {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        let diagnostic = match self {
            ParseError::UnexpectedEOF(file_id, _expected) => {
                let end = files.source_span(file_id).end;
                Diagnostic::error()
                    .with_message(format!(
                        "unexpected end of file when parsing {}",
                        files.name(file_id).to_string_lossy()
                    ))
                    .with_labels(vec![primary(&RawSpan {
                        start: end,
                        end,
                        src_id: file_id,
                    })])
            }
            ParseError::UnexpectedToken(span, _expected) => Diagnostic::error()
                .with_message("unexpected token")
                .with_labels(vec![primary(&span)]),
            ParseError::ExtraToken(span) => Diagnostic::error()
                .with_message("superfluous unexpected token")
                .with_labels(vec![primary(&span)]),
            ParseError::UnmatchedCloseBrace(span) => Diagnostic::error()
                .with_message("unmatched closing brace \'}\'")
                .with_labels(vec![primary(&span)]),
            ParseError::InvalidEscapeSequence(span) => Diagnostic::error()
                .with_message("invalid escape sequence")
                .with_labels(vec![primary(&span)]),
            ParseError::InvalidAsciiEscapeCode(span) => Diagnostic::error()
                .with_message("invalid ascii escape code")
                .with_labels(vec![primary(&span)]),
            ParseError::InvalidUnicodeEscapeCode(span) => Diagnostic::error()
                .with_message("invalid unicode escape code")
                .with_labels(vec![primary(&span)]),
            ParseError::StringDelimiterMismatch {
                opening_delimiter,
                closing_delimiter,
            } => Diagnostic::error()
                .with_message("string closing delimiter has too many `%`")
                .with_labels(vec![
                    primary(&closing_delimiter).with_message("the closing delimiter"),
                    secondary(&opening_delimiter).with_message("the opening delimiter"),
                ])
                .with_notes(vec![
                    "A special string must be opened and closed with the same number of `%` \
                    in the corresponding delimiters."
                        .into(),
                    "Try removing the superfluous `%` in the closing delimiter".into(),
                ]),
            ParseError::ExternalFormatError(format, msg, span_opt) => {
                let labels = span_opt
                    .as_ref()
                    .map(|span| vec![primary(span)])
                    .unwrap_or_default();

                Diagnostic::error()
                    .with_message(format!("{format} parse error: {msg}"))
                    .with_labels(labels)
            }
            ParseError::UnboundTypeVariables(idents) => Diagnostic::error()
                .with_message(format!(
                    "unbound type variable(s): {}",
                    idents
                        .iter()
                        .map(|x| format!("`{x}`"))
                        .collect::<Vec<_>>()
                        .join(",")
                ))
                .with_labels(
                    idents
                        .into_iter()
                        .filter_map(|id| id.pos.into_opt())
                        .map(|span| primary(&span).with_message("this identifier is unbound"))
                        .collect(),
                ),
            ParseError::InvalidRecordType {
                record_span,
                tail_span,
                cause,
            } => {
                let mut labels: Vec<_> = std::iter::once(primary(&record_span))
                    .chain(cause.labels())
                    .collect();
                let mut notes: Vec<_> = std::iter::once(
                    "A record type is a literal composed only of type annotations, of the \
                        form `<field>: <type>`."
                        .into(),
                )
                .chain(cause.notes())
                .collect();

                if let Some(tail_span) = tail_span {
                    labels.push(secondary(&tail_span).with_message("tail"));
                    notes.push(
                        "This literal was interpreted as a record type because it has a \
                        polymorphic tail; record values cannot have tails."
                            .into(),
                    );
                } else {
                    notes.push(
                        "This literal was interpreted as a record type because it has \
                        fields with type annotations but no value definitions; to make \
                        this a record value, assign values to its fields."
                            .into(),
                    );
                };
                Diagnostic::error()
                    .with_message("invalid record literal")
                    .with_labels(labels)
                    .with_notes(notes)
            }
            ParseError::RecursiveLetPattern(span) => Diagnostic::error()
                .with_message("recursive destructuring is not supported")
                .with_labels(vec![primary(&span)])
                .with_notes(vec![
                    "A destructuring let-binding can't be recursive. Try removing the `rec` \
                        from `let rec`."
                        .into(),
                    "You can reference other fields of a record recursively \
                        from within a field, so you might not need the recursive let."
                        .into(),
                ]),
            ParseError::PatternInLetBlock(span) => Diagnostic::error()
                .with_message("destructuring patterns are not currently permitted in let blocks")
                .with_labels(vec![primary(&span)])
                .with_notes(vec!["Try re-writing your let block as nested `let ... in` expressions.".into()]),
            ParseError::TypeVariableKindMismatch { ty_var, span } => Diagnostic::error()
                .with_message(format!(
                    "the type variable `{ty_var}` is used in conflicting ways"
                ))
                .with_labels(vec![primary(&span)])
                .with_notes(vec![
                    "Type variables may be used either as types, polymorphic record tails, \
                    or polymorphic enum tails."
                        .into(),
                    "Using the same type variable as more than one category at the same time \
                    is forbidden."
                        .into(),
                ]),
            ParseError::TypedFieldWithoutDefinition {
                field_span,
                annot_span,
            } => Diagnostic::error()
                .with_message("statically typed field without a definition")
                .with_labels(vec![
                    primary(&field_span).with_message("this field doesn't have a definition"),
                    secondary(&annot_span).with_message("but it has a type annotation"),
                ])
                .with_notes(vec![
                    "A static type annotation must be attached to an expression but \
                    this field doesn't have a definition."
                        .into(),
                    "Did you mean to use `|` instead of `:`, for example when defining a \
                    record contract?"
                        .into(),
                    "Typed fields without definitions are only allowed inside \
                    record types, but the enclosing record literal doesn't qualify as a \
                    record type. Please refer to the manual for the defining conditions of a \
                    record type."
                        .into(),
                ]),
            ParseError::InterpolationInStaticPath {
                input: _,
                path_elem_span,
            } => Diagnostic::error()
                .with_message("string interpolation is forbidden within a query")
                .with_labels(vec![primary(&path_elem_span)])
                .with_notes(vec![
                    "Field paths don't support string interpolation when querying \
                        metadata."
                        .into(),
                    "Only identifiers and simple string literals are allowed.".into(),
                ]),
            ParseError::DuplicateIdentInRecordPattern { ident, prev_ident } => Diagnostic::error()
                .with_message(format!(
                    "duplicated binding `{}` in record pattern",
                    ident.label()
                ))
                .with_labels(vec![
                    secondary(&prev_ident.pos.unwrap()).with_message("previous binding here"),
                    primary(&ident.pos.unwrap()).with_message("duplicated binding here"),
                ]),
            ParseError::DuplicateIdentInLetBlock { ident, prev_ident } => Diagnostic::error()
                .with_message(format!(
                    "duplicated binding `{}` in let block",
                    ident.label()
                ))
                .with_labels(vec![
                    secondary(&prev_ident.pos.unwrap()).with_message("previous binding here"),
                    primary(&ident.pos.unwrap()).with_message("duplicated binding here"),
                ]),
            ParseError::DisabledFeature { feature, span } => Diagnostic::error()
                .with_message("interpreter compiled without required features")
                .with_labels(vec![primary(&span).with_message(format!(
                    "this syntax is only supported with the `{feature}` feature enabled"
                ))])
                .with_notes(vec![format!(
                    "Recompile nickel with `--features {}`",
                    feature
                )]),
            ParseError::InvalidContract(span) => Diagnostic::error()
                .with_message("invalid contract expression")
                .with_labels(vec![primary(&span).with_message("this can't be used as a contract")])
                .with_notes(vec![
                    "This expression is used as a contract as part of an annotation or a type expression."
                        .to_owned(),
                    "Only functions and records might be valid contracts".to_owned(),
                ]),
            ParseError::InvalidImportFormat{span} => Diagnostic::error()
                .with_message("unknown import format tag")
                .with_labels(vec![primary(&span)])
                .with_notes(vec![
                    "Examples of valid format tags: 'Nickel, 'Json, 'Yaml, 'Toml, 'Text"
                        .to_owned()
                ]),
            ParseError::UnknownSigilSelector { selector, span } => {
                Diagnostic::error()
                .with_message(format!("unknown sigil selector `{selector}`"))
                .with_labels(vec![primary(&span)])
                .with_note("Available selectors are currently: `env`")
            }
            ParseError::UnknownSigilAttribute { selector, attribute, span } => {
                Diagnostic::error()
                .with_message(format!("unknown sigil attribute `{attribute}`"))
                .with_labels(vec![primary(&span).with_message(format!("unknown attribute for sigil selector `{selector}`"))])
                .with_note(available_sigil_attrs_note(&selector))
            }
            ParseError::SigilExprMissingColon(span) => {
                Diagnostic::error()
                .with_message("missing sigil expression separator `:`")
                .with_labels(vec![primary(&span)])
                .with_notes(vec![
                    "The CLI sigil expression syntax is `@<selector>:<argument>` or `@<selector>/<attribute>:<argument>`".to_owned(),
                    "The provided sigil expression is missing the `:` separator.".to_owned(),
                ])
            }
            ParseError::MultipleFieldDecls { ident, include_span, other_span } => Diagnostic::error()
                .with_message(format!(
                    "multiple declarations for included field `{ident}`",
                ))
                .with_labels(vec![
                    primary(&include_span).with_message("included here"),
                    secondary(&other_span).with_message("but also declared here"),
                ])
                .with_notes(vec![
                    "Piecewise definitions involving an included field are currently not supported".to_owned()
                ]),
        };

        vec![diagnostic]
    }
}

/// Returns the available attributes for each supported sigil
// It's currently trivial, but might be expanded in the future
fn available_sigil_attrs_note(selector: &str) -> String {
    format!(
        "No attributes are available for sigil selector `{selector}`. Use the selector directly as in `@{selector}:<argument>`"
    )
}

impl IntoDiagnostics for TypecheckErrorData {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        self.borrow_error().into_diagnostics(files)
    }
}

impl<'ast> IntoDiagnostics for &'_ TypecheckErrorKind<'ast> {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        fn mk_expr_label(span_opt: &TermPos) -> Vec<Label<FileId>> {
            mk_expr_label_with_msg(span_opt, "this expression".into())
        }

        fn mk_expr_label_with_msg(span_opt: &TermPos, msg: String) -> Vec<Label<FileId>> {
            span_opt
                .as_opt_ref()
                .map(|span| vec![primary(span).with_message(msg)])
                .unwrap_or_default()
        }

        fn mk_expected_msg<T: std::fmt::Display>(expected: &T) -> String {
            format!("Expected an expression of type `{expected}`")
        }

        fn mk_inferred_msg<T: std::fmt::Display>(inferred: &T) -> String {
            format!("Found an expression of type `{inferred}`")
        }

        match self {
            TypecheckErrorKind::UnboundIdentifier(id) =>
            // Use the same diagnostic as `EvalError::UnboundIdentifier` for consistency.
            {
                EvalErrorData {
                    ctxt: Default::default(),
                    error: EvalErrorKind::UnboundIdentifier(*id, id.pos),
                }
                .into_diagnostics(files)
            }
            TypecheckErrorKind::MissingRow {
                id,
                kind: RowKind::Record,
                expected,
                inferred,
                pos,
            } => {
                let id_access = match &expected.typ {
                    TypeF::Record(r) => {
                        r.find_row(id.ident()).and_then(|row| row.id.pos.into_opt())
                    }
                    _ => None,
                };
                let mut labels = mk_expr_label_with_msg(pos, format!("this record lacks `{id}`"));
                if let Some(id_access) = id_access {
                    labels
                        .push(secondary(&id_access).with_message(format!("`{id}` required here")));
                }
                vec![
                    Diagnostic::error()
                        .with_message(format!("type error: missing field `{id}`"))
                        .with_labels(labels)
                        .with_notes(vec![format!(
                            "Attempted to access field `{id}` on an expression of type `{inferred}`"
                        )]),
                ]
            }
            TypecheckErrorKind::MissingRow {
                id,
                kind: RowKind::Enum,
                expected,
                inferred,
                pos,
            } => vec![
                Diagnostic::error()
                    .with_message(format!("type error: missing row `{id}`"))
                    .with_labels(mk_expr_label(pos))
                    .with_notes(vec![
                        format!(
                            "{}, which contains the field `{id}`",
                            mk_expected_msg(expected)
                        ),
                        format!(
                            "{}, which does not contain the field `{id}`",
                            mk_inferred_msg(inferred)
                        ),
                    ]),
            ],
            TypecheckErrorKind::MissingDynTail {
                expected,
                inferred,
                pos,
            } => vec![
                Diagnostic::error()
                    .with_message(String::from("type error: missing dynamic tail `; Dyn`"))
                    .with_labels(mk_expr_label(pos))
                    .with_notes(vec![
                        format!(
                            "{}, which contains the tail `; Dyn`",
                            mk_expected_msg(expected)
                        ),
                        format!(
                            "{}, which does not contain the tail `; Dyn`",
                            mk_inferred_msg(inferred)
                        ),
                    ]),
            ],
            TypecheckErrorKind::ExtraRow {
                id,
                expected,
                inferred,
                pos,
            } => vec![
                Diagnostic::error()
                    .with_message(format!("type error: extra row `{id}`"))
                    .with_labels(mk_expr_label(pos))
                    .with_notes(vec![
                        format!(
                            "{}, which does not contain the field `{id}`",
                            mk_expected_msg(expected)
                        ),
                        format!(
                            "{}, which contains the extra field `{id}`",
                            mk_inferred_msg(inferred)
                        ),
                    ]),
            ],
            TypecheckErrorKind::ExtraDynTail {
                expected,
                inferred,
                pos,
            } => vec![
                Diagnostic::error()
                    .with_message(String::from("type error: extra dynamic tail `; Dyn`"))
                    .with_labels(mk_expr_label(pos))
                    .with_notes(vec![
                        format!(
                            "{}, which does not contain the tail `; Dyn`",
                            mk_expected_msg(expected)
                        ),
                        format!(
                            "{}, which contains the extra tail `; Dyn`",
                            mk_inferred_msg(inferred)
                        ),
                    ]),
            ],
            TypecheckErrorKind::UnboundTypeVariable(ident) => {
                vec![Diagnostic::error()
                    .with_message(format!("unbound type variable `{ident}`"))
                    .with_labels(vec![primary_alt(
                        ident.pos.into_opt(),
                        ident.to_string(),
                        files,
                    )
                    .with_message("this type variable is unbound")])
                    .with_notes(vec![format!(
                    "Did you forget to put a `forall {ident}.` somewhere in the enclosing type?"
                )])]
            }
            TypecheckErrorKind::TypeMismatch {
                expected,
                inferred,
                pos,
            } => {
                fn addendum<'ast>(ty: &Type<'ast>) -> &'static str {
                    if ty.typ.is_contract() {
                        " (a contract)"
                    } else {
                        ""
                    }
                }
                let last_note = if expected.typ.is_contract() ^ inferred.typ.is_contract() {
                    "Static types and contracts are not compatible"
                } else {
                    "These types are not compatible"
                };

                vec![
                    Diagnostic::error()
                        .with_message("incompatible types")
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                            format!("{}{}", mk_expected_msg(expected), addendum(expected),),
                            format!("{}{}", mk_inferred_msg(inferred), addendum(inferred),),
                            String::from(last_note),
                        ]),
                ]
            }
            TypecheckErrorKind::RecordRowMismatch {
                id,
                expected,
                inferred,
                cause: err,
                pos,
            } => {
                let mut err = err;
                // If the unification error is on a nested field, we will have a succession of
                // `RowMismatch` errors wrapping the underlying error. In this case, instead of
                // showing a cascade of similar error messages, we determine the full path of the
                // nested field (e.g. `pkg.subpkg1.meta.url`) and only show once the row mismatch
                // error followed by the underlying error.
                let mut path = vec![id.ident()];

                while let TypecheckErrorKind::RecordRowMismatch {
                    id: id_next,
                    cause: next,
                    ..
                } = &**err
                {
                    path.push(id_next.ident());
                    err = next;
                }

                let path_str: Vec<String> = path
                    .clone()
                    .into_iter()
                    .map(|ident| format!("{ident}"))
                    .collect();
                let field = path_str.join(".");

                let mk_expected_row_msg = |field, ty| {
                    format!("Expected an expression of a record type with the row `{field}: {ty}`")
                };
                let mk_inferred_row_msg = |field, ty| {
                    format!("Found an expression of a record type with the row `{field}: {ty}`")
                };

                //TODO: we should rather have RowMismatch hold a rows, instead of a general type,
                //than doing this match.
                let note1 = if let TypeF::Record(rrows) = &expected.typ {
                    match rrows.find_path(path.as_slice()) {
                        Some(row) => mk_expected_row_msg(&field, row.typ),
                        None => mk_expected_msg(&expected),
                    }
                } else {
                    mk_expected_msg(&expected)
                };

                let note2 = if let TypeF::Record(rrows) = &inferred.typ {
                    match rrows.find_path(path.as_slice()) {
                        Some(row) => mk_inferred_row_msg(&field, row.typ),
                        None => mk_inferred_msg(&inferred),
                    }
                } else {
                    mk_inferred_msg(inferred)
                };

                let mut diags = vec![
                    Diagnostic::error()
                        .with_message("incompatible record rows declaration")
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                            note1,
                            note2,
                            format!("Could not match the two declarations of `{field}`"),
                        ]),
                ];

                // We generate a diagnostic for the underlying error, but append a prefix to the
                // error message to make it clear that this is not a separate error but a more
                // precise description of why the unification of a row failed.
                diags.extend(err.into_diagnostics(files).into_iter().map(|mut diag| {
                    diag.message = format!("while typing field `{}`: {}", field, diag.message);
                    diag
                }));
                diags
            }
            TypecheckErrorKind::EnumRowMismatch {
                id,
                expected,
                inferred,
                cause,
                pos,
            } => {
                let mk_expected_row_msg = |row| {
                    format!("Expected an expression of an enum type with the enum row `{row}`")
                };
                let mk_inferred_row_msg =
                    |row| format!("Found an expression of an enum type with the enum row `{row}`");

                //TODO: we should rather have RowMismatch hold enum rows, instead of a general
                //type, to avoid doing this match.
                let note1 = if let TypeF::Enum(erows) = &expected.typ {
                    if let Some(row) = erows.find_row(id.ident()) {
                        mk_expected_row_msg(row)
                    } else {
                        mk_expected_msg(expected)
                    }
                } else {
                    mk_expected_msg(expected)
                };

                let note2 = if let TypeF::Enum(erows) = &inferred.typ {
                    if let Some(row) = erows.find_row(id.ident()) {
                        mk_inferred_row_msg(row)
                    } else {
                        mk_inferred_msg(expected)
                    }
                } else {
                    mk_inferred_msg(inferred)
                };

                let mut diags = vec![
                    Diagnostic::error()
                        .with_message("incompatible enum rows declaration")
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                            note1,
                            note2,
                            format!("Could not match the two declarations of `{id}`"),
                        ]),
                ];

                // We generate a diagnostic for the underlying error if any, but append a prefix to
                // the error message to make it clear that this is not a separate error but a more
                // precise description of why the unification of a row failed.
                if let Some(err) = cause {
                    diags.extend((*err).into_diagnostics(files).into_iter().map(|mut diag| {
                        diag.message = format!("while typing enum row `{id}`: {}", diag.message);
                        diag
                    }));
                }

                diags
            }
            TypecheckErrorKind::RecordRowConflict {
                row,
                expected,
                inferred,
                pos,
            } => {
                let mut diags = Vec::new();

                diags.push(
                    Diagnostic::error()
                        .with_message("multiple record row declarations")
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                            format!("Found an expression with the row `{row}`"),
                            format!(
                                "But this row appears inside another record type, \
                                which already has a different declaration for the field `{}`",
                                row.id
                            ),
                            String::from(
                                "A type cannot have two conflicting declarations for the same row",
                            ),
                        ]),
                );

                diags.push(
                    Diagnostic::note()
                        .with_message("while matching types")
                        .with_notes(vec![
                            format!("Expected type {expected}"),
                            format!("With inferred type {inferred}"),
                        ]),
                );

                diags
            }
            TypecheckErrorKind::EnumRowConflict {
                row,
                expected,
                inferred,
                pos,
            } => {
                let mut diags = Vec::new();

                diags.push(
                    Diagnostic::error()
                        .with_message("multiple enum row declarations")
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                            format!("Found an expression with the row `{row}`"),
                            format!(
                                "But this row appears inside another enum type, \
                                which already has a different declaration for the tag `{}`",
                                row.id
                            ),
                            String::from(
                                "A type cannot have two conflicting declarations for the same row",
                            ),
                        ]),
                );

                diags.push(
                    Diagnostic::note()
                        .with_message("while matching types")
                        .with_notes(vec![
                            format!("Expected type {expected}"),
                            format!("With inferred type {inferred}"),
                        ]),
                );

                diags
            }
            TypecheckErrorKind::ArrowTypeMismatch {
                expected,
                inferred,
                type_path,
                cause,
                pos,
            } => {
                // We locally convert the type to their runtime representation as a way to reuse
                // the code of `blame_error::path_span`, which works on the latter.
                let mut pos_table = PosTable::new();
                let expected_mline = expected.to_mainline(&mut pos_table);
                let inferred_mline = inferred.to_mainline(&mut pos_table);

                let PathSpan {
                    span: expd_span, ..
                } = blame_error::path_span(
                    &mut pos_table,
                    files,
                    type_path.iter(),
                    &expected_mline,
                );
                let PathSpan {
                    span: actual_span, ..
                } = blame_error::path_span(
                    &mut pos_table,
                    files,
                    type_path.iter(),
                    &inferred_mline,
                );

                let mut labels = vec![
                    secondary(&expd_span).with_message("this part of the expected type"),
                    secondary(&actual_span)
                        .with_message("does not match this part of the inferred type"),
                ];
                labels.extend(mk_expr_label(pos));

                let mut diags = vec![
                    Diagnostic::error()
                        .with_message("function types mismatch")
                        .with_labels(labels)
                        .with_notes(vec![
                            mk_expected_msg(expected),
                            mk_inferred_msg(inferred),
                            String::from("Could not match the two function types"),
                        ]),
                ];

                // We generate a diagnostic for the underlying error, but append a prefix to the
                // error message to make it clear that this is not a separated error but a more
                // precise description of why the unification of the row failed.
                match &**cause {
                    // If the underlying error is a type mismatch, printing won't add any useful
                    // information, so we just ignore it.
                    TypecheckErrorKind::TypeMismatch { .. } => (),
                    error => {
                        diags.extend(error.into_diagnostics(files).into_iter().map(|mut diag| {
                            diag.message =
                                format!("while matching function types: {}", diag.message);
                            diag
                        }));
                    }
                }

                diags
            }
            TypecheckErrorKind::ForallParametricityViolation {
                kind,
                tail,
                violating_type,
                pos,
            } => {
                let tail_kind = match kind {
                    VarKindDiscriminant::Type => "type",
                    VarKindDiscriminant::EnumRows => "enum tail",
                    VarKindDiscriminant::RecordRows => "record tail",
                };
                vec![
                    Diagnostic::error()
                        .with_message(format!(
                            "values of type `{violating_type}` are not guaranteed to be compatible \
                        with polymorphic {tail_kind} `{tail}`"
                        ))
                        .with_labels(mk_expr_label(pos))
                        .with_notes(vec![
                        "Type variables introduced in a `forall` range over all possible types."
                            .to_owned(),
                    ]),
                ]
            }
            TypecheckErrorKind::CtrTypeInTermPos { contract, pos_type } => {
                vec![Diagnostic::error()
                    .with_message(
                        "types containing user-defined contracts cannot be converted into contracts"
                    )
                    .with_labels(
                        pos_type.as_opt_ref()
                            .map(|span| {
                                primary(span).with_message("This type (in contract position)")
                            })
                            .into_iter()
                            .chain(contract.pos.as_opt_ref().map(|span| {
                                secondary(span).with_message("contains this user-defined contract")
                            }))
                            .collect(),
                    )]
            }
            TypecheckErrorKind::VarLevelMismatch {
                type_var: constant,
                pos,
            } => {
                let mut labels = mk_expr_label(pos);

                if let Some(span) = constant.pos.as_opt_ref() {
                    labels.push(secondary(span).with_message("this polymorphic type variable"));
                }

                vec![
                    Diagnostic::error()
                        .with_message("invalid polymorphic generalization".to_string())
                        .with_labels(labels)
                        .with_notes(vec![
                            "While the type of this expression is still undetermined, it appears \
                            indirectly in the type of another expression introduced before \
                            the `forall` block."
                                .into(),
                            format!(
                                "The type of this expression escapes the scope of the \
                                corresponding `forall` and can't be generalized to the \
                                polymorphic type variable `{constant}`"
                            ),
                        ]),
                ]
            }
            TypecheckErrorKind::InhomogeneousRecord {
                pos,
                row_a: expected,
                row_b: inferred,
            } => {
                vec![Diagnostic::error()
                    .with_message("incompatible types")
                    .with_labels(mk_expr_label(pos))
                    .with_notes(vec![
                        "Expected a dictionary type".into(),
                        format!("Found a record with a field of type {expected} and a field of type {inferred}"),
                        "Records are compatible with dicts only if all their fields have the same type".into(),
                    ])]
            }
            TypecheckErrorKind::OrPatternVarsMismatch { var, pos } => {
                let mut labels = vec![
                    primary_alt(var.pos.into_opt(), var.into_label(), files)
                        .with_message("this variable must occur in all branches"),
                ];

                if let Some(span) = pos.as_opt_ref() {
                    labels.push(secondary(span).with_message("in this or-pattern"));
                }

                vec![
                    Diagnostic::error()
                        .with_message("or-pattern variable mismatch".to_string())
                        .with_labels(labels)
                        .with_notes(vec![
                        "All branches of an or-pattern must bind exactly the same set of variables"
                            .into(),
                    ]),
                ]
            }
            // clone() here is unfortunate, but I haven't found a better way to interface typecheck
            // errors - which can generate a diagnostic by reference - from other errors (import
            // errors can themselves hide parsing errors), where `into_diagnostics` consume `self`
            // in the current implementation. Maybe we should migrate from `into_diagnostics` to
            // `to_diagnostic`, taking the error by reference, but this might cause more copying.
            TypecheckErrorKind::ImportError(err) => err.clone().into_diagnostics(files),
        }
    }
}

impl IntoDiagnostics for ImportErrorKind {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        match self {
            ImportErrorKind::IOError(path, error, span_opt) => {
                let labels = span_opt
                    .as_opt_ref()
                    .map(|span| vec![secondary(span).with_message("imported here")])
                    .unwrap_or_default();

                vec![
                    Diagnostic::error()
                        .with_message(format!("import of {path} failed: {error}"))
                        .with_labels(labels),
                ]
            }
            ImportErrorKind::ParseErrors(error, span_opt) => {
                let mut diagnostic: Vec<Diagnostic<FileId>> = error
                    .errors
                    .into_iter()
                    .flat_map(|e| e.into_diagnostics(files))
                    .collect();

                if let Some(span) = span_opt.as_opt_ref() {
                    diagnostic[0]
                        .labels
                        .push(secondary(span).with_message("imported here"));
                }

                diagnostic
            }
            ImportErrorKind::MissingDependency {
                parent,
                missing,
                pos,
            } => {
                let labels = pos
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("imported here")])
                    .unwrap_or_default();
                let msg = if let Some(parent_path) = parent.as_deref() {
                    format!(
                        "unknown package {missing}, imported from package {}",
                        parent_path.display()
                    )
                } else {
                    format!("unknown package {missing}")
                };

                vec![Diagnostic::error().with_message(msg).with_labels(labels)]
            }
            ImportErrorKind::NoPackageMap { pos } => {
                let labels = pos
                    .as_opt_ref()
                    .map(|span| vec![primary(span).with_message("imported here")])
                    .unwrap_or_default();
                vec![
                    Diagnostic::error()
                        .with_message(
                            "tried to import from a package, but no package manifest found",
                        )
                        .with_labels(labels)
                        .with_notes(vec![
                            "did you forget a --manifest-path argument?".to_owned(),
                        ]),
                ]
            }
        }
    }
}

impl IntoDiagnostics for ExportErrorData {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        let mut notes = if !self.data.path.0.is_empty() {
            vec![format!("When exporting field `{}`", self.data.path)]
        } else {
            vec![]
        };

        let pos_table = self.pos_table;

        match self.data.error {
            ExportErrorKind::NotAString(rt) => vec![
                Diagnostic::error()
                    .with_message(format!(
                        "raw export expects a String value, but got {}",
                        rt.type_of().unwrap_or("<unevaluated>")
                    ))
                    .with_labels(vec![primary_term(&pos_table, &rt, files)])
                    .with_notes(notes),
            ],
            ExportErrorKind::UnsupportedNull(format, rt) => vec![
                Diagnostic::error()
                    .with_message(format!("{format} format doesn't support null values"))
                    .with_labels(vec![primary_term(&pos_table, &rt, files)])
                    .with_notes(notes),
            ],
            ExportErrorKind::NonSerializable(rt) => {
                notes.extend([
                    "Nickel only supports serializing to and from strings, booleans, numbers, \
                    enum tags, `null` (depending on the format), as well as records and arrays \
                    of serializable values."
                        .into(),
                    "Functions and special values (such as contract labels) aren't \
                    serializable."
                        .into(),
                    "If you want serialization to ignore a specific value, please use the \
                    `not_exported` metadata."
                        .into(),
                ]);

                vec![
                    Diagnostic::error()
                        .with_message("non serializable term")
                        .with_labels(vec![primary_term(&pos_table, &rt, files)])
                        .with_notes(notes),
                ]
            }
            ExportErrorKind::NoDocumentation(rt) => {
                notes.push("documentation can only be collected from a record.".to_owned());

                vec![
                    Diagnostic::error()
                        .with_message("no documentation found")
                        .with_labels(vec![primary_term(&pos_table, &rt, files)])
                        .with_notes(notes),
                ]
            }
            ExportErrorKind::NumberOutOfRange { term, value } => {
                notes.push(format!(
                    "Only numbers in the range {:e} to {:e} can be portably serialized",
                    f64::MIN,
                    f64::MAX
                ));

                vec![
                    Diagnostic::error()
                        .with_message(format!(
                            "The number {} is too large (in absolute value) to be serialized.",
                            value.to_sci()
                        ))
                        .with_labels(vec![primary_term(&pos_table, &term, files)])
                        .with_notes(notes),
                ]
            }
            ExportErrorKind::Other(msg) => {
                notes.push(msg);

                vec![
                    Diagnostic::error()
                        .with_message("serialization failed")
                        .with_notes(notes),
                ]
            }
            ExportErrorKind::ExpectedArray { value } => {
                vec![
                    Diagnostic::error()
                        .with_message("yaml-documents export expects an array")
                        .with_labels(vec![primary_term(&pos_table, &value, files)])
                        .with_notes(notes),
                ]
            }
        }
    }
}

impl IntoDiagnostics for IOError {
    fn into_diagnostics(self, _fil: &mut Files) -> Vec<Diagnostic<FileId>> {
        match self {
            IOError(msg) => vec![Diagnostic::error().with_message(msg)],
        }
    }
}

impl IntoDiagnostics for ReplErrorKind {
    fn into_diagnostics(self, files: &mut Files) -> Vec<Diagnostic<FileId>> {
        match self {
            ReplErrorKind::UnknownCommand(s) => vec![
                Diagnostic::error()
                    .with_message(format!("unknown command `{s}`"))
                    .with_notes(vec![String::from(
                        "type `:?` or `:help` for a list of available commands.",
                    )]),
            ],
            ReplErrorKind::InvalidQueryPath(err) => err.into_diagnostics(files),
            ReplErrorKind::MissingArg { cmd, msg_opt } => {
                let mut notes = msg_opt
                    .as_ref()
                    .map(|msg| vec![msg.clone()])
                    .unwrap_or_default();
                notes.push(format!(
                    "type `:? {cmd}` or `:help {cmd}` for more information."
                ));

                vec![
                    Diagnostic::error()
                        .with_message(format!("{cmd}: missing argument"))
                        .with_notes(notes),
                ]
            }
        }
    }
}

impl CloneTo for TypecheckErrorKind<'_> {
    type Data<'ast> = TypecheckErrorKind<'ast>;

    fn clone_to<'to>(data: Self::Data<'_>, dest: &'to AstAlloc) -> Self::Data<'to> {
        match data {
            TypecheckErrorKind::UnboundIdentifier(loc_ident) => {
                TypecheckErrorKind::UnboundIdentifier(loc_ident)
            }
            TypecheckErrorKind::MissingRow {
                id,
                kind,
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::MissingRow {
                id,
                kind,
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::MissingDynTail {
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::MissingDynTail {
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::ExtraRow {
                id,
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::ExtraRow {
                id,
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::ExtraDynTail {
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::ExtraDynTail {
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::ForallParametricityViolation {
                kind,
                tail,
                violating_type,
                pos,
            } => TypecheckErrorKind::ForallParametricityViolation {
                kind,
                tail: Type::clone_to(tail, dest),
                violating_type: Type::clone_to(violating_type, dest),
                pos,
            },
            TypecheckErrorKind::UnboundTypeVariable(loc_ident) => {
                TypecheckErrorKind::UnboundTypeVariable(loc_ident)
            }
            TypecheckErrorKind::TypeMismatch {
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::TypeMismatch {
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::RecordRowMismatch {
                id,
                expected,
                inferred,
                cause,
                pos,
            } => TypecheckErrorKind::RecordRowMismatch {
                id,
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                cause: Box::new(TypecheckErrorKind::clone_to(*cause, dest)),
                pos,
            },
            TypecheckErrorKind::EnumRowMismatch {
                id,
                expected,
                inferred,
                cause,
                pos,
            } => TypecheckErrorKind::EnumRowMismatch {
                id,
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                cause: cause.map(|cause| Box::new(TypecheckErrorKind::clone_to(*cause, dest))),
                pos,
            },
            TypecheckErrorKind::RecordRowConflict {
                row,
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::RecordRowConflict {
                row: RecordRow::clone_to(row, dest),
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::EnumRowConflict {
                row,
                expected,
                inferred,
                pos,
            } => TypecheckErrorKind::EnumRowConflict {
                row: EnumRow::clone_to(row, dest),
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                pos,
            },
            TypecheckErrorKind::ArrowTypeMismatch {
                expected,
                inferred,
                type_path,
                cause,
                pos,
            } => TypecheckErrorKind::ArrowTypeMismatch {
                expected: Type::clone_to(expected, dest),
                inferred: Type::clone_to(inferred, dest),
                type_path,
                cause: Box::new(TypecheckErrorKind::clone_to(*cause, dest)),
                pos,
            },
            TypecheckErrorKind::CtrTypeInTermPos { contract, pos_type } => {
                TypecheckErrorKind::CtrTypeInTermPos {
                    contract: Ast::clone_to(contract, dest),
                    pos_type,
                }
            }
            TypecheckErrorKind::VarLevelMismatch { type_var, pos } => {
                TypecheckErrorKind::VarLevelMismatch { type_var, pos }
            }
            TypecheckErrorKind::InhomogeneousRecord { row_a, row_b, pos } => {
                TypecheckErrorKind::InhomogeneousRecord {
                    row_a: Type::clone_to(row_a, dest),
                    row_b: Type::clone_to(row_b, dest),
                    pos,
                }
            }
            TypecheckErrorKind::OrPatternVarsMismatch { var, pos } => {
                TypecheckErrorKind::OrPatternVarsMismatch { var, pos }
            }
            TypecheckErrorKind::ImportError(import_error) => {
                TypecheckErrorKind::ImportError(import_error)
            }
        }
    }
}//! Error diagnostics reporting and serialization.
use codespan_reporting::term::termcolor::{Ansi, NoColor};

use super::*;

/// Serializable wrapper type to export diagnostics with a top-level attribute.
#[derive(serde::Serialize)]
pub struct DiagnosticsWrapper {
    pub diagnostics: Vec<Diagnostic<FileId>>,
}

impl From<Vec<Diagnostic<FileId>>> for DiagnosticsWrapper {
    fn from(diagnostics: Vec<Diagnostic<FileId>>) -> Self {
        Self { diagnostics }
    }
}

/// Available export formats for error diagnostics.
#[derive(Copy, Clone, Eq, PartialEq, Debug, Default)]
#[cfg_attr(feature = "clap", derive(clap::ValueEnum))]
pub enum ErrorFormat {
    #[default]
    Text,
    Json,
    Yaml,
    Toml,
}

pub type ColorOpt = colorchoice::ColorChoice;

fn colors_for_terminal(color_opt: ColorOpt, is_terminal: bool) -> ColorChoice {
    match color_opt {
        colorchoice::ColorChoice::Auto => {
            if is_terminal {
                ColorChoice::Auto
            } else {
                ColorChoice::Never
            }
        }
        colorchoice::ColorChoice::Always => ColorChoice::Always,
        colorchoice::ColorChoice::AlwaysAnsi => ColorChoice::AlwaysAnsi,
        colorchoice::ColorChoice::Never => ColorChoice::Never,
    }
}

/// Pretty-print an error on stderr.
///
/// # Arguments
///
/// - `cache` is the file cache used during the evaluation, which is required by the reporting
///   infrastructure to point at specific locations and print snippets when needed.
pub fn report<E: IntoDiagnostics>(
    files: &mut Files,
    error: E,
    format: ErrorFormat,
    color_opt: ColorOpt,
) {
    use std::io::{IsTerminal, stderr};

    report_with(
        &mut StandardStream::stderr(colors_for_terminal(color_opt, stderr().is_terminal())).lock(),
        files,
        error,
        format,
    )
}

/// Pretty-print an error on stdout.
///
/// # Arguments
///
/// - `cache` is the file cache used during the evaluation, which is required by the reporting
///   infrastructure to point at specific locations and print snippets when needed.
pub fn report_to_stdout<E: IntoDiagnostics>(
    files: &mut Files,
    error: E,
    format: ErrorFormat,
    color_opt: ColorOpt,
) {
    use std::io::{IsTerminal, stdout};

    report_with(
        &mut StandardStream::stdout(colors_for_terminal(color_opt, stdout().is_terminal())).lock(),
        files,
        error,
        format,
    )
}

/// Build an error report as a string and return it.
pub fn report_as_str<E: IntoDiagnostics>(
    files: &mut Files,
    error: E,
    color_opt: ColorOpt,
) -> String {
    let mut buffer = Vec::new();
    let mut with_color;
    let mut no_color;
    let writer: &mut dyn WriteColor = if color_opt == colorchoice::ColorChoice::Never {
        no_color = NoColor::new(&mut buffer);
        &mut no_color
    } else {
        with_color = Ansi::new(&mut buffer);
        &mut with_color
    };

    report_with(writer, files, error, ErrorFormat::Text);
    // unwrap(): report_with() should only print valid utf8 to the the buffer
    String::from_utf8(buffer).unwrap()
}

/// Report an error on `stderr`, provided a file database and a list of stdlib file ids.
pub fn report_with<E: IntoDiagnostics>(
    writer: &mut dyn WriteColor,
    files: &mut Files,
    error: E,
    format: ErrorFormat,
) {
    let config = codespan_reporting::term::Config::default();
    let diagnostics = error.into_diagnostics(files);
    let stderr = std::io::stderr();

    let result = match format {
        ErrorFormat::Text => diagnostics.iter().try_for_each(|d| {
            codespan_reporting::term::emit_to_write_style(writer, &config, files, d)
                .map_err(|err| err.to_string())
        }),
        ErrorFormat::Json => serde_json::to_writer(stderr, &DiagnosticsWrapper::from(diagnostics))
            .map(|_| eprintln!())
            .map_err(|err| err.to_string()),
        ErrorFormat::Yaml => serde_yaml::to_writer(stderr, &DiagnosticsWrapper::from(diagnostics))
            .map_err(|err| err.to_string()),
        ErrorFormat::Toml => toml::to_string(&DiagnosticsWrapper::from(diagnostics))
            .map(|repr| eprint!("{repr}"))
            .map_err(|err| err.to_string()),
    };

    match result {
        Ok(()) => (),
        Err(err) => panic!("error::report_with(): could not print an error on stderr: {err}"),
    };
}//! Suggest existing symbols that are similar to what the user typed in case of various "symbol not
//! found" errors, such as [super::EvalErrorKind::UnboundIdentifier] or
//! [super::EvalErrorKind::FieldMissing].
//!
//! The current implementation uses the normalized Damereau-Levenshtein edit distance to find the
//! closest match.

use strsim::normalized_damerau_levenshtein;

/// The minimum similarity between the user's input and an existing symbol for the symbol to be
/// considered a serious candidate. The current threshold is rather low, because short words with
/// edit distance 1 such as `bar` and `bare` might have a similarity which isn't that high.
pub const MIN_SIMILARITY: f64 = 0.60;

/// Find the closest match to the user input in the given list of symbols, to be used as a
/// suggestion. If there is an exact match (modulo casing), it is returned immediately. Otherwise,
/// the symbol with the highest normalized Damerau-Levenshtein similarity is returned, as long as
/// the similarity is above the fixed threshold [MIN_SIMILARITY].
pub fn find_best_match<'syms, 'input, S, I>(
    symbols: &'syms [S],
    user_input: &'input I,
) -> Option<&'syms str>
where
    S: AsRef<str>,
    I: AsRef<str>,
{
    let mut max = f64::MIN;
    let mut arg_max: Option<&'syms str> = None;

    if symbols.is_empty() {
        return None;
    }

    for sym in symbols {
        // If there is an exact match (modulo case), return it immediately.
        if sym.as_ref().to_lowercase() == user_input.as_ref().to_lowercase() {
            return Some(sym.as_ref());
        }

        let similarity = normalized_damerau_levenshtein(sym.as_ref(), user_input.as_ref());

        if similarity > max && similarity >= MIN_SIMILARITY {
            arg_max = Some(sym.as_ref());
            max = similarity;
        }
    }

    arg_max
}

/// Take diagnostic notes and add a generic note suggesting existing symbols that are similar to
/// what the user typed thanks to [find_best_match], if any. If there is no match, `notes` is left
/// unchanged.
pub fn add_suggestion<S, I>(notes: &mut Vec<String>, symbols: &[S], user_input: &I)
where
    S: AsRef<str>,
    I: AsRef<str>,
{
    if let Some(best_match) = find_best_match(symbols, user_input) {
        notes.push(format!("Did you mean `{best_match}`?"));
    }
}use codespan_reporting::diagnostic::Diagnostic;

use crate::error::{IntoDiagnostics, primary, secondary};
use crate::files::{FileId, Files};
use crate::position::TermPos;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Warning {
    /// Applied a `fun label value => ...` (or match) as a contract directly,
    /// instead of using the construct constructors in the standard library.
    NakedFunctionContract {
        /// The position of the function that was used as a contract.
        func_pos: TermPos,
        /// The position of the thing that the contract was applied to.
        app_pos: TermPos,
    },
}

impl IntoDiagnostics for Warning {
    fn into_diagnostics(self, _files: &mut Files) -> Vec<Diagnostic<FileId>> {
        match self {
            Warning::NakedFunctionContract { func_pos, app_pos } => {
                let mut labels = vec![];
                if let Some(span) = app_pos.into_opt() {
                    labels.push(primary(&span).with_message("applied to this term"));
                }

                if let Some(func_span) = func_pos.into_opt() {
                    labels.push(secondary(&func_span).with_message("this function"));
                }

                vec![Diagnostic::warning()
                    .with_message("plain functions as contracts are deprecated")
                    .with_labels(labels)
                    .with_notes(vec!["wrap this function using one of the constructors in `std.contract` instead, like `std.contract.from_validator` or `std.contract.custom`".to_owned()])
                ]
            }
        }
    }
}//! Cross-evaluation incremental evaluation capabilities.

use super::{
    Cache,
    lazy::{CBNCache, Thunk, ThunkState},
};

use crate::eval::semantic_hash::SemanticHash;
use std::{
    collections::{HashMap, hash_map::Entry},
    io,
};

/// A thunk coming from a previous evaluation. Can be lazily loaded as a normal thunk if needed.
#[derive(Clone)]
pub struct LoadableThunk(Thunk);

impl LoadableThunk {
    pub fn load(&self) -> Thunk {
        self.0.clone()
    }
}

#[derive(Clone)]
pub enum CacheEntry {
    /// The entry is coming from a previous evaluation round, but it hasn't been re-used yet.
    Loadable(LoadableThunk),
    /// The entry is coming from a previous evaluation round, and it has been re-used in the
    /// current one.
    Loaded(Thunk),
    /// The entry is a new thunk coming from the current evaluation round.
    Recorded(Thunk),
}

impl CacheEntry {
    pub fn get(&mut self) -> &Thunk {
        match self {
            CacheEntry::Loadable(loadable_thunk) => {
                *self = CacheEntry::Loaded(loadable_thunk.load());
                self.get()
            }
            CacheEntry::Loaded(thunk) | CacheEntry::Recorded(thunk) => thunk,
        }
    }
}

// Not clear yet if all hashable thunks should always be fetched from cache, or if we need a
// distinction between dependencies (intermediate thunks) whose hash is needed but that we don't
// necessarily want to put in the cache, and thunks of interest. Note that at the time of
// serialization, we'll need _some_ dependencies, but they might have changed (or be gone
// completely). If there is no distinction, then we don't need the whole on-demand computation for
// hashes: we need to pre-compute the hash anyway to see if the thunk is in the cache, so we can
// very much fill it right away at thunk creation. Concretely, the question is: should we have only
// one `add_cached` additional method, or a `add_hashed` and `add_or_get_from_cache`? Let's
// meditate.
//
// # After meditation
//
// I think there's an even better way: makes hashing/cache fetching lazy, and only try to fetch
// from the incremental cache when we first evaluate a (hashable/of interest) thunk. Doing so, any
// unused thunk will be left alone. We can compute hashes in a lazy way. This means we allocate a
// thunk unconditionally at first (even if it ends up being pulled from the incremental cache), but
// it's not a huge cost and is likely to be similar to the cost of pulling an existing loadable
// thunk from the incremental cache anyway, as we need to put the thunk data somewhere.
#[derive(Default, Clone)]
pub struct IncrementalCache {
    cbn_cache: CBNCache,
    thunks: HashMap<SemanticHash, CacheEntry>,
}

impl IncrementalCache {
    /// Serialize the cache to a persistent storage (typically a file), to be re-used in a
    /// subsequent evaluation. Only loaded and recorded [CacheEntry]s will be saved; loadable ones
    /// (recorded from the previous evaluation but not used in the current one) are dropped.
    pub fn persist(self, _out: impl io::Write) -> io::Result<()> {
        unimplemented!()
    }

    /// Loads a persisted cache.
    pub fn load(_src: impl io::Read) -> io::Result<Self> {
        unimplemented!()
    }
}

impl Cache for IncrementalCache {
    type UpdateIndex = <CBNCache as Cache>::UpdateIndex;

    fn get(&self, idx: super::CacheIndex) -> crate::eval::Closure {
        self.cbn_cache.get(idx)
    }

    fn get_update_index(
        &mut self,
        idx: &mut super::CacheIndex,
    ) -> Result<Option<Self::UpdateIndex>, super::BlackholedError> {
        // Incremental caching: if the thunk has a computable hash, and we find it in the table, we
        // use that value as well
        if let ThunkState::Suspended = idx.state()
            && idx.cui().is_some()
            && let Some(content_hash) = idx.semantic_hash()
            && let Some(cached) = self.thunks.get_mut(&content_hash)
        {
            idx.clone().update(cached.get().get_owned())
        }

        self.cbn_cache.get_update_index(idx)
    }

    fn add(
        &mut self,
        clos: crate::eval::Closure,
        bty: crate::term::BindingType,
    ) -> super::CacheIndex {
        self.cbn_cache.add(clos, bty)
    }

    fn patch<F: Fn(&mut crate::eval::Closure)>(&mut self, idx: super::CacheIndex, f: F) {
        self.cbn_cache.patch(idx, f)
    }

    fn get_then<T, F: FnOnce(&crate::eval::Closure) -> T>(
        &self,
        idx: super::CacheIndex,
        f: F,
    ) -> T {
        self.cbn_cache.get_then(idx, f)
    }

    fn update(&mut self, clos: crate::eval::Closure, idx: Self::UpdateIndex) {
        // If we update a thunk of interest, now that we have a value for it, we can try to compute its
        // hash and record it for future evaluations.
        if idx.cui().is_some()
            && let Some(content_hash) = idx.semantic_hash()
            && let Entry::Vacant(entry) = self.thunks.entry(content_hash)
        {
            entry.insert_entry(CacheEntry::Recorded(idx.clone()));
        }

        self.cbn_cache.update(clos, idx)
    }

    fn new() -> Self {
        Self::default()
    }

    fn reset_index_state(&mut self, idx: &mut Self::UpdateIndex) {
        self.cbn_cache.reset_index_state(idx)
    }

    fn build_cached(
        &mut self,
        idx: &mut super::CacheIndex,
        rec_env: &[(nickel_lang_parser::identifier::Ident, super::CacheIndex)],
    ) {
        self.cbn_cache.build_cached(idx, rec_env)
    }

    fn saturate<I: DoubleEndedIterator<Item = nickel_lang_parser::identifier::Ident> + Clone>(
        &mut self,
        idx: super::CacheIndex,
        fields: I,
    ) -> crate::eval::value::NickelValue {
        self.cbn_cache.saturate(idx, fields)
    }

    fn revert(&mut self, idx: &super::CacheIndex) -> super::CacheIndex {
        self.cbn_cache.revert(idx)
    }

    fn deps(&self, idx: &super::CacheIndex) -> Option<crate::term::record::FieldDeps> {
        self.cbn_cache.deps(idx)
    }

    fn make_update_index(
        &mut self,
        idx: &mut super::CacheIndex,
    ) -> Result<Self::UpdateIndex, super::BlackholedError> {
        self.cbn_cache.make_update_index(idx)
    }

    fn attach_cui(&mut self, idx: &super::CacheIndex, cui: SemanticHash) {
        idx.set_cui(cui);
    }
}use std::collections::{HashMap, HashSet};

//! A [Cache] implementation with incremental computation features.
use super::{BlackholedError, Cache, CacheIndex, Closure, Environment, IdentKind};
use crate::{
    identifier::Ident,
    term::{record::FieldDeps, BindingType, RichTerm, Term},
};

/// The evaluation state of an [IncNode].
#[derive(Debug, Copy, Clone, Default, PartialEq, Eq)]
pub enum IncNodeState {
    #[default]
    Suspended,
    Blackholed,
    Evaluated,
}

#[derive(Debug, Copy, Clone, Eq, PartialEq)]
pub struct DependencyLink {
    id: Ident,
    idx: CacheIndex,
}

/// A node in the dependent computation graph stored in [IncCache].
#[derive(Debug, Clone)]
pub struct IncNode {
    // The original closure.
    orig: Closure,
    // The cached value of the closure.
    cached: Option<Closure>,
    kind: IdentKind,
    bty: BindingType,
    // The state of the node.
    state: IncNodeState,
    // Forward links to dependencies.
    fwdlinks: Vec<DependencyLink>,
    // Backlinks to nodes depending on this node.
    backlinks: Vec<DependencyLink>,
}

impl IncNode {
    fn new(clos: Closure, kind: IdentKind, bty: BindingType) -> Self {
        IncNode {
            orig: clos,
            cached: None,
            kind,
            bty,
            state: IncNodeState::default(),
            fwdlinks: Vec::new(),
            backlinks: Vec::new(),
        }
    }
}

/// A [Cache] implementation supporting incremental computation features.
/// Stores a dependent computation graph to keep track of what needs to be recomputed.
#[derive(Debug, Clone)]
pub struct IncCache {
    store: Vec<IncNode>,
    next: CacheIndex,
}

impl IncCache {
    fn add_node(&mut self, node: IncNode) -> CacheIndex {
        let idx = self.next;
        self.store.insert(idx, node);
        self.next += 1;

        idx
    }

    fn revnode_as_explicit_fun<'a, I>(node: &IncNode, args: I) -> IncNode
    where
        I: DoubleEndedIterator<Item = &'a Ident>,
    {
        match &node.bty {
            BindingType::Revertible(deps) if !deps.is_empty() => {
                let Closure { body, env } = node.orig.clone();

                // Build a list of the arguments that the function will need in the same order as
                // the original iterator. If the identifiers inside `args` are `a`, `b` and `c`, in
                // that order, we want to build `fun a => (fun b => (fun c => body))`. We thus need
                // a reverse fold.
                let as_function =
                    args.rfold(body, |built, id| RichTerm::from(Term::Fun(*id, built)));

                IncNode::new(
                    Closure {
                        body: as_function,
                        env,
                    },
                    node.kind,
                    node.bty.clone(),
                )
            }
            _ => node.clone(),
        }
    }

    fn update_backlinks(&mut self, idx: CacheIndex) {
        let node = self.store.get(idx).unwrap().clone();
        for i in node.fwdlinks {
            let n = self.store.get_mut(i.idx).unwrap();
            n.backlinks.push(DependencyLink { id: i.id, idx: idx });
        }
    }

    fn propagate_dirty(&mut self, idx: CacheIndex) {
        let mut node = self.store.get_mut(idx).unwrap();
        node.cached = None;
        node.state = IncNodeState::Suspended;

        let mut visited = HashSet::new();
        let mut stack = node.backlinks.clone();

        visited.insert(idx);

        while !stack.is_empty() {
            let i = stack.pop().unwrap();
            visited.insert(i.idx);
            let mut current_node = self.store.get_mut(i.idx).unwrap();
            current_node.cached = None;
            current_node.state = IncNodeState::Suspended;
            stack.extend(
                current_node
                    .backlinks
                    .iter()
                    .filter(|x| !visited.contains(&x.idx)),
            )
        }
    }

    /* Do we need this when we can revert in place?

    fn propagate_revert(&mut self, id: Ident, idx: CacheIndex) -> HashMap<Ident, CacheIndex> {
        let mut nodes_reverted = HashMap::new();

        let mut visited = HashSet::new();
        let mut stack = vec![idx];

        while !stack.is_empty() {
            let i = stack.pop().unwrap();
            visited.insert(i);

            let idx_reverted = self.revert(&idx);
            //FIXME: use the actual node's id
            let node_id = Ident::from("TODO!");
            nodes_reverted.insert(node_id, idx_reverted);

            let current_node = self.store.get(i).unwrap();

            stack.extend(
                current_node
                    .backlinks
                    .iter()
                    .map(|x| x.idx)
                    .filter(|x| !visited.contains(x)),
            )
        }

        nodes_reverted
    } */

    fn smart_clone(&mut self, v: Vec<CacheIndex>) -> HashMap<CacheIndex, CacheIndex> {
        let mut new_indices = HashMap::new();

        for i in v.iter() {
            let current_node = self.store.get(*i).unwrap().clone();
            new_indices.insert(*i, self.add_node(current_node));
        }

        for i in new_indices.values() {
            let current_node = self.store.get_mut(*i).unwrap();

            for dep in current_node.backlinks.iter_mut() {
                dep.idx = *new_indices.get(i).unwrap();
            }

            for dep in current_node.fwdlinks.iter_mut() {
                dep.idx = *new_indices.get(i).unwrap();
            }
        }

        new_indices
    }
}

impl Cache for IncCache {
    type UpdateIndex = CacheIndex;

    fn new() -> Self {
        IncCache {
            store: Vec::new(),
            next: 0,
        }
    }

    fn get(&self, idx: CacheIndex) -> Closure {
        let node = self.store.get(idx).unwrap();

        node.cached.clone().unwrap_or(node.orig.clone())
    }

    fn get_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Option<Self::UpdateIndex>, BlackholedError> {
        let node = self.store.get_mut(*idx).unwrap();

        if node.state == IncNodeState::Blackholed {
            Err(BlackholedError)
        } else if node.state == IncNodeState::Evaluated {
            Ok(None)
        } else {
            node.state = IncNodeState::Blackholed;
            Ok(Some(*idx))
        }
    }

    fn add(&mut self, clos: Closure, kind: IdentKind, bty: BindingType) -> CacheIndex {
        let node = IncNode::new(clos, kind, bty);

        self.add_node(node)
    }

    fn update(&mut self, clos: Closure, idx: Self::UpdateIndex) {
        let node = self.store.get_mut(idx).unwrap();

        node.cached = Some(clos);
        node.state = IncNodeState::Evaluated;
    }

    fn revert(&mut self, idx: &CacheIndex) -> CacheIndex {
        let node = self.store.get(*idx).unwrap();

        let new_node = match node.bty.clone() {
            BindingType::Normal => node.clone(),
            BindingType::Revertible(_) => {
                IncNode::new(node.orig.clone(), node.kind, node.bty.clone())
            }
        };

        self.add_node(new_node)
    }

    fn ident_kind(&self, idx: &CacheIndex) -> IdentKind {
        self.store.get(*idx).unwrap().kind
    }

    fn deps(&self, idx: &CacheIndex) -> Option<FieldDeps> {
        let node = self.store.get(*idx).unwrap();
        match node.bty.clone() {
            BindingType::Normal => None,
            BindingType::Revertible(deps) => Some(deps),
        }
    }

    fn get_then<T, F: FnOnce(&Closure) -> T>(&self, idx: CacheIndex, f: F) -> T {
        f(&self.get(idx))
    }

    fn patch<F: Fn(&mut Closure)>(&mut self, idx: CacheIndex, f: F) {
        let node = self.store.get_mut(idx).unwrap();

        f(&mut node.orig);
        node.cached.as_mut().map(|mut clos| f(&mut clos));
    }

    fn make_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Self::UpdateIndex, BlackholedError> {
        let node = self.store.get_mut(*idx).unwrap();

        if node.state == IncNodeState::Blackholed {
            return Err(BlackholedError);
        } else {
            node.state = IncNodeState::Blackholed;

            Ok(*idx)
        }
    }

    fn reset_index_state(&mut self, idx: &mut Self::UpdateIndex) {
        let node = self.store.get_mut(*idx).unwrap();

        node.state = IncNodeState::default();
    }

    // fn map_at_index<F: FnMut(&mut Self, &Closure) -> Closure>(
    //     &mut self,
    //     idx: &CacheIndex,
    //     mut f: F,
    // ) -> CacheIndex {
    //     let node = self.store.get(*idx).unwrap().clone();
    //
    //     let new_node = IncNode {
    //         orig: f(self, &node.orig),
    //         cached: node.cached.clone().map(|clos| f(self, &clos)),
    //         kind: node.kind,
    //         bty: node.bty.clone(),
    //         state: node.state,
    //         fwdlinks: node.fwdlinks.clone(),
    //         backlinks: node.backlinks.clone(),
    //     };
    //
    //     // TODO: Should this push the dependencies?
    //
    //     self.add_node(new_node)
    // }

    fn build_cached(&mut self, idx: &mut CacheIndex, rec_env: &[(Ident, CacheIndex)]) {
        let node = self.store.get_mut(*idx).unwrap();

        if node.cached.is_some() {
            return ();
        }

        let mut new_cached = Closure::clone(&node.orig);

        match node.bty {
            BindingType::Normal => (),
            BindingType::Revertible(ref deps) => match deps {
                FieldDeps::Unknown => new_cached.env.extend(rec_env.iter().cloned()),
                FieldDeps::Known(deps) if deps.is_empty() => (),
                FieldDeps::Known(deps) => {
                    let deps = rec_env.iter().filter(|(id, _)| deps.contains(id)).cloned();
                    node.fwdlinks = deps
                        .clone()
                        .map(|(id, idx)| DependencyLink { id, idx })
                        .collect();
                    new_cached.env.extend(deps);
                }
            },
        }

        node.cached = Some(new_cached);
        self.update_backlinks(*idx);
    }

    fn saturate<'a, I: DoubleEndedIterator<Item = &'a Ident> + Clone>(
        &mut self,
        idx: CacheIndex,
        fields: I,
    ) -> RichTerm {
        let node = self.store.get(idx).unwrap();

        let mut deps_filter: Box<dyn FnMut(&&Ident) -> bool> = match node.bty.clone() {
            BindingType::Revertible(FieldDeps::Known(deps)) => {
                Box::new(move |id: &&Ident| deps.contains(id))
            }
            BindingType::Revertible(FieldDeps::Unknown) => Box::new(|_: &&Ident| true),
            BindingType::Normal => Box::new(|_: &&Ident| false),
        };

        let node_as_function = self.add_node(IncCache::revnode_as_explicit_fun(
            node,
            fields.clone().filter(&mut deps_filter),
        ));

        let as_function_closurized = RichTerm::from(Term::Closure(node_as_function));
        let args = fields.filter_map(|id| deps_filter(&id).then(|| RichTerm::from(Term::Var(*id))));

        args.fold(as_function_closurized, |partial_app, arg| {
            RichTerm::from(Term::App(partial_app, arg))
        })
    }
}//! Thunks and associated devices used to implement lazy evaluation.
use super::{BlackholedError, Cache, CacheIndex, Closure};
use crate::{
    eval::value::{self, NickelValue},
    identifier::Ident,
    metrics::increment,
    position::PosIdx,
    term::{BindingType, Term, record::FieldDeps},
};

use std::{
    cell::{Ref, RefCell, RefMut},
    rc::Rc,
};

/// The state of a thunk.
///
/// When created, a thunk is flagged as suspended. When accessed for the first time, a
/// corresponding [ThunkUpdateFrame] is pushed on the stack and the thunk is flagged as
/// black-hole.
///
/// This prevents direct infinite recursions, since if a thunk is re-accessed while still in a
/// black-hole state, we are sure that the evaluation will loop, and we can thus error out before
/// overflowing the stack or looping forever. Finally, once the content of a thunk has been
/// evaluated, the thunk is updated with the new value and flagged as evaluated, so that future
/// accesses won't even push an update frame on the stack.
#[derive(Copy, Clone, Eq, PartialEq, Debug, Default)]
pub enum ThunkState {
    Blackholed,
    #[default]
    Suspended,
    Evaluated,
}

/// The mutable data stored inside a thunk.
#[derive(Clone, Debug, PartialEq)]
pub struct ThunkData {
    inner: InnerThunkData,
    /// The semantic hash of the expression represented by this thunk. Used for incremental
    /// evaluation. Computed from [Self::cui] and the semantic hashes of the this thunk's
    /// dependencies.
    #[cfg(feature = "incremental-experimental")]
    thunk_hash: ThunkHash,
    /// The Cross-evaluation Uniform Identifier. This is a semantic hash of the original expression
    /// of the closure set by the incremental evaluator for thunks of interest. It doesn't take
    /// dependencies into account: the final semantic hash is derived from the CUI and the semantic
    /// hashes of dependencies in the closure's environment.
    #[cfg(feature = "incremental-experimental")]
    cui: Option<crate::eval::semantic_hash::SemanticHash>,
    state: ThunkState,
    /// A flag indicating whether the thunk is locked. See [Thunk::lock].
    locked: bool,
}

/// The part of [ThunkData] responsible for storing the closure itself. It can either be:
///
/// - A standard thunk, that is destructively updated once and for all
/// - A revertible thunk, that can be restored to its original expression. Used to implement
///   recursive merging of records and overriding (see the
///   [RFC overriding](https://github.com/tweag/nickel/pull/330)). A revertible thunk optionally
///   stores the set of recursive fields it depends on (see [`crate::transform::free_vars`]).
///
/// # Revertible thunks
///
/// Recursive records are better understood as being functions. For example, the recursive record:
///
/// ```nickel
/// {
///   foo = bar + baz + 1,
///   bar = 2,
///   baz = 1,
/// }
/// ```
///
/// is really a builtin representation of `fun self => {foo = self.bar + self.baz + 1, bar = 2, baz
/// = 1}`. The interpreter computes a fixpoint when evaluating a `RecRecord` away to a `Record`,
/// equivalent to `let rec fixpoint = repr fixpoint in fixpoint`. We use a different vocabulary and
/// representation, but this is what we essentially do. We're just hiding the details from the
/// user and pretend recursive records are data that can be used as a normal record because it's
/// both simple and natural for the user.
///
/// A naive representation of recursive records could be to store them as actual functions, and
/// re-compute the fixpoint at each record operation, such as a field access. While correct, this
/// would be wasteful, because the result of each fixpoint computation is actually the same
/// throughout most record operations (put differently, `self` doesn't change often). But we can't
/// just compute the fixpoint once, store it in a normal thunk and forget about the original
/// function, because upon merge, and more specifically upon recursive overriding, we do need to
/// compute a new fixpoint from the original function.
///
/// Revertible thunks are a **memoization device** for the functional representation `fun self =>
/// ...` of a recursive record. First, note that there are several different but equivalent ways of
/// encoding the example above as a function:
///
/// ```nickel
/// fun self => { foo = self.bar + self.baz + 1, bar = 2, baz = 1 }
///
/// # pushing the function down the fields
/// {foo = fun self => self.bar + self.baz + 1, bar = fun self => 2, baz = fun self => 1}
///
/// # removing unused arguments
/// {foo = fun self => self.bar + self.baz + 1, bar = 2, baz = 1}
///
/// # splitting the self argument
/// {foo = fun bar baz => bar + baz + 1, bar = 2, bar 1}
/// ```
///
/// All those representations are isomorphic, in that, modulo basic free variable analysis, we can
/// get from one to another mechanically. Pushing the functions down the fields is better because
/// it reveals more static information about the record (such as the list of fields) without having
/// to provide any argument first. Then, splitting `self` and removing the function altogether when
/// the field doesn't depend on other fields is more precise with respect to dependency tracking
/// (this has an important positive memory impact, see [crate::term::record::FieldDeps]).
///
/// In practice, Nickel uses the last representation. Fields that don't have any free variable
/// intersecting with the name of the other fields are allocated as normal thunks that will only be
/// evaluated at most once. Fields with actual dependencies are stored in revertible thunks, where
/// the `orig` field stores the body of the function (in our example the expression `bar + baz +
/// 1`), and the cached version is the application to `self` computed when we evaluated the
/// recursive record to a normal record. The function arguments (that is, the intersection of the
/// free variables of the expression with the set of fields) are stored inside `deps`. `deps`
/// represent the other fields a specific field is depending on, and those names are guaranteed to
/// appear free inside `orig`.
///
/// In fact, unless there is an unbound identifier, `deps` should be exactly the set of free
/// variables of `orig`.
#[derive(Clone, Debug, PartialEq)]
pub enum InnerThunkData {
    Standard(Closure),
    Revertible {
        orig: Rc<Closure>,
        cached: Option<Closure>,
        deps: FieldDeps,
    },
}

const REVTHUNK_NO_CACHED_VALUE_MSG: &str =
    "tried to get data from a revertible thunk without a cached value";

impl ThunkData {
    /// Create new standard thunk data.
    #[inline]
    pub fn new(closure: Closure) -> Self {
        ThunkData {
            inner: InnerThunkData::Standard(closure),
            #[cfg(feature = "incremental-experimental")]
            thunk_hash: ThunkHash::Unknown,
            #[cfg(feature = "incremental-experimental")]
            cui: None,
            state: ThunkState::Suspended,
            locked: false,
        }
    }

    /// Create new revertible thunk data.
    #[inline]
    pub fn new_rev(orig: Closure, deps: FieldDeps) -> Self {
        increment!("Thunk::new_rev");
        ThunkData {
            inner: InnerThunkData::Revertible {
                orig: Rc::new(orig),
                cached: None,
                deps,
            },
            #[cfg(feature = "incremental-experimental")]
            cui: None,
            #[cfg(feature = "incremental-experimental")]
            thunk_hash: ThunkHash::Unknown,
            state: ThunkState::Suspended,
            locked: false,
        }
    }

    /// Initialize the cached value of a revertible thunk, given the recursive environment of the
    /// corresponding record. This function is a no-op on a standard thunk.
    ///
    /// # Invariant
    ///
    /// **This function must be called exactly once** on a revertible thunk, after the initial
    /// construction. It's part of its initialization. Calling it on a revertible thunks a second
    /// time, with a `cached` value which is not set to `None`, will panic.
    ///
    /// Non-revertible thunks are not concerned: this function has no effect on them, even if
    /// called repeatedly.
    ///
    /// This function is similar in spirit to setting the cached value to be the explicit function
    /// application given as built by `saturate`, but applied to arguments taken from `rec_env`.
    /// The major difference is that `init_cached` avoids the creation of the intermediate redex
    /// `(fun id1 .. id n => orig) <closure@1> .. <closure@n>` as well as the intermediate thunks
    /// and terms, because we can compute the application right away, in-place.
    pub fn init_cached(&mut self, rec_env: &[(Ident, Thunk)]) {
        match self.inner {
            InnerThunkData::Standard(_) => (),
            InnerThunkData::Revertible {
                ref mut cached,
                ref orig,
                ref deps,
            } => {
                // `build_cached_value` must be called exactly once on a revertible thunk. This is
                // an invariant that MUST be maintained by the interpreter.
                //
                // `cached` set to `None` solely exists because we need to first allocate all the
                // revertible thunks corresponding to a recursive record, and only then can we
                // patch them (build the cached value) in a second step, but they should be
                // logically seen as one construction operation.
                assert!(
                    cached.is_none(),
                    "tried to build the cached value of a revertible thunk, but was already set"
                );

                let mut new_cached = Closure::clone(orig);

                match deps {
                    FieldDeps::Known(deps) if deps.is_empty() => (),
                    FieldDeps::Known(deps) => new_cached
                        .env
                        .extend(rec_env.iter().filter(|(id, _)| deps.contains(id)).cloned()),
                    FieldDeps::Unknown => new_cached.env.extend(rec_env.iter().cloned()),
                };

                *cached = Some(new_cached);
            }
        }
    }

    /// Revert a thunk and abstract over the provided arguments to get back a function. The result
    /// is returned in a new, non-revertible, thunk.
    ///
    /// Used by [Thunk::saturate]. See the corresponding documentation for more details.
    ///
    /// # Example
    ///
    /// If `orig` is `foo + bar + a` and `args` correspond to `bar, foo`, this functions returns a
    /// standard thunk containing `fun bar foo => foo + bar + a`.
    fn revthunk_as_explicit_fun<I>(self, args: I) -> Self
    where
        I: DoubleEndedIterator<Item = Ident>,
    {
        match self.inner {
            InnerThunkData::Standard(_) => self,
            InnerThunkData::Revertible { orig, .. } => {
                let Closure { value: body, env } =
                    Rc::try_unwrap(orig).unwrap_or_else(|rc| Closure::clone(&rc));

                // Build a list of the arguments that the function will need in the same order as
                // the original iterator. If the identifiers inside `args` are `a`, `b` and `c`, in
                // that order, we want to build `fun a => (fun b => (fun c => body))`. We thus need
                // a reverse fold.
                let as_function = args.rfold(body, |built, id| {
                    NickelValue::from(Term::fun(id.into(), built))
                });

                ThunkData::new(Closure {
                    value: as_function,
                    env,
                })
            }
        }
    }

    /// Return a reference to the closure currently cached.
    pub fn closure(&self) -> &Closure {
        match self.inner {
            InnerThunkData::Standard(ref closure) => closure,
            // Nothing should peek into a revertible thunk before the cached value has been
            // constructed by [`build_cached_value`]. This is an invariant that MUST be maintained
            // by the interpreter.
            //
            // `cached` set to `None` solely exists because we need to first allocate all the
            // revertible thunks corresponding to a recursive record, and only then can we patch
            // them (build the cached value) in a second step. But calling to [`ThunkData::new_rev`]
            // followed by [`ThunkData::build_cached_value`] should be logically seen as just one
            // atomic operation.
            InnerThunkData::Revertible { ref cached, .. } => {
                cached.as_ref().expect(REVTHUNK_NO_CACHED_VALUE_MSG)
            }
        }
    }

    /// Return a reference to the closure currently cached. Return the original expression if this
    /// thunk is a revertible thunk that hasn't been built yet.
    ///
    /// This function is only used for contract equality checking on revertible thunks. In every
    /// other cases, you should use [Self::closure] instead.
    pub(crate) fn closure_or_orig(&self) -> &Closure {
        match self.inner {
            InnerThunkData::Standard(ref closure) => closure,
            InnerThunkData::Revertible {
                ref cached,
                ref orig,
                ..
            } => cached.as_ref().unwrap_or(orig),
        }
    }

    /// Return a mutable reference to the closure currently cached.
    pub fn closure_mut(&mut self) -> &mut Closure {
        match self.inner {
            InnerThunkData::Standard(ref mut closure) => closure,
            InnerThunkData::Revertible {
                ref mut cached,
                ref mut orig,
                ..
            } => cached.as_mut().unwrap_or_else(|| Rc::make_mut(orig)),
        }
    }

    /// Consume the data and return the cached closure.
    pub fn into_closure(self) -> Closure {
        match self.inner {
            InnerThunkData::Standard(closure) => closure,
            // Nothing should access the cached value of a revertible thunk before the cached value
            // has been constructed. This is an invariant that MUST be maintained by the interpreter
            //
            // `cached` set to `None` solely exists because we need to first allocate all the
            // revertible thunks corresponding to a recursive record, and only then can we patch
            // them (build the cached value) in a second step. But calling to [`ThunkData::new_rev`]
            // followed by [`ThunkData::build_cached_value`] should be logically seen as just one
            // construction operation.
            InnerThunkData::Revertible { cached, .. } => {
                cached.expect(REVTHUNK_NO_CACHED_VALUE_MSG)
            }
        }
    }

    /// Update the cached closure.
    pub fn update(&mut self, new: Closure) {
        match self.inner {
            InnerThunkData::Standard(ref mut closure) => *closure = new,
            InnerThunkData::Revertible { ref mut cached, .. } => *cached = Some(new),
        }

        self.state = ThunkState::Evaluated;
    }

    /// Create a freshly unevaluated thunk (minus `ident_type`) from a thunk, reverted to its
    /// original state before the first update. We need to operate at the [Thunk] level here
    /// (instead of [Self]) to avoid allocation in the non revertible case. Indeed, for standard
    /// thunk data, the content is unchanged and shared with the original thunk: in that case,
    /// `ThunkData::revert(thunk)` is the same as `thunk.clone()`.
    ///
    /// For revertible thunk data, the result is independent from the original one. Any update to
    /// one of the thunks doesn't affect the other.
    ///
    /// The new thunk is unlocked, regardless of the locking status of the original thunk.
    pub fn revert(thunk: &Thunk) -> Thunk {
        let thunk_data = thunk.data().borrow();

        match &thunk_data.inner {
            InnerThunkData::Standard(_) => thunk.clone(),
            InnerThunkData::Revertible { orig, deps, .. } => Thunk(NickelValue::thunk(
                ThunkData {
                    inner: InnerThunkData::Revertible {
                        orig: Rc::clone(orig),
                        cached: None,
                        deps: deps.clone(),
                    },
                    #[cfg(feature = "incremental-experimental")]
                    cui: thunk_data.cui,
                    //TODO: what should the hash be here? I suppose it should only be actually
                    //computed when building the cached value.
                    #[cfg(feature = "incremental-experimental")]
                    thunk_hash: ThunkHash::Unknown,
                    state: ThunkState::Suspended,
                    locked: false,
                },
                thunk.0.pos_idx(),
            )),
        }
    }

    /// Return the potential field dependencies stored in a revertible thunk. See
    /// [`crate::transform::free_vars`]
    pub fn deps(&self) -> FieldDeps {
        match self.inner {
            InnerThunkData::Standard(_) => FieldDeps::empty(),
            InnerThunkData::Revertible { ref deps, .. } => deps.clone(),
        }
    }
}

/// A thunk.
///
/// A thunk is a shared suspended computation. It is the primary device for the implementation of
/// lazy evaluation.
///
/// For the implementation of recursive merging, some thunks need to be revertible, in the sense
/// that we must be able to revert to the original expression before update. Those are called
/// revertible thunks. Most expressions don't need revertible thunks as their evaluation will
/// always give the same result, but some others, such as the ones containing recursive references
/// inside a record may be invalidated by merging, and thus need to store the unaltered original
/// expression. Those aspects are handled and discussed in more detail in
/// [InnerThunkData].
///
/// # Representation
///
/// Since the introduction of [crate::eval::value::NickelValue], thunk data are stored inside a
/// value block, like most other values. A pointer to those data is thus precisely a `NickelValue`.
/// [Thunk] is a smart constructor for a value for which we know for sure it contains a thunk
/// (which makes it possible to perform most operations bypassing checks).
#[derive(Clone, Debug, PartialEq)]
// CAUTION: we rely on the fact that `Thunk` has the same layout as `NickelValue` (we transmute
// them freely). It's useful to allow zero-cost conversion between `&NickelValue` and `&Thunk`. Do
// not change the representation of `Thunk` lightly. Doing so without properly adapting the rest of
// the codebase will incur Undefined Behavior.
#[repr(transparent)]
pub struct Thunk(pub(in crate::eval) NickelValue);

impl Thunk {
    /// Create a new standard thunk.
    #[inline]
    pub fn new(closure: Closure, pos_idx: PosIdx) -> Self {
        increment!("Thunk::new");
        Thunk(NickelValue::thunk(ThunkData::new(closure), pos_idx))
    }

    /// Create a new revertible thunk. If the dependencies are empty, this function acts as
    /// [Thunk::new] and create a standard (non-revertible) thunk.
    #[inline]
    pub fn new_rev(closure: Closure, deps: FieldDeps, pos_idx: PosIdx) -> Self {
        match deps {
            FieldDeps::Known(deps) if deps.is_empty() => Self::new(closure, pos_idx),
            deps => Thunk(NickelValue::thunk(
                ThunkData::new_rev(closure, deps),
                pos_idx,
            )),
        }
    }

    /// Returns a reference to the inner `RefCell<ThunkData>`.
    #[inline]
    fn data(&self) -> &RefCell<ThunkData> {
        // Safety: it's an invariant of `Thunk` that the inner `NickelValue` is a block of type
        // thunk.
        unsafe { self.0.as_thunk_data_unchecked() }
    }

    #[inline]
    pub fn state(&self) -> ThunkState {
        self.data().borrow().state
    }

    /// Set the state to evaluated.
    #[inline]
    pub fn set_evaluated(&self) {
        self.data().borrow_mut().state = ThunkState::Evaluated;
    }

    /// Lock a thunk. This flips a dedicated bit in the thunk's state. Returns `true` if the
    /// locking succeeded and the thunk wasn't previous locked, or `false` if the thunk was already
    /// in a locked state.
    ///
    /// Locking is used to prevent infinite loops for some step-by-step variants of deep evaluation
    /// such as `%deep_seq%`, `%force%` or [crate::program::Program::eval_record_spine], where the
    /// normal thunk update workflow isn't adapted.
    #[inline]
    pub fn lock(&self) -> bool {
        let mut data_ref = self.data().borrow_mut();

        if data_ref.locked {
            return false;
        }

        data_ref.locked = true;
        true
    }

    /// Unlock a thunk previously locked (see [Self::lock]). If the thunk wasn't locked, this is a
    /// no-op. Returns `true` if the thunk was previously locked, `false` otherwise.
    #[inline]
    pub fn unlock(&self) -> bool {
        let mut data_ref = self.data().borrow_mut();

        let was_locked = data_ref.locked;
        data_ref.locked = false;

        was_locked
    }

    /// Generate an update frame from this thunk and set the state to `Blackholed`. Return an
    /// error if the thunk was already black-holed.
    pub fn mk_update_frame(&mut self) -> Result<ThunkUpdateFrame, BlackholedError> {
        let mut data_ref = self.data().borrow_mut();

        if data_ref.state == ThunkState::Blackholed {
            return Err(BlackholedError);
        }

        data_ref.state = ThunkState::Blackholed;

        Ok(self.clone())
    }

    /// Immutably borrow the inner closure. Panic if there is another active mutable borrow.
    #[inline]
    pub fn borrow(&self) -> Ref<'_, Closure> {
        Ref::map(self.data().borrow(), ThunkData::closure)
    }

    /// Mutably borrow the inner closure. Panic if there is any other active borrow.
    #[inline]
    pub fn borrow_mut(&mut self) -> RefMut<'_, Closure> {
        RefMut::map(self.data().borrow_mut(), |data| data.closure_mut())
    }

    /// Immutably borrow the original expression stored in a thunk, even if it's a revertible
    /// thunks that hasn't been built yet (in which case the original expression is borrowed).
    /// **Beware**: the resulting closure might thus have unbound variables (recursive references of a
    /// freshly reverted thunks).
    ///
    /// Panic if there is another active mutable borrow.
    ///
    /// In general, no part of the interpreter should observe the intermediate state where a
    /// revertible thunk has been created but hasn't been built yet. Please use [Self::borrow]
    /// instead.
    ///
    /// There is, however, one exception: contract equality checks (needed for contract
    /// deduplication), which happen as part of merging and need to work on freshly reverted thunks
    /// which don't have their new recursive environment yet.
    ///
    /// This method is a leaking abstraction, which isn't very satisfying - in the future, we hope
    /// to have a proper incremental evaluation cache which performs (incremental) memoization, in
    /// which case revertible thunks wouldn't be needed anymore and could be replaced by a plain
    /// function.
    #[inline]
    pub(crate) fn borrow_orig(&self) -> Ref<'_, Closure> {
        Ref::map(self.data().borrow(), ThunkData::closure_or_orig)
    }

    /// Get an owned clone of the inner closure.
    #[inline]
    pub fn get_owned(&self) -> Closure {
        self.data().borrow().closure().clone()
    }

    /// Consume the thunk and return an owned closure. Avoid cloning if this thunk is the only
    /// reference to the inner closure.
    #[inline]
    pub fn into_closure(self) -> Closure {
        // We reuse the code of lenses here, which is precisely what we need
        value::lens::ValueLens::<value::ThunkData>::with_content(
            self.0,
            |inner| inner.into_inner().into_closure(),
            |cell| cell.borrow().closure().clone(),
        )
    }

    /// Create a fresh unevaluated thunk from `self`, reverted to its original state before the
    /// first update. For a standard thunk, the content is unchanged and the state is conserved: in
    /// this case, `revert()` is the same as `clone()`.
    #[inline]
    pub fn revert(&self) -> Self {
        ThunkData::revert(self)
    }

    #[inline]
    pub fn build_cached(&self, rec_env: &[(Ident, Thunk)]) {
        self.data().borrow_mut().init_cached(rec_env)
    }

    /// Revert a thunk, abstract over its dependencies to get back a function, and apply the
    /// resulting function to the given variables. The function part is allocated in a fresh thunk
    /// with the same environment as the original expression.
    ///
    /// Recall that revertible thunks are just a memoization mechanism for function application.
    /// The original expression (`orig`) and the dependencies (`deps`) are a representation of a
    /// function. Most of the time, we don't have to manipulate the explicit function, but just
    /// manipulate the body of the function directly (which is what is stored inside the `orig`
    /// field).
    ///
    /// However, in the general case of merging two record fields which may be both recursive (i.e.
    /// which may contain a revertible thunk), we have to use the explicit function representation
    /// and apply it to variables, which correspond to the fields of the recursive record being
    /// built by merging.
    ///
    /// `saturate`:
    ///
    /// - abstracts the original expression of the underlying revertible thunk, forming a function.
    /// - stores this function in a fresh standard thunk
    /// - returns the application of this function to the provided record field names (as variables)
    ///
    /// Field names are taken as an iterator over identifiers.
    ///
    /// # Parameters
    ///
    /// `fields` is the fields of the resulting recursive record being built by merging. `fields`
    /// is used for two purposes:
    ///
    /// - to impose a fixed order on the arguments of the function. The particular order is not
    ///   important but it must be the same for forming the function and forming the
    ///   application, to avoid a mismatch like `(fun foo bar => ...) bar foo`
    /// - to know what parameters to use for reverting a thunk whose dependencies are unknown.
    ///   In that case, we must be conservative and abstract over all the fields of the
    ///   recursive record, but we can't get this information from `self` alone
    ///
    /// # Standard thunks (non-revertible)
    ///
    /// Non revertible thunks can be seen as a special case of revertible thunks with no
    /// dependencies. Thus the abstraction and application are nullary, and the result is just the
    /// current thunk.
    ///
    /// # Example
    ///
    /// If `orig` is `foo + bar + a` where `foo` and `bar` are thunk dependencies (hence are free
    /// variables) and `a` is bound in the environment. Say the iterator represents the fields `bar,
    /// b, foo` in that order. Then `saturate`:
    ///
    /// - stores `fun bar foo => foo + bar + a` in a fresh (say `thunk1`) thunk with the same environment as `self`
    ///   (in particular, `a` is bound)
    /// - returns the term `<closure@thunk1> bar foo`
    pub fn saturate<I: DoubleEndedIterator<Item = Ident> + Clone>(self, fields: I) -> NickelValue {
        let deps = self.deps();
        let pos_idx = self.0.pos_idx();
        let inner =
            value::lens::ValueLens::<value::ThunkData>::extract_or_clone(self.0).into_inner();

        let mut deps_filter: Box<dyn FnMut(&Ident) -> bool> = match deps {
            FieldDeps::Known(deps) => Box::new(move |id: &Ident| deps.contains(id)),
            FieldDeps::Unknown => Box::new(|_: &Ident| true),
        };

        let thunk_as_function = NickelValue::thunk(
            inner.revthunk_as_explicit_fun(fields.clone().filter(&mut deps_filter)),
            pos_idx,
        );

        let args = fields
            .filter(deps_filter)
            .map(|id| NickelValue::from(Term::Var(id.into())));

        args.fold(thunk_as_function, |partial_app, arg| {
            NickelValue::from(Term::app(partial_app, arg))
        })
    }

    /// Determine if a thunk is worth being put on the stack for future update.
    ///
    /// Typically, expressions in weak head normal form won't evaluate further and their update can
    /// be skipped.
    #[inline]
    pub fn should_update(&self) -> bool {
        !self.borrow().value.is_whnf()
    }

    /// Return a clone of the potential field dependencies stored in a revertible thunk. See
    /// [`crate::transform::free_vars`].
    #[inline]
    pub fn deps(&self) -> FieldDeps {
        self.data().borrow().deps()
    }

    /// Check for physical equality between two thunks. This method is used for fast equality
    /// checking, as if two thunks are physically equal, they must be equal as Nickel values.
    #[inline]
    pub fn ptr_eq(this: &Thunk, that: &Thunk) -> bool {
        NickelValue::phys_eq(&this.0, &that.0)
    }
}

impl From<Thunk> for NickelValue {
    fn from(thunk: Thunk) -> Self {
        thunk.0
    }
}

impl std::fmt::Pointer for Thunk {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Pointer::fmt(&self.0, f)
    }
}

/// A thunk update frame.
///
/// A thunk update frame is put on the stack whenever a variable is entered, such that once this
/// variable is evaluated, the corresponding thunk can be updated. It is currently exactly the same
/// a thunk.
pub type ThunkUpdateFrame = Thunk;

impl ThunkUpdateFrame {
    /// Update the corresponding thunk with a closure. Set the state to `Evaluated`
    #[inline]
    pub fn update(self, closure: Closure) {
        self.data().borrow_mut().update(closure);
    }

    /// Reset the state of the thunk to Suspended
    /// Mainly used to reset the state of the VM between REPL runs
    #[inline]
    pub fn reset_state(&self) {
        self.data().borrow_mut().state = ThunkState::Suspended;
    }
}

#[cfg(feature = "incremental-experimental")]
mod incremental {
    use super::*;
    use crate::eval::semantic_hash::{SemanticHash, semantic_hash};

    /// Possible values of the cached semantic hash stored in the thunk.
    #[derive(Copy, Debug, PartialEq, Eq, Clone)]
    pub enum ThunkHash {
        /// The hash of this thunk can't be computed, and will never be, at least during the current
        /// run.
        ///
        /// This happens for thunks that aren't deemed worth of being versioned by the incremental
        /// evaluator, and aren't simple enough to compute their hash structurally (the hash of
        /// constants is typically always defined). This hash value is contagious: computing the hash
        /// of any (direct or indirect) reverse dependency of this thunk will lead to an undefined hash
        /// as well.
        Undefined,
        /// The hash of this thunk hasn't been computed yet. Note that an [Self::Unknown] hash might
        /// turn to [Self::Undefined] after hashing: it doesn't have to end up as [Self::Known].
        Unknown,
        Known(SemanticHash),
    }

    impl ThunkData {
        /// Compute the semantic hash of a thunk, given the closure stored in it and the
        /// Cross-evaluation Unique Identifier of the corresponding expression.
        pub fn semantic_hash(&mut self) -> Option<SemanticHash> {
            match self.thunk_hash {
                ThunkHash::Undefined => None,
                ThunkHash::Known(content_hash) => Some(content_hash),
                ThunkHash::Unknown => {
                    let computed = semantic_hash(self.closure(), self.cui);
                    self.thunk_hash = computed
                        .map(ThunkHash::Known)
                        .unwrap_or(ThunkHash::Undefined);
                    computed
                }
            }
        }
    }

    impl Thunk {
        /// Set the Cross-evaluation Unique Identifier to this thunk.
        #[inline]
        pub fn set_cui(&self, cui: SemanticHash) {
            self.data().borrow_mut().cui = Some(cui);
        }

        /// Attach a Cross-evaluation Unique Identifier to this thunk.
        #[inline]
        pub fn with_cui(self, cui: SemanticHash) -> Self {
            self.set_cui(cui);
            self
        }

        /// Returns the semantic hash of this thunk. If the hash has been computed before (and thus
        /// stored in `self`), returns it immediately. Otherwise, get the semantic hash of the
        /// dependencies, computes the semantic hash of this thunk using the CUI, and returns the
        /// result. In the latter case, the hash of the (transitive) dependencies are recursively
        /// fetched in the same way (they were either cached from a previous computations, or are
        /// computed on-demand).
        ///
        /// # Return
        ///
        /// Returns `None` if any of the transitive dependencies of this thunk has a hash with
        /// value [ThunkHash::Undefined], or if there is a loop in the dependencies (co-recursive
        /// thunks of interest). It means that for now, we can never cache co-recursive thunks.
        /// There might be a way to handle them properly, but this is left for future work.
        #[inline]
        pub fn semantic_hash(&self) -> Option<SemanticHash> {
            // `semantic_hash` calls to its dependencies' `semantic_hash` recursively, which can
            // cause an infinite loop for co-recursive thunks. We could use locking to prevent
            // that, but there is one issue: we do the recursion while keeping the mutable borrow
            // to the original thunk (and all thunk encountered on the way). By the time we check
            // the lock state, `borrow_mut()` would have already panic.
            //
            // We could organize the code to avoid that (releasing the borrow before recursing).
            // However, we can in fact turn this to our avantage and use `RefCell` itself as a lock
            // mechanism for no additional cost: if there's a loop, `try_borrow_mut` will fail.
            self.data().try_borrow_mut().ok()?.semantic_hash()
        }

        #[inline]
        pub fn cui(&self) -> Option<SemanticHash> {
            self.data().borrow().cui
        }
    }
}

#[cfg(feature = "incremental-experimental")]
pub use incremental::*;

/// Placeholder [Cache] for the call-by-need evaluation strategy.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct CBNCache {}

impl Cache for CBNCache {
    type UpdateIndex = ThunkUpdateFrame;

    #[inline]
    fn get(&self, idx: CacheIndex) -> Closure {
        idx.get_owned()
    }

    fn get_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Option<Self::UpdateIndex>, BlackholedError> {
        // If the thunk is already evaluated, we don't return an update frame.
        if idx.state() == ThunkState::Evaluated {
            return Ok(None);
        }

        // If the thunk isn't worth updating, we set its state to evaluated and we don't create an
        // update frame either. There's one exception: if the thunk is blackholed, we still want to
        // raise an infinite recursion error. This will be handled by `mk_update_frame()` below.
        if !idx.should_update() && idx.state() != ThunkState::Blackholed {
            idx.set_evaluated();
            return Ok(None);
        }

        // Otherwise, we return an update frame.
        Some(idx.mk_update_frame()).transpose()
    }

    fn add(&mut self, clos: Closure, bty: BindingType) -> CacheIndex {
        let pos_idx = clos.value.pos_idx();

        match bty {
            BindingType::Normal => Thunk::new(clos, pos_idx),
            BindingType::Revertible(deps) => Thunk::new_rev(clos, deps, pos_idx),
        }
    }

    #[inline]
    fn patch<F: FnOnce(&mut Closure)>(&mut self, mut idx: CacheIndex, f: F) {
        f(&mut idx.borrow_mut());
    }

    #[inline]
    fn get_then<T, F: FnOnce(&Closure) -> T>(&self, idx: CacheIndex, f: F) -> T {
        f(&idx.borrow())
    }

    #[inline]
    fn update(&mut self, clos: Closure, uidx: Self::UpdateIndex) {
        uidx.update(clos);
    }

    #[inline]
    fn new() -> Self {
        CBNCache {}
    }

    #[inline]
    fn reset_index_state(&mut self, idx: &mut Self::UpdateIndex) {
        idx.reset_state();
    }

    #[inline]
    fn build_cached(&mut self, idx: &mut CacheIndex, rec_env: &[(Ident, CacheIndex)]) {
        idx.build_cached(rec_env)
    }

    #[inline]
    fn saturate<'a, I: DoubleEndedIterator<Item = Ident> + Clone>(
        &mut self,
        idx: CacheIndex,
        fields: I,
    ) -> NickelValue {
        idx.saturate(fields)
    }

    #[inline]
    fn deps(&self, idx: &CacheIndex) -> Option<FieldDeps> {
        Some(idx.deps())
    }

    #[inline]
    fn revert(&mut self, idx: &CacheIndex) -> CacheIndex {
        idx.revert()
    }

    #[inline]
    fn make_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Self::UpdateIndex, BlackholedError> {
        idx.mk_update_frame()
    }
}/// The Nickel generic evaluation cache. This module abstracts away the details for managing
/// suspended computations and their memoization strategies.
///
/// Terminology:
/// An *element* of the cache is what is stored inside of it.
/// An *index* into the cache points to a given element.
use super::{Closure, value::NickelValue};
use crate::{
    identifier::Ident,
    term::{BindingType, record::FieldDeps},
};

#[cfg(feature = "incremental-experimental")]
pub mod incremental_ng;
pub mod lazy;

/// An index to a specific item stored in the cache
pub type CacheIndex = lazy::Thunk;

/// The current Cache implementation
#[cfg(not(feature = "incremental-experimental"))]
pub type CacheImpl = lazy::CBNCache;
#[cfg(feature = "incremental-experimental")]
pub type CacheImpl = incremental_ng::IncrementalCache;

/// A black-holed node was accessed, which would lead to infinite recursion.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BlackholedError;

pub trait Cache: Clone {
    /// Temporary: as of now we only need this for [lazy::CBNCache].
    type UpdateIndex;

    /// Gets the [Closure] from the element at index `idx`.
    fn get(&self, idx: CacheIndex) -> Closure;

    /// Checks whether the element at index `idx` is blackholed and returns a
    /// [BlackholedError] if it is. Otherwise, returns `Some(idx)` if the element
    /// needs to be updated, returns `None` if not.
    /// Should use [Cache::make_update_index].
    fn get_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Option<Self::UpdateIndex>, BlackholedError>;

    /// Adds an element into the [Cache] and returns its index.
    fn add(&mut self, clos: Closure, bty: BindingType) -> CacheIndex;

    /// Applies `f` to the [Closure] stored inside the element at index `idx`.
    fn patch<F: Fn(&mut Closure)>(&mut self, idx: CacheIndex, f: F);

    /// Clones the [Closure] from the element at index `idx` and applies `f` to it.
    fn get_then<T, F: FnOnce(&Closure) -> T>(&self, idx: CacheIndex, f: F) -> T;

    /// Updates the [Closure] from the element at index `idx` with `clos`.
    fn update(&mut self, clos: Closure, idx: Self::UpdateIndex);

    /// Initializes a new [Cache].
    fn new() -> Self;

    /// Resets the state of the element at index `idx` to `Suspended`
    fn reset_index_state(&mut self, idx: &mut Self::UpdateIndex);

    /// Initializes the cached value of the element at index `idx` with the given `rec_env`.
    fn build_cached(&mut self, idx: &mut CacheIndex, rec_env: &[(Ident, CacheIndex)]);

    /// Revert the element at index `idx`, abstract over its dependencies to get back a function,
    /// and apply the function to the given variables. The function part is allocated in a new
    /// cache entry, stored as a generated variable, with the same environment as the original
    /// expression.
    fn saturate<I: DoubleEndedIterator<Item = Ident> + Clone>(
        &mut self,
        idx: CacheIndex,
        fields: I,
    ) -> NickelValue;

    /// Reverts the element stored at index `idx` to its original value.
    fn revert(&mut self, idx: &CacheIndex) -> CacheIndex;

    /// Returns the dependencies of the element stored at index `idx`, if it has any.
    fn deps(&self, idx: &CacheIndex) -> Option<FieldDeps>;

    /// Checks whether the element at index `idx` is blackholed and returns a
    /// [BlackholedError] if it is. Otherwise, returns `idx`.
    fn make_update_index(
        &mut self,
        idx: &mut CacheIndex,
    ) -> Result<Self::UpdateIndex, BlackholedError>;

    /// Attach a [CUI][crate::eval::semantic_hash] to the given index, thereby marking it as being
    /// of interest for incremental evaluation.
    ///
    /// The default implementation does nothing, which is the behavior for caches that don't
    /// support incremental evaluation, such as the default CBN cache. In practice we never expect
    /// to actually call [Self::attach_cui] on such caches: a VM with incremental evaluation
    /// enabled should always use a cache that supports incremental evaluation, but we
    /// still need to have this method in the general cache interface.
    #[cfg(feature = "incremental-experimental")]
    fn attach_cui(&mut self, _idx: &CacheIndex, _cui: crate::eval::semantic_hash::SemanticHash) {}
}//! Lenses are a way to lazily and conditionally extract owned data from a Nickel value.
use super::{
    Container, InlineValue, NickelValue, TermData, ValueBlockData, ValueBlockHeader, ValueBlockRc,
};

use crate::{
    error::{EvalErrorKind, ParseError},
    eval::cache::lazy::Thunk,
    files::FileId,
    identifier::LocIdent,
    metrics::increment,
    term::{
        AnnotatedData, AppData, FunData, Import, LetData, Op1Data, Op2Data, OpNData, RecRecordData,
        SealedData, StrChunk, Term,
    },
};

use std::{alloc::dealloc, mem::ManuallyDrop, ptr};

/// A lazy handle to part or all of the content of a Nickel value, making it possible to
/// conditionally take owned data out. If the value is unique (1-ref counted), the data is directly
/// moved out and the corresponding block is consumed. Otherwise, the content is cloned, similarly
/// to [std::rc::Rc::unwrap_or_clone].
///
/// [Self] can either be consumed using `take()`, returning the owned content of the data, or
/// reverted back to the original value using `restore()`. When the structure of the lens isn't
/// enough to check if the content should be taken or not, [Self] also provides [Self::peek] which
/// returns a reference to the inner value, so that it can be examined arbitrarily.
///
/// See also [super::ValueContent].
pub struct ValueLens<T> {
    value: NickelValue,
    /// An extractor for the data `T` to take out from the value block.
    lens: fn(NickelValue) -> T,
}

impl<T> ValueLens<T> {
    /// Do not access the content and restore the original value unchanged.
    #[inline]
    pub fn restore(self) -> NickelValue {
        self.value
    }

    /// Peeks at the underlying value, without consuming the lens.
    #[inline]
    pub fn value(&self) -> &NickelValue {
        &self.value
    }

    /// Consumes the value and return the content of the block. If the block is unique, it is
    /// consumed. If the block is shared, the content is cloned. [Self::take] behaves very much
    /// like [std::rc::Rc::unwrap_or_clone].
    #[inline]
    pub fn take(self) -> T {
        (self.lens)(self.value)
    }
}

impl<T: ValueBlockData + Clone> ValueLens<Container<T>> {
    /// Create a new lens extracting either an inlined empty container or an allocated container
    /// data from a value.
    ///
    /// # Safety
    ///
    /// `value` must either be an inlined empty container (matching `T`) or a value block with tag
    /// `T::TAG`.
    pub(super) unsafe fn container_lens(value: NickelValue) -> Self {
        ValueLens {
            value,
            lens: |v| {
                // The precondition ensures that if `v` is inline, it is the corresponding empty
                // container.
                if v.is_inline() {
                    Container::Empty
                } else {
                    Container::Alloc(ValueLens::<T>::extract_or_clone(v))
                }
            },
        }
    }
}

impl<T: ValueBlockData + Clone> ValueLens<T> {
    /// Create a new lens extracting data of type `T` from a value.
    ///
    /// # Safety
    ///
    /// `value` must be a value block with tag [T::TAG].
    #[inline]
    pub(super) unsafe fn content_lens(value: NickelValue) -> Self {
        ValueLens {
            value,
            lens: Self::extract_or_clone,
        }
    }

    /// Custom extractor for a value block. If the reference is 1-counted, the content is extracted
    /// and the first closure is called with an owned value. Otherwise, the second closure is
    /// called with a reference to the content. This makes it possible to finer things than the
    /// blunt clone of [Self::extract_or_clone], such as avoiding cloning the outer `Box` wrapper
    /// of some `Term` variants when the data is shared.
    pub(in crate::eval) fn with_content<F, G, R>(value: NickelValue, on_owned: F, on_ref: G) -> R
    where
        F: FnOnce(T) -> R,
        G: FnOnce(&T) -> R,
    {
        // Safety: the fields of `ValueLens` are private, so it can only be constructed from within
        // this module. We maintain the invariant that if `with_content` is used as a lens for
        // a `ValueLens` object, then `T : ValueBlockData` and `self.value` is a value block whose
        // tag matches `T::TAG`, so `self.value.data` is a valid pointer to a `ValueBlockHeader`
        // followed by a `U` at the right offset.
        unsafe {
            let ptr = value.data;
            let ref_count = ptr.cast::<ValueBlockHeader>().as_ref().ref_count();
            let ptr_content = ptr.add(ValueBlockRc::data_offset::<T>()).cast::<T>();

            if ref_count == 1 {
                increment!("value::lens::take::no clone");
                // Since we "move" the original content, we don't want to run the destructor (if
                // `T` owns e.g. a `HashMap`, it would otherwise be de-allocated when `value` goes
                // out of scope, and we would return a dangling value).
                let _ = ManuallyDrop::new(value);

                // Safety: the content of a NickelValue with `T::TAG` should always be valid for
                // `T`
                let content = ptr::read(ptr_content.as_ptr());

                // While we don't want the destructor to run, we do want to clean up the original
                // allocation.
                dealloc(ptr.as_ptr(), T::TAG.block_layout());
                on_owned(content)
            } else {
                increment!("value::lens::take::clone");
                on_ref(ptr_content.as_ref())
            }
        }
    }

    /// Standard extractor for a value block.
    #[inline]
    pub(in crate::eval) fn extract_or_clone(value: NickelValue) -> T {
        Self::with_content(value, |v| v, |data| data.clone())
    }
}

impl ValueLens<()> {
    /// Creates a new lens extracting a null from a value.
    #[inline]
    pub(super) fn null_lens(value: NickelValue) -> Self {
        Self {
            value,
            lens: |_| (),
        }
    }
}

impl ValueLens<bool> {
    /// Creates a new lens extracting a bool from a value.
    ///
    /// # Safety
    ///
    /// `value.tag()` must be [super::ValueTag::Inline]
    ///
    /// # Panic
    ///
    /// Extraction through [ValueLens::take] will panic if the inline value is neither
    /// [super::InlineValue::True] nor [super::InlineValue::False].
    #[inline]
    pub(super) unsafe fn bool_lens(value: NickelValue) -> Self {
        Self {
            value,
            lens: Self::bool_extractor,
        }
    }

    /// Extractor for a bool value.
    fn bool_extractor(value: NickelValue) -> bool {
        // Safety: we maintain the invariant throughout this module that if `T = InlineValue`, then
        // `self.value` must be an inline value.
        match unsafe { value.as_inline_unchecked() } {
            InlineValue::True => true,
            InlineValue::False => false,
            _ => panic!("unexpected non-boolean inline value in the extractor of ValueLens<bool>"),
        }
    }
}

impl ValueLens<Thunk> {
    /// Creates a new lens extracting a thunk from a value.
    ///
    /// # Safety
    ///
    /// `value.tag()` must be [super::DataTag::Thunk]
    pub(super) unsafe fn thunk_lens(value: NickelValue) -> Self {
        Self {
            value,
            lens: Self::thunk_extractor,
        }
    }

    /// Extractor for a bool value.
    fn thunk_extractor(value: NickelValue) -> Thunk {
        // Safety: we maintain the invariant throughout this module that if `T = Thunk`, then
        // `self.value` must be a thunk.
        unsafe { value.into_thunk_unchecked() }
    }
}

/// Counterpart of [super::ValueContent] for [crate::term::Term] representing the inner term stored in a block
/// value. This makes it possible to conditionally take data out depending not only on the type of
/// the block, but on the specific constructor of the term inside that block as well.
///
/// This is the same type as [crate::term::Term] but where all the enum variant arguments have been
/// wrapped in a lens.
pub enum TermContent {
    StrChunks(ValueLens<Vec<StrChunk<NickelValue>>>),
    Fun(ValueLens<FunData>),
    Let(ValueLens<Box<LetData>>),
    App(ValueLens<AppData>),
    Var(ValueLens<LocIdent>),
    RecRecord(ValueLens<Box<RecRecordData>>),
    Closurize(ValueLens<NickelValue>),
    Op1(ValueLens<Op1Data>),
    Op2(ValueLens<Op2Data>),
    OpN(ValueLens<OpNData>),
    Sealed(ValueLens<SealedData>),
    Annotated(ValueLens<AnnotatedData>),
    Import(ValueLens<Import>),
    ResolvedImport(ValueLens<FileId>),
    ParseError(ValueLens<Box<ParseError>>),
    RuntimeError(ValueLens<Box<EvalErrorKind>>),
}

impl TermContent {
    /// Do not access the content and restore the original value unchanged.
    pub fn restore(self) -> NickelValue {
        match self {
            TermContent::StrChunks(lens) => lens.restore(),
            TermContent::Fun(lens) => lens.restore(),
            TermContent::Let(lens) => lens.restore(),
            TermContent::App(lens) => lens.restore(),
            TermContent::Var(lens) => lens.restore(),
            TermContent::RecRecord(lens) => lens.restore(),
            TermContent::Closurize(lens) => lens.restore(),
            TermContent::Op1(lens) => lens.restore(),
            TermContent::Op2(lens) => lens.restore(),
            TermContent::OpN(lens) => lens.restore(),
            TermContent::Sealed(lens) => lens.restore(),
            TermContent::Annotated(lens) => lens.restore(),
            TermContent::Import(lens) => lens.restore(),
            TermContent::ResolvedImport(lens) => lens.restore(),
            TermContent::ParseError(lens) => lens.restore(),
            TermContent::RuntimeError(lens) => lens.restore(),
        }
    }

    /// Returns a reference to the inner term. This can be useful to perform more elaborate pattern
    /// matching before deciding to take data out.
    pub fn term(&self) -> &Term {
        let value = match self {
            TermContent::StrChunks(lens) => &lens.value,
            TermContent::Fun(lens) => &lens.value,
            TermContent::Let(lens) => &lens.value,
            TermContent::App(lens) => &lens.value,
            TermContent::Var(lens) => &lens.value,
            TermContent::RecRecord(lens) => &lens.value,
            TermContent::Closurize(lens) => &lens.value,
            TermContent::Op1(lens) => &lens.value,
            TermContent::Op2(lens) => &lens.value,
            TermContent::OpN(lens) => &lens.value,
            TermContent::Sealed(lens) => &lens.value,
            TermContent::Annotated(lens) => &lens.value,
            TermContent::Import(lens) => &lens.value,
            TermContent::ResolvedImport(lens) => &lens.value,
            TermContent::ParseError(lens) => &lens.value,
            TermContent::RuntimeError(lens) => &lens.value,
        };

        // unwrap(): if the lens is a TermContent, then the underlying value must be a term block.
        value.as_term().unwrap()
    }

    /// Unconditionally take the inner `Term` out, ignoring the actual shape of the content.
    pub fn take(self) -> Term {
        let value = match self {
            TermContent::StrChunks(lens) => lens.value,
            TermContent::Fun(lens) => lens.value,
            TermContent::Let(lens) => lens.value,
            TermContent::App(lens) => lens.value,
            TermContent::Var(lens) => lens.value,
            TermContent::RecRecord(lens) => lens.value,
            TermContent::Closurize(lens) => lens.value,
            TermContent::Op1(lens) => lens.value,
            TermContent::Op2(lens) => lens.value,
            TermContent::OpN(lens) => lens.value,
            TermContent::Sealed(lens) => lens.value,
            TermContent::Annotated(lens) => lens.value,
            TermContent::Import(lens) => lens.value,
            TermContent::ResolvedImport(lens) => lens.value,
            TermContent::ParseError(lens) => lens.value,
            TermContent::RuntimeError(lens) => lens.value,
        };

        // Safety: since the value was extracted from `TermContent`, it must be a value block with a
        // term inside.
        unsafe { ValueLens::<TermData>::content_lens(value).take() }
    }
}

/// Generates a lens implementation with a constructor and an extractor for a given [Term]
/// constructor and the corresponding type of its payload.
///
/// # Arguments
///
/// - `$lens_cons`: the name of the constructor
/// - `$lens_extrct`: the  name of the extractor
/// - `$term_cons`: the corresponding variant of [Term]
/// - `$type`: the type of the argument of `$term_cons`
///
/// # Safety
///
/// The generated lens constructor is unsafe. The safety rule for the constructor is specified in
/// the function documentation within the macro definition just below.
macro_rules! impl_term_lens {
    ( $lens_cons:ident, $lens_extrct:ident, $term_cons:ident, $type:ty ) => {
        impl ValueLens<$type> {
            // Creates a new lens extracting `Term::$term_cons`.
            //
            // # Safety
            //
            // `value` must be a value block with tag `DataTag::Term`.
            //
            // # Panics
            //
            // Panics if the inner term doesn't match `Term::$term_cons`.
            pub(super) unsafe fn $lens_cons(value: NickelValue) -> Self {
                Self {
                    value,
                    lens: Self::$lens_extrct,
                }
            }

            // Extractor for `Term::$term_cons`.
            fn $lens_extrct(value: NickelValue) -> $type {
                if let Term::$term_cons(data) = ValueLens::<TermData>::extract_or_clone(value) {
                    data
                } else {
                    unreachable!()
                }
            }

            /// Peeks at the underlying term data without taking ownership.
            pub fn peek(&self) -> &$type {
                if let Some(Term::$term_cons(data)) = self.value.as_term() {
                    data
                } else {
                    unreachable!()
                }
            }
        }
    };
}

/// Same as `impl_term_lens!`, but specialized for terms with boxed payload, where the reference
/// and the extraction code are different. In particular, we try to avoid allocating a new [Box]
/// when copying non-1RC content (in practice, we always want to move the result on the stack).
macro_rules! impl_term_boxed_lens {
    ( $lens_cons:ident, $lens_extrct:ident, $term_cons:ident, $type:ty ) => {
        impl ValueLens<Box<$type>> {
            // Creates a new lens extracting `Term::$term_cons`.
            //
            // # Safety
            //
            // `value` must be a value block with tag `DataTag::Term`, and the inner term must
            // match `Term::$term_cons`.
            #[inline]
            pub(super) unsafe fn $lens_cons(value: NickelValue) -> Self {
                Self {
                    value,
                    lens: Self::$lens_extrct,
                }
            }

            // Extractor for `Term::$term_cons`.
            fn $lens_extrct(value: NickelValue) -> Box<$type> {
                if let Term::$term_cons(data) = ValueLens::<TermData>::extract_or_clone(value) {
                    data
                } else {
                    unreachable!()
                }
            }

            /// Variant of `take()` for boxed term data that returns the data unboxed. When the
            /// value is shared, [Self::take_unboxed] avoids cloning the outer box and directly
            /// clones the inner data instead. If you're going to move out of the box anyway,
            /// prefer this variant, which should avoid an ephemeral heap-allocation.
            pub fn take_unboxed(self) -> $type {
                ValueLens::<TermData>::with_content(
                    self.value,
                    |owned| {
                        if let Term::$term_cons(data) = owned {
                            *data
                        } else {
                            unreachable!()
                        }
                    },
                    |as_ref| {
                        if let Term::$term_cons(data) = as_ref {
                            (**data).clone()
                        } else {
                            unreachable!()
                        }
                    },
                )
            }

            /// Returns a reference to the inner term data without taking ownership.
            pub fn peek(&self) -> &$type {
                if let Some(Term::$term_cons(data)) = self.value.as_term() {
                    &**data
                } else {
                    unreachable!()
                }
            }
        }
    };
}

impl_term_lens!(
    term_closurize_lens,
    term_closurize_extractor,
    Closurize,
    NickelValue
);

impl_term_lens!(
    term_str_chunks_lens,
    term_str_chunks_extractor,
    StrChunks,
    Vec<StrChunk<NickelValue>>
);

impl_term_lens!(term_fun_lens, term_fun_extractor, Fun, FunData);

impl_term_boxed_lens!(term_let_lens, term_let_extractor, Let, LetData);

impl_term_lens!(term_app_lens, term_app_extractor, App, AppData);

impl_term_lens!(term_var_lens, term_var_extractor, Var, LocIdent);

impl_term_boxed_lens!(
    term_rec_record_lens,
    term_rec_record_extractor,
    RecRecord,
    RecRecordData
);

impl_term_lens!(term_op1_lens, term_op1_extractor, Op1, Op1Data);

impl_term_lens!(term_op2_lens, term_op2_extractor, Op2, Op2Data);

impl_term_lens!(term_opn_lens, term_opn_extractor, OpN, OpNData);

impl_term_lens!(term_sealed_lens, term_sealed_extractor, Sealed, SealedData);

impl_term_lens!(
    term_annotated_lens,
    term_annotated_extractor,
    Annotated,
    AnnotatedData
);

impl_term_lens!(term_import_lens, term_import_extractor, Import, Import);

impl_term_lens!(
    term_resolved_import_lens,
    term_resolved_import_extractor,
    ResolvedImport,
    FileId
);

impl_term_lens!(
    term_parse_error_lens,
    term_parse_error_extractor,
    ParseError,
    Box<ParseError>
);

impl_term_lens!(
    term_runtime_error_lens,
    term_runtime_error_extractor,
    RuntimeError,
    Box<EvalErrorKind>
);//! Runtime representation of Nickel values.
//!
//! This module implements a custom memory layout for a memory-efficient representation of Nickel
//! values. See
//! [RFC007](https://github.com/tweag/nickel/blob/master/rfcs/007-bytecode-interpreter.md) for more
//! details.
use crate::{
    identifier::LocIdent,
    impl_display_from_pretty,
    label::Label,
    metrics::increment,
    position::{PosIdx, PosTable, TermPos},
    term::{
        ForeignIdPayload, IndexMap, Number, RecordOpKind, RuntimeContract, SealingKey, Term,
        record::Field, string::NickelString,
    },
    traverse::{Traverse, TraverseControl, TraverseOrder},
    typ::Type,
};

use malachite::base::num::conversion::traits::ToSci as _;
use nickel_lang_vector::Slice;
use std::{
    alloc::{Layout, alloc, dealloc},
    borrow::ToOwned,
    cell::{Cell, RefCell},
    convert::Infallible,
    fmt,
    mem::{ManuallyDrop, size_of, transmute},
    num::NonZero,
    ptr::{self, NonNull},
};

pub use super::cache::lazy::{self, Thunk};
pub use crate::term::record::RecordData;

pub mod lens;

/// A Nickel array.
pub type Array = Slice<NickelValue, 32>;

/// A mismatch between an expected tag and the tag found during the decoding process of a value.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct TagMismatchError;

/// The unified representation of Nickel values.
///
/// A tagged pointer to a [reference-counted Nickel value block][ValueBlockRc], or an inline value.
/// The two least significant bits of the pointer are used as the tag. See [ValueTag] for more
/// details.
#[derive(Eq)]
pub struct NickelValue {
    // According to [Strict provenance
    // rules](https://doc.rust-lang.org/std/ptr/index.html#using-strict-provenance), as `data` can
    // contain a pointer and thus require provenance information, it must either be itself a
    // pointer, or we have to keep another pointer around that carries this information (which we
    // surely don't want to do). On the other hand, according to the official documentation of
    // `std::ptr`:
    //
    // > In general, it is always sound for an integer to pretend to be a pointer “for fun” as long
    // > as you don’t use operations on it which require it to be valid (non-zero-sized offset,
    // > read, write, etc).
    //
    // Thus, since `data` can represent either a integer (inline value) that can masquerade as a
    // pointer or an actual pointer with provenance requirements, we always represent it as a
    // pointer.
    //
    // Additionally, since pointers to value blocks are always initialized (and in particular
    // non-null), and the tag for non-pointers values is non-zero, `data` is never zero. We use
    // `NonNull`, which saves some null checks and enables layout optimizations.
    data: NonNull<u8>,
    // On 64-bits pointer-width archs, we can fit everything into one word. Otherwise, we stay safe
    // and use a separate field for the position index of inline values.
    #[cfg(not(target_pointer_width = "64"))]
    pos_idx: PosIdx,
}

// PartialEq is mostly used for tests, when it's handy to compare something to an expected result.
// Most of the instances aren't really meaningful to use outside of very simple cases, and you
// should avoid comparing terms directly.
impl PartialEq for NickelValue {
    fn eq(&self, other: &Self) -> bool {
        match (self.content_ref(), other.content_ref()) {
            (ValueContentRef::Null, ValueContentRef::Null) => true,
            (ValueContentRef::Bool(b1), ValueContentRef::Bool(b2)) => b1 == b2,

            (ValueContentRef::Number(number1), ValueContentRef::Number(number2)) => {
                number1 == number2
            }
            (ValueContentRef::Array(array1), ValueContentRef::Array(array2)) => array1 == array2,
            (ValueContentRef::Record(record1), ValueContentRef::Record(record2)) => {
                record1 == record2
            }
            (ValueContentRef::String(string1), ValueContentRef::String(string2)) => {
                string1 == string2
            }
            (ValueContentRef::Thunk(thunk1), ValueContentRef::Thunk(thunk2)) => {
                *thunk1.borrow() == *thunk2.borrow()
            }
            (ValueContentRef::Term(term1), ValueContentRef::Term(term2)) => term1 == term2,
            (ValueContentRef::Label(label1), ValueContentRef::Label(label2)) => label1 == label2,
            (
                ValueContentRef::EnumVariant(enum_variant1),
                ValueContentRef::EnumVariant(enum_variant2),
            ) => enum_variant1 == enum_variant2,
            (ValueContentRef::ForeignId(foreign_id1), ValueContentRef::ForeignId(foreign_id2)) => {
                foreign_id1 == foreign_id2
            }
            (
                ValueContentRef::SealingKey(sealing_key1),
                ValueContentRef::SealingKey(sealing_key2),
            ) => sealing_key1 == sealing_key2,
            (
                ValueContentRef::CustomContract(custom_contract1),
                ValueContentRef::CustomContract(custom_contract2),
            ) => custom_contract1 == custom_contract2,
            (ValueContentRef::Type(type1), ValueContentRef::Type(type2)) => type1 == type2,
            _ => false,
        }
    }
}

impl fmt::Debug for NickelValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "NickelValue {{ pos_idx: {:?}, data: ", self.pos_idx())?;

        match self.content_ref() {
            ValueContentRef::Null => write!(f, "InlineValue(null)"),
            ValueContentRef::Bool(b) => write!(f, "InlineValue({b})"),
            ValueContentRef::Number(number) => write!(f, "Number({number})"),
            ValueContentRef::Array(container) => write!(f, "Array({container:?})"),
            ValueContentRef::Record(container) => write!(f, "Record({container:?})"),
            ValueContentRef::String(string) => write!(f, "String({string})"),
            ValueContentRef::Thunk(thunk) => write!(f, "Thunk({:?})", thunk.borrow()),
            ValueContentRef::Term(term) => write!(f, "Term({term:?})"),
            ValueContentRef::Label(label) => write!(f, "Label({label:?})"),
            ValueContentRef::EnumVariant(enum_variant_data) => {
                write!(f, "EnumVariant({enum_variant_data:?})")
            }
            ValueContentRef::ForeignId(foreign_id) => {
                write!(f, "ForeignId({foreign_id:?})")
            }
            ValueContentRef::SealingKey(sealing_key) => {
                write!(f, "SealingKey({sealing_key:?})")
            }
            ValueContentRef::CustomContract(custom_contract) => {
                write!(f, "CustomContract({custom_contract:?})")
            }
            ValueContentRef::Type(type_data) => write!(f, "Type({type_data:?})"),
        }?;

        write!(f, "}}")
    }
}

impl std::fmt::Pointer for NickelValue {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.is_inline() {
            write!(f, "<inline>")
        } else {
            std::fmt::Pointer::fmt(&self.data, f)
        }
    }
}

// pointer-width-specific implementation
#[cfg(target_pointer_width = "64")]
impl NickelValue {
    /// The mask for the position index bits in an inline value.
    const INLINE_POS_IDX_MASK: usize = 0xFF_FF_FF_FF_00_00_00_00;

    /// Returns `self` with the inline position index set to `idx` if `self` is an inline value, or
    /// returns `self` unchanged otherwise.
    fn with_inline_pos_idx(mut self, idx: PosIdx) -> Self {
        if self.tag() == ValueTag::Inline {
            unsafe {
                self.data = self.data.map_addr(|data| {
                    // Safety: the lower part of the data an inline value is non-zero, and is
                    // preserved by the LHS of the bitwise or.
                    NonZero::new_unchecked(
                        (usize::from(data) & !Self::INLINE_POS_IDX_MASK) | (usize::from(idx) << 32),
                    )
                });
            }
        }
        self
    }

    /// Returns the position index of `self` if it is an inline value, or `None` otherwise.
    #[inline]
    fn inline_pos_idx(&self) -> Option<PosIdx> {
        (self.tag() == ValueTag::Inline).then(|| {
            PosIdx::from_usize_truncate((self.as_usize() & Self::INLINE_POS_IDX_MASK) >> 32)
        })
    }

    /// Creates a new inline value with an associated position index.
    #[inline]
    pub const fn inline(inline: InlineValue, idx: PosIdx) -> Self {
        NickelValue {
            // Safety: inline values are tagged, the `Inline` tag is non-zero and smaller than 4,
            // so the result of the bitwise or operation is non-zero.
            data: NonNull::without_provenance(unsafe {
                NonZero::new_unchecked(inline as usize | (idx.to_usize() << 32))
            }),
        }
    }

    /// Converts `self` to an inline value bypassing any safety checks.
    ///
    /// # Safety
    ///
    /// `self` must hold a valid inline value.
    #[inline]
    pub unsafe fn as_inline_unchecked(&self) -> InlineValue {
        // Safety: `InlineValue` is `#[repr(usize)]`, ensuring that it has the same layout as
        // `self.0`. The precondition of the function ensures that `self.0` is a valid value for
        // [InlineValue].
        //
        // Since `!Self::inline_pos_idx_MASK` is `FF_FF_FF_FF`, `AND`ing `self.data` with this mask
        // ensures that the result fit in a u32, so we can use `as` fearlessly.
        unsafe {
            transmute::<u32, InlineValue>((self.as_usize() & !Self::INLINE_POS_IDX_MASK) as u32)
        }
    }

    /// Makes a raw byte-to-byte copy of another Nickel value, entirely ignoring reference counting
    /// operations.
    ///
    /// # Safety
    ///
    /// - the ref count of the value block must be adjusted manually to compensate for dropping `self`. Possible solutions are:
    ///   - manually increment the reference count
    ///   - prevent `other` from being dropped (e.g. using [std::mem::ManuallyDrop])
    ///   - prevent `self` from being dropped
    #[inline]
    unsafe fn raw_copy(other: &Self) -> Self {
        NickelValue { data: other.data }
    }

    /// Create a Nickel value from a raw pointer to a value block.
    ///
    /// # Safety
    ///
    /// - `ptr` must be a valid pointer to a [ValueBlockRc].
    /// - the ref count of the value block must be adjusted manually to compensate for dropping `self`. Possible solutions are:
    ///   - manually increment the reference count
    ///   - prevent the original block or value of `ptr` from being dropped (e.g. using
    ///     [std::mem::ManuallyDrop])
    #[inline]
    unsafe fn block(data: NonNull<u8>) -> Self {
        NickelValue { data }
    }
}

// pointer-width-specific implementation
#[cfg(not(target_pointer_width = "64"))]
impl NickelValue {
    /// Returns `self` with the position index set to `idx` if `self` is an inline value, or
    /// returns `self` unchanged otherwise.
    #[inline]
    fn with_inline_pos_idx(mut self, idx: PosIdx) -> Self {
        // Although the inline position index is just dead data for value blocks on non-64 bits
        // architecture, we unconditionally update it to avoid branching
        self.pos_idx = idx;
        self
    }

    /// Returns the inline position index of `self` if it's an inline value, or `None` otherwise.
    fn inline_pos_idx(&self) -> Option<PosIdx> {
        if self.tag() == ValueTag::Inline {
            Some(self.pos_idx)
        } else {
            None
        }
    }

    /// Creates a new inline value.
    #[inline]
    pub const fn inline(inline: InlineValue, pos_idx: PosIdx) -> Self {
        NickelValue {
            // Safety: inline values are guaranteed to be tagged with a 1 bit, and thus are never
            // zero.
            data: unsafe { NonNull::without_provenance(NonZero::new_unchecked(inline as usize)) },
            pos_idx,
        }
    }

    /// Converts the inner value of `self` to an inline value bypassing any safety checks.
    ///
    /// # Safety
    ///
    /// `self` must hold a valid inline value.
    #[inline]
    pub unsafe fn as_inline_unchecked(&self) -> InlineValue {
        // Safety: `InlineValue` is `#[repr(usize)]`, ensuring that it has the same layout as
        // `self.0`. The precondition of the function ensures that `self.0` is a valid value for
        // [InlineValue].
        unsafe { transmute::<usize, InlineValue>(self.as_usize()) }
    }

    /// Makes a raw byte-to-byte copy of another Nickel value, entirely ignoring reference counting
    /// operations.
    ///
    /// # Safety
    ///
    /// - the ref count of the value block must be adjusted manually to compensate for dropping `self`. Possible solutions are:
    ///   - manually increment the reference count
    ///   - prevent `other` from being dropped (e.g. using [std::mem::ManuallyDrop])
    ///   - prevent `self` from being dropped
    #[inline]
    unsafe fn raw_copy(other: &Self) -> Self {
        NickelValue {
            data: other.data,
            pos_idx: other.pos_idx,
        }
    }

    /// Creates a Nickel value from a raw pointer to a value block.
    ///
    /// # Safety
    ///
    /// - `ptr` must be a valid pointer to a [ValueBlockRc].
    /// - the ref count of the value block must be adjusted manually to compensate for dropping `self`. Possible solutions are:
    ///   - manually increment the reference count,
    ///   - prevent `self` from being dropped (e.g. using [std::mem::ManuallyDrop])
    ///   - use a `ptr` coming from a call to [ValueBlockRc::into_raw]
    ///   - derive `ptr` from a value or a value block that won't be dropped
    #[inline]
    unsafe fn block(data: NonNull<u8>) -> Self {
        NickelValue {
            data,
            pos_idx: PosIdx::NONE,
        }
    }
}

impl NickelValue {
    /// The mask for the tag bits in a value pointer.
    const VALUE_TAG_MASK: usize = 0b11;

    /// Returns the inner data as a bare `usize`. This loses the provenance of `self.data`, and is
    /// supposed to be used for inline values.
    #[inline]
    fn as_usize(&self) -> usize {
        self.data.addr().into()
    }

    /// Assuming this value is a value block, returns a reference to the corresponding header.
    ///
    /// # Safety
    ///
    /// `self` must be a value block, that is `self.tag()` must be `Pointer`.
    #[inline]
    unsafe fn header(&self) -> &ValueBlockHeader {
        // Safety: function pre-conditions, plus the lifetime of the returned header is tied to
        // `&self`, guaranteeing that the block won't be de-allocated.
        unsafe { ValueBlockRc::header_from_raw(self.data) }
    }

    /// Returns the tag bits of this value.
    #[inline]
    pub fn tag(&self) -> ValueTag {
        (self.as_usize() & Self::VALUE_TAG_MASK).try_into().unwrap()
    }

    /// Creates a new inline value without an associated position index. Same as
    /// `Self::inline(inline, PosIdx::NONE)`.
    #[inline]
    pub const fn inline_posless(inline: InlineValue) -> Self {
        Self::inline(inline, PosIdx::NONE)
    }

    /// Creates a new null value with the index set to [PosIdx::NONE].
    #[inline]
    pub const fn null() -> Self {
        Self::inline_posless(InlineValue::Null)
    }

    /// Creates a new true value with the index set to [PosIdx::NONE].
    #[inline]
    pub const fn bool_true() -> Self {
        Self::inline_posless(InlineValue::True)
    }

    /// Creates a new false value with the index set to [PosIdx::NONE].
    #[inline]
    pub const fn bool_false() -> Self {
        Self::inline_posless(InlineValue::False)
    }

    /// Creates a new boolean value.
    pub fn bool_value(value: bool, pos_idx: PosIdx) -> Self {
        if value {
            Self::inline(InlineValue::True, pos_idx)
        } else {
            Self::inline(InlineValue::False, pos_idx)
        }
    }

    /// Creates a new boolean value with the index set to [PosIdx::NONE].
    #[inline]
    pub fn bool_value_posless(value: bool) -> Self {
        Self::bool_value(value, PosIdx::NONE)
    }

    /// Creates a new empty array with the index set to [PosIdx::NONE].
    #[inline]
    pub const fn empty_array() -> Self {
        Self::inline_posless(InlineValue::EmptyArray)
    }

    /// Creates a new empty record with the index set to [PosIdx::NONE].
    #[inline]
    pub const fn empty_record() -> Self {
        Self::inline_posless(InlineValue::EmptyRecord)
    }

    /// Allocates a new number value.
    #[inline]
    pub fn number(value: impl Into<Number>, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value.into(), pos_idx).into()
    }

    /// Allocates a new number value without any position set. Equivalent to `Self::number(value,
    /// PosIdx::NONE`
    #[inline]
    pub fn number_posless(value: impl Into<Number>) -> Self {
        Self::number(value, PosIdx::NONE)
    }

    /// Allocates a new string value.
    #[inline]
    pub fn string(value: impl Into<NickelString>, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value.into(), pos_idx).into()
    }

    /// Allocates a new string value without any position set. Equivalent to `Self::string(value,
    /// PosIdx::NONE`
    #[inline]
    pub fn string_posless(value: impl Into<NickelString>) -> Self {
        Self::string(value, PosIdx::NONE)
    }

    /// Allocates a new array value. If the array is empty, it is automatically inlined as
    /// [InlineValue::EmptyArray].
    pub fn array(value: Array, pending_contracts: Vec<RuntimeContract>, pos_idx: PosIdx) -> Self {
        if value.is_empty() {
            Self::inline(InlineValue::EmptyArray, pos_idx)
        } else {
            ValueBlockRc::encode(
                ArrayData {
                    array: value,
                    pending_contracts,
                },
                pos_idx,
            )
            .into()
        }
    }

    /// Allocates a new array value without any position set. If the array is empty, it is
    /// automatically inlined as [InlineValue::EmptyArray].
    #[inline]
    pub fn array_posless(value: Array, pending_contracts: Vec<RuntimeContract>) -> Self {
        Self::array(value, pending_contracts, PosIdx::NONE)
    }

    /// Creates a new empty array, but doesn't inline it. This forces the allocation of a value
    /// block. [Self::empty_array_block] can be useful when one needs to have a pre-allocated array
    /// that will be mutated in a second step.
    #[inline]
    pub fn empty_array_block(pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(ArrayData::default(), pos_idx).into()
    }

    /// Allocates a new record value. If the record is empty, it is automatically inlined as
    /// [InlineValue::EmptyRecord].
    pub fn record(value: RecordData, pos_idx: PosIdx) -> Self {
        // We need to exclude empty open records here, because we would otherwise lose this bit of
        // information: an inline empty record is assumed to be closed.
        if value.is_empty() && !value.attrs.open {
            Self::inline(InlineValue::EmptyRecord, pos_idx)
        } else {
            ValueBlockRc::encode(value, pos_idx).into()
        }
    }

    /// Allocates a new record value without any position set. If the record is empty, it is
    /// automatically inlined as [InlineValue::EmptyRecord].
    pub fn record_posless(value: RecordData) -> Self {
        if value.is_empty() {
            Self::empty_record()
        } else {
            ValueBlockRc::encode(value, PosIdx::NONE).into()
        }
    }

    /// Creates a new empty record, but doesn't inline it. This forces the allocation of a value
    /// block. [Self::empty_record] can be useful when one needs to have a pre-allocated record
    /// that will be mutated in a second step.
    #[inline]
    pub fn empty_record_block(pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(RecordData::empty(), pos_idx).into()
    }

    /// Allocates a new thunk value.
    #[inline]
    pub fn thunk(data: lazy::ThunkData, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(RefCell::new(data), pos_idx).into()
    }

    /// Allocates a new thunk value without any position set. Equivalent to `Self::thunk(value,
    /// PosIdx::NONE)`.
    #[inline]
    pub fn thunk_posless(data: lazy::ThunkData) -> Self {
        Self::thunk(data, PosIdx::NONE)
    }

    /// Allocates a new term value.
    #[inline]
    pub fn term(value: Term, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value, pos_idx).into()
    }

    /// Allocates a new term value without any position set. Equivalent to `Self::term(value,
    /// PosIdx::NONE)`.
    #[inline]
    pub fn term_posless(value: Term) -> Self {
        Self::term(value, PosIdx::NONE)
    }

    /// Allocates a new label value.
    #[inline]
    pub fn label(value: Label, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value, pos_idx).into()
    }

    /// Allocates a new label value without any position set. Equivalent to `Self::label(value,
    /// PosIdx::NONE)`.
    #[inline]
    pub fn label_posless(value: Label) -> Self {
        Self::label(value, PosIdx::NONE)
    }

    /// Allocates a new enum variant value.
    pub fn enum_variant(
        tag: impl Into<LocIdent>,
        arg: Option<NickelValue>,
        pos_idx: PosIdx,
    ) -> Self {
        ValueBlockRc::encode(
            EnumVariantData {
                tag: tag.into(),
                arg,
            },
            pos_idx,
        )
        .into()
    }

    /// Allocates a new enum variant value without any position set. Equivalent to
    /// `Self::enum_variant(tag, arg, PosIdx::NONE)`.
    #[inline]
    pub fn enum_variant_posless(tag: impl Into<LocIdent>, arg: Option<NickelValue>) -> Self {
        Self::enum_variant(tag.into(), arg, PosIdx::NONE)
    }

    /// Allocates a new enum tag value. Same as `Self::enum_variant(tag, None, pos_idx)`.
    #[inline]
    pub fn enum_tag(tag: impl Into<LocIdent>, pos_idx: PosIdx) -> Self {
        Self::enum_variant(tag.into(), None, pos_idx)
    }

    /// Allocates a new enum tag value without any position set. Equivalent to `Self::enum_tag(tag,
    /// arg, PosIdx::NONE)`.
    #[inline]
    pub fn enum_tag_posless(tag: impl Into<LocIdent>) -> Self {
        Self::enum_tag(tag.into(), PosIdx::NONE)
    }

    /// Allocates a new foreign ID value.
    #[inline]
    pub fn foreign_id(value: ForeignIdPayload, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value, pos_idx).into()
    }

    /// Allocates a new foreign ID value without any position set. Equivalent to
    /// `Self::foreign_id(value, PosIdx::NONE)`.
    #[inline]
    pub fn foreign_id_posless(value: ForeignIdPayload) -> Self {
        Self::foreign_id(value, PosIdx::NONE)
    }

    /// Allocates a new sealing key value.
    #[inline]
    pub fn sealing_key(value: SealingKey, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value, pos_idx).into()
    }

    /// Allocates a new sealing key value without any position set. Equivalent to
    /// `Self::sealing_key(value, PosIdx::NONE)`.
    #[inline]
    pub fn sealing_key_posless(value: SealingKey) -> Self {
        Self::sealing_key(value, PosIdx::NONE)
    }

    /// Allocates a new custom contract value.
    #[inline]
    pub fn custom_contract(value: NickelValue, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(value, pos_idx).into()
    }

    /// Allocates a new custom contract value without any position set. Equivalent to
    /// `Self::custom_contract(value, PosIdx::NONE)`.
    #[inline]
    pub fn custom_contract_posless(value: NickelValue) -> Self {
        Self::custom_contract(value, PosIdx::NONE)
    }

    /// Allocates a new type.
    #[inline]
    pub fn typ(typ: Type, contract: NickelValue, pos_idx: PosIdx) -> Self {
        ValueBlockRc::encode(TypeData { typ, contract }, pos_idx).into()
    }

    /// Returns the inner value of `self` if it's an inline value, or `None` otherwise.
    #[inline]
    pub fn as_inline(&self) -> Option<InlineValue> {
        InlineValue::try_from(self).ok()
    }

    /// Returns the inner value of `self` if it's a (inlined) boolean value, or `None` otherwise.
    #[inline]
    pub fn as_bool(&self) -> Option<bool> {
        match self.as_inline()? {
            InlineValue::True => Some(true),
            InlineValue::False => Some(false),
            _ => None,
        }
    }

    /// Returns a reference to the inner number stored in this value if `self` is a value block
    /// with tag number, or `None` otherwise.
    #[inline]
    pub fn as_number(&self) -> Option<&NumberData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner string stored in this value if `self` is a value block
    /// with tag string, or `None` otherwise.
    #[inline]
    pub fn as_string(&self) -> Option<&StringData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner array stored in this value if `self` is a value block
    /// with tag array or an inline empty array. Returns `None` otherwise.
    #[inline]
    pub fn as_array(&self) -> Option<Container<&ArrayData>> {
        if self.is_inline_empty_array() {
            Some(Container::Empty)
        } else {
            self.as_value_data().map(Container::Alloc)
        }
    }

    /// Returns a reference to the inner record stored in this value if `self` is a value block
    /// with tag record or an inline empty record. Returns `None` otherwise.
    pub fn as_record(&self) -> Option<Container<&RecordData>> {
        if self.is_inline_empty_record() {
            Some(Container::Empty)
        } else {
            self.as_value_data().map(Container::Alloc)
        }
    }

    /// Returns a reference to the inner thunk data stored in this value if `self` is a value block
    /// with tag record or an inline empty record. Returns `None` otherwise.
    ///
    /// # Safety
    ///
    /// `self` must be a thunk value block, that is `self.data_tag()` must be [DataTag::Thunk].
    #[inline]
    pub unsafe fn as_thunk_data_unchecked(&self) -> &ThunkData {
        // Safety: function safety pre-condition
        unsafe { ValueBlockRc::decode_from_raw_unchecked(self.data) }
    }

    /// Returns `&self` seen as a thunk if `self` is a value block with tag thunk, or
    /// `None` otherwise.
    ///
    /// While it would be more in line with other `as_xxx` functions to return [ThunkData], in
    /// practice you often want [Thunk] instead, the latter being harder to work with.
    pub fn as_thunk(&self) -> Option<&Thunk> {
        if let Some(DataTag::Thunk) = self.data_tag() {
            // Safety: function safety pre-condition
            unsafe { Some(self.as_thunk_unchecked()) }
        } else {
            None
        }
    }

    /// Returns the same value but wrapped as a [crate::eval::cache::lazy::Thunk] if `self` is a
    /// value block with tag thunk, or `Err(self)` otherwise.
    pub fn try_into_thunk(self) -> Result<Thunk, NickelValue> {
        if let Some(DataTag::Thunk) = self.data_tag() {
            Ok(Thunk(self))
        } else {
            Err(self)
        }
    }

    /// Same as [Self::as_thunk], but doesn't check that the value is a block nor that the data tag
    /// is [DataTag::Thunk].
    ///
    /// This method is mostly intended to be used internally and from [Thunk] only. You should
    /// almost always use [Self::as_thunk] instead.
    ///
    /// # Safety
    ///
    /// `self` must be a value block with a thunk inside, that is `self.data_tag()` must be
    /// [DataTag::Thunk].
    #[inline]
    pub(super) unsafe fn as_thunk_unchecked(&self) -> &Thunk {
        // Safety: `Thunk` is a struct with a single field that is a `NickelValue` and has the
        // `transparent` representation, guaranteeing the same layout as `NickelValue`.
        unsafe { transmute::<&NickelValue, &Thunk>(self) }
    }

    /// Mutable version of [Self::as_thunk_unchecked].
    ///
    /// # Safety
    ///
    /// `self` must be a value block with a thunk inside, that is `self.data_tag()` must be
    /// [DataTag::Thunk].
    #[inline]
    pub(super) unsafe fn as_thunk_mut_unchecked(&mut self) -> &mut Thunk {
        // Safety: `Thunk` is a struct with a single field that is a `NickelValue` and has the
        // `transparent` representation, guaranteeing the same layout as `NickelValue`.
        unsafe { transmute::<&mut NickelValue, &mut Thunk>(self) }
    }

    /// Interprets this value as a thunk, without checking that the value is a block nor that the
    /// data tag is [DataTag::Thunk].
    ///
    /// This method is mostly intended to be used internally and from [Thunk] only. You should
    /// almost always use [Self::as_thunk] instead.
    ///
    /// # Safety
    ///
    /// `self` must be a value block with a thunk inside, that is `self.data_tag()` must be
    /// [DataTag::Thunk].
    #[inline]
    pub(super) unsafe fn into_thunk_unchecked(self) -> Thunk {
        // Safety: this function pre-condition.
        Thunk(self)
    }

    /// Returns a reference to the inner term stored in this value if `self` is a value block with
    /// a tag term, or `None` otherwise.
    #[inline]
    pub fn as_term(&self) -> Option<&TermData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner label stored in this value if `self` is a value block with
    /// tag label, or `None` otherwise.
    #[inline]
    pub fn as_label(&self) -> Option<&LabelData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner enum variant stored in this value if `self` is a value
    /// block with tag enum variant, or `None` otherwise.
    #[inline]
    pub fn as_enum_variant(&self) -> Option<&EnumVariantData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner enum tag stored in this value if `self` is a value is a
    /// block with an enum variant inside, which has no arguments, or `None` otherwise.
    pub fn as_enum_tag(&self) -> Option<LocIdent> {
        let enum_var = self.as_enum_variant()?;
        enum_var.arg.is_none().then_some(enum_var.tag)
    }

    /// Returns a reference to the inner sealing key stored in this value if `self` is a value
    /// block with sealing key inside, or `None` otherwise.
    #[inline]
    pub fn as_sealing_key(&self) -> Option<&SealingKeyData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner type stored in this value if `self` is a value with a type
    /// inside, or `None` otherwise.
    #[inline]
    pub fn as_type(&self) -> Option<&TypeData> {
        self.as_value_data()
    }

    /// Returns a reference to the inner foreign id stored in this value if `self` is a value
    /// block with a foreign value inside, or `None` otherwise.
    #[inline]
    pub fn as_foreign_id(&self) -> Option<&ForeignIdData> {
        self.as_value_data()
    }

    /// Returns the value block pointed to by this Nickel value if it's a value block, or `Err`
    /// otherwise. This is equivalent to `<Self as TryInto<ValueBlockRc>>::try_into`, but is more
    /// succinct and type-inference-friendly. Since this method must consume `self` in the case
    /// it's a value block, in order to keep the reference count correct, the caller can get `self`
    /// back in case of error.
    #[inline]
    pub fn into_block(self) -> Result<ValueBlockRc, Self> {
        ValueBlockRc::try_from(self)
    }

    /// Returns a reference to the content of this value if it's a value block of type `T`, or
    /// `None` otherwise.
    fn as_value_data<T: ValueBlockData>(&self) -> Option<&T> {
        if self.tag() == ValueTag::Pointer {
            // Safety: if `tag` is `Pointer`, the content of `self` must be a valid non-null
            // pointer to a value block.
            //
            // Since the value block won't be dropped until self is dropped, and since the output
            // lifetime of `&T` is tied to `&self`, `&T` won't outlive the value block.
            unsafe { ValueBlockRc::try_decode_from_raw(self.data) }
        } else {
            None
        }
    }

    /// Checks if this value is an inline value or is an allocated block.
    #[inline]
    pub fn is_inline(&self) -> bool {
        self.tag() == ValueTag::Inline
    }

    /// Returns a typed reference to the content of the value, or the content of the inline value
    /// directly.
    pub fn content_ref(&self) -> ValueContentRef<'_> {
        match self.tag() {
            // Safety: if `self.tag()` is `Pointer`, then the content of self must be a valid
            // non-null pointer to a value block.
            ValueTag::Pointer => unsafe {
                let tag = ValueBlockRc::tag_from_raw(self.data);

                // Safety: additionally, the lifetime of the return `ValueContentRef<'_>` is tied to
                // `&self`, so the former won't outlive the value block.
                match tag {
                    DataTag::Number => {
                        ValueContentRef::Number(ValueBlockRc::decode_from_raw_unchecked(self.data))
                    }
                    DataTag::Array => ValueContentRef::Array(Container::Alloc(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    )),
                    DataTag::Record => ValueContentRef::Record(Container::Alloc(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    )),
                    DataTag::String => {
                        ValueContentRef::String(ValueBlockRc::decode_from_raw_unchecked(self.data))
                    }
                    DataTag::Thunk => {
                        // Safety: we checked that value's tag is `DataTag::Thunk`
                        ValueContentRef::Thunk(self.as_thunk_unchecked())
                    }
                    DataTag::Term => {
                        ValueContentRef::Term(ValueBlockRc::decode_from_raw_unchecked(self.data))
                    }
                    DataTag::Label => {
                        ValueContentRef::Label(ValueBlockRc::decode_from_raw_unchecked(self.data))
                    }
                    DataTag::EnumVariant => ValueContentRef::EnumVariant(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    ),
                    DataTag::ForeignId => ValueContentRef::ForeignId(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    ),
                    DataTag::SealingKey => ValueContentRef::SealingKey(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    ),
                    DataTag::CustomContract => ValueContentRef::CustomContract(
                        ValueBlockRc::decode_from_raw_unchecked(self.data),
                    ),
                    DataTag::Type => {
                        ValueContentRef::Type(ValueBlockRc::decode_from_raw_unchecked(self.data))
                    }
                }
            },
            ValueTag::Inline => {
                // Safety: `self.tag()` is `ValueTag::Inline`
                match unsafe { self.as_inline_unchecked() } {
                    InlineValue::EmptyArray => ValueContentRef::Array(Container::Empty),
                    InlineValue::EmptyRecord => ValueContentRef::Record(Container::Empty),
                    InlineValue::Null => ValueContentRef::Null,
                    InlineValue::True => ValueContentRef::Bool(true),
                    InlineValue::False => ValueContentRef::Bool(false),
                }
            }
        }
    }

    /// Returns a mutable typed reference to the content of the value. Returns `None` if the
    /// underlying value block has a reference count greater than one. See [Self::content_make_mut]
    /// in this case.
    ///
    /// # Thunks
    ///
    /// [ValueContentRefMut::Thunk] is special in that it returns a wrapper around `self`, and not
    /// a reference into the block. It's the only case that doesn't actually require to
    /// copy-on-write, and thus this method always return `Some` for thunks even if the block is
    /// shared.
    pub fn content_mut(&mut self) -> Option<ValueContentRefMut<'_>> {
        match self.tag() {
            // Safety: if `self.tag()` is `Pointer`, then the content of self must be a valid
            // non-null pointer to a value block.
            ValueTag::Pointer => unsafe {
                let header = self.header();

                // [^thunk-copy-on-mut-ref]: We must be careful with thunks. Not only we don't need
                // to copy-on-write, since we're handing back a `Thunk` which is just a wrapper
                // around `self` (instead of a mutable reference inside the block), but we must
                // actually _avoid_ making copies, which would break the sharing of thunks.
                if header.ref_count() != 1 && header.tag() != DataTag::Thunk {
                    return None;
                }

                // Safety:
                //  - additionally, the lifetime of the return `ValueContentRef<'_>` is tied to
                //    `&mut self`, so the former won't outlive the value block.
                //  - we've checked above that `ref_count` is `1`, and we hold a mutable borrow of
                //  `  self`, so there can't be other active mutable borrows to the block
                Some(match header.tag() {
                    DataTag::Number => ValueContentRefMut::Number(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::Array => ValueContentRefMut::Array(Container::Alloc(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    )),
                    DataTag::Record => ValueContentRefMut::Record(Container::Alloc(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    )),
                    DataTag::String => ValueContentRefMut::String(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    // Safety: `Thunk` is a struct with a single field that is a `NickelValue` and has the
                    // `transparent` representation, guaranteeing the same layout as `NickelValue`.
                    DataTag::Thunk => ValueContentRefMut::Thunk(self.as_thunk_mut_unchecked()),
                    DataTag::Term => ValueContentRefMut::Term(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::Label => ValueContentRefMut::Label(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::EnumVariant => ValueContentRefMut::EnumVariant(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::ForeignId => ValueContentRefMut::ForeignId(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::SealingKey => ValueContentRefMut::SealingKey(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::CustomContract => ValueContentRefMut::CustomContract(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                    DataTag::Type => ValueContentRefMut::Type(
                        ValueBlockRc::decode_mut_from_raw_unchecked(self.data),
                    ),
                })
            },
            ValueTag::Inline => {
                // Safety: `self.tag()` is `ValueTag::Inline`
                Some(match unsafe { self.as_inline_unchecked() } {
                    InlineValue::EmptyArray => ValueContentRefMut::Array(Container::Empty),
                    InlineValue::EmptyRecord => ValueContentRefMut::Record(Container::Empty),
                    InlineValue::Null => ValueContentRefMut::Null(self),
                    InlineValue::True => ValueContentRefMut::Bool(self),
                    InlineValue::False => ValueContentRefMut::Bool(self),
                })
            }
        }
    }

    /// Returns a lazy, owned handle to the content of this value.
    pub fn content(self) -> ValueContent {
        use lens::{TermContent, ValueLens};

        match self.tag() {
            ValueTag::Pointer => {
                // Safety: in each branch, the tag of the value block matches the type parameter of
                // the lens built with `content_lens()`.
                unsafe {
                    // Safety: if `self.tag()` is `ValueTag::Pointer`, `self.data` must be a valid
                    // pointer to a block.
                    match self.header().tag() {
                        DataTag::Number => ValueContent::Number(ValueLens::content_lens(self)),
                        DataTag::Array => ValueContent::Array(ValueLens::container_lens(self)),
                        DataTag::Record => ValueContent::Record(ValueLens::container_lens(self)),
                        DataTag::String => ValueContent::String(ValueLens::content_lens(self)),
                        DataTag::Thunk => ValueContent::Thunk(ValueLens::thunk_lens(self)),
                        DataTag::Term => {
                            let term: &TermData =
                                ValueBlockRc::decode_from_raw_unchecked(self.data);

                            ValueContent::Term(match term {
                                Term::StrChunks(_) => {
                                    TermContent::StrChunks(ValueLens::term_str_chunks_lens(self))
                                }
                                Term::Fun(..) => TermContent::Fun(ValueLens::term_fun_lens(self)),
                                Term::Let(..) => TermContent::Let(ValueLens::term_let_lens(self)),
                                Term::App(..) => TermContent::App(ValueLens::term_app_lens(self)),
                                Term::Var(..) => TermContent::Var(ValueLens::term_var_lens(self)),
                                Term::RecRecord(..) => {
                                    TermContent::RecRecord(ValueLens::term_rec_record_lens(self))
                                }
                                Term::Closurize(_) => {
                                    TermContent::Closurize(ValueLens::term_closurize_lens(self))
                                }
                                Term::Op1(..) => TermContent::Op1(ValueLens::term_op1_lens(self)),
                                Term::Op2(..) => TermContent::Op2(ValueLens::term_op2_lens(self)),
                                Term::OpN(..) => TermContent::OpN(ValueLens::term_opn_lens(self)),
                                Term::Sealed(..) => {
                                    TermContent::Sealed(ValueLens::term_sealed_lens(self))
                                }
                                Term::Annotated(..) => {
                                    TermContent::Annotated(ValueLens::term_annotated_lens(self))
                                }
                                Term::Import(_) => {
                                    TermContent::Import(ValueLens::term_import_lens(self))
                                }
                                Term::ResolvedImport(_) => TermContent::ResolvedImport(
                                    ValueLens::term_resolved_import_lens(self),
                                ),
                                Term::ParseError(_) => {
                                    TermContent::ParseError(ValueLens::term_parse_error_lens(self))
                                }
                                Term::RuntimeError(_) => TermContent::RuntimeError(
                                    ValueLens::term_runtime_error_lens(self),
                                ),
                            })
                        }
                        DataTag::Label => ValueContent::Label(ValueLens::content_lens(self)),
                        DataTag::EnumVariant => {
                            ValueContent::EnumVariant(ValueLens::content_lens(self))
                        }
                        DataTag::ForeignId => {
                            ValueContent::ForeignId(ValueLens::content_lens(self))
                        }
                        DataTag::SealingKey => {
                            ValueContent::SealingKey(ValueLens::content_lens(self))
                        }
                        DataTag::CustomContract => {
                            ValueContent::CustomContract(ValueLens::content_lens(self))
                        }
                        DataTag::Type => ValueContent::Type(ValueLens::content_lens(self)),
                    }
                }
            }
            ValueTag::Inline => {
                // Safety:
                //
                // as_inline_unchecked: `self.tag()` is `ValueTag::Inline`
                //
                // ValueLens::xxx_lens: in each branch, the type of the inline value matches the
                // type of the lens built with `xxx_lens()`.
                unsafe {
                    match self.as_inline_unchecked() {
                        InlineValue::Null => ValueContent::Null(ValueLens::null_lens(self)),
                        InlineValue::True | InlineValue::False => {
                            ValueContent::Bool(ValueLens::bool_lens(self))
                        }
                        InlineValue::EmptyArray => {
                            ValueContent::Array(ValueLens::container_lens(self))
                        }
                        InlineValue::EmptyRecord => {
                            ValueContent::Record(ValueLens::container_lens(self))
                        }
                    }
                }
            }
        }
    }

    /// Returns a mutable typed reference to the content of the value. This method is
    /// copy-on-write, same as [std::rc::Rc::make_mut] and [ValueBlockRc::make_mut]: if the
    /// underlying value block has a reference count greater than one, `self` is assigned to a fresh
    /// copy which is guaranteed to be 1-reference counted, and a mutable reference to the content
    /// of this copy is returned. Thunks are exception, and will never be copied; see
    /// [Self::content_mut].
    pub fn content_make_mut(&mut self) -> ValueContentRefMut<'_> {
        // Safety: `value.tag()` must be `Pointer` and `value.data_tag()` must be equal to `T::Tag`
        unsafe fn make_mut<T: ValueBlockData + Clone>(value: &mut NickelValue) -> &mut T {
            unsafe {
                if value.header().ref_count() != 1 {
                    increment!("value::content_make_mut::strong clone");
                    // Safety: header doesn't become dangling because the ref count is strictly
                    // greater than one, so the reassignment of `*value` doesn't invalidate it.
                    *value = ValueBlockRc::encode(
                        // Safety: `value.data_tag()` is `T::Tag` (precondition)
                        ValueBlockRc::decode_from_raw_unchecked::<T>(value.data).clone(),
                        value.header().pos_idx,
                    )
                    .into();
                } else {
                    increment!("value::content_make_mut::no clone");
                }

                // Safety: we've made sure `value` is now unique
                ValueBlockRc::decode_mut_from_raw_unchecked::<T>(value.data)
            }
        }

        match self.tag() {
            // Safety: if `self.tag()` is `Pointer`, then the content of self must be a valid
            // non-null pointer to a value block.
            ValueTag::Pointer => unsafe {
                let tag = ValueBlockRc::tag_from_raw(self.data);

                match tag {
                    DataTag::Number => ValueContentRefMut::Number(make_mut(self)),
                    DataTag::Array => ValueContentRefMut::Array(Container::Alloc(make_mut(self))),
                    DataTag::Record => ValueContentRefMut::Record(Container::Alloc(make_mut(self))),
                    DataTag::String => ValueContentRefMut::String(make_mut(self)),
                    // See [^thunk-copy-on-mut-ref].
                    DataTag::Thunk => {
                        // Safety: we just checked that the value's tag is `Thunk`.
                        ValueContentRefMut::Thunk(self.as_thunk_mut_unchecked())
                    }
                    DataTag::Term => ValueContentRefMut::Term(make_mut(self)),
                    DataTag::Label => ValueContentRefMut::Label(make_mut(self)),
                    DataTag::EnumVariant => ValueContentRefMut::EnumVariant(make_mut(self)),
                    DataTag::ForeignId => ValueContentRefMut::ForeignId(make_mut(self)),
                    DataTag::SealingKey => ValueContentRefMut::SealingKey(make_mut(self)),
                    DataTag::CustomContract => ValueContentRefMut::CustomContract(make_mut(self)),
                    DataTag::Type => ValueContentRefMut::Type(make_mut(self)),
                }
            },
            ValueTag::Inline => {
                // Safety: `self.tag()` is `ValueTag::Inline`
                match unsafe { self.as_inline_unchecked() } {
                    InlineValue::Null => ValueContentRefMut::Null(self),
                    InlineValue::True | InlineValue::False => ValueContentRefMut::Bool(self),
                    InlineValue::EmptyArray => ValueContentRefMut::Array(Container::Empty),
                    InlineValue::EmptyRecord => ValueContentRefMut::Record(Container::Empty),
                }
            }
        }
    }

    /// Returns the data tag of the underlying value block, or `None` if `self` is an inline value.
    pub fn data_tag(&self) -> Option<DataTag> {
        (self.tag() == ValueTag::Pointer).then(|| {
            // Safety: if `self.tag()` is `Pointer`, then `self.data` must be valid pointer to a
            // value block.
            unsafe { ValueBlockRc::tag_from_raw(self.data) }
        })
    }

    /// Checks if this value is the inline empty array. Caution: note that `self` could also be an
    /// empty array, but allocated as a block. In that case, [Self::is_inline_empty_array] would
    /// still return `false`.
    pub fn is_inline_empty_array(&self) -> bool {
        self.as_inline()
            .is_some_and(|inl| matches!(inl, InlineValue::EmptyArray))
    }

    /// Checks if this value is the inline empty record. Caution: note that `self` could also be an
    /// empty record, but allocated as a block. In that case, [Self::is_inline_empty_record] would still
    /// return `false`.
    pub fn is_inline_empty_record(&self) -> bool {
        self.as_inline()
            .is_some_and(|inl| matches!(inl, InlineValue::EmptyRecord))
    }

    /// Checks if this value is the inlined boolean `true`.
    pub fn is_bool_true(&self) -> bool {
        self.as_inline()
            .is_some_and(|inl| matches!(inl, InlineValue::True))
    }

    /// Checks if this value is the inlined boolean `false`.
    pub fn is_bool_false(&self) -> bool {
        self.as_inline()
            .is_some_and(|inl| matches!(inl, InlineValue::False))
    }

    /// Checks if this value is the inlined constant `null`.
    pub fn is_null(&self) -> bool {
        self.as_inline()
            .is_some_and(|inl| matches!(inl, InlineValue::Null))
    }

    /// Determines if a value is in evaluated form, called weak head normal form (WHNF). See
    /// [crate::term::Term::is_whnf] for more details.
    #[inline]
    pub fn is_whnf(&self) -> bool {
        !matches!(self.data_tag(), Some(DataTag::Thunk | DataTag::Term))
    }

    /// Returns the class of an expression in WHNF.
    ///
    /// The class of an expression is an approximation of its type used in error reporting. Class
    /// and type coincide for constants (numbers, strings and booleans) and arrays. Otherwise the
    /// class is less precise than the type and indicates the general shape of the term: `Record`
    /// for records, `Array` for arrays, etc. If the term is not a WHNF, `None` is returned.
    pub fn type_of(&self) -> Option<&'static str> {
        match self.content_ref() {
            ValueContentRef::Null => Some("Other"),
            ValueContentRef::Bool(_) => Some("Bool"),
            ValueContentRef::Number(_) => Some("Number"),
            ValueContentRef::Array(_) => Some("Array"),
            ValueContentRef::Record(_) => Some("Record"),
            ValueContentRef::String(_) => Some("String"),
            ValueContentRef::Term(term) => match term {
                Term::Closurize(v) => v.type_of(),
                Term::RecRecord(..) => Some("Record"),
                Term::Fun(..) => Some("Function"),
                Term::Sealed(..) => Some("Sealed"),
                Term::Annotated(..) => Some("Annotated"),
                Term::Let(..)
                | Term::App(_)
                | Term::Var(_)
                | Term::Op1(_)
                | Term::Op2(_)
                | Term::OpN(_)
                | Term::Import(_)
                | Term::ResolvedImport(_)
                | Term::StrChunks(_)
                | Term::ParseError(_)
                | Term::RuntimeError(_) => None,
            },
            ValueContentRef::Label(_) => Some("Label"),
            ValueContentRef::EnumVariant(EnumVariantData { arg: None, tag: _ }) => Some("EnumTag"),
            ValueContentRef::EnumVariant(EnumVariantData {
                arg: Some(_),
                tag: _,
            }) => Some("EnumVariant"),
            ValueContentRef::ForeignId(_) => Some("ForeignId"),
            ValueContentRef::SealingKey(_) => Some("SealingKey"),
            ValueContentRef::CustomContract(_) => Some("CustomContract"),
            ValueContentRef::Type(_) => Some("Type"),
            _ => None,
        }
    }

    /// Determines if a term is a constant.
    ///
    /// In this context, a constant is an atomic literal of the language that mustn't contain any
    /// other sub-expression: null, a boolean, a number, a string, a label, an enum tag, an empty
    /// container (array or record), a sealing key or a foreign id.
    pub fn is_constant(&self) -> bool {
        match self.content_ref() {
            ValueContentRef::Null
            | ValueContentRef::Bool(_)
            | ValueContentRef::Array(Container::Empty)
            | ValueContentRef::Record(Container::Empty)
            | ValueContentRef::Number(_)
            | ValueContentRef::Label(_)
            | ValueContentRef::ForeignId(_)
            | ValueContentRef::SealingKey(_)
            | ValueContentRef::String(_) => true,
            ValueContentRef::EnumVariant(enum_variant) => enum_variant.arg.is_none(),
            ValueContentRef::Array(_)
            | ValueContentRef::Record(_)
            | ValueContentRef::Thunk(_)
            | ValueContentRef::Term(_)
            | ValueContentRef::CustomContract(_)
            | ValueContentRef::Type(_) => false,
        }
    }

    /// Determines if a value is an atom of the surface syntax. Atoms are basic elements of the
    /// syntax that can freely substituted without being parenthesized.
    pub fn fmt_is_atom(&self) -> bool {
        let Some(data_tag) = self.data_tag() else {
            // All inline values are atoms
            // Caution: if we inline some integers in the future as well, negative integers are NOT
            // atoms, so this path should be updated.
            return true;
        };

        match data_tag {
            DataTag::Array
            | DataTag::Record
            | DataTag::ForeignId
            | DataTag::SealingKey
            | DataTag::Label
            | DataTag::String => true,
            DataTag::Number => self.as_value_data::<NumberData>().unwrap() >= &0,
            DataTag::EnumVariant => self
                .as_value_data::<EnumVariantData>()
                .unwrap()
                .arg
                .is_none(),
            DataTag::Thunk => false,
            DataTag::Term => self.as_value_data::<TermData>().unwrap().fmt_is_atom(),
            DataTag::CustomContract => self
                .as_value_data::<CustomContractData>()
                .unwrap()
                .fmt_is_atom(),
            DataTag::Type => self.as_value_data::<TypeData>().unwrap().typ.fmt_is_atom(),
        }
    }

    /// Converts a primitive value (number, string, boolean, enum tag or null) to a Nickel string,
    /// or returns `None` if the value isn't primitive.
    pub fn to_nickel_string(&self) -> Option<NickelString> {
        match self.content_ref() {
            ValueContentRef::Null => Some("null".into()),
            ValueContentRef::Bool(b) => Some(b.to_string().into()),
            ValueContentRef::String(s) => Some(s.clone()),
            ValueContentRef::EnumVariant(EnumVariantData { tag, arg: None }) => Some((*tag).into()),
            ValueContentRef::Number(n) => Some(format!("{}", n.to_sci()).into()),
            _ => None,
        }
    }

    /// Checks for physical equality of two Nickel values. This is a very fast check that is
    /// complete for inline values but partial otherwise (i.e. it only returns `true` for pointers
    /// if the values physically point to the same value block).
    ///
    /// For inline values, this check **ignores** the position index.
    pub fn phys_eq(&self, other: &Self) -> bool {
        match self.tag() {
            ValueTag::Pointer => self.data == other.data,
            // Safety: the tag is checked to be `Inline`
            ValueTag::Inline => {
                other.is_inline()
                    && unsafe {
                        // Using `as_inline_unchecked` instead of `self.data` directly sidesteps the
                        // platform-specific differences
                        self.as_inline_unchecked() == other.as_inline_unchecked()
                    }
            }
        }
    }

    /// Updates the position of this value. First allocates a position index in the position table
    /// and use it as the new index.
    #[inline]
    pub fn with_pos(self, pos_table: &mut PosTable, pos: TermPos) -> Self {
        self.with_pos_idx(pos_table.push(pos))
    }

    /// Updates the position index of this value. If the value is a shared block (the ref
    /// count is greater than one), the result will be a new copy of the original value with the
    /// position set.
    pub fn with_pos_idx(self, pos_idx: PosIdx) -> Self {
        match self.tag() {
            ValueTag::Pointer => {
                // unwrap(): if the tag is `Pointer`, `ValueBlocRc::try_from(self)` must succeed.
                let mut block: ValueBlockRc = self.try_into().unwrap();
                block.make_unique();
                // Safety: `make_unique()` ensures there's no sharing, and we have the exclusive
                // access (ownership) of the block.
                unsafe { block.0.cast::<ValueBlockHeader>().as_mut().pos_idx = pos_idx }
                block.into()
            }
            // Safety: the tag is checked to be `Inline`
            ValueTag::Inline => self.with_inline_pos_idx(pos_idx),
        }
    }

    /// Returns the position index of this value, whether it is inline or not.
    pub fn pos_idx(&self) -> PosIdx {
        match self.tag() {
            // Safety: if `self.tag()` is `Pointer`, then `self.data` must be a valid non-null
            // pointer to a value block
            ValueTag::Pointer => unsafe { self.header().pos_idx },
            // unwrap(): if the tag is `Inline`, then `inline_pos_idx()` must be `Some`
            ValueTag::Inline => self.inline_pos_idx().unwrap(),
        }
    }

    /// Returns the position associated to this value.
    #[inline]
    pub fn pos(&self, table: &PosTable) -> TermPos {
        table.get(self.pos_idx())
    }

    /// Returns the same value with all the positions (recursively) cleared (set to
    /// [crate::position::PosIdx::NONE]).
    ///
    /// This is currently only used in test code, but because it's used from integration
    /// tests we cannot hide it behind `#[cfg(test)]`.
    pub fn without_pos(self) -> Self {
        self.traverse(
            &mut |t: Type| {
                Ok::<_, Infallible>(Type {
                    pos: TermPos::None,
                    ..t
                })
            },
            TraverseOrder::BottomUp,
        )
        .unwrap()
        .traverse(
            &mut |val: NickelValue| {
                //unwrap(): will go away soon
                Ok::<_, Infallible>(val.with_pos_idx(PosIdx::NONE))
            },
            TraverseOrder::BottomUp,
        )
        .unwrap()
    }
}

impl Default for NickelValue {
    #[inline]
    fn default() -> Self {
        Self::null()
    }
}

// Since a `NickelValue` can be a reference-counted pointer in disguise, we can't just copy it
// blindly. We need to make sure the reference count is incremented accordingly.
impl Clone for NickelValue {
    #[inline]
    fn clone(&self) -> Self {
        if self.tag() == ValueTag::Pointer {
            unsafe {
                // Safety: `self.tag()` is `Pointer`.
                //
                // We need to prevent this value block from being dropped as this would decrement
                // the refcount, nullifying our increment.
                self.header().inc_ref_count();
            }
        }

        // Safety: we incremented the ref count above, if the inner value is a block.
        unsafe { NickelValue::raw_copy(self) }
    }
}

// Same as for `Clone`: since we might be a reference-counted pointer in disguise, we need to
// properly decrement the underlying ref count.
impl Drop for NickelValue {
    #[inline]
    fn drop(&mut self) {
        if self.tag() == ValueTag::Pointer {
            unsafe {
                // Safety: if `self.tag()` is `Pointer`, `self.0` must be valid non-null pointer to
                // a value block
                let _ = ValueBlockRc::from_raw(self.data);
            }
        }
    }
}

impl From<InlineValue> for NickelValue {
    #[inline]
    fn from(inline: InlineValue) -> Self {
        NickelValue::inline_posless(inline)
    }
}

impl<'a> TryFrom<&'a NickelValue> for InlineValue {
    type Error = TagMismatchError;

    fn try_from(value: &'a NickelValue) -> Result<Self, Self::Error> {
        if value.tag() == ValueTag::Inline {
            // Safety: we checked that the tag is `ValueTag::Inline`
            unsafe { Ok(value.as_inline_unchecked()) }
        } else {
            Err(TagMismatchError)
        }
    }
}

impl TryFrom<NickelValue> for ValueBlockRc {
    /// To avoid consuming the original value needlessly, it is returned upon error.
    type Error = NickelValue;

    fn try_from(value: NickelValue) -> Result<Self, Self::Error> {
        if value.tag() == ValueTag::Pointer {
            Ok(unsafe {
                // We need to prevent value from being dropped, or this will decrease the refcount.
                let value = ManuallyDrop::new(value);
                // Safety: if `self.tag()` is `Pointer`, `self.0` must be a valid non-null pointer
                // to a value block
                ValueBlockRc::from_raw(value.data)
            })
        } else {
            Err(value)
        }
    }
}

impl From<ValueBlockRc> for NickelValue {
    // Converts this value block to a [NickelValue] pointer. To keep the reference count
    // consistent, this function consumes the value block without decrementing the reference
    // count, which is left unchanged by the conversion.
    #[inline]
    fn from(block: ValueBlockRc) -> Self {
        // We must avoid dropping `block` here, which would decrement the reference count.
        let this = ManuallyDrop::new(block);
        // Safety: this is a valid pointer to a `ValueBlockRc`, and the usage of manually drop
        // ensures the ref count is left unchanged.
        unsafe { NickelValue::block(this.0) }
    }
}

impl_display_from_pretty!(NickelValue);

/// Pointer tag used by [NickelValue] to discriminate between the pointer and non-pointer kind of Nickel values.
#[repr(usize)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
///////////
// CAUTION
///////////
// unsafe conversion functions from and to numeric types are relying on the precise values
// and range of `ValueTag`. If you add or remove tags, make sure to update all the corresponding
// code, in particular the `Self::MAX` constant.
//
// Values must be consecutive.
pub enum ValueTag {
    /// A heap-allocated value, meaning the tagged data is a valid pointer to [ValueBlockRc].
    Pointer = 0,
    /// The tag for an [InlineValue], which is not a pointer.
    Inline = 1,
}

impl ValueTag {
    /// The highest possible value when a tag is seen as a usize.
    pub const MAX: usize = ValueTag::Inline as usize;
}

impl From<ValueTag> for usize {
    #[inline]
    fn from(tag: ValueTag) -> Self {
        tag as usize
    }
}

/// Out of bounds error when trying to convert a numeric type to a tag.
#[derive(Clone, Copy, Eq, PartialEq, Debug)]
pub struct TagOutOfBoundsError;

impl TryFrom<usize> for ValueTag {
    type Error = TagOutOfBoundsError;

    fn try_from(value: usize) -> Result<Self, Self::Error> {
        if value <= ValueTag::MAX {
            // Safety: `#[repr(usize)]` on [ValueTag] guarantees that the enum is safe to transmute
            // to and from `usize`, as long as we are in the range of valid tags.
            Ok(unsafe { transmute::<usize, ValueTag>(value) })
        } else {
            Err(TagOutOfBoundsError)
        }
    }
}

/// Encode an inline value as a tagged pointer representation (a [NickelValue]).
const fn tag_inline(inline: u32) -> u32 {
    // Ensures the two highest bits of the inline value aren't set, so that `content << 2` doesn't
    // lose any information.
    debug_assert!(inline <= (u32::MAX >> 2));
    (inline << 2) | (ValueTag::Inline as u32)
}

/// Small Nickel values that can be inlined in the higher bits (excluding the tag) of the compact
/// representation of a Nickel value. Their numeric value is directly encoded with the tag
/// included, so that no bit shifting is needed at all when reading or writing them.
#[repr(u32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InlineValue {
    Null = tag_inline(0),
    True = tag_inline(1),
    False = tag_inline(2),
    EmptyArray = tag_inline(3),
    EmptyRecord = tag_inline(4),
}

/// The discriminating tag for the different kinds of data that can be store in a value block.
///////////
// CAUTION
///////////
// unsafe conversion functions from and to numeric types are relying on the `u8` representation,
// and precise values and range of `ValueTag`. If you add or remove tags, make sure to update all
// the corresponding code, in particular the `Self::MAX` constant.
//
// Values must be consecutive.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum DataTag {
    Number = 0,
    Array = 1,
    Record = 2,
    String = 3,
    Thunk = 4,
    /// This is a temporary optimization. We could always store a term as a thunk with an empty
    /// environment, but this requires additional allocation, indirection, etc. As long as we keep
    /// the hybrid term/value representation, we'll use [Self::Term] to inline a term with an empty
    /// environment, typically when converting the new AST to the runtime representation.
    Term = 5,
    Label = 6,
    EnumVariant = 7,
    ForeignId = 8,
    SealingKey = 9,
    CustomContract = 10,
    Type = 11,
}

impl DataTag {
    /// Returns the offset of the data in a value block from the start pointer (the header). Calls
    /// to [ValueBlockRc::data_offset] under the hood instantiated with the right type.
    const fn data_offset(&self) -> usize {
        match self {
            DataTag::Number => ValueBlockRc::data_offset::<NumberData>(),
            DataTag::String => ValueBlockRc::data_offset::<StringData>(),
            DataTag::Array => ValueBlockRc::data_offset::<ArrayData>(),
            DataTag::Record => ValueBlockRc::data_offset::<RecordData>(),
            DataTag::Thunk => ValueBlockRc::data_offset::<ThunkData>(),
            DataTag::Term => ValueBlockRc::data_offset::<TermData>(),
            DataTag::Label => ValueBlockRc::data_offset::<LabelData>(),
            DataTag::EnumVariant => ValueBlockRc::data_offset::<EnumVariantData>(),
            DataTag::ForeignId => ValueBlockRc::data_offset::<ForeignIdData>(),
            DataTag::SealingKey => ValueBlockRc::data_offset::<SealingKeyData>(),
            DataTag::CustomContract => ValueBlockRc::data_offset::<CustomContractData>(),
            DataTag::Type => ValueBlockRc::data_offset::<TypeData>(),
        }
    }

    /// Returns the layout to be used for (de)allocation of a whole value block for a given type of
    /// data. Calls to [ValueBlockRc::block_layout] under the hood instantiated with the right
    /// type.
    const fn block_layout(&self) -> Layout {
        match self {
            DataTag::Number => ValueBlockRc::block_layout::<NumberData>(),
            DataTag::String => ValueBlockRc::block_layout::<StringData>(),
            DataTag::Array => ValueBlockRc::block_layout::<ArrayData>(),
            DataTag::Record => ValueBlockRc::block_layout::<RecordData>(),
            DataTag::Thunk => ValueBlockRc::block_layout::<ThunkData>(),
            DataTag::Term => ValueBlockRc::block_layout::<TermData>(),
            DataTag::Label => ValueBlockRc::block_layout::<LabelData>(),
            DataTag::EnumVariant => ValueBlockRc::block_layout::<EnumVariantData>(),
            DataTag::ForeignId => ValueBlockRc::block_layout::<ForeignIdData>(),
            DataTag::SealingKey => ValueBlockRc::block_layout::<SealingKeyData>(),
            DataTag::CustomContract => ValueBlockRc::block_layout::<CustomContractData>(),
            DataTag::Type => ValueBlockRc::block_layout::<TypeData>(),
        }
    }

    /// The highest possible value (included) for [Self].
    const MAX: u8 = DataTag::Type as u8;
}

impl From<DataTag> for u8 {
    #[inline]
    fn from(tag: DataTag) -> Self {
        tag as u8
    }
}

impl TryFrom<u8> for DataTag {
    type Error = TagOutOfBoundsError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        if value <= DataTag::MAX {
            // Safety: `#[repr(u8)]` on `DataTag` guarantees that the enum is safe to transmute to
            // and from `u8`, as long as we are in the range of valid tags.
            Ok(unsafe { transmute::<u8, DataTag>(value) })
        } else {
            Err(TagOutOfBoundsError)
        }
    }
}

/// The header for a heap-allocated Nickel value which is laid out at the beginning of a value
/// block directly followed by the value data.
// We set a minimal alignment of `4` bytes, so that pointers to the content of a value block
// (which are aligned to the max of the alignment of `ValueBlockHeader` and the content) is
// guaranteed to have at least the last 2 bits free for tagging (although we currently only use one
// bit).
#[repr(Rust, align(4))]
#[derive(Debug, Clone, PartialEq, Eq)]
struct ValueBlockHeader {
    /// The tag determining the type and the layout of the data following the header in a value
    /// block, and the (strong) reference count of the value, packed in 64 bits. The 8 most
    /// significant bits represent the tag, and the remaining 56 bits the reference count.
    ///
    /// This packed representation proved to perform better (or play better with optimizations at
    /// least) than having `data: DataTag` followed by `ref_count: [u8; 7]`. This makes [Self]
    /// 8-bytes aligned, meaning that currently we waste 4 unused bytes in the header. However, it
    /// was already the case before with a 12 bytes, 4-bytes aligned header (since all data but
    /// [SealingKeyData] are 8-bytes aligned anyway, and the latter is very rare). We can also use
    /// this space later to store more information.
    tag_and_ref_count: Cell<u64>,
    /// The position index of the source position of the value.
    pos_idx: PosIdx,
}

impl ValueBlockHeader {
    const TAG_MASK: u64 = 0xFF_00_00_00_00_00_00_00;
    const MAX_REF_COUNT: u64 = 0x00_FF_FF_FF_FF_FF_FF_FF;

    /// Packs a data tagand a reference count together.
    ///
    /// # Safety
    ///
    /// This function doesn't check that the reference count is representable on 56 bits.
    /// `ref_count` must be smaller or equal to [Self::MAX_REF_COUNT], or the data tag might be
    /// later decoded to an invalid value.
    const unsafe fn pack(tag: DataTag, ref_count: u64) -> u64 {
        ((tag as u64) << 56) | ref_count
    }

    /// Returns the [DataTag] of this value block.
    #[inline]
    pub fn tag(&self) -> DataTag {
        // Safety: `DataTag` is `repr(u8)`, and we maintain the invariant that the higher 8 bits
        // of `self.tag_and_ref_count` stores a valid `DataTag` value.
        unsafe { transmute::<u8, DataTag>((self.tag_and_ref_count.get() >> 56) as u8) }
    }

    /// Creates a new header for a value block with the given tag, a reference count of 1 and the
    /// given position index.
    #[inline]
    pub fn new(tag: DataTag, pos_idx: PosIdx) -> Self {
        Self {
            // Safety: 1 is smaller than `Self::MAX_REF_COUNT`
            tag_and_ref_count: unsafe { Cell::new(Self::pack(tag, 1)) },
            pos_idx,
        }
    }

    #[inline]
    fn ref_count(&self) -> u64 {
        self.tag_and_ref_count.get() & !Self::TAG_MASK
    }

    #[inline]
    fn set_ref_count(&self, count: u64) {
        // Safety: we checked above that `count` is smaller or equal to `Self::MAX_REF_COUNT`.
        unsafe {
            self.tag_and_ref_count.set(Self::pack(self.tag(), count));
        }

        if count > Self::MAX_REF_COUNT {
            panic!("reference count overflow");
        }
    }

    #[inline]
    fn inc_ref_count(&self) {
        // The code and the tricks of this method are inspired (or downright copied) from
        // `std::rc::Rc`.
        let count = self.ref_count();

        // We insert an `assume` here to hint LLVM at an otherwise missed optimization.
        // SAFETY: The reference count will never be zero when this is called.
        unsafe {
            std::hint::assert_unchecked(count != 0);
        }

        self.set_ref_count(count + 1);
    }

    #[inline]
    fn dec_ref_count(&self) {
        self.set_ref_count(self.ref_count() - 1);
    }
}

/// Marker trait for the data that can be stored in a Nickel value block after the header.
pub trait ValueBlockData {
    const TAG: DataTag;
}

pub type NumberData = Number;
pub type StringData = NickelString;

#[derive(Clone, Debug, PartialEq, Default)]
pub struct ArrayData {
    pub array: Array,
    /// Arrays implement lazy contract application for performance reasons: contracts applied to
    /// this array are lazily accumulated in this field and only applied when an element is
    /// extracted.
    pub pending_contracts: Vec<RuntimeContract>,
}

impl ArrayData {
    /// Iterates over all values in the array, with pending contracts applied.
    pub fn iter_with_pending_contracts(
        &self,
        pos: PosIdx,
    ) -> impl Iterator<Item = NickelValue> + use<'_> {
        self.array.iter().map(move |v| {
            RuntimeContract::apply_all(v.clone(), self.pending_contracts.iter().cloned(), pos)
        })
    }
}

pub type ThunkData = RefCell<lazy::ThunkData>;
pub type TermData = Term;
pub type LabelData = Label;

#[derive(Clone, Debug, PartialEq)]
pub struct EnumVariantData {
    pub tag: LocIdent,
    pub arg: Option<NickelValue>,
}

pub type ForeignIdData = ForeignIdPayload;
pub type CustomContractData = NickelValue;
pub type SealingKeyData = SealingKey;

#[derive(Clone, Debug, PartialEq)]
pub struct TypeData {
    /// The static type.
    pub typ: Type,
    /// The conversion of this type to a contract, that is, `typ.contract()?`. This field
    /// serves as a caching mechanism so we only run the contract generation code once per type
    /// written by the user.
    pub contract: NickelValue,
}

impl ValueBlockData for NumberData {
    const TAG: DataTag = DataTag::Number;
}

impl ValueBlockData for ArrayData {
    const TAG: DataTag = DataTag::Array;
}

impl ValueBlockData for RecordData {
    const TAG: DataTag = DataTag::Record;
}

impl ValueBlockData for StringData {
    const TAG: DataTag = DataTag::String;
}

impl ValueBlockData for ThunkData {
    const TAG: DataTag = DataTag::Thunk;
}

impl ValueBlockData for TermData {
    const TAG: DataTag = DataTag::Term;
}

impl ValueBlockData for LabelData {
    const TAG: DataTag = DataTag::Label;
}

impl ValueBlockData for EnumVariantData {
    const TAG: DataTag = DataTag::EnumVariant;
}

impl ValueBlockData for ForeignIdData {
    const TAG: DataTag = DataTag::ForeignId;
}

impl ValueBlockData for CustomContractData {
    const TAG: DataTag = DataTag::CustomContract;
}

impl ValueBlockData for SealingKeyData {
    const TAG: DataTag = DataTag::SealingKey;
}

impl ValueBlockData for TypeData {
    const TAG: DataTag = DataTag::Type;
}

/// A pointer to a heap-allocated, reference-counted Nickel value of variable size, although the
/// size is a deterministic function of the tag stored in the header (first word of the block).
///
/// # Layout
///
/// In the following, the type `T : ValueBlockData` is uniquely determined by the tag in the
/// header.
///
/// A value block is laid out as follows:
///
/// ```text
/// -------------------+---------+---+
/// | ValueBlockHeader | padding | T |
/// -------------------+---------+---+
/// ```
///
/// The base address (`self.0`) is `max(align_of::<ValueBlockHeader>(), align_of::<T>())`-aligned.
/// The padding is determined statically and is only necessary if `size_of::<ValueBlockHeader>()`
/// isn't a multiple of the total alignment. Currently, for example, there is no padding on x86_64
/// in practice. It might happen if the alignment of `T` grows larger than the size of the header.
///
/// The content of padding is left uninitialized and should not be accessed.
pub struct ValueBlockRc(NonNull<u8>);

impl ValueBlockRc {
    /// Creates a new [Self] from a raw pointer.
    ///
    /// # Safety
    ///
    /// `ptr` must be a valid, non-null pointer to a value block.
    #[inline]
    pub unsafe fn from_raw(ptr: NonNull<u8>) -> Self {
        ValueBlockRc(ptr)
    }

    /// Returns the header of this value block.
    #[inline]
    fn header(&self) -> &ValueBlockHeader {
        // Safety: self.0 is always a valid pointer into a value block, and the lifetime of the
        // returned reference is tied to `&self`, guaranteeing that that the block will live as
        // long as the `&ValueBlockHeader` reference.
        unsafe { Self::header_from_raw(self.0) }
    }

    /// Returns the tag in the header of this value block.
    #[inline]
    fn tag(&self) -> DataTag {
        self.header().tag()
    }

    /// Returns the position index of this value.
    #[inline]
    pub fn pos_idx(&self) -> PosIdx {
        self.header().pos_idx
    }

    /// Returns a reference to the header of a value block pointed to by `ptr`.
    ///
    /// # Safety
    ///
    /// - `ptr` must be a valid pointer into a value block.
    /// - the corresponding value block must remain alive for `'a`.
    #[inline]
    unsafe fn header_from_raw<'a>(ptr: NonNull<u8>) -> &'a ValueBlockHeader {
        // Safety: the safety precondition of this function
        unsafe { ptr.cast::<ValueBlockHeader>().as_ref() }
    }

    /// Returns the tag in the header of a value block pointed to by `ptr`.
    ///
    /// # Safety
    ///
    /// - `ptr` must be a valid pointer into a value block.
    #[inline]
    unsafe fn tag_from_raw(ptr: NonNull<u8>) -> DataTag {
        // Safety: the safety precondition of this function
        unsafe { Self::header_from_raw(ptr).tag() }
    }

    /// Same as [std::rc::Rc::get_mut] but for a value block. Mutably borrows the value block.
    /// Returns an error if the tag doesn't match `T::Tag`.
    pub fn try_get_mut<T: ValueBlockData>(&mut self) -> Result<Option<&mut T>, TagMismatchError> {
        let header = self.header();

        if header.tag() != T::TAG {
            Err(TagMismatchError)
        } else if header.ref_count() != 1 {
            Ok(None)
        } else {
            // Safety: we know that the value block is unique, and we have a mutable borrow to the
            // only pointer to it, so we can safely decode the content to a mutable reference
            // without any risk of aliasing.
            unsafe { Ok(Some(self.decode_mut_unchecked::<T>())) }
        }
    }

    /// Panicking variant of [Self::try_get_mut]. Equivalent to
    /// `self.try_get_mut().unwrap().unwrap()`.
    #[inline]
    pub fn get_mut<T: ValueBlockData>(&mut self) -> &mut T {
        self.try_get_mut().unwrap().unwrap()
    }

    /// Same as [std::rc::Rc::make_mut] but for a value block. Returns `None` if the tag doesn't
    /// match `T::Tag`.
    pub fn try_make_mut<T: ValueBlockData + Clone>(&mut self) -> Option<&mut T> {
        if self.tag() != T::TAG {
            return None;
        }

        self.make_unique();
        // Safety: we know that the value block is unique, so we can safely decode the content
        // without any risk of aliasing.
        unsafe { Some(self.decode_mut_unchecked::<T>()) }
    }

    /// Panicking variant of [Self::try_make_mut]. Equivalent to `self.try_make_mut().unwrap()`.
    #[inline]
    pub fn make_mut<T: ValueBlockData + Clone>(&mut self) -> &mut T {
        self.try_make_mut().unwrap()
    }

    /// Makes `self` a unique (non shared) block, that is a 1-reference counted block with the same
    /// data. Similar to [Self::make_mut] in spirit but it doesn't require to specify the `T` and
    /// doesn't return a mutable reference.
    ///
    /// This is a no-op if `self` is 1-reference counted. Otherwise, a fresh (strong) copy is
    /// allocated and assigned to `self`.
    pub fn make_unique(&mut self) {
        if self.header().ref_count() == 1 {
            increment!("value::make_unique::no clone");
        } else {
            increment!("value::make_unique::strong clone");
            *self = self.strong_clone();
        }
    }

    /// Creates a copy of the content of this value block. As opposed to [Self::clone], which just
    /// increments the reference count but encapsulates a pointer to the same block in memory (as
    /// [std::rc::Rc::clone]), this method allocates a fresh block with a clone of the content and
    /// return a value that is 1-reference counted.
    pub fn strong_clone(&self) -> Self {
        match self.tag() {
            DataTag::Number => Self::encode(self.decode::<NumberData>().clone(), self.pos_idx()),
            DataTag::Array => Self::encode(self.decode::<ArrayData>().clone(), self.pos_idx()),
            DataTag::Record => Self::encode(self.decode::<RecordData>().clone(), self.pos_idx()),
            DataTag::String => Self::encode(self.decode::<StringData>().clone(), self.pos_idx()),
            DataTag::Thunk => Self::encode(self.decode::<ThunkData>().clone(), self.pos_idx()),
            DataTag::Term => Self::encode(self.decode::<TermData>().clone(), self.pos_idx()),
            DataTag::Label => Self::encode(self.decode::<LabelData>().clone(), self.pos_idx()),
            DataTag::EnumVariant => {
                Self::encode(self.decode::<EnumVariantData>().clone(), self.pos_idx())
            }
            DataTag::ForeignId => Self::encode(*self.decode::<ForeignIdData>(), self.pos_idx()),
            DataTag::SealingKey => Self::encode(*self.decode::<SealingKeyData>(), self.pos_idx()),
            DataTag::CustomContract => {
                Self::encode(self.decode::<CustomContractData>().clone(), self.pos_idx())
            }
            DataTag::Type => Self::encode(self.decode::<TypeData>().clone(), self.pos_idx()),
        }
    }

    /// Returns the required padding in bytes between the header and the data in [ValueBlockRc]
    /// depending on the tag. Calls to [ValueBlockRc::padding] under the hood instantiated with the
    /// right type.
    const fn padding<T: ValueBlockData>() -> usize {
        let align = Self::block_align::<T>();
        let leftover = size_of::<ValueBlockHeader>() % align;

        (align - leftover) % align
    }

    /// Returns the offset to add to the start of a value block (the address of the block header)
    /// to reach the data (including padding). Offsetting [Self::0] by [Self::data_offset]
    /// yields a valid pointer to a `T`.
    const fn data_offset<T: ValueBlockData>() -> usize {
        size_of::<ValueBlockHeader>() + Self::padding::<T>()
    }

    /// Returns the alignment in bytes of a value block for a given value content type `T`. This is
    /// the maximum of the alignment of the header and the alignment of `T`, and is guaranteed to
    /// be at least 4 bytes.
    const fn block_align<T: ValueBlockData>() -> usize {
        // Note: we can't use `std::cmp::max` in a const context
        if align_of::<ValueBlockHeader>() < align_of::<T>() {
            align_of::<T>()
        } else {
            align_of::<ValueBlockHeader>()
        }
    }

    /// Determines the layout for allocation or de-allocation of value blocks for a given value
    /// content type `T`.
    const fn block_layout<T: ValueBlockData>() -> Layout {
        let header_layout = Layout::new::<ValueBlockHeader>();
        let data_layout = Layout::new::<T>();
        let size = header_layout.size() + Self::padding::<T>() + data_layout.size();

        // The check is not tight (technically, there are a few valid size values for Layout that
        // will fail this assert) but it's simpler and the few corner cases don't matter in
        // practice.
        assert!(
            size + Self::block_align::<T>() <= isize::MAX as usize,
            "value block size overflow"
        );

        // Safety: align is the max of existing valid alignments, so it's a power of 2. The assert
        // above ensures that the nearest multiple of the alignment after `size` is less than
        // `isize::MAX`.
        unsafe { Layout::from_size_align_unchecked(size, Self::block_align::<T>()) }
    }

    /// Allocates a new value block with the given value `T` as content.
    fn encode<T: ValueBlockData>(value: T, pos_idx: PosIdx) -> Self {
        unsafe {
            // Safety: the layout of a block verifies `size > 0`
            let start = alloc(Self::block_layout::<T>());

            if start.is_null() {
                panic!("out of memory: failed to allocate memory for Nickel value")
            }

            let header_ptr = start as *mut ValueBlockHeader;
            header_ptr.write(ValueBlockHeader::new(T::TAG, pos_idx));

            // Safety: layout computations are correct (hopefully)
            let data_layout = start.add(Self::data_offset::<T>()) as *mut T;
            data_layout.write(value);

            // Safety: we abort if `start.is_null()` above, so `start` is not null
            Self(NonNull::new_unchecked(start))
        }
    }

    /// Tries to decode this value block as a reference to a value of type `T`. Returns `None` if
    /// the tag of this value block is not `T::TAG`.
    #[inline]
    fn try_decode<T: ValueBlockData>(&self) -> Option<&T> {
        // Safety: we decode only if `self.tag()` is `T::TAG`
        (self.tag() == T::TAG).then(|| unsafe { self.decode_unchecked() })
    }

    /// Panicking variant of [Self::try_decode]. Same as `self.try_decode().unwrap()`.
    #[inline]
    #[track_caller]
    fn decode<T: ValueBlockData>(&self) -> &T {
        self.try_decode().unwrap()
    }

    /// Unsafe variant of [Self::try_decode]. Doesn't perform any tag check, and blindly tries to
    /// decode the content of this block to a `&T`.
    ///
    /// # Safety
    ///
    /// The content of this value block must have been encoded from a value of type `T`, that is
    /// `self.tag() == T::TAG`.
    #[inline]
    unsafe fn decode_unchecked<T: ValueBlockData>(&self) -> &T {
        // Safety: preconditions
        unsafe { Self::decode_from_raw_unchecked(self.0) }
    }

    /// Mutable variant of [Self::decode_unchecked] (or unsafe variant of [Self::get_mut]).
    ///
    /// # Safety
    ///
    /// - The content of this value block must have been encoded from a value of type `T`, that is
    ///   `self.tag() == T::TAG`.
    /// - You must ensure that there is no active mutable reference inside this value block as long
    ///   as the returned mutable reference is alive. This is typically the case if the reference
    ///   count of the value block is 1.
    #[inline]
    unsafe fn decode_mut_unchecked<T: ValueBlockData>(&mut self) -> &mut T {
        // Safety: preconditions
        unsafe { Self::decode_mut_from_raw_unchecked(self.0) }
    }

    /// Given a pointer into a value block, blindly tries to decode the content to a `T` bypassing all safety checks.
    ///
    /// # Safety
    ///
    /// - The content of this value block must have been encoded from a value of type `T`, that is
    ///   `self.tag() == T::TAG`.
    /// - The lifetime `'a` of the returned reference must not outlive the value block.
    /// - The value block content must not be mutably borrowed during the lifetime `'a`.
    #[inline]
    unsafe fn decode_from_raw_unchecked<'a, T: ValueBlockData>(ptr: NonNull<u8>) -> &'a T {
        // Safety: preconditions
        unsafe { ptr.add(Self::data_offset::<T>()).cast::<T>().as_ref() }
    }

    /// Mutable variant of [Self::decode_from_raw_unchecked].
    ///
    /// # Safety
    ///
    /// - The content of this value block must have been encoded from a value of type `T`, that is
    ///   `self.tag() == T::TAG`.
    /// - The lifetime `'a` of the returned reference must not outlive the value block.
    /// - You must ensure that there is no active mutable reference inside this value block as long
    ///   as the returned mutable reference is alive (during `'a`). This is typically satisfied if
    ///   the reference count of the value block is `1`.
    #[inline]
    unsafe fn decode_mut_from_raw_unchecked<'a, T: ValueBlockData>(ptr: NonNull<u8>) -> &'a mut T {
        // Safety: preconditions
        unsafe { ptr.add(Self::data_offset::<T>()).cast::<T>().as_mut() }
    }

    /// Given a pointer into a value block, tries to decode the content to a `T`. Returns `None` if
    /// the tag of this value block is not `T::TAG`.
    ///
    /// Same as [Self::try_decode], but takes a raw (non-null) pointer instead of a value block.
    ///
    /// # Safety
    ///
    /// - The lifetime `'a` of the returned reference must not outlive the value block
    /// - The value block content must not be mutably borrowed during the lifetime `'a`.
    #[inline]
    unsafe fn try_decode_from_raw<'a, T: ValueBlockData>(ptr: NonNull<u8>) -> Option<&'a T> {
        // Safety: we've checked that the tag matched `T`. The rest of the safety conditions are
        // the pre-conditions of the current function `try_decode`.
        unsafe { (Self::tag_from_raw(ptr) == T::TAG).then(|| Self::decode_from_raw_unchecked(ptr)) }
    }

    // Non-inlined part of drop. Splitting the inlined and slow part is inspired from `std::rc::Rc`
    // code.
    #[inline(never)]
    unsafe fn drop_slow(&mut self) {
        unsafe {
            let tag = self.tag();
            // Safety: the value block is guaranteed to have been allocated with a size of
            // `size_of::<ValueBlockHeader>()` + `padding` + `size_of::<T>()`.
            let data_ptr = self.0.as_ptr().add(tag.data_offset());

            // Safety: `data_ptr` is a valid pointer for the corresponding type and it hasn't
            // been dropped before, as it's only dropped once when the last reference goes out
            // of scope.
            match tag {
                DataTag::Number => {
                    ptr::drop_in_place(data_ptr as *mut NumberData);
                }
                DataTag::Array => {
                    ptr::drop_in_place(data_ptr as *mut ArrayData);
                }
                DataTag::Record => {
                    ptr::drop_in_place(data_ptr as *mut RecordData);
                }
                DataTag::String => {
                    ptr::drop_in_place(data_ptr as *mut StringData);
                }
                DataTag::Thunk => {
                    ptr::drop_in_place(data_ptr as *mut ThunkData);
                }
                DataTag::Term => {
                    ptr::drop_in_place(data_ptr as *mut TermData);
                }
                DataTag::Label => {
                    ptr::drop_in_place(data_ptr as *mut LabelData);
                }
                DataTag::EnumVariant => {
                    ptr::drop_in_place(data_ptr as *mut EnumVariantData);
                }
                DataTag::ForeignId => {
                    ptr::drop_in_place(data_ptr as *mut ForeignIdData);
                }
                DataTag::CustomContract => {
                    ptr::drop_in_place(data_ptr as *mut CustomContractData);
                }
                DataTag::SealingKey => {
                    ptr::drop_in_place(data_ptr as *mut SealingKeyData);
                }
                DataTag::Type => {
                    ptr::drop_in_place(data_ptr as *mut TypeData);
                }
            };

            dealloc(self.0.as_ptr(), tag.block_layout());
        }
    }
}

impl Drop for ValueBlockRc {
    #[inline]
    fn drop(&mut self) {
        self.header().dec_ref_count();

        if self.header().ref_count() == 0 {
            unsafe {
                self.drop_slow();
            }
        }
    }
}

impl Clone for ValueBlockRc {
    #[inline]
    fn clone(&self) -> Self {
        self.header().inc_ref_count();
        Self(self.0)
    }
}

/// Empty containers are inlined, but this should be an implementation detail as much as possible.
/// This generic handler is providing a uniform interface to a container, that can either be
/// inlined as empty, or allocated (note that an allocated container can still be empty!).
#[derive(Clone, PartialEq, Debug, Copy)]
pub enum Container<C> {
    /// An empty, inlined value.
    Empty,
    /// An allocated container. **Note that an allocated container can still be empty as a container**:
    /// for example, an open record `{..}` needs to be allocated to store the open attribute, but
    /// will have an empty underlying map.
    Alloc(C),
}

impl<C> Container<C> {
    /// Converts this container to an optional. Returns `None` if `self` is [Container::Empty], and
    /// `Some` otherwise.
    pub fn into_opt(self) -> Option<C> {
        match self {
            Container::Empty => None,
            Container::Alloc(c) => Some(c),
        }
    }

    /// Unwrap the underlying allocation, or panics if `self` is [Self::Empty].
    #[inline]
    pub fn unwrap_alloc(self) -> C {
        self.into_opt().unwrap()
    }
}

impl<C: Default> Container<C> {
    /// Unwrap the underlying container, or allocate a new empty one (via [Default]) if `self` is
    /// [Container::Empty].
    #[inline]
    pub fn unwrap_or_alloc(self) -> C {
        self.into_opt().unwrap_or_default()
    }
}

impl<C: ToOwned> Container<&C> {
    /// Clones the underlying container if `self` is [Self::Alloc], or returns [Self::Empty]
    /// otherwise.
    pub fn to_owned(&self) -> Container<C::Owned> {
        match self {
            Container::Empty => Container::Empty,
            Container::Alloc(c) => Container::Alloc((*c).to_owned()),
        }
    }
}

impl Container<&RecordData> {
    /// Retrieves a field from [crate::term::record::RecordData::fields], or returns `None` if `self`
    /// is [Self::Empty].
    pub fn get(&self, id: LocIdent) -> Option<&Field> {
        self.into_opt().and_then(|record| record.fields.get(&id))
    }

    /// Returns a vector of all the fields' names of this record sorted alphabetically. Returns an
    /// empty vector if `self` is [Self::Empty].
    pub fn field_names(&self, op_kind: RecordOpKind) -> Vec<LocIdent> {
        self.into_opt()
            .map(|record| record.field_names(op_kind))
            .unwrap_or_default()
    }

    /// Returns the length of the underlying record.
    pub fn len(&self) -> usize {
        self.into_opt().map_or(0, |record| record.fields.len())
    }

    /// Checks if this record is [Self::Empty], or is [Self::Alloc] where the underlying record is
    /// empty (is such that [RecordData::is_empty] returns `true`).
    pub fn is_empty(&self) -> bool {
        match self {
            Container::Empty => true,
            Container::Alloc(record) => record.is_empty(),
        }
    }

    /// Checks if this record is [Self::Empty], or is [Self::Alloc] where the underlying record is
    /// empty or has only empty optional fields (is such that [RecordData::has_only_empty_opts]
    /// returns `true`).
    pub fn has_only_empty_opts(&self) -> bool {
        match self {
            Container::Empty => true,
            Container::Alloc(record) => record.has_only_empty_opts(),
        }
    }
}

impl Container<&ArrayData> {
    /// Iterates over the elements of the array.
    pub fn iter(&self) -> impl Iterator<Item = &NickelValue> {
        self.into_opt()
            .into_iter()
            .flat_map(|array_data| array_data.array.iter())
    }

    /// Iterates over the elements of the array, with pending contracts applied.
    pub fn iter_with_pending_contracts(&self, pos: PosIdx) -> impl Iterator<Item = NickelValue> {
        self.into_opt()
            .into_iter()
            .flat_map(move |array_data| array_data.iter_with_pending_contracts(pos))
    }

    /// Iterates over the pending contracts.
    pub fn iter_pending_contracts(&self) -> impl Iterator<Item = &RuntimeContract> {
        self.into_opt()
            .into_iter()
            .flat_map(|array_data| array_data.pending_contracts.iter())
    }

    /// Retrieves an element from the underlying array at the given index, or returns `None` if `self`
    /// is [Self::Empty].
    pub fn get(&self, idx: usize) -> Option<&NickelValue> {
        self.into_opt()
            .and_then(|array_data| array_data.array.get(idx))
    }

    /// Returns the length of the underlying array.
    pub fn len(&self) -> usize {
        self.into_opt()
            .map_or(0, |array_data| array_data.array.len())
    }

    /// Checks if this record is [Self::Empty], or is [Self::Alloc] where the underlying array is
    /// empty (is such that [Array::is_empty] returns `true`).
    pub fn is_empty(&self) -> bool {
        match self {
            Container::Empty => true,
            Container::Alloc(array_data) => array_data.array.is_empty(),
        }
    }
}

/// An enum representation of a decoded Nickel value. This is useful to match on a general value in
/// a typed way.
///
/// Note that we only ever store references to the content of a value block here, or 1-word inline
/// values, so this enum is compact and doesn't defeat the purpose of the whole value encoding
/// (beside the fact that [ValueContentRef] is only materialized temporarily by helpers and not a
/// standard value representation). This is still true for `Container<ref>` values, thanks to the
/// niche optimizatio of rustc: [Self] is 16 bytes wide.
#[derive(Clone, Copy, Debug)]
pub enum ValueContentRef<'a> {
    Null,
    Bool(bool),
    Number(&'a NumberData),
    Array(Container<&'a ArrayData>),
    Record(Container<&'a RecordData>),
    String(&'a StringData),
    Thunk(&'a Thunk),
    Term(&'a TermData),
    Label(&'a LabelData),
    EnumVariant(&'a EnumVariantData),
    ForeignId(&'a ForeignIdData),
    SealingKey(&'a SealingKeyData),
    CustomContract(&'a CustomContractData),
    Type(&'a TypeData),
}

/// Mutable version of [ValueContentRef].
pub enum ValueContentRefMut<'a> {
    /// Given the encoding of inline values, it's a bad idea to provide a bare Rust reference to
    /// the underlying data encoding the inline value. While it's possible currently, we might use
    /// a more exotic layout in the future making it impossible to produce a valid Rust reference
    /// to an [InlineValue].
    ///
    /// A mutable reference is mostly useful for value blocks anyway. For inline values, we just
    /// return the original value back. It can be overridden directly with a new inline value.
    ///
    /// Note that the empty array case and the empty record case are handled by the [Container]
    /// part in [Self::Array] and [Self::Record].
    Null(&'a mut NickelValue),
    Bool(&'a mut NickelValue),
    Number(&'a mut NumberData),
    Array(Container<&'a mut ArrayData>),
    Record(Container<&'a mut RecordData>),
    String(&'a mut StringData),
    Thunk(&'a mut Thunk),
    Term(&'a mut TermData),
    Label(&'a mut LabelData),
    EnumVariant(&'a mut EnumVariantData),
    ForeignId(&'a mut ForeignIdData),
    SealingKey(&'a mut SealingKeyData),
    CustomContract(&'a mut CustomContractData),
    Type(&'a mut TypeData),
}

/// A lazy handle to the owned content of a value block.
///
/// It's a common pattern to need to move the content out of a block (copying the content if it's
/// shared, but avoiding copy if it's unique, like [std::rc::Rc::unwrap_or_clone]) only if a value
/// matches some pattern. Typically during program transformations, where blocks should always be
/// 1-reference counted, and where one transformation only affects specific nodes.
///
/// This is the *lazy* part: while the type of the data is known, the content is hidden behind a
/// lazy handle, which can either be unwrapped further - consuming the original value irreversibly
/// and producing an owned version of the data - or reverted back to the original value.
pub enum ValueContent {
    /// It can seem useless to carry a lens here, since there's no real data to take out. However,
    /// it's important to keep the ability to restore a [Self] value to the original [NickelValue],
    /// which is precisely the role of the lens.
    Null(lens::ValueLens<()>),
    Bool(lens::ValueLens<bool>),
    Number(lens::ValueLens<NumberData>),
    Array(lens::ValueLens<Container<ArrayData>>),
    Record(lens::ValueLens<Container<RecordData>>),
    String(lens::ValueLens<StringData>),
    Thunk(lens::ValueLens<Thunk>),
    Term(lens::TermContent),
    Label(lens::ValueLens<LabelData>),
    EnumVariant(lens::ValueLens<EnumVariantData>),
    ForeignId(lens::ValueLens<ForeignIdData>),
    SealingKey(lens::ValueLens<SealingKeyData>),
    CustomContract(lens::ValueLens<CustomContractData>),
    Type(lens::ValueLens<TypeData>),
}

impl ValueContent {
    /// Do not access the content and restore the original value unchanged.
    pub fn restore(self) -> NickelValue {
        match self {
            ValueContent::Null(lens) => lens.restore(),
            ValueContent::Bool(lens) => lens.restore(),
            ValueContent::Number(lens) => lens.restore(),
            ValueContent::Array(lens) => lens.restore(),
            ValueContent::Record(lens) => lens.restore(),
            ValueContent::String(lens) => lens.restore(),
            ValueContent::Thunk(lens) => lens.restore(),
            ValueContent::Term(lens) => lens.restore(),
            ValueContent::Label(lens) => lens.restore(),
            ValueContent::EnumVariant(lens) => lens.restore(),
            ValueContent::ForeignId(lens) => lens.restore(),
            ValueContent::SealingKey(lens) => lens.restore(),
            ValueContent::CustomContract(lens) => lens.restore(),
            ValueContent::Type(lens) => lens.restore(),
        }
    }
}

impl Traverse<NickelValue> for NickelValue {
    fn traverse<F, E>(self, f: &mut F, order: TraverseOrder) -> Result<Self, E>
    where
        F: FnMut(NickelValue) -> Result<NickelValue, E>,
    {
        let value = match order {
            TraverseOrder::TopDown => f(self)?,
            TraverseOrder::BottomUp => self,
        };

        let pos_idx = value.pos_idx();

        let result = match value.content() {
            lens @ (ValueContent::Null(_)
            | ValueContent::Bool(_)
            | ValueContent::Number(_)
            | ValueContent::String(_)
            | ValueContent::Label(_)
            | ValueContent::Thunk(_)
            | ValueContent::SealingKey(_)
            | ValueContent::ForeignId(_)) => lens.restore(),
            ValueContent::Array(lens) if lens.value().is_inline_empty_array() => lens.restore(),
            ValueContent::Record(lens) if lens.value().is_inline_empty_record() => lens.restore(),
            ValueContent::Term(lens) => {
                let term = lens.take();
                let term = term.traverse(f, order)?;
                NickelValue::term(term, pos_idx)
            }
            ValueContent::Record(lens) => {
                //unwrap(): we already treated the empty case above, so if we end up here, the
                //container must be non-empty, and `into_opt()` must return `Some`.
                let record = lens.take().into_opt().unwrap();

                // The annotation on `fields_res` uses Result's corresponding trait to convert from
                // Iterator<Result> to a Result<Iterator>
                let fields: Result<IndexMap<LocIdent, Field>, E> = record
                    .fields
                    .into_iter()
                    // For the conversion to work, note that we need a Result<(Ident,RichTerm), E>
                    .map(|(id, field)| Ok((id, field.traverse(f, order)?)))
                    .collect();
                NickelValue::record(
                    RecordData::new_shared_tail(fields?, record.attrs, record.sealed_tail),
                    pos_idx,
                )
            }
            ValueContent::Array(lens) => {
                //unwrap(): we already treated the empty case above, so if we end up here, the
                //container must be non-empty, and `into_opt()` must return `Some`.
                let ArrayData {
                    array,
                    pending_contracts,
                } = lens.take().into_opt().unwrap();

                let array = array
                    .into_iter()
                    .map(|t| t.traverse(f, order))
                    .collect::<Result<Array, _>>()?;

                // We don't recurse into pending contracts currently
                NickelValue::array(array, pending_contracts, pos_idx)
            }
            ValueContent::Type(lens) => {
                let TypeData { typ, contract } = lens.take();
                let typ = typ.traverse(f, order)?;
                let contract = contract.traverse(f, order)?;

                NickelValue::typ(typ, contract, pos_idx)
            }
            ValueContent::EnumVariant(lens) => {
                let EnumVariantData { tag, arg } = lens.take();
                let arg = arg.map(|arg| arg.traverse(f, order)).transpose()?;
                NickelValue::enum_variant(tag, arg, pos_idx)
            }
            ValueContent::CustomContract(lens) => {
                let ctr = lens.take();
                let ctr = ctr.traverse(f, order)?;
                NickelValue::custom_contract(ctr, pos_idx)
            }
        };

        match order {
            TraverseOrder::TopDown => Ok(result),
            TraverseOrder::BottomUp => f(result),
        }
    }

    fn traverse_ref<S, U>(
        &self,
        f: &mut dyn FnMut(&NickelValue, &S) -> TraverseControl<S, U>,
        scope: &S,
    ) -> Option<U> {
        let child_scope = match f(self, scope) {
            TraverseControl::Continue => None,
            TraverseControl::ContinueWithScope(s) => Some(s),
            TraverseControl::SkipBranch => {
                return None;
            }
            TraverseControl::Return(ret) => {
                return Some(ret);
            }
        };

        let scope = child_scope.as_ref().unwrap_or(scope);

        match self.content_ref() {
            ValueContentRef::Null
            | ValueContentRef::Bool(_)
            | ValueContentRef::Array(Container::Empty)
            | ValueContentRef::Record(Container::Empty)
            | ValueContentRef::Number(_)
            | ValueContentRef::String(_)
            | ValueContentRef::Label(_)
            | ValueContentRef::Thunk(_)
            | ValueContentRef::SealingKey(_)
            | ValueContentRef::EnumVariant(EnumVariantData { arg: None, .. })
            | ValueContentRef::ForeignId(_) => None,
            ValueContentRef::EnumVariant(EnumVariantData { arg: Some(v), .. })
            | ValueContentRef::CustomContract(v) => v.traverse_ref(f, scope),
            ValueContentRef::Array(Container::Alloc(array_data)) => array_data
                .array
                .iter()
                .find_map(|t| t.traverse_ref(f, scope)),
            ValueContentRef::Type(TypeData { typ, contract }) => {
                typ.traverse_ref(f, scope)?;
                contract.traverse_ref(f, scope)
            }
            ValueContentRef::Record(Container::Alloc(data)) => data
                .fields
                .values()
                .find_map(|field| field.traverse_ref(f, scope)),
            ValueContentRef::Term(term) => term.traverse_ref(f, scope),
        }
    }
}

impl Traverse<Type> for NickelValue {
    fn traverse<F, E>(self, f: &mut F, order: TraverseOrder) -> Result<NickelValue, E>
    where
        F: FnMut(Type) -> Result<Type, E>,
    {
        self.traverse(
            &mut |value: NickelValue| {
                let pos_idx = value.pos_idx();

                match value.content() {
                    ValueContent::Type(lens) => {
                        let TypeData { typ, contract } = lens.take();
                        let typ = typ.traverse(f, order)?;
                        Ok(NickelValue::typ(typ, contract, pos_idx))
                    }
                    lens => Ok(lens.restore()),
                }
            },
            order,
        )
    }

    fn traverse_ref<S, U>(
        &self,
        f: &mut dyn FnMut(&Type, &S) -> TraverseControl<S, U>,
        state: &S,
    ) -> Option<U> {
        self.traverse_ref(
            &mut |value: &NickelValue, state: &S| {
                if let Some(TypeData { typ, contract: _ }) = value.as_type() {
                    typ.traverse_ref(f, state).into()
                } else {
                    TraverseControl::Continue
                }
            },
            state,
        )
    }
}

impl From<Term> for NickelValue {
    fn from(term: Term) -> Self {
        NickelValue::term_posless(term)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::position::RawSpan;

    #[test]
    fn inline_values() {
        use crate::files::Files;

        let inline_null = NickelValue::null();
        let inline_true = NickelValue::bool_true();
        let inline_false = NickelValue::bool_false();
        let inline_empty_array = NickelValue::empty_array();
        let inline_empty_record = NickelValue::empty_record();

        assert_eq!(inline_null.tag(), ValueTag::Inline);
        assert_eq!(inline_true.tag(), ValueTag::Inline);
        assert_eq!(inline_false.tag(), ValueTag::Inline);
        assert_eq!(inline_empty_array.tag(), ValueTag::Inline);
        assert_eq!(inline_empty_record.tag(), ValueTag::Inline);

        assert_eq!(inline_null.as_inline(), Some(InlineValue::Null));
        assert_eq!(inline_true.as_inline(), Some(InlineValue::True));
        assert_eq!(inline_false.as_inline(), Some(InlineValue::False));
        assert_eq!(
            inline_empty_array.as_inline(),
            Some(InlineValue::EmptyArray)
        );
        assert_eq!(
            inline_empty_record.as_inline(),
            Some(InlineValue::EmptyRecord)
        );

        let dummy_pos = TermPos::Original(RawSpan {
            src_id: Files::empty().add("<test>", String::from("empty")),
            start: 0.into(),
            end: 1.into(),
        });

        let mut pos_table = PosTable::new();

        // Makes sure the values are what we expect, and that `phys_eq` properly ignores position
        // information (we create a fresh position index for each value).
        assert!(
            inline_null
                .clone()
                .with_inline_pos_idx(pos_table.push(dummy_pos))
                .phys_eq(&NickelValue::null().with_inline_pos_idx(pos_table.push(dummy_pos)))
        );
        assert!(
            inline_true
                .with_inline_pos_idx(pos_table.push(dummy_pos))
                .phys_eq(&NickelValue::bool_true().with_inline_pos_idx(pos_table.push(dummy_pos)))
        );
        assert!(
            inline_false
                .with_inline_pos_idx(pos_table.push(dummy_pos))
                .phys_eq(&NickelValue::bool_false().with_inline_pos_idx(pos_table.push(dummy_pos)))
        );
        assert!(
            inline_empty_array
                .with_inline_pos_idx(pos_table.push(dummy_pos))
                .phys_eq(
                    &NickelValue::empty_array().with_inline_pos_idx(pos_table.push(dummy_pos))
                )
        );
        assert!(
            inline_empty_record
                .with_inline_pos_idx(pos_table.push(dummy_pos))
                .phys_eq(
                    &NickelValue::empty_record().with_inline_pos_idx(pos_table.push(dummy_pos))
                )
        );

        assert!(!inline_null.phys_eq(&NickelValue::bool_true()));
    }

    #[test]
    fn basic_value_blocks() {
        let number_value = NickelValue::number_posless(42);
        let string_value = NickelValue::string_posless("Hello, World!");

        assert_eq!(number_value.tag(), ValueTag::Pointer);
        assert_eq!(string_value.tag(), ValueTag::Pointer);

        assert_eq!(number_value.as_number().unwrap(), &Number::from(42));
        assert_eq!(
            string_value.as_string().unwrap(),
            &NickelString::from("Hello, World!")
        );

        assert!(number_value.as_string().is_none());
        assert!(string_value.as_number().is_none());
    }

    #[test]
    fn ref_counting() {
        let number_value = NickelValue::number_posless(42);

        let mut copies =
            std::array::from_fn::<_, 20, _>(|_| ManuallyDrop::new(number_value.clone()));

        let mut as_val = number_value.into_block().unwrap();
        assert_eq!(as_val.header().ref_count(), 21);

        let mut block_copy = ManuallyDrop::new(as_val.clone());

        assert_eq!(as_val.header().ref_count(), 22);

        assert!(as_val.try_get_mut::<NumberData>().unwrap().is_none());

        for copy in copies.iter_mut().take(10) {
            unsafe {
                ManuallyDrop::drop(copy);
            }
        }

        assert_eq!(as_val.header().ref_count(), 12);

        for copy in copies.iter_mut().skip(10) {
            unsafe {
                ManuallyDrop::drop(copy);
            }
        }

        let mut cow = as_val.clone();
        *cow.make_mut() = Number::from(0);

        // The original value wasn't 1-RCed, so it should be left unchanged and cow must be a
        // separate copy.
        assert_eq!(as_val.header().ref_count(), 2);
        assert_eq!(as_val.decode::<NumberData>(), &Number::from(42));
        assert_eq!(cow.header().ref_count(), 1);
        assert_eq!(cow.decode::<NumberData>(), &Number::from(0));

        unsafe { ManuallyDrop::drop(&mut block_copy) }

        *as_val.get_mut() = Number::from(100);
        assert_eq!(as_val.header().ref_count(), 1);
        assert_eq!(as_val.decode::<NumberData>(), &Number::from(100));
    }

    #[test]
    fn in_place_modification() {
        // We make the containers non-empty so that they're not inlined.
        let mut record_data = RecordData::default();
        record_data
            .fields
            .insert(LocIdent::from("hello"), Default::default());
        let mut array_data = Array::default();
        array_data.push(NickelValue::null());

        let record = NickelValue::record_posless(record_data);
        let array = NickelValue::array_posless(array_data, Vec::new());

        let mut record_value = record.into_block().unwrap();
        let mut array_value = array.into_block().unwrap();

        assert_eq!(record_value.decode::<RecordData>().fields.len(), 1);
        assert_eq!(array_value.decode::<ArrayData>().array.len(), 1);

        record_value
            .get_mut::<RecordData>()
            .fields
            .insert(LocIdent::from("world"), Default::default());
        array_value
            .get_mut::<ArrayData>()
            .array
            .push(NickelValue::null());

        let array_copy = array_value.clone();
        let record_copy = record_value.clone();

        assert_eq!(record_copy.decode::<RecordData>().fields.len(), 2);
        assert_eq!(array_copy.decode::<ArrayData>().array.len(), 2);
    }

    #[test]
    fn in_place_modification_with_content_ref() {
        // We make the containers non-empty so that they're not inlined.
        let mut record_data = RecordData::default();
        record_data
            .fields
            .insert(LocIdent::from("hello"), Default::default());
        let mut array_data = Array::default();
        array_data.push(NickelValue::null());

        let mut record = NickelValue::record_posless(record_data);
        let mut array = NickelValue::array_posless(array_data, Vec::new());

        assert_eq!(record.as_record().unwrap().unwrap_alloc().fields.len(), 1);
        assert_eq!(array.as_array().unwrap().unwrap_alloc().array.len(), 1);

        if let Some(ValueContentRefMut::Record(Container::Alloc(record))) = record.content_mut() {
            record
                .fields
                .insert(LocIdent::from("world"), Default::default());
        } else {
            panic!("Expected RecordData");
        }

        if let Some(ValueContentRefMut::Array(Container::Alloc(array_data))) = array.content_mut() {
            array_data.array.push(NickelValue::null());
        } else {
            panic!("Expected ArrayData");
        }

        let array_copy = array.clone();
        let record_copy = record.clone();

        assert_eq!(record_copy.as_record().unwrap().len(), 2);
        assert_eq!(array_copy.as_array().unwrap().len(), 2);
    }

    #[test]
    fn content_make_mut() {
        // We make the containers non-empty so that they're not inlined.
        let mut record_data = RecordData::default();
        record_data
            .fields
            .insert(LocIdent::from("hello"), Default::default());
        let mut array_data = Array::default();
        array_data.push(NickelValue::null());

        let mut record = NickelValue::record_posless(record_data);
        let mut array = NickelValue::array_posless(array_data, Vec::new());
        let array_copy = array.clone();

        assert_eq!(record.as_record().unwrap().unwrap_alloc().fields.len(), 1);
        assert_eq!(array.as_array().unwrap().unwrap_alloc().array.len(), 1);

        if let ValueContentRefMut::Record(Container::Alloc(record)) = record.content_make_mut() {
            record
                .fields
                .insert(LocIdent::from("world"), Default::default());
        } else {
            panic!("Expected RecordData");
        }

        if let ValueContentRefMut::Array(Container::Alloc(array_data)) = array.content_make_mut() {
            array_data.array.push(NickelValue::null());
        } else {
            panic!("Expected ArrayData");
        }

        let record_copy = record.clone();

        assert_eq!(record.as_record().unwrap().len(), 2);
        assert_eq!(record_copy.as_record().unwrap().len(), 2);
        assert_eq!(array.as_array().unwrap().len(), 2);
        // The copy was made before the call to `content_make_mut`, so it must have been preserved.
        assert_eq!(array_copy.as_array().unwrap().len(), 1);
    }

    #[test]
    fn empty_containers_are_inlined() {
        let empty_record = NickelValue::record_posless(RecordData::default());
        let empty_array = NickelValue::array_posless(Array::default(), Vec::new());

        assert_eq!(empty_record.tag(), ValueTag::Inline);
        assert_eq!(empty_array.tag(), ValueTag::Inline);

        assert_eq!(empty_record.as_inline(), Some(InlineValue::EmptyRecord));
        assert_eq!(empty_array.as_inline(), Some(InlineValue::EmptyArray));
    }
}//! In a lazy language like Nickel, there are no well delimited stack frames due to how function
//! application is evaluated. Additional information about the history of function calls is thus
//! stored in a call stack solely for better error reporting.
use crate::{
    files::Files,
    identifier::LocIdent,
    position::{PosIdx, PosTable, RawSpan, TermPos},
};

/// A call stack, saving the history of function calls.
///
/// # Size
///
/// The callstack length is assumed to be smaller at most `u32::MAX`, which allows to store indices
/// in a more compact way on the eval stack. Any method leading to a push that reaches this size
/// will currently panic.
#[derive(PartialEq, Eq, Clone, Default, Debug)]
pub struct CallStack(pub Vec<StackElem>);

/// Basic description of a function call. Used for error reporting.
pub struct CallDescr {
    /// The name of the called function, if any.
    pub head: Option<LocIdent>,
    /// The position of the application.
    pub span: RawSpan,
}

/// A call stack element.
#[derive(Debug, Clone, Eq, PartialEq)]
pub enum StackElem {
    /// A function body was entered. The position is the position of the original application.
    Fun(PosIdx),
    /// An application was evaluated.
    App(PosIdx),
    /// A variable was entered.
    Var { id: LocIdent, pos: PosIdx },
    /// A record field was entered.
    Field {
        id: LocIdent,
        pos_record: PosIdx,
        pos_field: PosIdx,
        pos_access: PosIdx,
    },
}

impl CallStack {
    pub fn new() -> Self {
        CallStack(Vec::new())
    }

    /// Pushes an element to the stack, or panic if the size of the call stack is [u32::MAX].
    fn push(&mut self, elem: StackElem) {
        if self.0.len() == u32::MAX as usize {
            panic!("max call stack size reached");
        }

        self.0.push(elem);
    }

    /// Push a marker to indicate that a var was entered.
    pub fn enter_var(&mut self, id: LocIdent, pos: PosIdx) {
        self.push(StackElem::Var { id, pos });
    }

    /// Push a marker to indicate that an application was entered.
    pub fn enter_app(&mut self, pos_table: &PosTable, pos: PosIdx) {
        // We ignore application without positions, which have been generated by the interpreter.
        if pos_table.get(pos).is_def() {
            self.push(StackElem::App(pos));
        }
    }

    /// Push a marker to indicate that during the evaluation an application, the function part was
    /// finally evaluated to an expression of the form `fun x => body`, and that the body of this
    /// function was entered.
    pub fn enter_fun(&mut self, pos_table: &PosTable, pos: PosIdx) {
        // We ignore application without positions, which have been generated by the interpreter.
        if pos_table.get(pos).is_def() {
            self.push(StackElem::Fun(pos));
        }
    }

    /// Push a marker to indicate that a record field was entered.
    pub fn enter_field(
        &mut self,
        id: LocIdent,
        pos_record: PosIdx,
        pos_field: PosIdx,
        pos_access: PosIdx,
    ) {
        self.push(StackElem::Field {
            id,
            pos_record,
            pos_field,
            pos_access,
        });
    }

    /// Process a raw callstack by aggregating elements belonging to the same call. Return a list of
    /// call descriptions from the most nested/recent to the least nested/recent, together with the
    /// last pending call, if any.
    ///
    /// Recall that when a call `f arg` is evaluated, the following events happen:
    /// 1. `arg` is pushed on the evaluation stack.
    /// 2. `f` is evaluated.
    /// 3. Hopefully, the result of this evaluation is a function `Func(id, body)`. `arg` is popped
    ///    from the stack, bound to `id` in the environment, and `body is entered`.
    ///
    /// For error reporting purpose, we want to be able to determine the chain of nested calls
    /// leading to the current code path at any moment. To do so, the Nickel abstract machine
    /// maintains a callstack via this basic mechanism:
    /// 1. When an application is evaluated, push a marker with the position of the application on
    ///    the callstack.
    /// 2. When a function body is entered, push a marker with the position of the original
    ///    application on the callstack.
    /// 3. When a variable is evaluated, push a marker with its name and position on the callstack.
    /// 4. When a record field is accessed, push a marker with its name and position on the
    ///    callstack too.
    ///
    /// Both field and variable are useful to determine the name of a called function, when there is
    /// one.  The resulting stack is not suited to be reported to the user for the following
    /// reasons:
    ///
    /// 1. One call spans several items on the callstack. First the application is entered (pushing
    ///    an `App`), then possibly variables or other application are evaluated until we eventually
    ///    reach a function for the left hand side. Then body of this function is entered (pushing a
    ///    `Fun`).
    /// 2. Because of currying, multi-ary applications span several objects on the callstack.
    ///    Typically, `(fun x y => x + y) arg1 arg2` spans two `App` and two `Fun` elements in the
    ///    form `App1 App2 Fun2 Fun1`, where the position span of `App1` includes the position span
    ///    of `App2`.  We want to group them as one call.
    /// 3. The callstack includes calls to builtin contracts. These calls are inserted implicitly by
    ///    the abstract machine and are not written explicitly by the user. Showing them is
    ///    confusing and clutters the call chain, so we get rid of them too.
    ///
    /// This is the role of `group_by_calls`, which filter out unwanted elements and groups
    /// callstack elements into atomic call elements represented by [`CallDescr`].
    ///
    /// The final call description list is reversed such that the most nested calls, which are
    /// usually the most relevant to understand the error, are printed first.
    ///
    /// # Arguments
    ///
    /// - `stdlib_ids`: the `FileId`s of the sources containing standard contracts, to filter their
    ///   calls out.
    pub fn group_by_calls(
        self: &CallStack,
        pos_table: &PosTable,
        files: &Files,
    ) -> (Vec<CallDescr>, Option<CallDescr>) {
        // We filter out calls and accesses made from within the builtin contracts, as well as
        // generated variables introduced by program transformations.
        let it = self.0.iter().filter(|elem| {
            // We avoid applications (Fun/App) with inherited positions. Such calls include
            // contracts applications which add confusing call items whose positions don't point to
            // an actual call in the source.
            let src_id = match elem {
                StackElem::Var { id, .. } if id.is_generated() => None,
                StackElem::Var { pos, .. }
                | StackElem::Field {
                    pos_access: pos, ..
                } => pos_table.get(*pos).into_opt().map(|span| span.src_id),
                StackElem::Fun(pos) | StackElem::App(pos) => {
                    if let TermPos::Original(RawSpan { src_id, .. }) = pos_table.get(*pos) {
                        Some(src_id)
                    } else {
                        None
                    }
                }
            };

            src_id.is_some_and(|src_id| !files.is_stdlib(src_id))
        });

        // We maintain a stack of active calls (whose head is being evaluated).  When encountering
        // an identifier (variable or record field), we see if it could serve as a function name
        // for the current active call. When a `Fun` is encountered, we check if this correspond to
        // the current active call, and if it does, the call description is moved to a stack of
        // processed calls.
        //
        // We also merge subcalls, in the sense that subcalls of larger calls are not considered
        // separately. `app1` is a subcall of `app2` if the position of `app1` is included in the
        // one of `app2` and the starting index is equal. We want `f a b c` to be reported as only
        // one big call to `f` rather than three nested calls `f a`, `f a b`, and `f a b c`.
        let mut pending: Vec<CallDescr> = Vec::new();
        let mut entered: Vec<CallDescr> = Vec::new();

        for elt in it {
            match elt {
                StackElem::Var { id, pos, .. }
                | StackElem::Field {
                    id,
                    pos_access: pos,
                    ..
                } => {
                    let span = pos_table.get(*pos).unwrap();

                    match pending.last_mut() {
                        Some(CallDescr {
                            head: head @ None,
                            span: span_call,
                        }) if span <= *span_call => *head = Some(*id),
                        _ => (),
                    };
                }
                StackElem::App(pos) => {
                    let span = pos_table.get(*pos).unwrap();

                    match pending.last() {
                        Some(CallDescr {
                            span: span_call, ..
                        }) if span <= *span_call && span.start == span_call.start => (),
                        _ => pending.push(CallDescr { head: None, span }),
                    }
                }
                StackElem::Fun(pos) => {
                    let span = pos_table.get(*pos).unwrap();

                    if pending
                        .last()
                        .map(|cdescr| cdescr.span == span)
                        .unwrap_or(false)
                    {
                        entered.push(pending.pop().unwrap());
                    }
                    // Otherwise, we are most probably entering a subcall () of the currently
                    // active call (e.g. in an multi-ary application `f g h`, a subcall would be `f
                    // g`). In any case, we do nothing.
                }
            }
        }

        entered.reverse();
        (entered, pending.pop())
    }

    /// Return the length of the callstack. Wrapper for `callstack.0.len()`.
    pub fn len(&self) -> u32 {
        // safe conversion: we maintain the invariant that the length of the stack is at most
        // u32::MAX
        self.0.len() as u32
    }

    /// Return whether the callstack is empty.
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Truncate the callstack at a certain size. Used e.g. to quickly drop the elements introduced
    /// during the strict evaluation of the operand of a primitive operator. Wrapper for
    /// `callstack.0.truncate(len)`.
    pub fn truncate(&mut self, len: usize) {
        self.0.truncate(len)
    }
}

impl From<CallStack> for Vec<StackElem> {
    fn from(cs: CallStack) -> Self {
        cs.0
    }
}//! Computation of contract equality.
//!
//! This module is temporary, and has been extracted from the typechecker operating in the legacy
//! AST (`NickelValue`). It's used by the current tree-walking virtual machine, but will be scrapped
//! once the bytecode virtual machine (RFC007) is operational. At the time, we won't have the AST
//! around at runtime anymore, and will use an entirely different technique for contract
//! deduplication.
//!
//! Determine if two contracts are equal at runtime, which is leveraged by the contract
//! deduplication optimization.
//!
//! We first test for physical equality. If the comparison fails, we do a simple structural
//! recursion, unfolding simple forms and following variables with a limited number of times. For
//! anything more complex, we return false.
//!
//! The terms involved can be arbitrarily complex. Primops applications, `match`, and the like are
//! quite unlikely to appear inside an annotation (they surely appear inside contract definitions).
//!
//! We don't want to compare functions syntactically either. The spirit of this implementation is
//! to equate aliases or simple constructs that may appear inlined inside an annotation
//! (applications, records, primitive constants and arrays, mostly) in a structural way, and rely
//! on physical equality otherwise when two contracts "point" (through maybe variables) to the same
//! definition.
//!
//! ## Recursion
//!
//! We must refrain from following all variables links blindly, as there could be cycles in the
//! graph leading to an infinite loop:
//!
//! ```nickel
//! {
//!   Foo = Bar,
//!   Bar = Foo,
//! }
//! ```
//!
//! Because we just follows variables, and don't apply functions, we can detect cycles while
//! walking the graph. Still, as it is potentially performed many times during typechecking, type
//! equality ought to stay reasonably cheap. We choose to just set an arbitrary limit (the gas) on
//! the number of variable links that the type equality may follow. Doing so, we don't have to
//! worry about loops anymore.
use super::Environment;

use crate::{
    eval::{
        cache::lazy::Thunk,
        value::{Container, EnumVariantData, NickelValue, ValueContentRef},
    },
    identifier::LocIdent,
    term::{IndexMap, Op1Data, StrChunk, Term, UnaryOp, record::Field},
    typ::{
        EnumRowF, EnumRows, EnumRowsIteratorItem, RecordRowF, RecordRows, RecordRowsIteratorItem,
        Type, TypeF,
    },
};

/// The maximal number of variable links we want to unfold before abandoning the check. It should
/// stay low, but has been fixed arbitrarily: feel fee to increase reasonably if it turns out
/// legitimate type equalities between simple contracts are unduly rejected in practice.
pub const MAX_GAS: u8 = 12;

/// State threaded through the type equality computation.
#[derive(Copy, Clone, Default)]
struct State {
    /// The current gas remaining for variable substitutions. Once it reaches zero and we encounter
    /// a variable, we abort the computation and return false.
    gas: u8,
}

impl State {
    fn new() -> Self {
        State { gas: MAX_GAS }
    }

    /// Try to consume one unit of gas for a variable substitution. Return true in case of success,
    /// or false if the gas was already at zero.
    fn use_gas(&mut self) -> bool {
        if self.gas == 0 {
            false
        } else {
            self.gas -= 1;
            true
        }
    }
}

/// Compute equality between two contracts.
///
/// # Parameters
///
/// - `env`: an environment mapping variables to their definition (the second placeholder in a
///   `let _ = _ in _`)
pub fn contract_eq(
    t1: &NickelValue,
    env1: &Environment,
    t2: &NickelValue,
    env2: &Environment,
) -> bool {
    contract_eq_bounded(&mut State::new(), t1, env1, t2, env2)
}

/// **Warning**: this function isn't computing a sound contract equality (it could equate contracts
/// that aren't actually the same). It is used to deduplicate type and contract annotations for
/// pretty-printing, where there is no notion of environment and the only thing that matters is
/// that they are printed the same or not.
///
/// Compute equality between two contracts in an empty environment. This means that two variables
/// with the same name are considered equal.
pub fn type_eq_noenv(t1: &Type, t2: &Type) -> bool {
    let empty = Environment::new();

    type_eq_bounded(&mut State::new(), t1, &empty, t2, &empty)
}

/// Decide type equality on contracts in their respective environment and given the remaining gas
/// in `state`.
fn contract_eq_bounded(
    state: &mut State,
    t1: &NickelValue,
    env1: &Environment,
    t2: &NickelValue,
    env2: &Environment,
) -> bool {
    // Test for physical equality as both an optimization and a way to cheaply equate complex
    // contracts that happen to point to the same definition (while the purposely limited
    // structural checks below may reject the equality)
    if t1.phys_eq(t2) && Environment::ptr_eq(env1, env2) {
        return true;
    }

    match (t1.content_ref(), t2.content_ref()) {
        (ValueContentRef::Null, ValueContentRef::Null) => true,
        (ValueContentRef::Bool(b1), ValueContentRef::Bool(b2)) => b1 == b2,
        (ValueContentRef::EnumVariant(enum1), ValueContentRef::EnumVariant(enum2)) => {
            match (enum1, enum2) {
                (
                    EnumVariantData {
                        tag: tag1,
                        arg: None,
                    },
                    EnumVariantData {
                        tag: tag2,
                        arg: None,
                    },
                ) => tag1 == tag2,
                (
                    EnumVariantData {
                        tag: tag1,
                        arg: Some(arg1),
                    },
                    EnumVariantData {
                        tag: tag2,
                        arg: Some(arg2),
                    },
                ) => tag1 == tag2 && contract_eq_bounded(state, arg1, env1, arg2, env2),
                _ => false,
            }
        }
        (ValueContentRef::SealingKey(s1), ValueContentRef::SealingKey(s2)) => s1 == s2,
        (ValueContentRef::Record(Container::Empty), ValueContentRef::Record(Container::Empty)) => {
            true
        }
        (
            ValueContentRef::Record(Container::Alloc(r1)),
            ValueContentRef::Record(Container::Alloc(r2)),
        ) => {
            map_eq(
                contract_eq_fields,
                state,
                &r1.fields,
                env1,
                &r2.fields,
                env2,
            ) && r1.attrs.open == r2.attrs.open
        }
        (ValueContentRef::Array(Container::Empty), ValueContentRef::Array(Container::Empty)) => {
            true
        }
        (
            ValueContentRef::Array(Container::Alloc(arr_data1)),
            ValueContentRef::Array(Container::Alloc(arr_data2)),
        ) => {
            arr_data1.array.len() == arr_data2.array.len()
                && arr_data1
                    .array
                    .iter()
                    .zip(arr_data2.array.iter())
                    .all(|(t1, t2)| contract_eq_bounded(state, t1, env1, t2, env2))
                // Ideally we would compare pending contracts, but it's a bit advanced and for now
                // we only equate arrays without additional contracts
                && arr_data1.pending_contracts.is_empty() && arr_data2.pending_contracts.is_empty()
        }
        // Contract is just a caching mechanism. `typ` should be the source of truth for equality
        // (and it's probably easier to prove that type are equal rather than their generated
        // contract version).
        (ValueContentRef::Type(type_data1), ValueContentRef::Type(type_data2)) => {
            type_eq_bounded(state, &type_data1.typ, env1, &type_data2.typ, env2)
        }
        // All variables must be bound at this stage. This is checked by the typechecker when
        // walking annotations. However, we may assume that `env` is a local environment (that it
        // doesn't include the stdlib). In that case, free variables (unbound) may be deemed equal
        // if they have the same identifier: whatever global environment the term will be put in,
        // free variables are not redefined locally and will be bound to the same value in any case.
        (ValueContentRef::Term(Term::Var(id1)), ValueContentRef::Term(Term::Var(id2))) => {
            match (env1.get(&id1.ident()), env2.get(&id2.ident())) {
                (Some(idx1), Some(idx2)) => {
                    // We consider unwrapping two thunks as only one operation using one
                    // unit of gas. This is arbitrary but unimportant.
                    if !state.use_gas() {
                        return false;
                    }

                    let closure1 = idx1.borrow();
                    let closure2 = idx2.borrow();

                    contract_eq_bounded(
                        state,
                        &closure1.value,
                        &closure1.env,
                        &closure2.value,
                        &closure2.env,
                    )
                }
                (None, None) => id1 == id2,
                _ => false,
            }
        }
        (ValueContentRef::Term(Term::Var(id)), _) => {
            state.use_gas()
                && env1
                    .get(&id.ident())
                    .map(|idx| {
                        let closure = idx.borrow();
                        contract_eq_bounded(state, &closure.value, &closure.env, t2, env2)
                    })
                    .unwrap_or(false)
        }
        (_, ValueContentRef::Term(Term::Var(id))) => {
            state.use_gas()
                && env2
                    .get(&id.ident())
                    .map(|idx| {
                        let closure = idx.borrow();
                        contract_eq_bounded(state, t1, env1, &closure.value, &closure.env)
                    })
                    .unwrap_or(false)
        }
        (ValueContentRef::Term(term1), ValueContentRef::Term(term2)) => {
            match (&term1, &term2) {
                // We only compare string chunks when they represent a plain string (they don't contain any
                // interpolated expression), as static string may be currently parsed as such. We return
                // false for anything more complex.
                (Term::StrChunks(scs1), Term::StrChunks(scs2)) => {
                    scs1.len() == scs2.len()
                        && scs1.iter().zip(scs2.iter()).all(|(chunk1, chunk2)| {
                            match (chunk1, chunk2) {
                                (StrChunk::Literal(s1), StrChunk::Literal(s2)) => s1 == s2,
                                _ => false,
                            }
                        })
                }
                (Term::App(data1), Term::App(data2)) => {
                    contract_eq_bounded(state, &data1.head, env1, &data2.head, env2)
                        && contract_eq_bounded(state, &data1.arg, env1, &data2.arg, env2)
                }
                (Term::RecRecord(data1), Term::RecRecord(data2)) =>
                // We only compare records whose field structure is statically known (i.e. without dynamic
                // fields) and without include expressions, which are a bit tricky to consider.
                {
                    data1.dyn_fields.is_empty()
                        && data2.dyn_fields.is_empty()
                        && data1.includes.is_empty()
                        && data2.includes.is_empty()
                        && map_eq(
                            contract_eq_fields,
                            state,
                            &data1.record.fields,
                            env1,
                            &data2.record.fields,
                            env2,
                        )
                        && data1.record.attrs.open == data2.record.attrs.open
                }
                // We must compare the inner values as well as the corresponding contracts or type
                // annotations.
                (Term::Annotated(data1), Term::Annotated(data2)) => {
                    let value_eq =
                        contract_eq_bounded(state, &data1.inner, env1, &data2.inner, env2);

                    // TODO:
                    // - does it really make sense to compare the annotations?
                    // - does it even happen to have contracts having themselves type annotations?
                    // - and in the latter case, should they be declared unequal because of that?
                    //   The answer to the last question is probably yes, because contracts are
                    //   fundamentally as powerful as function application, so they can change their
                    //   argument.

                    // We use the same logic as in the typechecker: the type associated to an annotated
                    // value is either the type annotation, or the first contract annotation.
                    let ty1 = data1.annot.first();
                    let ty2 = data2.annot.first();

                    let ty_eq = match (ty1, ty2) {
                        (None, None) => true,
                        (Some(ctr1), Some(ctr2)) => {
                            type_eq_bounded(state, &ctr1.typ, env1, &ctr2.typ, env2)
                        }
                        _ => false,
                    };

                    value_eq && ty_eq
                }
                (
                    Term::Op1(Op1Data {
                        op: UnaryOp::RecordAccess(id1),
                        arg: arg1,
                    }),
                    Term::Op1(Op1Data {
                        op: UnaryOp::RecordAccess(id2),
                        arg: arg2,
                    }),
                ) => id1 == id2 && contract_eq_bounded(state, arg1, env1, arg2, env2),
                (Term::Sealed(data1), Term::Sealed(data2)) => {
                    data1.key == data2.key
                        && contract_eq_bounded(state, &data1.inner, env1, &data2.inner, env2)
                }
                (Term::Closurize(v1), Term::Closurize(v2)) => {
                    contract_eq_bounded(state, v1, env1, v2, env2)
                }
                // We don't treat imports, parse errors, functions, let-bindings nor pairs of terms
                // that don't have the same shape
                _ => false,
            }
        }
        (ValueContentRef::Thunk(thunk1), ValueContentRef::Thunk(thunk2))
            if Thunk::ptr_eq(thunk1, thunk2) =>
        {
            true
        }
        (ValueContentRef::Thunk(thunk1), ValueContentRef::Thunk(thunk2)) => {
            // We consider unwrapping two thunks as only one operation using one unit of gas. This
            // is arbitrary but unimportant.
            if !state.use_gas() {
                return false;
            }

            // If we find a closure that isn't coming from a variable, it might be the content of a
            // recursive field. When deduplicating contracts at merge time, those fields have been
            // reverted to a state where they don't have a cached value built yet. This state is
            // not observable by the rest of the evaluator, but we do have to consider it here. We
            // make use of `borrow_orig` built for this purpose, to get the original closure in
            // this case instead of panicking as `borrow()` would.
            let closure1 = thunk1.borrow_orig();
            let closure2 = thunk2.borrow_orig();

            contract_eq_bounded(
                state,
                &closure1.value,
                &closure1.env,
                &closure2.value,
                &closure2.env,
            )
        }
        (ValueContentRef::Thunk(thunk), _) => {
            let closure = thunk.borrow_orig();

            state.use_gas() && contract_eq_bounded(state, &closure.value, &closure.env, t2, env2)
        }
        (_, ValueContentRef::Thunk(thunk)) => {
            let closure = thunk.borrow_orig();

            state.use_gas() && contract_eq_bounded(state, t1, env1, &closure.value, &closure.env)
        }
        (
            ValueContentRef::Term(Term::RecRecord(data)),
            ValueContentRef::Record(Container::Empty),
        )
        | (
            ValueContentRef::Record(Container::Empty),
            ValueContentRef::Term(Term::RecRecord(data)),
        ) => {
            data.dyn_fields.is_empty()
                && data.includes.is_empty()
                && data.record.fields.is_empty()
                // An open record is always properly allocated (not inlined), even if empty. So
                // `Container::Empty` implies closed.
                && !data.record.attrs.open
        }
        (
            ValueContentRef::Term(Term::RecRecord(rec_data)),
            ValueContentRef::Record(Container::Alloc(record)),
        )
        | (
            ValueContentRef::Record(Container::Alloc(record)),
            ValueContentRef::Term(Term::RecRecord(rec_data)),
        ) => {
            rec_data.dyn_fields.is_empty()
                && rec_data.includes.is_empty()
                && map_eq(
                    contract_eq_fields,
                    state,
                    &record.fields,
                    env1,
                    &rec_data.record.fields,
                    env2,
                )
                && rec_data.record.attrs.open == record.attrs.open
        }
        // Other cases are pairwise different
        _ => false,
    }
}

/// Compute the equality between two hashmaps holding either types or terms.
fn map_eq<V, F>(
    mut f: F,
    state: &mut State,
    map1: &IndexMap<LocIdent, V>,
    env1: &Environment,
    map2: &IndexMap<LocIdent, V>,
    env2: &Environment,
) -> bool
where
    F: FnMut(&mut State, &V, &Environment, &V, &Environment) -> bool,
{
    map1.len() == map2.len()
        && map1.iter().all(|(id, v1)| {
            map2.get(id)
                .map(|v2| f(state, v1, env1, v2, env2))
                .unwrap_or(false)
        })
}

/// Convert record rows to a hashmap.
///
/// Require the rows to be closed (i.e. the last element must be `RowEmpty`), otherwise `None` is
/// returned. `None` is returned as well if a type encountered is not row, or if it is a enum row.
fn rrows_as_map(erows: &RecordRows) -> Option<IndexMap<LocIdent, &Type>> {
    let map: Option<IndexMap<LocIdent, _>> = erows
        .iter()
        .map(|item| match item {
            RecordRowsIteratorItem::Row(RecordRowF { id, typ }) => Some((id, typ)),
            _ => None,
        })
        .collect();

    map
}

/// Convert enum rows to a hashmap.
///
/// Require the rows to be closed (i.e. the last element must be `RowEmpty`), otherwise `None` is
/// returned. `None` is returned as well if a type encountered is not row type, or if it is a
/// record row.
fn erows_as_map(erows: &EnumRows) -> Option<IndexMap<LocIdent, Option<&Type>>> {
    let set: Option<IndexMap<LocIdent, Option<_>>> = erows
        .iter()
        .map(|item| match item {
            EnumRowsIteratorItem::Row(EnumRowF { id, typ }) => Some((id, typ)),
            _ => None,
        })
        .collect();

    set
}

/// Check for contract equality between record fields. Fields are equal if they are both without a
/// definition, or are both defined and their values are equal.
///
/// The attached metadata must be equal as well: most record contracts are written as field with
/// metadata but without definition. For example, take `{ foo | {bar | Number}}` and `{foo | {bar |
/// String}}`. Those two record contracts are obviously not equal, but to know that, we have to
/// look at the contracts of each bar field.
fn contract_eq_fields(
    state: &mut State,
    field1: &Field,
    env1: &Environment,
    field2: &Field,
    env2: &Environment,
) -> bool {
    // Check that the pending contracts are equal.
    //
    // [^contract-eq-ignore-label]: We mostly ignore the label here, which doesn't impact the fact
    // that a contract blame or not. Different labels might lead to different error messages,
    // though. Note that there is one important exception: the field `type_environment` does impact
    // the evaluation of the contract. Fortunately, it's a simple datastructure that is easy to
    // compare, so we do check for equality here.
    //
    // Otherwise, comparing the rest of the labels seem rather clumsy (as labels store a wide
    // variety of static and runtime data) and not very meaningful.
    let pending_contracts_eq = field1
        .pending_contracts
        .iter()
        .zip(field2.pending_contracts.iter())
        .all(|(c1, c2)| {
            c1.label.type_environment == c2.label.type_environment
                && contract_eq_bounded(state, &c1.contract, env1, &c2.contract, env2)
        });

    // Check that the type and contract annotations are equal. [^contract-eq-ignore-label] applies
    // here as well.
    let annotations_eq = field1
        .metadata
        .iter_annots()
        .zip(field2.metadata.iter_annots())
        .all(|(t1, t2)| {
            t1.label.type_environment == t2.label.type_environment
                && type_eq_bounded(state, &t1.typ, env1, &t2.typ.clone(), env2)
        });

    // Check that "scalar" metadata (simple values) are equals
    let scalar_metadata_eq = field1.metadata.opt() == field2.metadata.opt()
        && field1.metadata.not_exported() == field2.metadata.not_exported()
        && field1.metadata.priority() == field2.metadata.priority();

    let value_eq = match (&field1.value, &field2.value) {
        (Some(value1), Some(value2)) => contract_eq_bounded(state, value1, env1, value2, env2),
        (None, None) => true,
        _ => false,
    };

    pending_contracts_eq && annotations_eq && scalar_metadata_eq && value_eq
}

/// Perform equality comparison on types. Structurally recurse into type constructors and test that
/// subtypes or subterms (contracts) are equals.
fn type_eq_bounded(
    state: &mut State,
    ty1: &Type,
    env1: &Environment,
    ty2: &Type,
    env2: &Environment,
) -> bool {
    match (&ty1.typ, &ty2.typ) {
        (TypeF::Wildcard(id1), TypeF::Wildcard(id2)) => id1 == id2,
        (TypeF::Dyn, TypeF::Dyn)
        | (TypeF::Number, TypeF::Number)
        | (TypeF::Bool, TypeF::Bool)
        | (TypeF::Symbol, TypeF::Symbol)
        | (TypeF::String, TypeF::String) => true,
        (
            TypeF::Dict {
                type_fields: uty1,
                flavour: attrs1,
            },
            TypeF::Dict {
                type_fields: uty2,
                flavour: attrs2,
            },
        ) if attrs1 == attrs2 => type_eq_bounded(state, uty1, env1, uty2, env2),
        (TypeF::Array(uty1), TypeF::Array(uty2)) => type_eq_bounded(state, uty1, env1, uty2, env2),
        (TypeF::Arrow(s1, t1), TypeF::Arrow(s2, t2)) => {
            type_eq_bounded(state, s1, env1, s2, env2) && type_eq_bounded(state, t1, env1, t2, env2)
        }
        (TypeF::Enum(uty1), TypeF::Enum(uty2)) => {
            fn type_eq_bounded_wrapper(
                state: &mut State,
                uty1: &Option<&Type>,
                env1: &Environment,
                uty2: &Option<&Type>,
                env2: &Environment,
            ) -> bool {
                match (uty1, uty2) {
                    (Some(uty1), Some(uty2)) => type_eq_bounded(state, uty1, env1, uty2, env2),
                    (None, None) => true,
                    _ => false,
                }
            }

            let map1 = erows_as_map(uty1);
            let map2 = erows_as_map(uty2);

            map1.zip(map2)
                .map(|(m1, m2)| map_eq(type_eq_bounded_wrapper, state, &m1, env1, &m2, env2))
                .unwrap_or(false)
        }
        (TypeF::Record(uty1), TypeF::Record(uty2)) => {
            fn type_eq_bounded_wrapper(
                state: &mut State,
                uty1: &&Type,
                env1: &Environment,
                uty2: &&Type,
                env2: &Environment,
            ) -> bool {
                type_eq_bounded(state, uty1, env1, uty2, env2)
            }

            let map1 = rrows_as_map(uty1);
            let map2 = rrows_as_map(uty2);

            map1.zip(map2)
                .map(|(m1, m2)| map_eq(type_eq_bounded_wrapper, state, &m1, env1, &m2, env2))
                .unwrap_or(false)
        }
        (TypeF::Contract(t1), TypeF::Contract(t2)) => {
            contract_eq_bounded(state, t1, env1, t2, env2)
        }
        // We don't handle foralls in this temporary module: they are unlikely to appear,
        // and they require type substitution machinery.
        _ => false,
    }
}//! Compute the fixpoint of a recursive record.
use super::{merge::RevertClosurize, value::ValueContentRefMut, *};
use crate::position::PosIdx;

/// Updates the environment of an expression by extending it with a recursive environment. In the
/// general case, the expression is expected to be a variable pointing to the element to be patched.
/// Otherwise, it's considered to have no dependencies and is left untouched.
///
/// This function achieve the same as [patch_field], but is somehow lower-level, as it operates on
/// a general [crate::eval::value::NickelValue] instead of a [crate::term::record::Field]. In
/// practice, the patched expression is either the value of a field or one of its pending contract.
fn patch_value<C: Cache>(cache: &mut C, value: &mut NickelValue, rec_env: &[(Ident, CacheIndex)]) {
    if let Some(ValueContentRefMut::Thunk(thunk)) = value.content_mut() {
        cache.build_cached(thunk, rec_env);
    } else {
        debug_assert!(value.is_constant())
    }
}

/// Builds a recursive environment from record bindings. For each field, `rec_env` either extracts
/// the corresponding cache element from the environment in the general case, or create a closure
/// on the fly if the field is a constant. The resulting environment is to be passed to the
/// [`patch_field`] function.
///
/// # Pending contracts
///
/// Since the implementation of RFC005, contract are lazily applied at the level of record fields.
/// Consider the following example:
///
/// ```nickel
/// let Schema = {bar | default = "hello"} in
///
/// {
///   foo | Schema = {},
///   baz = foo.bar
/// }
/// ```
///
/// This program is valid and should output `{foo.bar = "hello", baz = "hello"}`. To make this
/// happen, we have to ensure the pending contract `Schema` is applied to the recursive occurrence
/// `foo` used in the definition `baz = foo.bar`. That is, we must apply pending contracts to their
/// corresponding field when building the recursive environment.
pub fn rec_env<'a, I: Iterator<Item = (&'a LocIdent, &'a Field)>, C: Cache>(
    cache: &mut C,
    bindings: I,
    pos_record: PosIdx,
) -> Vec<(Ident, CacheIndex)> {
    bindings
        .map(|(id, field)| {
            if let Some(ref value) = field.value {
                let idx = value.as_thunk().cloned().unwrap_or_else(|| {
                    // If we are in this branch, `value` must be a constant after closurization
                    // (the evaluation of a recursive record starts by closurizing all fields and
                    // contracts).
                    debug_assert!(value.is_constant());
                    // Constants don't need an environment: they contain no variable.
                    let closure: Closure = value.clone().into();

                    cache.add(closure, BindingType::Normal)
                });

                // We now need to wrap the binding in a value with contracts applied.
                let with_ctr_applied = RuntimeContract::apply_all(
                    idx.into(),
                    field.pending_contracts.iter().cloned(),
                    value.pos_idx(),
                );

                let final_closure: Closure = with_ctr_applied.into();

                (id.ident(), cache.add(final_closure, BindingType::Normal))
            } else {
                let error = EvalErrorKind::MissingFieldDef {
                    id: *id,
                    metadata: field.metadata.clone_inner(),
                    pos_record,
                    // The access location is not yet known (there may not be any access, if the
                    // current field is never used).
                    //
                    // This field is filled later by the evaluation function if this
                    // `MissingFieldDef` is ever extracted from the environment.
                    pos_access: PosIdx::NONE,
                };

                let closure: Closure =
                    NickelValue::from(Term::RuntimeError(Box::new(error))).into();

                (id.ident(), cache.add(closure, BindingType::Normal))
            }
        })
        .collect()
}

/// Update the environment of the content of a recursive record field by extending it with a
/// recursive environment. When seeing revertible elements as a memoizing device for functions,
/// this step correspond to function application (see documentation of
/// [crate::eval::cache::lazy::ThunkData]).
///
/// For each field, retrieve the set of dependencies from the corresponding element in the
/// environment, and only add those dependencies to the environment. This avoids retaining
/// reference-counted pointers to unused data. If no dependencies are available, conservatively add
/// all the recursive environment. See [`crate::transform::free_vars`].
pub fn patch_field<C: Cache>(cache: &mut C, field: &mut Field, rec_env: &[(Ident, CacheIndex)]) {
    if let Some(ref mut value) = field.value {
        patch_value(cache, value, rec_env);
    }

    // We must patch the contracts contained in the fields' pending contracts as well, since they
    // can depend recursively on other fields, as in:
    //
    // ```
    // let Variant = match {
    //   'num => Number,
    //   'str => String,
    //   'any => Dyn,
    // } in
    //
    // {
    //   tag | default = 'num,
    //   value | Variant tag,
    // }
    // ```
    //
    // Here, `Variant` depends on `tag` recursively.
    for ctr in field.pending_contracts.iter_mut() {
        patch_value(cache, &mut ctr.contract, rec_env);
    }
}

/// Revert an evaluated record (`Record`) back to a recursive record (`RecRecord`). The fixpoint
/// will be recomputed again at evaluation.
///
/// `revert` is used when an operation (excluding `merge`, which has its own reverting logic) might
/// have changed the value of fields (e.g. a lazy contract application on a record), requiring to
/// update recursive dependencies.
///
/// # Parameters
///
/// - `cache`: the evaluation cache
/// - `record_data`: the data of the record to revert
pub fn revert<C: Cache>(cache: &mut C, record_data: RecordData) -> Term {
    let fields = record_data
        .fields
        .into_iter()
        .map(|(id, field)| (id, field.revert_closurize(cache)))
        .collect();

    let record_data = RecordData {
        fields,
        ..record_data
    };

    // At run-time, we don't care about `RecordDeps`, because this information is already stored in
    // the cache (thunks in call-by-need mode). We set it to `None`.
    //
    // Include expressions are transformed to normal fields the very first time they are seen. They
    // aren't reconstructed, so the result of a merge never has any include expressions.
    //
    // The fields are already closurized.
    Term::rec_record(record_data, Vec::new(), Vec::new(), None, true)
}//! Evaluation of the merge operator.
//!
//! Merge is a primitive operation of Nickel, which recursively combines records. Together with
//! field metadata, it allows to write and mix contracts with standard records.
//!
//! # Operational semantics
//!
//! ## On records
//!
//! When records `r1` and `r2` are merged, the result is a new record with the following fields:
//! - All the fields of `r1` that are not in `r2`
//! - All the fields of `r2` that are not in `r1`
//! - Fields that are both in `r1` and `r2` are recursively merged: for a field `f`, the result
//!   contains the binding `f = r1.f & r2.f`
//!
//! As fields are recursively merged, merge needs to operate on any value, not only on records:
//!
//! - *function*: merging a function with anything else fails
//! - *values*: merging any other values succeeds if and only if these two values are equals, in
//!   which case it evaluates to this common value.
//!
//! ## Metadata
//!
//! One can think of merge to be defined on metadata as well. When merging two fields, the
//! resulting metadata is the result of merging the two original field's metadata. The semantics
//! depend on each metadata.

use nickel_lang_parser::ast::MergeKind;

use super::*;
use crate::{
    closurize::Closurize,
    combine::Combine,
    error::IllegalPolymorphicTailAction,
    label::{Label, MergeLabel},
    position::PosIdx,
    term::{
        BinaryOp, IndexMap, Term, TypeAnnotation, make as mk_term,
        record::{self, Field, FieldDeps, FieldMetadata, RecordAttrs, RecordData},
    },
};

/// Merging mode. Merging is used both to combine standard data and to apply contracts defined as
/// records.
///
/// In [MergeMode::Contract] mode, the merge operator acts like a custom contract. Instead of
/// returning the result directly, it either returns `'Ok result`, or `'Error {..}` if there were
/// some unexpected extra fields.
#[derive(Clone, PartialEq, Debug)]
pub enum MergeMode {
    /// Standard merging, for combining data.
    Standard(MergeLabel),
    /// Merging to apply a record contract to a value, with the associated label.
    Contract(Label),
}

impl From<MergeMode> for MergeLabel {
    /// Either takes the inner merge label if the mode is `Standard`, or converts a contract label
    /// to a merge label if the mode is `Contract`.
    fn from(mode: MergeMode) -> Self {
        match mode {
            MergeMode::Standard(merge_label) => merge_label,
            MergeMode::Contract(label) => label.into(),
        }
    }
}

impl<'ctxt, R: ImportResolver, C: Cache> VirtualMachine<'ctxt, R, C> {
    /// Compute the merge of two evaluated operands. Support both standard merging and record contract
    /// application.
    ///
    /// # Mode
    ///
    /// In [`MergeMode::Contract`] mode, `t1` must be the value and `t2` must be the contract. It is
    /// important as `merge` is not commutative in this mode.
    // TODO: Is it worth to pack the inputs in an ad-hoc struct?
    #[allow(clippy::too_many_arguments)]
    pub fn merge(
        &mut self,
        v1: NickelValue,
        env1: Environment,
        v2: NickelValue,
        env2: Environment,
        pos_op: PosIdx,
        mode: MergeMode,
    ) -> Result<Closure, ErrorKind> {
        let pos1 = v1.pos_idx();
        let pos2 = v2.pos_idx();
        let pos_op_inh = pos_op.to_inherited();

        // Determines if we need to wrap the result in `'Ok` upon successful merging, which is the case
        // when in contract merge mode. We're going to move out of `mode` at some point, so we need to
        // save this information now.
        let wrap_in_ok = matches!(mode, MergeMode::Contract(_));

        let result = match (v1.content_ref(), v2.content_ref()) {
            // Merge is idempotent on basic terms
            (ValueContentRef::Null, ValueContentRef::Null) => {
                Ok(NickelValue::null().with_pos_idx(pos_op_inh))
            }
            (ValueContentRef::Bool(b1), ValueContentRef::Bool(b2)) if b1 == b2 => {
                Ok(NickelValue::bool_value(b1, pos_op_inh))
            }
            (ValueContentRef::Number(n1), ValueContentRef::Number(n2)) => {
                if n1 == n2 {
                    Ok(NickelValue::number(n1.clone(), pos_op_inh))
                } else {
                    Err(Box::new(EvalErrorKind::MergeIncompatibleArgs {
                        left_arg: NickelValue::number(n1.clone(), pos1),
                        right_arg: NickelValue::number(n2.clone(), pos2),
                        merge_label: mode.into(),
                    }))
                }
            }
            (ValueContentRef::String(s1), ValueContentRef::String(s2)) => {
                if s1 == s2 {
                    Ok(NickelValue::string(s1, pos_op_inh))
                } else {
                    Err(Box::new(EvalErrorKind::MergeIncompatibleArgs {
                        left_arg: NickelValue::string(s1, pos1),
                        right_arg: NickelValue::string(s2, pos2),
                        merge_label: mode.into(),
                    }))
                }
            }
            (ValueContentRef::Label(label1), ValueContentRef::Label(label2)) => {
                if label1 == label2 {
                    Ok(NickelValue::label(label1.clone(), pos_op_inh))
                } else {
                    Err(Box::new(EvalErrorKind::MergeIncompatibleArgs {
                        left_arg: NickelValue::label(label1.clone(), pos1),
                        right_arg: NickelValue::label(label2.clone(), pos2),
                        merge_label: mode.into(),
                    }))
                }
            }
            (ValueContentRef::EnumVariant(enum1), ValueContentRef::EnumVariant(enum2)) => {
                match (enum1, enum2) {
                    (
                        EnumVariantData {
                            tag: tag1,
                            arg: None,
                        },
                        EnumVariantData {
                            tag: tag2,
                            arg: None,
                        },
                    ) if tag1 == tag2 => Ok(NickelValue::enum_tag(*tag1, pos_op_inh)),
                    (
                        EnumVariantData {
                            tag: tag1,
                            arg: Some(arg1),
                        },
                        EnumVariantData {
                            tag: tag2,
                            arg: Some(arg2),
                        },
                    ) if tag1 == tag2 => {
                        let arg = NickelValue::term_posless(Term::op2(
                            BinaryOp::Merge(mode.into()),
                            arg1.clone().closurize(&mut self.context.cache, env1),
                            arg2.clone().closurize(&mut self.context.cache, env2),
                        ))
                        .closurize(&mut self.context.cache, Environment::new());

                        Ok(NickelValue::enum_variant(*tag1, Some(arg), pos_op_inh))
                    }
                    (enum1, enum2) => Err(Box::new(EvalErrorKind::MergeIncompatibleArgs {
                        left_arg: NickelValue::enum_variant(enum1.tag, enum1.arg.clone(), pos1),
                        right_arg: NickelValue::enum_variant(enum2.tag, enum2.arg.clone(), pos2),
                        merge_label: mode.into(),
                    })),
                }
            }
            // There are several different (and valid) ways of merging arrays. We don't want to choose
            // for the user, so future custom merge functions will provide a way to overload the native
            // merging function. For the time being, we still need to be idempotent: thus we rewrite
            // `array1 & array2` to `contract.Equal array1 array2`, so that we extend merge in the
            // minimum way such that it is idempotent.
            (ValueContentRef::Array(_), ValueContentRef::Array(_)) => {
                use crate::{mk_app, stdlib, typ::TypeF};
                use std::rc::Rc;

                let v1 = v1.closurize(&mut self.context.cache, env1);
                let v2 = v2.closurize(&mut self.context.cache, env2);

                // We reconstruct the contract we apply later on just to fill the label. This will be
                // printed out when reporting the error.
                let contract_for_display = mk_app!(
                    mk_term::op1(
                        UnaryOp::RecordAccess("Equal".into()),
                        Term::Var("contract".into()),
                    ),
                    // We would need to substitute variables inside `t1` to make it useful to print,
                    // but currently we don't want to do it preventively at each array merging, so we
                    // just print `contract.Equal some_array`.
                    //
                    // If the error reporting proves to be insufficient, consider substituting the
                    // variables inside `t1`, but be aware that it might (or might not) have a
                    // noticeable impact on performance.
                    mk_term::var("some_array")
                );

                let merge_label: MergeLabel = mode.into();
                let mut notes = vec!["\
                    This equality contract was auto-generated from a merge operation on two arrays. \
                    Arrays can only be merged if they are equal.".into()];
                if merge_label.kind == MergeKind::PiecewiseDef {
                    notes.push(
                        "\
                        The arrays were merged because they were assigned to the same record field \
                        piecewise. This is likely to have been a mistake. Check for duplicate \
                        definitions of the same record field."
                            .into(),
                    );
                }

                let label = Label {
                    typ: Rc::new(TypeF::Contract(contract_for_display).into()),
                    span: merge_label.span,
                    ..Default::default()
                }
                .with_diagnostic_message("cannot merge unequal arrays")
                .with_diagnostic_notes(notes);

                // We don't actually use `contract.Equal` directly, because `contract` could have been
                // locally redefined. We rather use the internal `$stdlib_contract_equal`, which is
                // exactly the same, but can't be shadowed.
                let eq_contract = mk_app!(stdlib::internals::stdlib_contract_equal(), v1);

                Ok(mk_app!(
                    mk_term::op2(
                        BinaryOp::ContractApply,
                        eq_contract,
                        NickelValue::label_posless(label)
                    ),
                    v2
                )
                .with_pos_idx(pos_op_inh))
            }
            // The empty record is the neutral element for merging. We treat this case specifically
            // for performance reasons: to avoid allocation, recomputation of fixpoint, etc.
            (ValueContentRef::Record(_), ValueContentRef::Record(Container::Empty))
            | (ValueContentRef::Record(Container::Empty), ValueContentRef::Record(_)) => {
                let non_empty = if v1.is_inline_empty_record() { v2 } else { v1 };

                // In merge contract mode, we need to maintain the position of the first argument,
                // which is the scrutinized value, to maintain good contract error messages.
                //
                // Otherwise, since one of the argument is the neutral element for merging, it's
                // better to keep the position of the other argument (instead of the position of
                // the merge), since the result will inherit everything from it.
                let final_pos = if let MergeMode::Standard(_) = mode {
                    non_empty.pos_idx()
                } else {
                    pos1.to_inherited()
                };

                Ok(non_empty
                    // In `MergeMode::Contract(_)` mode, we want to maintain
                    .with_pos_idx(final_pos))
            }
            // Merge put together the fields of records, and recursively merge
            // fields that are present in both terms
            (
                ValueContentRef::Record(Container::Alloc(r1)),
                ValueContentRef::Record(Container::Alloc(r2)),
            ) => {
                // While it wouldn't be impossible to merge records with sealed tails,
                // working out how to do so in a "sane" way that preserves parametricity
                // is non-trivial. It's also not entirely clear that this is something
                // users will generally have reason to do, so in the meantime we've
                // decided to just prevent this entirely
                if let Some(record::SealedTail { label, .. }) = r1
                    .sealed_tail
                    .as_ref()
                    .or(r2.sealed_tail.as_ref())
                    .map(|rc| &**rc)
                {
                    return Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                        action: IllegalPolymorphicTailAction::Merge,
                        evaluated_arg: label.get_evaluated_arg(&self.context.cache),
                        label: label.clone(),
                    }));
                }

                let split::SplitResult {
                    left,
                    center,
                    right,
                } = split::split_ref(&r1.fields, &r2.fields);

                match mode {
                    MergeMode::Contract(_) if !r2.attrs.open && !left.is_empty() => {
                        let fields: Vec<String> =
                            left.keys().map(|field| format!("`{field}`")).collect();
                        let plural = if fields.len() == 1 { "" } else { "s" };
                        let fields_list = fields.join(", ");

                        let error_data = [
                            (
                                "message".into(),
                                NickelValue::string_posless(format!(
                                    "extra field{plural} {fields_list}"
                                )),
                            ),
                            (
                                "notes".into(),
                                NickelValue::array_posless(
                                    [
                                        NickelValue::string_posless("Have you misspelled a field?"),
                                        NickelValue::string_posless(
                                            "The record contract might also be too strict. By default, \
                                record contracts exclude any field which is not listed.\n\
                                Append `, ..` at the end of the record contract, as in \
                                `{some_field | SomeContract, ..}`, to make it accept extra fields.",
                                        ),
                                    ]
                                    .into_iter()
                                    .collect(),
                                    Default::default(),
                                ),
                            ),
                        ];

                        // The presence of extra fields is an immediate contract error. Thus, instead
                        // of raising a blame error as for a delayed contract error, which can't be
                        // caught in user-code, we return an `'Error {..}` value instead.
                        return Ok(mk_term::enum_variant(
                            "Error",
                            NickelValue::record_posless(RecordData::with_field_values(error_data)),
                        )
                        .into());
                    }
                    _ => (),
                };

                let final_pos = if let MergeMode::Standard(_) = mode {
                    pos_op_inh
                } else {
                    pos1.to_inherited()
                };

                let merge_label = MergeLabel::from(mode);

                let field_names: Vec<_> = left
                    .keys()
                    .chain(center.keys())
                    .chain(right.keys())
                    .copied()
                    .collect();
                let mut m = IndexMap::with_capacity(left.len() + center.len() + right.len());

                // Merging recursive records is the one operation that may override recursive fields. To
                // have the recursive fields depend on the updated values, we need to revert the
                // corresponding elements in the cache to their original expression.
                //
                // We do that for the left and the right part.
                //
                // The fields in the intersection (center) need a slightly more general treatment to
                // correctly propagate the recursive values down each field: saturation. See
                // [crate::eval::cache::Cache::saturate()].
                m.extend(
                    left.into_iter()
                        .map(|(id, field)| (id, field.revert_closurize(&mut self.context.cache))),
                );

                m.extend(
                    right
                        .into_iter()
                        .map(|(id, field)| (id, field.revert_closurize(&mut self.context.cache))),
                );

                for (id, (field1, field2)) in center.into_iter() {
                    m.insert(
                        id,
                        merge_fields(
                            &mut self.context.cache,
                            merge_label,
                            field1,
                            field2,
                            field_names.iter(),
                        )?,
                    );
                }

                let attrs = RecordAttrs::combine(r1.attrs, r2.attrs);

                Ok(NickelValue::term(
                    // We don't have to provide RecordDeps, which are required in a previous stage
                    // of program transformations. At this point, the interpreter doesn't care
                    // about them anymore, and dependencies are stored at the level of revertible
                    // cache elements directly.
                    //
                    // Include expressions are transformed to normal fields the very first time
                    // they are seen, and there's no way back. We always set them to empty here.
                    //
                    // The result is already closurized, so we set `closurized` to true.
                    Term::rec_record(
                        RecordData::new(m, attrs, None),
                        Vec::new(),
                        Vec::new(),
                        None,
                        true,
                    ),
                    final_pos,
                ))
            }
            _ => Err(Box::new(EvalErrorKind::MergeIncompatibleArgs {
                left_arg: v1,
                right_arg: v2,
                merge_label: mode.into(),
            })),
        };

        result.map(|value| {
            if wrap_in_ok {
                let pos = value.pos_idx();
                NickelValue::enum_variant(
                    "Ok",
                    Some(value.closurize(&mut self.context.cache, Environment::new())),
                    pos,
                )
                .into()
            } else {
                value.into()
            }
        })
    }
}

/// Take two record fields in their respective environment and combine both their metadata and
/// values. Apply the required saturate, revert or closurize operation, including on the final
/// field returned.
#[allow(clippy::too_many_arguments)]
fn merge_fields<'a, C: Cache, I: DoubleEndedIterator<Item = &'a LocIdent> + Clone>(
    cache: &mut C,
    merge_label: MergeLabel,
    field1: Field,
    field2: Field,
    fields: I,
) -> Result<Field, ErrorKind> {
    let Field {
        metadata: metadata1,
        value: value1,
        pending_contracts: pending_contracts1,
    } = field1;
    let Field {
        metadata: metadata2,
        value: value2,
        pending_contracts: pending_contracts2,
    } = field2;

    let metadata1 = metadata1.into_inner();
    let metadata2 = metadata2.into_inner();

    // Selecting either meta1's value, meta2's value, or the merge of the two values,
    // depending on which is defined and respective priorities.
    let (value, priority) = match (value1, value2) {
        (Some(t1), Some(t2)) if metadata1.priority == metadata2.priority => (
            Some(fields_merge_closurize(cache, merge_label, t1, t2, fields).unwrap()),
            metadata1.priority,
        ),
        (Some(t1), _) if metadata1.priority > metadata2.priority => {
            (Some(t1.revert_closurize(cache)), metadata1.priority)
        }
        (Some(t1), None) => (Some(t1.revert_closurize(cache)), metadata1.priority),
        (_, Some(t2)) if metadata2.priority > metadata1.priority => {
            (Some(t2.revert_closurize(cache)), metadata2.priority)
        }
        (None, Some(t2)) => (Some(t2.revert_closurize(cache)), metadata2.priority),
        (None, None) => (None, Default::default()),
        _ => unreachable!(),
    };

    // Since contracts are closurized, they don't need another local environment
    let empty = Environment::new();

    let pending_contracts = RuntimeContract::combine_dedup(
        pending_contracts1.revert_closurize(cache),
        &empty,
        pending_contracts2.revert_closurize(cache),
        &empty,
    );

    Ok(Field {
        metadata: FieldMetadata {
            doc: merge_doc(metadata1.doc, metadata2.doc),
            annotation: TypeAnnotation::combine_dedup(metadata1.annotation, metadata2.annotation),
            // If one of the record requires this field, then it musn't be optional. The
            // resulting field is optional iff both are.
            opt: metadata1.opt && metadata2.opt,
            not_exported: metadata1.not_exported || metadata2.not_exported,
            priority,
        }
        .into(),
        value,
        pending_contracts,
    })
}

/// Merge two optional documentations.
///
/// This function is parametrized temporarily to accommodate both the mainline Nickel AST
/// ([crate::term::Term]) where documentation is represented as a `String`, and the new bytecode
/// AST where documentation is represented as an `Rc<str>`.
//FIXME: remove the type parameter `D` once we've moved evaluation to the new bytecode VM.
//Currently we need to handle both the old representation `D=String` and the new one `D=Rc<str>`.
pub(crate) fn merge_doc<D>(doc1: Option<D>, doc2: Option<D>) -> Option<D> {
    //FIXME: how to merge documentation? Just concatenate?
    doc1.or(doc2)
}

/// See [crate::eval::cache::Cache::saturate]. Saturation is a transformation on recursive cache
/// elements that is used when we must combine different values with different recursive
/// dependencies (say, the two values of fields being merged) into one expression.
///
/// Saturation is first and foremost a transformation of terms, but like
/// [crate::transform::Closurizable], it can be applied to other types that contain terms, hence
/// the trait.
trait Saturate: Sized {
    /// Take the content of a record field, and saturate the potential revertible element with the
    /// given fields. See [crate::eval::cache::Cache::saturate].
    ///
    /// If the expression is not a variable referring to an element in the cache (this can happen
    ///  e.g. for numeric constants), we just return the term as it is, which falls into the zero
    /// dependencies special case.
    fn saturate<'a, I: DoubleEndedIterator<Item = &'a LocIdent> + Clone, C: Cache>(
        self,
        cache: &mut C,
        fields: I,
    ) -> Result<Self, EvalError>;
}

impl Saturate for NickelValue {
    fn saturate<'a, I: DoubleEndedIterator<Item = &'a LocIdent> + Clone, C: Cache>(
        self,
        cache: &mut C,
        fields: I,
    ) -> Result<NickelValue, EvalError> {
        let pos_idx = self.pos_idx();

        match self.try_into_thunk() {
            Ok(idx) => Ok(cache
                .saturate(idx.clone(), fields.map(LocIdent::ident))
                .with_pos_idx(pos_idx)),
            // It's possible for constants, or arbitrary deserialized data since the introduction
            // of the compact value representation (`NickelValue`), to not be closurized.
            Err(this) => Ok(this),
        }
    }
}

/// Return the dependencies of a field when represented as a `NickelValue`.
fn field_deps<C: Cache>(cache: &C, value: &NickelValue) -> Result<FieldDeps, EvalError> {
    if let Some(idx) = value.as_thunk() {
        Ok(cache.deps(idx).unwrap_or_else(FieldDeps::empty))
    } else {
        Ok(FieldDeps::empty())
    }
}

/// Take the current environment, two fields with their local environment, and return a term which
/// is the merge of the two fields, closurized in the provided final environment.
///
/// The element in the cache allocated for the result is revertible if and only if at least one of
/// the original elements is (if one of the original values is overridable, then so is the merge of
/// the two). In this case, the field dependencies are the union of the dependencies of each field.
///
/// The fields are saturated (see [saturate]) to properly propagate recursive dependencies down to
/// `t1` and `t2` in the final, merged record.
#[allow(clippy::too_many_arguments)]
fn fields_merge_closurize<'a, I: DoubleEndedIterator<Item = &'a LocIdent> + Clone, C: Cache>(
    cache: &mut C,
    merge_label: MergeLabel,
    t1: NickelValue,
    t2: NickelValue,
    fields: I,
) -> Result<NickelValue, EvalError> {
    let combined_deps = field_deps(cache, &t1)?.union(field_deps(cache, &t2)?);
    let body = NickelValue::from(Term::op2(
        BinaryOp::Merge(merge_label),
        t1.saturate(cache, fields.clone())?,
        t2.saturate(cache, fields)?,
    ));

    // We closurized the final result with appropriate dependencies, so we can return a closure
    // with an empty environment.
    let idx = cache.add(body.into(), BindingType::Revertible(combined_deps));

    Ok(idx.into())
}

/// Same as [Closurizable], but also revert the element if the term is a closure.
pub(super) trait RevertClosurize {
    /// Revert the element at the index inside the term (if any)
    fn revert_closurize<C: Cache>(self, cache: &mut C) -> Self;
}

impl RevertClosurize for NickelValue {
    fn revert_closurize<C: Cache>(self, _cache: &mut C) -> NickelValue {
        if let Some(thunk) = self.as_thunk() {
            thunk.revert().into()
        } else {
            // It's possible for constants, or arbitrary deserialized data since the introduction
            // of the compact value representation (`NickelValue`), to not be closurized.
            self
        }
    }
}

impl RevertClosurize for Field {
    fn revert_closurize<C: Cache>(self, cache: &mut C) -> Field {
        let value = self.value.map(|value| value.revert_closurize(cache));
        let pending_contracts = self.pending_contracts.revert_closurize(cache);

        Field {
            metadata: self.metadata,
            value,
            pending_contracts,
        }
    }
}

impl RevertClosurize for RuntimeContract {
    fn revert_closurize<C: Cache>(self, cache: &mut C) -> RuntimeContract {
        self.map_contract(|ctr| ctr.revert_closurize(cache))
    }
}

impl RevertClosurize for Vec<RuntimeContract> {
    fn revert_closurize<C: Cache>(self, cache: &mut C) -> Vec<RuntimeContract> {
        self.into_iter()
            .map(|pending_contract| pending_contract.revert_closurize(cache))
            .collect()
    }
}

pub mod split {
    use crate::term::IndexMap;

    pub struct SplitResult<K, V1, V2> {
        pub left: IndexMap<K, V1>,
        pub center: IndexMap<K, (V1, V2)>,
        pub right: IndexMap<K, V2>,
    }

    /// Split two maps m1 and m2 in three parts (left,center,right), where left holds bindings
    /// `(key,value)` where key is not in `m2.keys()`, right is the dual (keys of m2 that are not
    /// in m1), and center holds bindings for keys that are both in m1 and m2.
    pub fn split<K, V1, V2>(m1: IndexMap<K, V1>, m2: IndexMap<K, V2>) -> SplitResult<K, V1, V2>
    where
        K: std::hash::Hash + Eq,
    {
        let mut left = IndexMap::new();
        let mut center = IndexMap::new();
        let mut right = m2;

        for (key, value) in m1 {
            // We don't preserve the ordering of the right part. However, note that currently, what
            // matters is that the iteration order on hashmap is _deterministic_. It's a bonus that
            // it corresponds to insertion order for record literal, but we don't make any
            // guarantee on the result of merging or other operations. Exporting will sort the
            // result anyway.
            if let Some(v2) = right.swap_remove(&key) {
                center.insert(key, (value, v2));
            } else {
                left.insert(key, value);
            }
        }

        SplitResult {
            left,
            center,
            right,
        }
    }

    /// Same as [split], but takes the maps by reference, and clone data as needed.
    pub fn split_ref<K, V1: Clone, V2: Clone>(
        m1: &IndexMap<K, V1>,
        m2: &IndexMap<K, V2>,
    ) -> SplitResult<K, V1, V2>
    where
        K: std::hash::Hash + Eq + Clone,
    {
        let mut center = IndexMap::new();
        // We reuse the hashmap structure to remember what has been already put in the center. To
        // do so, we clone of the map and remove elements as found in the other. To limit the work
        // done here, we clone the smallest of the two maps.
        //
        // We don't preserve the ordering of the non-cloned part. However, note that currently,
        // what matters is that the iteration order on hashmap is _deterministic_. It's a bonus
        // that it corresponds to insertion order for record literal, but we don't make any
        // guarantee on the result of merging or other operations. Exporting will sort the result
        // anyway.
        if m1.len() < m2.len() {
            let mut left = m1.clone();
            let mut right = IndexMap::new();

            for (key, v2) in m2.iter() {
                if let Some(v1) = left.swap_remove(key) {
                    center.insert(key.clone(), (v1, v2.clone()));
                } else {
                    right.insert(key.clone(), v2.clone());
                }
            }

            SplitResult {
                left,
                center,
                right,
            }
        } else {
            let mut left = IndexMap::new();
            let mut right = m2.clone();

            for (key, v1) in m1.iter() {
                if let Some(v2) = right.swap_remove(key) {
                    center.insert(key.clone(), (v1.clone(), v2));
                } else {
                    left.insert(key.clone(), v1.clone());
                }
            }

            SplitResult {
                left,
                center,
                right,
            }
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn all_left() -> Result<(), String> {
            let mut m1 = IndexMap::new();
            let m2 = IndexMap::<isize, isize>::new();

            m1.insert(1, 1);
            let SplitResult {
                mut left,
                center,
                right,
            } = split(m1, m2);

            if left.swap_remove(&1) == Some(1)
                && left.is_empty()
                && center.is_empty()
                && right.is_empty()
            {
                Ok(())
            } else {
                Err(String::from("Expected all elements to be in the left part"))
            }
        }

        #[test]
        fn all_right() -> Result<(), String> {
            let m1 = IndexMap::<isize, isize>::new();
            let mut m2 = IndexMap::new();

            m2.insert(1, 1);
            let SplitResult {
                left,
                center,
                mut right,
            } = split(m1, m2);

            if right.swap_remove(&1) == Some(1)
                && right.is_empty()
                && left.is_empty()
                && center.is_empty()
            {
                Ok(())
            } else {
                Err(String::from(
                    "Expected all elements to be in the right part",
                ))
            }
        }

        #[test]
        fn all_center() -> Result<(), String> {
            let mut m1 = IndexMap::new();
            let mut m2 = IndexMap::new();

            m1.insert(1, 1);
            m2.insert(1, 2);
            let SplitResult {
                left,
                mut center,
                right,
            } = split(m1, m2);

            if center.swap_remove(&1) == Some((1, 2))
                && center.is_empty()
                && left.is_empty()
                && right.is_empty()
            {
                Ok(())
            } else {
                Err(String::from(
                    "Expected all elements to be in the center part",
                ))
            }
        }

        #[test]
        fn mixed() -> Result<(), String> {
            let mut m1 = IndexMap::new();
            let mut m2 = IndexMap::new();

            m1.insert(1, 1);
            m1.insert(2, 1);
            m2.insert(1, -1);
            m2.insert(3, -1);
            let SplitResult {
                mut left,
                mut center,
                mut right,
            } = split(m1, m2);

            if left.swap_remove(&2) == Some(1)
                && center.swap_remove(&1) == Some((1, -1))
                && right.swap_remove(&3) == Some(-1)
                && left.is_empty()
                && center.is_empty()
                && right.is_empty()
            {
                Ok(())
            } else {
                Err(String::from(
                    "Expected all elements to be in the center part",
                ))
            }
        }
    }
}//! Evaluation of a Nickel term.
//!
//! Implementation of the Nickel abstract machine. Note that this machine is not currently
//! formalized somewhere and is just a convenient name to designate the current implementation.
//!
//! # The Nickel Abstract Machine
//!
//! The abstract machine is a stack machine composed of the following elements:
//!
//! - The term being currently evaluated
//! - The main stack, storing arguments, cache indices and pending computations (continuations)
//! - A pair of [environment][Environment], mapping identifiers to [closures][Closure]:
//!     - The initial environment contains builtin functions accessible from anywhere, is immutable
//!       and alive during the whole evaluation
//!     - The local environment contains the variables in scope of the current term and is subject
//!       to garbage collection (currently reference counting based)
//! - A [callstack], mainly for error reporting purpose
//!
//! Depending on the shape of the current term, the following actions are performed:
//!
//! ## Core calculus
//!
//! - **variable (`id`)**: the term bound to `id` in the environment is fetched, and an update index is
//!   pushed on the stack to indicate that once this term has been evaluated, the cached value for
//!   this variable must be updated
//! - **application `func arg`**: a closure containing the argument and the current environment is pushed on
//!   the stack and the VM proceed with the evaluation of `func`
//! - **`let id = term in body`**: `term` is bound to `id` in the environment and the VM proceeds
//!   with the evaluation of `body`
//! - **`fun id => body`**: tries to pop an argument from the stack. If there is one, we bind it to
//!   `id` in the environment and proceed with the body of the function. Otherwise, we are done:
//!   the end result is a (unapplied) function
//! - **Index on stack**: if the evaluation of the current term is done, and there is one (or
//!   several) index on the stack, this means we have to perform an evaluation cache update.
//!   Consecutive indices are popped from the stack and are updated to point to the current evaluated
//!   term.
//! - **Import**: import must have been resolved before the evaluation starts. An unresolved import
//!   causes an [`crate::error::EvalErrorKind::InternalError`]. A resolved import, identified by a
//!   `FileId`, is retrieved from the import resolver and evaluation proceeds.
//!
//! ## Operators
//!
//! Operators are strict by definition. To evaluate say `exp1 + exp2`, the following steps have to
//! be performed:
//!
//! - `exp1` needs to be evaluated. The result must be saved somewhere, together with the resulting
//!   environment
//! - same thing for `exp2`
//! - Finally, the implementation of `+` can proceed with the computation
//!
//! We detail the case of binary operators, as the case of unary ones is similar and simpler.
//!
//! - **Op(op, first, second)**: pushes an `OpFirst` element on the stack, which saves the operator
//!   `op`, the second argument `second` and the current environment, and proceed with the evaluation
//!   of `first`
//! - **OpFirst on stack**: if the evaluation of the current term is done and there is an `OpFirst`
//!   marker on the stack, then:
//!     1. Extract the saved operator, the second argument and the environment `env2` from the
//!        marker
//!     2. Push an `OpSecond` marker, saving the operator and the evaluated form of the first
//!        argument with its environment
//!     3. Proceed with the evaluation of the second argument in environment `env2`
//! - **OpSecond on stack**: once the second term is evaluated, we can get back the operator and the
//!   first term evaluated, and forward all both arguments evaluated and their respective
//!   environment to the specific implementation of the operator (located in [operation], or in
//!   [merge] for `merge`).
//!
//! # Garbage collection
//!
//! Currently the machine relies on Rust's reference counting to manage memory. Precisely, the
//! environment stores `Rc<RefCell<Closure>>` objects, which are reference-counted pointers to a
//! mutable memory cell. This means that we do not deep copy everything everywhere, but this is
//! probably suboptimal for a functional language and is unable to collect cyclic data, which may
//! appear inside recursive records. A dedicated garbage collector is probably something to
//! consider at some point.
use crate::{
    cache::{CacheHub as ImportCaches, ImportResolver},
    closurize::{Closurize, closurize_rec_record},
    environment::Environment as GenericEnvironment,
    error::{
        Error, EvalCtxt, EvalError, EvalErrorData, EvalErrorKind, PointedExportErrorData, Reporter,
        warning::Warning,
    },
    files::{FileId, Files},
    identifier::{Ident, LocIdent},
    metrics::{increment, measure_runtime},
    position::{PosIdx, PosTable},
    program::FieldPath,
    term::{
        BinaryOp, BindingType, FunData, Import, RecordOpKind, RuntimeContract, StrChunk, Term,
        UnaryOp, make as mk_term,
        record::{Field, RecordData},
        string::NickelString,
    },
    transform::gen_pending_contracts,
    typ::UnboundTypeVariableError,
};

use std::{
    io::Write,
    mem::ManuallyDrop,
    ops::{Deref, DerefMut},
};

pub mod cache;
pub mod callstack;
pub mod contract_eq;
pub mod fixpoint;
pub mod merge;
pub mod operation;
#[cfg(feature = "incremental-experimental")]
pub mod semantic_hash;
pub mod stack;
pub mod value;

use callstack::*;
#[cfg(feature = "incremental-experimental")]
use semantic_hash::Register as _;
use stack::{
    Op1ContItem, Op2FirstContItem, OpNContItem, PrimopAppInfo, SealedCont, Stack, StrAccItem,
};
use value::{Container, EnumVariantData, NickelValue, ValueContent, ValueContentRef};

use self::cache::{Cache, CacheIndex};

impl AsRef<Vec<StackElem>> for CallStack {
    fn as_ref(&self) -> &Vec<StackElem> {
        &self.0
    }
}

/// The context of the Nickel virtual machine. The context stores external state that might need to
/// outlive one VM instance and configuration. The virtual machine typically borrows the context
/// mutably.
pub struct VmContext<R: ImportResolver, C: Cache> {
    /// The interface used to resolve and fetch imports.
    pub import_resolver: R,
    /// The stream for writing trace output.
    pub trace: Box<dyn Write>,
    /// A collector for warnings. Currently we only collect warnings and not errors; errors
    /// terminate evaluation (or typechecking, or whatever) immediately, and so they just
    /// get early-returned in a `Result`.
    pub reporter: Box<dyn Reporter<(Warning, Files)>>,
    /// The evaluation cache.
    pub cache: C,
    /// The position table, mapping position indices to spans.
    pub pos_table: PosTable,
    /// Bindings to layer on top of the stdlib in the initial environment when a [VirtualMachine]
    /// is created via [VirtualMachine::new]. On collision, the extension wins; on duplicate
    /// identifiers within the vector, the later entry wins. Configured via
    /// [Self::with_extend_env]; defaults to empty.
    pub extend_env: Vec<(Ident, NickelValue)>,
    /// Whether incremental evaluation is enabled or not. Incremental evaluation is currently
    /// feature-gated, but even when compiled with the feature, it needs to be explicitly enabled
    /// through this feature.
    #[cfg(feature = "incremental-experimental")]
    pub enable_incremental_evaluation: bool,
}

impl<R: ImportResolver, C: Cache> VmContext<R, C> {
    /// Creates a new VM context from a resolver, a trace sink and a reporter. Creates a new empty
    /// position table and eval cache.
    pub fn new(
        import_resolver: R,
        trace: impl Write + 'static,
        reporter: impl Reporter<(Warning, Files)> + 'static,
    ) -> Self {
        Self::new_with_pos_table(import_resolver, PosTable::new(), trace, reporter)
    }

    /// Creates a new VM context from a resolver, a position table, a trace sink and a reporter.
    /// Creates a new empty eval cache.
    pub fn new_with_pos_table(
        import_resolver: R,
        pos_table: PosTable,
        trace: impl Write + 'static,
        reporter: impl Reporter<(Warning, Files)> + 'static,
    ) -> Self {
        VmContext {
            import_resolver,
            trace: Box::new(trace),
            reporter: Box::new(reporter),
            cache: C::new(),
            pos_table,
            extend_env: Vec::new(),
            #[cfg(feature = "incremental-experimental")]
            enable_incremental_evaluation: false,
        }
    }

    /// Layer additional bindings on top of the stdlib in the initial environment of any
    /// [VirtualMachine] subsequently constructed from this context. Calling this
    /// multiple times replaces the previously configured bindings. On collision
    /// with the initial evaluation environment, the extension wins.
    pub fn with_extend_env(mut self, env: Vec<(Ident, NickelValue)>) -> Self {
        self.extend_env = env;
        self
    }

    /// Enable incremental evaluation for this VM.
    #[cfg(feature = "incremental-experimental")]
    pub fn with_incremental_evaluation(mut self) -> Self {
        self.enable_incremental_evaluation = true;
        self
    }
}

/// Many functions in [self] and submodules returns an error of type [EvalErrorKind]. However, this
/// error is large, so we box it to avoid performance issues related to large error variant (and to
/// satisfy clippy).
pub type ErrorKind = Box<EvalErrorKind>;

impl From<UnboundTypeVariableError> for ErrorKind {
    fn from(err: UnboundTypeVariableError) -> Self {
        Box::new(err.into())
    }
}

impl From<PointedExportErrorData> for ErrorKind {
    fn from(err: PointedExportErrorData) -> Self {
        Box::new(err.into())
    }
}

impl<C: Cache> VmContext<ImportCaches, C> {
    /// Prepares the underlying program for evaluation (load the stdlib, typecheck, transform,
    /// etc.).
    pub fn prepare_eval(&mut self, main_id: FileId) -> Result<NickelValue, Error> {
        self.prepare_eval_impl(main_id, true)
    }

    /// Same as [Self::prepare_eval], but skip typechecking.
    pub fn prepare_eval_only(&mut self, main_id: FileId) -> Result<NickelValue, Error> {
        self.prepare_eval_impl(main_id, false)
    }

    /// Register every binding configured via [Self::with_extend_env] in the typing context as
    /// `Dyn`. No-op if the extend env is empty. Idempotent: callable multiple times.
    pub fn register_extend_env_for_typecheck(&mut self) {
        if !self.extend_env.is_empty() {
            let idents: Vec<_> = self.extend_env.iter().map(|(id, _)| *id).collect();
            self.import_resolver.add_dyn_type_bindings(idents);
        }
    }

    fn prepare_eval_impl(
        &mut self,
        main_id: FileId,
        typecheck: bool,
    ) -> Result<NickelValue, Error> {
        measure_runtime!(
            "runtime:prepare_stdlib",
            self.import_resolver.prepare_stdlib(&mut self.pos_table)?
        );

        self.register_extend_env_for_typecheck();

        measure_runtime!(
            "runtime:prepare_main",
            if typecheck {
                self.import_resolver.prepare(&mut self.pos_table, main_id)
            } else {
                self.import_resolver
                    .prepare_eval_only(&mut self.pos_table, main_id)
            }
        )?;

        // Unwrap: closurization only fails if the input wasn't parsed, and we just
        // parsed it.
        self.import_resolver
            .closurize(&mut self.cache, main_id)
            .unwrap();

        Ok(self.import_resolver.get(main_id).unwrap())
    }
}

/// The Nickel virtual machine.
///
/// # Drop
///
/// The virtual machine implements [Drop]. The stack is unwinded by default upon dropping, which
/// amounts to calling [VirtualMachine::reset()], and avoids leaving thunks in the blackholed state
/// on abort. If you don't need unwinding and don't want to pay for it (though it doesn't cost
/// anything for successful executions), see [NoUnwindVirtualMachine].
pub struct VirtualMachine<'ctxt, R: ImportResolver, C: Cache> {
    context: &'ctxt mut VmContext<R, C>,
    /// The main stack, storing arguments, cache indices and pending computations.
    stack: Stack<C>,
    /// The call stack, for error reporting.
    call_stack: CallStack,
    /// The initial environment containing stdlib and builtin functions accessible from anywhere
    initial_env: Environment,
}

impl<'ctxt, R: ImportResolver, C: Cache> Drop for VirtualMachine<'ctxt, R, C> {
    fn drop(&mut self) {
        self.reset();
    }
}

impl<'ctxt, R: ImportResolver, C: Cache> VirtualMachine<'ctxt, R, C> {
    /// Creates a new VM with an empty initial environment. See [Self::new] for initialization of
    /// the initial environment when `R` is instantiated to [crate::cache::CacheHub].
    pub fn new_empty_env(context: &'ctxt mut VmContext<R, C>) -> Self {
        VirtualMachine {
            context,
            call_stack: Default::default(),
            stack: Stack::new(),
            initial_env: Environment::new(),
        }
    }

    pub fn warn(&mut self, warning: Warning) {
        self.context
            .reporter
            .report((warning, self.context.import_resolver.files().clone()));
    }

    /// Reset the state of the machine (stacks, eval mode and state of cached elements) to prepare
    /// for another evaluation round.
    pub fn reset(&mut self) {
        self.call_stack.0.clear();
        self.stack.unwind(&mut self.context.cache);
    }

    pub fn import_resolver(&self) -> &R {
        &self.context.import_resolver
    }

    pub fn import_resolver_mut(&mut self) -> &mut R {
        &mut self.context.import_resolver
    }

    /// Evaluate a Nickel expression. Wrapper around [VirtualMachine::eval_closure] that starts
    /// from an empty local environment and drops the final environment.
    pub fn eval(&mut self, value: NickelValue) -> Result<NickelValue, EvalError> {
        self.eval_closure(value.into()).map(|closure| closure.value)
    }

    /// Fully evaluate a Nickel term: the result is not a WHNF but to a value with all variables
    /// substituted.
    pub fn eval_full(&mut self, value: NickelValue) -> Result<NickelValue, EvalError> {
        self.eval_full_closure(value.into())
            .map(|result| result.value)
    }

    /// Same as [Self::eval_full], but takes a closure as an argument instead of a term.
    pub fn eval_full_closure(&mut self, closure: Closure) -> Result<Closure, EvalError> {
        self.eval_deep_closure_impl(closure, false)
            .map(|result| Closure {
                value: subst(
                    &self.context.pos_table,
                    &self.context.cache,
                    result.value,
                    &self.initial_env,
                    &result.env,
                ),
                env: result.env,
            })
    }

    /// Like [Self::eval_full], but skips evaluating record fields marked `not_exported`.
    pub fn eval_full_for_export(&mut self, value: NickelValue) -> Result<NickelValue, EvalError> {
        self.eval_deep_closure_impl(value.into(), true)
            .map(|result| {
                subst(
                    &self.context.pos_table,
                    &self.context.cache,
                    result.value,
                    &self.initial_env,
                    &result.env,
                )
            })
    }

    /// Same as [Self::eval_full_for_export], but takes a closure as an argument instead of a term.
    pub fn eval_full_for_export_closure(
        &mut self,
        closure: Closure,
    ) -> Result<NickelValue, EvalError> {
        self.eval_deep_closure_impl(closure, true).map(|result| {
            subst(
                &self.context.pos_table,
                &self.context.cache,
                result.value,
                &self.initial_env,
                &result.env,
            )
        })
    }

    /// Fully evaluates a Nickel term like `eval_full`, but does not substitute all variables.
    pub fn eval_deep(&mut self, value: NickelValue) -> Result<NickelValue, EvalError> {
        self.eval_deep_closure_impl(value.into(), false)
            .map(|result| result.value)
    }

    /// Same as [Self::eval_deep], but take a closure as an argument instead of a term.
    pub fn eval_deep_closure(&mut self, closure: Closure) -> Result<NickelValue, EvalError> {
        self.eval_deep_closure_impl(closure, false)
            .map(|result| result.value)
    }

    /// Use a specific initial environment for evaluation. Usually, [VmContext::prepare_eval] is
    /// populating the initial environment. But in some cases, such as testing or benchmarks, we
    /// might want to use a different one.
    ///
    /// Return the new virtual machine with the updated initial environment.
    pub fn with_initial_env(mut self, env: Environment) -> Self {
        self.initial_env = env;
        self
    }

    fn eval_deep_closure_impl(
        &mut self,
        mut closure: Closure,
        for_export: bool,
    ) -> Result<Closure, EvalError> {
        closure.value = mk_term::op1(
            UnaryOp::Force {
                ignore_not_exported: for_export,
            },
            closure.value,
        );

        self.eval_closure(closure)
    }

    /// Take a term and a field path, and evaluate until the corresponding field can be extracted.
    /// Return the resulting field in its final environment.
    ///
    /// Note that this method doesn't evaluate the content of the field itself. Calling it with an
    /// empty path simply returns the original expression unevaluated in an empty environment. If
    /// you need to evaluate the value later, don't forget to apply pending contracts stored in the
    /// field.
    ///
    /// For example, extracting `foo.bar.baz` on a term `exp` will evaluate `exp` to a record and
    /// try to extract the field `foo`. If anything goes wrong (the result isn't a record or the
    /// field `bar` doesn't exist), a proper error is raised. Otherwise,
    /// [Self::extract_field_closure] applies the same recipe recursively and evaluate the content
    /// of the `foo` field extracted from `exp` to a record, tries to extract `bar`, and so on.
    pub fn extract_field_closure(
        &mut self,
        closure: Closure,
        path: &FieldPath,
    ) -> Result<(Field, Environment), EvalError> {
        self.extract_field_impl(closure, path, false)
    }

    /// Same as [Self::extract_field_closure], but also requires that the field value is defined
    /// and returns the value directly.
    ///
    /// This method also applies potential pending contracts to the value.
    ///
    /// In theory, extracting the value could be done manually after calling to
    /// [Self::extract_field_closure], instead of needing a separate method.
    ///
    /// However, once [Self::extract_field_closure] returns, most contextual information required
    /// to raise a proper error if the field is missing (e.g. positions) has been lost. So, if the
    /// returned field's value is `None`, we would have a hard time reporting a good error message.
    /// On the other hand, [Self::extract_field_value_closure] raises the error earlier, when the
    /// context is still available.
    pub fn extract_field_value_closure(
        &mut self,
        closure: Closure,
        path: &FieldPath,
    ) -> Result<Closure, EvalError> {
        let (field, env) = self.extract_field_impl(closure, path, true)?;

        // unwrap(): by definition, extract_field_impl(_, _, true) ensure that
        // `field.value.is_some()`
        let value = field.value_with_pending_contracts().unwrap();

        let Closure { value, env } = self.eval_closure(Closure { value, env })?;

        Ok(Closure { value, env })
    }

    fn extract_field_impl(
        &mut self,
        closure: Closure,
        path: &FieldPath,
        require_defined: bool,
    ) -> Result<(Field, Environment), EvalError> {
        let mut prev_pos_idx = closure.value.pos_idx();

        let mut field: Field = closure.value.into();
        let mut path = path.0.iter().peekable();
        let mut env = closure.env;

        let Some(mut prev_id) = path.peek().cloned() else {
            return Ok((field, env));
        };

        for id in path {
            let Some(current_value) = field.value_with_pending_contracts() else {
                return self.throw_with_ctxt(EvalErrorKind::MissingFieldDef {
                    id: *prev_id,
                    metadata: field.metadata.into_inner(),
                    pos_record: prev_pos_idx,
                    pos_access: PosIdx::NONE,
                });
            };
            prev_pos_idx = current_value.pos_idx();

            // We evaluate the fields' value, either to handle the next ident of the
            // path, or to show the value if we are treating the last ident of the path
            let current_evaled = self.eval_closure(Closure {
                value: current_value,
                env,
            })?;

            env = current_evaled.env;

            match current_evaled.value.content_ref() {
                ValueContentRef::Record(container) => {
                    let Some(next_field) = container.get(*id).cloned() else {
                        let pos_op = self.context.pos_table.push(id.pos);

                        return self.throw_with_ctxt(EvalErrorKind::FieldMissing {
                            id: *id,
                            field_names: container.field_names(RecordOpKind::IgnoreEmptyOpt),
                            operator: "extract_field".to_owned(),
                            pos_record: prev_pos_idx,
                            // TODO: we need to push back the position in the table, which isn't
                            // too bad, but is a bit useless. Maybe we should have a runtime
                            // version of identifiers with `PosIdx` instead of `TermPos`?
                            pos_op,
                        });
                    };

                    field = next_field;
                }
                _ => {
                    //unwrap(): if we enter this pattern branch, `field.value` must be `Some(_)`
                    return self.throw_with_ctxt(EvalErrorKind::QueryNonRecord {
                        pos: prev_pos_idx,
                        id: *id,
                        value: current_evaled.value,
                    });
                }
            }

            prev_id = id;
        }

        if field.value.is_none() && require_defined {
            return self.throw_with_ctxt(EvalErrorKind::MissingFieldDef {
                id: *prev_id,
                metadata: field.metadata.into_inner(),
                pos_record: prev_pos_idx,
                pos_access: PosIdx::NONE,
            });
        }

        Ok((field, env))
    }

    pub fn query(&mut self, v: NickelValue, path: &FieldPath) -> Result<Field, EvalError> {
        self.query_closure(v.into(), path)
    }

    /// Generates an error context from this virtual machine. This consumes the callstack, which
    /// doesn't have to be preserved after an error. However, we have to preserve the position
    /// table, since the VM could be reset and used for another evaluation round. The latter is
    /// copied.
    fn eval_ctxt(&mut self) -> EvalCtxt {
        EvalCtxt {
            call_stack: std::mem::take(&mut self.call_stack),
            pos_table: self.context.pos_table.clone(),
        }
    }

    /// Wraps [Self::err_with_ctxt] in the `Err` variant.
    fn throw_with_ctxt<T>(&mut self, error: EvalErrorKind) -> Result<T, EvalError> {
        Err(self.err_with_ctxt(error))
    }

    /// Wraps an evaluation error [crate::error::EvalError] with the current evaluation context
    /// ([Self::eval_ctxt]) to make a [crate::error::EvalError].
    fn err_with_ctxt(&mut self, error: EvalErrorKind) -> EvalError {
        Box::new(EvalErrorData {
            error,
            ctxt: self.eval_ctxt(),
        })
    }

    /// Same as [VirtualMachine::query], but starts from a closure instead of a term in an empty
    /// environment.
    pub fn query_closure(
        &mut self,
        closure: Closure,
        path: &FieldPath,
    ) -> Result<Field, EvalError> {
        // extract_field does almost what we want, but for querying, we evaluate the content of the
        // field as well in order to print a potential default value.
        let (mut field, env) = self.extract_field_closure(closure, path)?;

        if let Some(value) = field.value_with_pending_contracts() {
            field.value = Some(self.eval_closure(Closure { value, env })?.value);
        }

        Ok(field)
    }

    fn enter_cache_index(
        &mut self,
        var: Option<LocIdent>,
        mut idx: CacheIndex,
        pos_idx: PosIdx,
        env: Environment,
    ) -> Result<Closure, ErrorKind> {
        // idx may be a 1-counted RC, so we make sure we drop any reference to it from `env`, which
        // is going to be discarded anyway
        std::mem::drop(env);

        match self.context.cache.get_update_index(&mut idx) {
            Ok(Some(idx_upd)) => self.stack.push_update_index(idx_upd),
            Ok(None) => {}
            Err(_blackholed_error) => {
                return Err(Box::new(EvalErrorKind::InfiniteRecursion(
                    self.call_stack.clone(),
                    pos_idx,
                )));
            }
        }

        if let Some(var) = var {
            self.call_stack.enter_var(var, pos_idx);
        }

        // If we are fetching a recursive field from the environment that doesn't have
        // a definition, we complete the error with the additional information of where
        // it was accessed:
        let closure = self.context.cache.get(idx);

        let value = match closure.value.content_ref() {
            ValueContentRef::Term(Term::RuntimeError(data))
                if matches!(&**data, EvalErrorKind::MissingFieldDef { .. }) =>
            {
                let EvalErrorKind::MissingFieldDef {
                    id,
                    metadata,
                    pos_record,
                    pos_access: PosIdx::NONE,
                } = (**data).clone()
                else {
                    unreachable!();
                };

                NickelValue::term(
                    Term::RuntimeError(Box::new(EvalErrorKind::MissingFieldDef {
                        id,
                        metadata,
                        pos_record,
                        pos_access: pos_idx,
                    })),
                    pos_idx,
                )
            }
            _ => closure.value,
        };

        Ok(Closure { value, ..closure })
    }

    /// Fetches a closure from the local or the initial environment, or fails with
    /// [crate::error::EvalError::UnboundIdentifier] with either the variable position, or the
    /// provided fallback position if the former isn't defined.
    fn get_var(
        &self,
        id: LocIdent,
        env: &Environment,
        pos_idx: PosIdx,
    ) -> Result<CacheIndex, ErrorKind> {
        get_var(&self.context.pos_table, id, &self.initial_env, env, pos_idx)
    }

    /// The main loop of evaluation.
    ///
    /// Implement the evaluation loop of the core language. The specific implementations of
    /// primitive operations is delegated to the modules [operation] and [merge].
    ///
    /// # Arguments
    ///
    /// - `clos`: the closure to evaluate
    /// - `initial_env`: the initial environment containing the stdlib items.
    ///   Accessible from anywhere in the program.
    ///
    /// # Return
    ///
    /// Either:
    ///  - an evaluation error
    ///  - the evaluated term with its final environment
    pub fn eval_closure(&mut self, closure: Closure) -> Result<Closure, EvalError> {
        self.eval_closure_impl(closure)
            .map_err(|err| self.err_with_ctxt(*err))
    }

    /// Actual implementation of [Self::eval_closure]. We use this indirection mostly to use the
    /// `?` operator on [crate::error::EvalError], and only add the missing context to make it
    /// an [crate:error::EvalError] once at the end.
    fn eval_closure_impl(&mut self, mut closure: Closure) -> Result<Closure, ErrorKind> {
        #[cfg(feature = "metrics")]
        let start_time = std::time::Instant::now();

        // See https://github.com/rust-lang/rust-clippy/issues/15987.
        #[allow(clippy::let_and_return)]
        let result = loop {
            let Closure { value, mut env } = closure;
            let pos_idx = value.pos_idx();
            let has_cont_on_stack = self.stack.is_top_idx() || self.stack.is_top_cont();

            closure = match value.content_ref() {
                ValueContentRef::Thunk(_) => {
                    // unwrap(): we know that `value` is a thunk in this branch
                    self.enter_cache_index(None, value.try_into_thunk().unwrap(), pos_idx, env)?
                }
                ValueContentRef::Term(Term::Sealed(data)) => {
                    let closure = Closure {
                        value: NickelValue::term(Term::Sealed(data.clone()), pos_idx),
                        env: env.clone(),
                    };

                    // Update at the original index (the index which holds the result of the op) in
                    // both cases, even if we continue with a seq.
                    //
                    // We do this because we are on a `Sealed` term which is in weak head normal
                    // form, and if we don't, we will be unwrapping a `Sealed` term and assigning
                    // the "unsealed" value to the result of the `Seq` operation. See also:
                    // https://github.com/tweag/nickel/issues/123
                    update_at_indices(&mut self.context.cache, &mut self.stack, &closure);

                    // We have to peek the stack to see what operation is coming next and decide
                    // what to do.
                    //
                    // - If it's `unseal`, then we proceed with its evaluation, as `unseal` legitly
                    //   operates on sealed terms.
                    // - `seq` is the only primitive operation allowed to see through a sealed
                    //   term. Indeed, `seq`-ing doesn't violate parametricity, `seq`-ing shouldn't
                    //   be observable (that is, adding seq shouldn't change the semantics and
                    //   suddenly make a program blame), and it's useful in practice to seq sealed
                    //   terms such as in the implementation of `std.fold_left` to ensure we don't
                    //   accumulate thunks in memory.
                    // - If it's anything else, we raise an error right away because the
                    //   corresponding polymorphic contract has been violated: a function tried to
                    //   use a polymorphic sealed value.
                    match self.stack.peek_sealed_cont() {
                        SealedCont::Unseal => self.continue_op(closure)?,
                        SealedCont::Seq => {
                            // evaluate / `Seq` the inner value.
                            Closure {
                                value: data.inner.clone(),
                                env,
                            }
                        }
                        SealedCont::Other => {
                            // This operation should not be allowed to evaluate a sealed term
                            break Err(Box::new(EvalErrorKind::BlameError {
                                evaluated_arg: data.label.get_evaluated_arg(&self.context.cache),
                                label: (*data.label).clone(),
                            }));
                        }
                    }
                }
                ValueContentRef::Term(Term::Var(id)) => {
                    let idx = self.get_var(*id, &env, pos_idx)?;
                    self.enter_cache_index(Some(*id), idx, pos_idx, env)?
                }
                ValueContentRef::Term(Term::App(data)) => {
                    self.call_stack.enter_app(&self.context.pos_table, pos_idx);

                    self.stack.push_arg(
                        Closure {
                            value: data.arg.clone(),
                            env: env.clone(),
                        },
                        pos_idx,
                    );
                    Closure {
                        value: data.head.clone(),
                        env,
                    }
                }
                ValueContentRef::Term(Term::Let(data)) => {
                    let mut indices = Vec::new();
                    let init_env = env.clone();

                    for (x, bound) in &data.bindings {
                        let bound_closure = Closure {
                            value: bound.clone(),
                            env: init_env.clone(),
                        };

                        let idx = self
                            .context
                            .cache
                            .add(bound_closure, data.attrs.binding_type.clone());

                        // Patch the environment with the (x <- closure) binding
                        if data.attrs.rec {
                            indices.push(idx.clone());
                        }

                        #[cfg(feature = "incremental-experimental")]
                        if self.context.enable_incremental_evaluation {
                            idx.register(&mut self.context.cache);
                        }

                        env.insert(x.ident(), idx);
                    }

                    for idx in indices {
                        self.context.cache.patch(idx, |cl| cl.env = env.clone());
                    }

                    Closure {
                        value: data.body.clone(),
                        env,
                    }
                }
                ValueContentRef::Term(Term::Op1(data)) => {
                    self.stack.push_op1_cont(Op1ContItem {
                        op: data.op.clone(),
                        orig_pos_arg: data.arg.pos_idx(),
                        app_info: PrimopAppInfo {
                            call_stack_size: self.call_stack.len(),
                            pos_idx,
                        },
                    });

                    Closure {
                        value: data.arg.clone(),
                        env,
                    }
                }
                ValueContentRef::Term(Term::Op2(data)) => {
                    self.stack.push_op2_first_cont(Op2FirstContItem {
                        op: data.op.clone(),
                        app_info: PrimopAppInfo {
                            call_stack_size: self.call_stack.len(),
                            pos_idx,
                        },
                        arg2: Closure {
                            value: data.arg2.clone(),
                            env: env.clone(),
                        },
                        orig_pos_arg1: data.arg1.pos_idx(),
                    });

                    Closure {
                        value: data.arg1.clone(),
                        env,
                    }
                }
                ValueContentRef::Term(Term::OpN(data)) => {
                    // Arguments are passed as a stack to the operation continuation, so we reverse
                    // the original list.
                    let mut args_iter = data.args.iter();
                    let fst_arg = args_iter.next().ok_or_else(|| {
                        EvalErrorKind::NotEnoughArgs(data.op.arity(), data.op.to_string(), pos_idx)
                    })?;

                    let pending: Vec<Closure> = args_iter
                        .rev()
                        .map(|value| Closure {
                            value: value.clone(),
                            env: env.clone(),
                        })
                        .collect();

                    self.stack.push_opn_cont(OpNContItem {
                        op: data.op.clone(),
                        app_info: PrimopAppInfo {
                            call_stack_size: self.call_stack.len(),
                            pos_idx,
                        },
                        evaluated: Vec::with_capacity(pending.len() + 1),
                        pending,
                        current_pos_idx: fst_arg.pos_idx(),
                    });

                    Closure {
                        value: fst_arg.clone(),
                        env,
                    }
                }
                ValueContentRef::Term(Term::StrChunks(chunks)) => {
                    let mut chunks_iter = chunks.iter().cloned();
                    match chunks_iter.next_back() {
                        None => NickelValue::string(NickelString::new(), pos_idx).into(),
                        Some(chunk) => {
                            let (arg, indent) = match chunk {
                                StrChunk::Literal(s) => (NickelValue::string_posless(s), 0),
                                StrChunk::Expr(e, indent) => (e, indent),
                            };

                            self.stack.push_str_chunks(chunks_iter);
                            self.stack.push_str_acc(StrAccItem {
                                acc: String::new(),
                                env: env.clone(),
                                // unwrap(): we don't expect an indentation of `u32::MAX` lines...
                                curr_indent: indent.try_into().unwrap(),
                                curr_pos: arg.pos_idx(),
                            });

                            // TODO: we should set up the stack properly, instead of allocating an
                            // `op1` term here.
                            Closure {
                                value: NickelValue::term(
                                    Term::op1(UnaryOp::ChunksConcat, arg),
                                    pos_idx,
                                ),
                                env,
                            }
                        }
                    }
                }
                ValueContentRef::Term(Term::Closurize(value)) => {
                    match value.content_ref() {
                        ValueContentRef::Array(Container::Empty)
                        | ValueContentRef::Record(Container::Empty) => value.clone(),
                        ValueContentRef::Array(Container::Alloc(array_data)) => {
                            // This *should* make it unnecessary to call closurize in [operation].
                            // See the comment on the `BinaryOp::ArrayConcat` match arm.
                            let array = array_data
                                .array
                                .iter()
                                .cloned()
                                .map(|t| t.closurize(&mut self.context.cache, env.clone()))
                                .collect();

                            let pending_contracts = array_data
                                .pending_contracts
                                .iter()
                                .cloned()
                                .map(|ctr| {
                                    RuntimeContract::new(
                                        ctr.contract
                                            .closurize(&mut self.context.cache, env.clone()),
                                        ctr.label,
                                    )
                                })
                                .collect();

                            #[cfg(feature = "incremental-experimental")]
                            if self.context.enable_incremental_evaluation {
                                array_data.register(&mut self.context.cache);
                            }

                            NickelValue::array(array, pending_contracts, pos_idx)
                        }
                        ValueContentRef::Record(Container::Alloc(data)) => {
                            // unwrap(): we treated the empty record case already
                            let record_data = data.clone().closurize(&mut self.context.cache, env);

                            #[cfg(feature = "incremental-experimental")]
                            if self.context.enable_incremental_evaluation {
                                record_data.register(&mut self.context.cache);
                            }

                            NickelValue::record(record_data, pos_idx)
                        }
                        ValueContentRef::EnumVariant(data) => {
                            let EnumVariantData { tag, arg } = data.clone();
                            let arg = arg.map(|arg| arg.closurize(&mut self.context.cache, env));
                            NickelValue::enum_variant(tag, arg, pos_idx)
                        }
                        _ => {
                            // This case is a red flag (it should be unreachable), but
                            // isn't a blocker per se, so we only fail in debug mode.
                            debug_assert!(false, "trying to closurize a non-container value");
                            value.clone()
                        }
                    }
                    // We can use an empty environment for a freshly closurized value
                    .into()
                }
                ValueContentRef::Term(Term::RecRecord(data)) => {
                    // We start by closurizing the fields, which might not be if the record is
                    // coming out of the parser.

                    // We must avoid re-closurizing a recursive record that is already closurized
                    // (coming from `merge`, for example), as the current representation is broken
                    // if we add a new indirection. This should ideally be encoded in the Rust
                    // type, once we have a different representation for runtime evaluation,
                    // instead of relying on invariants. But for now, we have to live with it.
                    let (mut static_part, dyn_fields) = if !data.closurized {
                        let includes_as_terms: Result<Vec<_>, _> = data
                            .includes
                            .iter()
                            .map(|incl| -> Result<_, ErrorKind> {
                                let field = Field {
                                    value: Some(
                                        NickelValue::from(self.get_var(
                                            incl.ident,
                                            &env,
                                            PosIdx::NONE,
                                        )?)
                                        .with_pos(&mut self.context.pos_table, incl.ident.pos),
                                    ),
                                    metadata: incl.metadata.clone().into(),
                                    pending_contracts: Vec::new(),
                                };

                                Ok((
                                    incl.ident,
                                    gen_pending_contracts::with_pending_contracts(
                                        &mut self.context.pos_table,
                                        field,
                                    )?,
                                ))
                            })
                            .collect();

                        // We assume that the parser doesn't allow conflicts between field
                        // definitions and includes (the same field is defined in both). This
                        // restriction might be lifted in the future (we would probably merge the
                        // included field and the other definition pieces), but for now it's
                        // simpler this way.
                        let mut record = data.record.clone();
                        record.fields.extend(includes_as_terms?);

                        closurize_rec_record(
                            &mut self.context.cache,
                            record,
                            data.dyn_fields.clone(),
                            data.deps.clone(),
                            env,
                        )
                    } else {
                        // In a record that has been already closurized, we expect include
                        // expressions to be evaluated away.
                        debug_assert!(data.includes.is_empty());
                        (data.record.clone(), data.dyn_fields.clone())
                    };

                    let rec_env = fixpoint::rec_env(
                        &mut self.context.cache,
                        static_part.fields.iter(),
                        pos_idx,
                    );

                    for rt in static_part.fields.values_mut() {
                        fixpoint::patch_field(&mut self.context.cache, rt, &rec_env);
                    }

                    #[cfg(feature = "incremental-experimental")]
                    if self.context.enable_incremental_evaluation {
                        static_part.register(&mut self.context.cache);
                    }

                    // Transform the static part `{stat1 = val1, ..., statn = valn}` and the
                    // dynamic part `{exp1 = dyn_val1, ..., expm = dyn_valm}` to a sequence of
                    // extensions
                    //
                    // ```
                    // %record/insert% exp1
                    //   (...
                    //     (%record/insert% expn {stat1 = val1, ..., statn = valn} dyn_valn)
                    //   ...)
                    //   dyn_val1
                    //
                    // ```
                    //
                    // The `dyn_val` are given access to the recursive environment, but the
                    // recursive environment only contains the static fields, and not the dynamic
                    // fields.
                    let extended = dyn_fields.into_iter().fold(
                        NickelValue::record(static_part, pos_idx),
                        |acc, (name_as_term, mut field)| {
                            let pos_dyn_field = field
                                .value
                                .as_ref()
                                .map(NickelValue::pos_idx)
                                .unwrap_or_else(|| name_as_term.pos_idx());

                            fixpoint::patch_field(&mut self.context.cache, &mut field, &rec_env);

                            let ext_kind = field.extension_kind();
                            let Field {
                                metadata,
                                value,
                                pending_contracts,
                            } = field;

                            let extend = mk_term::op2(
                                BinaryOp::RecordInsert {
                                    metadata,
                                    pending_contracts,
                                    ext_kind,
                                    op_kind: RecordOpKind::ConsiderAllFields,
                                },
                                name_as_term,
                                acc,
                            );

                            match value {
                                Some(value) => NickelValue::term(
                                    Term::app(extend, value),
                                    pos_dyn_field.to_inherited(),
                                ),
                                None => extend,
                            }
                        },
                    );

                    extended.with_pos_idx(pos_idx).into()
                }
                ValueContentRef::Term(Term::ResolvedImport(id)) => {
                    increment!(format!("import:{id:?}"));

                    if let Some(val) = self.context.import_resolver.get(*id) {
                        #[cfg(feature = "incremental-experimental")]
                        if self.context.enable_incremental_evaluation {
                            val.register(&mut self.context.cache);
                        }

                        val.into()
                    } else {
                        break Err(Box::new(EvalErrorKind::InternalError(
                            format!("Resolved import not found ({id:?})"),
                            pos_idx,
                        )));
                    }
                }
                ValueContentRef::Term(Term::Import(Import::Path { path, .. })) => {
                    break Err(Box::new(EvalErrorKind::InternalError(
                        format!("Unresolved import ({})", path.to_string_lossy()),
                        pos_idx,
                    )));
                }
                ValueContentRef::Term(Term::Import(Import::Package { id })) => {
                    return Err(Box::new(EvalErrorKind::InternalError(
                        format!("Unresolved package import ({id})"),
                        pos_idx,
                    )));
                }
                ValueContentRef::Term(Term::ParseError(parse_error)) => {
                    break Err(Box::new(EvalErrorKind::ParseError((**parse_error).clone())));
                }
                ValueContentRef::Term(Term::RuntimeError(error)) => {
                    break Err(error.clone());
                }
                // For now, we simply erase annotations at runtime. They aren't accessible anyway
                // (as opposed to field metadata) and don't change the operational semantics, as
                // long as we generate the corresponding contract application when consuming it.
                //
                // The situation could change if we want to implement optimizations such as
                // avoiding repeated contract application. Annotations could then be a good way of
                // remembering which contracts have been applied to a value.
                ValueContentRef::Term(Term::Annotated(data)) => {
                    increment!("contract:free-standing(annotated)");

                    // We apply the contract coming from the static type annotation separately as
                    // it is optimized.
                    let static_contract = data.annot.static_contract(&mut self.context.pos_table);
                    let contracts = data.annot.pending_contracts(&mut self.context.pos_table)?;
                    let pos_inner = data.inner.pos_idx();
                    let inner = data.inner.clone();

                    let inner_with_static = if let Some(static_ctr) = static_contract {
                        static_ctr?.apply(inner, pos_inner)
                    } else {
                        inner
                    };

                    let inner_with_ctr =
                        RuntimeContract::apply_all(inner_with_static, contracts, pos_inner);

                    Closure {
                        value: inner_with_ctr,
                        env,
                    }
                }
                // Function call if there's no continuation on the stack (otherwise, the function
                // is just an argument to a primop or to put in the eval cache)
                ValueContentRef::Term(Term::Fun(FunData { arg, body })) if !has_cont_on_stack => {
                    if let Some((idx, pos_app)) = self.stack.pop_arg_as_idx(&mut self.context.cache)
                    {
                        self.call_stack.enter_fun(&self.context.pos_table, pos_app);
                        env.insert(arg.ident(), idx);
                        Closure {
                            value: body.clone(),
                            env,
                        }
                    } else {
                        break Ok(Closure { value, env });
                    }
                }
                // At this point, we've evaluated the current term to a weak head normal form.
                _ => {
                    let evaluated = Closure { value, env };

                    // If there is a cache index update frame on the stack, we proceed with the
                    // update of the corresponding cached value.
                    if self.stack.is_top_idx() {
                        update_at_indices(&mut self.context.cache, &mut self.stack, &evaluated);
                        evaluated
                    }
                    // If there is a primitive operator continuation on the stack, we proceed with
                    // the continuation.
                    else if self.stack.is_top_cont() {
                        self.continue_op(evaluated)?
                    }
                    // Otherwise, if the stack is non-empty, this is an ill-formed application (we
                    // are supposed to evaluate an application, but the left hand side isn't a
                    // function)
                    else if let Some((arg, pos_app)) = self.stack.pop_arg(&self.context.cache) {
                        break Err(Box::new(EvalErrorKind::NotAFunc(
                            evaluated.value,
                            arg.value,
                            pos_app,
                        )));
                    }
                    // Finally, if the stack is empty, it's all good: it just means we are done
                    // evaluating.
                    else {
                        break Ok(evaluated);
                    }
                }
            };
        };

        increment!("runtime:eval", start_time.elapsed().as_millis() as u64);

        result
    }

    /// Evaluate a term, but attempt to continue on errors.
    ///
    /// This differs from `VirtualMachine::eval_full` in three ways:
    /// - We try to accumulate errors instead of bailing out. When recursing into record
    ///   fields and array elements, we keep evaluating subsequent elements even if one
    ///   fails.
    /// - We only return the accumulated errors; we don't return the eval'ed term.
    /// - We support a recursion limit, to limit the number of times we recurse into
    ///   arrays or records.
    pub fn eval_permissive(
        &mut self,
        value: NickelValue,
        recursion_limit: usize,
    ) -> Vec<EvalError> {
        fn inner<R: ImportResolver, C: Cache>(
            this: &mut VirtualMachine<R, C>,
            acc: &mut Vec<EvalError>,
            value: NickelValue,
            recursion_limit: usize,
        ) {
            if recursion_limit == 0 {
                return;
            }

            let pos_idx = value.pos_idx();
            match this.eval(value) {
                Err(e) => {
                    acc.push(e);
                    this.reset();
                }
                Ok(val) => match val.content_ref() {
                    ValueContentRef::Array(Container::Alloc(data)) => {
                        for elt in data.iter_with_pending_contracts(pos_idx) {
                            // After eval_closure, all the array elements  are
                            // closurized already, so we don't need to do any tracking
                            // of the env.
                            inner(this, acc, elt, recursion_limit.saturating_sub(1));
                        }
                    }
                    ValueContentRef::Record(Container::Alloc(data)) => {
                        for (id, field) in &data.fields {
                            if let Some(v) = field.value_with_pending_contracts() {
                                inner(this, acc, v, recursion_limit.saturating_sub(1));
                            } else {
                                acc.push(this.err_with_ctxt(EvalErrorKind::MissingFieldDef {
                                    id: *id,
                                    metadata: field.metadata.clone_inner(),
                                    pos_record: pos_idx,
                                    pos_access: PosIdx::NONE,
                                }));
                            }
                        }
                    }
                    ValueContentRef::EnumVariant(EnumVariantData { arg: Some(arg), .. }) => {
                        inner(this, acc, arg.clone(), recursion_limit.saturating_sub(1));
                    }
                    _ => {}
                },
            }
        }

        let mut ret = Vec::new();
        inner(self, &mut ret, value, recursion_limit);
        ret
    }
}

impl<'ctxt, C: Cache> VirtualMachine<'ctxt, ImportCaches, C> {
    /// Creates a new VM, and automatically fills the initial environment with
    /// `context.import_resolver.mk_initial_env()`.
    ///
    /// Use [VmContext::with_extend_env] to expose additional names
    /// at the top level.
    pub fn new(context: &'ctxt mut VmContext<ImportCaches, C>) -> Self {
        let mut initial_env = context.import_resolver.mk_eval_env(&mut context.cache);
        // Allocate a fresh thunk for each extras binding. The values were supplied by the
        // caller in raw form, so we wrap them in closures with an empty local env before
        // inserting into the initial env. Later entries shadow earlier ones on duplicate
        // identifiers, and any binding here shadows the stdlib on collision.
        for (id, value) in &context.extend_env {
            let idx = context.cache.add(value.clone().into(), BindingType::Normal);
            initial_env.insert(*id, idx);
        }

        VirtualMachine {
            context,
            call_stack: Default::default(),
            stack: Stack::new(),
            initial_env,
        }
    }
}

/// An wrapper around [VirtualMachine] which doesn't unwind the VM stack upon destruction.
///
/// Unwinding ensures all thunks are properly cleaned from their previous state if the VM abort,
/// which makes it possible to run subsequent evaluations (whether in the same or another VM
/// instance). Since VM are light instances that are built on the spot, the default behavior is to
/// unwind upon dropping, to avoid bad surprises (and unwinding is virtually free if the evaluation
/// succeeds, since the stack is then empty).
///
/// However, it could happen that in some workflows, one wishes to avoid the cost of unwinding. In
/// that case, use this wrapper instead of [VirtualMachine].
pub struct NoUnwindVirtualMachine<'ctxt, R: ImportResolver, C: Cache>(
    ManuallyDrop<VirtualMachine<'ctxt, R, C>>,
);

impl<'ctxt, R: ImportResolver, C: Cache> NoUnwindVirtualMachine<'ctxt, R, C> {
    pub fn new(vm: VirtualMachine<'ctxt, R, C>) -> Self {
        Self(ManuallyDrop::new(vm))
    }
}

impl<'ctxt, R: ImportResolver, C: Cache> Deref for NoUnwindVirtualMachine<'ctxt, R, C> {
    type Target = VirtualMachine<'ctxt, R, C>;

    fn deref(&self) -> &Self::Target {
        self.0.deref()
    }
}

impl<'ctxt, R: ImportResolver, C: Cache> DerefMut for NoUnwindVirtualMachine<'ctxt, R, C> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.0.deref_mut()
    }
}

/// A closure, which is a value packed with its environment.
#[derive(PartialEq, Clone)]
pub struct Closure {
    pub value: NickelValue,
    pub env: Environment,
}

impl std::fmt::Debug for Closure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Closure")
            .field("body", &self.value)
            .finish_non_exhaustive()
    }
}

impl From<NickelValue> for Closure {
    fn from(value: NickelValue) -> Self {
        Closure {
            value,
            env: Environment::new(),
        }
    }
}

#[allow(type_alias_bounds)] // TODO: Look into this warning.
pub type Environment = GenericEnvironment<Ident, CacheIndex>;

/// Raised when trying to build an environment from a term which is not a record.
#[derive(Clone, Debug)]
pub enum EnvBuildError {
    NotARecord(NickelValue),
}

/// Add the bindings of a record to an environment. Ignore the fields defined by interpolation as
/// well, fields without definition and `include` expressions.
pub fn env_add_record<C: Cache>(
    cache: &mut C,
    env: &mut Environment,
    closure: Closure,
) -> Result<(), EnvBuildError> {
    if closure.value.is_inline_empty_record() {
        return Ok(());
    }

    // We unwrap potential `Closurize` sprinkled in unevaluated terms, which is typically the case
    // for the stdlib.
    let value = if let Some(Term::Closurize(inner)) = closure.value.as_term() {
        inner
    } else {
        &closure.value
    };

    let record = match value.content_ref() {
        ValueContentRef::Record(Container::Empty) => return Ok(()),
        ValueContentRef::Record(Container::Alloc(record)) => record,
        ValueContentRef::Term(Term::RecRecord(data)) => &data.record,
        _ => return Err(EnvBuildError::NotARecord(closure.value)),
    };

    let ext = record.fields.iter().filter_map(|(id, field)| {
        field.value.as_ref().map(|value| {
            (
                id.ident(),
                cache.add(
                    Closure {
                        value: value.clone(),
                        env: closure.env.clone(),
                    },
                    BindingType::Normal,
                ),
            )
        })
    });

    env.extend(ext);
    Ok(())
}

/// Bind a closure in an environment.
pub fn env_add<C: Cache>(
    cache: &mut C,
    env: &mut Environment,
    id: LocIdent,
    value: NickelValue,
    local_env: Environment,
) {
    let closure = Closure {
        value,
        env: local_env,
    };
    env.insert(id.ident(), cache.add(closure, BindingType::Normal));
}

/// Pop and update all the indices on the top of the stack with the given closure.
fn update_at_indices<C: Cache>(cache: &mut C, stack: &mut Stack<C>, closure: &Closure) {
    while let Some(idx) = stack.pop_update_index() {
        cache.update(closure.clone(), idx);
    }
}

/// Free-standing implementation of [VirtualMachine::get_var].
fn get_var(
    pos_table: &PosTable,
    id: LocIdent,
    initial_env: &Environment,
    env: &Environment,
    pos_idx: PosIdx,
) -> Result<CacheIndex, ErrorKind> {
    env.get(&id.ident())
        .or_else(|| initial_env.get(&id.ident()))
        .cloned()
        .ok_or(Box::new(EvalErrorKind::UnboundIdentifier(
            id,
            id.pos.or(pos_table.get(pos_idx)),
        )))
}

/// Recursively substitute each variable occurrence of a term for its value in the environment.
pub fn subst<C: Cache>(
    pos_table: &PosTable,
    cache: &C,
    value: NickelValue,
    initial_env: &Environment,
    env: &Environment,
) -> NickelValue {
    use value::lens::TermContent;

    let pos_idx = value.pos_idx();

    match value.content() {
        lens @ (ValueContent::Null(_)
        | ValueContent::Bool(_)
        | ValueContent::Number(_)
        | ValueContent::String(_)
        | ValueContent::CustomContract(_)
        | ValueContent::Label(_)
        // We could recurse in types, because types can contain terms which would then be subject
        // to substitution. Not recursing should be fine, though, because a type in term position
        // turns into a contract, and we don't substitute inside contracts either currently.
        | ValueContent::Type(_)
        | ValueContent::ForeignId(_)
        | ValueContent::SealingKey(_)) => lens.restore(),
        ValueContent::Thunk(lens) => {
            let closure = cache.get(lens.take());
            subst(pos_table, cache, closure.value, initial_env, &closure.env)
        }
        ValueContent::Record(lens) => {
            let Container::Alloc(record) = lens.take() else {
                return NickelValue::empty_record().with_pos_idx(pos_idx);
            };

            let record = record.map_defined_values(|_, value| subst(pos_table, cache, value, initial_env, env));

            //unwrap(): we didn't change the size of the record, so whether it was inline or not,
            //its position index should be of the according type
            NickelValue::record(record, pos_idx)
        }
        ValueContent::Array(lens) => {
            let Container::Alloc(array_data) = lens.take() else {
                return NickelValue::empty_array().with_pos_idx(pos_idx);
            };

            let array = array_data.array.into_iter()
                .map(|t| subst(pos_table, cache, t, initial_env, env))
                .collect();

            NickelValue::array(array, array_data.pending_contracts, pos_idx)
        }
        ValueContent::EnumVariant(lens) => {
            let EnumVariantData { tag, arg } = lens.take();
            let arg = arg.map(|arg| subst(pos_table, cache, arg, initial_env, env));

            NickelValue::enum_variant(tag, arg, pos_idx)
        }
        ValueContent::Term(content) => {
            match content {
                TermContent::Var(lens) => {
                    let id = lens.take();

                    get_var(pos_table, id, env, initial_env, PosIdx::NONE)
                    .map(|idx| {
                        let closure = cache.get(idx);
                        subst(pos_table, cache, closure.value, initial_env, &closure.env)
                    })
                    .unwrap_or_else(|_| NickelValue::term(Term::Var(id), pos_idx))
                }
                lens @ (TermContent::ParseError(_) | TermContent::RuntimeError(_)
                // Do not substitute under lambdas: mutually recursive function could cause an infinite
                // loop. Although avoidable, this requires some care and is not currently needed.
                | TermContent::Fun(..)
                | TermContent::Import(_)
                | TermContent::ResolvedImport(_)) => lens.restore(),
                TermContent::Let(lens) => {
                    let mut data = lens.take();

                    for (_key, val) in &mut data.bindings {
                        let prev = std::mem::take(val);
                        *val = subst(pos_table, cache, prev, initial_env, env);
                    }
                    data.body = subst(pos_table, cache, data.body, initial_env, env);

                    NickelValue::term(Term::Let(data), pos_idx)
                }
                TermContent::App(lens) => {
                    let mut data = lens.take();
                    data.head = subst(pos_table, cache, data.head, initial_env, env);
                    data.arg = subst(pos_table, cache, data.arg, initial_env, env);

                    NickelValue::term(Term::App(data), pos_idx)
                }
                TermContent::Op1(lens) => {
                    let mut data = lens.take();
                    data.arg = subst(pos_table, cache, data.arg, initial_env, env);

                    NickelValue::term(Term::Op1(data), pos_idx)
                }
                TermContent::Op2(lens) => {
                    let mut data = lens.take();
                    data.arg1 = subst(pos_table, cache, data.arg1, initial_env, env);
                    data.arg2 = subst(pos_table, cache, data.arg2, initial_env, env);

                    NickelValue::term(Term::Op2(data), pos_idx)
                }
                TermContent::OpN(lens) => {
                    let mut data = lens.take();
                    data.args = data.args
                        .into_iter()
                        .map(|t| subst(pos_table, cache, t, initial_env, env))
                        .collect();

                    NickelValue::term(Term::OpN(data), pos_idx)
                }
                TermContent::Sealed(lens) => {
                    let mut data = lens.take();
                    data.inner = subst(pos_table, cache, data.inner, initial_env, env);
                    NickelValue::term(Term::Sealed(data), pos_idx)
                }
                // Currently, we downright ignore `include` expressions. However, one could argue that
                // substituting `foo` for `bar` in `{include foo}` should result in `{foo = bar}`.
                TermContent::RecRecord(lens) => {
                    let mut data = lens.take();

                    data.record = data.record
                        .map_defined_values(|_, value| subst(pos_table, cache, value, initial_env, env));

                    data.dyn_fields = data.dyn_fields
                        .into_iter()
                        .map(|(id_t, field)| {
                            (
                                subst(pos_table, cache, id_t, initial_env, env),
                                field.map_value(|v| subst(pos_table, cache, v, initial_env, env)),
                            )
                        })
                        .collect();

                    NickelValue::term(Term::RecRecord(data), pos_idx)
                }
                TermContent::StrChunks(lens) => {
                    let chunks = lens.take()
                        .into_iter()
                        .map(|chunk| match chunk {
                            chunk @ StrChunk::Literal(_) => chunk,
                            StrChunk::Expr(t, indent) => StrChunk::Expr(
                                subst(pos_table, cache, t, initial_env, env),
                                indent,
                            ),
                        })
                        .collect();

                    NickelValue::term(Term::StrChunks(chunks), pos_idx)
                }
                TermContent::Annotated(lens) => {
                    let mut data = lens.take();
                    data.inner = subst(pos_table, cache, data.inner, initial_env, env);
                    // Currently, there is no interest in replacing variables inside contracts, thus we
                    // limit the work of `subst`.
                    NickelValue::term(Term::Annotated(data), pos_idx)
                }
                TermContent::Closurize(lens) => {
                    NickelValue::term(Term::Closurize(subst(pos_table, cache, lens.take(), initial_env, env)), pos_idx)
                }
            }
        }
    }
}

