/// Result of the equality of two terms.
///
/// The equality of two terms can either be computed directly for base types (`Number`, `String`,
/// etc.), in which case `Bool` is returned. Otherwise, composite values such as arrays or records
/// generate new subequalities, as represented by the last variant as a vector of pairs of terms.
/// This list should be non-empty (it if was empty, `eq` should have returned `Bool(true)`
/// directly).  The first element of this non-empty list is encoded as the two first parameters of
/// `Eqs`, while the last vector parameter is the (potentially empty) tail.
///
/// See [`eq`].
enum EqResult {
    Bool(bool),
    Eqs(NickelValue, NickelValue, Vec<(Closure, Closure)>),
}

/// All the data required to evaluate a unary operation.
struct Op1EvalData {
    /// The unary operation to apply.
    op: UnaryOp,
    /// The evaluated argument.
    arg: Closure,
    /// The position of the original expression of the argument, when it was put on the stack for
    /// evaluation.
    orig_pos_arg: PosIdx,
    /// The position of the primop application.
    pos_op: PosIdx,
}

/// All the data required to evaluate a binary operation.
struct Op2EvalData {
    /// The binary operation to apply.
    op: BinaryOp,
    /// The first argument evaluated.
    arg1: Closure,
    /// The second argument evaluated.
    arg2: Closure,
    /// The position of the original expression of the first argument, when it was put on the stack
    /// for evaluation.
    orig_pos_arg1: PosIdx,
    /// The position of the original expression of the second argument, when it was put on the
    /// stack for evaluation.
    orig_pos_arg2: PosIdx,
    /// The position of the primop application.
    pos_op: PosIdx,
}

struct OpNEvalData {
    /// The n-ary operation to apply.
    op: NAryOp,
    /// The arguments evaluated, together with the position of their original expression, when it
    /// was put on the stack for evaluation.
    args: Vec<(Closure, PosIdx)>,
    /// The position of the primop application.
    pos_op: PosIdx,
}

/// A string representation of the type of the first argument of serialization-related primitive
/// operations. This is a Nickel enum of the supported serialization formats.
static ENUM_FORMAT: &str = "[| 'Json, 'Toml, 'Yaml, 'YamlDocuments |]";

impl<'ctxt, R: ImportResolver, C: Cache> VirtualMachine<'ctxt, R, C> {
    /// Proceeds to the next step of the evaluation of a primitive operation.
    ///
    /// Depending on the content of the stack, it either starts the evaluation of the next argument
    /// or finally proceed with the operation if all arguments are evaluated.
    pub fn continue_op(&mut self, closure: Closure) -> Result<Closure, ErrorKind> {
        if let Some(op1_cont) = self.stack.pop_op1_cont() {
            self.call_stack
                .truncate(op1_cont.app_info.call_stack_size as usize);

            self.eval_op1(Op1EvalData {
                op: op1_cont.op,
                arg: closure,
                orig_pos_arg: op1_cont.orig_pos_arg,
                pos_op: op1_cont.app_info.pos_idx,
            })
        } else if let Some(op2_fst_cont) = self.stack.pop_op2_first_cont() {
            self.call_stack
                .truncate(op2_fst_cont.app_info.call_stack_size as usize);

            self.stack.push_op2_second_cont(Op2SecondContItem {
                op: op2_fst_cont.op,
                app_info: op2_fst_cont.app_info,
                arg1_evaled: closure,
                orig_pos_arg1: op2_fst_cont.orig_pos_arg1,
                orig_pos_arg2: op2_fst_cont.arg2.value.pos_idx(),
            });

            Ok(op2_fst_cont.arg2)
        } else if let Some(op2_snd_cont) = self.stack.pop_op2_second_cont() {
            self.call_stack
                .truncate(op2_snd_cont.app_info.call_stack_size as usize);

            self.eval_op2(Op2EvalData {
                op: op2_snd_cont.op,
                arg1: op2_snd_cont.arg1_evaled,
                arg2: closure,
                orig_pos_arg1: op2_snd_cont.orig_pos_arg1,
                orig_pos_arg2: op2_snd_cont.orig_pos_arg2,
                pos_op: op2_snd_cont.app_info.pos_idx,
            })
        } else if let Some(mut opn_cont) = self.stack.pop_opn_cont() {
            self.call_stack
                .truncate(opn_cont.app_info.call_stack_size as usize);

            opn_cont.evaluated.push((closure, opn_cont.current_pos_idx));

            if let Some(next) = opn_cont.pending.pop() {
                opn_cont.current_pos_idx = next.value.pos_idx();
                self.stack.push_opn_cont(opn_cont);

                Ok(next)
            } else {
                self.eval_opn(OpNEvalData {
                    op: opn_cont.op,
                    args: opn_cont.evaluated,
                    pos_op: opn_cont.app_info.pos_idx,
                })
            }
        } else {
            panic!("unexpected state of eval stack in continue_op()");
        }
    }

    /// Evaluate a unary operation.
    ///
    /// The argument is expected to be evaluated (in WHNF). `pos_op` corresponds to the whole
    /// operation position, that may be needed for error reporting.
    fn eval_op1(&mut self, eval_data: Op1EvalData) -> Result<Closure, ErrorKind> {
        let Op1EvalData {
            orig_pos_arg,
            arg: Closure { value, env },
            pos_op,
            op,
        } = eval_data;

        increment!(format!("primop:{op}"));

        let pos = value.pos_idx();
        let pos_op_inh = eval_data.pos_op.to_inherited();

        macro_rules! mk_type_error {
            (op_name=$op_name:expr, $expected:expr) => {
                mk_type_error!(op_name = $op_name, $expected, value = value)
            };
            (op_name=$op_name:expr, $expected:expr, value=$value:expr) => {
                Err(Box::new(EvalErrorKind::UnaryPrimopTypeError {
                    primop: String::from($op_name),
                    expected: String::from($expected),
                    pos_arg: orig_pos_arg,
                    arg_evaluated: $value,
                }))
            };
            ($expected:expr) => {
                mk_type_error!(op_name = op.to_string(), $expected)
            };
            ($expected:expr, value=$value:expr) => {
                mk_type_error!(op_name = op.to_string(), $expected, value = $value)
            };
            ($expected:expr, value=$value:expr) => {};
            ($expected:expr, $arg_number:expr) => {
                mk_type_error!($expected, $arg_number, value = value)
            };
            ($expected:expr, $arg_number:expr, value=$value:expr) => {
                Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                    primop: op.to_string(),
                    expected: String::from($expected),
                    arg_number: $arg_number,
                    pos_arg: orig_pos_arg,
                    arg_evaluated: $value,
                    pos_op,
                }))
            };
        }

        match op {
            UnaryOp::IfThenElse => {
                if let Some(b) = value.as_bool() {
                    let (fst, ..) = self
                        .stack
                        .pop_arg(&self.context.cache)
                        .expect("if-then-else primop isn't saturated");
                    let (snd, ..) = self
                        .stack
                        .pop_arg(&self.context.cache)
                        .expect("if-then-else primop isn't saturated");

                    Ok(if b { fst } else { snd })
                } else {
                    // Not using mk_type_error! because of a non-uniform message
                    Err(Box::new(EvalErrorKind::TypeError {
                        expected: String::from("Bool"),
                        message: String::from(
                            "the condition in an if expression must have type Bool",
                        ),
                        orig_pos: orig_pos_arg,
                        term: value,
                    }))
                }
            }
            UnaryOp::Typeof => Ok(NickelValue::enum_tag(type_tag(&value), pos_op_inh).into()),
            UnaryOp::Cast => {
                Ok(NickelValue::enum_variant(type_tag(&value), Some(value), pos_op_inh).into())
            }
            UnaryOp::BoolAnd =>
            // The syntax should not allow partially applied boolean operators.
            {
                if let Some((next, ..)) = self.stack.pop_arg(&self.context.cache) {
                    match value.as_bool() {
                        Some(true) => Ok(next),
                        // FIXME: this does not check that the second argument is actually a
                        // boolean. This means `true && 2` silently evaluates to `2`. This is
                        // simpler and more efficient, but can make debugging harder. In any case,
                        // it should be solved only once primary operators have better support for
                        // laziness in some arguments.
                        Some(false) => Ok(value.with_pos_idx(pos_op_inh).into()),
                        _ => mk_type_error!("Bool", 1),
                    }
                } else {
                    Err(Box::new(EvalErrorKind::NotEnoughArgs(
                        2,
                        String::from("&&"),
                        pos_op,
                    )))
                }
            }
            UnaryOp::BoolOr => {
                if let Some((next, ..)) = self.stack.pop_arg(&self.context.cache) {
                    match value.as_bool() {
                        Some(true) => Ok(value.with_pos_idx(pos_op_inh).into()),
                        // FIXME: this does not check that the second argument is actually a
                        // boolean. This means `false || 2` silently evaluates to `2`. This is
                        // simpler and more efficient, but can make debugging harder. In any case,
                        // it should be solved only once primary operators have better support for
                        // laziness in some arguments.
                        Some(false) => Ok(next),
                        _ => mk_type_error!("Bool", 1),
                    }
                } else {
                    Err(Box::new(EvalErrorKind::NotEnoughArgs(
                        2,
                        String::from("||"),
                        pos_op,
                    )))
                }
            }
            UnaryOp::BoolNot => {
                if let Some(b) = value.as_bool() {
                    Ok(NickelValue::bool_value_posless(!b)
                        .with_pos_idx(pos_op_inh)
                        .into())
                } else {
                    mk_type_error!("Bool")
                }
            }
            UnaryOp::Blame => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                Err(Box::new(EvalErrorKind::BlameError {
                    evaluated_arg: label.get_evaluated_arg(&self.context.cache),
                    label: label.clone(),
                }))
            }
            UnaryOp::EnumEmbed(_id) => {
                if value.as_enum_variant().is_some() {
                    Ok(value.with_pos_idx(pos_op_inh).into())
                } else {
                    mk_type_error!("Enum")
                }
            }
            UnaryOp::TagsOnlyMatch { has_default } => {
                let (cases_closure, ..) = self
                    .stack
                    .pop_arg(&self.context.cache)
                    .expect("missing arg for match");

                let default = if has_default {
                    Some(
                        self.stack
                            .pop_arg(&self.context.cache)
                            .map(|(clos, ..)| clos)
                            .expect("missing default case for match"),
                    )
                } else {
                    None
                };

                if let Some(enum_variant) = value.as_enum_variant()
                    && enum_variant.arg.is_none()
                {
                    let Closure {
                        value: cases_val,
                        env: cases_env,
                    } = cases_closure;

                    let ValueContentRef::Record(container) = cases_val.content_ref() else {
                        panic!("invalid argument for %match%")
                    };

                    container
                        .get(enum_variant.tag)
                        .map(|field| Closure {
                            // The record containing the match cases, as well as the match primop
                            // itself, aren't accessible in the surface language. They are
                            // generated by the interpreter, and should never contain field without
                            // definition.
                            value: field
                                .value
                                .as_ref()
                                .cloned()
                                .expect("%match% cases must have a definition"),
                            env: cases_env,
                        })
                        .or(default)
                        .ok_or_else(|| {
                            Box::new(EvalErrorKind::NonExhaustiveEnumMatch {
                                expected: container.field_names(RecordOpKind::IgnoreEmptyOpt),
                                found: NickelValue::enum_variant_posless(enum_variant.tag, None)
                                    .with_pos_idx(pos),
                                pos: pos_op_inh,
                            })
                        })
                } else if let Some(clos) = default {
                    Ok(clos)
                } else {
                    mk_type_error!("Enum", 2)
                }
            }
            UnaryOp::LabelFlipPol => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.polarity = label.polarity.flip();
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            UnaryOp::LabelPol => {
                if let Some(label) = value.as_label() {
                    Ok(NickelValue::from(label.polarity)
                        .with_pos_idx(pos_op_inh)
                        .into())
                } else {
                    mk_type_error!("Label")
                }
            }
            UnaryOp::LabelGoDom => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.path.push(ty_path::Elem::Domain);
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            UnaryOp::LabelGoCodom => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.path.push(ty_path::Elem::Codomain);
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            UnaryOp::LabelGoArray => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.path.push(ty_path::Elem::Array);
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            UnaryOp::LabelGoDict => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.path.push(ty_path::Elem::Dict);
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            UnaryOp::RecordAccess(id) => {
                match value.as_record() {
                    Some(Container::Alloc(record)) => {
                        // We have to apply potentially pending contracts. Right now, this
                        // means that repeated field access will re-apply the contract again
                        // and again, which is not optimal. The same thing happens with array
                        // contracts. There are several way to improve this, but this is left
                        // as future work.
                        match record
                            .get_value_with_ctrs(&id)
                            .map_err(|err| err.into_eval_err(pos, pos_op))?
                        {
                            Some(value) => {
                                self.call_stack
                                    .enter_field(id, pos, value.pos_idx(), pos_op);
                                Ok(Closure { value, env })
                            }
                            None => match record.sealed_tail.as_ref() {
                                Some(t) if t.has_field(&id.ident()) => {
                                    Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                                        action: IllegalPolymorphicTailAction::FieldAccess {
                                            field: id.to_string(),
                                        },
                                        evaluated_arg: t
                                            .label
                                            .get_evaluated_arg(&self.context.cache),
                                        label: t.label.clone(),
                                    }))
                                }
                                _ => Err(Box::new(EvalErrorKind::FieldMissing {
                                    id,
                                    field_names: record.field_names(RecordOpKind::IgnoreEmptyOpt),
                                    operator: String::from("(.)"),
                                    pos_record: pos,
                                    pos_op,
                                })),
                            }, //TODO include the position of operators on the stack
                        }
                    }
                    Some(Container::Empty) => Err(Box::new(EvalErrorKind::FieldMissing {
                        id,
                        field_names: Vec::new(),
                        operator: String::from("(.)"),
                        pos_record: pos,
                        pos_op,
                    })),
                    None =>
                    // Not using mk_type_error! because of a non-uniform message
                    {
                        Err(Box::new(EvalErrorKind::TypeError {
                            expected: String::from("Record"),
                            message: String::from("field access only makes sense for records"),
                            orig_pos: orig_pos_arg,
                            term: value,
                        }))
                    }
                }
            }
            UnaryOp::RecordFields(op_kind) => {
                if let Some(container) = value.as_record() {
                    let fields_as_terms: Array = container
                        .field_names(op_kind)
                        .into_iter()
                        .map(|id| {
                            NickelValue::string(id.label(), self.context.pos_table.push(id.pos))
                        })
                        .collect();

                    Ok(Closure {
                        value: NickelValue::array(fields_as_terms, Vec::new(), pos_op_inh),
                        env,
                    })
                } else {
                    mk_type_error!("Record")
                }
            }
            UnaryOp::RecordValues => {
                if let Some(container) = value.as_record() {
                    let mut values = container
                        .into_opt()
                        .map(|r| r.iter_without_opts())
                        .into_iter()
                        .flatten()
                        .collect::<Result<Vec<_>, _>>()
                        .map_err(|miss_def_err| miss_def_err.into_eval_err(pos, pos_op))?;

                    values.sort_by_key(|(id, _)| *id);
                    let terms = values.into_iter().map(|(_, value)| value).collect();

                    Ok(Closure {
                        // as evaluated records are assumed to be closurized, we can assume that
                        // the extracted array here is, in turn, also closuried.
                        value: NickelValue::array(terms, Vec::new(), pos_op_inh),
                        env,
                    })
                } else {
                    mk_type_error!("Record")
                }
            }
            UnaryOp::ArrayMap => {
                let (f, _) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(
                        2,
                        String::from("array/map"),
                        pos_op,
                    ))
                })?;

                let Some(cont) = value.as_array() else {
                    return mk_type_error!("Array");
                };

                let Container::Alloc(array_data) = cont else {
                    return Ok(value.into());
                };

                let f_as_var = f.value.closurize(&mut self.context.cache, f.env);

                // Array elements are closurized to preserve laziness of data
                // structures. It maintains the invariant that any data structure only
                // contain indices (that is, currently, variables).
                let ts = array_data
                    .iter_with_pending_contracts(pos)
                    .map(|t| {
                        NickelValue::term(Term::app(f_as_var.clone(), t), pos_op_inh)
                            .closurize(&mut self.context.cache, env.clone())
                    })
                    .collect();

                Ok(NickelValue::array(ts, Vec::new(), pos_op_inh).into())
            }
            UnaryOp::ArrayGen => {
                let (f, _) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(
                        2,
                        String::from("array/generate"),
                        pos_op,
                    ))
                })?;

                let Some(n) = value.as_number() else {
                    return mk_type_error!("Number");
                };

                if n < &Number::ZERO {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "array/generate expects its first argument to be a positive number, got {n}"
                        ),
                        pos_op,
                    )));
                }

                let Ok(n_int) = u32::try_from(n) else {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "array/generate expects its first argument to be an integer \
                            smaller than {}, got {n}",
                            u32::MAX,
                        ),
                        pos_op,
                    )));
                };

                let f_closure = f.value.closurize(&mut self.context.cache, f.env);

                // Array elements are closurized to preserve laziness of data structures. It
                // maintains the invariant that any data structure only contain indices (that is,
                // currently, variables).
                let ts = (0..n_int)
                    .map(|n| {
                        mk_app!(f_closure.clone(), NickelValue::number_posless(n))
                            .closurize(&mut self.context.cache, env.clone())
                    })
                    .collect();

                Ok(NickelValue::array(ts, Vec::new(), pos_op_inh).into())
            }
            UnaryOp::RecordMap => {
                let (f, ..) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    EvalErrorKind::NotEnoughArgs(2, String::from("record/map"), pos_op)
                })?;

                let Some(container) = value.as_record() else {
                    return mk_type_error!("Record");
                };

                if let Container::Alloc(record) = container {
                    let record = record.clone();
                    // While it's certainly possible to allow mapping over
                    // a record with a sealed tail, it's not entirely obvious
                    // how that should behave. It's also not clear that this
                    // is something users will actually need to do, so we've
                    // decided to prevent this until we have a clearer idea
                    // of potential use-cases.
                    if let Some(tail) = record.sealed_tail {
                        let label = Rc::unwrap_or_clone(tail).label;

                        return Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                            action: IllegalPolymorphicTailAction::Map,
                            evaluated_arg: label.get_evaluated_arg(&self.context.cache),
                            label,
                        }));
                    }

                    let f_closure = f.value.closurize(&mut self.context.cache, f.env);

                    // As for `ArrayMap` (see above), we closurize the content of fields

                    let fields = record
                        .fields
                        .into_iter()
                        .filter(|(_, field)| !field.is_empty_optional())
                        .map_values_closurize(&mut self.context.cache, &env, |id, t| {
                            let pos_idx = t.pos_idx().to_inherited();

                            mk_app!(
                                f_closure.clone(),
                                NickelValue::string_posless(id.label()),
                                t
                            )
                            .with_pos_idx(pos_idx)
                        })
                        .map_err(|miss_field_err| miss_field_err.into_eval_err(pos, pos_op))?;

                    // By construction, mapping freezes the record. We set the frozen flag so
                    // that operations that require the record to be frozen don't have to
                    // perform the work again.
                    let attrs = record.attrs.frozen();

                    Ok(NickelValue::record(
                        RecordData {
                            fields,
                            attrs,
                            ..record
                        },
                        pos_op_inh,
                    )
                    .into())
                } else {
                    Ok(value.with_pos_idx(pos_op).into())
                }
            }
            UnaryOp::Seq => self
                .stack
                .pop_arg(&self.context.cache)
                .map(|(next, ..)| next)
                .ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(2, String::from("seq"), pos_op))
                }),
            UnaryOp::DeepSeq => {
                // Build a `NickelValue` that forces a given list of terms, and at the end resumes the
                // evaluation of the argument on the top of the stack.
                //
                // Requires its first argument to be non-empty.
                fn seq_terms<I>(mut it: I, pos_op_inh: PosIdx) -> NickelValue
                where
                    I: Iterator<Item = NickelValue>,
                {
                    let first = it
                        .next()
                        .expect("expected the argument to be a non-empty iterator");

                    it.fold(
                        mk_term::op1(UnaryOp::DeepSeq, first).with_pos_idx(pos_op_inh),
                        |acc, t| {
                            mk_app!(mk_term::op1(UnaryOp::DeepSeq, t), acc).with_pos_idx(pos_op_inh)
                        },
                    )
                }

                match value.content_ref() {
                    ValueContentRef::Record(Container::Alloc(record))
                        if !record.fields.is_empty() =>
                    {
                        let defined = record
                            // `iter_without_opts` takes care of applying pending contracts
                            .iter_without_opts()
                            .collect::<Result<Vec<_>, _>>()
                            .map_err(|missing_def_err| {
                                missing_def_err.into_eval_err(pos, pos_op)
                            })?;

                        let terms = defined.into_iter().map(|(_, field)| field);

                        Ok(Closure {
                            value: seq_terms(terms, pos_op),
                            env,
                        })
                    }
                    ValueContentRef::Array(Container::Alloc(array_data))
                        if !array_data.array.is_empty() =>
                    {
                        let terms = seq_terms(
                            array_data
                                .iter_with_pending_contracts(pos.to_inherited())
                                .map(|t| t.closurize(&mut self.context.cache, env.clone())),
                            pos_op,
                        );

                        Ok(terms.into())
                    }
                    ValueContentRef::EnumVariant(EnumVariantData {
                        tag: _,
                        arg: Some(arg),
                    }) => Ok(Closure {
                        value: seq_terms(std::iter::once(arg.clone()), pos_op),
                        env,
                    }),
                    _ => {
                        if let Some((next, ..)) = self.stack.pop_arg(&self.context.cache) {
                            Ok(next)
                        } else {
                            Err(Box::new(EvalErrorKind::NotEnoughArgs(
                                2,
                                String::from("deep_seq"),
                                pos_op,
                            )))
                        }
                    }
                }
            }
            UnaryOp::ArrayLength => {
                //TODO[RFC007]: empty array
                if let Some(container) = value.as_array() {
                    // A num does not have any free variable so we can drop the environment
                    Ok(NickelValue::number(container.len(), pos_op_inh).into())
                } else {
                    mk_type_error!("Array")
                }
            }
            UnaryOp::ChunksConcat => {
                let mut str_acc = self.stack.pop_str_acc().expect("invalid stack state: missing string accumulator on the top while evaluating string chunks");

                if let Some(s) = value.to_nickel_string() {
                    if str_acc.curr_indent != 0 {
                        let indent_str: String = std::iter::once('\n')
                            .chain((0..str_acc.curr_indent).map(|_| ' '))
                            .collect();
                        str_acc.acc.push_str(&s.as_str().replace('\n', &indent_str))
                    } else {
                        str_acc.acc.push_str(s.as_str())
                    }

                    let mut next_chunk = self.stack.pop_str_chunk();
                    // Pop consecutive string literals to find the next expression to evaluate
                    while let Some(StrChunk::Literal(s)) = next_chunk {
                        str_acc.acc.push_str(&s);
                        next_chunk = self.stack.pop_str_chunk();
                    }

                    if let Some(StrChunk::Expr(e, indent)) = next_chunk {
                        self.stack.push_str_acc(StrAccItem {
                            acc: str_acc.acc,
                            // unwrap(): we don't expect an indentation level bigger than `u32::MAX`
                            curr_indent: indent.try_into().unwrap(),
                            env: str_acc.env.clone(),
                            curr_pos: e.pos_idx(),
                        });

                        str_acc.curr_indent = indent.try_into().unwrap();
                        str_acc.curr_pos = e.pos_idx();

                        // TODO: we should set up the stack properly, and directly, for the
                        // continuation instead of allocating a new term here and returning it.
                        Ok(Closure {
                            value: NickelValue::term(
                                Term::op1(UnaryOp::ChunksConcat, e),
                                pos_op_inh,
                            ),
                            env: str_acc.env.clone(),
                        })
                    } else {
                        Ok(
                            NickelValue::string(std::mem::take(&mut str_acc.acc), pos_op_inh)
                                .into(),
                        )
                    }
                } else {
                    // Since the error halts the evaluation, we don't bother cleaning the stack of
                    // the remaining string chunks.
                    //
                    // Not using mk_type_error! because of a non-uniform message
                    Err(Box::new(EvalErrorKind::TypeError {
                        expected: String::from("Stringable"),
                        message: String::from(
                            "interpolated values must be Stringable (string, number, boolean, enum tag or null)",
                        ),
                        orig_pos: str_acc.curr_pos,
                        term: value,
                    }))
                }
            }
            UnaryOp::StringTrim => {
                if let Some(s) = value.as_string() {
                    Ok(NickelValue::string(s.trim(), pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::StringChars => {
                if let Some(s) = value.as_string() {
                    let ts = s.characters();
                    Ok(NickelValue::array(ts, Vec::new(), pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::StringUppercase => {
                if let Some(s) = value.as_string() {
                    Ok(NickelValue::string(s.to_uppercase(), pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::StringLowercase => {
                if let Some(s) = value.as_string() {
                    Ok(NickelValue::string(s.to_lowercase(), pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::StringLength => {
                if let Some(s) = value.as_string() {
                    let length = s.graphemes(true).count();
                    Ok(NickelValue::number(length, pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::ToString => value
                .to_nickel_string()
                .map(|s| NickelValue::string(s, pos_op_inh).into())
                .ok_or_else(|| {
                    Box::new(EvalErrorKind::Other(
                        format!(
                            "to_string: can't convert an argument of type {} to string",
                            value.type_of().unwrap()
                        ),
                        pos,
                    ))
                }),
            UnaryOp::NumberFromString => {
                if let Some(s) = value.as_string() {
                    let n = parse_number_sci(s).map_err(|_| {
                        Box::new(EvalErrorKind::Other(
                            format!(
                                "number/from_string: invalid number literal `{}`",
                                s.as_str()
                            ),
                            pos,
                        ))
                    })?;

                    Ok(NickelValue::number(n, pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::EnumFromString => {
                if let Some(s) = value.as_string() {
                    Ok(NickelValue::enum_tag(LocIdent::from(s), pos_op_inh).into())
                } else {
                    mk_type_error!("String")
                }
            }
            UnaryOp::StringIsMatch => {
                if let Some(s) = value.as_string() {
                    let re = regex::Regex::new(s)
                        .map_err(|err| Box::new(EvalErrorKind::Other(err.to_string(), pos_op)))?;

                    let matcher = eta_expand(UnaryOp::StringIsMatchCompiled(re.into()), pos_op_inh);
                    Ok(NickelValue::term(matcher, pos_op_inh).into())
                } else {
                    mk_type_error!("String", 1)
                }
            }
            UnaryOp::StringFind => {
                if let Some(s) = value.as_string() {
                    let re = regex::Regex::new(s)
                        .map_err(|err| Box::new(EvalErrorKind::Other(err.to_string(), pos_op)))?;

                    let matcher = eta_expand(UnaryOp::StringFindCompiled(re.into()), pos_op_inh);
                    Ok(NickelValue::term(matcher, pos_op_inh).into())
                } else {
                    mk_type_error!("String", 1)
                }
            }
            UnaryOp::StringFindAll => {
                if let Some(s) = value.as_string() {
                    let re = regex::Regex::new(s)
                        .map_err(|err| Box::new(EvalErrorKind::Other(err.to_string(), pos_op)))?;

                    let matcher = eta_expand(UnaryOp::StringFindAllCompiled(re.into()), pos_op_inh);
                    Ok(NickelValue::term(matcher, pos_op_inh).into())
                } else {
                    mk_type_error!("String", 1)
                }
            }
            UnaryOp::StringIsMatchCompiled(regex) => {
                if let Some(s) = value.as_string() {
                    Ok(s.matches_regex(&regex).with_pos_idx(pos_op_inh).into())
                } else {
                    mk_type_error!(op_name = "a compiled regular expression match", "String")
                }
            }
            UnaryOp::StringFindCompiled(regex) => {
                if let Some(s) = value.as_string() {
                    use crate::term::string::RegexFindResult;

                    let result = match s.find_regex(&regex) {
                        // This record doesn't need to be closurized, since all values are
                        // constant.
                        None => mk_record!(
                            ("matched", NickelValue::string_posless("")),
                            ("index", NickelValue::number_posless(-1)),
                            ("groups", NickelValue::empty_array())
                        ),
                        Some(RegexFindResult {
                            matched: mtch,
                            index,
                            groups,
                        }) => closurize_container(mk_record!(
                            ("matched", NickelValue::string_posless(mtch)),
                            ("index", NickelValue::number_posless(index)),
                            (
                                "groups",
                                NickelValue::array_posless(
                                    Array::from_iter(
                                        groups
                                            .into_iter()
                                            // Unmatched groups get turned into empty strings. It
                                            // might be nicer to have a 'Some s / 'None instead,
                                            // but that would be an API break.
                                            .map(|s| NickelValue::string_posless(
                                                s.unwrap_or_default()
                                            ))
                                    ),
                                    Vec::new()
                                )
                            )
                        )),
                    };

                    Ok(result.with_pos_idx(pos_op_inh).into())
                } else {
                    mk_type_error!(op_name = "a compiled regular expression match", "String")
                }
            }
            UnaryOp::StringFindAllCompiled(regex) => {
                if let Some(s) = value.as_string() {
                    let result = NickelValue::array(
                        Array::from_iter(s.find_all_regex(&regex).map(|found| {
                            closurize_container(mk_record!(
                                ("matched", NickelValue::string_posless(found.matched)),
                                ("index", NickelValue::number_posless(found.index)),
                                (
                                    "groups",
                                    NickelValue::array_posless(
                                        Array::from_iter(
                                            found
                                                .groups
                                                .into_iter()
                                                // Unmatched groups get turned into empty strings. It
                                                // might be nicer to have a 'Some s / 'None instead,
                                                // but that would be an API break.
                                                .map(|s| NickelValue::string_posless(
                                                    s.unwrap_or_default()
                                                ))
                                        ),
                                        Vec::new(),
                                    )
                                )
                            ))
                        })),
                        Vec::new(),
                        pos_op_inh,
                    );

                    Ok(result.into())
                } else {
                    mk_type_error!(op_name = "a compiled regular expression match", "String")
                }
            }
            UnaryOp::Force {
                ignore_not_exported,
            } => {
                /// `Seq` the `terms` iterator and then resume evaluating the `cont` continuation.
                fn seq_terms<I>(terms: I, pos: PosIdx, cont: NickelValue) -> NickelValue
                where
                    I: Iterator<Item = NickelValue>,
                {
                    terms
                        .fold(cont, |acc, t| mk_app!(mk_term::op1(UnaryOp::Seq, t), acc))
                        .with_pos_idx(pos)
                }

                match value.content_ref() {
                    ValueContentRef::Record(Container::Alloc(record)) => {
                        let fields = record
                            .fields
                            .iter()
                            .filter(|(_, field)| {
                                !(field.is_empty_optional()
                                    || (ignore_not_exported && field.metadata.not_exported()))
                            })
                            .map(|(id, field)| (*id, field.clone()))
                            .map_values_closurize(&mut self.context.cache, &env, |_, value| {
                                mk_term::op1(
                                    UnaryOp::Force {
                                        ignore_not_exported,
                                    },
                                    value,
                                )
                            })
                            .map_err(|e| e.into_eval_err(pos, pos_op))?;

                        let terms: Vec<NickelValue> = fields
                            .values()
                            .map(|field| {
                                field.value.as_ref().cloned().expect(
                                    "map_values_closurize ensures that values without a \
                                    definition throw a MissingFieldDefError",
                                )
                            })
                            .collect();

                        let pos_inh = pos.to_inherited();
                        let cont = NickelValue::record(
                            RecordData {
                                fields,
                                attrs: record.attrs,
                                sealed_tail: record.sealed_tail.clone(),
                            },
                            pos_inh,
                        );

                        Ok(seq_terms(terms.into_iter(), pos_op, cont).into())
                    }
                    ValueContentRef::Array(Container::Alloc(array_data)) => {
                        let pos_inh = pos.to_inherited();
                        let ts = array_data
                            .iter_with_pending_contracts(pos_inh)
                            .map(|t| {
                                mk_term::op1(
                                    UnaryOp::Force {
                                        ignore_not_exported,
                                    },
                                    t,
                                )
                                .closurize(&mut self.context.cache, env.clone())
                            })
                            // It's important to collect here, otherwise the two usages below
                            // will each do their own .closurize(...) calls and end up with
                            // different closures, which means that `cont` won't be properly
                            // updated.
                            .collect::<Array>();

                        let terms = ts.clone().into_iter();
                        let cont = NickelValue::array(ts, Vec::new(), pos_inh);

                        Ok(seq_terms(terms, pos_op, cont).into())
                    }
                    ValueContentRef::EnumVariant(data) => {
                        let EnumVariantData { tag, arg } = data.clone();

                        if let Some(arg) = arg {
                            let arg = mk_term::op1(
                                UnaryOp::Force {
                                    ignore_not_exported,
                                },
                                arg,
                            )
                            .closurize(&mut self.context.cache, env.clone());

                            let cont = NickelValue::enum_variant(
                                tag,
                                Some(arg.clone()),
                                pos.to_inherited(),
                            );

                            Ok(Closure {
                                value: seq_terms(std::iter::once(arg), pos_op, cont),
                                env,
                            })
                        } else {
                            Ok(Closure { value, env })
                        }
                    }
                    _ => Ok(Closure { value, env }),
                }
            }
            UnaryOp::RecordEmptyWithTail => {
                let Some(container) = value.as_record() else {
                    return mk_type_error!("Record");
                };

                let mut result = RecordData::empty();
                result.sealed_tail = container
                    .into_opt()
                    .and_then(|record| record.sealed_tail.clone());

                Ok(Closure {
                    value: NickelValue::record(result, pos_op_inh),
                    env,
                })
            }
            UnaryOp::RecordFreeze => {
                // If the record is already frozen, there's nothing to do.
                if matches!(value.as_record(), Some(Container::Alloc(record)) if record.attrs.frozen)
                {
                    // A frozen record shouldn't have a polymorphic tail
                    debug_assert!(
                        // unwrap()s: the pattern in `matches` ensures that both unwrap will
                        // succeed.
                        value
                            .as_record()
                            .unwrap()
                            .unwrap_alloc()
                            .sealed_tail
                            .is_none()
                    );

                    return Ok(Closure { value, env });
                }

                let Some(container) = value.as_record() else {
                    return mk_type_error!("Record");
                };

                if let Container::Alloc(record) = container {
                    // It's not clear what the semantics of freezing a record with a sealed tail
                    // would be, as there might be dependencies between the sealed part and the
                    // unsealed part. Merging is disallowed on records with tail, so we disallow
                    // freezing as well.
                    if let Some(tail) = &record.sealed_tail {
                        return Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                            action: IllegalPolymorphicTailAction::Freeze,
                            evaluated_arg: tail.label.get_evaluated_arg(&self.context.cache),
                            label: tail.label.clone(),
                        }));
                    }

                    let fields = record
                        .fields
                        .iter()
                        .map(|(id, field)| {
                            let value = field.value_with_pending_contracts();

                            let field = Field {
                                value,
                                pending_contracts: Vec::new(),
                                metadata: field.metadata.clone(),
                            }
                            .closurize(&mut self.context.cache, env.clone());

                            (*id, field)
                        })
                        .collect();

                    let attrs = record.attrs.frozen();

                    Ok(Closure {
                        value: NickelValue::record(
                            RecordData {
                                fields,
                                attrs,
                                sealed_tail: None,
                            },
                            pos_op_inh,
                        ),
                        env,
                    })
                } else {
                    // Ditto if the record is empty. We can also drop the environment.
                    Ok(value.into())
                }
            }
            UnaryOp::Trace => {
                if let Some(s) = value.as_string() {
                    let _ = writeln!(self.context.trace, "std.trace: {s}");
                    Ok(())
                } else {
                    mk_type_error!("String")
                }?;

                self.stack
                    .pop_arg(&self.context.cache)
                    .map(|(next, ..)| next)
                    .ok_or_else(|| {
                        Box::new(EvalErrorKind::NotEnoughArgs(
                            2,
                            String::from("trace"),
                            pos_op,
                        ))
                    })
            }
            UnaryOp::LabelPushDiag => {
                let Some(label) = value.as_label() else {
                    return mk_type_error!("Label");
                };

                let mut label = label.clone();
                label.push_diagnostic();
                Ok(Closure {
                    value: NickelValue::label(label, pos),
                    env,
                })
            }
            #[cfg(feature = "nix-experimental")]
            UnaryOp::EvalNix => {
                if let Some(s) = value.as_string() {
                    let base_dir = self
                        .context
                        .pos_table
                        .get(pos_op)
                        .into_opt()
                        .map(|span| self.import_resolver().get_base_dir_for_nix(span.src_id))
                        .unwrap_or_default();

                    let json = nix_ffi::eval_to_json(&String::from(s), &base_dir).map_err(|e| {
                        Box::new(EvalErrorKind::Other(
                            format!("nix code failed to evaluate:\n {}", e.what()),
                            pos,
                        ))
                    })?;

                    let result: NickelValue = serde_json::from_str(&json).map_err(|e| {
                        Box::new(EvalErrorKind::Other(
                            format!("nix produced invalid json: {e}"),
                            pos,
                        ))
                    })?;

                    Ok(result.into())
                } else {
                    // Not using mk_type_error! because of a non-uniform message
                    Err(Box::new(EvalErrorKind::TypeError {
                        expected: String::from("String"),
                        message: String::from("eval_nix takes a string of nix code as an argument"),
                        orig_pos: orig_pos_arg,
                        term: value,
                    }))
                }
            }
            UnaryOp::EnumGetArg => {
                if let Some(EnumVariantData { arg: Some(arg), .. }) = value.as_enum_variant() {
                    Ok(Closure {
                        value: arg.clone(),
                        env,
                    })
                } else {
                    mk_type_error!("Enum variant")
                }
            }
            UnaryOp::EnumMakeVariant => {
                let Some(tag) = value.as_string() else {
                    return mk_type_error!("String");
                };

                let (arg_clos, _) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(
                        2,
                        String::from("enum/make_variant"),
                        pos,
                    ))
                })?;
                let arg_pos = arg_clos.value.pos_idx();

                Ok(NickelValue::enum_variant(
                    LocIdent::new(tag).with_pos(self.context.pos_table.get(pos)),
                    Some(Thunk::new(arg_clos, arg_pos).into()),
                    pos_op_inh,
                )
                .into())
            }
            UnaryOp::EnumGetTag => match value.as_enum_variant() {
                Some(EnumVariantData { tag, .. }) => {
                    Ok(NickelValue::enum_tag(*tag, pos_op_inh).into())
                }
                _ => mk_type_error!("Enum"),
            },
            UnaryOp::EnumIsVariant => Ok(NickelValue::bool_value(
                value
                    .as_enum_variant()
                    .is_some_and(|enum_variant| enum_variant.arg.is_some()),
                pos_op_inh,
            )
            .into()),
            UnaryOp::ContractCustom => {
                let contract = if matches!(value.as_term(), Some(Term::Fun(..))) {
                    value.closurize(&mut self.context.cache, env)
                } else {
                    return mk_type_error!("Function or MatchExpression");
                };

                Ok(NickelValue::custom_contract(contract, pos_op_inh).into())
            }
            UnaryOp::ContractPostprocessResult => {
                let Some(EnumVariantData {
                    tag,
                    arg: Some(arg),
                }) = value.as_enum_variant()
                else {
                    return mk_type_error!("[| 'Ok, 'Error _ |]");
                };

                // We pop the second argument which isn't strict: we don't need to evaluate the
                // label if there's no error.
                let (label_closure, pos_label) = self.stack.pop_arg(&self.context.cache).unwrap();

                match (tag.label(), arg) {
                    ("Ok", value) => Ok(Closure {
                        value: value.clone(),
                        env,
                    }),
                    ("Error", err_data) => {
                        let app_info = PrimopAppInfo {
                            call_stack_size: self.call_stack.len(),
                            pos_idx: pos_op_inh,
                        };
                        // In the error case, we first need to force the error data so that
                        // primitive values (strings) can be extracted from it, attach the
                        // corresponding data to the label, and then blame.
                        //
                        // To do so, we setup the stack to represent the evaluation context
                        // `%contract/blame% (%label/with_error_data% (%force% [.]) label)` and
                        // then continue with `err_data`.
                        self.stack.push_op1_cont(Op1ContItem {
                            op: UnaryOp::Blame,
                            app_info,
                            orig_pos_arg,
                        });
                        self.stack.push_op2_first_cont(Op2FirstContItem {
                            op: BinaryOp::LabelWithErrorData,
                            app_info,
                            arg2: label_closure,
                            orig_pos_arg1: pos_label,
                        });
                        self.stack.push_op1_cont(Op1ContItem {
                            op: UnaryOp::Force {
                                ignore_not_exported: false,
                            },
                            app_info,
                            orig_pos_arg,
                        });

                        Ok(Closure {
                            value: err_data.clone(),
                            env,
                        })
                    }
                    _ => mk_type_error!("[| 'Ok, 'Error {..} |]'"),
                }
            }
            UnaryOp::ContractAttachDefaultLabel => {
                if !matches!(
                    value.as_enum_variant(),
                    Some(EnumVariantData { arg: Some(_), .. })
                ) {
                    return mk_type_error!("[| 'Ok, 'Error _ |]");
                }
                // The stack should already contain the default label to attach, so push
                // the (potential) error data.
                self.stack.push_arg(Closure { value, env }, orig_pos_arg);

                Ok(Closure {
                    value: internals::add_default_check_label(),
                    env: Environment::new(),
                })
            }
            UnaryOp::NumberArcCos => self.number_op1(
                f64::acos,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::NumberArcSin => self.number_op1(
                f64::asin,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::NumberArcTan => self.number_op1(
                f64::atan,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::NumberCos => self.number_op1(
                f64::cos,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::NumberSin => self.number_op1(
                f64::sin,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::NumberTan => self.number_op1(
                f64::tan,
                Op1EvalData {
                    op,
                    arg: Closure { value, env },
                    orig_pos_arg,
                    pos_op,
                },
            ),
            UnaryOp::RecDefault => unimplemented!(),
            UnaryOp::RecForce => unimplemented!(),
        }
    }

    fn number_op1<F>(&mut self, f: F, eval_data: Op1EvalData) -> Result<Closure, ErrorKind>
    where
        F: Fn(f64) -> f64,
    {
        let Op1EvalData {
            op,
            arg: Closure { value, env: _ },
            orig_pos_arg,
            pos_op,
        } = eval_data;

        if let Some(n) = value.as_number() {
            let result_as_f64 = f(f64::rounding_from(n, RoundingMode::Nearest).0);
            let result = Number::try_from_float_simplest(result_as_f64).map_err(|_| {
                Box::new(EvalErrorKind::Other(
                    format!(
                        "invalid arithmetic operation: \
                        {op}({n}) returned {result_as_f64}, \
                        but {result_as_f64} isn't representable in Nickel",
                    ),
                    pos_op,
                ))
            })?;

            Ok(NickelValue::number(result, pos_op.to_inherited()).into())
        } else {
            Err(Box::new(EvalErrorKind::UnaryPrimopTypeError {
                primop: op.to_string(),
                expected: String::from("Number"),
                pos_arg: orig_pos_arg,
                arg_evaluated: value,
            }))
        }
    }

    /// Evaluate a binary operation.
    ///
    /// Both arguments are expected to be evaluated (in WHNF).
    fn eval_op2(&mut self, eval_data: Op2EvalData) -> Result<Closure, ErrorKind> {
        let Op2EvalData {
            op,
            arg1: Closure {
                value: value1,
                env: env1,
            },
            arg2:
                Closure {
                    value: mut value2,
                    env: env2,
                },
            orig_pos_arg1,
            orig_pos_arg2,
            pos_op,
        } = eval_data;

        increment!(format!("primop:{op}"));

        let pos1 = value1.pos_idx();
        let pos2 = value2.pos_idx();
        let pos_op_inh = pos_op.to_inherited();

        macro_rules! mk_type_error {
            (op_name=$op_name:expr, $expected:expr, $arg_number:expr, $arg_evaled:expr) => {
                Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                    primop: String::from($op_name),
                    expected: String::from($expected),
                    arg_number: $arg_number,
                    pos_arg: {
                        match $arg_number {
                            1 => orig_pos_arg1,
                            2 => orig_pos_arg2,
                            _ => unimplemented!(),
                        }
                    },
                    arg_evaluated: $arg_evaled,
                    pos_op,
                }))
            };
            ($expected:expr, $arg_number:expr, $arg_evaled:expr) => {
                mk_type_error!(
                    op_name = op.to_string(),
                    $expected,
                    $arg_number,
                    $arg_evaled
                )
            };
        }

        match op {
            BinaryOp::Seal => {
                let Some(key) = value1.as_sealing_key() else {
                    return mk_type_error!("SealingKey", 1, value1);
                };

                let Some(label) = value2.as_label() else {
                    return mk_type_error!("Label", 2, value2);
                };

                Ok(mk_fun!(
                    "x",
                    NickelValue::term(
                        Term::sealed(*key, mk_term::var("x"), label.clone()),
                        pos_op_inh
                    )
                )
                .into())
            }
            BinaryOp::Plus => self.number_op2(
                |n1, n2| n1 + n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::Sub => self.number_op2(
                |n1, n2| n1 - n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::Mult => self.number_op2(
                |n1, n2| n1 * n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::Div => {
                let Some(n1) = value1.as_number() else {
                    return mk_type_error!("Number", 1, value1);
                };

                let Some(n2) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                if n2 == &Number::ZERO {
                    Err(Box::new(EvalErrorKind::Other(
                        String::from("division by zero"),
                        pos_op,
                    )))
                } else {
                    Ok(NickelValue::number(n1 / n2, pos_op_inh).into())
                }
            }
            BinaryOp::Modulo => {
                let Some(n1) = value1.as_number() else {
                    return mk_type_error!("Number", 1, value1);
                };

                let Some(n2) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                if n2 == &Number::ZERO {
                    return Err(Box::new(EvalErrorKind::Other(
                        String::from("division by zero (%)"),
                        pos2,
                    )));
                }

                // This is the equivalent of `truncate()` for `Number`
                let quotient = Number::from(Integer::rounding_from(n1 / n2, RoundingMode::Down).0);

                Ok(NickelValue::number(n1 - quotient * n2, pos_op_inh).into())
            }
            BinaryOp::NumberArcTan2 => {
                let Some(n1) = value1.as_number() else {
                    return mk_type_error!("Number", 1, value1);
                };

                let Some(n2) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                let y = f64::rounding_from(n1, RoundingMode::Nearest).0;
                let x = f64::rounding_from(n2, RoundingMode::Nearest).0;

                let result_as_f64 = y.atan2(x);

                let result = Number::try_from_float_simplest(result_as_f64).map_err(|_| {
                    Box::new(EvalErrorKind::Other(
                        format!(
                            "invalid arithmetic operation: \
                            number/arctan2({n1}, {n2}) returned {result_as_f64}, \
                            but {result_as_f64} isn't representable in Nickel"
                        ),
                        pos_op,
                    ))
                })?;

                Ok(NickelValue::number(result, pos_op_inh).into())
            }
            BinaryOp::NumberLog => {
                let Some(n1) = value1.as_number() else {
                    return mk_type_error!("Number", 1, value1);
                };

                let Some(n2) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                let n = f64::rounding_from(n1, RoundingMode::Nearest).0;

                let result_as_f64 = if n2 == &2 {
                    n.log2()
                } else if n2 == &Number::from(10) {
                    n.log10()
                } else {
                    let base = f64::rounding_from(n2, RoundingMode::Nearest).0;
                    n.log(base)
                };

                let result = Number::try_from_float_simplest(result_as_f64).map_err(|_| {
                    Box::new(EvalErrorKind::Other(
                        format!(
                            "invalid arithmetic operation: \
                            number/log({n1}, {n2}) returned {result_as_f64}, \
                            but {result_as_f64} isn't representable in Nickel"
                        ),
                        pos_op,
                    ))
                })?;

                Ok(NickelValue::number(result, pos_op_inh).into())
            }
            BinaryOp::Pow => {
                let Some(n1) = value1.as_number() else {
                    return mk_type_error!("Number", 1, value1);
                };

                let Some(n2) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                // Malachite's Rationals don't support exponents larger than `u64`. Anyway,
                // the result of such an operation would be huge and impractical to
                // store.
                //
                // We first try to convert the rational to an `i64`, in which case the
                // power is computed in an exact way.
                //
                // If the conversion fails, we fallback to converting both the exponent and
                // the value to the nearest `f64`, perform the exponentiation, and convert
                // the result back to rationals, with a possible loss of precision.
                let result = if let Ok(n2_as_i64) = i64::try_from(n2) {
                    n1.pow(n2_as_i64)
                } else {
                    let result_as_f64 = f64::rounding_from(n1, RoundingMode::Nearest)
                        .0
                        .powf(f64::rounding_from(n2, RoundingMode::Nearest).0);
                    // The following conversion fails if the result is NaN or +/-infinity
                    Number::try_from_float_simplest(result_as_f64).map_err(|_| {
                        Box::new(EvalErrorKind::Other(
                            format!(
                                "invalid arithmetic operation: \
                                        {n1}^{n2} returned {result_as_f64}, \
                                        but {result_as_f64} isn't representable in Nickel"
                            ),
                            pos_op,
                        ))
                    })?
                };

                Ok(NickelValue::number(result, pos_op_inh).into())
            }
            BinaryOp::StringConcat => {
                let Some(s1) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let Some(s2) = value2.as_string() else {
                    return mk_type_error!("String", 2, value2);
                };

                Ok(NickelValue::string(format!("{s1}{s2}"), pos_op_inh).into())
            }
            BinaryOp::ContractApply | BinaryOp::ContractCheck => {
                let app_info = PrimopAppInfo {
                    call_stack_size: self.call_stack.len(),
                    pos_idx: pos_op_inh,
                };

                // Performing only one match `if let Term::Type` and putting the call to
                // `increment!` there looks sensible at first, but it's annoying to explain to
                // rustc and clippy that we match on `typ` but use it only if the `metrics` feature
                // is enabled (we get unused variable warning otherwise). It's simpler to just make
                // a separate `if` conditionally included.
                #[cfg(feature = "metrics")]
                if let Some(TypeData { typ, .. }) = value1.as_type() {
                    increment!(format!(
                        "primop:contract/apply:{}",
                        typ.pretty_print_cap(40)
                    ));
                }

                if let Some(TypeData { typ: _, contract }) = value1.as_type() {
                    // The contract generation from a static type might return any kind of
                    // contract, including e.g. a record or a custom contract. The result needs to
                    // be evaluated first, and then passed to `b_op` again. In that case, we don't
                    // bother tracking the argument and updating the label: this will be done by
                    // the next call to `b_op`.

                    // We set the stack to represent the evaluation context `<b_op> [.] label` and
                    // proceed to evaluate `<typ.contract()>`
                    self.stack.push_op2_first_cont(Op2FirstContItem {
                        op,
                        app_info,
                        arg2: Closure {
                            value: value2,
                            env: env2,
                        },
                        orig_pos_arg1,
                    });

                    return Ok(Closure {
                        value: contract.clone(),
                        env: env1,
                    });
                }

                let Some(label) = value2.as_label() else {
                    return mk_type_error!("Label", 2, value2);
                };

                let mut label = label.clone();

                increment!(format!(
                    "contract:originates_from_type {}",
                    label.typ.pretty_print_cap(40)
                ));

                #[cfg(feature = "metrics")]
                if let Some(field) = label.field_name {
                    increment!(format!("contract:originates_from_field {field}"));
                }

                // Pop the contract argument to track its cache index in the label for better
                // error reporting, and because we might add post-processing steps on the stack
                // which need to sit underneath the value and the label (they will be run after
                // the contract application is evaluated). We'll just push the value and the
                // label back on the stack at the end.
                let (idx, stack_value_pos) = self
                    .stack
                    .pop_arg_as_idx(&mut self.context.cache)
                    .ok_or_else(|| {
                        Box::new(EvalErrorKind::NotEnoughArgs(
                            3,
                            String::from("contract/apply"),
                            pos_op,
                        ))
                    })?;

                // We update the label and convert it back to a term form that can be cheaply cloned
                label.arg_pos = self
                    .context
                    .cache
                    .get_then(idx.clone(), |c| c.value.pos_idx());
                label.arg_idx = Some(idx.clone());
                let new_label = NickelValue::label(label, pos2);

                // If we're evaluating a plain contract application but we are applying
                // something with the signature of a custom contract, we need to setup some
                // post-processing.
                //
                // We prepare the stack so that `contract/postprocess_result` will be applied
                // afterwards. This primop converts the result of a custom contract `'Ok value`
                // or `'Error err_data` to either `value` or a proper contract error with
                // `err_data` included in the label.
                //
                // That is, prepare the stack to represent the evaluation context
                // `%contract/postprocess_result% [.] label`
                if let (
                    ValueContentRef::CustomContract(_) | ValueContentRef::Record(_),
                    BinaryOp::ContractApply,
                ) = (value1.content_ref(), &op)
                {
                    self.stack.push_arg(new_label.clone().into(), pos_op_inh);

                    self.stack.push_op1_cont(Op1ContItem {
                        op: UnaryOp::ContractPostprocessResult,
                        app_info,
                        orig_pos_arg: pos1.to_inherited(),
                    });
                }

                // Contract checks are allowed to specify a blame location, but they don't
                // have to. We insert an op to check if they omitted the blame location and
                // put in a default one if not.
                //
                // Prepare the stack to represent the evaluation context
                // `%contract/attach_default_label% [.] label`
                if let BinaryOp::ContractCheck = &op {
                    self.stack.push_arg(new_label.clone().into(), pos_op_inh);

                    self.stack.push_op1_cont(Op1ContItem {
                        op: UnaryOp::ContractAttachDefaultLabel,
                        app_info,
                        orig_pos_arg: pos1.to_inherited(),
                    });
                }

                // Now that we've updated the label, we push the checked value and the new
                // label back on the stack, so that they become the two arguments of the
                // contract (transformed to something that can be applied directly). That is,
                // we prepare the stack to represent the evaluation context `[.] label value`
                // and proceed with the evaluation of `functoid`.
                self.stack.push_tracked_arg(idx, stack_value_pos);
                self.stack.push_arg(new_label.into(), pos2.to_inherited());

                // We convert the contract (which can be a custom contract, a record, a naked
                // function, etc.) to a form that can be applied to a label and a value.
                let functoid = match value1.content_ref() {
                    ValueContentRef::Term(Term::Fun(..)) => {
                        // Warn on naked function contracts, but not if they came from the
                        // stdlib. Some stdlib functions return naked function contracts.
                        if let Some(pos) = self.context.pos_table.get(pos1).as_opt_ref()
                            && !self.context.import_resolver.files().is_stdlib(pos.src_id)
                        {
                            self.warn(Warning::NakedFunctionContract {
                                func_pos: self.context.pos_table.get(pos1),
                                app_pos: self.context.pos_table.get(pos_op),
                            });
                        }

                        if let BinaryOp::ContractApply = op {
                            Closure {
                                value: value1,
                                env: env1,
                            }
                        } else {
                            // Prepare the stack to represent the evaluation context `[.]
                            // as_naked` and proceed with `$naked_to_custom`
                            self.stack.push_arg(
                                Closure {
                                    value: value1,
                                    env: env1,
                                },
                                orig_pos_arg1,
                            );

                            internals::naked_to_custom().into()
                        }
                    }
                    ValueContentRef::CustomContract(ctr) => Closure {
                        value: ctr.clone(),
                        env: env1,
                    },
                    ValueContentRef::Record(..) => {
                        // Prepare the stack to represent the evaluation context `[.] t1` and
                        // proceed with `$record_contract`
                        self.stack.push_arg(
                            Closure {
                                value: value1,
                                env: env1,
                            },
                            orig_pos_arg1,
                        );

                        internals::record_contract().into()
                    }
                    _ => return mk_type_error!("Contract", 1, value1),
                };

                Ok(functoid)
            }
            BinaryOp::LabelWithErrorData => {
                // We need to extract plain values from a Nickel data structure, which most likely
                // contains closures at least, even if it's fully evaluated. As for serialization,
                // we thus need to fully substitute all variables first.
                let value1 = subst(
                    &self.context.pos_table,
                    &self.context.cache,
                    value1,
                    &self.initial_env,
                    &env1,
                );

                let Some(label) = value2.as_label() else {
                    return mk_type_error!("Label", 2, value2);
                };

                let mut label = label.clone();

                match value1.as_record() {
                    Some(Container::Empty) => Ok(NickelValue::label(label, pos2).into()),
                    Some(Container::Alloc(record_data)) => {
                        // If the contract returned a label as part of its error
                        // data, blame that one instead.
                        if let Some(user_label) = record_data
                            .fields
                            .get(&LocIdent::from("blame_location"))
                            .and_then(|field| field.value.as_ref())
                            .and_then(NickelValue::as_label)
                        {
                            label = user_label.clone();
                        }

                        if let Some(msg) = record_data
                            .fields
                            .get(&LocIdent::from("message"))
                            .and_then(|field| field.value.as_ref())
                            .and_then(NickelValue::as_string)
                        {
                            label = label.with_diagnostic_message(msg.clone().into_inner());
                        }

                        if let Some(notes) = record_data
                            .fields
                            .get(&LocIdent::from("notes"))
                            .and_then(|field| field.value.as_ref())
                            .and_then(NickelValue::as_array)
                            .and_then(Container::into_opt)
                        {
                            let notes = notes
                                .array
                                .iter()
                                .map(|element| {
                                    if let Some(s) = element.as_string() {
                                        Ok(s.clone().into_inner())
                                    } else {
                                        mk_type_error!("String (notes)", 1, element.clone())
                                    }
                                })
                                .collect::<Result<Vec<_>, _>>()?;

                            label = label.with_diagnostic_notes(notes);
                        }

                        Ok(NickelValue::label(label, pos2).into())
                    }
                    _ => {
                        mk_type_error!("Record", 1, value1)
                    }
                }
            }
            BinaryOp::Unseal => {
                if let Some(key) = value1.as_sealing_key() {
                    // The last argument (lazy, on the stack) of unseal is an expression raising
                    // blame. If the keys match, we ignore the blame and thus return a function
                    // `const unsealed_term_content`. Otherwise, we return `id`.
                    //
                    // Since the stack is set up as `[.] blame_expr`, this does ignore the error
                    // and proceed with the unsealed term in the happy path, or on the opposite
                    // drop the sealed term and proceed with the error on the stack otherwise.
                    Ok(if let Some(Term::Sealed(data)) = value2.as_term() {
                        if key == &data.key {
                            Closure {
                                value: mk_fun!(LocIdent::fresh(), data.inner.clone()),
                                env: env2,
                            }
                        } else {
                            mk_term::id().into()
                        }
                    } else {
                        mk_term::id().into()
                    })
                } else {
                    mk_type_error!("SealingKey", 1, value1)
                }
            }
            BinaryOp::Eq => {
                let c1 = Closure {
                    value: value1,
                    env: env1,
                };
                let c2 = Closure {
                    value: value2,
                    env: env2,
                };

                match eq(&mut self.context.cache, c1, c2, pos_op_inh)? {
                    EqResult::Bool(b) => match (b, self.stack.pop_eq()) {
                        (false, _) => {
                            self.stack.clear_eqs();
                            Ok(NickelValue::bool_value(false, pos_op_inh).into())
                        }
                        (true, None) => Ok(NickelValue::bool_value(true, pos_op_inh).into()),
                        (true, Some(EqItem { arg1, arg2 })) => {
                            let v1 = arg1.value.closurize(&mut self.context.cache, arg1.env);
                            let v2 = arg2.value.closurize(&mut self.context.cache, arg2.env);

                            // TODO: avoid term allocation in evaluation
                            Ok(NickelValue::term(Term::op2(BinaryOp::Eq, v1, v2), pos_op).into())
                        }
                    },
                    EqResult::Eqs(v1, v2, subeqs) => {
                        self.stack.push_eqs(subeqs.into_iter());

                        // TODO: avoid term allocation in evaluation
                        Ok(NickelValue::term(Term::op2(BinaryOp::Eq, v1, v2), pos_op).into())
                    }
                }
            }
            BinaryOp::LessThan => self.number_cmp2(
                |n1, n2| n1 < n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::LessOrEq => self.number_cmp2(
                |n1, n2| n1 <= n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::GreaterThan => self.number_cmp2(
                |n1, n2| n1 > n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::GreaterOrEq => self.number_cmp2(
                |n1, n2| n1 >= n2,
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::LabelGoField => {
                let Some(field) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let Some(label) = value2.as_label() else {
                    return mk_type_error!("Label", 2, value2);
                };

                let mut label = label.clone();
                label
                    .path
                    .push(ty_path::Elem::Field(field.clone().into_inner().into()));
                Ok(NickelValue::label(label, pos_op_inh).into())
            }
            BinaryOp::RecordGet => {
                // This error should be impossible to trigger. The parser
                // prevents a dynamic field access where the field name is not syntactically
                // a string.
                let Some(id) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let Some(container) = value2.as_record() else {
                    // Not using mk_type_error! because of a non-uniform message
                    return Err(Box::new(EvalErrorKind::TypeError {
                        expected: String::from("Record"),
                        message: String::from("field access only makes sense for records"),
                        orig_pos: orig_pos_arg2,
                        term: value2,
                    }));
                };

                let ident = LocIdent::from(id);

                let Container::Alloc(record) = container else {
                    return Err(Box::new(EvalErrorKind::FieldMissing {
                        id: ident,
                        field_names: Vec::new(),
                        operator: BinaryOp::RecordGet.to_string(),
                        pos_record: pos2,
                        pos_op,
                    }));
                };

                // We have to apply potential pending contracts. Right now, this
                // means that repeated field access will re-apply the contract again
                // and again, which is not optimal. The same thing happens with array
                // contracts. There are several way to improve this, but this is left
                // as future work.
                match record
                    .get_value_with_ctrs(&ident)
                    .map_err(|missing_field_err| missing_field_err.into_eval_err(pos2, pos_op))?
                {
                    Some(value) => {
                        self.call_stack
                            .enter_field(ident, pos2, value.pos_idx(), pos_op);
                        Ok(Closure { value, env: env2 })
                    }
                    None => match record.sealed_tail.as_ref() {
                        Some(t) if t.has_dyn_field(id) => {
                            Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                                action: IllegalPolymorphicTailAction::FieldAccess {
                                    field: id.to_string(),
                                },
                                evaluated_arg: t.label.get_evaluated_arg(&self.context.cache),
                                label: t.label.clone(),
                            }))
                        }
                        _ => Err(Box::new(EvalErrorKind::FieldMissing {
                            id: ident,
                            field_names: record.field_names(RecordOpKind::IgnoreEmptyOpt),
                            operator: BinaryOp::RecordGet.to_string(),
                            pos_record: pos2,
                            pos_op,
                        })),
                    },
                }
            }
            BinaryOp::RecordInsert {
                metadata,
                pending_contracts,
                ext_kind,
                op_kind,
            } => {
                // Since we take ownership of the data hidden in `RecordInsert`, we can't pretty
                // print it anymore. However we do need a string representation for the error case,
                // which we reconstruct here.
                let op_name = || {
                    BinaryOp::RecordInsert {
                        ext_kind,
                        op_kind,
                        metadata: SharedMetadata::empty(),
                        pending_contracts: Vec::new(),
                    }
                    .to_string()
                };

                let Some(id) = value1.as_string() else {
                    return mk_type_error!(op_name = op_name(), "String", 1, value1);
                };

                let mut value2 = value2;

                if value2.is_inline_empty_record() {
                    // We are going to insert in the record, so we make sure that it's an allocated
                    // block and not an inline empty record.
                    value2 = NickelValue::empty_record_block(pos2);
                }

                let ValueContentRefMut::Record(Container::Alloc(record)) =
                    value2.content_make_mut()
                else {
                    // Theoretically, we could be in the case `Record(Container::Empty)` here, but
                    // we made sure to allocate a record block to specifically exclude this case.
                    return mk_type_error!(op_name = op_name(), "Record", 2, value2);
                };

                // If a defined value is expected for this field, it must be
                // provided as an additional argument, so we pop it from the stack
                let value = if let RecordExtKind::WithValue = ext_kind {
                    let (value_closure, _) =
                        self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                            Box::new(EvalErrorKind::NotEnoughArgs(
                                3,
                                String::from("insert"),
                                pos_op,
                            ))
                        })?;

                    let closurized = value_closure
                        .value
                        .closurize(&mut self.context.cache, value_closure.env);
                    Some(closurized)
                } else {
                    None
                };

                match record.fields.insert(
                    LocIdent::from(id),
                    Field {
                        value,
                        metadata,
                        pending_contracts,
                    },
                ) {
                    Some(t)
                        if matches!(op_kind, RecordOpKind::ConsiderAllFields)
                            || !t.is_empty_optional() =>
                    {
                        Err(Box::new(EvalErrorKind::Other(
                            format!(
                                "{}: \
                                tried to extend a record with the field {id}, \
                                but it already exists",
                                op_name(),
                            ),
                            pos_op,
                        )))
                    }
                    _ => Ok(Closure {
                        // Insertion preserves the frozenness
                        value: value2,
                        env: env2,
                    }),
                }
            }
            BinaryOp::RecordRemove(op_kind) => {
                let Some(id) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let mut value2 = value2;

                if value2.is_inline_empty_record() {
                    // We are going to insert in the record, so we make sure that it's an allocated
                    // block and not an inline empty record.
                    value2 = NickelValue::empty_record_block(pos2);
                }

                let ValueContentRefMut::Record(Container::Alloc(record)) =
                    value2.content_make_mut()
                else {
                    // Theoretically, we could be in the case `Record(Container::Empty)` here, but
                    // we made sure to allocate a record block to specifically exclude this case.
                    return mk_type_error!("Record", 2, value2);
                };

                let fetched = record.fields.swap_remove(&LocIdent::from(id));

                if fetched.is_none()
                    || matches!(
                        (op_kind, fetched),
                        (
                            RecordOpKind::IgnoreEmptyOpt,
                            Some(Field {
                                value: None,
                                metadata, ..
                            })
                        ) if metadata.opt()
                    )
                {
                    match record.sealed_tail.as_ref() {
                        Some(t) if t.has_dyn_field(id) => {
                            Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                                action: IllegalPolymorphicTailAction::FieldRemove {
                                    field: id.to_string(),
                                },
                                evaluated_arg: t.label.get_evaluated_arg(&self.context.cache),
                                label: t.label.clone(),
                            }))
                        }
                        _ => Err(Box::new(EvalErrorKind::FieldMissing {
                            id: id.into(),
                            field_names: record.field_names(op_kind),
                            operator: String::from("record/remove"),
                            pos_record: pos2,
                            pos_op,
                        })),
                    }
                } else {
                    Ok(Closure {
                        value: value2,
                        env: env2,
                    })
                }
            }
            BinaryOp::RecordHasField(op_kind) => {
                let Some(id) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let Some(container) = value2.as_record() else {
                    return mk_type_error!("Record", 2, value2);
                };

                Ok(NickelValue::bool_value(matches!(
                            container.get(id.clone().into()),
                            Some(field) if matches!(op_kind, RecordOpKind::ConsiderAllFields) || !field.is_empty_optional()
                        ),
                    pos_op_inh
                ).into())
            }
            BinaryOp::RecordFieldIsDefined(op_kind) => {
                let Some(id) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let Some(container) = value2.as_record() else {
                    return mk_type_error!("Record", 2, value2);
                };

                Ok(NickelValue::bool_value(
                        matches!(
                            container.get(id.clone().into()),
                            Some(field @ Field { value: Some(_), ..}) if matches!(op_kind, RecordOpKind::ConsiderAllFields) || !field.is_empty_optional()
                        ),
                        pos_op_inh,
                ).into())
            }
            BinaryOp::ArrayConcat => {
                let Some(container1) = value1.as_array() else {
                    return mk_type_error!("Array", 1, value1);
                };

                let Some(container2) = value2.as_array() else {
                    return mk_type_error!("Array", 2, value2);
                };

                // If one of the array is empty, we directly return the other.
                let Container::Alloc(array_data1) = container1 else {
                    return Ok(value2.into());
                };

                let Container::Alloc(array_data2) = container2 else {
                    return Ok(value1.into());
                };

                // In all generality, we need to apply the pending contracts on both sides, as they
                // can differ. Even if some are common, the order of contracts is meaningful, so
                // deduplicating the common part is not trivial.
                //
                // Still, we can handle the following case: if the pending contracts are the same
                // size and are equal pairwise, we can keep them lazy. The typical case is when
                // there's only one contract, but it's doesn't cost much to try them all.

                if array_data1.pending_contracts.len() == array_data2.pending_contracts.len()
                    && array_data1
                        .pending_contracts
                        .iter()
                        .zip(array_data2.pending_contracts.iter())
                        .all(|(ctr1, ctr2)| {
                            !ctr1.can_have_poly_ctrs()
                                && contract_eq(&ctr1.contract, &env1, &ctr2.contract, &env2)
                        })
                {
                    // Cloning a slice is cheap: it's better to clone the left hand side and extend
                    // it rather that building a chained iterator.
                    let mut result = array_data1.array.clone();
                    result.extend(array_data2.array.iter().cloned());

                    Ok(NickelValue::array(
                        result,
                        array_data1.pending_contracts.clone(),
                        pos_op_inh,
                    )
                    .into())
                } else {
                    // We need to collect in two phases, since the mapped closures capture
                    // `&mut self.cache`, so chaining the iterators first wouldn't work.

                    // We need to collect in two phases, since the mapped closures capture
                    // `&mut self.cache`, so chaining the iterators first wouldn't work.
                    //
                    // Technically, we could clone `array_data1` and ierate mutably over its
                    // elements in hope of sharing some of the structure. However, since it's a
                    // clone, the leaves will be shared, and mutable iteration over a shared
                    // persistent vector won't have much advantage over collecting a new array from
                    // an iterator.
                    let mut result: Array = container1
                        .iter_with_pending_contracts(pos1)
                        .map(|elt| elt.closurize(&mut self.context.cache, env1.clone()))
                        .collect();

                    result.extend(
                        container2
                            .iter_with_pending_contracts(pos2)
                            .map(|elt| elt.closurize(&mut self.context.cache, env2.clone())),
                    );

                    Ok(NickelValue::array(result, Vec::new(), pos_op_inh).into())
                }
            }
            BinaryOp::ArrayAt => {
                let Some(container) = value1.as_array() else {
                    return mk_type_error!("Array", 1, value1);
                };

                let Some(n) = value2.as_number() else {
                    return mk_type_error!("Number", 2, value2);
                };

                let Ok(n_as_usize) = usize::try_from(n) else {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "array/at expects its second argument to be a \
                                positive integer smaller than {}, got {n}",
                            usize::MAX
                        ),
                        pos_op,
                    )));
                };

                let Container::Alloc(array_data) = container else {
                    return Err(Box::new(EvalErrorKind::Other(
                        "array/at: index out of bounds. \
                        Can't index into an empty array."
                            .to_owned(),
                        pos_op,
                    )));
                };

                if n_as_usize >= array_data.array.len() {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "array/at: index out of bounds. \
                                Expected an index between 0 and {}, got {}",
                            array_data.array.len(),
                            n
                        ),
                        pos_op,
                    )));
                }

                let elem_with_ctr = RuntimeContract::apply_all(
                    array_data.array.get(n_as_usize).unwrap().clone(),
                    array_data.pending_contracts.iter().cloned(),
                    pos1.to_inherited(),
                );

                Ok(Closure {
                    value: elem_with_ctr,
                    env: env1,
                })
            }
            BinaryOp::Merge(merge_label) => self.merge(
                value1,
                env1,
                value2,
                env2,
                pos_op,
                MergeMode::Standard(merge_label),
            ),
            BinaryOp::Hash => {
                let mk_err_fst =
                    || mk_type_error!("[| 'Md5, 'Sha1, 'Sha256, 'Sha512 |]", 1, value1.clone());

                let Some(enum_data) = value1.as_enum_variant() else {
                    return mk_err_fst();
                };

                if enum_data.arg.is_some() {
                    return mk_err_fst();
                }

                let Some(s) = value2.as_string() else {
                    return mk_type_error!("String", 2, value2);
                };

                let result = match enum_data.tag.as_ref() {
                    "Md5" => {
                        let mut hasher = md5::Md5::new();
                        hasher.update(s.as_ref());
                        hex_encode(&hasher.finalize())
                    }
                    "Sha1" => {
                        let mut hasher = sha1::Sha1::new();
                        hasher.update(s.as_ref());
                        hex_encode(&hasher.finalize())
                    }
                    "Sha256" => {
                        let mut hasher = sha2::Sha256::new();
                        hasher.update(s.as_ref());
                        hex_encode(&hasher.finalize())
                    }
                    "Sha512" => {
                        let mut hasher = sha2::Sha512::new();
                        hasher.update(s.as_ref());
                        hex_encode(&hasher.finalize())
                    }
                    _ => return mk_err_fst(),
                };

                Ok(NickelValue::string(result, pos_op_inh).into())
            }
            BinaryOp::Serialize => {
                let mk_err_fst = || mk_type_error!(ENUM_FORMAT, 1, value1.clone());

                let Some(enum_data) = value1.as_enum_variant() else {
                    return mk_err_fst();
                };

                if enum_data.arg.is_some() {
                    return mk_err_fst();
                }

                // Serialization needs all variables term to be fully substituted
                let initial_env = Environment::new();
                let v2_subst = subst(
                    &self.context.pos_table,
                    &self.context.cache,
                    value2,
                    &initial_env,
                    &env2,
                );

                let format = match enum_data.tag.to_string().as_str() {
                    "Json" => ExportFormat::Json,
                    "Yaml" => ExportFormat::Yaml,
                    "YamlDocuments" => ExportFormat::YamlDocuments,
                    "Toml" => ExportFormat::Toml,
                    _ => return mk_err_fst(),
                };

                serialize::validate(format, &v2_subst)?;

                Ok(
                    NickelValue::string(serialize::to_string(format, &v2_subst)?, pos_op_inh)
                        .into(),
                )
            }
            BinaryOp::Deserialize => {
                let mk_err_fst = || mk_type_error!(ENUM_FORMAT, 1, value1.clone());

                let Some(enum_data) = value1.as_enum_variant() else {
                    return mk_err_fst();
                };

                if enum_data.arg.is_some() {
                    return mk_err_fst();
                }

                let Some(s) = value2.as_string() else {
                    return mk_type_error!("String", 2, value2);
                };

                let deser: NickelValue = match enum_data.tag.label() {
                    "Json" => serde_json::from_str(s).map_err(|err| {
                        Box::new(EvalErrorKind::DeserializationError(
                            String::from("json"),
                            format!("{err}"),
                            pos_op,
                        ))
                    })?,
                    // TODO: we could try to generate better error positions here,
                    // but it will be some work.
                    //
                    // We pass `None` to `load_yaml` (so it produces a position-less
                    // `NickelValue`) even if we have a position for `s`, because `s` is
                    // likely not at offset zero in its file and so `load_yaml` will give
                    // the wrong error locations. Were it just a matter of offsetting the
                    // error location, this would be easy to fix. Unfortunately getting the
                    // locations right would involve handling location shifts caused by
                    // escape sequences and interpolation.
                    tag @ ("Yaml" | "YamlDocuments") => {
                        let listify = if tag == "Yaml" {
                            Listify::Auto
                        } else {
                            Listify::Always
                        };
                        crate::serialize::yaml::load_yaml_value(
                            &mut self.context.pos_table,
                            s,
                            None,
                            listify,
                        )
                        .map_err(|err| {
                            Box::new(EvalErrorKind::DeserializationErrorWithInner {
                                format: InputFormat::Yaml,
                                inner: err,
                                pos: pos_op,
                            })
                        })?
                    }
                    "Toml" => toml::from_str(s).map_err(|err| {
                        Box::new(EvalErrorKind::DeserializationError(
                            String::from("toml"),
                            format!("{err}"),
                            pos_op,
                        ))
                    })?,
                    _ => return mk_err_fst(),
                };

                Ok(deser.with_pos_idx(pos_op_inh).into())
            }
            BinaryOp::StringSplit => self.string_fn2(
                |input, sep| NickelValue::array(input.split(sep), Vec::new(), pos_op_inh),
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::StringContains => self.string_fn2(
                |s1, s2| NickelValue::bool_value(s1.contains(s2.as_str()), pos_op_inh),
                Op2EvalData {
                    op,
                    arg1: Closure {
                        value: value1,
                        env: env1,
                    },
                    arg2: Closure {
                        value: value2,
                        env: env2,
                    },
                    orig_pos_arg1,
                    orig_pos_arg2,
                    pos_op,
                },
            ),
            BinaryOp::StringCompare => {
                let as_term_pos = self.context.pos_table.get(pos_op_inh);

                self.string_fn2(
                    |s1, s2| {
                        use std::cmp::Ordering;

                        NickelValue::enum_tag(
                            LocIdent::new_with_pos(
                                match s1.cmp(s2) {
                                    Ordering::Less => "Lesser",
                                    Ordering::Equal => "Equal",
                                    Ordering::Greater => "Greater",
                                },
                                as_term_pos,
                            ),
                            pos_op_inh,
                        )
                    },
                    Op2EvalData {
                        op,
                        arg1: Closure {
                            value: value1,
                            env: env1,
                        },
                        arg2: Closure {
                            value: value2,
                            env: env2,
                        },
                        orig_pos_arg1,
                        orig_pos_arg2,
                        pos_op,
                    },
                )
            }
            BinaryOp::StringBase64Encode => {
                let mk_err_fst = || {
                    mk_type_error!(
                        "[| 'Standard, 'UrlSafe, 'NoPad, 'UrlSafeNoPad |]",
                        1,
                        value1.clone()
                    )
                };

                let Some(b64_variant) = value1.as_enum_variant() else {
                    return mk_err_fst();
                };

                if b64_variant.arg.is_some() {
                    return mk_err_fst();
                }

                let Some(s) = value2.as_string() else {
                    return mk_type_error!("String", 2, value2);
                };

                let result = match b64_variant.tag.as_ref() {
                    "Standard" => base64::prelude::BASE64_STANDARD.encode(s.as_str()),
                    "UrlSafe" => base64::prelude::BASE64_URL_SAFE.encode(s.as_str()),
                    "NoPad" => base64::prelude::BASE64_STANDARD_NO_PAD.encode(s.as_str()),
                    "UrlSafeNoPad" => base64::prelude::BASE64_URL_SAFE_NO_PAD.encode(s.as_str()),
                    _ => return mk_err_fst(),
                };

                Ok(NickelValue::string(result, pos_op_inh).into())
            }
            BinaryOp::StringBase64Decode => {
                let mk_err_fst = || {
                    mk_type_error!(
                        "[| 'Standard, 'UrlSafe, 'NoPad, 'UrlSafeNoPad |]",
                        1,
                        value1.clone()
                    )
                };

                let Some(b64_variant) = value1.as_enum_variant() else {
                    return mk_err_fst();
                };

                if b64_variant.arg.is_some() {
                    return mk_err_fst();
                }

                let Some(s) = value2.as_string() else {
                    return mk_type_error!("String", 2, value2);
                };

                let decode_with = |engine: base64::engine::GeneralPurpose| {
                    let decode_result = engine
                        .decode(s.as_str())
                        .map_err(|err| format!("Base64 decoding failed: {err}"))
                        .and_then(|decoded_bytes| {
                            String::from_utf8(decoded_bytes).map_err(|err| {
                                format!("Could not convert decoded value to string: {err}")
                            })
                        });
                    match decode_result {
                        Ok(decoded_string) => Ok(NickelValue::enum_variant(
                            "Ok",
                            Some(NickelValue::string(decoded_string, pos_op_inh)),
                            pos_op_inh,
                        )
                        .into()),
                        Err(err) => Ok(NickelValue::enum_variant(
                            "Error",
                            Some(
                                mk_record!(("message", NickelValue::string_posless(err)))
                                    .with_pos_idx(pos_op_inh),
                            ),
                            pos_op_inh,
                        )
                        .into()),
                    }
                };

                match b64_variant.tag.as_ref() {
                    "Standard" => decode_with(base64::prelude::BASE64_STANDARD),
                    "UrlSafe" => decode_with(base64::prelude::BASE64_URL_SAFE),
                    "NoPad" => decode_with(base64::prelude::BASE64_STANDARD_NO_PAD),
                    "UrlSafeNoPad" => decode_with(base64::prelude::BASE64_URL_SAFE_NO_PAD),
                    _ => mk_err_fst(),
                }
            }
            BinaryOp::ContractArrayLazyApp => {
                let (ctr, _) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(
                        3,
                        String::from("contract/array_lazy_app"),
                        pos_op,
                    ))
                })?;

                let Closure {
                    value: ctr_val,
                    env: env_ctr,
                } = ctr;

                let Some(label) = value1.as_label() else {
                    return mk_type_error!("Label", 1, value1);
                };

                if value2.is_inline_empty_array() {
                    // We are going to insert in the array, so we make sure that it's an allocated
                    // block and not an inline empty array.
                    value2 = NickelValue::empty_array_block(pos2);
                }

                let ValueContentRefMut::Array(Container::Alloc(array_data)) =
                    value2.content_make_mut()
                else {
                    // Theoretically, we could be in the case `Array(Container::Empty)` here, but
                    // we made sure to allocate an array block to specifically exclude this case.
                    return mk_type_error!("Array", 2, value2);
                };

                // Preserve the environment of the contract in the resulting array.
                let contract = ctr_val.closurize(&mut self.context.cache, env_ctr);
                RuntimeContract::push_dedup(
                    &mut array_data.pending_contracts,
                    &env2,
                    RuntimeContract::new(contract, label.clone()),
                    &Environment::new(),
                );

                let array_with_ctr = Closure {
                    value: value2,
                    env: env2,
                };

                Ok(array_with_ctr)
            }
            BinaryOp::ContractRecordLazyApp => {
                // The contract is expected to be of type `String -> Contract`: it takes the name
                // of the field as a parameter, and returns a contract.
                let (
                    Closure {
                        value: ctr_val,
                        env: ctr_env,
                    },
                    _,
                ) = self.stack.pop_arg(&self.context.cache).ok_or_else(|| {
                    Box::new(EvalErrorKind::NotEnoughArgs(
                        3,
                        String::from("contract/record_lazy_app"),
                        pos_op,
                    ))
                })?;

                let Some(label) = value1.as_label() else {
                    return mk_type_error!("Label", 1, value1);
                };

                let Some(container) = value2.as_record() else {
                    return mk_type_error!("Record", 2, value2);
                };

                let Container::Alloc(record_data) = container else {
                    return Ok(NickelValue::empty_record().with_pos_idx(pos2).into());
                };

                let mut record_data = record_data.clone();

                // Applying a lazy contract unfreezes a record, as frozen record are
                // expected to have all their contracts applied and thus an empty list of
                // pending contracts.
                record_data.attrs.frozen = false;

                let mut contract_at_field = |id: LocIdent| {
                    let pos = ctr_val.pos_idx();
                    mk_app!(
                        ctr_val.clone(),
                        NickelValue::string(id, self.context.pos_table.push(id.pos))
                    )
                    .with_pos_idx(pos)
                    .closurize(&mut self.context.cache, ctr_env.clone())
                };

                for (id, field) in record_data.fields.iter_mut() {
                    let runtime_ctr = RuntimeContract {
                        contract: contract_at_field(*id),
                        label: label.clone(),
                    };

                    RuntimeContract::push_dedup(
                        &mut field.pending_contracts,
                        &env2,
                        runtime_ctr,
                        &ctr_env,
                    );
                }

                // IMPORTANT: here, we revert the record back to a `RecRecord`. The
                // reason is that applying a contract over fields might change the
                // value of said fields (the typical example is adding a value to a
                // subrecord via the default value of a contract).
                //
                // We want recursive occurrences of fields to pick this new value as
                // well: hence, we need to recompute the fixpoint, which is done by
                // `fixpoint::revert`.
                let reverted = super::fixpoint::revert(&mut self.context.cache, record_data);

                Ok(NickelValue::term(reverted, pos2).into())
            }
            BinaryOp::LabelWithMessage => {
                let Some(message) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let ValueContentRefMut::Label(label) = value2.content_make_mut() else {
                    return mk_type_error!("Label", 2, value2);
                };

                label.set_diagnostic_message(message.clone().into_inner());
                Ok(value2.into())
            }
            BinaryOp::LabelWithNotes => {
                // We need to extract plain strings from a Nickel array, which most likely
                // contains at least generated variables.
                // As for serialization, we thus fully substitute all variables first.
                let val1_subst = subst(
                    &self.context.pos_table,
                    &self.context.cache,
                    value1.clone(),
                    &Environment::new(),
                    &env1,
                );

                let Some(array_data) = val1_subst.as_array() else {
                    return mk_type_error!("Array", 1, value1);
                };

                let ValueContentRefMut::Label(label) = value2.content_make_mut() else {
                    return mk_type_error!("Label", 2, value2);
                };

                let notes = array_data
                    .iter()
                    .map(|element| {
                        if let Some(s) = element.as_string() {
                            Ok(s.clone().into_inner())
                        } else {
                            mk_type_error!("String", 1, element.clone())
                        }
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                label.set_diagnostic_notes(notes);

                Ok(value2.into())
            }
            BinaryOp::LabelAppendNote => {
                let Some(note) = value1.as_string() else {
                    return mk_type_error!("String", 1, value1);
                };

                let ValueContentRefMut::Label(label) = value2.content_make_mut() else {
                    return mk_type_error!("Label", 2, value2);
                };

                label.append_diagnostic_note(note);
                Ok(value2.into())
            }
            BinaryOp::LabelLookupTypeVar => {
                let Some(key) = value1.as_sealing_key() else {
                    return mk_type_error!("SealingKey", 1, value1);
                };

                let Some(label) = value2.as_label() else {
                    return mk_type_error!("Label", 2, value2);
                };

                Ok(NickelValue::from(
                    label
                        .type_environment
                        .iter()
                        // We rev to find the latest binding, if there ever were several type
                        // variables bound with the same name
                        .rev()
                        .find_map(|(k, data)| (k == key).then_some(data))
                        .unwrap(),
                )
                .with_pos_idx(pos_op_inh)
                .into())
            }
            BinaryOp::RecordSplitPair => {
                let Some(cont1) = value1.as_record() else {
                    return mk_type_error!("Record", 1, value1);
                };

                let Some(cont2) = value2.as_record() else {
                    return mk_type_error!("Record", 2, value2);
                };

                let record1 = cont1.into_opt();
                let record2 = cont2.into_opt();

                let split::SplitResult {
                    left,
                    center,
                    right,
                } = split::split_ref(
                    record1
                        .as_ref()
                        .map(|r| &r.fields)
                        .unwrap_or(&Default::default()),
                    record2
                        .as_ref()
                        .map(|r| &r.fields)
                        .unwrap_or(&Default::default()),
                );

                let left_only = NickelValue::record_posless(RecordData {
                    fields: left,
                    sealed_tail: record1
                        .as_ref()
                        .map(|r| r.sealed_tail.clone())
                        .unwrap_or_default(),
                    attrs: record1.as_ref().map(|r| r.attrs).unwrap_or_default(),
                });

                let right_only = NickelValue::record_posless(RecordData {
                    fields: right,
                    sealed_tail: record2
                        .as_ref()
                        .map(|r| r.sealed_tail.clone())
                        .unwrap_or_default(),
                    attrs: record2.as_ref().map(|r| r.attrs).unwrap_or_default(),
                });

                let (center1, center2): (IndexMap<LocIdent, Field>, IndexMap<LocIdent, Field>) =
                    center
                        .into_iter()
                        .map(|(id, (left, right))| ((id, left), (id, right)))
                        .unzip();

                let left_center = NickelValue::record_posless(RecordData {
                    fields: center1,
                    sealed_tail: None,
                    attrs: RecordAttrs::default(),
                });

                let right_center = NickelValue::record_posless(RecordData {
                    fields: center2,
                    sealed_tail: None,
                    attrs: RecordAttrs::default(),
                });

                Ok(closurize_container(NickelValue::record(
                    RecordData {
                        fields: IndexMap::from([
                            (LocIdent::from("left_only"), Field::from(left_only)),
                            (LocIdent::from("left_center"), Field::from(left_center)),
                            (LocIdent::from("right_center"), Field::from(right_center)),
                            (LocIdent::from("right_only"), Field::from(right_only)),
                        ]),
                        attrs: RecordAttrs::default(),
                        sealed_tail: None,
                    },
                    pos_op_inh,
                ))
                .into())
            }
            BinaryOp::RecordDisjointMerge => {
                let Some(container1) = value1.as_record() else {
                    return mk_type_error!("Record", 1, value1);
                };

                let Some(container2) = value2.as_record() else {
                    return mk_type_error!("Record", 2, value2);
                };

                let (record1, record2) = match (container1, container2) {
                    (Container::Alloc(record1), Container::Alloc(record2)) => (record1, record2),
                    (Container::Empty, _) => {
                        return Ok(Closure {
                            value: value2.with_pos_idx(pos_op_inh),
                            env: env2,
                        });
                    }
                    (_, Container::Empty) => {
                        return Ok(Closure {
                            value: value1.with_pos_idx(pos_op_inh),
                            env: env1,
                        });
                    }
                };

                // As for merge, we refuse to combine two records if one of them has a sealed tail.
                // However, if only one of them does, because we don't do any recursive
                // re-evaluation here, it's fine to just pick this tail as the tail of the result.
                //
                // This behavior is actually useful, because disjoint_merge is used in the
                // implementation of builtin contracts to combine an unsealed tail with the
                // original body of the record. In that case, the unsealed tail might have an
                // additional sealed tail itself (tail can be sealed multiple times in a nested
                // way), and the right behavior (tm) is to just keep it.
                let sealed_tail = match (&record1.sealed_tail, &record2.sealed_tail) {
                    (Some(tail1), Some(_)) => {
                        return Err(Box::new(EvalErrorKind::IllegalPolymorphicTailAccess {
                            action: IllegalPolymorphicTailAction::Merge,
                            evaluated_arg: tail1.label.get_evaluated_arg(&self.context.cache),
                            label: tail1.label.clone(),
                        }));
                    }
                    (tail1, tail2) => tail1.as_ref().or(tail2.as_ref()).cloned(),
                };

                // Note that because of record closurization, we assume here that the record data
                // of each record are already closurized, so we don't really care about
                // environments. Should that invariant change, we might get into trouble (trouble
                // meaning undue `UnboundIdentifier` errors).
                let mut fields =
                    IndexMap::with_capacity(record1.fields.len() + record2.fields.len());

                fields.extend(record1.fields.iter().map(|(k, v)| (*k, v.clone())));
                fields.extend(record2.fields.iter().map(|(k, v)| (*k, v.clone())));

                let attrs = Combine::combine(record1.attrs, record2.attrs);

                Ok(NickelValue::record(
                    RecordData {
                        fields,
                        attrs,
                        sealed_tail,
                    },
                    pos_op_inh,
                )
                .into())
            }
        }
    }

    fn number_cmp2<F>(&mut self, f: F, eval_data: Op2EvalData) -> Result<Closure, ErrorKind>
    where
        F: Fn(&Number, &Number) -> bool,
    {
        let pos_op_inh = eval_data.pos_op.to_inherited();

        self.number_fn2(
            |n1, n2| NickelValue::bool_value(f(n1, n2), pos_op_inh),
            eval_data,
        )
    }

    fn number_op2<F>(&mut self, f: F, eval_data: Op2EvalData) -> Result<Closure, ErrorKind>
    where
        F: Fn(&Number, &Number) -> Number,
    {
        let pos_op_inh = eval_data.pos_op.to_inherited();

        self.number_fn2(
            |n1, n2| NickelValue::number(f(n1, n2), pos_op_inh),
            eval_data,
        )
    }

    fn number_fn2<F>(&mut self, f: F, eval_data: Op2EvalData) -> Result<Closure, ErrorKind>
    where
        F: Fn(&Number, &Number) -> NickelValue,
    {
        let Op2EvalData {
            op,
            arg1: Closure {
                value: value1,
                env: _,
            },
            arg2: Closure {
                value: value2,
                env: _,
            },
            orig_pos_arg1,
            orig_pos_arg2,
            pos_op,
        } = eval_data;

        let Some(n1) = value1.as_number() else {
            return Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                primop: op.to_string(),
                expected: "Number".to_owned(),
                arg_number: 1,
                pos_arg: orig_pos_arg1,
                arg_evaluated: value1,
                pos_op,
            }));
        };

        let Some(n2) = value2.as_number() else {
            return Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                primop: op.to_string(),
                expected: "Number".to_owned(),
                arg_number: 2,
                pos_arg: orig_pos_arg2,
                arg_evaluated: value2,
                pos_op,
            }));
        };

        Ok(f(n1, n2).into())
    }

    fn string_fn2<F>(&mut self, f: F, eval_data: Op2EvalData) -> Result<Closure, ErrorKind>
    where
        F: Fn(&NickelString, &NickelString) -> NickelValue,
    {
        let Op2EvalData {
            op,
            arg1: Closure {
                value: value1,
                env: _,
            },
            arg2: Closure {
                value: value2,
                env: _,
            },
            orig_pos_arg1,
            orig_pos_arg2,
            pos_op,
        } = eval_data;

        let Some(s1) = value1.as_string() else {
            return Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                primop: op.to_string(),
                expected: "String".to_owned(),
                arg_number: 1,
                pos_arg: orig_pos_arg1,
                arg_evaluated: value1,
                pos_op,
            }));
        };

        let Some(s2) = value2.as_string() else {
            return Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                primop: op.to_string(),
                expected: "String".to_owned(),
                arg_number: 2,
                pos_arg: orig_pos_arg2,
                arg_evaluated: value2,
                pos_op,
            }));
        };

        Ok(f(s1, s2).into())
    }

    /// Evaluate a n-ary operation.
    ///
    /// Arguments are expected to be evaluated (in WHNF).
    fn eval_opn(&mut self, eval_data: OpNEvalData) -> Result<Closure, ErrorKind> {
        let OpNEvalData { op, args, pos_op } = eval_data;
        increment!(format!("primop:{op}"));
        let pos_op_inh = pos_op.to_inherited();

        let mk_type_error =
            |expected: &str, arg_number: usize, pos_arg: PosIdx, arg_evaluated: NickelValue| {
                Err(Box::new(EvalErrorKind::NAryPrimopTypeError {
                    primop: op.to_string(),
                    expected: expected.to_owned(),
                    arg_number,
                    pos_arg,
                    arg_evaluated,
                    pos_op,
                }))
            };

        // Currently, for fixed arity primitive operators, the parser must ensure that they get
        // exactly the right number of argument: if it is not the case, this is a bug, and we panic.
        match op {
            NAryOp::StringReplace | NAryOp::StringReplaceRegex => {
                let mut args_wo_env = args.into_iter().map(|(arg, pos)| (arg.value, pos));
                let (arg1, arg_pos1) = args_wo_env.next().unwrap();
                let (arg2, arg_pos2) = args_wo_env.next().unwrap();
                let (arg3, arg_pos3) = args_wo_env.next().unwrap();
                debug_assert!(args_wo_env.next().is_none());

                let Some(s) = arg1.as_string() else {
                    return mk_type_error("String", 1, arg_pos1, arg1);
                };

                let Some(from) = arg2.as_string() else {
                    return mk_type_error("String", 2, arg_pos2, arg2);
                };

                let Some(to) = arg3.as_string() else {
                    return mk_type_error("String", 3, arg_pos3, arg3);
                };

                let result = if let NAryOp::StringReplace = op {
                    s.replace(from.as_str(), to.as_str())
                } else {
                    let re = regex::Regex::new(from)
                        .map_err(|err| Box::new(EvalErrorKind::Other(err.to_string(), pos_op)))?;

                    s.replace_regex(&CompiledRegex(re), to)
                };

                Ok(NickelValue::string(result, pos_op_inh).into())
            }
            NAryOp::StringSubstr => {
                let mut args_wo_env = args.into_iter().map(|(arg, pos)| (arg.value, pos));
                let (arg1, arg_pos1) = args_wo_env.next().unwrap();
                let (arg2, arg_pos2) = args_wo_env.next().unwrap();
                let (arg3, arg_pos3) = args_wo_env.next().unwrap();
                debug_assert!(args_wo_env.next().is_none());

                let Some(s) = arg1.as_string() else {
                    return mk_type_error("String", 1, arg_pos1, arg1);
                };

                let Some(start) = arg2.as_number() else {
                    return mk_type_error("Number", 2, arg_pos2, arg2);
                };

                let Some(end) = arg3.as_number() else {
                    return mk_type_error("Number", 3, arg_pos3, arg3);
                };

                s.substring(start, end)
                    .map(|substr| NickelValue::string(substr, pos_op_inh).into())
                    .map_err(|e| Box::new(EvalErrorKind::Other(format!("{e}"), pos_op)))
            }
            NAryOp::MergeContract => {
                let mut args_iter = args.into_iter();

                let (
                    Closure {
                        value: arg1,
                        env: _,
                    },
                    _,
                ) = args_iter.next().unwrap();

                let (
                    Closure {
                        value: arg2,
                        env: env2,
                    },
                    _,
                ) = args_iter.next().unwrap();

                let (
                    Closure {
                        value: arg3,
                        env: env3,
                    },
                    _,
                ) = args_iter.next().unwrap();

                debug_assert!(args_iter.next().is_none());

                let Some(label) = arg1.as_label() else {
                    return Err(Box::new(EvalErrorKind::InternalError(
                        format!(
                            "The {op} operator was expecting \
                                a first argument of type Label, got {}",
                            arg1.type_of().unwrap_or("<unevaluated>")
                        ),
                        pos_op,
                    )));
                };

                self.merge(
                    arg2,
                    env2,
                    arg3,
                    env3,
                    pos_op,
                    MergeMode::Contract(label.clone()),
                )
            }
            NAryOp::RecordSealTail => {
                let mut args = args.into_iter();
                let (
                    Closure {
                        value: arg1,
                        env: _,
                    },
                    arg_pos1,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: arg2,
                        env: _,
                    },
                    arg_pos2,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: mut arg3,
                        env: env3,
                    },
                    arg_pos3,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: arg4,
                        env: env4,
                    },
                    arg_pos4,
                ) = args.next().unwrap();

                debug_assert!(args.next().is_none());

                let Some(s) = arg1.as_sealing_key() else {
                    return mk_type_error("SealingKey", 1, arg_pos1, arg1);
                };

                let Some(label) = arg2.as_label() else {
                    return mk_type_error("Label", 2, arg_pos2, arg2);
                };

                if arg3.is_inline_empty_record() {
                    // We are going to insert in the record, so we make sure that it's an allocated
                    // block and not an inline empty record.
                    arg3 = NickelValue::empty_record_block(arg3.pos_idx());
                }

                let ValueContentRefMut::Record(Container::Alloc(r)) = arg3.content_make_mut()
                else {
                    return mk_type_error("Record", 3, arg_pos3, arg3);
                };

                // Even if the record to seal is empty, the correctness of polymorphic contracts
                // relies on the symmetry of sealing/unsealing operations. It's wiser to always
                // seal a tail, even when empty.
                let Some(tail) = arg4.as_record() else {
                    return mk_type_error("Record", 4, arg_pos4, arg4);
                };

                let tail_closurized = arg4.clone().closurize(&mut self.context.cache, env4);
                let fields = tail
                    .into_opt()
                    .map(|r| r.fields.keys().map(|s| s.ident()).collect())
                    .unwrap_or_default();
                r.sealed_tail = Some(Rc::new(record::SealedTail::new(
                    *s,
                    label.clone(),
                    tail_closurized,
                    fields,
                )));

                Ok(Closure {
                    value: arg3,
                    env: env3,
                })
            }
            NAryOp::RecordUnsealTail => {
                let mut args = args.into_iter();
                let (
                    Closure {
                        value: arg1,
                        env: _,
                    },
                    arg_pos1,
                ) = args.next().unwrap();
                let (
                    Closure {
                        value: arg2,
                        env: _,
                    },
                    arg_pos2,
                ) = args.next().unwrap();
                let (
                    Closure {
                        value: arg3,
                        env: env3,
                    },
                    arg_pos3,
                ) = args.next().unwrap();

                debug_assert!(args.next().is_none());

                let Some(s) = arg1.as_sealing_key() else {
                    return mk_type_error("SealingKey", 1, arg_pos1, arg1);
                };

                let Some(label) = arg2.as_label() else {
                    return mk_type_error("Label", 2, arg_pos2, arg2);
                };

                let Some(container) = arg3.as_record() else {
                    return mk_type_error("Record", 3, arg_pos3, arg3);
                };

                container
                    .into_opt()
                    .and_then(|record| record.sealed_tail.as_ref())
                    .and_then(|tail| tail.unseal(s).cloned())
                    .ok_or_else(|| {
                        Box::new(EvalErrorKind::BlameError {
                            evaluated_arg: label.get_evaluated_arg(&self.context.cache),
                            label: label.clone(),
                        })
                    })
                    .map(|tail_unsealed| Closure {
                        value: tail_unsealed,
                        env: env3,
                    })
            }
            NAryOp::LabelInsertTypeVar => {
                let mut args = args.into_iter();

                let (
                    Closure {
                        value: arg1,
                        env: _,
                    },
                    arg_pos1,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: arg2,
                        env: _,
                    },
                    arg_pos2,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: mut arg3,
                        env: _,
                    },
                    arg_pos3,
                ) = args.next().unwrap();

                debug_assert!(args.next().is_none());

                let Some(key) = arg1.as_sealing_key() else {
                    return mk_type_error("SealingKey", 1, arg_pos1, arg1);
                };

                let Ok(polarity) = Polarity::try_from(&arg2) else {
                    return mk_type_error("Polarity", 2, arg_pos2, arg2);
                };

                let ValueContentRefMut::Label(label) = arg3.content_make_mut() else {
                    return mk_type_error("Label", 3, arg_pos3, arg3);
                };

                label
                    .type_environment
                    .push((*key, TypeVarData { polarity }));

                Ok(arg3.with_pos_idx(arg_pos3.to_inherited()).into())
            }
            NAryOp::ArraySlice => {
                let mut args = args.into_iter();

                let (
                    Closure {
                        value: arg1,
                        env: _,
                    },
                    arg_pos1,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: arg2,
                        env: _,
                    },
                    arg_pos2,
                ) = args.next().unwrap();

                let (
                    Closure {
                        value: mut arg3,
                        env: env3,
                    },
                    arg_pos3,
                ) = args.next().unwrap();

                debug_assert!(args.next().is_none());

                let Some(start) = arg1.as_number() else {
                    return mk_type_error("Number", 1, arg_pos1, arg1);
                };

                let Some(end) = arg2.as_number() else {
                    return mk_type_error("Number", 2, arg_pos2, arg2);
                };

                if arg3.is_inline_empty_array() {
                    // We are going to insert in the array, so we make sure that it's an allocated
                    // block and not an inline empty array.
                    arg3 = NickelValue::empty_array_block(arg3.pos_idx());
                }

                let ValueContentRefMut::Array(Container::Alloc(ArrayData { array, .. })) =
                    arg3.content_make_mut()
                else {
                    return mk_type_error("Array", 3, arg_pos3, arg3);
                };

                let Ok(start_as_usize) = usize::try_from(start) else {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "{op} expects its first argument (start) to be a \
                            positive integer smaller than {}, got {start}",
                            usize::MAX
                        ),
                        pos_op,
                    )));
                };

                let Ok(end_as_usize) = usize::try_from(end) else {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "{op} expects its second argument (end) to be a \
                            positive integer smaller than {}, got {end}",
                            usize::MAX
                        ),
                        pos_op,
                    )));
                };

                if end_as_usize < start_as_usize || end_as_usize > array.len() {
                    return Err(Box::new(EvalErrorKind::Other(
                        format!(
                            "{op}: index out of bounds. Expected `start <= end <= {}`, but \
                            got `start={start}` and `end={end}`.",
                            array.len()
                        ),
                        pos_op,
                    )));
                }

                array.slice(start_as_usize, end_as_usize);

                Ok(Closure {
                    value: arg3.with_pos_idx(pos_op_inh),
                    env: env3,
                })
            }
        }
    }
}

fn hex_encode(bytes: &[u8]) -> String {
    use std::fmt::Write;
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        write!(&mut out, "{b:02x}").unwrap();
    }
    out
}

/// The enum tag returned by Typeof and Cast.
///
/// This function is a less precise version of `v.type_of()`, because `type_tag` has backward
/// compatibility guarantees to uphold. Instead of relying on
/// [crate::eval::value::NickelValue::type_of], it's safer to duplicate the logic here.
fn type_tag(v: &NickelValue) -> &'static str {
    match v.content_ref() {
        ValueContentRef::Null => "Other",
        ValueContentRef::Bool(_) => "Bool",
        ValueContentRef::Number(_) => "Number",
        ValueContentRef::Array(_) => "Array",
        ValueContentRef::Record(_) => "Record",
        ValueContentRef::String(_) => "String",
        ValueContentRef::Term(term) => match term {
            Term::RecRecord(..) => "Record",
            Term::Fun(..) => "Function",
            _ => "Other",
        },
        ValueContentRef::Label(_) => "Label",
        ValueContentRef::EnumVariant(_) => "Enum",
        ValueContentRef::ForeignId(_) => "ForeignId",
        ValueContentRef::CustomContract(_) => "CustomContract",
        ValueContentRef::Type(_) => "Type",
        _ => "Other",
    }
}

/// Compute the equality of two terms, represented as closures.
///
/// # Parameters
///
/// - `c1`: the closure of the first operand.
/// - `c2`: the closure of the second operand.
/// - `pos_op`: the position of the equality operation, used for error diagnostics.
///
/// # Return
///
/// If the comparison is successful, returns a bool indicating whether the values were equal,
/// otherwise returns an [`EvalError`] indicating that the values cannot be compared (typically two
/// functions).
///
/// # Uncomparable values
///
/// Comparing two functions is undecidable. Even in simple cases, it's not trivial to handle an
/// approximation (functions might capture free variables, you'd need to take eta-conversion into
/// account to equate e.g. `fun x => x` and `fun y => y`, etc.).
///
/// Thus, by default, comparing a function to something else always returns `false`. However, this
/// breaks the reflexivity property of equality, which users might rightfully rely on, because `fun
/// x => x` isn't equal to itself. Also, comparing two functions is probably never intentional nor
/// meaningful: thus we error out when trying to compare two functions. We still allow comparing
/// functions to something else, because it's useful to have tests like `if value == 1` or `if
/// value == null` typically in contracts without having to defensively check that `value` is a
/// function.
///
/// The same reasoning applies to foreign values (which we don't want to compare for security
/// reasons, at least right now, not because we can't).
fn eq<C: Cache>(
    cache: &mut C,
    c1: Closure,
    c2: Closure,
    pos_op: PosIdx,
) -> Result<EqResult, ErrorKind> {
    let Closure {
        value: value1,
        env: env1,
    } = c1;

    let Closure {
        value: value2,
        env: env2,
    } = c2;

    // Take a list of subequalities, and either return `EqResult::Bool(true)` if it is empty, or
    // generate an appropriate `EqResult::Eqs` variant with closurized terms in it.
    fn gen_eqs<I, C: Cache>(
        cache: &mut C,
        mut it: I,
        env1: Environment,
        env2: Environment,
    ) -> EqResult
    where
        I: Iterator<Item = (NickelValue, NickelValue)>,
    {
        if let Some((v1, v2)) = it.next() {
            let eqs = it
                .map(|(v1, v2)| {
                    (
                        Closure {
                            value: v1,
                            env: env1.clone(),
                        },
                        Closure {
                            value: v2,
                            env: env2.clone(),
                        },
                    )
                })
                .collect();

            EqResult::Eqs(v1.closurize(cache, env1), v2.closurize(cache, env2), eqs)
        } else {
            EqResult::Bool(true)
        }
    }

    match (value1.content_ref(), value2.content_ref()) {
        (ValueContentRef::Null, ValueContentRef::Null) => Ok(EqResult::Bool(true)),
        (ValueContentRef::Bool(b1), ValueContentRef::Bool(b2)) => Ok(EqResult::Bool(b1 == b2)),
        (ValueContentRef::Number(n1), ValueContentRef::Number(n2)) => Ok(EqResult::Bool(n1 == n2)),
        (ValueContentRef::String(s1), ValueContentRef::String(s2)) => Ok(EqResult::Bool(s1 == s2)),
        (ValueContentRef::Label(l1), ValueContentRef::Label(l2)) => Ok(EqResult::Bool(l1 == l2)),
        (ValueContentRef::SealingKey(k1), ValueContentRef::SealingKey(k2)) => {
            Ok(EqResult::Bool(k1 == k2))
        }
        (
            ValueContentRef::EnumVariant(EnumVariantData {
                tag: tag1,
                arg: None,
            }),
            ValueContentRef::EnumVariant(EnumVariantData {
                tag: tag2,
                arg: None,
            }),
        ) => Ok(EqResult::Bool(tag1.ident() == tag2.ident())),
        (
            ValueContentRef::EnumVariant(EnumVariantData {
                tag: tag1,
                arg: Some(arg1),
            }),
            ValueContentRef::EnumVariant(EnumVariantData {
                tag: tag2,
                arg: Some(arg2),
            }),
        ) if tag1.ident() == tag2.ident() => Ok(gen_eqs(
            cache,
            std::iter::once((arg1.clone(), arg2.clone())),
            env1,
            env2,
        )),
        // [^eq-empty-containers] We can't just handle the pattern `(Container::Empty,
        // Container::Empty)`, because the first could be the inlined empty record while the second
        // is allocated but empty as well (typically the case for the empty open record `{..}`), or
        // have only empty optional fields (which equality ignores). Hence we rely on
        // `has_only_empty_opts`, which handles both cases.
        (ValueContentRef::Record(container1), ValueContentRef::Record(container2))
            if container1.has_only_empty_opts() && container2.has_only_empty_opts() =>
        {
            Ok(EqResult::Bool(true))
        }
        (
            ValueContentRef::Record(Container::Alloc(r1)),
            ValueContentRef::Record(Container::Alloc(r2)),
        ) => {
            let merge::split::SplitResult {
                left,
                center,
                right,
            } = merge::split::split_ref(&r1.fields, &r2.fields);

            // As for other record operations, we ignore optional fields without a definition.
            if !left.values().all(Field::is_empty_optional)
                || !right.values().all(Field::is_empty_optional)
            {
                Ok(EqResult::Bool(false))
            } else if center.is_empty() {
                Ok(EqResult::Bool(true))
            } else {
                // We consider undefined values to be equal. We filter out pairs of undefined
                // values, but we reject pairs where one of the value is undefined and not the
                // other.
                let eqs: Result<Vec<_>, _> = center
                    .into_iter()
                    .filter_map(|(id, (field1, field2))| match (field1, field2) {
                        (
                            Field {
                                value: Some(value1),
                                pending_contracts: pending_contracts1,
                                ..
                            },
                            Field {
                                value: Some(value2),
                                pending_contracts: pending_contracts2,
                                ..
                            },
                        ) => {
                            let pos1 = value1.pos_idx();
                            let pos2 = value2.pos_idx();

                            let value1_with_ctr =
                                RuntimeContract::apply_all(value1, pending_contracts1, pos1);
                            let value2_with_ctr =
                                RuntimeContract::apply_all(value2, pending_contracts2, pos2);
                            Some(Ok((value1_with_ctr, value2_with_ctr)))
                        }
                        (Field { value: None, .. }, Field { value: None, .. }) => None,
                        (
                            Field {
                                value: v1 @ None,
                                metadata,
                                ..
                            },
                            Field { value: Some(_), .. },
                        )
                        | (
                            Field {
                                value: v1 @ Some(_),
                                ..
                            },
                            Field {
                                value: None,
                                metadata,
                                ..
                            },
                        ) => {
                            let pos_record = if v1.is_none() {
                                value1.pos_idx()
                            } else {
                                value2.pos_idx()
                            };

                            Some(Err(Box::new(EvalErrorKind::MissingFieldDef {
                                id,
                                metadata: metadata.into_inner(),
                                pos_record,
                                pos_access: pos_op,
                            })))
                        }
                    })
                    .collect();

                Ok(gen_eqs(cache, eqs?.into_iter(), env1, env2))
            }
        }
        // See [^eq-empty-containers]
        (ValueContentRef::Array(container1), ValueContentRef::Array(container2))
            if container1.is_empty() && container2.is_empty() =>
        {
            Ok(EqResult::Bool(true))
        }
        (
            ValueContentRef::Array(Container::Alloc(array_data1)),
            ValueContentRef::Array(Container::Alloc(array_data2)),
        ) if array_data1.array.len() == array_data2.array.len() => {
            // Equalities are tested in reverse order, but that shouldn't matter. If it
            // does, just do `eqs.rev()`

            // We should apply all contracts here, otherwise we risk having wrong values, think
            // record contracts with default values, wrapped terms, etc.

            let mut eqs = array_data1
                .iter_with_pending_contracts(value1.pos_idx().to_inherited())
                .map(|elt| elt.closurize(cache, env1.clone()))
                .collect::<Vec<_>>()
                .into_iter()
                .zip(
                    array_data2
                        .iter_with_pending_contracts(value2.pos_idx().to_inherited())
                        .map(|elt| elt.closurize(cache, env2.clone())),
                )
                .collect::<Vec<_>>();

            match eqs.pop() {
                None => Ok(EqResult::Bool(true)),
                Some((v1, v2)) => {
                    let eqs = eqs
                        .into_iter()
                        .map(|(v1, v2)| (v1.into(), v2.into()))
                        .collect::<Vec<(Closure, Closure)>>();

                    Ok(EqResult::Eqs(v1, v2, eqs))
                }
            }
        }
        // Function-like terms and foreign ids can't be compared together.
        (ValueContentRef::ForeignId(_), ValueContentRef::ForeignId(_))
        | (ValueContentRef::CustomContract(_), ValueContentRef::CustomContract(_))
        | (ValueContentRef::Term(Term::Fun(..)), ValueContentRef::Term(Term::Fun(..))) => {
            Err(Box::new(EvalErrorKind::IncomparableValues {
                eq_pos: pos_op,
                left: value1,
                right: value2,
            }))
        }
        (_, _) => Ok(EqResult::Bool(false)),
    }
}

/// Eta-expands a unary operator into a (lazy) function.
///
/// Regex-based primitive operations are evaluated to a function that captures the compiled regexp,
/// to avoid recompiling it at each call. [eta_expand] builds such a closure: given a primary (in
/// practice, regex) operator `%op1%`, [eta_expand] will return the expression `fun x => %op1% x`.
/// Each intermediate term is given the position index `pos_op`.
fn eta_expand(op: UnaryOp, pos_op: PosIdx) -> Term {
    let param = LocIdent::fresh();

    Term::fun(
        param,
        NickelValue::term(
            Term::op1(op, NickelValue::term(Term::Var(param), pos_op)),
            pos_op,
        ),
    )
}

trait MapValuesClosurize: Sized {
    /// Returns a HashMap from `Ident` to `Field` by:
    ///
    /// 1. Applying the pending contracts to each fields
    /// 2. Applying the provided function
    /// 3. Closurizing each result into the shared environment.
    ///
    /// Because we applied the pending contracts in 1., they are dropped in the result: all fields
    /// have an empty set of pending contracts.
    fn map_values_closurize<F, C: Cache>(
        self,
        cache: &mut C,
        env: &Environment,
        f: F,
    ) -> Result<IndexMap<LocIdent, Field>, record::MissingFieldDefError>
    where
        F: FnMut(LocIdent, NickelValue) -> NickelValue;
}

impl<Iter> MapValuesClosurize for Iter
where
    Iter: IntoIterator<Item = (LocIdent, Field)>,
{
    fn map_values_closurize<F, C: Cache>(
        self,
        cache: &mut C,
        env: &Environment,
        mut f: F,
    ) -> Result<IndexMap<LocIdent, Field>, record::MissingFieldDefError>
    where
        F: FnMut(LocIdent, NickelValue) -> NickelValue,
    {
        self.into_iter()
            .map(|(id, field)| {
                let value = field
                    .value_with_pending_contracts()
                    .map(|value| f(id, value))
                    .ok_or(record::MissingFieldDefErrorData {
                        id,
                        metadata: field.metadata.clone_inner(),
                    })?;

                let field = Field {
                    value: Some(value),
                    pending_contracts: Vec::new(),
                    ..field
                }
                .closurize(cache, env.clone());

                Ok((id, field))
            })
            .collect()
    }
}

/// Wrap a value in a [crate::term::Term::Closurize] operator with the same position index.
fn closurize_container(value: NickelValue) -> NickelValue {
    let pos_idx = value.pos_idx();
    NickelValue::term(Term::Closurize(value), pos_idx)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        cache::resolvers::DummyResolver,
        error::NullReporter,
        eval::{Environment, VmContext, cache::CacheImpl},
    };

    const NO_APP_INFO: PrimopAppInfo = PrimopAppInfo {
        call_stack_size: 0,
        pos_idx: PosIdx::NONE,
    };

    // Initialize a VM with a default context
    fn with_vm(test: impl FnOnce(VirtualMachine<'_, DummyResolver, CacheImpl>)) {
        let mut vm_ctxt = VmContext::new(DummyResolver {}, std::io::sink(), NullReporter {});
        let vm = VirtualMachine::new_empty_env(&mut vm_ctxt);
        test(vm);
    }

    #[test]
    fn ite_operation() {
        with_vm(|mut vm| {
            vm.stack.push_arg(mk_term::integer(5).into(), PosIdx::NONE);
            vm.stack.push_arg(mk_term::integer(46).into(), PosIdx::NONE);
            vm.stack.push_op1_cont(Op1ContItem {
                op: UnaryOp::IfThenElse,
                orig_pos_arg: PosIdx::NONE,
                app_info: NO_APP_INFO,
            });

            assert_eq!(
                vm.continue_op(NickelValue::bool_true().into()),
                Ok(mk_term::integer(46).into())
            );
            assert_eq!(0, vm.stack.count_args());
        });
    }

    #[test]
    fn plus_first_term_operation() {
        with_vm(|mut vm| {
            vm.stack.push_op2_first_cont(Op2FirstContItem {
                op: BinaryOp::Plus,
                app_info: NO_APP_INFO,
                arg2: Closure {
                    value: mk_term::integer(6),
                    env: Environment::new(),
                },
                orig_pos_arg1: PosIdx::NONE,
            });

            assert_eq!(
                vm.continue_op(mk_term::integer(7).into()),
                Ok(mk_term::integer(6).into())
            );
            assert_eq!(1, vm.stack.count_conts());
            assert_eq!(
                (Op2SecondContItem {
                    op: BinaryOp::Plus,
                    app_info: NO_APP_INFO,
                    arg1_evaled: mk_term::integer(7).into(),
                    orig_pos_arg1: PosIdx::NONE,
                    orig_pos_arg2: PosIdx::NONE,
                }),
                vm.stack
                    .pop_op2_second_cont()
                    .expect("Condition already checked.")
            );
        });
    }

    #[test]
    fn plus_second_term_operation() {
        with_vm(|mut vm| {
            vm.stack.push_op2_second_cont(Op2SecondContItem {
                op: BinaryOp::Plus,
                app_info: NO_APP_INFO,
                arg1_evaled: mk_term::integer(7).into(),
                orig_pos_arg1: PosIdx::NONE,
                orig_pos_arg2: PosIdx::NONE,
            });

            assert_eq!(
                vm.continue_op(mk_term::integer(6).into()),
                Ok(Closure {
                    value: mk_term::integer(13),
                    env: Environment::new()
                })
            );
        });
    }
}//! # Cross-evaluation Unique Identifier
//!
//! The CUI is a semantic hash of expressions that makes it possible for the incremental evaluator
//! to identify and match expressions that haven't changed since the last evaluation, so that their
//! result can be re-used.
//!
//! # Semantic hash of closures and open expressions
//!
//! We compute the semantic hash of an actual closure by combining the CUI of its core expression
//! with the CUI of its dependencies, hashing everything together. For example, if `CUI(x + 1) =
//! A`, `x` is bound to `0` in the environment, and `CUI(0) = B`, the semantic hash of the closure
//! `{x + 1 | x <- 0 }` is something akin to `hash((A,B))`.
//!
//! # Semantic hashing schemes
//!
//! There are a lot of possible semantic hashing schemes. By scheme, we mean a specific
//! implementation as a function from expressions to CUI/hashes. The fundamental constraint we
//! require is that if `CUI(e1) = CUI(e2)`, then `e1` and `e2` are beta-equivalent
//! (to simplify, they either both loop or evaluate to the same value: for example `1+1` and `2`
//! are beta-equivalent). Otherwise the incremental evaluator could change the result of a program
//! by replacing `e1` with a different, non-equivalent `e2` that happens to have the same CUI.
//!
//! Possible schemes are for example:
//!
//! - hashing the source expression as text
//! - hashing the AST
//! - hashing the AST modulo some rules or some normalization (for example hashing modulo
//!   alpha-conversion)
//! - unique and deterministic index based on hash-consing
//! - etc.
//!
//! The main trade-off for the scheme selection is between overhead and generality. A more general
//! semantic hash equalize more terms, or put differently, is invariant by more semantic-preserving
//! transformations. The more general, the better: the interpreter can identify more expressions
//! for reuse. However, it usually also means that the CUI is more expensive to compute, which can
//! nullify the benefits or heavily penalize cases with a lot of changes.
//!
//! The spectrum goes from the degenerate case of assigning a fresh, unique, random CUI to every
//! expression, which is fast and sound (probabilistically at least) but useless (no matching is
//! possible). The other end is an ideal scheme verifying `e1` beta-equivalent to `e2` implies
//! `CUI(e1) = CUI(e2)`. This would give the best reuse but isn't even computable because of the
//! halting problem.
//!
//! The interpreter picks so-called _thunks of interest_, which are thunks that are worth caching
//! across evaluations (as hashing, recording and persisting has a cost). This is the thunks for
//! which we compute the CUI.

use super::{
    Closure,
    cache::Cache,
    value::{
        ArrayData, Container, EnumVariantData, NickelValue, RecordData, Thunk, ValueContentRef,
    },
};

use std::hash::{DefaultHasher, Hash, Hasher};

/// A semantic hash for re-using previous computations in the incremental evaluation mode.
#[derive(Copy, Debug, PartialEq, Eq, Clone, Hash)]
pub struct SemanticHash(pub u64);

pub fn cui(_v: &NickelValue) -> SemanticHash {
    unimplemented!()
}

/// In the context of incremental evaluation, decides if an expression put in thunk should be
/// (given its content):
///
/// 1. Fetched from the incremental cache, re-using its value from the last evaluation, if
///    possible.
/// 2. Recorded as thunk of interest in the incremental cache given its content. A thunk of
///    interest is hashed and persisted as a candidate to be re-used in the next evaluation.
///
/// Such thunks are called thunks of interest. Trying to fetch a thunk or recording it for future
/// use has a cost. Ideally we'd like to strike a balance between this cost and the expected
/// return. Typically, thunk of interests should be rather costly to compute (otherwise, it might
/// be cheaper to recompute them from scratch) and have good chances of surviving successive
/// changes (e.g focusing on top-level configurations fields rather than local variables).
///
/// Currently, the decision algorithm for thunks of interest is unimplemented.
pub fn is_of_interest(_v: &NickelValue) -> bool {
    unimplemented!()
}

pub trait Register<C: Cache> {
    /// If `self` is a thunk and its content makes it a candidate for incremental caching
    /// [interesting][is_of_interest], it's registered in the incremental cache (in practice, set
    /// its [CUI][cui]).
    ///
    /// When `Self` represents a container with thunks inside ([RecordData], [ArrayData]), the
    /// _register if interesting_ operation is applied to each element.
    ///
    /// For instances where `self` might sometime not be a thunk or a thunk container, or for
    /// thunks that are not of interest, this function is a no-op.
    fn register(&self, cache: &mut C);
}

impl<C: Cache> Register<C> for NickelValue {
    fn register(&self, cache: &mut C) {
        if let Some(thunk) = self.as_thunk() {
            thunk.register(cache);
        }
    }
}

impl<C: Cache> Register<C> for Thunk {
    fn register(&self, cache: &mut C) {
        let content = &self.borrow().value;

        if is_of_interest(content) {
            cache.attach_cui(self, cui(content));
        }
    }
}

impl<C: Cache> Register<C> for RecordData {
    fn register(&self, cache: &mut C) {
        for field in self.fields.values() {
            //TODO: we cache the pure value, but not the potential pending contracts applied to this
            //value, which we probably want as well. It's not entirely clear how to do that given the
            //current implementation (there's no associated thunk), so it's left for future work.
            if let Some(value) = &field.value {
                value.register(cache)
            }
        }
    }
}

impl<C: Cache> Register<C> for ArrayData {
    fn register(&self, cache: &mut C) {
        for value in self.array.iter() {
            //TODO: as for records, we should try to cache the value with pending contracts appied.
            value.register(cache)
        }
    }
}

/// Computes the semantic hash of a closure, given an optional Cross-evaluation Unique Identifier.
///
/// If no CUI is provided, the closure to hash is a dependency of a thunk of interest, but isn't
/// itself of interest. We don't want to override the original decision of the interpreter so we
/// don't compute its CUI, but we still try a shallow, fast hash that works on simple values.
pub fn semantic_hash(closure: &Closure, cui: Option<SemanticHash>) -> Option<SemanticHash> {
    // TODO: For now, we're being stupid, and hash the whole environment. What we should do is
    // 1. Compute the free variables of each expression of interest
    // 2. Only retrieve the free variables as dependencies from the environment
    let mut hasher = DefaultHasher::new();

    for (id, thunk) in closure.env.iter_elems() {
        id.hash(&mut hasher);
        thunk.semantic_hash()?.hash(&mut hasher);
    }

    if let Some(cui) = cui {
        cui.hash(&mut hasher);
    } else {
        // If we don't have a cross-evaluation unique identifier, we still try to structurally
        // hash simple constants, that don't involve other expressions.
        closure.value.tag().hash(&mut hasher);

        match closure.value.content_ref() {
            ValueContentRef::Null => 0.hash(&mut hasher),
            ValueContentRef::Bool(b) => b.hash(&mut hasher),
            ValueContentRef::Number(n) => n.hash(&mut hasher),
            ValueContentRef::String(s) => s.hash(&mut hasher),
            ValueContentRef::EnumVariant(EnumVariantData { tag, arg: None }) => {
                tag.hash(&mut hasher)
            }
            ValueContentRef::Array(Container::Empty)
            | ValueContentRef::Record(Container::Empty) => 0.hash(&mut hasher),
            _ => return None,
        }
    }

    Some(SemanticHash(hasher.finish()))
}//! Define the main evaluation stack of the Nickel abstract machine and related operations.
//!
//! See [eval](../eval/index.html).
use super::{
    Closure,
    cache::{Cache, CacheIndex},
    value::NickelValue,
};

use crate::{
    position::PosIdx,
    term::{BinaryOp, BindingType, NAryOp, StrChunk, UnaryOp},
};

use std::{mem, ptr};

/// The different kinds of items that the stack can store. Used in [Stack] as a marker that
/// determines the shape of the data beneath each marker.
#[derive(Clone, Copy, Eq, PartialEq, Debug)]
// CAUTION: Do not change the representation `repr(u8)`
//
// While some of the code is agnostic with respect to the size and representation of the marker,
// some parts (like `Stack::top_marker`) relies on the fact that it is `repr(u8)`. Also, I can't
// see why we would need more than 255 different types of stack items. Any additional metadata for
// an item can and should be encoded in the item itself, not in the marker.
#[repr(u8)]
pub(crate) enum Marker {
    /// A pair of expressions to be checked for equality.
    Eq,
    /// An argument of an application.
    Arg,
    /// A tracked argument. Behaves the same as a standard argument, but is given directly as a
    /// cache index (thunk), such that it can be shared with other part of the program.
    ///
    /// In particular, contract arguments are tracked, in order to report the actual, evaluated
    /// offending term in case of blame.
    TrackedArg,
    /// An update index (update frame), which is a pointer to a mutable memory cell to be updated
    /// (thunk).
    UpdateIndex,
    /// The continuation of a unary primitive operation.
    Op1Cont,
    /// The continuation of a binary primitive operation before the evaluation of the first
    /// argument.
    Op2FirstCont,
    /// The continuation of a binary primitive operation after the evaluation of the first argument.
    Op2SecondCont,
    /// The continuation of a n-ary primitive operation.
    OpNCont,
    /// A string chunk.
    ///
    /// Generated by [crate::term::UnaryOp::ChunksConcat] when evaluating a string with
    /// interpolated expressions. Such strings are represented by a list of chunks to evaluate and
    /// concatenate, a chunk being either an interpolated expression or a string literal.
    ///
    /// The shared environment is stored in the `str_acc` special register of the VM.
    StrChunk,
    /// A string accumulator.
    ///
    /// When evaluating a sequence of chunks, the `str_acc` register of the VM stores the chunks
    /// evaluated and concatenated into one string up to this point. If interpolated strings are
    /// nested, we need to save this accumulator on the stack, as a new string chunk evaluation can
    /// happen in the middle of the outer accumulation.
    StrAcc,
}

impl Marker {
    /// Returns the size in bytes of the stack item corresponding to this marker, that is the
    /// `size_of::<T>()` where `T` is such that `T::marker() == self`.
    fn item_size<C: Cache>(&self) -> usize {
        match self {
            Marker::Eq => mem::size_of::<EqItem>(),
            Marker::Arg => mem::size_of::<ArgItem>(),
            Marker::TrackedArg => mem::size_of::<TrackedArgItem>(),
            Marker::UpdateIndex => mem::size_of::<UpdateIndexItem<C>>(),
            Marker::Op1Cont => mem::size_of::<Op1ContItem>(),
            Marker::Op2FirstCont => mem::size_of::<Op2FirstContItem>(),
            Marker::Op2SecondCont => mem::size_of::<Op2SecondContItem>(),
            Marker::OpNCont => mem::size_of::<OpNContItem>(),
            Marker::StrChunk => mem::size_of::<StrChunkItem>(),
            Marker::StrAcc => mem::size_of::<StrAccItem>(),
        }
    }
}

/// A marker trait for data that can be pushed onto the stack.
trait StackItem {
    fn marker() -> Marker;
}

/// The payload of a [ItemKind::Eq] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct EqItem {
    pub(crate) arg1: Closure,
    pub(crate) arg2: Closure,
}

/// The payload of a [ItemKind::Arg] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct ArgItem {
    pub(crate) arg: Closure,
    /// The original position of the argument, before it's been evaluated.
    pub(crate) orig_arg_pos: PosIdx,
}

/// The payload of a [ItemKind::TrackedArg] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct TrackedArgItem {
    pub(crate) idx: CacheIndex,
    /// The original position of the argument, before it's been evaluated.
    pub(crate) orig_arg_pos: PosIdx,
}

/// The payload of a [ItemKind::UpdateIndex] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct UpdateIndexItem<C: Cache>(C::UpdateIndex);

/// Auxiliary data for operator continuation items.
#[derive(Clone, Debug, Copy, PartialEq)]
pub(crate) struct PrimopAppInfo {
    /// The callstack size at the point just before the operator evaluation started. Used to
    /// truncate the callstack after the evaluation is done.
    pub(crate) call_stack_size: u32,
    /// The position of the primitive operation application.
    pub(crate) pos_idx: PosIdx,
}

/// The payload of a [ItemKind::Op1Cont] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Op1ContItem {
    pub(crate) op: UnaryOp,
    pub(crate) app_info: PrimopAppInfo,
    /// The original position of the argument, before it's been evaluated.
    pub(crate) orig_pos_arg: PosIdx,
}

/// The payload of a [ItemKind::Op2FirstCont] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Op2FirstContItem {
    pub(crate) op: BinaryOp,
    pub(crate) app_info: PrimopAppInfo,
    pub(crate) arg2: Closure,
    /// The original position of the first argument, before it's been evaluated.
    pub(crate) orig_pos_arg1: PosIdx,
}

/// The payload of a [ItemKind::Op2SecondCont] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Op2SecondContItem {
    pub(crate) op: BinaryOp,
    pub(crate) app_info: PrimopAppInfo,
    pub(crate) arg1_evaled: Closure,
    /// The original position of the first argument, before it's been evaluated.
    pub(crate) orig_pos_arg1: PosIdx,
    /// The original position of the second argument, before it's been evaluated.
    pub(crate) orig_pos_arg2: PosIdx,
}

/// The payload of a [ItemKind::OpNCont] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct OpNContItem {
    pub(crate) op: NAryOp,
    pub(crate) app_info: PrimopAppInfo,
    /// Arguments that have already been evaluated, together with their original position.
    pub(crate) evaluated: Vec<(Closure, PosIdx)>,
    /// The stack (thus reversed) of arguments yet to be evaluated.
    pub(crate) pending: Vec<Closure>,
    /// The original position of the argument being currently evaluated by the VM (note that this
    /// argument is neither in [Self::evaluated] nor in [Self::pending], but only in the VM state).
    pub(crate) current_pos_idx: PosIdx,
}

/// The payload of a [ItemKind::StrChunk] stack item.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct StrChunkItem {
    pub(crate) chunk: StrChunk<NickelValue>,
}

/// A string accumulator which maintains state while the virtual machine is evaluating a sequence
/// of string chunks to a single string.
#[derive(Default, PartialEq)]
pub(crate) struct StrAccItem {
    /// The current result.
    pub(crate) acc: String,
    /// The common environment of chunks.
    pub(crate) env: super::Environment,
    /// The indentation level of the chunk currently being evaluated.
    pub(crate) curr_indent: u32,
    /// The position of the original (unevaluated) expression of the chunk currently being
    /// evaluated.
    pub(crate) curr_pos: PosIdx,
}

impl StackItem for EqItem {
    fn marker() -> Marker {
        Marker::Eq
    }
}

impl StackItem for ArgItem {
    fn marker() -> Marker {
        Marker::Arg
    }
}

impl StackItem for TrackedArgItem {
    fn marker() -> Marker {
        Marker::TrackedArg
    }
}

impl<C: Cache> StackItem for UpdateIndexItem<C> {
    fn marker() -> Marker {
        Marker::UpdateIndex
    }
}

impl StackItem for Op1ContItem {
    fn marker() -> Marker {
        Marker::Op1Cont
    }
}

impl StackItem for Op2FirstContItem {
    fn marker() -> Marker {
        Marker::Op2FirstCont
    }
}

impl StackItem for Op2SecondContItem {
    fn marker() -> Marker {
        Marker::Op2SecondCont
    }
}

impl StackItem for OpNContItem {
    fn marker() -> Marker {
        Marker::OpNCont
    }
}

impl StackItem for StrChunkItem {
    fn marker() -> Marker {
        Marker::StrChunk
    }
}

impl StackItem for StrAccItem {
    fn marker() -> Marker {
        Marker::StrAcc
    }
}

impl Marker {
    #[cfg(test)]
    pub(crate) fn is_arg(self) -> bool {
        matches!(self, Marker::Arg | Marker::TrackedArg)
    }

    pub(crate) fn is_idx(self) -> bool {
        matches!(self, Marker::UpdateIndex)
    }

    pub(crate) fn is_cont(self) -> bool {
        matches!(
            self,
            Marker::Op1Cont | Marker::Op2FirstCont | Marker::Op2SecondCont | Marker::OpNCont
        )
    }
}

/// A possible continuation of interest when a sealed term is currently being evaluated.
/// See [Stack::peek_sealed_cont].
pub(crate) enum SealedCont {
    /// The next operation is an [Op2SecondContItem] where the operator is
    /// [BinaryOp::Unseal].
    Unseal,
    /// The next operation is an [Op1ContItem] where the operator is
    /// [UnaryOp::Seq].
    Seq,
    /// All other cases.
    Other,
}

/// The Nickel evaluation stack.
///
/// # Design
///
/// Because the Nickel virtual machine isn't yet a full bytecode VM (see RFC007), we currently need
/// to store non-trivial data structures on the stack. Ideally, in a bytecode VM, the kind of
/// things that can be stored on the stack is limited, and if possible they're all one-word long
/// (mostly values). This is much harder to realize in the current tree-walking interpreter.
///
/// We used to store a single type `Marker` which was a big enum of everything that could land in
/// the stack, having the stack itself just being a `Vec<Marker>`. Given how enums are represented
/// in Rust, this consumed an huge amount of space for any stack element (more than 100 bytes). As
/// mentioned above, it's really hard to bring this enum back to a reasonable size; unless we would
/// allocate a lot of things on the heap, but that would have poor performance and somehow defeats
/// the purpose of having a fast-to-access stack.
///
/// Instead, we now implement the stack as an untyped sequence of bytes (`Vec<u8>`). When we push
/// an arbitrary data structure to the stack, we first push the data, and then use the last word to
/// store an [ItemKind] marker. When popping, we look at the first word which lets us know how to
/// interpret the rest of the data at the top of the stack, and how many bytes we need to pop.
///
/// # Safety
///
/// We can entirely ignore alignment constraints, because the stack is designed with the following
/// invariant: no reference to a stack item is ever materialized directly in the backing vector.
/// For the Rust compiler, [Self::data] is just a stream of bytes. Whenever we need to pop, read or
/// write data, we always first re-materialize a stack item on the native stack (that is, in a
/// local variable), which is properly aligned.
pub(crate) struct Stack<C: Cache> {
    data: Vec<u8>,
    phantom: std::marker::PhantomData<C>,
}

impl<C: Cache> Default for Stack<C> {
    fn default() -> Self {
        Stack {
            data: Vec::default(),
            phantom: std::marker::PhantomData,
        }
    }
}

impl<C: Cache> Stack<C> {
    /// The default capacity of the eval stack. Currently one page (4KB).
    pub(crate) const DEFAULT_CAPACITY: usize = 4 * 1024;

    /// Creates a stack with a default capacity of [Self::DEFAULT_CAPACITY]. Use
    /// [Self::with_capacity] for a different value, or [Default::default] for a stack with the
    /// same default capacity as [Vec].
    pub(crate) fn new() -> Self {
        Self::with_capacity(Self::DEFAULT_CAPACITY)
    }

    /// Creates a stack with the specified capacity in bytes. Uses [Vec::with_capacity] to build
    /// the underlying vector.
    pub(crate) fn with_capacity(capacity: usize) -> Self {
        Stack {
            data: Vec::with_capacity(capacity),
            phantom: std::marker::PhantomData,
        }
    }

    /// Pushes an item of the stack. Reserve sufficient space in the backing storage, write `value`
    /// as a sequence of bytes, and finally write the corresponding marker.
    fn push<T: StackItem>(&mut self, item: T) {
        let size_value = mem::size_of::<T>();
        let kind = T::marker();

        let prev_len = self.data.len();
        self.data.reserve(size_value + mem::size_of::<Marker>());

        let storage = self.data.as_mut_ptr();

        unsafe {
            // Safety: we reserved enough space in `data` with the call to `reserve` above so that
            // the backing allocation of data contains `data_slot` and `marker_slot`.
            let data_slot = storage.add(self.data.len());
            let marker_slot = data_slot.add(size_value);

            // Safety:
            // - `data_slot` is valid for write (located in the backing allocation of a mutably
            //    borrowed Vec)
            // - `&value` is valid for read (as a local variable)
            // - `data_slot` and `value` can't overlap, as `Vec` guarantees unique ownership of its
            //   allocation in the heap, while `value` is on the stack
            ptr::copy_nonoverlapping(&item as *const T as *const u8, data_slot, size_value);
            // Safety: `marker_slot` is valid for write (located in the backing allocation of a
            // mutably borrowed Vec)
            ptr::write(marker_slot, kind as u8);

            // Safety: we've reserved enough capacity with `reserve()` above, and we wrote
            // initialized data in the new slots with `ptr::write`, so we can force a new length.
            self.data
                .set_len(prev_len + size_value + mem::size_of::<Marker>());
        }

        // Since we've copied the value onto the eval stack, we will materialize it again at pop
        // time: we mustn't run any clean up code now. In some sense, we've moved the value from
        // the Rust stack into the eval stack, albeit as a bunch of untyped bytes instead of a
        // proper `T` value.
        let _ = mem::ManuallyDrop::new(item);
    }

    /// Tries to pop an element as `T`, or returns `None` if the stack is empty or if the top
    /// marker isn't equal to `T::marker()`.
    fn pop<T: StackItem>(&mut self) -> Option<T> {
        let marker = self.top_marker()?;

        if marker != T::marker() {
            return None;
        }

        // Safety: we've checked that the stack is non-empty and that the top element is a marker
        // which is equal to `T::marker()`
        unsafe { Some(self.pop_unchecked()) }
    }

    /// Peeks the top marker of the stack, or returns `None` if the stack is empty.
    pub(crate) fn top_marker(&self) -> Option<Marker> {
        self.data
            .last()
            .map(|marker_untyped| unsafe { mem::transmute::<u8, Marker>(*marker_untyped) })
    }

    /// Returns an iterator over the markers, starting from the top of the stack and going down.
    fn markers(&self) -> StackMarkerIter<'_, C> {
        StackMarkerIter {
            stack: self,
            cursor: self.data.len(),
        }
    }

    /// Counts the number of consecutive markers satisfying `pred` from the top of the stack.
    #[cfg(test)]
    fn count(&self, mut pred: impl FnMut(Marker) -> bool) -> usize {
        self.markers().take_while(|marker| pred(*marker)).count()
    }

    /// Pops the top item as `T`, without checking that the tag correspond.
    ///
    /// # Safety
    ///
    /// The top element of the stack must of be of type `T`. That is, the stack must be non-empty
    /// and [Self::top_marker] must return `T::marker`.
    unsafe fn pop_unchecked<T: StackItem>(&mut self) -> T {
        // Safety: safety pre-conditions of this function
        let item: T = unsafe { mem::ManuallyDrop::into_inner(self.read_unchecked()) };
        // underflow: read_unchecked computes `marker_offset - item_size` which is `len -
        // marker_size - item_size` with checked operations (and panics upon failure), so we know
        // this computation can't underflow at this point
        self.data
            .truncate(self.data.len() - mem::size_of::<Marker>() - mem::size_of::<T>());

        item
    }

    /// Reads the top item as `T`, without checking that the tag correspond.
    ///
    /// # Safety
    ///
    /// The top element of the stack must of be of type `T`. That is, the stack must be non-empty
    /// and [Self::top_marker] must return `T::marker`.
    ///
    /// - Once the item is read, it is *not* removed from the stack. Thus the result must **not**
    ///   be manually dropped (e.g. [std::mem::ManuallyDrop::drop] or
    ///   [std::mem::ManuallyDrop::into_inner]).
    /// - You must not move out of any data contained in the return value.
    /// - The top value must not be materialized a second time, either using [Self::read_unchecked]
    ///   or any of the `pop` variants, while the return value of this method is still alive. That
    ///   will violate non-aliasing requirements of many heap-allocated data (this is only ok if
    ///   `T` is [Copy]).
    unsafe fn read_unchecked<T: StackItem>(&self) -> mem::ManuallyDrop<T> {
        let item_size = mem::size_of::<T>();
        let data_offset = self
            .data
            .len()
            .checked_sub(mem::size_of::<Marker>())
            .expect("unexpected missing marker on the eval stack")
            .checked_sub(item_size)
            .expect("unexpected missing item data on the eval stack after reading a marker");

        let mut item_slot = mem::MaybeUninit::<T>::uninit();

        unsafe {
            // Safety:
            // - self.data.as_ptr() is valid for read (backing allocation of a Vec)
            // - `item_slot` is valid for write (uninitialized slot on the stack)
            // - they can't alias (stack slot vs heap-allocated, mutably borrowed vector
            //   allocation)
            ptr::copy_nonoverlapping(
                self.data.as_ptr().add(data_offset),
                item_slot.as_mut_ptr() as *mut u8,
                item_size,
            );

            // Safety: we've written back a `T` value in `item_slot`, as it was originally pushed
            // onto the stack, so `item_slot` is initialized and is a valid state for `T`.
            mem::ManuallyDrop::new(item_slot.assume_init())
        }
    }

    /// Pops the top element of the stack and materializes it on the Rust stack to properly drop
    /// it, whatever element it is. Does nothing if the stack is empty.
    fn drop_top(&mut self) {
        let Some(top_marker) = self.top_marker() else {
            return;
        };

        // Safety: in each branch, we materialize an object whose type corresponds to the marker.
        unsafe {
            match top_marker {
                Marker::Eq => {
                    self.pop_unchecked::<EqItem>();
                }
                Marker::Arg => {
                    self.pop_unchecked::<ArgItem>();
                }
                Marker::TrackedArg => {
                    self.pop_unchecked::<TrackedArgItem>();
                }
                Marker::UpdateIndex => {
                    self.pop_unchecked::<UpdateIndexItem<C>>();
                }
                Marker::Op1Cont => {
                    self.pop_unchecked::<Op1ContItem>();
                }
                Marker::Op2FirstCont => {
                    self.pop_unchecked::<Op2FirstContItem>();
                }
                Marker::Op2SecondCont => {
                    self.pop_unchecked::<Op2SecondContItem>();
                }
                Marker::OpNCont => {
                    self.pop_unchecked::<OpNContItem>();
                }
                Marker::StrChunk => {
                    self.pop_unchecked::<StrChunkItem>();
                }
                Marker::StrAcc => {
                    self.pop_unchecked::<StrAccItem>();
                }
            }
        }
    }

    /// Pops (and drops) all items in the stack and resets the state of the [Cache] elements it encounters.
    pub(crate) fn unwind(&mut self, cache: &mut C) {
        while !self.data.is_empty() {
            if let Some(Marker::UpdateIndex) = self.top_marker() {
                // Safety: we checked in the outer if that the top marker is `UpdateIndex`.
                let UpdateIndexItem::<C>(mut uidx) = unsafe { self.pop_unchecked() };
                cache.reset_index_state(&mut uidx);
            } else {
                self.drop_top();
            }
        }
    }

    /// Count the number of arguments at the top of the stack.
    #[cfg(test)]
    pub(crate) fn count_args(&self) -> usize {
        self.count(Marker::is_arg)
    }

    pub(crate) fn push_arg(&mut self, arg: Closure, orig_arg_pos: PosIdx) {
        self.push(ArgItem { arg, orig_arg_pos })
    }

    pub(crate) fn push_tracked_arg(&mut self, idx: CacheIndex, orig_arg_pos: PosIdx) {
        self.push(TrackedArgItem { idx, orig_arg_pos })
    }

    pub(crate) fn push_update_index(&mut self, uidx: C::UpdateIndex) {
        self.push(UpdateIndexItem::<C>(uidx))
    }

    pub(crate) fn push_op1_cont(&mut self, op_cont: Op1ContItem) {
        self.push(op_cont);
    }

    pub(crate) fn push_op2_first_cont(&mut self, op_cont: Op2FirstContItem) {
        self.push(op_cont);
    }

    pub(crate) fn push_op2_second_cont(&mut self, op_cont: Op2SecondContItem) {
        self.push(op_cont);
    }

    pub(crate) fn push_opn_cont(&mut self, op_cont: OpNContItem) {
        self.push(op_cont);
    }

    /// Push a sequence of equalities on the stack.
    pub(crate) fn push_eqs<I>(&mut self, it: I)
    where
        I: Iterator<Item = (Closure, Closure)>,
    {
        self.data
            .reserve(it.size_hint().0 * (mem::size_of::<EqItem>() + 1));

        for (arg1, arg2) in it {
            self.push(EqItem { arg1, arg2 });
        }
    }

    /// Push a sequence of string chunks on the stack.
    pub(crate) fn push_str_chunks<I>(&mut self, it: I)
    where
        I: Iterator<Item = StrChunk<NickelValue>>,
    {
        self.data
            .reserve(it.size_hint().0 * (mem::size_of::<StrChunkItem>() + 1));

        for chunk in it {
            self.push(StrChunkItem { chunk });
        }
    }

    /// Push a string accumulator on the stack.
    pub(crate) fn push_str_acc(&mut self, str_acc: StrAccItem) {
        self.push(str_acc);
    }

    /// Try to pop an argument from the top of the stack. If `None` is returned, the top element
    /// was not an argument and the stack is left unchanged.
    ///
    /// If the argument is tracked, it is automatically converted into an owned closure.
    pub(crate) fn pop_arg(&mut self, cache: &C) -> Option<(Closure, PosIdx)> {
        let marker = self.top_marker()?;

        match marker {
            Marker::Arg => {
                let ArgItem { arg, orig_arg_pos } = unsafe { self.pop_unchecked() };
                Some((arg, orig_arg_pos))
            }
            Marker::TrackedArg => {
                let TrackedArgItem { idx, orig_arg_pos } = unsafe { self.pop_unchecked() };
                Some((cache.get(idx), orig_arg_pos))
            }
            _ => None,
        }
    }

    /// Try to pop an argument from the top of the stack and return it as an index. If `None` is
    /// returned, the top element was not an argument and the stack is left unchanged.
    ///
    /// If the argument is not tracked, it is directly returned.
    pub(crate) fn pop_arg_as_idx(&mut self, cache: &mut C) -> Option<(CacheIndex, PosIdx)> {
        let marker = self.top_marker()?;

        match marker {
            Marker::Arg => {
                let ArgItem { arg, orig_arg_pos } = unsafe { self.pop_unchecked() };
                let idx = cache.add(arg, BindingType::Normal);
                Some((idx, orig_arg_pos))
            }
            Marker::TrackedArg => {
                let TrackedArgItem { idx, orig_arg_pos } = unsafe { self.pop_unchecked() };
                Some((idx, orig_arg_pos))
            }
            _ => None,
        }
    }

    /// Try to pop an index from the top of the stack. If `None` is returned, the top element was
    /// not an index and the stack is left unchanged.
    pub(crate) fn pop_update_index(&mut self) -> Option<C::UpdateIndex> {
        self.pop::<UpdateIndexItem<C>>()
            .map(|UpdateIndexItem(uidx)| uidx)
    }

    /// Try to pop a unary operator continuation from the top of the stack. If `None` is returned, the
    /// top element was not an operator continuation and the stack is left unchanged.
    pub(crate) fn pop_op1_cont(&mut self) -> Option<Op1ContItem> {
        self.pop()
    }

    /// Try to pop a binary operator first continuation from the top of the stack. If `None` is
    /// returned, the top element was not an operator continuation and the stack is left unchanged.
    pub(crate) fn pop_op2_first_cont(&mut self) -> Option<Op2FirstContItem> {
        self.pop()
    }

    /// Try to pop a binary operator second continuation from the top of the stack. If `None` is
    /// returned, the top element was not an operator continuation and the stack is left unchanged.
    pub(crate) fn pop_op2_second_cont(&mut self) -> Option<Op2SecondContItem> {
        self.pop()
    }

    /// Try to pop a n-ary operator continuation from the top of the stack. If `None` is returned,
    /// the top element was not an operator continuation and the stack is left unchanged.
    pub(crate) fn pop_opn_cont(&mut self) -> Option<OpNContItem> {
        self.pop()
    }

    /// Helper for an ad-hoc check that needs to be performed by the evaluation of a sealed term,
    /// to decide what to do next. It used to be implemented using a generic `peek_op_cont` method,
    /// but such a generic method is now impossible to implement with the stack as a byte stream
    /// implementation. Instead, we moved this check inside stack.
    ///
    /// This method look at the first element of the stack and return a corresponding [SealedCont].
    pub(crate) fn peek_sealed_cont(&self) -> SealedCont {
        match self.top_marker() {
            Some(Marker::Op1Cont) => {
                // Safety: we checked that the marker corresponds to what we read
                let item: mem::ManuallyDrop<Op1ContItem> = unsafe { self.read_unchecked() };

                if let UnaryOp::Seq = item.op {
                    SealedCont::Seq
                } else {
                    SealedCont::Other
                }
            }
            Some(Marker::Op2SecondCont) => {
                // Safety: we checked that the marker corresponds to what we read
                let item: mem::ManuallyDrop<Op2SecondContItem> = unsafe { self.read_unchecked() };

                if let BinaryOp::Unseal = item.op {
                    SealedCont::Unseal
                } else {
                    SealedCont::Other
                }
            }
            _ => SealedCont::Other,
        }
    }

    /// Try to pop an equality from the top of the stack. If `None` is returned, the top element
    /// was not an equality and the stack is left unchanged.
    pub(crate) fn pop_eq(&mut self) -> Option<EqItem> {
        self.pop()
    }

    /// Try to pop a string chunk from the top of the stack. If `None` is returned, the top element
    /// was not a string chunk and the stack is left unchanged.
    pub(crate) fn pop_str_chunk(&mut self) -> Option<StrChunk<NickelValue>> {
        self.pop::<StrChunkItem>()
            .map(|StrChunkItem { chunk }| chunk)
    }

    /// Try to pop a string accumulator from the top of the stack. If `None` is returned, the top
    /// element was not a string chunk and the stack is left unchanged.
    pub(crate) fn pop_str_acc(&mut self) -> Option<StrAccItem> {
        self.pop()
    }

    /// Check if the top element is a [CacheIndex].
    pub(crate) fn is_top_idx(&self) -> bool {
        self.top_marker().is_some_and(Marker::is_idx)
    }

    /// Check if the top element is an operation continuation.
    pub(crate) fn is_top_cont(&self) -> bool {
        self.top_marker().is_some_and(Marker::is_cont)
    }

    /// Discard all the consecutive equality from the top of the stack. This drops the continuation
    /// of the equality being currently evaluated.
    pub(crate) fn clear_eqs(&mut self) {
        while self.pop_eq().is_some() {}
    }
}

impl<C: Cache> Drop for Stack<C> {
    fn drop(&mut self) {
        while !self.data.is_empty() {
            self.drop_top();
        }
    }
}

/// An iterator over the markers in the stack.
pub(crate) struct StackMarkerIter<'a, C: Cache> {
    stack: &'a Stack<C>,
    /// The cursor, pointing to one index past the current marker (that is, it's `stack.len()` at
    /// the beginning of iteration and `0` at the end).
    cursor: usize,
}

impl<C: Cache> Iterator for StackMarkerIter<'_, C> {
    type Item = Marker;

    fn next(&mut self) -> Option<Self::Item> {
        if self.cursor == 0 {
            return None;
        }

        // Safety: we maintain as an invariant that `cursor` either is `0`, or `cursor - 1` points
        // to a byte of the stack which is the marker of a stack item. This is true when creating
        // the iterator (cursor should point to one byte past the last element) and maintained
        // throughout iteration.
        //
        // We rely on `Marker` being `repr(u8)`.
        //
        // underflow: we checked that `cursor != 0` above, so `cursor >= 1`.
        let marker = unsafe { mem::transmute::<u8, Marker>(self.stack.data[self.cursor - 1]) };

        self.cursor = self
            .cursor
            .checked_sub(mem::size_of::<Marker>() + marker.item_size::<C>())
            .expect(
                "invalid eval stack layout during marker iteration: underflow while updating the cursor",
            );

        Some(marker)
    }
}

impl<C: Cache> std::fmt::Debug for Stack<C> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "--- STACK ---")?;
        for marker in self.markers() {
            writeln!(f, "| {marker:?}")?;
        }
        writeln!(f, "---  END  ---")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::eval::cache::CacheImpl;
    use crate::term::UnaryOp;
    use assert_matches::assert_matches;

    impl Stack<CacheImpl> {
        /// Count the number of indices at the top of the stack.
        pub fn count_thunks(&self) -> usize {
            Stack::count(self, Marker::is_idx)
        }

        /// Count the number of operation continuation at the top of the stack.
        pub fn count_conts(&self) -> usize {
            Stack::count(self, Marker::is_cont)
        }
    }

    fn some_closure() -> Closure {
        NickelValue::bool_true().into()
    }

    fn some_cont_item() -> Op1ContItem {
        Op1ContItem {
            op: UnaryOp::Typeof,
            app_info: PrimopAppInfo {
                call_stack_size: 0,
                pos_idx: PosIdx::NONE,
            },
            orig_pos_arg: PosIdx::NONE,
        }
    }

    #[test]
    fn marker_differentiates() {
        assert!(ArgItem::marker().is_arg());
        assert!(UpdateIndexItem::<CacheImpl>::marker().is_idx());
        assert!(Op1ContItem::marker().is_cont());
    }

    #[test]
    fn pushing_and_popping_args() {
        let mut s = Stack::default();
        assert_eq!(0, s.count_args());

        s.push_arg(some_closure(), PosIdx::NONE);
        s.push_arg(some_closure(), PosIdx::NONE);
        assert_eq!(2, s.count_args());
        assert_eq!(
            some_closure(),
            s.pop_arg(&CacheImpl::new()).expect("Already checked").0
        );
        assert_eq!(1, s.count_args());
    }

    #[test]
    fn pushing_and_popping_thunks() {
        let mut s = Stack::default();
        assert_eq!(0, s.count_thunks());

        let mut eval_cache = CacheImpl::new();

        let mut idx = eval_cache.add(some_closure(), BindingType::Normal);
        s.push_update_index(eval_cache.make_update_index(&mut idx).unwrap());
        idx = eval_cache.add(some_closure(), BindingType::Normal);
        s.push_update_index(eval_cache.make_update_index(&mut idx).unwrap());

        assert_eq!(2, s.count_thunks());
        s.pop_update_index().expect("Already checked");
        assert_eq!(1, s.count_thunks());
    }

    #[test]
    fn thunk_blackhole() {
        let mut eval_cache = CacheImpl::new();
        let mut idx = eval_cache.add(some_closure(), BindingType::Normal);
        let idx_upd = eval_cache.make_update_index(&mut idx);
        assert_matches!(idx_upd, Ok(..));
        assert_matches!(eval_cache.make_update_index(&mut idx), Err(..));
        eval_cache.update(some_closure(), idx_upd.unwrap());
        assert_matches!(eval_cache.make_update_index(&mut idx), Ok(..));
    }

    #[test]
    fn pushing_and_popping_conts() {
        let mut s = Stack::default();
        assert_eq!(0, s.count_conts());

        s.push_op1_cont(Op1ContItem {
            app_info: PrimopAppInfo {
                call_stack_size: 3,
                pos_idx: PosIdx::NONE,
            },
            ..some_cont_item()
        });
        s.push_op1_cont(Op1ContItem {
            app_info: PrimopAppInfo {
                call_stack_size: 4,
                pos_idx: PosIdx::NONE,
            },
            ..some_cont_item()
        });

        assert_eq!(2, s.count_conts());
        assert_eq!(
            Some(Op1ContItem {
                app_info: PrimopAppInfo {
                    call_stack_size: 4,
                    pos_idx: PosIdx::NONE
                },
                ..some_cont_item()
            }),
            s.pop_op1_cont()
        );
        assert_eq!(1, s.count_conts());
    }
}use super::{
    cache::{Cache as _, CacheImpl},
    *,
};
use crate::{
    cache::resolvers::{DummyResolver, SimpleResolver},
    error::{ImportError, ImportErrorKind, NullReporter},
    files::Files,
    label::Label,
    parser::{ErrorTolerantParserCompat, grammar, lexer},
    term::{BinaryOp, Number, StrChunk, UnaryOp, make as mk_term},
    transform::import_resolution::strict::resolve_imports,
    {mk_app, mk_fun, mk_record},
};
use assert_matches::assert_matches;

/// Generates a minimal VM context for test purpose.
fn vm_ctxt() -> VmContext<DummyResolver, CacheImpl> {
    VmContext::new(DummyResolver {}, std::io::sink(), NullReporter {})
}

/// Creates an non-unwinding machine with an empty initial environment from a VM context.
fn new_no_unwind_vm<R: ImportResolver, C: cache::Cache>(
    vm_ctxt: &mut VmContext<R, C>,
) -> NoUnwindVirtualMachine<'_, R, C> {
    NoUnwindVirtualMachine::new(VirtualMachine::new_empty_env(vm_ctxt))
}

/// Evaluate a term without import support.
fn eval_no_import(v: NickelValue) -> Result<NickelValue, EvalError> {
    new_no_unwind_vm(&mut vm_ctxt()).eval(v)
}

/// Fully evaluate a term without import support.
fn eval_full_no_import(v: NickelValue) -> Result<NickelValue, EvalError> {
    new_no_unwind_vm(&mut vm_ctxt()).eval_full(v)
}

fn parse(s: &str) -> Option<NickelValue> {
    parse_with_table(&mut PosTable::new(), s)
}

/// Same as [parse], but when we actually need the position table later.
fn parse_with_table(pos_table: &mut PosTable, s: &str) -> Option<NickelValue> {
    let id = Files::empty().add("<test>", String::from(s));

    grammar::TermParser::new()
        .parse_strict_compat(pos_table, id, lexer::Lexer::new(s))
        .map(NickelValue::without_pos)
        .map_err(|err| println!("{err:?}"))
        .ok()
}

#[test]
fn identity_over_values() {
    let num = NickelValue::number_posless(Number::try_from(45.3).unwrap());
    assert_eq!(Ok(num.clone()), eval_no_import(num));

    let boolean = NickelValue::bool_true();
    assert_eq!(Ok(boolean.clone()), eval_no_import(boolean));

    let lambda = mk_fun!("x", mk_app!(mk_term::var("x"), mk_term::var("x")));
    assert_eq!(Ok(lambda.clone()), eval_no_import(lambda));
}

#[test]
fn blame_panics() {
    let dummy = Label::dummy();
    let res = eval_no_import(mk_term::op1(
        UnaryOp::Blame,
        NickelValue::label_posless(dummy.clone()),
    ));

    if let Err(data) = res
        && let EvalErrorKind::BlameError {
            evaluated_arg: _,
            label,
        } = data.error
    {
        assert_eq!(dummy, label);
    } else {
        panic!("This evaluation should've returned a BlameError!");
    }
}

#[test]
#[should_panic]
fn lone_var_panics() {
    eval_no_import(mk_term::var("unbound")).unwrap();
}

#[test]
fn only_fun_are_applicable() {
