/// Result of the evaluation of an input.
#[derive(Debug, Clone)]
pub enum EvalResult {
    /// The input has been evaluated to a term.
    Evaluated(NickelValue),
    /// The input was a toplevel let, which has been bound in the environment.
    Bound(LocIdent),
}

impl From<NickelValue> for EvalResult {
    fn from(t: NickelValue) -> Self {
        EvalResult::Evaluated(t)
    }
}

/// Interface of the REPL backend.
pub trait Repl {
    /// Evaluate an expression, which can be either a standard term or a toplevel let-binding.
    fn eval(&mut self, exp: &str) -> Result<EvalResult, Error>;
    /// Fully evaluate an expression, which can be either a standard term or a toplevel let-binding.
    fn eval_full(&mut self, exp: &str) -> Result<EvalResult, Error>;
    /// Load the content of a file in the environment. Return the loaded record.
    fn load(&mut self, path: impl AsRef<OsStr>) -> Result<NickelValue, Error>;
    /// Typecheck an expression and return its [apparent type][crate::typecheck::ApparentType].
    fn typecheck(&mut self, exp: &str) -> Result<Type<'_>, Error>;
    /// Query the metadata of an expression.
    fn query(&mut self, path: String) -> Result<Field, Error>;
    /// Required for error reporting on the frontend.
    fn cache_mut(&mut self) -> &mut CacheHub;
    /// Required for error reporting on the frontend.
    fn pos_table(&self) -> &PosTable;
}

/// Standard implementation of the REPL backend.
pub struct ReplImpl<EC: EvalCache> {
    /// The virtual machine context.
    vm_ctxt: VmContext<CacheHub, EC>,
    /// The current eval environment, including the stdlib and top-level lets.
    eval_env: eval::Environment,
    phantom: PhantomData<EC>,
}

impl<EC: EvalCache> ReplImpl<EC> {
    /// Create a new empty REPL.
    pub fn new(trace: impl Write + 'static) -> Self {
        ReplImpl {
            eval_env: eval::Environment::new(),
            vm_ctxt: VmContext::new(CacheHub::new(), trace, NullReporter {}),
            phantom: PhantomData,
        }
    }

    /// Load and process the stdlib, and use it to populate the eval environment as well as the
    /// typing environment.
    pub fn load_stdlib(&mut self) -> Result<(), Error> {
        self.vm_ctxt
            .import_resolver
            .prepare_stdlib(&mut self.vm_ctxt.pos_table)?;
        self.eval_env = self
            .vm_ctxt
            .import_resolver
            .mk_eval_env(&mut self.vm_ctxt.cache);
        Ok(())
    }

    fn eval_(&mut self, exp: &str, eval_full: bool) -> Result<EvalResult, Error> {
        let file_id = self.vm_ctxt.import_resolver.sources.add_string(
            SourcePath::ReplInput(InputNameCounter::next()),
            String::from(exp),
        );

        let id = self
            .vm_ctxt
            .import_resolver
            .prepare_repl(&mut self.vm_ctxt.pos_table, file_id)?
            .inner();
        // unwrap(): we've just prepared the term successfully, so it must be in cache
        let term = self
            .vm_ctxt
            .import_resolver
            .terms
            .get_owned(file_id)
            .unwrap();

        if let Some(id) = id {
            let current_env = self.eval_env.clone();
            eval::env_add(
                &mut self.vm_ctxt.cache,
                &mut self.eval_env,
                id,
                term,
                current_env,
            );

            Ok(EvalResult::Bound(id))
        } else {
            let closure = Closure {
                value: term,
                env: self.eval_env.clone(),
            };

            let mut vm = VirtualMachine::new(&mut self.vm_ctxt);

            let result = if eval_full {
                vm.eval_full_closure(closure)
            } else {
                vm.eval_closure(closure)
            };

            Ok(result?.value.into())
        }
    }

    #[cfg(feature = "repl")]
    fn report(&mut self, err: impl IntoDiagnostics, color_opt: ColorOpt) {
        let mut files = self.vm_ctxt.import_resolver.sources.files().clone();
        report::report(&mut files, err, ErrorFormat::Text, color_opt);
    }
}

impl<EC: EvalCache> Repl for ReplImpl<EC> {
    fn eval(&mut self, exp: &str) -> Result<EvalResult, Error> {
        self.eval_(exp, false)
    }

    fn eval_full(&mut self, exp: &str) -> Result<EvalResult, Error> {
        self.eval_(exp, true)
    }

    fn load(&mut self, path: impl AsRef<OsStr>) -> Result<NickelValue, Error> {
        let file_id = self
            .vm_ctxt
            .import_resolver
            .sources
            .add_file(OsString::from(path.as_ref()), InputFormat::Nickel)
            .map_err(IOError::from)?;

        self.vm_ctxt
            .import_resolver
            .prepare_repl(&mut self.vm_ctxt.pos_table, file_id)?;
        let value = self
            .vm_ctxt
            .import_resolver
            .terms
            .get_owned(file_id)
            .unwrap();
        let pos = value.pos_idx();

        let Closure {
            value,
            env: new_env,
        } = {
            VirtualMachine::new(&mut self.vm_ctxt).eval_closure(Closure {
                value,
                env: self.eval_env.clone(),
            })?
        };

        self.vm_ctxt
            .import_resolver
            .add_repl_bindings(&self.vm_ctxt.pos_table, &value)
            .map_err(|NotARecord| {
                Error::eval_error(
                    Default::default(),
                    EvalErrorKind::Other(String::from("load: expected a record"), pos),
                )
            })?;

        eval::env_add_record(
            &mut self.vm_ctxt.cache,
            &mut self.eval_env,
            Closure {
                value: value.clone(),
                env: new_env,
            },
        )
        // unwrap(): if the call above succeeded, the term must be a record
        .unwrap();

        Ok(value)
    }

    fn typecheck(&mut self, exp: &str) -> Result<Type<'_>, Error> {
        let cache = &mut self.vm_ctxt.import_resolver;

        let file_id = cache.replace_string(SourcePath::ReplTypecheck, String::from(exp));
        let _ = cache.parse_to_ast(file_id)?;

        cache
            .typecheck(file_id, TypecheckMode::Walk)
            .map_err(|cache_err| {
                cache_err.unwrap_error(
                    "repl::typecheck(): expected source to be parsed before typechecking",
                )
            })?;

        Ok(cache
            .type_of(file_id)
            .map_err(|cache_err| {
                cache_err.unwrap_error(
                    "repl::typecheck(): expected source to be parsed before retrieving the type",
                )
            })?
            .inner())
    }

    fn query(&mut self, path: String) -> Result<Field, Error> {
        let mut query_path = FieldPath::parse(&mut self.vm_ctxt.import_resolver, path)?;

        // remove(): this is safe because there is no such thing as an empty field path, at least
        // when it comes out of the parser. If `path` is empty, the parser will error out. Hence,
        // `FieldPath::parse` always returns a non-empty vector.
        let target = query_path.0.remove(0);

        let file_id = self
            .vm_ctxt
            .import_resolver
            .replace_string(SourcePath::ReplQuery, target.label().into());
        self.vm_ctxt
            .import_resolver
            .prepare_repl(&mut self.vm_ctxt.pos_table, file_id)?;

        let result = {
            let value = self
                .vm_ctxt
                .import_resolver
                .terms
                .get_owned(file_id)
                .unwrap();

            VirtualMachine::new(&mut self.vm_ctxt).query_closure(
                Closure {
                    value,
                    env: self.eval_env.clone(),
                },
                &query_path,
            )?
        };

        Ok(result)
    }

    fn cache_mut(&mut self) -> &mut CacheHub {
        &mut self.vm_ctxt.import_resolver
    }

    fn pos_table(&self) -> &PosTable {
        &self.vm_ctxt.pos_table
    }
}

/// Error occurring when initializing the REPL.
pub enum InitError {
    /// Unable to load, parse or typecheck the stdlib
    Stdlib,
    /// An I/O or Linux Syscall (Errno) error happened while initializing the interactive terminal.
    ReadlineError(String),
}

pub enum InputStatus {
    Complete,
    Partial,
    Command,
    Failed(ParseErrors),
}

/// Validator enabling multiline input.
///
/// The behavior is the following:
/// - always end an input that starts with the command prefix `:`
/// - otherwise, try to parse the input. If an unexpected end of file error occurs, continue
///   the input in a new line. Otherwise, accept and end the input.
//TODO: the validator throws away the result of parsing, or the parse error, when accepting an
//input, meaning that the work is done a second time by the REPL. Validator's work could be
//reused. This overhead shouldn't be dramatic for the typical REPL input size, though.
#[cfg_attr(
    feature = "repl",
    derive(
        rustyline_derive::Completer,
        rustyline_derive::Helper,
        rustyline_derive::Hinter
    )
)]
pub struct InputParser {
    parser: grammar::ExtendedTermParser,
    /// Currently the parser expect a `FileId` to fill in location information. For this
    /// validator, this may be a dummy one, since for now location information is not used.
    file_id: FileId,
    /// The allocator used to allocate AST nodes.
    ///
    /// Note that we just grow this allocator without ever freeing it. This should be fine for a
    /// REPL. If that is a problem, it's not very hard to periodically clear it.
    alloc: AstAlloc,
}

impl InputParser {
    pub fn new(file_id: FileId) -> Self {
        InputParser {
            parser: grammar::ExtendedTermParser::new(),
            file_id,
            alloc: AstAlloc::new(),
        }
    }

    pub fn parse(&self, input: &str) -> InputStatus {
        if input.starts_with(':') || input.trim().is_empty() {
            return InputStatus::Command;
        }

        let result =
            self.parser
                .parse_tolerant(&self.alloc, self.file_id, lexer::Lexer::new(input));

        let partial = |pe| {
            matches!(
                pe,
                &ParseError::UnexpectedEOF(..) | &ParseError::UnmatchedCloseBrace(..)
            )
        };

        match result {
            Ok((_, e)) if e.no_errors() => InputStatus::Complete,
            Ok((_, e)) if e.errors.iter().all(partial) => InputStatus::Partial,
            Ok((_, e)) => InputStatus::Failed(e),
            Err(e) if partial(&e) => InputStatus::Partial,
            Err(err) => InputStatus::Failed(err.into()),
        }
    }
}

#[cfg(feature = "repl")]
impl rustyline::highlight::Highlighter for InputParser {
    fn highlight_prompt<'b, 's: 'b, 'p: 'b>(
        &'s self,
        prompt: &'p str,
        _default: bool,
    ) -> std::borrow::Cow<'b, str> {
        let style = Style::new().fg_color(Some(AnsiColor::Green.into()));
        std::borrow::Cow::Owned(format!("{style}{prompt}"))
    }
}

#[cfg(feature = "repl")]
impl rustyline::validate::Validator for InputParser {
    fn validate(&self, ctx: &mut ValidationContext<'_>) -> rustyline::Result<ValidationResult> {
        match self.parse(ctx.input()) {
            InputStatus::Partial => Ok(ValidationResult::Invalid(None)),
            _ => Ok(ValidationResult::Valid(None)),
        }
    }
}

/// Print the help message corresponding to a command, or show a list of available commands if
/// the argument is `None` or is not a command.
#[cfg(any(feature = "repl", feature = "repl-wasm"))]
pub fn print_help(out: &mut impl Write, arg: Option<&str>) -> std::io::Result<()> {
    use command::*;

    if let Some(arg) = arg {
        fn print_aliases(w: &mut impl Write, cmd: CommandType) -> std::io::Result<()> {
            let mut aliases = cmd.aliases().into_iter();

            if let Some(fst) = aliases.next() {
                write!(w, "Aliases: `{fst}`")?;
                aliases.try_for_each(|alias| write!(w, ", `{alias}`"))?;
                writeln!(w)?;
            }

            writeln!(w)
        }

        match arg.parse::<CommandType>() {
            Ok(c @ CommandType::Help) => {
                writeln!(out, ":{c} [command]")?;
                print_aliases(out, c)?;
                writeln!(
                    out,
                    "Prints a list of available commands or the help of the given command"
                )?;
            }
            Ok(c @ CommandType::Query) => {
                writeln!(out, ":{c} <field path>")?;
                print_aliases(out, c)?;
                writeln!(out, "Print the metadata attached to a field")?;
                writeln!(
                    out,
                    "<field path> is a dot-separated sequence of identifiers pointing to a field. \
                    Fields can be quoted if they contain special characters, \
                    just like in normal Nickel source code.\n"
                )?;
                writeln!(out, "Examples:")?;
                writeln!(out, "- `:{c} std.array.any`")?;
                writeln!(out, "- `:{c} mylib.contracts.\"special#chars.\".bar`")?;
            }
            Ok(c @ CommandType::Load) => {
                writeln!(out, ":{c} <file>")?;
                print_aliases(out, c)?;
                writeln!(
                    out,
                    "Evaluate the content of <file> to a record \
                    and add its fields to the environment."
                )?;
                writeln!(
                    out,
                    "Fail if the content of <file> doesn't evaluate to a record."
                )?;
            }
            Ok(c @ CommandType::Typecheck) => {
                writeln!(out, ":{c} <expression>")?;
                print_aliases(out, c)?;
                writeln!(
                    out,
                    "Typecheck the given expression and print its top-level type"
                )?;
            }
            Ok(c @ CommandType::Print) => {
                writeln!(out, ":{c} <expression>")?;
                print_aliases(out, c)?;
                writeln!(out, "Evaluate and print <expression> recursively")?;
            }
            Ok(c @ CommandType::Exit) => {
                writeln!(out, ":{c}")?;
                print_aliases(out, c)?;
                writeln!(out, "Exit the REPL session")?;
            }
            Err(UnknownCommandError {}) => {
                writeln!(out, "Unknown command `{arg}`.")?;
                writeln!(
                    out,
                    "Available commands: ? {}",
                    CommandType::all().join(" ")
                )?;
            }
        };

        Ok(())
    } else {
        writeln!(out, "Available commands: help query load typecheck exit")
    }
}//! Rendering of the results of a metadata query.
use serde::Serialize;

use crate::{
    eval::value::{Container, NickelValue, ValueContentRef},
    identifier::{Ident, LocIdent},
    pretty::PrettyPrintCap,
    term::{
        MergePriority, Term,
        record::{Field, FieldMetadata},
    },
};

use std::{io, io::Write};

/// The maximum width for pretty-printing default values. Beyond this limit, the content is cut and
/// an ellipsis is appended.
const TERM_MAX_WIDTH: usize = 80;

/// A query printer. The implementation may differ depending on the activation of markdown
/// support.
pub trait QueryPrinter {
    /// Print a metadata attribute.
    fn write_metadata(&self, out: &mut impl Write, attr: &str, value: &str) -> io::Result<()>;
    /// Print the documentation attribute.
    fn write_doc(&self, out: &mut impl Write, content: &str) -> io::Result<()>;
    /// Print the list of fields of a record.
    fn write_fields<I>(&self, out: &mut impl Write, fields: I) -> io::Result<()>
    where
        I: Iterator<Item = Ident>;
}

#[cfg(feature = "markdown")]
pub struct MarkdownRenderer {
    skin: termimad::MadSkin,
}

pub struct SimpleRenderer {}

/// Helper to render the result of the `query` sub-command without markdown support.
impl QueryPrinter for SimpleRenderer {
    fn write_metadata(&self, out: &mut impl Write, attr: &str, value: &str) -> io::Result<()> {
        writeln!(out, "* {attr}: {value}")
    }

    fn write_doc(&self, out: &mut impl Write, content: &str) -> io::Result<()> {
        if content.find('\n').is_none() {
            self.write_metadata(out, "documentation", content)
        } else {
            writeln!(out, "* documentation\n")?;
            writeln!(out, "{content}")
        }
    }

    fn write_fields<I>(&self, out: &mut impl Write, fields: I) -> io::Result<()>
    where
        I: Iterator<Item = Ident>,
    {
        writeln!(out, "Available fields:")?;

        for field in fields {
            writeln!(out, " - {field}")?;
        }

        Ok(())
    }
}

#[cfg(feature = "markdown")]
impl MarkdownRenderer {
    pub fn new() -> Self {
        MarkdownRenderer {
            skin: termimad::MadSkin::default(),
        }
    }
}

#[cfg(feature = "markdown")]
impl Default for MarkdownRenderer {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(feature = "markdown")]
fn termimad_to_io(err: termimad::Error) -> io::Error {
    match err {
        termimad::Error::IO(err) => err,
        // Not an IO error per se, but creating a new error type and changing the signatures of the
        // query printer functions just for this variant that is specific to the termimad backend
        // doesn't seem to worth it.
        termimad::Error::InsufficientWidth(err) => io::Error::other(format!("{err}")),
    }
}

/// Helper to render the result of the `query` sub-command with markdown support on the
/// terminal.
#[cfg(feature = "markdown")]
impl QueryPrinter for MarkdownRenderer {
    fn write_metadata(&self, out: &mut impl Write, attr: &str, value: &str) -> io::Result<()> {
        use minimad::*;
        use termimad::*;

        let mut expander = OwningTemplateExpander::new();
        let template = TextTemplate::from("* **${attr}**: *${value}*");

        expander.set("attr", attr);
        expander.set("value", value);
        let text = expander.expand(&template);
        let (width, _) = terminal_size();
        let fmt_text = FmtText::from_text(&self.skin, text, Some(width as usize));
        write!(out, "{fmt_text}")
    }

    fn write_doc(&self, out: &mut impl Write, content: &str) -> io::Result<()> {
        if content.find('\n').is_none() {
            self.skin
                .write_text_on(out, &format!("* **documentation**: {content}"))
                .map_err(termimad_to_io)
        } else {
            self.skin
                .write_text_on(out, "* **documentation**\n\n")
                .map_err(termimad_to_io)?;
            self.skin
                .write_text_on(out, content)
                .map_err(termimad_to_io)
        }
    }

    fn write_fields<I>(&self, out: &mut impl Write, fields: I) -> io::Result<()>
    where
        I: Iterator<Item = Ident>,
    {
        use minimad::*;
        use termimad::*;

        let (width, _) = terminal_size();
        let mut expander = OwningTemplateExpander::new();
        let template = TextTemplate::from("* ${field}");

        self.skin
            .write_text_on(out, "## Available fields")
            .map_err(termimad_to_io)?;

        for field in fields {
            expander.set("field", field.to_string());
            let text = expander.expand(&template);
            let fmt_text = FmtText::from_text(&self.skin, text, Some(width as usize));
            write!(out, "{fmt_text}")?;
        }

        Ok(())
    }
}

/// Represent which metadata attributes are requested by a query.
#[derive(Clone, Copy, Eq, PartialEq, Serialize)]
pub struct Attributes {
    pub doc: bool,
    pub contract: bool,
    pub typ: bool,
    pub default: bool,
    pub value: bool,
}

// By default, show all available metadata.
impl Default for Attributes {
    fn default() -> Self {
        Attributes {
            doc: true,
            contract: true,
            typ: true,
            default: true,
            value: true,
        }
    }
}

/// Render the result of a metadata query, automatically selecting an adapted query printer at
/// compile time.
///
/// Return `true` if some metadata were found (according to the selected attributes) and printed,
/// and `false` otherwise.
pub fn write_query_result(
    out: &mut impl Write,
    field: &Field,
    selected_attrs: Attributes,
) -> io::Result<bool> {
    #[cfg(feature = "markdown")]
    let renderer = MarkdownRenderer::new();

    #[cfg(not(feature = "markdown"))]
    let renderer = SimpleRenderer {};

    render_query_result(out, field, selected_attrs, &renderer)
}

/// Render the result of a metadata query.
///
/// Return `true` if some metadata were found (according to the selected attributes) and printed,
/// and `false` otherwise.
fn render_query_result<R: QueryPrinter>(
    out: &mut impl Write,
    field: &Field,
    selected_attrs: Attributes,
    renderer: &R,
) -> io::Result<bool> {
    // Print a list the fields of a term if it is a record, or do nothing otherwise.
    fn write_fields<R: QueryPrinter>(
        out: &mut impl Write,
        renderer: &R,
        value: &NickelValue,
    ) -> io::Result<()> {
        writeln!(out)?;

        match value.content_ref() {
            ValueContentRef::Record(Container::Alloc(record)) if !record.fields.is_empty() => {
                let mut fields: Vec<_> = record.fields.keys().collect();
                fields.sort();
                renderer.write_fields(out, fields.into_iter().map(LocIdent::ident))
            }
            ValueContentRef::Term(Term::RecRecord(data)) if !data.record.fields.is_empty() => {
                let mut fields: Vec<_> = data.record.fields.keys().map(LocIdent::ident).collect();
                fields.extend(data.includes.iter().map(|incl| incl.ident.ident()));
                fields.sort();

                let dynamic = Ident::from("<dynamic>");
                fields.extend(data.dyn_fields.iter().map(|_| dynamic));

                renderer.write_fields(out, fields.into_iter())
            }
            ValueContentRef::Record(..) | ValueContentRef::Term(Term::RecRecord(..)) => {
                renderer.write_metadata(out, "value", "{}")
            }
            _ => Ok(()),
        }
    }

    let mut found = false;
    let metadata = &field.metadata;

    if selected_attrs.contract
        && let Some(m) = metadata.as_ref()
        && !m.annotation.contracts.is_empty()
    {
        let ctrs: Vec<String> = m
            .annotation
            .contracts
            .iter()
            // We use the original user-written type stored in the label. Using
            // `ctr.typ` instead is unreadable most of the time, as it can have been
            // altered by closurizations or other run-time rewriting
            .map(|ctr| ctr.label.typ.to_string())
            .collect();
        renderer.write_metadata(out, "contract", &ctrs.join(","))?;
        found = true;
    }

    if selected_attrs.typ
        && let Some(m) = metadata.as_ref()
        && m.annotation.typ.is_some()
    {
        renderer.write_metadata(
            out,
            "type",
            &m.annotation
                .typ
                .as_ref()
                .unwrap()
                // We use the original type here, as well.
                .label
                .typ
                .to_string(),
        )?;
        found = true;
    }

    match (field.metadata.as_ref(), &field.value) {
        (
            Some(FieldMetadata {
                priority: MergePriority::Bottom,
                ..
            }),
            Some(t),
        ) if selected_attrs.default => {
            renderer.write_metadata(out, "default", &t.pretty_print_cap(TERM_MAX_WIDTH))?;
            found = true;
        }
        (
            Some(FieldMetadata {
                priority: MergePriority::Numeral(n),
                ..
            }),
            Some(t),
        ) if selected_attrs.value => {
            renderer.write_metadata(out, "priority", &format!("{n}"))?;
            renderer.write_metadata(out, "value", &t.pretty_print_cap(TERM_MAX_WIDTH))?;
            found = true;
        }
        _ => (),
    }

    match metadata.doc() {
        Some(s) if selected_attrs.doc => {
            renderer.write_doc(out, s)?;
            found = true;
        }
        _ => (),
    }

    match &field.value {
        Some(value) if selected_attrs.value => write_fields(out, renderer, value)?,
        _ => (),
    };

    Ok(found)
}//! Native terminal implementation of a REPL frontend using rustyline.
use std::path::PathBuf;

use super::{command::Command, *};

use crate::{
    error::report::ColorOpt,
    eval::{cache::CacheImpl, value::ValueContentRef},
};

use anstyle::Style;
use rustyline::{Config, EditMode, Editor, error::ReadlineError};

/// The config of rustyline's editor.
pub fn config(color_opt: ColorOpt) -> Config {
    Config::builder()
        .history_ignore_space(true)
        .edit_mode(EditMode::Emacs)
        .color_mode(color_mode_from_opt(color_opt))
        .auto_add_history(true)
        .build()
}

fn color_mode_from_opt(c: ColorOpt) -> rustyline::config::ColorMode {
    use rustyline::config::ColorMode;
    match c {
        colorchoice::ColorChoice::Always => ColorMode::Forced,
        colorchoice::ColorChoice::AlwaysAnsi => ColorMode::Enabled,
        colorchoice::ColorChoice::Auto => ColorMode::Enabled,
        colorchoice::ColorChoice::Never => ColorMode::Disabled,
    }
}

/// Main loop of the REPL.
pub fn repl(histfile: Option<PathBuf>, color_opt: ColorOpt) -> Result<(), InitError> {
    let mut repl = ReplImpl::<CacheImpl>::new(std::io::stderr());

    match repl.load_stdlib() {
        Ok(()) => (),
        Err(err) => {
            repl.report(err, color_opt);
            return Err(InitError::Stdlib);
        }
    }

    let validator = InputParser::new(
        repl.cache_mut()
            .replace_string(SourcePath::ReplInput(0), String::new()),
    );

    let mut editor = Editor::with_config(config(color_opt))
        .map_err(|readline_err| InitError::ReadlineError(format!("{readline_err}")))?;
    if let Some(histfile) = histfile.as_ref() {
        let _ = editor.load_history(histfile);
    }
    editor.set_helper(Some(validator));

    let result = loop {
        let line = editor.readline("nickel> ");
        let mut stdout = std::io::stdout();

        match line {
            Ok(line) if line.trim().is_empty() => (),
            Ok(line) if line.starts_with(':') => {
                let cmd = line.chars().skip(1).collect::<String>().parse::<Command>();
                let result = match cmd {
                    Ok(Command::Load(path)) => repl.load(&path).map(|term| match term.content_ref() {
                        ValueContentRef::Record(container) => {
                            println!(
                                "Loaded {} symbol(s) in the environment.",
                                container.len()
                            )
                        }
                        ValueContentRef::Term(Term::RecRecord(data)) => {
                            if !data.dyn_fields.is_empty() {
                                println!(
                                    "Warning: loading dynamic fields is currently not supported. \
                                    {} symbols ignored",
                                    data.dyn_fields.len()
                                );
                            }

                            if !data.includes.is_empty() {
                                println!(
                                    "Warning: loading record with `include` expressions is currently not supported. \
                                    {} symbols ignored",
                                    data.includes.len()
                                );
                            }

                            println!(
                                "Loaded {} symbol(s) in the environment.",
                                data.record.fields.len()
                            )
                        }
                        _ => (),
                    }),
                    Ok(Command::Typecheck(exp)) => {
                        repl.typecheck(&exp).map(|typ| println!("Ok: {typ}"))
                    }
                    Ok(Command::Query(path)) => repl.query(path).map(|field| {
                        query_print::write_query_result(
                            &mut stdout,
                            &field,
                            query_print::Attributes::default(),
                        )
                        .unwrap();
                    }),
                    Ok(Command::Print(exp)) => {
                        match repl.eval_full(&exp) {
                            Ok(EvalResult::Evaluated(rt)) => println!("{rt}"),
                            Ok(EvalResult::Bound(_)) => (),
                            Err(err) => repl.report(err, color_opt),
                        };
                        Ok(())
                    }
                    Ok(Command::Help(arg)) => {
                        print_help(&mut std::io::stdout(), arg.as_deref()).unwrap();
                        Ok(())
                    }
                    Ok(Command::Exit) => {
                        println!("{}Exiting", Style::new().bold());
                        break Ok(());
                    }
                    Err(err) => Err(Error::from(err)),
                };

                if let Err(err) = result {
                    repl.report(err, color_opt);
                } else {
                    println!();
                }
            }
            Ok(line) => {
                match repl.eval_full(&line) {
                    Ok(EvalResult::Evaluated(rt)) => println!("{rt}\n"),
                    Ok(EvalResult::Bound(_)) => (),
                    Err(err) => repl.report(err, color_opt),
                };
            }
            Err(ReadlineError::Eof) => {
                println!("{}Ctrl+D. Exiting", Style::new().bold());
                break Ok(());
            }
            Err(ReadlineError::Interrupted) => (),
            Err(err) => {
                if let Some(histfile) = histfile.as_ref() {
                    let _ = editor.save_history(histfile);
                }
                repl.report(Error::IOError(IOError(format!("{err}"))), color_opt);
            }
        }
    };

    if let Some(histfile) = histfile.as_ref() {
        let _ = editor.save_history(histfile);
    }
    result
}//! Simple, UI-agnostic interface to the REPL. Take string inputs and return string outputs.
//! The output may contain ANSI escape codes.
use super::{command::Command, *};
use crate::{
    error::Error,
    serialize::{self, ExportFormat},
};
use std::io::Cursor;

/// Add a failure mode to usual errors for features that are not supported by all REPLs (for
/// example, the `:load` command in the WASM frontend).
#[allow(
    clippy::large_enum_variant,
    reason = "the large variant is probably more common"
)]
pub enum InputError {
    NickelError(Error),
    Other(String),
}

/// The successful result of the evaluation of an input.
pub enum InputResult {
    /// The input succeeded with associated error message.
    Success(String),
    /// The input was blank.
    Blank,
    /// The input is incomplete.
    Partial,
}

impl From<Error> for InputError {
    fn from(error: Error) -> InputError {
        InputError::NickelError(error)
    }
}

/// Return a new instance of an REPL with the standard library loaded.
pub fn init<EC: EvalCache>(trace: impl Write + 'static) -> Result<ReplImpl<EC>, Error> {
    let mut repl = ReplImpl::new(trace);
    repl.load_stdlib()?;
    Ok(repl)
}

/// Evaluate an input.
pub fn input<R: Repl>(repl: &mut R, line: &str) -> Result<InputResult, InputError> {
    if line.trim().is_empty() {
        Ok(InputResult::Blank)
    } else if line.starts_with(':') {
        let cmd = line.chars().skip(1).collect::<String>().parse::<Command>();
        match cmd {
            Ok(Command::Load(_)) => Err(InputError::Other(String::from(
                ":load is not enabled on this REPL.",
            ))),
            Ok(Command::Typecheck(exp)) => repl
                .typecheck(&exp)
                .map(|typ| InputResult::Success(format!("Ok: {typ}")))
                .map_err(InputError::from),
            Ok(Command::Query(path)) => repl
                .query(path)
                .map(|t| {
                    let mut buffer = Cursor::new(Vec::<u8>::new());
                    query_print::write_query_result(
                        &mut buffer,
                        &t,
                        query_print::Attributes::default(),
                    )
                    .unwrap();
                    InputResult::Success(String::from_utf8(buffer.into_inner()).unwrap())
                })
                .map_err(InputError::from),
            Ok(Command::Print(exp)) => repl
                .eval_full(&exp)
                .map(|res| match res {
                    EvalResult::Evaluated(rt) => InputResult::Success(format!("{rt}\n")),
                    EvalResult::Bound(_) => InputResult::Blank,
                })
                .map_err(InputError::from),
            Ok(Command::Help(arg)) => {
                let mut buffer = Cursor::new(Vec::<u8>::new());
                print_help(&mut buffer, arg.as_deref()).unwrap();
                Ok(InputResult::Success(
                    String::from_utf8(buffer.into_inner()).unwrap(),
                ))
            }
            Ok(Command::Exit) => Ok(InputResult::Success(String::from("Exiting"))),
            Err(err) => Err(InputError::from(Error::from(err))),
        }
    } else {
        repl.eval_full(line)
            .map(|eval_res| match eval_res {
                EvalResult::Evaluated(rt) => InputResult::Success(format!("{rt}\n")),
                EvalResult::Bound(_) => InputResult::Success(String::new()),
            })
            .map_err(InputError::from)
    }
}

/// Evaluate an input and serialize the result.
pub fn serialize<R: Repl>(
    repl: &mut R,
    format: ExportFormat,
    input: &str,
) -> Result<InputResult, InputError> {
    repl.eval_full(input)
        .and_then(|eval_res| match eval_res {
            EvalResult::Evaluated(t) => serialize::to_string(format, &t)
                .map(InputResult::Success)
                .map_err(|error| error.with_pos_table(repl.pos_table().clone()).into()),
            EvalResult::Bound(_) => Ok(InputResult::Success(String::new())),
        })
        .map_err(InputError::from)
}//! Web assembly interface to the REPL.
use super::simple_frontend::{InputError, InputResult, input, serialize};
use super::{Repl, ReplImpl};
use crate::cache::CacheHub;
use crate::error::IntoDiagnostics;
use crate::eval::cache::CacheImpl;
use crate::files::{FileId, Files};
use crate::serialize::ExportFormat;
use codespan_reporting::{
    diagnostic::{Diagnostic, Label, LabelStyle, Severity},
    term::termcolor::Ansi,
};
use serde::Serialize;
use serde_repr::Serialize_repr;
use std::convert::TryInto;
use std::io::Cursor;
use wasm_bindgen::prelude::*;

/// Return codes of the WASM REPL.
///
/// wasm-bindgen doesn't support exporting arbitrary enumeration. Thus we have to encode these
/// enums as structures with a tag and values. The values that are actually set depend on the
/// tag.
#[wasm_bindgen]
#[derive(Clone, Copy, Eq, PartialEq)]
pub enum WasmResultTag {
    Success = 0,
    Blank = 1,
    Partial = 2,
    Error = 3,
}

/// Severity of an error diagnostic. WASM wrapper for the corresponding codespan type.
#[derive(Serialize_repr, Clone, Copy, Eq, PartialEq)]
#[repr(u8)]
pub enum WasmErrorSeverity {
    Bug = 5,
    /// An error.
    Error = 4,
    /// A warning.
    Warning = 3,
    /// A note.
    Note = 2,
    /// A help message.
    Help = 1,
}

impl From<Severity> for WasmErrorSeverity {
    fn from(s: Severity) -> WasmErrorSeverity {
        match s {
            Severity::Bug => WasmErrorSeverity::Bug,
            Severity::Error => WasmErrorSeverity::Error,
            Severity::Warning => WasmErrorSeverity::Warning,
            Severity::Note => WasmErrorSeverity::Note,
            Severity::Help => WasmErrorSeverity::Help,
        }
    }
}

/// Style of an error label. WASM wrapper for the corresponding codespan type.
#[derive(Serialize_repr, Clone, Copy, Eq, PartialEq)]
#[repr(u8)]
pub enum WasmErrorLabelStyle {
    Primary = 0,
    Secondary = 1,
}

impl From<LabelStyle> for WasmErrorLabelStyle {
    fn from(label_style: LabelStyle) -> WasmErrorLabelStyle {
        match label_style {
            LabelStyle::Primary => WasmErrorLabelStyle::Primary,
            LabelStyle::Secondary => WasmErrorLabelStyle::Secondary,
        }
    }
}

/// A serializable error diagnostic. WASM wrapper for the corresponding codespan type.
#[derive(Serialize)]
pub struct WasmErrorDiagnostic {
    pub severity: WasmErrorSeverity,
    msg: String,
    notes: Vec<String>,
    labels: Vec<WasmErrorLabel>,
}

impl WasmErrorDiagnostic {
    fn from_codespan(files: &Files, diag: Diagnostic<FileId>) -> Self {
        WasmErrorDiagnostic {
            severity: diag.severity.into(),
            msg: diag.message,
            notes: diag.notes,
            labels: diag
                .labels
                .into_iter()
                .map(|label| WasmErrorLabel::from_codespan(files, label))
                .collect(),
        }
    }
}

/// A serializable error label. WASM wrapper for the corresponding codespan type.
#[derive(Serialize)]
pub struct WasmErrorLabel {
    msg: String,
    pub style: WasmErrorLabelStyle,
    pub line_start: usize,
    pub col_start: usize,
    pub line_end: usize,
    pub col_end: usize,
}

impl WasmErrorLabel {
    fn from_codespan(files: &Files, label: Label<FileId>) -> Self {
        let start_loc = files.location(label.file_id, label.range.start as u32);
        let end_loc = files.location(label.file_id, label.range.end as u32);

        let (line_start, col_start, line_end, col_end) = match (start_loc, end_loc) {
            (Ok(start_loc), Ok(end_loc)) => (
                start_loc.line.to_usize(),
                start_loc.column.to_usize(),
                end_loc.line.to_usize(),
                end_loc.column.to_usize(),
            ),
            (Ok(loc), _) | (_, Ok(loc)) => (
                loc.line.to_usize(),
                loc.column.to_usize(),
                loc.line.to_usize(),
                loc.column.to_usize(),
            ),
            _ => (0, 0, 0, 0),
        };

        WasmErrorLabel {
            msg: label.message,
            style: label.style.into(),
            line_start,
            col_start,
            line_end,
            col_end,
        }
    }
}

/// WASM wrapper for the result type of the initialization of the REPL.
#[wasm_bindgen]
pub struct WasmInitResult {
    msg: String,
    pub tag: WasmResultTag,
    state: ReplState,
}

#[wasm_bindgen]
impl WasmInitResult {
    #[wasm_bindgen(getter)]
    pub fn msg(&self) -> String {
        self.msg.clone()
    }

    pub fn repl(self) -> ReplState {
        self.state
    }

    /// Make a `WasmInitResult` result from an `InputError`.
    fn error(mut state: ReplState, error: InputError) -> Self {
        WasmInitResult {
            msg: err_to_string(state.0.cache_mut(), error),
            tag: WasmResultTag::Error,
            state,
        }
    }
}

/// WASM wrapper for the result type of an execution of the REPL.
#[wasm_bindgen]
pub struct WasmInputResult {
    msg: String,
    pub tag: WasmResultTag,
    errors: JsValue,
}

#[wasm_bindgen]
impl WasmInputResult {
    #[wasm_bindgen(getter)]
    pub fn msg(&self) -> String {
        self.msg.clone()
    }

    #[wasm_bindgen(getter)]
    pub fn errors(&self) -> JsValue {
        self.errors.clone()
    }

    /// Make a `WasmInputResult` from an `InputError`.
    fn error(cache: &mut CacheHub, error: InputError) -> Self {
        let (msg, errors) = match error {
            InputError::NickelError(err) => {
                let mut files = cache.sources.files().clone();
                let diagnostics = err.into_diagnostics(&mut files);

                let msg = diags_to_string(&files, &diagnostics);
                let errors: Vec<WasmErrorDiagnostic> = diagnostics
                    .into_iter()
                    .map(|diag| WasmErrorDiagnostic::from_codespan(cache.sources.files(), diag))
                    .collect();
                (msg, errors)
            }
            InputError::Other(err) => (err, Vec::new()),
        };

        WasmInputResult {
            msg,
            tag: WasmResultTag::Error,
            errors: serde_wasm_bindgen::to_value(&errors).unwrap(),
        }
    }

    /// Generate a serializable empty list.
    fn empty_errors() -> JsValue {
        serde_wasm_bindgen::to_value(&Vec::<WasmErrorDiagnostic>::new()).unwrap()
    }
}

impl From<InputResult> for WasmInputResult {
    fn from(ir: InputResult) -> Self {
        match ir {
            InputResult::Success(msg) => WasmInputResult {
                msg,
                tag: WasmResultTag::Success,
                errors: WasmInputResult::empty_errors(),
            },
            InputResult::Blank => WasmInputResult {
                msg: String::new(),
                tag: WasmResultTag::Blank,
                errors: WasmInputResult::empty_errors(),
            },
            InputResult::Partial => WasmInputResult {
                msg: String::new(),
                tag: WasmResultTag::Partial,
                errors: WasmInputResult::empty_errors(),
            },
        }
    }
}

/// WASM-compatible wrapper around `ReplImpl`.
#[wasm_bindgen]
pub struct ReplState(ReplImpl<CacheImpl>);

/// WASM-compatible wrapper around `serialize::ExportFormat`.
#[wasm_bindgen]
pub enum WasmExportFormat {
    Text = "text",
    Json = "json",
    Yaml = "yaml",
    Toml = "toml",
}

pub type ExportFormaParseError = ();

impl TryInto<ExportFormat> for WasmExportFormat {
    type Error = ExportFormaParseError;

    fn try_into(self) -> Result<ExportFormat, ExportFormaParseError> {
        match self {
            WasmExportFormat::Text => Ok(ExportFormat::Text),
            WasmExportFormat::Json => Ok(ExportFormat::Json),
            WasmExportFormat::Yaml => Ok(ExportFormat::Yaml),
            WasmExportFormat::Toml => Ok(ExportFormat::Toml),
            _ => Err(()),
        }
    }
}

/// A `Write` implementor that calls a callback whenever it gets written to.
struct CallbackWriter {
    callback: Option<js_sys::Function>,
    buf: Vec<u8>,
}

impl CallbackWriter {
    fn new(callback: Option<js_sys::Function>) -> Self {
        Self {
            callback,
            buf: Vec::new(),
        }
    }
}

impl std::io::Write for CallbackWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.buf.extend_from_slice(buf);
        if buf.contains(&b'\n') {
            self.flush()?;
        }
        Ok(buf.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        if let Some(callback) = &self.callback {
            let js_string = JsValue::from_str(String::from_utf8_lossy(&self.buf).trim());
            callback
                .call1(&JsValue::NULL, &js_string)
                .map_err(|e| std::io::Error::other(format!("{e:?}")))?;
        }
        self.buf.clear();
        Ok(())
    }
}

/// Render error diagnostics as a string.
pub fn diags_to_string(files: &Files, diags: &[Diagnostic<FileId>]) -> String {
    let mut buffer = Ansi::new(Cursor::new(Vec::new()));
    let config = codespan_reporting::term::Config::default();

    diags
        .iter()
        .try_for_each(|d| {
            codespan_reporting::term::emit_to_write_style(&mut buffer, &config, files, d)
        })
        .unwrap();

    String::from_utf8(buffer.into_inner().into_inner()).unwrap()
}

/// Render an error as a string (similar to [`diags_to_string`](./meth.diags_to_string.html)).
pub fn err_to_string(cache: &CacheHub, error: InputError) -> String {
    match error {
        InputError::NickelError(nickel_err) => {
            let mut files = cache.sources.files().clone();
            let diags = nickel_err.into_diagnostics(&mut files);
            diags_to_string(&files, &diags)
        }
        InputError::Other(msg) => msg,
    }
}

/// Return a new instance of the WASM REPL, with the standard library loaded.
#[wasm_bindgen]
pub fn repl_init(trace_callback: Option<js_sys::Function>) -> WasmInitResult {
    let trace = CallbackWriter::new(trace_callback);
    let mut repl = ReplImpl::new(trace);
    match repl.load_stdlib() {
        Ok(()) => WasmInitResult {
            msg: String::new(),
            tag: WasmResultTag::Success,
            state: ReplState(repl),
        },
        Err(err) => WasmInitResult::error(ReplState(repl), err.into()),
    }
}

/// Evaluate an input in the WASM REPL.
#[wasm_bindgen]
pub fn repl_input(state: &mut ReplState, line: &str) -> WasmInputResult {
    input(&mut state.0, line)
        .map(WasmInputResult::from)
        .unwrap_or_else(|err| WasmInputResult::error(state.0.cache_mut(), err))
}

/// Evaluate an input in the WASM REPL and serialize it.
#[wasm_bindgen]
pub fn repl_serialize(
    state: &mut ReplState,
    format: WasmExportFormat,
    line: &str,
) -> WasmInputResult {
    serialize(&mut state.0, format.try_into().unwrap_or_default(), line)
        .map(WasmInputResult::from)
        .unwrap_or_else(|err| WasmInputResult::error(state.0.cache_mut(), err))
}//! Serialization of an evaluated program to various data format.
use crate::{
    error::{ExportErrorKind, PointedExportErrorData},
    eval::value::{ArrayData, Container, EnumVariantData, NickelValue, ValueContentRef},
    identifier::{Ident, LocIdent},
    metrics,
    term::{IndexMap, Number, TypeAnnotation, record::RecordData},
};

use serde::{
    de::{Deserialize, Deserializer},
    ser::{Serialize, SerializeMap, SerializeSeq, Serializer},
};

use malachite::base::{
    num::{
        basic::floats::PrimitiveFloat,
        conversion::traits::{IsInteger, RoundingFrom},
    },
    rounding_modes::RoundingMode,
};
use once_cell::sync::Lazy;

use std::{fmt, io};

pub mod yaml;

/// Available export formats.
#[derive(Copy, Clone, Eq, PartialEq, Debug, Default)]
#[cfg_attr(feature = "clap", derive(clap::ValueEnum))]
pub enum ExportFormat {
    /// Evaluate a Nickel expression to a string and write that text to the output
    /// Note: `raw` is a deprecated alias for `text`; prefer `text` instead.
    #[cfg_attr(feature = "clap", value(alias("raw")))]
    Text,
    #[default]
    Json,
    Yaml,
    /// Like `Yaml`, but generates multiple YAML documents in a single file,
    /// separated by `---`. The output data must be a list: each list element is
    /// converted into its own document.
    YamlDocuments,
    Toml,
}

impl fmt::Display for ExportFormat {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Text => write!(f, "text"),
            Self::Json => write!(f, "json"),
            Self::Yaml => write!(f, "yaml"),
            Self::YamlDocuments => write!(f, "yaml-documents"),
            Self::Toml => write!(f, "toml"),
        }
    }
}

/// Available metadata export formats.
#[derive(Copy, Clone, Eq, PartialEq, Debug, Default)]
#[cfg_attr(feature = "clap", derive(clap::ValueEnum))]
pub enum MetadataExportFormat {
    #[default]
    Markdown,
    Json,
    Yaml,
    Toml,
}

impl fmt::Display for MetadataExportFormat {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Markdown => write!(f, "markdown"),
            Self::Json => write!(f, "json"),
            Self::Yaml => write!(f, "yaml"),
            Self::Toml => write!(f, "toml"),
        }
    }
}

#[derive(Clone, Eq, PartialEq, Debug)]
pub struct ParseFormatError(String);

impl fmt::Display for ParseFormatError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "unsupported export format {}", self.0)
    }
}

/// Implicitly convert numbers to primitive integers when possible, and serialize an exact
/// representation. Note that `u128` and `i128` aren't supported for common configuration formats in
/// serde, so we rather pick `i64` and `u64`, even if the former couple theoretically allows for a
/// wider range of rationals to be exactly represented. We don't expect values to be that large in
/// practice anyway: using arbitrary precision rationals is directed toward not introducing rounding
/// errors when performing simple arithmetic operations over decimals numbers, mostly.
///
/// If the number doesn't fit into an `i64` or `u64`, we approximate it by the nearest `f64` and
/// serialize this value. This may incur a loss of precision, but this is expected: we can't
/// represent something like e.g. `1/3` exactly in JSON anyway.
pub fn serialize_num<S>(n: &Number, serializer: S) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    if n.is_integer() {
        if *n < 0 {
            if let Ok(n_as_integer) = i64::try_from(n) {
                return n_as_integer.serialize(serializer);
            }
        } else if let Ok(n_as_uinteger) = u64::try_from(n) {
            return n_as_uinteger.serialize(serializer);
        }
    }

    f64::rounding_from(n, RoundingMode::Nearest)
        .0
        .serialize(serializer)
}

/// Helper function to convert a serialized primitive float to a Nickel number. Return a deserialize error if
/// the floating point value is either NaN or infinity.
fn number_from_float<F: PrimitiveFloat, E: serde::de::Error>(float_value: F) -> Result<Number, E>
where
    Number: TryFrom<
            F,
            Error = malachite_q::conversion::from_primitive_float::RationalFromPrimitiveFloatError,
        >,
{
    Number::try_from_float_simplest(float_value).map_err(|_| {
        E::custom(format!(
            "couldn't convert {float_value} to a Nickel number: Nickel doesn't support NaN nor infinity"
        ))
    })
}

/// Deserialize a Nickel number. As for parsing, we convert the number from a 64bits float.
pub fn deserialize_num<'de, D>(deserializer: D) -> Result<Number, D::Error>
where
    D: Deserializer<'de>,
{
    let as_f64 = f64::deserialize(deserializer)?;
    number_from_float::<f64, D::Error>(as_f64)
}

/// Serializer for annotated values.
pub fn serialize_annotated_value<S>(
    _annot: &TypeAnnotation,
    t: &NickelValue,
    serializer: S,
) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    t.serialize(serializer)
}

/// Serializer for a record. Serialize fields in alphabetical order to get a deterministic output
pub fn serialize_record<S>(record: &RecordData, serializer: S) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    let mut entries = record
        .iter_serializable()
        .collect::<Result<Vec<_>, _>>()
        .map_err(|missing_def_err| {
            serde::ser::Error::custom(format!(
                "missing field definition for `{}`",
                missing_def_err.id
            ))
        })?;

    entries.sort_by_key(|(k, _)| *k);

    let mut map_ser = serializer.serialize_map(Some(entries.len()))?;
    for (id, t) in entries.iter() {
        map_ser.serialize_entry(&id.to_string(), &t)?
    }

    map_ser.end()
}

/// Deserialize for a record. Required to set the record attributes to default.
pub fn deserialize_record<'de, D>(deserializer: D) -> Result<RecordData, D::Error>
where
    D: Deserializer<'de>,
{
    let fields = IndexMap::<LocIdent, _>::deserialize(deserializer)?;
    Ok(RecordData::with_field_values(fields))
}

impl Serialize for NickelValue {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        match self.content_ref() {
            ValueContentRef::Null => serializer.serialize_none(),
            ValueContentRef::Bool(b) => serializer.serialize_bool(b),
            ValueContentRef::Number(n) => serialize_num(n, serializer),
            ValueContentRef::String(s) => serializer.serialize_str(s),
            ValueContentRef::EnumVariant(EnumVariantData { tag, arg: None }) => {
                serializer.serialize_str(tag.label())
            }
            ValueContentRef::EnumVariant(EnumVariantData { tag, arg: Some(_) }) => {
                Err(serde::ser::Error::custom(format!(
                    "cannot serialize enum variant `'{tag}` with non-empty argument"
                )))
            }
            ValueContentRef::Record(Container::Empty) => {
                let map_ser = serializer.serialize_map(Some(0))?;
                map_ser.end()
            }
            ValueContentRef::Record(Container::Alloc(record)) => {
                serialize_record(record, serializer)
            }
            ValueContentRef::Array(Container::Empty) => {
                let seq_ser = serializer.serialize_seq(Some(0))?;
                seq_ser.end()
            }
            ValueContentRef::Array(Container::Alloc(ArrayData { array, .. })) => {
                let mut seq_ser = serializer.serialize_seq(Some(array.len()))?;
                for elt in array.iter() {
                    seq_ser.serialize_element(elt)?
                }
                seq_ser.end()
            }
            _ => Err(serde::ser::Error::custom(format!(
                "cannot serialize non-fully evaluated terms of type {}",
                self.type_of().unwrap_or("unknown")
            ))),
        }
    }
}

// This macro generates boilerplate visitors for the various serde number types to be included in
// the `NickelValue` deserialize implementation.
macro_rules! def_number_visitor {
    ($($ty:ty),*) => {
        $(
            paste::paste! {
                fn [<visit_ $ty>]<E>(self, v: $ty) -> Result<Self::Value, E>
                where
                    E: serde::de::Error,
                {
                    Ok(NickelValue::number_posless(v))
                }
            }
        )*
    };
}

impl<'de> Deserialize<'de> for NickelValue {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        struct NickelValueVisitor;

        impl<'de> serde::de::Visitor<'de> for NickelValueVisitor {
            type Value = NickelValue;

            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("a valid Nickel value")
            }

            fn visit_bool<E>(self, v: bool) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(NickelValue::bool_value_posless(v))
            }

            def_number_visitor!(i8, u8, i16, u16, i32, u32, i64, u64, i128, u128);

            fn visit_f32<E>(self, v: f32) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                let n = number_from_float::<f32, E>(v)?;
                Ok(NickelValue::number_posless(n))
            }

            fn visit_f64<E>(self, v: f64) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                let n = number_from_float::<f64, E>(v)?;
                Ok(NickelValue::number_posless(n))
            }

            fn visit_str<E>(self, v: &str) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(NickelValue::string_posless(v))
            }

            fn visit_string<E>(self, v: String) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(NickelValue::string_posless(v))
            }

            fn visit_none<E>(self) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(NickelValue::null())
            }

            fn visit_unit<E>(self) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(NickelValue::null())
            }

            fn visit_seq<A>(self, mut seq: A) -> Result<Self::Value, A::Error>
            where
                A: serde::de::SeqAccess<'de>,
            {
                let mut elts = Vec::with_capacity(seq.size_hint().unwrap_or(0));

                while let Some(elem) = seq.next_element()? {
                    elts.push(elem);
                }

                Ok(NickelValue::array_posless(
                    elts.into_iter().collect(),
                    Vec::new(),
                ))
            }

            fn visit_map<A>(self, mut map: A) -> Result<Self::Value, A::Error>
            where
                A: serde::de::MapAccess<'de>,
            {
                let mut fields = IndexMap::with_capacity(map.size_hint().unwrap_or(0));

                while let Some((key, value)) = map.next_entry::<String, NickelValue>()? {
                    fields.insert(key.into(), value);
                }

                Ok(NickelValue::record_posless(RecordData::with_field_values(
                    fields,
                )))
            }
        }

        deserializer.deserialize_any(NickelValueVisitor)
    }
}

/// Element of a path to a specific value within a serialized term. See [NickelPointer].
#[derive(Debug, PartialEq, Clone)]
pub enum NickelPointerElem {
    Field(Ident),
    Index(usize),
}

impl fmt::Display for NickelPointerElem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            NickelPointerElem::Field(id) => write!(f, "{id}"),
            NickelPointerElem::Index(i) => write!(f, "[{i}]"),
        }
    }
}

/// A pointer to a specific value within a serialized term. The name is inspired from [JSON
/// pointer](https://datatracker.ietf.org/doc/html/rfc6901), which is an equivalent notion.
///
/// In a serialized term, there can only be constants (numbers, strings, booleans, null) and two
/// kinds of containers: records and lists. To locate a particular value within a serialized term,
/// we can use a path of field names and indices.
///
/// # Example
///
/// In the following full evaluated program:
///
/// ```nickel
/// {
///   foo = {
///     bar = ["hello", "world"],
///     other = null,
///   }
/// }
/// ```
///
/// The path to the string `"world"` is `[Field("foo"), Field("bar"), Index(1)]`. This is
/// represented (e.g. in error messages) as `foo.bar[1]`.
#[derive(Debug, PartialEq, Clone, Default)]
pub struct NickelPointer(pub Vec<NickelPointerElem>);

impl NickelPointer {
    pub fn new() -> Self {
        Self::default()
    }
}

impl fmt::Display for NickelPointer {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut it = self.0.iter();
        let Some(first) = it.next() else {
            return Ok(());
        };

        write!(f, "{first}")?;

        for elem in it {
            if let NickelPointerElem::Field(_) = elem {
                write!(f, ".{elem}")?
            } else {
                write!(f, "{elem}")?
            }
        }

        Ok(())
    }
}

/// Check that a term is serializable. Serializable terms are booleans, numbers, strings, enum,
/// arrays of serializable terms or records of serializable terms.
pub fn validate(format: ExportFormat, value: &NickelValue) -> Result<(), PointedExportErrorData> {
    // The max and min value that we accept to serialize as a number. Because Nickel uses arbitrary
    // precision rationals, we could actually support a wider range of numbers, but we expect that
    // implementations consuming the resulting JSON (or similar formats) won't necessary be able to
    // handle values that don't fit in a 64 bits float.
    static NUMBER_MIN: Lazy<Number> = Lazy::new(|| Number::try_from(f64::MIN).unwrap());
    static NUMBER_MAX: Lazy<Number> = Lazy::new(|| Number::try_from(f64::MAX).unwrap());

    // We need to build a field path locating a potential export error. One way would be to pass a
    // context storing the current path to recursive calls of `validate`. However, representing
    // this context isn't entirely trivial: using an owned `Vec` will incur a lot of copying, even
    // in the happy path (no error), because the current path needs to be shared among all sibling
    // fields of a record. What we want is persistent linked list (cheap to clone and to extend),
    // but Rust doesn't have a built-in type for that. It's not very hard to implement manually, or
    // to use an external crate, but it's still more code.
    //
    // Instead, what we do is to return the current field in case of an error. Then, recursive
    // calls to `do_validate` can unwrap the error and add their own field to the path, so that
    // when the chain of recursive calls finally returns, we have reconstructed the full path (in
    // some sense, we're encoding the list in the OS stack). Not only this doesn't require any
    // additional data structure, but we expect that it's performant, as in the happy path branch
    // prediction should be able to cancel the error code path.
    //
    // `do_validate` is the method doing the actual validation. The only reason this code is put in
    // a separate subfunction is that since we reconstruct the path bottom-up, it needs to be
    // reversed before finally returning from validate.
    fn do_validate(
        format: ExportFormat,
        value: &NickelValue,
    ) -> Result<(), PointedExportErrorData> {
        match value.content_ref() {
            // TOML doesn't support null values
            ValueContentRef::Null
                if format == ExportFormat::Json || format == ExportFormat::Yaml =>
            {
                Ok(())
            }
            ValueContentRef::Null => {
                Err(ExportErrorKind::UnsupportedNull(format, value.clone()).into())
            }
            ValueContentRef::Bool(_)
            | ValueContentRef::Record(Container::Empty)
            | ValueContentRef::Array(Container::Empty)
            | ValueContentRef::String(_) => Ok(()),
            ValueContentRef::EnumVariant(EnumVariantData { arg: None, .. }) => Ok(()),
            ValueContentRef::EnumVariant(EnumVariantData { arg: Some(_), .. }) => {
                Err(ExportErrorKind::NonSerializable(value.clone()).into())
            }
            ValueContentRef::Number(n) => {
                if *n >= *NUMBER_MIN && *n <= *NUMBER_MAX {
                    Ok(())
                } else {
                    Err(ExportErrorKind::NumberOutOfRange {
                        term: value.clone(),
                        value: n.clone(),
                    }
                    .into())
                }
            }
            ValueContentRef::Record(Container::Alloc(record)) => {
                record.iter_serializable().try_for_each(|binding| {
                    // unwrap(): terms must be fully evaluated before being validated for
                    // serialization. Otherwise, it's an internal error.
                    let (id, value) = binding.unwrap_or_else(|err| {
                        panic!(
                            "encountered field without definition `{}` \
                            during pre-serialization validation",
                            err.id
                        )
                    });

                    do_validate(format, value)
                        .map_err(|err| err.with_elem(NickelPointerElem::Field(id)))
                })?;
                Ok(())
            }
            ValueContentRef::Array(Container::Alloc(array_data)) => {
                array_data
                    .array
                    .iter()
                    .enumerate()
                    .try_for_each(|(index, val)| {
                        do_validate(format, val)
                            .map_err(|err| err.with_elem(NickelPointerElem::Index(index)))
                    })?;
                Ok(())
            }
            _ => Err(ExportErrorKind::NonSerializable(value.clone()).into()),
        }
    }

    if format == ExportFormat::Text {
        if value.as_string().is_some() {
            Ok(())
        } else {
            Err(ExportErrorKind::NotAString(value.clone()).into())
        }
    } else {
        let mut result = do_validate(format, value);

        if let Err(PointedExportErrorData { path, .. }) = &mut result {
            path.0.reverse();
        }

        result
    }
}

pub fn to_writer_metadata<W, T>(
    mut writer: W,
    format: MetadataExportFormat,
    item: &T,
) -> Result<(), PointedExportErrorData>
where
    W: io::Write,
    T: ?Sized + Serialize,
{
    // This is a near-verbatim copy of `to_writer`
    match format {
        MetadataExportFormat::Markdown => unimplemented!(),
        MetadataExportFormat::Json => serde_json::to_writer_pretty(writer, &item)
            .map_err(|err| ExportErrorKind::Other(err.to_string())),
        MetadataExportFormat::Yaml => {
            writeln!(writer, "---").map_err(|err| ExportErrorKind::Other(err.to_string()))?;
            serde_yaml::to_writer(writer, &item)
                .map_err(|err| ExportErrorKind::Other(err.to_string()))
        }
        MetadataExportFormat::Toml => toml::to_string_pretty(item)
            .map_err(|err| ExportErrorKind::Other(err.to_string()))
            .and_then(|s| {
                writer
                    .write_all(s.as_bytes())
                    .map_err(|err| ExportErrorKind::Other(err.to_string()))
            }),
    }?;

    Ok(())
}

pub fn to_writer<W>(
    mut writer: W,
    format: ExportFormat,
    value: &NickelValue,
) -> Result<(), PointedExportErrorData>
where
    W: io::Write,
{
    #[cfg(feature = "metrics")]
    let start_time = std::time::Instant::now();

    match format {
        ExportFormat::Json => serde_json::to_writer_pretty(writer, &value)
            .map_err(|err| ExportErrorKind::Other(err.to_string())),
        ExportFormat::Yaml => {
            writeln!(writer, "---").map_err(|err| ExportErrorKind::Other(err.to_string()))?;
            serde_yaml::to_writer(writer, &value)
                .map_err(|err| ExportErrorKind::Other(err.to_string()))
        }
        ExportFormat::YamlDocuments => {
            if let Some(arr) = value.as_array() {
                for value in arr.iter() {
                    writeln!(writer, "---")
                        .map_err(|err| ExportErrorKind::Other(err.to_string()))?;
                    serde_yaml::to_writer(&mut writer, value)
                        .map_err(|err| ExportErrorKind::Other(err.to_string()))?;
                }
                Ok(())
            } else {
                Err(ExportErrorKind::ExpectedArray {
                    value: value.clone(),
                })
            }
        }
        ExportFormat::Toml => toml::to_string_pretty(value)
            .map_err(|err| ExportErrorKind::Other(err.to_string()))
            .and_then(|s| {
                writer
                    .write_all(s.as_bytes())
                    .map_err(|err| ExportErrorKind::Other(err.to_string()))
            }),
        ExportFormat::Text => match value.as_string() {
            Some(s) => writer
                .write_all(s.as_bytes())
                .map_err(|err| ExportErrorKind::Other(err.to_string())),
            _ => Err(ExportErrorKind::Other(format!(
                "raw export requires a `String`, got {}",
                // unwrap(): terms must be fully evaluated before serialization,
                // and fully evaluated terms have a definite type.
                value.type_of().unwrap()
            ))),
        },
    }?;

    metrics::increment!("runtime:serialize", start_time.elapsed().as_millis() as u64);

    Ok(())
}

pub fn to_string(format: ExportFormat, rt: &NickelValue) -> Result<String, PointedExportErrorData> {
    let mut buffer: Vec<u8> = Vec::new();
    to_writer(&mut buffer, format, rt)?;

    Ok(String::from_utf8_lossy(&buffer).into_owned())
}

/// We don't use serde to deserialize toml, because
/// - this bug: <https://github.com/toml-rs/toml/issues/798>
/// - the machinery for getting spans for toml+serde is more code than
///   what we have below
///
/// Instead, we parse the toml using `toml-edit` and then convert from their
/// representation to a `NickelValue`. Using `toml-edit` here doesn't introduce
/// any new dependencies, because it's used by `toml` internally anyway.
pub mod toml_deser {
    use crate::{
        eval::value::NickelValue,
        files::FileId,
        identifier::LocIdent,
        position::{PosTable, RawSpan, TermPos},
        term::record::{RecordAttrs, RecordData},
    };
    use codespan::ByteIndex;
    use malachite::{base::num::conversion::traits::ExactFrom as _, rational::Rational};
    use nickel_lang_parser::ast::{
        Ast, AstAlloc, Node,
        record::{FieldDef, FieldMetadata, FieldPathElem},
    };
    use std::ops::Range;
    use toml_edit::Value;

    fn range_pos(range: Option<Range<usize>>, src_id: FileId) -> TermPos {
        range.map_or(TermPos::None, |span| {
            RawSpan {
                src_id,
                start: ByteIndex(span.start as u32),
                end: ByteIndex(span.end as u32),
            }
            .into()
        })
    }

    // Add `to_value` method to `toml_edit` types.
    trait ToNickelValue {
        fn to_value(&self, pos_table: &mut PosTable, src_id: FileId) -> NickelValue;

        fn to_value_with_pos(
            &self,
            pos_table: &mut PosTable,
            range: Option<Range<usize>>,
            src_id: FileId,
        ) -> NickelValue {
            let pos = range_pos(range, src_id);
            self.to_value(pos_table, src_id).with_pos(pos_table, pos)
        }
    }

    impl ToNickelValue for toml_edit::Table {
        fn to_value(&self, pos_table: &mut PosTable, src_id: FileId) -> NickelValue {
            NickelValue::record_posless(RecordData::new(
                self.iter()
                    .map(|(key, val)| {
                        (
                            LocIdent::new(key),
                            val.to_value_with_pos(pos_table, val.span(), src_id).into(),
                        )
                    })
                    .collect(),
                RecordAttrs::default(),
                None,
            ))
        }
    }

    impl ToNickelValue for toml_edit::Value {
        fn to_value(&self, pos_table: &mut PosTable, src_id: FileId) -> NickelValue {
            match self {
                Value::String(s) => NickelValue::string_posless(s.value()),
                Value::Integer(i) => NickelValue::number_posless(*i.value()),
                Value::Float(f) => NickelValue::number_posless(Rational::exact_from(*f.value())),
                Value::Boolean(b) => NickelValue::bool_value_posless(*b.value()),
                Value::Array(vs) => NickelValue::array_posless(
                    vs.iter()
                        .map(|val| val.to_value_with_pos(pos_table, val.span(), src_id))
                        .collect(),
                    Vec::new(),
                ),
                Value::InlineTable(t) => NickelValue::record_posless(RecordData::new(
                    t.iter()
                        .map(|(key, val)| {
                            (
                                LocIdent::new(key),
                                val.to_value_with_pos(pos_table, val.span(), src_id).into(),
                            )
                        })
                        .collect(),
                    RecordAttrs::default(),
                    None,
                )),
                // We don't have a proper type to represent datetimes currently, so we just parse
                // this as a string.
                Value::Datetime(dt) => NickelValue::string_posless(dt.to_string()),
            }
        }
    }

    impl ToNickelValue for toml_edit::Item {
        fn to_value(&self, pos_table: &mut PosTable, src_id: FileId) -> NickelValue {
            match self {
                toml_edit::Item::None => NickelValue::null(),
                toml_edit::Item::Table(t) => t.to_value(pos_table, src_id),
                toml_edit::Item::ArrayOfTables(ts) => NickelValue::array_posless(
                    ts.iter()
                        .map(|val| val.to_value_with_pos(pos_table, val.span(), src_id))
                        .collect(),
                    Vec::new(),
                ),
                toml_edit::Item::Value(v) => v.to_value(pos_table, src_id),
            }
        }
    }

    /// Deserialize a Nickel term with position information from a TOML source provided as a
    /// string and the file id of this source.
    pub fn from_str(
        pos_table: &mut PosTable,
        s: &str,
        file_id: FileId,
    ) -> Result<NickelValue, toml_edit::TomlError> {
        let doc: toml_edit::Document<_> = s.parse()?;
        Ok(doc
            .as_item()
            .to_value_with_pos(pos_table, doc.span(), file_id))
    }

    trait ToAst {
        fn to_ast<'ast>(&self, alloc: &'ast AstAlloc, file_id: FileId) -> Ast<'ast>;
    }

    fn to_record<'a, 'ast, T: ToAst + 'a, I: Iterator<Item = (&'a str, &'a T)>>(
        alloc: &'ast AstAlloc,
        file_id: FileId,
        iter: I,
    ) -> Node<'ast> {
        Node::Record(
            alloc.record_data(
                [],
                iter.map(|(key, val)| FieldDef {
                    path: FieldPathElem::single_ident_path(alloc, LocIdent::new(key)),
                    metadata: FieldMetadata::default(),
                    value: Some(val.to_ast(alloc, file_id)),
                    pos: TermPos::default(),
                })
                .collect::<Vec<_>>(),
                false,
            ),
        )
    }

    impl ToAst for toml_edit::Table {
        fn to_ast<'ast>(&self, alloc: &'ast AstAlloc, file_id: FileId) -> Ast<'ast> {
            Ast::from(to_record(alloc, file_id, self.iter()))
                .with_pos(range_pos(self.span(), file_id))
        }
    }

    impl ToAst for toml_edit::Item {
        fn to_ast<'ast>(&self, alloc: &'ast AstAlloc, file_id: FileId) -> Ast<'ast> {
            let pos = range_pos(self.span(), file_id);
            match self {
                toml_edit::Item::None => Ast::from(Node::Null).with_pos(pos),
                toml_edit::Item::Value(val) => val.to_ast(alloc, file_id),
                toml_edit::Item::Table(t) => t.to_ast(alloc, file_id),
                toml_edit::Item::ArrayOfTables(ts) => Ast::from(
                    alloc.array(
                        ts.iter()
                            .map(|t| t.to_ast(alloc, file_id))
                            .collect::<Vec<_>>(),
                    ),
                )
                .with_pos(pos),
            }
        }
    }

    impl ToAst for toml_edit::Value {
        fn to_ast<'ast>(&self, alloc: &'ast AstAlloc, file_id: FileId) -> Ast<'ast> {
            let pos = range_pos(self.span(), file_id);
            let node = match self {
                Value::String(s) => alloc.string(s.value()),
                Value::Integer(i) => alloc.number((*i.value()).into()),
                Value::Float(f) => alloc.number(Rational::exact_from(*f.value())),
                Value::Boolean(b) => Node::Bool(*b.value()),
                Value::Datetime(dt) => alloc.string(&dt.to_string()),
                Value::Array(array) => alloc.array(
                    array
                        .iter()
                        .map(|v| v.to_ast(alloc, file_id))
                        .collect::<Vec<_>>(),
                ),
                Value::InlineTable(t) => to_record(alloc, file_id, t.iter()),
            };
            Ast::from(node).with_pos(pos)
        }
    }

    pub fn ast_from_str<'ast>(
        alloc: &'ast AstAlloc,
        s: &str,
        file_id: FileId,
    ) -> Result<Ast<'ast>, toml_edit::TomlError> {
        let doc: toml_edit::Document<_> = s.parse()?;
        Ok(doc.as_item().to_ast(alloc, file_id))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        cache::CacheHub,
        error::NullReporter,
        eval::{VirtualMachine, VmContext, cache::CacheImpl},
        program::{Program, ProgramBuilder},
        term::{BinaryOp, make as mk_term},
    };
    use serde_json::json;
    use std::io::Cursor;

    #[track_caller]
    fn eval(s: &str) -> NickelValue {
        let mut prog: Program<CacheImpl> = ProgramBuilder::new()
            .add_source_string(s.to_owned(), "<test>")
            .with_trace(std::io::stderr())
            .build()
            .unwrap();
        prog.eval_full().expect("program eval should succeed")
    }

    #[track_caller]
    fn eval_with_ctxt(vm_ctxt: &mut VmContext<CacheHub, CacheImpl>, s: &str) -> NickelValue {
        use crate::cache::{InputFormat, SourcePath};

        let file_id = vm_ctxt
            .import_resolver
            .sources
            .add_source(
                SourcePath::Path("<test>".into(), InputFormat::Nickel),
                Cursor::new(s),
            )
            .unwrap();
        let value = vm_ctxt.prepare_eval(file_id).unwrap();

        VirtualMachine::<_, CacheImpl>::new(vm_ctxt)
            .eval_full(value)
            .unwrap()
    }

    #[track_caller]
    fn assert_json_eq<T: Serialize>(term: &str, expected: T) {
        assert_eq!(
            serde_json::to_string(&eval(term)).unwrap(),
            serde_json::to_string(&expected).unwrap()
        )
    }

    #[track_caller]
    fn assert_nickel_eq(
        vm_ctxt: &mut VmContext<CacheHub, CacheImpl>,
        value: NickelValue,
        expected: NickelValue,
    ) {
        assert!(
            VirtualMachine::<_, CacheImpl>::new_empty_env(vm_ctxt)
                .eval(mk_term::op2(BinaryOp::Eq, value, expected))
                .unwrap()
                .phys_eq(&NickelValue::bool_true())
        );
    }

    #[track_caller]
    fn assert_pass_validation(format: ExportFormat, term: &str) {
        validate(format, &eval(term)).unwrap();
    }

    #[track_caller]
    fn assert_fail_validation(format: ExportFormat, term: &str) {
        validate(format, &eval(term)).unwrap_err();
    }

    #[track_caller]
    fn assert_involutory(term: &str) {
        let mut vm_ctxt = VmContext::new(CacheHub::new(), std::io::stderr(), NullReporter {});
        let evaluated = eval_with_ctxt(&mut vm_ctxt, term);

        let from_json: NickelValue =
            serde_json::from_str(&serde_json::to_string(&evaluated).unwrap()).unwrap();
        let from_yaml: NickelValue =
            serde_yaml::from_str(&serde_yaml::to_string(&evaluated).unwrap()).unwrap();
        let from_toml: NickelValue = toml::from_str(&toml::to_string(&evaluated).unwrap()).unwrap();

        assert_nickel_eq(&mut vm_ctxt, from_json, evaluated.clone());
        assert_nickel_eq(&mut vm_ctxt, from_yaml, evaluated.clone());
        assert_nickel_eq(&mut vm_ctxt, from_toml, evaluated);
    }

    #[test]
    fn basic() {
        assert_json_eq("1 + 1", 2);

        let null: Option<()> = None;
        assert_json_eq("null", null);

        assert_json_eq("if true then false else true", false);
        assert_json_eq(r#""Hello, %{"world"}!""#, "Hello, world!");
        assert_json_eq("'foo", "foo");
    }

    #[test]
    fn arrays() {
        assert_json_eq("[]", json!([]));
        assert_json_eq("[null, (1+1), (2+2), (3+3)]", json!([null, 2, 4, 6]));
        assert_json_eq(
            r#"['a, ("b" ++ "c"), "d%{"e"}f", "g"]"#,
            json!(["a", "bc", "def", "g"]),
        );
        assert_json_eq(
            r#"std.array.fold_right (fun elt acc => [[elt]] @ acc) [] [1, 2, 3, 4]"#,
            json!([[1], [2], [3], [4]]),
        );
        assert_json_eq("[\"a\", 1, false, 'foo]", json!(["a", 1, false, "foo"]));
    }

    #[test]
    fn records() {
        assert_json_eq(
            "{a = 1, b = 2+2, c = 3, d = null}",
            json!({"a": 1, "b": 4, "c": 3, "d": null}),
        );

        assert_json_eq(
            "{a = {} & {b = {c = if true then 'richtig else 'falsch}}}",
            json!({"a": {"b": {"c": "richtig"}}}),
        );

        assert_json_eq(
            "{foo = let z = 0.5 + 0.5 in z, \
            bar = [\"str\", true || false], \
            baz = {subfoo = !false} & {subbar = 1 - 1}}",
            json!({"foo": 1, "bar": ["str", true], "baz": {"subfoo": true, "subbar": 0}}),
        );
    }

    #[test]
    fn meta_values() {
        assert_json_eq(
            "{a | default = 1, b | doc \"doc\" = 2+2, c = 3}",
            json!({"a": 1, "b": 4, "c": 3}),
        );

        assert_json_eq(
            "{a = {b | default = {}} & {b.c | default = (if true then 'faux else 'vrai)}}",
            json!({"a": {"b": {"c": "faux"}}}),
        );

        assert_json_eq(
            "{baz | default = {subfoo | default = !false} & {subbar | default = 1 - 1}}",
            json!({"baz": {"subfoo": true, "subbar": 0}}),
        );

        assert_json_eq(
            "{a = {b | default = {}} & {b.c | not_exported = false} & {b.d = true}}",
            json!({"a": {"b": {"d": true}}}),
        );
    }

    #[test]
    fn prevalidation() {
        assert_fail_validation(ExportFormat::Json, "{a = 1, b = {c = fun x => x}}");
        assert_fail_validation(
            ExportFormat::Json,
            "{foo.bar = let y = \"a\" in y, b = [[fun x => x]]}",
        );
        assert_pass_validation(ExportFormat::Json, "{foo = null}");
        assert_fail_validation(ExportFormat::Toml, "{foo = null}");
    }

    #[test]
    fn involution() {
        assert_involutory("{val = 1 + 1}");
        assert_involutory("{val = \"Some string\"}");
        assert_involutory("{val = [\"a\", 3, []]}");
        assert_involutory("{a.foo.bar = \"2\", b = false, c = [{d = \"e\"}, {d = \"f\"}]}");
    }
}//! Support for parsing YAML and converting it to Nickel.
//!
//! We use the `saphyr` crate because it looks like the best-maintained
//! option right now, and it supports reporting locations. We use their
//! lower-level API so that we can convert directly to an `Ast`
//! without passing through `saphyr`'s in-memory `Yaml` structure.
//! (Also, this lets us support recursive aliases.)

use std::{
    borrow::Cow,
    collections::{BTreeMap, HashMap, HashSet},
    convert::Infallible,
    num::NonZeroUsize,
};

use codespan::ByteIndex;
use nickel_lang_parser::traverse::{TraverseAlloc, TraverseControl};
use saphyr_parser::{BufferedInput, Parser, ScalarStyle, SpannedEventReceiver, Tag};

use crate::{
    ast::{
        self, Ast, AstAlloc,
        compat::ToMainline,
        record::{FieldMetadata, FieldPathElem},
    },
    error::ParseError,
    eval::value::{NickelValue, ValueContent, lens::TermContent},
    files::FileId,
    identifier::{Ident, LocIdent},
    position::{PosTable, RawSpan, TermPos},
    term::Number,
    traverse::Traverse,
};

fn mk_pos(file_id: Option<FileId>, start: usize, end: usize, char_index_map: &[usize]) -> TermPos {
    let start_byte = char_index_map.get(start).copied().unwrap_or(start);
    let end_byte = char_index_map.get(end).copied().unwrap_or(end);
    file_id
        .map(|src_id| {
            TermPos::Original(RawSpan {
                src_id,
                start: ByteIndex::from(start_byte as u32),
                end: ByteIndex::from(end_byte as u32),
            })
        })
        .unwrap_or_default()
}

#[derive(Clone, Debug)]
enum Node<'ast> {
    Array {
        array: Vec<Ast<'ast>>,
        pos: TermPos,
    },
    Map {
        map: Vec<ast::record::FieldDef<'ast>>,
        cur_key: Option<LocIdent>,
        pos: TermPos,
    },
    Scalar(Ast<'ast>),
}

impl<'ast> Node<'ast> {
    fn pos(&self) -> &TermPos {
        match self {
            Node::Array { pos, .. } | Node::Map { pos, .. } => pos,
            Node::Scalar(rt) => &rt.pos,
        }
    }

    fn finish(self, alloc: &'ast AstAlloc) -> Ast<'ast> {
        match self {
            Node::Array { array, pos } => Ast {
                node: alloc.array(array),
                pos,
            },
            Node::Map { map, cur_key, pos } => {
                debug_assert!(cur_key.is_none());
                Ast {
                    node: ast::Node::Record(alloc.record_data([], map, false)),
                    pos,
                }
            }
            Node::Scalar(ast) => ast,
        }
    }

    fn with_end_pos(mut self, end: ByteIndex) -> Self {
        match &mut self {
            Node::Array { pos, .. } | Node::Map { pos, .. } => {
                *pos = pos.map(|sp| RawSpan { end, ..sp });
            }
            Node::Scalar(rt) => {
                rt.pos = rt.pos.map(|sp| RawSpan { end, ..sp });
            }
        }
        self
    }
}

/// Keep track of anchors.
///
/// We turn anchor references into Nickel variable references: every node
/// with an anchor gets inserted into a big top-level `let` block, and every
/// reference to an anchor gets turned into a `Term::Var` node.
///
/// This is different from saphyr's approach, where they clone the referent
/// every time it's referenced. In addition to avoiding unnecessary clones,
/// our version supports recursive anchor references.
///
/// As an example, we turn
///
/// ```yaml
/// bar: &ref
///     - 1
///     - 2
/// baz: *ref
/// ```
///
/// into
///
/// ```nickel
/// let rec _anchor0 = [ 1, 2 ] in { bar = _anchor0, baz = _anchor0, }
/// ```
///
/// Note that we generate the reference even if it's never
/// dereferenced: if the `baz` in the example above were
/// missing, we'd generate
///
/// ```nickel
/// let rec _anchor0 = [ 1, 2 ] in { bar = _anchor0, }
/// ```
///
/// This could be changed in the future, but the current behavior is nice
/// because we can do it all in one pass.
#[derive(Default)]
struct AnchorMap<'ast> {
    map: BTreeMap<NonZeroUsize, (Ident, Ast<'ast>)>,
}

impl<'ast> AnchorMap<'ast> {
    /// Assign a unique variable name to this anchor id.
    ///
    /// This should be called when opening a container (i.e. an array or map),
    /// and before recursing into its children. That way the variable name will
    /// be available to any children that reference the parent.
    fn reserve(&mut self, anchor_id: Option<NonZeroUsize>) {
        if let Some(aid) = anchor_id {
            self.map
                .insert(aid, (Ident::fresh(), ast::Node::Null.into()));
        }
    }

    fn var(&self, anchor_id: NonZeroUsize) -> Ast<'ast> {
        ast::Node::Var(self.map[&anchor_id].0.into()).into()
    }

    /// If an `Ast` has an anchor id, replace it with a `Node::Var`.
    ///
    /// (The original `Ast` will get hoisted up to the top-level recursive let block.)
    fn anchorify(&mut self, anchor_id: Option<NonZeroUsize>, ast: Ast<'ast>) -> Ast<'ast> {
        if let Some(aid) = anchor_id {
            let (ident, slot) = self
                .map
                .entry(aid)
                .or_insert((Ident::fresh(), ast::Node::Null.into()));
            *slot = ast;
            ast::Node::Var((*ident).into()).into()
        } else {
            ast
        }
    }
}

/// Tracks the state needed for loading YAML from a stream of events and
/// building an `Ast`.
///
/// This is designed mainly as an implementor of the
/// `saphyr_parser::SpannedEventReceiver` trait. We adapt it for JSON by a
/// little shim that translates `json_scanner` events to `saphyr_parser` events.
struct Loader<'ast> {
    /// For error reporting, do we claim to be loading YAML or JSON?
    format_name: &'static str,
    alloc: &'ast AstAlloc,
    /// Keeps track of the anchors we've encountered so far.
    anchor_map: AnchorMap<'ast>,
    /// The stack of incomplete containers, and their anchor ids.
    ///
    /// The top of the stack is the container currently being filled;
    /// as we encounter new nodes, we add them to that container.
    ///
    /// There is one situation in which a non-container `Node` will
    /// be on the stack: if the document contains nothing but a single
    /// scalar.
    doc_stack: Vec<(Node<'ast>, Option<NonZeroUsize>)>,
    /// All the docs that we've already finished loading.
    docs: Vec<Ast<'ast>>,
    /// If the input came from a file, here is its id.
    file_id: Option<FileId>,
    /// Saphyr errors early when it encounters a YAML parse error, but it
    /// doesn't provide a way for the loader to exit on error. We have a few
    /// error cases that aren't caught by the yaml parser (for example, because
    /// Nickel records only allow string keys). Because there's no way to
    /// early-exit, we keep track of those errors by stashing them here.
    err: Option<ParseError>,
    /// Saphyr reports positions in char indices, so we need to convert
    /// them back to bytes. Our little JSON shim, on the other hand, reports
    /// positions in bytes directly.
    ///
    /// So, if this vector is non-empty then it's a mapping of char indices to
    /// byte indices. If it's empty, no mapping will be applied (indices will
    /// be assumed to already be bytes).
    ///
    /// (In fact, we always look up in this vec, but if the input is out-of-bounds
    /// then we fall back to returning the input index.)
    char_index_map: Vec<usize>,
}

impl<'ast> Loader<'ast> {
    fn push_node(&mut self, node: Node<'ast>, anchor_id: Option<NonZeroUsize>) {
        if let Some((parent, _)) = self.doc_stack.last_mut() {
            match parent {
                Node::Array { array, pos: _ } => {
                    let node = self
                        .anchor_map
                        .anchorify(anchor_id, node.finish(self.alloc));
                    array.push(node);
                }
                Node::Map {
                    map,
                    cur_key,
                    pos: _,
                } => {
                    if let Some(key) = cur_key.take() {
                        let node = self
                            .anchor_map
                            .anchorify(anchor_id, node.finish(self.alloc));
                        map.push(ast::record::FieldDef {
                            path: FieldPathElem::single_ident_path(self.alloc, key),
                            metadata: FieldMetadata::default(),
                            value: Some(node),
                            pos: TermPos::default(),
                        });
                    } else {
                        self.err = Some(ParseError::ExternalFormatError(
                            self.format_name.to_owned(),
                            "Nickel records only support string keys".into(),
                            node.pos().as_opt_ref().cloned(),
                        ));
                    }
                }
                Node::Scalar(_) => {
                    // The parser shouldn't allow us to get into this state.
                    debug_assert!(false, "scalars can't have children");
                }
            }
        } else {
            self.doc_stack.push((node, anchor_id));
        }
    }

    fn push_scalar_with_err(
        &mut self,
        value: &str,
        style: ScalarStyle,
        anchor_id: Option<NonZeroUsize>,
        tag: Option<&Cow<'_, Tag>>,
        pos: TermPos,
    ) -> Result<(), ParseError> {
        // Returns Ok(Some(f)) if it succeeds, Ok(None) if the argument wasn't a float, or
        // Err it it was a float that Nickel doesn't support (i.e. inf or nan).
        //
        // The motivation here is that we want an error on ".inf" instead of silently treating
        // it as a string.
        fn parse_float<'a>(
            v: &str,
            fmt: &str,
            pos: TermPos,
            alloc: &'a AstAlloc,
        ) -> Result<Option<ast::Node<'a>>, ParseError> {
            match v {
                ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" | "-.inf" | "-.Inf"
                | "-.INF" | ".nan" | ".NaN" | ".NAN" => Err(ParseError::ExternalFormatError(
                    fmt.to_owned(),
                    "Nickel numbers cannot be inf or NaN".into(),
                    pos.into_opt(),
                )),
                // `f64::from_str` will succeed on "NaN" and "inf". Since those aren't
                // valid YAML floats, we want to skip them.
                _ if v.as_bytes().iter().any(u8::is_ascii_digit) => {
                    use malachite::base::num::conversion::traits::FromSciString;
                    let n = Number::from_sci_string(v);
                    Ok(n.map(|n| alloc.number(n)))
                }
                _ => Ok(None),
            }
        }

        // Parse a YAML scalar, inferring the type from the value itself.
        fn parse<'a>(
            v: &str,
            fmt: &str,
            pos: TermPos,
            alloc: &'a AstAlloc,
        ) -> Result<ast::Node<'a>, ParseError> {
            if let Some(number) = v.strip_prefix("0x")
                && let Ok(i) = i64::from_str_radix(number, 16)
            {
                return Ok(alloc.number(i.into()));
            } else if let Some(number) = v.strip_prefix("0o")
                && let Ok(i) = i64::from_str_radix(number, 8)
            {
                return Ok(alloc.number(i.into()));
            } else if let Some(number) = v.strip_prefix('+')
                && let Ok(i) = number.parse::<i64>()
            {
                return Ok(alloc.number(i.into()));
            }
            match v {
                "~" | "null" | "Null" | "NULL" => Ok(ast::Node::Null),
                "true" | "True" | "TRUE" => Ok(ast::Node::Bool(true)),
                "false" | "False" | "FALSE" => Ok(ast::Node::Bool(false)),
                _ => {
                    if let Ok(i) = v.parse::<i64>() {
                        Ok(alloc.number(i.into()))
                    } else if let Some(f) = parse_float(v, fmt, pos, alloc)? {
                        Ok(f)
                    } else {
                        Ok(alloc.string(v))
                    }
                }
            }
        }

        let t = if style != ScalarStyle::Plain {
            // Any quoted scalar is a string.
            ast::Node::String(self.alloc.alloc_str(value))
        } else if let Some(tag) = tag.map(Cow::as_ref) {
            // TODO: once we switch to edition 2024, see if this test can be folded into the `if let`
            if tag.is_yaml_core_schema() {
                let t = match tag.suffix.as_ref() {
                    "bool" => value
                        .parse::<bool>()
                        .map(ast::Node::Bool)
                        .map_err(|_| "invalid bool scalar"),
                    "int" => value
                        .parse::<i64>()
                        .map(|i| self.alloc.number(i.into()))
                        .map_err(|_| "invalid int scalar"),
                    "float" => parse_float(value, self.format_name, pos, self.alloc)?
                        .ok_or("invalid float scalar"),
                    "null" => match value {
                        "~" | "null" => Ok(ast::Node::Null),
                        _ => Err("invalid null scalar"),
                    },
                    "str" => Ok(ast::Node::String(self.alloc.alloc_str(value))),
                    _ => Err("unknown tag"),
                };
                t.map_err(|msg| {
                    ParseError::ExternalFormatError(
                        self.format_name.to_owned(),
                        msg.into(),
                        pos.into_opt(),
                    )
                })?
            } else {
                // If it isn't a core schema tag, try to infer the type.
                parse(value, self.format_name, pos, self.alloc)?
            }
        } else {
            // If there's no tag, try to infer the type.
            parse(value, self.format_name, pos, self.alloc)?
        };

        let node = Node::Scalar(Ast { node: t, pos });
        self.push_node(node, anchor_id);
        Ok(())
    }

    fn push_scalar(
        &mut self,
        value: &str,
        style: ScalarStyle,
        anchor_id: Option<NonZeroUsize>,
        tag: Option<&Cow<'_, Tag>>,
        pos: TermPos,
    ) {
        if let Err(e) = self.push_scalar_with_err(value, style, anchor_id, tag, pos) {
            self.err = Some(e);
        }
    }

    /// If we're expecting the next item to be a map key, return somewhere to put it.
    ///
    /// The goal here is to delay parsing so that we can interpret map keys as strings as much as
    /// possible. For example, we want to parse
    ///
    /// ```yaml
    /// 1.00: foo
    /// ```
    ///
    /// as having a string key, with value "1.00". If we were to call
    /// `Scalar::parse_...` too early, it would parse the "1.00" as a number, and
    /// then lose information because it will store the number as "1" and forget
    /// that the original string was "1.00".
    ///
    /// So the idea is that you call `key_slot` to check whether the next value
    /// needs to be interpreted as a key. If so, you parse it as a string; if not,
    /// you let yaml decide how to interpret it.
    ///
    /// This only works for scalar keys: given the input
    ///
    /// ```yaml
    /// [bar, baz]: foo
    /// ```
    ///
    /// saphyr will produce a map whose key is a list (which we don't support in Nickel).
    fn key_slot(&mut self) -> Option<&mut Option<LocIdent>> {
        match self.doc_stack.last_mut() {
            Some((Node::Map { cur_key, .. }, _)) if cur_key.is_none() => Some(cur_key),
            _ => None,
        }
    }
}

impl<'input, 'ast> SpannedEventReceiver<'input> for Loader<'ast> {
    fn on_event(&mut self, ev: saphyr_parser::Event<'input>, span: saphyr_parser::Span) {
        // saphyr-parser doesn't provide a way for the loader to signal an
        // error. So we store an error in our internal state and just refuse to
        // process anything once we have one.
        if self.err.is_some() {
            return;
        }

        use saphyr_parser::Event::*;
        let pos = mk_pos(
            self.file_id,
            span.start.index(),
            span.end.index(),
            &self.char_index_map,
        );
        match ev {
            DocumentStart(_) | Nothing | StreamStart | StreamEnd => {}
            DocumentEnd => {
                let doc = match self.doc_stack.len() {
                    0 => Ast {
                        node: ast::Node::Null,
                        pos,
                    },
                    1 => self.doc_stack.pop().unwrap().0.finish(self.alloc),
                    _ => unreachable!(),
                };
                self.docs.push(doc);
            }
            Alias(id) => {
                // unwrap: saphyr uses id zero to represent no id, so it should
                // never be the payload of the Alias variant.
                let id = NonZeroUsize::new(id).unwrap();
                self.push_node(Node::Scalar(self.anchor_map.var(id)), None);
            }
            Scalar(value, style, anchor_id, tag) => {
                if let Some(key_slot) = self.key_slot() {
                    let key = LocIdent::from(value.as_ref()).with_pos(pos);
                    *key_slot = Some(key);
                } else {
                    let aid = NonZeroUsize::new(anchor_id);
                    self.push_scalar(&value, style, aid, tag.as_ref(), pos);
                }
            }
            SequenceStart(anchor_id, _tag) => {
                let anchor_id = NonZeroUsize::new(anchor_id);
                self.anchor_map.reserve(anchor_id);
                let node = Node::Array {
                    array: Vec::new(),
                    pos,
                };
                self.doc_stack.push((node, anchor_id));
            }
            MappingStart(anchor_id, _tag) => {
                let anchor_id = NonZeroUsize::new(anchor_id);
                self.anchor_map.reserve(anchor_id);
                let node = Node::Map {
                    map: Vec::new(),
                    cur_key: None,
                    pos,
                };
                self.doc_stack.push((node, anchor_id));
            }
            SequenceEnd | MappingEnd => {
                let end_idx = ByteIndex::from(span.end.index() as u32);
                let (node, anchor_id) = self.doc_stack.pop().unwrap();
                let node = node.with_end_pos(end_idx);
                self.push_node(node, anchor_id);
            }
        }
    }
}

/// Parse a YAML string and convert it to an [`Ast`].
///
/// If `file_id` is provided, the `Ast` will have its positions filled out.
pub fn load_yaml<'ast>(
    alloc: &'ast AstAlloc,
    s: &str,
    file_id: Option<FileId>,
    listify: Listify,
) -> Result<Ast<'ast>, ParseError> {
    load(alloc, s, file_id, "yaml", listify)
}

fn json_scanner_error(file_id: Option<FileId>, e: json_scanner::ParseError) -> ParseError {
    ParseError::ExternalFormatError(
        "json".to_owned(),
        e.kind.to_string(),
        file_id.map(|src_id| RawSpan {
            src_id,
            start: ByteIndex(e.byte_offset as u32),
            end: ByteIndex(e.byte_offset as u32 + 1),
        }),
    )
}

/// Parse a JSON string and convert it to an [`Ast`].
///
/// If the location is provided, the `Ast` will have its positions filled out.
pub fn load_json<'ast>(
    alloc: &'ast AstAlloc,
    s: &str,
    file_id: Option<FileId>,
) -> Result<Ast<'ast>, ParseError> {
    let mut parser = json_scanner::Parser::new(s.as_bytes());
    let mut loader = Loader {
        format_name: "json",
        file_id,
        alloc,
        anchor_map: Default::default(),
        doc_stack: Default::default(),
        docs: Default::default(),
        err: Default::default(),
        char_index_map: Vec::new(),
    };

    while let Some(ev) = parser
        .next_event()
        .map_err(|e| json_scanner_error(file_id, e))?
    {
        let span = saphyr_parser::Span {
            // We don't actually use the line/column, so set them to zero.
            start: saphyr_parser::Marker::new(ev.start, 0, 0),
            end: saphyr_parser::Marker::new(ev.end, 0, 0),
        };
        fn scalar(s: &str) -> saphyr_parser::Event<'_> {
            saphyr_parser::Event::Scalar(s.into(), ScalarStyle::Plain, 0, None)
        }

        let saphyr_ev = match ev.event {
            json_scanner::Event::BeginObject => saphyr_parser::Event::MappingStart(0, None),
            json_scanner::Event::EndObject => saphyr_parser::Event::MappingEnd,
            json_scanner::Event::BeginArray => saphyr_parser::Event::SequenceStart(0, None),
            json_scanner::Event::EndArray => saphyr_parser::Event::SequenceEnd,
            json_scanner::Event::Number(n) => scalar(n),
            json_scanner::Event::String(s) => {
                saphyr_parser::Event::Scalar(s, ScalarStyle::DoubleQuoted, 0, None)
            }
            json_scanner::Event::Boolean(true) => scalar("true"),
            json_scanner::Event::Boolean(false) => scalar("false"),
            json_scanner::Event::Null => scalar("null"),
        };

        loader.on_event(saphyr_ev, span);
    }
    loader.on_event(
        saphyr_parser::Event::DocumentEnd,
        saphyr_parser::Span::default(),
    );

    debug_assert!(loader.docs.len() <= 1);
    Ok(loader.docs.pop().unwrap_or_else(|| Ast {
        node: ast::Node::Null,
        pos: mk_pos(file_id, 0, 0, &[]),
    }))
}

/// Collects everything in `ast` that could possibly get put into an environment.
///
/// That is, everything not put in `idents` is guaranteed not to collide with
/// anything. This is specialized to JSON/YAML, so names can only appear in
/// records (and not in let bindings or functions).
fn collect_idents(ast: &Ast<'_>, idents: &mut HashSet<Ident>) {
    ast.traverse_ref(
        &mut |node: &Ast<'_>, &()| {
            if let ast::Node::Record(data) = &node.node {
                idents.extend(
                    data.field_defs
                        .iter()
                        .flat_map(|def| def.path)
                        .filter_map(|elem| elem.try_as_ident().map(|id| id.ident())),
                );
            }
            TraverseControl::<(), ()>::Continue
        },
        &(),
    );
}

/// Generates a name like `_anchor0`, but one that's guaranteed not to collide
/// with any other used identifier.
///
/// `counter` tells us which number to start searching at, and will be
/// incremented to the chosen value (so if we return `_anchor7` then `counter`
/// will be set to `7`).
fn unused_ident(all_idents: &mut HashSet<Ident>, counter: &mut u64) -> Ident {
    loop {
        let id = Ident::new(format!("_anchor{counter}"));
        if all_idents.insert(id) {
            return id;
        }
        *counter += 1;
    }
}

/// A YAML file can contain multiple documents. How should they be handled?
#[derive(Debug, PartialEq)]
pub enum Listify {
    /// If the YAML file contains multiple documents, pack them into an array.
    /// If it contains a single document, return it "bare". If it's empty,
    /// return `null`.
    Auto,
    /// Pack the documents into a list no matter what: a single document
    /// becomes a single-element list, and an empty file becomes an empty list.
    Always,
}

fn load<'ast>(
    alloc: &'ast AstAlloc,
    s: &str,
    file_id: Option<FileId>,
    format_name: &'static str,
    listify: Listify,
) -> Result<Ast<'ast>, ParseError> {
    let mut loader = Loader {
        format_name,
        file_id,
        alloc,
        anchor_map: Default::default(),
        doc_stack: Default::default(),
        docs: Default::default(),
        err: Default::default(),
        char_index_map: s.char_indices().map(|(byte_idx, _)| byte_idx).collect(),
    };
    let mut parser = Parser::new(BufferedInput::new(s.chars()));
    parser
        .load(&mut loader, true)
        .map_err(|e| ParseError::from_yaml(e, file_id))?;
    if let Some(e) = loader.err {
        return Err(e);
    }
    let mut yaml = loader.docs;

    let main_term = if listify == Listify::Always || yaml.len() > 1 {
        Ast {
            node: alloc.array(yaml),
            pos: mk_pos(file_id, 0, s.len(), &[]),
        }
    } else if yaml.is_empty() {
        Ast {
            node: ast::Node::Null,
            pos: mk_pos(file_id, 0, 0, &[]),
        }
    } else {
        // yaml.len() == 1 {
        yaml.pop().unwrap()
    };

    if loader.anchor_map.map.is_empty() {
        Ok(main_term)
    } else {
        // We generated an AST using fresh identifiers. Here we convert the
        // fresh identifiers into normal identifiers so that the resulting
        // AST will be syntactically valid when pretty-printed.
        //
        // It would be nice if we could avoid generating fresh identifiers
        // and then replacing them later. But at the time we generate the
        // identifiers, we don't yet know which identifier names are available
        // (i.e. guaranteed not to collide with anything else).
        let mut all_idents = HashSet::new();
        collect_idents(&main_term, &mut all_idents);
        for (_, value) in loader.anchor_map.map.values() {
            collect_idents(value, &mut all_idents);
        }

        let mut counter = 0;
        let renamed_bindings: HashMap<Ident, (Ident, Ast<'_>)> = loader
            .anchor_map
            .map
            .into_values()
            .map(|(id, value)| {
                let new_id = unused_ident(&mut all_idents, &mut counter);
                counter += 1;
                (id, (new_id, value))
            })
            .collect();

        fn rename_vars<'ast>(
            alloc: &'ast AstAlloc,
            ast: Ast<'ast>,
            renamed_bindings: &HashMap<Ident, (Ident, Ast<'ast>)>,
        ) -> Ast<'ast> {
            ast.traverse::<_, Infallible>(
                alloc,
                &mut |ast: Ast<'_>| match &ast.node {
                    ast::Node::Var(id) => {
                        if let Some((new_id, _)) = renamed_bindings.get(&id.ident()) {
                            Ok(ast::Node::Var((*new_id).into()).into())
                        } else {
                            Ok(ast)
                        }
                    }
                    _ => Ok(ast),
                },
                nickel_lang_parser::traverse::TraverseOrder::BottomUp,
            )
            // unwrap: the error was Infallible
            .unwrap()
        }

        let main_term = rename_vars(alloc, main_term, &renamed_bindings);
        let bindings = renamed_bindings
            .values()
            .map(|(id, value)| ast::LetBinding {
                pattern: ast::pattern::Pattern::any((*id).into()),
                metadata: Default::default(),
                value: rename_vars(alloc, value.clone(), &renamed_bindings),
            });
        // unwrap: the error was Infallible
        Ok(alloc.let_block(bindings, main_term, true).into())
    }
}

// Convert a pure-data Ast to a pure-data NickelValue.
//
// The mainline conversion creates `RecRecords`, but since they came from data we know they're just
// normal Records. This is important for std.deserialize, since it expects deserialized data to be
// evaluated.
fn ast_to_term(pos_table: &mut PosTable, ast: Ast<'_>) -> NickelValue {
    let value: NickelValue = ast.to_mainline(pos_table);
    value
        .traverse::<_, Infallible>(
            &mut |value: NickelValue| {
                let pos_idx = value.pos_idx();

                Ok(match value.content() {
                    ValueContent::Term(TermContent::RecRecord(lens)) => {
                        NickelValue::record(lens.take().record, pos_idx)
                    }
                    lens => lens.restore(),
                })
            },
            crate::traverse::TraverseOrder::BottomUp,
        )
        // unwrap: our traversal is infallible
        .unwrap()
}

/// Parse a JSON string and convert it to a [`NickelValue`].
///
/// If a location is provided, the `NickelValue` will have its positions filled out.
pub fn load_json_value(
    pos_table: &mut PosTable,
    s: &str,
    location: Option<FileId>,
) -> Result<NickelValue, ParseError> {
    let alloc = AstAlloc::new();
    Ok(ast_to_term(pos_table, load_json(&alloc, s, location)?))
}

pub fn load_yaml_value(
    pos_table: &mut PosTable,
    s: &str,
    file_id: Option<FileId>,
    listify: Listify,
) -> Result<NickelValue, ParseError> {
    let alloc = AstAlloc::new();
    Ok(ast_to_term(
        pos_table,
        load_yaml(&alloc, s, file_id, listify)?,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    // Turn a YAML string into a Nickel string, by converting to Ast
    // and pretty-printing. This is more convenient for testing than comparing Asts.
    fn yaml_to_ncl(s: &str) -> String {
        let alloc = AstAlloc::new();
        load_yaml(&alloc, s, None, Listify::Auto)
            .unwrap()
            .to_string()
    }

    #[test]
    fn basic_yaml_loading() {
        assert_eq!(&yaml_to_ncl("[1, 2]"), "[ 1, 2 ]");
        assert_eq!(&yaml_to_ncl("{a: 1, b: 2}"), "{ a = 1, b = 2 }");
        assert_eq!(&yaml_to_ncl(""), "null");

        // Multiple yaml documents get turned into a list.
        let multi_doc = r#"
1
---
2
"#;
        assert_eq!(&yaml_to_ncl(multi_doc), "[ 1, 2 ]");
    }

    #[test]
    fn yaml_refs() {
        let basic_ref = r#"
bar: &ref
    - 1
    - 2
baz: *ref
"#;
        assert_eq!(
            &yaml_to_ncl(basic_ref),
            "let rec _anchor0 = [ 1, 2 ] in { bar = _anchor0, baz = _anchor0 }"
        );

        let recursive_ref = r#"
foo: &ref
    - 1
    - bar: *ref
"#;
        assert_eq!(
            &yaml_to_ncl(recursive_ref),
            "let rec _anchor0 = [ 1, { bar = _anchor0 } ] in { foo = _anchor0 }"
        );

        let recursive_ref_with_name_collision = r#"
foo: &ref
    - 1
    - _anchor0: *ref
"#;
        assert_eq!(
            &yaml_to_ncl(recursive_ref_with_name_collision),
            "let rec _anchor1 = [ 1, { _anchor0 = _anchor1 } ] in { foo = _anchor1 }"
        );
    }
}//! A builder interface for producing Nickel records.
//!
//! Using this module, you can define Nickel records using a builder style. For example:
//!
//! ```rust
//! # use nickel_lang_core::{
//! #   eval::value::NickelValue,
//! #   term::{MergePriority, Term, make::builder::Record},
//! # };
//!
//! let b = Record::new()
//!     .field("foo")
//!     .priority(MergePriority::Bottom)
//!     .doc("foo?")
//!     .not_exported()
//!     .value(NickelValue::string_posless("foo"));
//! let t : NickelValue = b
//!     .field("bar")
//!     .value(NickelValue::number_posless(42))
//!     .into();
//! ```
//!
use indexmap::IndexMap;

use crate::{
    combine::Combine,
    eval::value::NickelValue,
    identifier::{Ident, LocIdent},
    label::Label,
    term::{
        BinaryOp, LabeledType, MergePriority, Term,
        make::op2,
        record::{self, FieldMetadata, RecordAttrs, RecordData},
    },
    typ::Type,
};

use std::rc::Rc;

type StaticPath = Vec<Ident>;

/// Typestate style tag for `Field`s that are not yet completely specified
pub struct Incomplete();

/// Typestate style tag for `Field`s that have been finalized
pub struct Complete(Option<NickelValue>);

/// A Nickel record field being constructed
#[derive(Debug)]
pub struct Field<RB> {
    record: RB,
    path: StaticPath,
    metadata: FieldMetadata,
}

impl<A> Field<A> {
    /// Attach documentation metadata to the field
    pub fn doc(self, doc: impl AsRef<str>) -> Self {
        self.some_doc(Some(doc))
    }

    /// Attach documentation metadata to the field, optionally
    pub fn some_doc(mut self, some_doc: Option<impl AsRef<str>>) -> Self {
        self.metadata.doc = some_doc.map(|d| Rc::from(d.as_ref()));
        self
    }

    /// Mark the field as optional
    pub fn optional(self) -> Self {
        self.set_optional(true)
    }

    /// Mark the field as optional or not, depending on `opt`
    pub fn set_optional(mut self, opt: bool) -> Self {
        self.metadata.opt = opt;
        self
    }

    /// Mark the field as `not_exported`
    pub fn not_exported(self) -> Self {
        self.set_not_exported(true)
    }

    /// Mark the field as `not_exported` or not, depending on the argument
    pub fn set_not_exported(mut self, not_exported: bool) -> Self {
        self.metadata.not_exported = not_exported;
        self
    }

    /// Attach a contract to the field
    pub fn contract(mut self, contract: impl Into<Type>) -> Self {
        self.metadata.annotation.contracts.push(LabeledType {
            typ: contract.into(),
            label: Default::default(),
        });
        self
    }

    /// Attach multiple contracts to the field
    pub fn contracts<I>(mut self, contracts: I) -> Self
    where
        I: IntoIterator<Item = Type>,
    {
        self.metadata
            .annotation
            .contracts
            .extend(contracts.into_iter().map(|c| LabeledType {
                typ: c,
                label: Default::default(),
            }));
        self
    }

    /// Attach a type annotation to the field
    pub fn types(mut self, t: impl Into<Type>) -> Self {
        self.metadata.annotation.typ = Some(LabeledType {
            typ: t.into(),
            label: Default::default(),
        });
        self
    }

    /// Set the field's merge priority
    pub fn priority(mut self, priority: MergePriority) -> Self {
        self.metadata.priority = priority;
        self
    }

    /// Set the field's metadata all at once
    pub fn metadata(mut self, metadata: FieldMetadata) -> Self {
        self.metadata = metadata;
        self
    }
}

impl Field<Incomplete> {
    /// Construct an incomplete [`Field`] at a given path
    pub fn path<I, It>(path: It) -> Self
    where
        I: AsRef<str>,
        It: IntoIterator<Item = I>,
    {
        Field {
            record: Incomplete(),
            path: path.into_iter().map(|e| e.as_ref().into()).collect(),
            metadata: Default::default(),
        }
    }

    /// Construct an incomplete [`Field`] with a given name
    pub fn name(name: impl AsRef<str>) -> Self {
        Self::path([name])
    }

    /// Finalize the [`Field`] without setting a value
    pub fn no_value(self) -> Field<Complete> {
        Field {
            record: Complete(None),
            path: self.path,
            metadata: self.metadata,
        }
    }

    /// Finalize the [`Field`] by setting its value
    pub fn value(self, value: impl Into<NickelValue>) -> Field<Complete> {
        Field {
            record: Complete(Some(value.into())),
            path: self.path,
            metadata: self.metadata,
        }
    }
}

impl Field<Complete> {
    /// Attach a finalized [`Field`] to a [`Record`]
    pub fn with_record(self, r: Record) -> Record {
        let v = self.record;
        let f = Field {
            record: r,
            path: self.path,
            metadata: self.metadata,
        };
        match v {
            Complete(Some(v)) => f.value(v),
            Complete(None) => f.no_value(),
        }
    }
}

impl Field<Record> {
    /// Finalize the [`Field`] without setting a value
    pub fn no_value(mut self) -> Record {
        self.record.fields.push((
            self.path,
            record::Field {
                metadata: self.metadata.into(),
                ..Default::default()
            },
        ));
        self.record
    }

    /// Finalize the [`Field`] by setting its a value
    pub fn value(mut self, value: impl Into<NickelValue>) -> Record {
        self.record.fields.push((
            self.path,
            record::Field {
                value: Some(value.into()),
                metadata: self.metadata.into(),
                ..Default::default()
            },
        ));
        self.record
    }
}

/// A Nickel record being constructed
#[derive(Debug)]
pub struct Record {
    fields: Vec<(StaticPath, record::Field)>,
    attrs: RecordAttrs,
}

fn elaborate_field_path<I>(path: I, content: record::Field) -> (LocIdent, record::Field)
where
    I: IntoIterator<Item = Ident>,
    I::IntoIter: DoubleEndedIterator,
{
    let mut it = path.into_iter();
    let fst = it.next().unwrap();

    let content = it.rev().fold(content, |acc, id| {
        record::Field::from(NickelValue::term_posless(Term::Closurize(
            NickelValue::record_posless(RecordData {
                fields: [(LocIdent::from(id), acc)].into(),
                ..Default::default()
            }),
        )))
    });

    (fst.into(), content)
}

fn build_record<I>(fields: I, attrs: RecordAttrs) -> NickelValue
where
    I: IntoIterator<Item = (LocIdent, record::Field)>,
{
    fn merge_fields(field1: record::Field, field2: record::Field) -> record::Field {
        let value = match (field1.value, field2.value) {
            (Some(t1), Some(t2)) => Some(op2(BinaryOp::Merge(Label::default().into()), t1, t2)),
            (Some(t), None) | (None, Some(t)) => Some(t),
            (None, None) => None,
        };

        record::Field {
            value,
            metadata: Combine::combine(field1.metadata, field2.metadata),
            pending_contracts: vec![],
        }
    }

    let mut static_fields = IndexMap::new();
    for (id, t) in fields {
        match static_fields.entry(id) {
            indexmap::map::Entry::Occupied(mut occupied) => {
                let prev = occupied.insert(record::Field::default());
                occupied.insert(merge_fields(prev, t));
            }
            indexmap::map::Entry::Vacant(vacant) => {
                vacant.insert(t);
            }
        }
    }

    NickelValue::record_posless(RecordData::new(static_fields, attrs, None))
}

impl Record {
    /// Make a new, empty record builder
    pub fn new() -> Self {
        Record {
            fields: vec![],
            attrs: Default::default(),
        }
    }

    /// Start constructing a field with the given name
    pub fn field(self, name: impl AsRef<str>) -> Field<Record> {
        Field {
            record: self,
            path: vec![Ident::new(name)],
            metadata: Default::default(),
        }
    }

    /// Attach possibly multiple fields to this record
    pub fn fields<I, It>(mut self, fields: It) -> Self
    where
        I: Into<Field<Complete>>,
        It: IntoIterator<Item = I>,
    {
        for f in fields {
            self = f.into().with_record(self)
        }
        self
    }

    /// Start constructing a field at the given path
    pub fn path<It, I>(self, path: It) -> Field<Record>
    where
        I: AsRef<str>,
        It: IntoIterator<Item = I>,
    {
        Field {
            record: self,
            path: path.into_iter().map(|e| Ident::new(e)).collect(),
            metadata: Default::default(),
        }
    }

    /// Set all record attributes at once
    pub fn attrs(mut self, attrs: RecordAttrs) -> Self {
        self.attrs = attrs;
        self
    }

    // Clippy correctly observes that `open` is the only field in `RecordAttrs`.
    // Nevertheless, we want to do the record update. That way we can be
    // somewhat futureproof in case new fields are added to `RecordAttrs` in
    // Nickel.
    #[allow(clippy::needless_update)]
    /// Mark this record as "open" when used as a contract
    pub fn open(mut self) -> Self {
        self.attrs = RecordAttrs {
            open: true,
            ..self.attrs
        };
        self
    }

    // See `open` for comments on the clippy directive
    #[allow(clippy::needless_update)]
    /// Mark this record as "open" when used as a contract, depending on the value of `open`
    pub fn set_open(mut self, open: bool) -> Self {
        self.attrs = RecordAttrs { open, ..self.attrs };
        self
    }

    /// Finalize the record and turn it into a [`crate::term::NickelValue`].
    ///
    /// # Closurization
    ///
    /// [Self::build] is intended to provide a ready-to-use value, so the built record is wrapped
    /// into a [crate::term::Term::Closurize] operation, as are any sub-records implicitly created
    /// by field paths. However, field values are not automatically closurized.
    pub fn build(self) -> NickelValue {
        let elaborated = self
            .fields
            .into_iter()
            .map(|(path, rt)| elaborate_field_path(path, rt));

        NickelValue::term_posless(Term::Closurize(build_record(elaborated, self.attrs)))
    }
}

impl Default for Record {
    fn default() -> Self {
        Self::new()
    }
}

impl<I, It> From<It> for Record
where
    I: Into<Field<Complete>>,
    It: IntoIterator<Item = I>,
{
    fn from(f: It) -> Self {
        Record::new().fields(f)
    }
}

impl From<Record> for NickelValue {
    fn from(val: Record) -> Self {
        val.build()
    }
}

#[cfg(test)]
mod tests {
    use crate::{
        position::TermPos,
        term::{NickelValue, TypeAnnotation},
        typ::{Type, TypeF},
    };

    use pretty_assertions::assert_eq;

    use super::*;

    fn build_closurized_record<I>(fields: I, attrs: RecordAttrs) -> NickelValue
    where
        I: IntoIterator<Item = (LocIdent, record::Field)>,
    {
        NickelValue::term_posless(Term::Closurize(build_record(fields, attrs)))
    }

    #[test]
    fn trivial() {
        let t: NickelValue = Record::new()
            .field("foo")
            .value(NickelValue::string_posless("bar"))
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![("foo".into(), NickelValue::string_posless("bar").into())],
                Default::default()
            )
        );
    }

    #[test]
    fn from_iter() {
        let t: NickelValue = Record::from([
            Field::name("foo").value(NickelValue::null()),
            Field::name("bar").value(NickelValue::null()),
        ])
        .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![
                    ("foo".into(), NickelValue::null().into()),
                    ("bar".into(), NickelValue::null().into()),
                ],
                Default::default()
            )
        );
    }

    #[test]
    fn some_doc() {
        let t: NickelValue = Record::from([
            Field::name("foo").some_doc(Some("foo")).no_value(),
            Field::name("bar").some_doc(None as Option<&str>).no_value(),
            Field::name("baz").doc("baz").no_value(),
        ])
        .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![
                    (
                        "foo".into(),
                        record::Field::from(FieldMetadata {
                            doc: Some("foo".into()),
                            ..Default::default()
                        })
                    ),
                    ("bar".into(), Default::default()),
                    (
                        "baz".into(),
                        record::Field::from(FieldMetadata {
                            doc: Some("baz".into()),
                            ..Default::default()
                        })
                    )
                ],
                Default::default()
            )
        );
    }

    #[test]
    fn fields() {
        let t: NickelValue = Record::new()
            .fields([
                Field::name("foo").value(NickelValue::string_posless("foo")),
                Field::name("bar").value(NickelValue::string_posless("bar")),
            ])
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![
                    ("foo".into(), NickelValue::string_posless("foo").into()),
                    ("bar".into(), NickelValue::string_posless("bar").into()),
                ],
                Default::default()
            )
        );
    }

    #[test]
    fn fields_metadata() {
        let t: NickelValue = Record::new()
            .fields([
                Field::name("foo").optional().no_value(),
                Field::name("bar").optional().no_value(),
            ])
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![
                    (
                        "foo".into(),
                        record::Field::from(FieldMetadata {
                            opt: true,
                            ..Default::default()
                        })
                    ),
                    (
                        "bar".into(),
                        record::Field::from(FieldMetadata {
                            opt: true,
                            ..Default::default()
                        }),
                    ),
                ],
                Default::default()
            )
        );
    }

    #[test]
    fn overriding() {
        let v: NickelValue = Record::new()
            .path(vec!["terraform", "required_providers"])
            .value(Record::from([
                Field::name("foo").value(NickelValue::null()),
                Field::name("bar").value(NickelValue::null()),
            ]))
            .path(vec!["terraform", "required_providers", "foo"])
            .value(NickelValue::string_posless("hello world!"))
            .into();
        assert_eq!(
            v,
            build_closurized_record(
                vec![
                    elaborate_field_path(
                        vec!["terraform".into(), "required_providers".into()],
                        build_closurized_record(
                            vec![
                                ("foo".into(), NickelValue::null().into()),
                                ("bar".into(), NickelValue::null().into())
                            ],
                            Default::default()
                        )
                        .into()
                    ),
                    elaborate_field_path(
                        vec![
                            "terraform".into(),
                            "required_providers".into(),
                            "foo".into(),
                        ],
                        NickelValue::string_posless("hello world!").into()
                    ),
                ],
                Default::default()
            )
        );
    }

    #[test]
    fn open_record() {
        let t: NickelValue = Record::new().open().into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![],
                RecordAttrs {
                    open: true,
                    ..Default::default()
                }
            )
        );
    }

    #[test]
    fn prio_metadata() {
        let t: NickelValue = Record::new()
            .field("foo")
            .priority(MergePriority::Top)
            .no_value()
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![(
                    "foo".into(),
                    record::Field::from(FieldMetadata {
                        priority: MergePriority::Top,
                        ..Default::default()
                    })
                )],
                Default::default()
            )
        );
    }

    #[test]
    fn contract() {
        let t: NickelValue = Record::new()
            .field("foo")
            .contract(TypeF::String)
            .no_value()
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![(
                    "foo".into(),
                    record::Field::from(TypeAnnotation {
                        contracts: vec![LabeledType {
                            typ: Type {
                                typ: TypeF::String,
                                pos: TermPos::None
                            },
                            label: Default::default()
                        }],
                        ..Default::default()
                    })
                )],
                Default::default()
            )
        );
    }

    #[test]
    fn exercise_metadata() {
        let t: NickelValue = Record::new()
            .field("foo")
            .priority(MergePriority::Bottom)
            .doc("foo?")
            .contract(TypeF::String)
            .types(TypeF::Number)
            .optional()
            .not_exported()
            .no_value()
            .into();
        assert_eq!(
            t,
            build_closurized_record(
                vec![(
                    "foo".into(),
                    record::Field::from(FieldMetadata {
                        doc: Some("foo?".into()),
                        opt: true,
                        priority: MergePriority::Bottom,
                        not_exported: true,
                        annotation: TypeAnnotation {
                            typ: Some(LabeledType {
                                typ: Type {
                                    typ: TypeF::Number,
                                    pos: TermPos::None
                                },
                                label: Default::default()
                            }),
                            contracts: vec![LabeledType {
                                typ: Type {
                                    typ: TypeF::String,
                                    pos: TermPos::None
                                },
                                label: Default::default()
                            }],
                        },
                    }),
                )],
                Default::default()
            )
        );
    }
}//! Pattern analysis.

use crate::{
    identifier::LocIdent,
    term::{pattern::*, record::Field},
};

pub trait Bindings {
    /// Returns a list of all variables bound by this pattern, together with the path to the field
    /// they match and the associated extra annotations.
    ///
    /// # Example
    ///
    /// For a pattern `{a = x @ {foo, bar | Number = z, ..rest}, d = e}`, the result of this function
    /// contains:
    ///
    /// - `(["a"], "x", empty field)` for the `x` variable
    /// - `(["a"], "rest", empty field)` for the `rest` variable
    /// - `(["a", "foo"], "foo", empty field)` for the `foo` variable
    /// - `(["a", "bar"], "z", field with Number contract)` for the `z` variable
    /// - `(["d"], "e", empty field)` for the `e` variable
    fn bindings(&self) -> Vec<(Vec<LocIdent>, LocIdent, Field)>;
}

trait InjectBindings {
    /// Same as [Bindings::bindings], but work relative to a current path inside a pattern and
    /// injects the bindings into a working vector instead of returning the result. This method is
    /// mostly used internally and is the one performing the actual work.
    ///
    /// Other modules of the LSP should use [Bindings::bindings] directly.
    ///
    /// # Parameters
    ///
    /// - `bindings`: the vector to inject the bindings into.
    /// - `path`: the field path to the sub-pattern being analysed.
    /// - `parent_extra`: the extra annotations associated with a potential parent field pattern.
    ///   For example, when injecting the bindings of `{foo ? 5 = x @ y @ z}`, all the introduced
    ///   variables should refer to default annotation of `foo`. This annotation is thus passed
    ///   along when calling to the sub-patterns' [Self::inject_bindings].
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        parent_extra: Option<&Field>,
    );
}

impl Bindings for Pattern {
    fn bindings(&self) -> Vec<(Vec<LocIdent>, LocIdent, Field)> {
        let mut bindings = Vec::new();
        self.inject_bindings(&mut bindings, Vec::new(), None);
        bindings
    }
}

impl InjectBindings for Pattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        parent_deco: Option<&Field>,
    ) {
        if let Some(alias) = self.alias {
            bindings.push((
                path.clone(),
                alias,
                parent_deco.cloned().unwrap_or_default(),
            ));
        }

        self.data.inject_bindings(bindings, path, parent_deco);
    }
}

impl InjectBindings for PatternData {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        parent_deco: Option<&Field>,
    ) {
        match self {
            PatternData::Any(id) => {
                bindings.push((path, *id, parent_deco.cloned().unwrap_or_default()))
            }
            PatternData::Record(record_pat) => {
                record_pat.inject_bindings(bindings, path, parent_deco)
            }
            PatternData::Array(array_pat) => array_pat.inject_bindings(bindings, path, parent_deco),
            PatternData::Enum(evariant_pat) => {
                evariant_pat.inject_bindings(bindings, path, parent_deco)
            }
            PatternData::Or(or_pat) => or_pat.inject_bindings(bindings, path, parent_deco),
            // Wildcard and constant patterns don't bind any variable
            PatternData::Wildcard | PatternData::Constant(_) => (),
        }
    }
}

impl InjectBindings for RecordPattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        parent_extra: Option<&Field>,
    ) {
        for field_pat in self.patterns.iter() {
            // Field patterns have their own annotation, so there's no need to propagate
            // `parent_extra` any further
            field_pat.inject_bindings(bindings, path.clone(), None);
        }

        if let TailPattern::Capture(rest) = self.tail {
            // If a contract is attached to the whole record pattern in the enclosing pattern, the
            // rest doesn't exactly match this contract: there are some fields missing. Still, it
            // sounds more useful to keep the whole metadata - including documentation - for
            // autocompletion and the like, even if it's an over-approximation.
            bindings.push((path, rest, parent_extra.cloned().unwrap_or_default()));
        }
    }
}

impl InjectBindings for ArrayPattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        _parent_extra: Option<&Field>,
    ) {
        for subpat in self.patterns.iter() {
            // Array elements shouldn't inherit the annotation from their parent (for once, they
            // are of a different type), so we reset `parent_extra` to `None`.
            subpat.inject_bindings(bindings, path.clone(), None);
        }

        if let TailPattern::Capture(rest) = self.tail {
            bindings.push((path, rest, Default::default()));
        }
    }
}

impl InjectBindings for FieldPattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        mut path: Vec<LocIdent>,
        _parent_extra: Option<&Field>,
    ) {
        path.push(self.matched_id);
        self.pattern
            .inject_bindings(bindings, path, Some(&Field::from(self.annotation.clone())));
    }
}

impl InjectBindings for EnumPattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        _parent_extra: Option<&Field>,
    ) {
        //TODO: I'm not sure we should just transparently forward to the variant's argument. Maybe
        //we need a more complex notion of path here, that knows when we enter an enum variant?
        if let Some(ref arg_pat) = self.pattern {
            arg_pat.inject_bindings(bindings, path, None);
        }
    }
}

impl InjectBindings for OrPattern {
    fn inject_bindings(
        &self,
        bindings: &mut Vec<(Vec<LocIdent>, LocIdent, Field)>,
        path: Vec<LocIdent>,
        parent_extra: Option<&Field>,
    ) {
        for subpat in self.patterns.iter() {
            subpat.inject_bindings(bindings, path.clone(), parent_extra);
        }
    }
}//! Compilation of pattern matching down to pattern-less Nickel code.
//!
//! # Algorithm
//!
//! Compiling patterns amounts to generate a decision tree - concretely, a term composed mostly of
//! nested if-then-else - which either succeeds to match a value and returns the bindings of
//! pattern variables, or fails and returns `null`.
//!
//! Compilation of pattern matching is a well-studied problem in the literature, where efficient
//! algorithms try to avoid the duplication of checks by "grouping" them in a smart way. A standard
//! resource on this topic is the paper [_Compiling Pattern Matching to Good Decision
//! Trees_](https://dl.acm.org/doi/10.1145/1411304.1411311) by Luc Maranget.
//!
//! The current version of pattern compilation in Nickel is naive: it simply compiles each pattern
//! to a checking expression and tries them all until one works. We don't expect pattern matching
//! to be relevant for performance anytime soon (allegedly, there are much more impacting aspects
//! to handle before that). We might revisit this in the future if pattern matching turns out to be
//! a bottleneck.
//!
//! Most building blocks are generated programmatically rather than written out as e.g. members of
//! the [crate::stdlib::internals] module. While clunkier, this makes it easier to change
//! the compilation strategy in the future and is more efficient in the current setting (combining
//! building blocks from the standard library would require much more function applications, while
//! we can generate inlined versions on-the-fly here).
use std::collections::HashMap;

use indexmap::IndexMap;
use nickel_lang_parser::{
    ast::pattern::{
        ArrayPattern, ConstantPattern, ConstantPatternData, EnumPattern, OrPattern, RecordPattern,
        TailPattern, bindings::Bindings,
    },
    identifier::LocIdent,
};
use smallvec::SmallVec;

use crate::{
    ast::{
        compat::ToMainline,
        pattern::{Pattern, PatternData},
    },
    error::EvalErrorKind,
    eval::value::{NickelValue, RecordData},
    metrics::increment,
    mk_app,
    position::{PosIdx, PosTable},
    term::{
        BinaryOp, BindingType, FunData, LetAttrs, NAryOp, RecordExtKind, RecordOpKind, Term,
        UnaryOp, make,
        record::{Field, FieldMetadata},
    },
};

/// A branch of a match expression.
///
/// This is a weird mix of `Ast` and `NickelValue`, because it's used during the
/// AST lowering. Also, `Pattern` doesn't have a runtime representation.
#[derive(Debug, Clone, PartialEq)]
pub struct MatchBranch<'ast> {
    /// The pattern on the left hand side of `=>`.
    pub pattern: Pattern<'ast>,
    /// A potential guard, which is an additional side-condition defined as `if cond`. The value
    /// stored in this field is the boolean condition itself.
    pub guard: Option<NickelValue>,
    /// The body of the branch, on the right hand side of `=>`.
    pub body: NickelValue,
}

/// Generate a standard `%record/insert%` primop as generated by the parser.
fn record_insert() -> BinaryOp {
    BinaryOp::RecordInsert {
        ext_kind: RecordExtKind::WithValue,
        metadata: Default::default(),
        pending_contracts: Default::default(),
        // We don't really care for optional fields here and we don't need to filter them out
        op_kind: RecordOpKind::ConsiderAllFields,
    }
}

/// Generate a Nickel expression which checks if a field is defined in a record provided as a
/// variable, and if not, insert a default value. Return the result (either the original record
/// unchanged, or the original record with the default value). The resulting record is guaranteed
/// to have the `field` defined. The implementation uses merging to avoid dropping the contracts
/// and other metadata affected to `field`, if the field exists but has no definition.
///
/// More precisely, [with_default_value] generates the following code:
///
/// ```nickel
/// if !(%record/field_is_defined% "<field>" record_id) then
///   if %record/has_field% "<field>" record_id then
///     record_id & { "<field>" = default }
///   else
///     # Merging is potentially more costly, and we can just fallback to record insertion here.
///     %record/insert% "<field>" record_id default
/// else
///   record_id
/// ```
pub(crate) fn with_default_value(
    pos_table: &mut PosTable,
    record_id: LocIdent,
    field: LocIdent,
    default: NickelValue,
) -> NickelValue {
    let field_not_defined = make::op1(
        UnaryOp::BoolNot,
        make::op2(
            BinaryOp::RecordFieldIsDefined(RecordOpKind::ConsiderAllFields),
            NickelValue::string_posless(field.label()),
            Term::Var(record_id),
        ),
    );

    let has_field = make::op2(
        BinaryOp::RecordHasField(RecordOpKind::ConsiderAllFields),
        NickelValue::string_posless(field.label()),
        Term::Var(record_id),
    );

    let insert = mk_app!(
        make::op2(
            record_insert(),
            NickelValue::string_posless(field),
            make::var(record_id)
        ),
        default.clone()
    );

    let inner_let_if = make::if_then_else(
        has_field,
        update_with_merge(pos_table, record_id, field, Field::from(default)),
        insert,
    );

    make::if_then_else(field_not_defined, inner_let_if, Term::Var(record_id))
}

/// Update a record field by merging it with a singleton record containing the new value.
///
/// ```nickel
/// record_id & { "<id>" = <field> }
/// ```
fn update_with_merge(
    pos_table: &mut PosTable,
    record_id: LocIdent,
    id: LocIdent,
    field: Field,
) -> NickelValue {
    use crate::{ast::MergeKind, label::MergeLabel};

    let annot_spans = field
        .metadata
        .iter_annots()
        .filter_map(|labeled_ty| pos_table.get(labeled_ty.label.span).into_opt());
    let value_spans = field
        .value
        .as_ref()
        .and_then(|v| pos_table.get(v.pos_idx()).into_opt());
    let span = annot_spans
        .chain(value_spans)
        // We fuse all the definite spans together.
        // unwrap(): all span should come from the same file
        .reduce(|span1, span2| span1.fuse(span2).unwrap());

    let singleton = NickelValue::record_posless(RecordData {
        fields: IndexMap::from_iter([(id, field)]),
        ..Default::default()
    });
    // Right now, patterns are compiled on-the-fly during evaluation. We thus need to
    // perform the gen_pending_contract transformation manually, or the contracts will
    // just be ignored. One step suffices, as we create a singleton record that doesn't
    // contain other non-transformed records (the default value, if any, has been
    // transformed normally).
    //
    // unwrap(): typechecking ensures that there are no unbound variables at this point
    let singleton =
        crate::transform::gen_pending_contracts::transform_one(pos_table, singleton).unwrap();

    // Since we generate a non-recursive record and inject it in the evaluation, we must manually
    // enforce it's properly closurized.
    let singleton = NickelValue::term_posless(Term::Closurize(singleton));

    let merge_label = MergeLabel {
        span: pos_table.push(span.into()),
        kind: MergeKind::Standard,
    };

    make::op2(
        BinaryOp::Merge(merge_label),
        Term::Var(record_id),
        singleton,
    )
}

pub trait CompilePart {
    /// Compile part of a broader pattern to a Nickel expression.
    ///
    /// `value_id` is the value being matched on. The caller of `compile_part`
    /// is in charge of putting it into the environment.
    ///
    /// `match_cont` and `fail_cont` are continuations: `match_cont` is the
    /// one to use if this pattern matches, while `fail_cont` is the one to
    /// use if this pattern fails to match. Both `match_cont` and `fail_cont`
    /// are allowed to contain -- as free variables -- identifiers bound by this
    /// match expression.
    ///
    /// Pattern compilation must avoid shadowing any variables. In particular,
    /// `compile_part` is not responsible for binding any of the free variables
    /// in `match_cont` or `fail_cont`.
    ///
    /// As a motivating example, consider a match block like
    ///
    /// ```nickel
    /// let foo = 1 in
    /// [2, 'Blah] |> match {
    ///   [foo, 'Bar] => foo,
    ///   [_, 'Blah] => foo,
    /// }
    /// ```
    ///
    /// This gets compiled by calling `compile_part` on the first match arm,
    /// with a `fail_cont` continuation that falls through to the second match
    /// arm. If the first match arm's pattern were to bind `foo` to `2` and
    /// then fail to match `'Bar`, the second match arm would see the wrong
    /// binding for `foo`.
    ///
    /// To avoid this unwanted shadowing, we accept a `bindings` mapping that
    /// maps the pattern variables to pattern-local identifiers. In the example
    /// above, `bindings` would be `{ foo => %1 }`. Pattern compilation can
    /// safely bind `%1` because it doesn't shadow anything, and the actual
    /// `foo` binding will be done by the match arm just before entering the
    /// body.
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue;
}

impl<'ast> CompilePart for Pattern<'ast> {
    // Compilation of the top-level pattern wrapper. If there's an alias,
    // compiles to
    //
    // pattern_data.compile(value_id, let <alias> = value_id in <match_cont>, <fail_cont>)
    //
    // where `<alias>` is a generated id, not the actual id bound in the pattern.
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        let match_cont = if let Some(alias) = self.alias {
            make::let_one_in(bindings[&alias], Term::Var(value_id), match_cont)
        } else {
            match_cont
        };

        self.data
            .compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
    }
}

impl<'ast> CompilePart for PatternData<'ast> {
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        match self {
            PatternData::Wildcard => match_cont,
            PatternData::Any(id) => make::let_one_in(bindings[id], Term::Var(value_id), match_cont),
            PatternData::Record(pat) => {
                pat.compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
            }
            PatternData::Array(pat) => {
                pat.compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
            }
            PatternData::Enum(pat) => {
                pat.compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
            }
            PatternData::Constant(pat) => {
                pat.compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
            }
            PatternData::Or(pat) => {
                pat.compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
            }
        }
    }
}

impl<'ast> CompilePart for ConstantPattern<'ast> {
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        self.data
            .compile_part(pos_table, value_id, match_cont, fail_cont, bindings)
    }
}

impl<'ast> CompilePart for ConstantPatternData<'ast> {
    fn compile_part(
        &self,
        _: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        _bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        let compile_constant = |nickel_type: &str, value: NickelValue| {
            // if %typeof% value_id == '<nickel_type> && value_id == <value> then
            //   match_cont
            // else
            //   fail_cont

            // %typeof% value_id == '<nickel_type>
            let type_matches = make::op2(
                BinaryOp::Eq,
                make::op1(UnaryOp::Typeof, Term::Var(value_id)),
                NickelValue::enum_tag_posless(nickel_type),
            );

            // value_id == <value>
            let value_matches = make::op2(BinaryOp::Eq, Term::Var(value_id), value);

            // <type_matches> && <value_matches>
            let if_condition = mk_app!(make::op1(UnaryOp::BoolAnd, type_matches), value_matches);

            make::if_then_else(if_condition, match_cont, fail_cont)
        };

        match self {
            ConstantPatternData::Bool(b) => {
                compile_constant("Bool", NickelValue::bool_value_posless(*b))
            }
            ConstantPatternData::Number(n) => {
                compile_constant("Number", NickelValue::number_posless((*n).clone()))
            }
            ConstantPatternData::String(s) => {
                compile_constant("String", NickelValue::string_posless(s.to_owned()))
            }
            ConstantPatternData::Null => compile_constant("Other", NickelValue::null()),
        }
    }
}

impl<'ast> CompilePart for OrPattern<'ast> {
    // Compilation of or patterns.
    //
    // We fold over the patterns in reverse order. In the fold, the accumulator is
    // `fail_cont`, because if an element in the or pattern fails to match then it
    // falls through to the next case (which is what's in the accumulator because
    // we're folding in reverse).
    //
    // We clone `match_cont` for each alternative. This looks wasteful
    // when pretty-printing, but `NickelValue` is cheaply cloneable so it's
    // probably fine. Another option would be to add an indirection through
    // a `Term::Var`.
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        self.patterns.iter().rev().fold(fail_cont, |cont, pattern| {
            pattern.compile_part(pos_table, value_id, match_cont.clone(), cont, bindings)
        })
    }
}

impl<'ast> CompilePart for RecordPattern<'ast> {
    // Compilation of the top-level record pattern wrapper.
    //
    // We check the match shallowly before extracting bindings, ensuring that
    // all non-defaulted fields are present. If the record isn't open, we also
    // check that there are no extra fields. We do this just by checking the
    // record length, because typechecking has already ensured that there are no
    // duplicate bindings.
    //
    // The very first thing the generated code does is to insert default values:
    // if there are any default values in the pattern, redefine `value_id` to
    // include them. This is the last part of this function (because we're in a
    // sort of continuation-passing style), but just keep in mind that the eager
    // tests are working on a record that already has default values.
    //
    // if %typeof% value_id == 'Record
    //   <if self.patterns has any default value>
    //     let value_id = <with_default_value(with_default_value(value_id, field0, default0), field1, default1) ...> in
    //   <end if>
    //
    //   <let length_check = if self.is_open { true } else { (%record/fields_with_opts% value_id |> %array/length%) == <self.patterns.len()> }>
    //
    //   if (%record/has_field_with_opts% field0 value_id) && (%record/has_field_with_opts% field1 value_id) && ... && <length_check> then
    //     <fold block (see below)>
    //   else
    //     <fail_cont>
    // else
    //   <fail_cont>
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        // <a> && <b>
        // (with a small optimization if one is `true`)
        fn and(a: NickelValue, b: NickelValue) -> NickelValue {
            if a.is_bool_true() {
                b
            } else if b.is_bool_true() {
                a
            } else {
                mk_app!(make::op1(UnaryOp::BoolAnd, a), b)
            }
        }

        let local_value_id = LocIdent::fresh();

        // (%record/has_field_with_opts% field0 local_value_id) && (%record/has_field_with_opts% field1 local_value_id) && ...
        //
        // Where field0, field1, etc. are all the non-defaulted fields.
        let has_fields = self.patterns.iter().rev().fold(
            NickelValue::bool_true(),
            |has_other_fields, field_pat| {
                if field_pat.default.is_some() {
                    has_other_fields
                } else {
                    let has_field = make::op2(
                        BinaryOp::RecordFieldIsDefined(RecordOpKind::ConsiderAllFields),
                        NickelValue::string_posless(field_pat.matched_id.label()),
                        Term::Var(local_value_id),
                    );

                    and(has_field, has_other_fields)
                }
            },
        );

        // If this pattern is non-open, this is
        //
        // (%record/fields_with_opts% local_value_id |> %array/length%) == <self.patterns.len()>
        let has_right_length = if self.is_open() {
            NickelValue::bool_true()
        } else {
            make::op2(
                BinaryOp::Eq,
                make::op1(
                    UnaryOp::ArrayLength,
                    make::op1(
                        UnaryOp::RecordFields(RecordOpKind::IgnoreEmptyOpt),
                        Term::Var(local_value_id),
                    ),
                ),
                NickelValue::number_posless(self.patterns.len()),
            )
        };

        let matches_shallow = and(has_fields, has_right_length);

        let match_cont = if let TailPattern::Capture(tail) = self.tail {
            // let
            //   <tail> = (%record/remove_with_opts% field0 (%record/remove_with_opts% field1 local_value_id) ... )
            // in <match_cont>
            //
            // where field0, field1, ... are all the fields matched in the pattern, and <tail> is a generated
            // id, not the actual id bound in the pattern.
            let tail_value = self.patterns.iter().fold(
                NickelValue::term_posless(Term::Var(local_value_id)),
                |tail, field_pat| {
                    make::op2(
                        BinaryOp::RecordRemove(RecordOpKind::ConsiderAllFields),
                        NickelValue::string_posless(field_pat.matched_id.label()),
                        tail,
                    )
                },
            );
            make::let_one_in(bindings[&tail], tail_value, match_cont)
        } else {
            match_cont
        };

        // The main fold block where we extract all of the bound variables.
        // Because there's an eager check before we enter this block, we
        // can't fail to extract any of the variables. However, there could be
        // sub-patterns that fail to match.
        //
        // Our accumulator is `match_cont`, the continuation to take when
        // the match succeeds.
        //
        // There are two cases in the match block, depending on whether the
        // field in the pattern has an annotation. If it doesn't, we yield
        //
        // let <field> = %static_access(<field>)% local_value_id in
        // <field_pat.pattern.compile_part(field, match_cont, fail_cont)>
        //
        // If there is an annotation, we yield
        //
        // let value_id = <update_with_merge value_id field annotation> in
        // let <field> = %static_access(<field>)% local_value_id in
        // <field_pat.pattern.compile_part(field, match_cont, fail_cont)>
        let fold_block = self
            .patterns
            .iter()
            .rev()
            .fold(match_cont, |match_cont, field_pat| {
                let local_field_id = LocIdent::fresh();
                let field = field_pat.matched_id;

                let match_cont = field_pat.pattern.compile_part(
                    pos_table,
                    local_field_id,
                    match_cont,
                    fail_cont.clone(),
                    bindings,
                );

                // %static_access(field)% value_id
                let extracted_value =
                    make::op1(UnaryOp::RecordAccess(field), Term::Var(local_value_id));

                // let <local_field_id> = <extracted_value> in <match_cont>
                let match_cont = make::let_one_in(local_field_id, extracted_value, match_cont);

                // <if !field.annotation.is_empty()>
                //   let value_id = <update_with_merge...> in <match_cont>
                // <else>
                //   <match_cont>
                // <end if>
                if !field_pat.annotation.is_empty() {
                    let annotation = field_pat.annotation.to_mainline(pos_table);
                    make::let_one_in(
                        local_value_id,
                        update_with_merge(
                            pos_table,
                            local_value_id,
                            field,
                            Field::from(FieldMetadata {
                                annotation,
                                ..Default::default()
                            }),
                        ),
                        match_cont,
                    )
                } else {
                    match_cont
                }
            });

        // if <matches_shallow> then <fold_block> else <fail_cont>
        let inner_if = make::if_then_else(matches_shallow, fold_block, fail_cont.clone());

        // %typeof% value_id == 'Record
        let is_record: NickelValue = make::op2(
            BinaryOp::Eq,
            make::op1(UnaryOp::Typeof, Term::Var(value_id)),
            NickelValue::enum_tag_posless("Record"),
        );

        // <if any default values {>
        //   let local_value_id = <with_default_value(with_default_value(value_id, field0, default0), field1, default1) ...> in match_cont
        // <} else {>
        //   match_cont
        // <}>
        //
        // where field0, default0, etc. range over the fields and their default values.
        let with_defaults = self.patterns.iter().fold(inner_if, |cont, field_pat| {
            if let Some(default) = field_pat.default.as_ref() {
                let default = default.to_mainline(pos_table);
                make::let_one_in(
                    local_value_id,
                    with_default_value(pos_table, local_value_id, field_pat.matched_id, default),
                    cont,
                )
            } else {
                cont
            }
        });

        // if <is_record> then let local_value_id = value_id in <with_defaults> else <fail_cont>
        make::if_then_else(
            is_record,
            make::let_one_in(local_value_id, Term::Var(value_id), with_defaults),
            fail_cont,
        )
    }
}

impl<'ast> CompilePart for ArrayPattern<'ast> {
    // Compilation of an array pattern.
    //
    // let value_len = %array/length% value_id in
    //
    // <if self.is_open()>
    // if %typeof% value_id == 'Array && value_len >= <self.patterns.len()>
    // <else>
    // if %typeof% value_id == 'Array && value_len == <self.patterns.len()>
    // <end if>
    //   <fold block (see below)>
    // else
    //   <fail_cont>
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        let value_len_id = LocIdent::fresh();
        let pats_len = NickelValue::number_posless(self.patterns.len());

        let match_cont = if let TailPattern::Capture(rest) = self.tail {
            // let <rest> = %array/slice% <self.patterns.len()> value_len value_id in <match_cont>
            make::let_one_in(
                bindings[&rest],
                make::opn(
                    NAryOp::ArraySlice,
                    vec![
                        pats_len.clone(),
                        Term::Var(value_len_id).into(),
                        Term::Var(value_id).into(),
                    ],
                ),
                match_cont,
            )
        } else {
            match_cont
        };

        // <fold (idx) in 0..self.patterns.len()
        //  - match_cont is the accumulator
        //  - initial accumulator is `match_cont`, which includes the tail bindings if necessary
        //  >
        //
        //   let local_value_id = %array/at% <idx> value_id in
        //   <self.patterns[idx].compile_part(local_value_id, match_cont, fail_cont)>
        //
        // <end fold>
        let fold_block: NickelValue = self.patterns.iter().enumerate().rev().fold(
            match_cont,
            |match_cont, (idx, elem_pat)| {
                let local_value_id = LocIdent::fresh();

                // %array/at% idx value_id
                let extracted_value = make::op2(
                    BinaryOp::ArrayAt,
                    Term::Var(value_id),
                    NickelValue::number_posless(idx),
                );

                make::let_one_in(
                    local_value_id,
                    extracted_value,
                    elem_pat.compile_part(
                        pos_table,
                        local_value_id,
                        match_cont,
                        fail_cont.clone(),
                        bindings,
                    ),
                )
            },
        );

        // %typeof% value_id == 'Array
        let is_array: NickelValue = make::op2(
            BinaryOp::Eq,
            make::op1(UnaryOp::Typeof, Term::Var(value_id)),
            NickelValue::enum_tag_posless("Array"),
        );

        let comp_op = if self.is_open() {
            BinaryOp::GreaterOrEq
        } else {
            BinaryOp::Eq
        };

        // <is_array> && value_len <comp_op> <self.patterns.len()>
        let outer_check = mk_app!(
            make::op1(UnaryOp::BoolAnd, is_array),
            make::op2(comp_op, Term::Var(value_len_id), pats_len)
        );

        // if <outer_check> then <fold_block> else <fail_cont>
        let outer_if = make::if_then_else(outer_check, fold_block, fail_cont);

        // let <value_len_id> = %array/length% <value_id> in <outer_if>
        make::let_one_in(
            value_len_id,
            make::op1(UnaryOp::ArrayLength, Term::Var(value_id)),
            outer_if,
        )
    }
}

impl<'ast> CompilePart for EnumPattern<'ast> {
    fn compile_part(
        &self,
        pos_table: &mut PosTable,
        value_id: LocIdent,
        match_cont: NickelValue,
        fail_cont: NickelValue,
        bindings: &HashMap<LocIdent, LocIdent>,
    ) -> NickelValue {
        // %enum/get_tag% value_id == '<self.tag>
        let tag_matches = make::op2(
            BinaryOp::Eq,
            make::op1(UnaryOp::EnumGetTag, Term::Var(value_id)),
            NickelValue::enum_tag_posless(self.tag),
        );

        if let Some(pat) = &self.pattern {
            // if %enum/is_variant% value_id && %enum/get_tag% value_id == '<self.tag> then
            //   let next_value_id = %enum/get_arg% value_id in
            //   <pattern.compile(next_value_id, match_cont, fail_cont)>
            // else
            //   fail_cont

            // %enum/is_variant% value_id && <tag_matches>
            let if_condition = mk_app!(
                make::op1(
                    UnaryOp::BoolAnd,
                    make::op1(UnaryOp::EnumIsVariant, Term::Var(value_id)),
                ),
                tag_matches
            );

            let next_value_id = LocIdent::fresh();

            make::if_then_else(
                if_condition,
                make::let_one_in(
                    next_value_id,
                    make::op1(UnaryOp::EnumGetArg, Term::Var(value_id)),
                    pat.compile_part(
                        pos_table,
                        next_value_id,
                        match_cont,
                        fail_cont.clone(),
                        bindings,
                    ),
                ),
                fail_cont,
            )
        } else {
            // if %typeof% value_id == 'Enum && !(%enum/is_variant% value_id) && <tag_matches> then
            //   match_cont
            // else
            //   fail_cont

            // %typeof% value_id == 'Enum
            let is_enum = make::op2(
                BinaryOp::Eq,
                make::op1(UnaryOp::Typeof, Term::Var(value_id)),
                NickelValue::enum_tag_posless("Enum"),
            );

            // !(%enum/is_variant% value_id)
            let is_enum_tag = make::op1(
                UnaryOp::BoolNot,
                make::op1(UnaryOp::EnumIsVariant, Term::Var(value_id)),
            );

            // <is_enum> && <is_enum_tag> && <tag_matches>
            let if_condition = mk_app!(
                make::op1(UnaryOp::BoolAnd, is_enum,),
                mk_app!(make::op1(UnaryOp::BoolAnd, is_enum_tag,), tag_matches)
            );

            make::if_then_else(if_condition, match_cont, fail_cont)
        }
    }
}

pub trait Compile {
    /// Compile a match expression to a Nickel expression matching `value`.
    fn compile(self, pos_table: &mut PosTable, value: NickelValue, pos_idx: PosIdx) -> NickelValue;
}

/// Content of a match expression.
#[derive(Debug, Clone, PartialEq)]
pub struct MatchData<'ast> {
    pub branches: Vec<MatchBranch<'ast>>,
}

impl<'ast> Compile for MatchData<'ast> {
    // Compilation of a full match expression, represented as an array of
    // its branches. Code between < and > is Rust code, think of it as a kind
    // of templating. Note that some special cases compile differently as
    // optimizations.
    //
    // let value_id = value in <fold_block>
    //
    // The main action is in <fold_block> (see below), which folds over the match branches.
    fn compile(
        mut self,
        pos_table: &mut PosTable,
        value: NickelValue,
        pos_idx: PosIdx,
    ) -> NickelValue {
        increment!("pattern_compile");

        if self.branches.iter().all(|branch| {
            // While we could get something working even with a guard, it's a bit more work and
            // there's no current incentive to do so (a guard on a tags-only match is arguably less
            // common, as such patterns don't bind any variable). For the time being, we just
            // exclude guards from the tags-only optimization.
            matches!(
                branch.pattern.data,
                PatternData::Enum(EnumPattern { pattern: None, .. }) | PatternData::Wildcard
            ) && branch.guard.is_none()
        }) {
            let wildcard_pat = self.branches.iter().enumerate().find_map(
                |(
                    idx,
                    MatchBranch {
                        pattern,
                        guard,
                        body,
                    },
                )| {
                    if matches!((&pattern.data, guard), (PatternData::Wildcard, None)) {
                        Some((idx, body.clone()))
                    } else {
                        None
                    }
                },
            );

            // If we find a wildcard pattern, we record its index in order to discard all the
            // patterns coming after the wildcard, because they are unreachable.
            let default = if let Some((idx, body)) = wildcard_pat {
                self.branches.truncate(idx + 1);
                Some(body)
            } else {
                None
            };

            let tags_only = self
                .branches
                .into_iter()
                .filter_map(
                    |MatchBranch {
                         pattern,
                         guard: _,
                         body,
                     }| {
                        if let PatternData::Enum(EnumPattern { tag, .. }) = pattern.data {
                            Some((*tag, body))
                        } else {
                            None
                        }
                    },
                )
                .collect();

            return TagsOnlyMatch {
                branches: tags_only,
                default,
            }
            .compile(pos_table, value, pos_idx);
        }

        let error_case = NickelValue::term(
            Term::RuntimeError(Box::new(EvalErrorKind::NonExhaustiveMatch {
                value: value.clone(),
                pos: pos_idx,
            })),
            pos_idx,
        );

        let value_id = LocIdent::fresh();

        // The fold block.
        //
        // As in or pattern compilation, we fold in reverse over the
        // alternatives, and our accumulator is the failure continuation. The
        // initial accumulator is a runtime error.
        //
        // This is the point at which we actually bind the variables from the
        // pattern. We start by generating a map of pattern-bound variables
        // to fresh variables (e.g. `{ foo => %1, bar => %2 }`) if `foo` and
        // `bar` are the variables bound by the current pattern. We pass
        // this map to the pattern compilation so that it will bind `%1` to
        // the expression that we'll eventually bind `foo` to.
        // See `CompilePart::compile_part` for why we do this.
        //
        // <for branch in branches.rev()
        //  - fail_cont is the accumulator
        // >
        //    <let match_cont = if there's a guard {
        //      let foo = %1, bar = %2, <...other bindings> in if <guard> then match_cont else fail_cont
        //    } else {
        //      let foo = %1, bar = %2, <...other bindings> in match_cont
        //    }
        //    >
        //    <pattern.compile_part(value_id, match_cont, fail_cont)>
        let fold_block = self
            .branches
            .into_iter()
            .rev()
            .fold(error_case, |fail_cont, branch| {
                let bindings = branch
                    .pattern
                    .bindings()
                    .iter()
                    .map(|b| (b.id, LocIdent::fresh()))
                    .collect::<HashMap<_, _>>();
                let match_cont = if let Some(guard) = branch.guard {
                    // The guard expression becomes part of the match
                    // continuation, so it will be evaluated in the same
                    // environment as the body of the branch.
                    make::if_then_else(guard, branch.body, fail_cont.clone())
                } else {
                    branch.body
                };

                let match_cont = make::let_in(
                    false,
                    bindings
                        .iter()
                        .map(|(binding_id, fresh_id)| (*binding_id, Term::Var(*fresh_id))),
                    match_cont,
                );
                branch
                    .pattern
                    .compile_part(pos_table, value_id, match_cont, fail_cont, &bindings)
            });

        // let value_id = value in <fold_block>
        make::let_one_in(value_id, value, fold_block)
    }
}

/// Simple wrapper used to implement specialization of match statements when all of the patterns
/// are enum tags. Instead of a sequence of conditionals (which has linear time complexity), we use
/// a special primops based on a hashmap, which has amortized constant time complexity.
struct TagsOnlyMatch {
    branches: Vec<(LocIdent, NickelValue)>,
    default: Option<NickelValue>,
}

impl Compile for TagsOnlyMatch {
    fn compile(self, _: &mut PosTable, value: NickelValue, pos_idx: PosIdx) -> NickelValue {
        increment!("pattern_compile(tags_only_match)");

        // We simply use the corresponding specialized primop in that case.
        let match_op = mk_app!(
            make::op1(
                UnaryOp::TagsOnlyMatch {
                    has_default: self.default.is_some()
                },
                value
            )
            .with_pos_idx(pos_idx),
            NickelValue::record_posless(RecordData::with_field_values(self.branches.into_iter()))
        );

        let match_op = if let Some(default) = self.default {
            mk_app!(match_op, default)
        } else {
            match_op
        };

        match_op.with_pos_idx(pos_idx)
    }
}

/// Compile a destructuring let-binding into a `Term` (which has no destructuring let)
///
/// A let-binding
///
/// ```text
/// let
///   <pat1> = <bound1>,
///   <pat2> = <bound2>
/// in body
/// ```
///
/// in which `<pat1>` binds `foo` and `<pat2>` binds `bar` is desugared to
///
/// ```text
/// let
///   %b1 = <bound1>,
///   %b2 = <bound2>,
/// in
/// let
///   %r1 = <pat1.compile_part(%b1, { foo = %c1 }, <error>, <{ foo => %c1 }>)>,
///   %r2 = <pat2.compile_part(%b2, { baz = %c2 }, <error>), <{ bar => %c2 }>)>,
/// in
/// let
///   foo = %r1.foo,
///   ...
///   baz = %r2.baz,
/// in (%seq% %r1) (%seq% %r2) body
/// ```
/// where `foo` and `baz` are names bound in `<pat1>` and `<pat2>`.
///
/// There's some ambiguity about where to put the error-checking. It might be natural
/// to put it before trying to access `%r1.foo`, but that would only raise the error
/// if someone tries to evaluate `foo`. Putting it in the body as above raises
/// an error, for example, in `let 'Foo = 'Bar in true`.
///
/// A recursive let-binding is desugared almost the same way, except that everything is
/// shoved into a single let-rec block instead of three nested blocks.
pub fn compile_let_pattern<'ast>(
    pos_table: &mut PosTable,
    bindings: &[(&Pattern<'ast>, NickelValue)],
    body: NickelValue,
    attrs: LetAttrs,
) -> Term {
    // Outer bindings are the ones we called %b1 and %b2, and %empty_record_id in the doc above.
    let mut outer_bindings = SmallVec::new();
    // Mid bindings are the ones we called %r1 and %r2 above.
    let mut mid_bindings = SmallVec::new();
    // Inner bindings are the ones that bind the actual variables defined in the patterns.
    let mut inner_bindings = SmallVec::new();

    for (pat, rhs) in bindings {
        let fused_pos = pat.pos.fuse(pos_table.get(rhs.pos_idx()));
        let error_case = NickelValue::term(
            Term::RuntimeError(Box::new(EvalErrorKind::FailedDestructuring {
                value: rhs.clone(),
                pattern_pos: pos_table.push(pat.pos),
            })),
            pos_table.push(fused_pos),
        );

        let outer_id = LocIdent::fresh();
        outer_bindings.push((outer_id, rhs.clone()));

        let mid_id = LocIdent::fresh();

        let mut pattern_bindings = HashMap::new();
        for binding in pat.bindings() {
            let id = binding.id;
            inner_bindings.push((
                id,
                make::static_access(Term::Var(mid_id), std::iter::once(id)),
            ));
            pattern_bindings.insert(id, LocIdent::fresh());
        }

        // Build the mapping from pattern variables to fresh variables
        // (see `CompilePart::compile_part` for details). This corresponds
        // to the <{ foo => %c1 }> part of the documentation above.
        let bindings_record = NickelValue::record_posless(RecordData {
            fields: pattern_bindings
                .iter()
                .map(|(bound_id, fresh_id)| {
                    (*bound_id, NickelValue::from(Term::Var(*fresh_id)).into())
                })
                .collect(),
            attrs: Default::default(),
            sealed_tail: None,
        });

        mid_bindings.push((
            mid_id,
            pat.compile_part(
                pos_table,
                outer_id,
                bindings_record,
                error_case,
                &pattern_bindings,
            ),
        ));
    }

    // Force all the "mid" ids, to make pattern failures more eager.
    // Without this, `let 'Foo = 'Bar in 1` wouldn't fail.
    let checked_body = mid_bindings.iter().rev().fold(body, |acc, (id, _)| {
        mk_app!(make::op1(UnaryOp::Seq, Term::Var(*id)), acc)
    });

    let attrs = LetAttrs {
        binding_type: BindingType::Normal,
        rec: attrs.rec,
    };
    if attrs.rec {
        Term::let_in(
            outer_bindings
                .into_iter()
                .chain(mid_bindings)
                .chain(inner_bindings)
                .collect(),
            checked_body,
            attrs,
        )
    } else {
        Term::let_in(
            outer_bindings,
            Term::let_in(
                mid_bindings,
                Term::let_in(inner_bindings, checked_body, attrs.clone()).into(),
                attrs.clone(),
            )
            .into(),
            attrs,
        )
    }
}

/// Compile a destructuring function into a `Term` (which has no destructuring function).
///
/// A function `fun <pat> => body` is desugared to `fun x => let <pat> = x in body`, and then we compile
/// the destructuring let.
pub fn compile_fun_pattern<'ast>(
    pos_table: &mut PosTable,
    pattern: &Pattern<'ast>,
    body: NickelValue,
) -> Term {
    let id = pattern.alias.unwrap_or_else(LocIdent::fresh);
    let wrapped_body = compile_let_pattern(
        pos_table,
        &[(pattern, Term::Var(id).into())],
        body,
        LetAttrs::default(),
    );
    Term::Fun(FunData {
        arg: id,
        body: wrapped_body.into(),
    })
}//! Pattern matching and destructuring of Nickel values.

