/// Iterator items produced by [RecordRowsIterator] on [UnifRecordRows<'ast>].
pub enum RecordRowsElt<'a, 'ast> {
    TailDyn,
    TailVar(&'a LocIdent),
    TailUnifVar { id: VarId, init_level: VarLevel },
    TailConstant(VarId),
    Row(RecordRowF<&'a UnifType<'ast>>),
}

impl<'a, 'ast> Iterator for RecordRowsIterator<'a, UnifType<'ast>, UnifRecordRows<'ast>> {
    type Item = RecordRowsElt<'a, 'ast>;

    fn next(&mut self) -> Option<Self::Item> {
        self.rrows.and_then(|next| match next {
            UnifRecordRows::Concrete { rrows, .. } => match rrows {
                RecordRowsF::Empty => {
                    self.rrows = None;
                    None
                }
                RecordRowsF::TailDyn => {
                    self.rrows = None;
                    Some(RecordRowsElt::TailDyn)
                }
                RecordRowsF::TailVar(id) => {
                    self.rrows = None;
                    Some(RecordRowsElt::TailVar(id))
                }
                RecordRowsF::Extend { row, tail } => {
                    self.rrows = Some(tail);
                    Some(RecordRowsElt::Row(RecordRowF {
                        id: row.id,
                        typ: row.typ.as_ref(),
                    }))
                }
            },
            UnifRecordRows::UnifVar { id, init_level } => {
                self.rrows = None;
                Some(RecordRowsElt::TailUnifVar {
                    id: *id,
                    init_level: *init_level,
                })
            }
            UnifRecordRows::Constant(var_id) => {
                self.rrows = None;
                Some(RecordRowsElt::TailConstant(*var_id))
            }
        })
    }
}

/// Iterator items produced by [`EnumRowsIterator`].
pub enum EnumRowsElt<'a, 'ast> {
    TailVar(&'a LocIdent),
    TailUnifVar { id: VarId, init_level: VarLevel },
    TailConstant(VarId),
    Row(EnumRowF<&'a UnifType<'ast>>),
}

impl<'a, 'ast> Iterator for EnumRowsIterator<'a, UnifType<'ast>, UnifEnumRows<'ast>> {
    type Item = EnumRowsElt<'a, 'ast>;

    fn next(&mut self) -> Option<Self::Item> {
        self.erows.and_then(|next| match next {
            UnifEnumRows::Concrete { erows, .. } => match erows {
                EnumRowsF::Empty => {
                    self.erows = None;
                    None
                }
                EnumRowsF::TailVar(id) => {
                    self.erows = None;
                    Some(EnumRowsElt::TailVar(id))
                }
                EnumRowsF::Extend { row, tail } => {
                    self.erows = Some(tail);
                    Some(EnumRowsElt::Row(EnumRowF {
                        id: row.id,
                        typ: row.typ.as_ref().map(|ty| ty.as_ref()),
                    }))
                }
            },
            UnifEnumRows::UnifVar { id, init_level } => {
                self.erows = None;
                Some(EnumRowsElt::TailUnifVar {
                    id: *id,
                    init_level: *init_level,
                })
            }
            UnifEnumRows::Constant(var_id) => {
                self.erows = None;
                Some(EnumRowsElt::TailConstant(*var_id))
            }
        })
    }
}

pub trait ReifyAsUnifType<'ast> {
    fn unif_type() -> UnifType<'ast>;
}

impl<'ast> ReifyAsUnifType<'ast> for crate::label::TypeVarData {
    fn unif_type() -> UnifType<'ast> {
        mk_uty_record!(("polarity", crate::label::Polarity::unif_type()))
    }
}

impl<'ast> ReifyAsUnifType<'ast> for crate::label::Polarity {
    fn unif_type() -> UnifType<'ast> {
        mk_uty_enum!("Positive", "Negative")
    }
}

/// The typing context is a structure holding the scoped, environment-like data structures required
/// to perform typechecking. The context is designed to be relatively cheap to clone.
#[derive(Debug, PartialEq, Clone)]
pub struct Context<'ast> {
    /// The typing environment.
    pub type_env: TypeEnv<'ast>,
    /// The term environment, used to decide type equality over contracts.
    pub term_env: TermEnv<'ast>,
    /// The current variable level, incremented each time we instantiate a polymorphic type and
    /// thus introduce a new block of variables (either unification variables or rigid type
    /// variables).
    pub var_level: VarLevel,
}

/// A pair of environments for a record.
#[derive(Clone, PartialEq, Debug)]
pub(super) struct RecordContext<'ast> {
    /// The outer environment of the record.
    pub(super) outer: Context<'ast>,
    /// The inner environment of the record, also dubbed the recursive environment, which is
    /// composed of [Self::outer] plus the fields of the record.
    pub(super) inner: Context<'ast>,
}

impl<'ast> RecordContext<'ast> {
    /// Creates a new context from the outer environment. The inner environment is cloned from the
    /// outer, and supposed to be be filled later through mutation.
    pub(super) fn from_outer(outer: Context<'ast>) -> Self {
        RecordContext {
            inner: outer.clone(),
            outer,
        }
    }
}

impl<'ast> Context<'ast> {
    pub fn new() -> Self {
        Context {
            type_env: TypeEnv::new(),
            term_env: TermEnv::new(),
            var_level: VarLevel::MIN_LEVEL,
        }
    }

    /// Returns `true` if this context is empty, or equivalently if it equals to [Self::new()], or
    /// equivalently if it equals to [Self::default()].
    pub fn is_empty(&self) -> bool {
        self.type_env.is_empty()
            && self.term_env.0.is_empty()
            && self.var_level == VarLevel::MIN_LEVEL
    }

    /// Retrieves a variable from the type environment, or fail with
    /// [crate::error::TypecheckErrorKind::UnboundIdentifier] instead.
    pub fn get_type(&self, id: LocIdent) -> Result<UnifType<'ast>, TypecheckError> {
        self.type_env.get(&id.ident()).cloned().ok_or_else(|| {
            TypecheckErrorData::new(AstAlloc::new(), |_alloc| {
                TypecheckErrorKind::UnboundIdentifier(id)
            })
            .into()
        })
    }
}

impl Default for Context<'_> {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Clone, Debug)]
pub enum EnvBuildError<'ast> {
    NotARecord(Ast<'ast>),
}

/// Populate the initial typing environment from a `Vec` of parsed files.
pub fn mk_initial_ctxt<'ast>(
    ast_alloc: &'ast AstAlloc,
    initial_env: impl IntoIterator<Item = (nickel_stdlib::StdlibModule, &'ast Ast<'ast>)>,
) -> Result<Context<'ast>, EnvBuildError<'ast>> {
    // Collect the bindings for each module, clone them and flatten the result to a single list.
    let mut bindings = Vec::new();

    for (module, ast) in initial_env {
        match (module, &ast.node) {
            // The internals module is special: it is required to be syntactically a record,
            // and is added directly to the top-level environment.
            (nickel_stdlib::StdlibModule::Internals, Node::Record(record)) => {
                // We reject fields without a value (that would be a stdlib module without
                // definition). We also assume that the top-level modules of the stdlib aren't
                // defined piecewise, so that all path have length exactly one, and that those are
                // static.
                bindings.extend(record.field_defs.iter().map(|field_def| {
                    // unwrap(s)(): see assumptions above about the structure of the stdlib.
                    debug_assert!(
                        field_def.path.len() == 1,
                        "unexpected piecewise definition in stdlib internals module"
                    );

                    let id = field_def.path.first().unwrap().try_as_ident().unwrap();

                    (
                        id,
                        field_def.value.as_ref().unwrap_or_else(|| {
                            panic!("expected stdlib module {id} to have a definition")
                        }),
                    )
                }));
            }
            (nickel_stdlib::StdlibModule::Internals, _) => {
                return Err(EnvBuildError::NotARecord((*ast).clone()));
            }
            // Otherwise, we insert a value in the environment bound to the name of the module
            (module, _) => bindings.push((module.name().into(), ast)),
        }
    }

    let term_env = bindings
        .iter()
        .cloned()
        .map(|(id, ast)| (id.ident(), (ast.clone(), TermEnv::new())))
        .collect();

    let type_env = bindings
        .into_iter()
        .map(|(id, ast)| {
            (
                id.ident(),
                infer_record_type(ast_alloc, ast, &term_env, INFER_RECORD_MAX_DEPTH),
            )
        })
        .collect();

    Ok(Context {
        type_env,
        term_env,
        var_level: VarLevel::MIN_LEVEL,
    })
}

/// Add the bindings of a record to a typing environment. Ignore fields whose name are defined
/// through interpolation.
//TODO: support the case of a record with a type annotation.
pub fn env_add_term<'ast>(
    ast_alloc: &'ast AstAlloc,
    env: &mut TypeEnv<'ast>,
    ast: &Ast<'ast>,
    term_env: &TermEnv<'ast>,
    resolver: &mut dyn AstImportResolver,
) -> Result<(), EnvBuildError<'ast>> {
    match &ast.node {
        Node::Record(record) => {
            for field_def in record.field_defs.iter() {
                if let Some(id) = field_def.path.first().unwrap().try_as_ident() {
                    let uty = UnifType::from_apparent_type(
                        field_def.apparent_type(ast_alloc, Some(env), Some(resolver)),
                        term_env,
                    );

                    env.insert(id.ident(), uty);
                }
            }

            Ok(())
        }
        _ => Err(EnvBuildError::NotARecord(ast.clone())),
    }
}

/// Bind one term in a typing environment.
pub fn env_add<'ast>(
    ast_alloc: &'ast AstAlloc,
    env: &mut TypeEnv<'ast>,
    id: LocIdent,
    ast: &'ast Ast<'ast>,
    term_env: &TermEnv<'ast>,
    resolver: &mut dyn AstImportResolver,
) {
    env.insert(
        id.ident(),
        UnifType::from_apparent_type(
            ast.apparent_type(ast_alloc, Some(env), Some(resolver)),
            term_env,
        ),
    );
}

/// The shared state of unification.
///
/// # Lifetimes
///
/// - `'ast`: the lifetime of the AST nodes. It is supposed to outlive the typechecking
///   phase, so references with this lifetime can be freely duplicated and passed.
/// - `'local`: usually the lifetime of the current typechecking function being called. It can be
///   refined/reborrowed during recursive calls.
pub struct State<'ast, 'local> {
    /// The import resolver, to retrieve and typecheck imports.
    resolver: &'local mut dyn AstImportResolver,
    /// The unification table.
    table: &'local mut UnifTable<'ast>,
    /// Row constraints.
    constr: &'local mut RowConstrs,
    /// A mapping from unification variables or constants together with their
    /// kind to the name of the corresponding type variable which introduced it,
    /// if any.
    ///
    /// Used for error reporting.
    names: &'local mut NameTable,
    /// A mapping from wildcard ID to unification variable.
    wildcard_vars: &'local mut Vec<UnifType<'ast>>,
    /// The AST allocator.
    ast_alloc: &'ast AstAlloc,
}

/// Immutable and owned data, required by the LSP to carry out specific analysis.
/// It is basically an owned-subset of the typechecking state.
pub struct TypeTables<'ast> {
    pub table: UnifTable<'ast>,
    pub names: NameTable,
    pub wildcards: Vec<Type<'ast>>,
}

/// Typechecks a term.
///
/// Returns the inferred type in case of success. This is just a wrapper that calls
/// `typecheck_visit` with a blanket implementation for the visitor.
///
/// Note that this function doesn't recursively typecheck imports (anymore), but just the current
/// file. It however still needs the resolver to get the apparent type of imports.
///
/// Returns the type inferred for type wildcards.
pub fn typecheck<'ast>(
    alloc: &'ast AstAlloc,
    ast: &'ast Ast<'ast>,
    initial_ctxt: Context<'ast>,
    resolver: &mut dyn AstImportResolver,
    initial_mode: TypecheckMode,
) -> Result<Wildcards<'ast>, TypecheckError> {
    typecheck_visit(alloc, ast, initial_ctxt, resolver, &mut (), initial_mode)
        .map(|tables| tables.wildcards)
}

/// Typechecks a term while providing the type information to a visitor.
pub fn typecheck_visit<'ast, V>(
    ast_alloc: &'ast AstAlloc,
    ast: &'ast Ast<'ast>,
    initial_ctxt: Context<'ast>,
    resolver: &mut dyn AstImportResolver,
    visitor: &mut V,
    initial_mode: TypecheckMode,
) -> Result<TypeTables<'ast>, TypecheckError>
where
    V: TypecheckVisitor<'ast>,
{
    let (mut table, mut names) = (UnifTable::new(), HashMap::new());
    let mut wildcard_vars = Vec::new();

    {
        let mut state = State {
            resolver,
            table: &mut table,
            constr: &mut RowConstrs::new(),
            names: &mut names,
            wildcard_vars: &mut wildcard_vars,
            ast_alloc,
        };

        if initial_mode == TypecheckMode::Enforce {
            let uty = state.table.fresh_type_uvar(initial_ctxt.var_level);
            ast.check(&mut state, initial_ctxt, visitor, uty)?;
        } else {
            ast.walk(&mut state, initial_ctxt, visitor)?;
        }
    }

    let wildcards = wildcard_vars_to_type(ast_alloc, wildcard_vars.clone(), &table);

    Ok(TypeTables {
        table,
        names,
        wildcards,
    })
}

/// AST components that can be walked (traversed to look for statically typed block). Corresponds
/// to typechecking in **walk** mode.
trait Walk<'ast>: Copy {
    /// Walks the AST of a term looking for statically typed blocks to check. Calls the visitor
    /// callbacks alongside and store the apparent type of variables inside the type and
    /// environments.
    // [^self-owned]: this method doesn't require to take ownership `self`, as the AST nodes are
    //     merely traversed. However, we need to implement `Walk` on two different categories of
    //     objects:
    //
    //     1. Reference to AST nodes, which needs to be of the form of `&'ast _` in order to produce
    //        suberefences that are guaranteed to live as long as `'ast`.
    //     2. References to temporary objects, that don't live in the allocator and are created on the
    //        spot by the typechecker. The typical example is [record::ResolvedRecord]. Those can't
    //        have an `&'ast` lifetime. But this is fine because they hold internal node
    //        references that are `&'ast`, so we can relax the constraint and implement the trait
    //        for `&_`.
    //
    //     To have the same interface work on both categories, we implement this trait on _the
    //     reference type_ instead, such as `&'ast Ast<'ast>`, so that the implementer can freely
    //     chose the lifetime of the reference. This is why we take ownership of `self` here: it's
    //     actually of type `&'something _`, for the `_` of interest.
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError>;
}

impl<'ast, T> Walk<'ast> for &'ast [T]
where
    &'ast T: Walk<'ast>,
{
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        for t in self {
            t.walk(state, ctxt.clone(), visitor)?;
        }

        Ok(())
    }
}

impl<'ast, T> Walk<'ast> for &'ast StringChunk<T>
where
    &'ast T: Walk<'ast>,
{
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        if let StringChunk::Expr(t, _) = self {
            t.walk(state, ctxt.clone(), visitor)?;
        }

        Ok(())
    }
}

impl<'ast> Walk<'ast> for &'ast Ast<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        mut ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        visitor.visit_term(
            self,
            UnifType::from_apparent_type(
                self.apparent_type(state.ast_alloc, Some(&ctxt.type_env), Some(state.resolver)),
                &ctxt.term_env,
            ),
        );

        match &self.node {
            Node::ParseError(_)
            | Node::Null
            | Node::Bool(_)
            | Node::Number(_)
            | Node::String(_)
            | Node::EnumVariant { arg: None, .. } => Ok(()),
            // This function doesn't recursively typecheck imports: this is the responsibility of the
            // caller. However, we still resolve the import, in order to report any error there.
            //
            // This is an arbitrary architectural choice: we could handle failed imports later in
            // `crate::cache` because we don't walk it there anyway, and thus could handle a failure.
            // But since a faulty import leads to an error in a statically typed block (where we need
            // to peek at the content), this is simpler and more symmetric to force resolution here as
            // well.
            //
            // Additionally, this makes the life of NLS simpler: typecheck is guaranteed to resolve
            // all imports in a source, whether they are in a typed block or not.
            Node::Import(import) => {
                let _ = state.resolver.resolve(import, &self.pos)?;
                Ok(())
            }
            Node::Var(x) => ctxt.get_type(*x).map(|_| ()),
            Node::StringChunks(chunks) => (*chunks).walk(state, ctxt, visitor),
            Node::Fun { args, body } => {
                // The parameter of an unannotated function is always assigned type `Dyn`, unless the
                // function is directly annotated with a function contract (see the special casing in
                // `walk_with_annot`).
                for arg in args.iter() {
                    let PatternTypeData {
                        bindings: pat_bindings,
                        ..
                    } = arg.pattern_types(state, &ctxt, TypecheckMode::Walk)?;
                    ctxt.type_env
                        .extend(pat_bindings.into_iter().map(|(id, typ)| (id.ident(), typ)));
                }

                body.walk(state, ctxt, visitor)
            }
            Node::Array(array) => array.walk(state, ctxt, visitor),
            Node::Let {
                bindings,
                body,
                rec,
            } => {
                // For a recursive let block, shadow all the names we're about to bind, so
                // we aren't influenced by variables defined in an outer scope.
                if *rec {
                    for binding in bindings.iter() {
                        for pat_binding in binding.pattern.bindings() {
                            ctxt.type_env
                                .insert(pat_binding.id.ident(), mk_uniftype::dynamic());
                        }
                    }
                }

                let start_ctxt = ctxt.clone();

                // We first need to populate the (potentially) recursive environment in this separate
                // loop before walking bound values.
                for binding in bindings.iter() {
                    let ty_let = binding_type(state, binding, &start_ctxt, false);

                    let mut register_binding = |id: &LocIdent, uty: UnifType<'ast>| {
                        visitor.visit_ident(id, uty.clone());
                        ctxt.type_env.insert(id.ident(), uty);
                        // [^term-env-rec-bindings]: we don't support recursive binding when checking
                        // for contract equality.
                        //
                        // This would quickly lead to `Rc` cycles, which are hard to deal with without
                        // leaking memory. The best way out would be to allocate all the term
                        // environments inside an arena, local to each statically typed block, and use
                        // bare references to represent cycles. Everything would be cleaned at the end
                        // of the block.
                        ctxt.term_env.0.insert(
                            id.ident(),
                            (binding.value.clone(), start_ctxt.term_env.clone()),
                        );
                    };

                    // The use of start_ctxt here looks like it might be wrong for let rec, but in fact
                    // the context is unused in mode `TypecheckMode::Walk` anyway.
                    let PatternTypeData {
                        bindings: pat_bindings,
                        ..
                    } = binding
                        .pattern
                        .pattern_types(state, &start_ctxt, TypecheckMode::Walk)?;

                    for (id, typ) in pat_bindings {
                        register_binding(&id, typ);
                    }

                    // In the case of a let-binding, we want to guess a better type than `Dyn` when we
                    // can do so cheaply for the whole pattern, that is when there's an alias and/or
                    // when the pattern is an `Any` pattern. We do this after the generic loop over
                    // bindings, so that this more precise type information shadows the previous one.

                    if let Some(alias) = &binding.pattern.alias {
                        register_binding(alias, ty_let.clone());
                    }

                    if let Some(id) = &binding.pattern.try_as_any() {
                        register_binding(id, ty_let);
                    }
                }

                let value_ctxt = if *rec {
                    ctxt.clone()
                } else {
                    start_ctxt.clone()
                };

                for binding in bindings.iter() {
                    binding.walk(state, value_ctxt.clone(), visitor)?;
                }

                body.walk(state, ctxt, visitor)
            }
            Node::App { head, args } => {
                head.walk(state, ctxt.clone(), visitor)?;
                args.walk(state, ctxt, visitor)
            }
            Node::Match(match_data) => {
                for MatchBranch {
                    pattern,
                    guard,
                    body,
                } in match_data.branches.iter()
                {
                    let mut local_ctxt = ctxt.clone();
                    let PatternTypeData {
                        bindings: pat_bindings,
                        ..
                    } = pattern.pattern_types(state, &ctxt, TypecheckMode::Walk)?;

                    for (id, typ) in pat_bindings {
                        visitor.visit_ident(&id, typ.clone());
                        local_ctxt.type_env.insert(id.ident(), typ);
                    }

                    if let Some(guard) = guard {
                        guard.walk(state, local_ctxt.clone(), visitor)?;
                    }

                    body.walk(state, local_ctxt, visitor)?;
                }

                Ok(())
            }
            Node::IfThenElse {
                cond,
                then_branch,
                else_branch,
            } => {
                cond.walk(state, ctxt.clone(), visitor)?;
                then_branch.walk(state, ctxt.clone(), visitor)?;
                else_branch.walk(state, ctxt, visitor)
            }
            Node::Record(record) => record
                .resolve()
                .with_pos(self.pos)
                .walk(state, ctxt, visitor),
            Node::EnumVariant { arg: Some(arg), .. } => arg.walk(state, ctxt, visitor),
            Node::PrimOpApp { args, .. } => args.walk(state, ctxt, visitor),
            Node::Annotated { annot, inner } => {
                walk_with_annot(state, ctxt, visitor, *annot, Some(inner))
            }
            Node::Type(typ) => typ.walk(state, ctxt, visitor),
        }
    }
}

impl<'ast> Walk<'ast> for &'ast Type<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        match &self.typ {
       TypeF::Dyn
       | TypeF::Number
       | TypeF::Bool
       | TypeF::String
       | TypeF::ForeignId
       | TypeF::Symbol
       // Currently, the parser can't generate unbound type variables by construction. Thus we
       // don't check here for unbound type variables again.
       | TypeF::Var(_)
       // An enum type can't contain a contract.
       // TODO: the assertion above isn't true anymore (ADTs). Need fixing?
       | TypeF::Enum(_)
       | TypeF::Wildcard(_) => Ok(()),
       TypeF::Arrow(ty1, ty2) => {
           ty1.walk(state, ctxt.clone(), visitor)?;
           ty2.walk(state, ctxt, visitor)
       }
       TypeF::Record(rrows) => rrows.walk(state, ctxt, visitor),
       TypeF::Contract(t) => t.walk(state, ctxt, visitor),
       TypeF::Dict { type_fields: ty, .. }
       | TypeF::Array(ty)
       | TypeF::Forall {body: ty, ..} => ty.walk(state, ctxt, visitor),
    }
    }
}

impl<'ast> Walk<'ast> for &'ast RecordRows<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        match self.0 {
            RecordRowsF::Empty
            // Currently, the parser can't generate unbound type variables by construction. Thus we
            // don't check here for unbound type variables again.
            | RecordRowsF::TailVar(_)
            | RecordRowsF::TailDyn => Ok(()),
            RecordRowsF::Extend { ref row, tail } => {
                row.typ.walk(state, ctxt.clone(), visitor)?;
                tail.walk(state, ctxt, visitor)
            }
        }
    }
}

impl<'ast, S: AnnotSeqRef<'ast>> Walk<'ast> for &FieldDefCheckView<'ast, S> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        walk_with_annot(state, ctxt, visitor, self.annots, self.value)
    }
}

impl<'ast> Walk<'ast> for &'ast FieldDef<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        walk_with_annot(
            state,
            ctxt,
            visitor,
            &self.metadata.annotation,
            self.value.as_ref(),
        )
    }
}

impl<'ast> Walk<'ast> for &'ast LetBinding<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        walk_with_annot(
            state,
            ctxt,
            visitor,
            &self.metadata.annotation,
            Some(&self.value),
        )
    }
}

/// Walk an annotated term, either via [crate::term::record::FieldMetadata], or via a standalone
/// type and contracts annotation. A type annotation switches the typechecking mode to _enforce_.
fn walk_with_annot<'ast, 'a, S: AnnotSeqRef<'ast>, V: TypecheckVisitor<'ast>>(
    state: &mut State<'ast, '_>,
    mut ctxt: Context<'ast>,
    visitor: &mut V,
    annots: S,
    value: Option<&'ast Ast<'ast>>,
) -> Result<(), TypecheckError> {
    annots
        .iter()
        .try_for_each(|ty| ty.walk(state, ctxt.clone(), visitor))?;

    let typ = annots.typ();

    match (typ, value) {
        (Some(ty2), Some(value)) => {
            let uty2 = UnifType::from_type(ty2.clone(), &ctxt.term_env);
            value.check(state, ctxt, visitor, uty2)
        }
        (None, Some(value)) => {
            // If we see a function annotated with a function contract, we can get the type of the
            // arguments for free. We use this information both for typechecking (you could see it
            // as an extension of the philosophy of apparent types, but for function arguments
            // instead of let-bindings) and for the LSP, to provide better type information and
            // completion.
            if let Node::Fun { args, body } = value.node {
                // We look for the first contract of the list that is a function contract.
                let domains = annots.contracts().find_map(|c| {
                    if let TypeF::Arrow(domain, mut codomain) = c.typ {
                        let mut domains =
                            vec![UnifType::from_type((*domain).clone(), &ctxt.term_env)];

                        while let TypeF::Arrow(next_domain, next_codomain) = &codomain.typ {
                            domains
                                .push(UnifType::from_type((*next_domain).clone(), &ctxt.term_env));
                            codomain = next_codomain;
                        }

                        Some(domains)
                    } else {
                        None
                    }
                });

                let mut register_binding =
                    |id: LocIdent, ctxt: &mut Context<'ast>, uty: UnifType<'ast>| {
                        visitor.visit_ident(&id, uty.clone());
                        ctxt.type_env.insert(id.ident(), uty);
                    };

                if let Some(domains) = domains {
                    for (arg, uty) in args
                        .iter()
                        // We might find fewer domains than arguments (for example, a function `fun
                        // x y z` can very much be annotated with a contract `Number -> Dyn`).
                        // However we still need to process all of the arguments, or they will be
                        // reported as unbound variable when used. So if we're out of domain types,
                        // we just use `Dyn` for the remaining args.
                        .zip(domains.into_iter().map(Some).chain(std::iter::repeat(None)))
                    {
                        let uty = uty.unwrap_or_else(mk_uniftype::dynamic);

                        // Because the normal code path in `walk` sets the function argument to `Dyn`,
                        // we need to short-circuit it. We manually visit the argument, augment the
                        // typing environment and walk the body of the function.
                        if let Some(id) = arg.try_as_any() {
                            register_binding(id, &mut ctxt, uty.clone());

                            if let Some(alias) = arg.alias {
                                register_binding(alias, &mut ctxt, uty);
                            }
                        }
                        // However, if the pattern is a single variable, we need to properly fill
                        // the environment with pattern variables.
                        else {
                            let PatternTypeData {
                                bindings: pat_bindings,
                                ..
                            } = arg.pattern_types(state, &ctxt, TypecheckMode::Walk)?;

                            ctxt.type_env.extend(
                                pat_bindings.into_iter().map(|(id, typ)| (id.ident(), typ)),
                            );
                        }
                    }

                    return body.walk(state, ctxt, visitor);
                }
            }

            value.walk(state, ctxt, visitor)
        }
        _ => Ok(()),
    }
}

/// AST components that can be checked against a given type. Although this method mostly
/// corresponds to checking mode in the classical bidirectional framework, it combines both
/// checking and inference modes in practice, to avoid duplicating rules (that is, code) as
/// detailed below.
///
/// # Literals
///
/// Checking a literal (a number, a string, a boolean, etc.) unifies the checked type with the
/// corresponding primitive type (`Number`, `String`, `Bool`, etc.). If the checked type is a
/// unification variable, `check` acts as an inference rule. If the type is concrete, unification
/// enforces equality, and `check` acts as a checking rule.
///
/// # Introduction rules
///
/// Following Pfenning's recipe (see [Bidirectional Typing][bidirectional-typing]), introduction
/// rules (e.g. typechecking a record) are checking. `check` follows the same logic here: it uses
/// unification to "match" on the expected type (for example in the case of records, a record type
/// or a dictionary type) and pushes typechecking down the record fields.
///
/// # Elimination rules
///
/// Elimination rules (such as function application or primitive operator application) only exist in
/// inference mode (still following Pfenning's recipe). `check` follows the inference mode here
/// (typically on function application, where we first call to `infer` on the function part, and
/// then check the argument).
///
/// Still, `check` is supposed to be implementing checking mode from the outside. We thus also
/// apply the typing rule which switches from inference to checking mode. Currently, subtyping
/// isn't supported yet in Nickel but is planned as part of RFC004. When subtyping lands, as the
/// name suggests, [`subsumption`] will be the place where we apply subsumption, as customary in
/// bidirectional type systems with subtyping.
///
/// To sum up, elimination rules inside `check` correspond to an inference rule composed with the
/// switching/subsumption rule, resulting in a composite checking rule.
///
/// # Parameters
///
/// - `state`: the unification state (see [`State`]).
/// - `env`: the typing environment, mapping free variable to types.
/// - `lin`: The current building linearization of building state `S`
/// - `visitor`: A visitor that can modify the linearization
/// - `t`: the term to check.
/// - `ty`: the type to check the term against.
///
/// # LSP
///
/// `check` is in charge of registering every term it comes across (and identifiers) with the
/// `visitor` and makes sure to scope the visitor accordingly.
///
/// [bidirectional-typing]: (https://arxiv.org/abs/1908.05839)
trait Check<'ast> {
    /// Checks `self` against a given type.
    // We take ownership of `self`: see [^self-owned] in `Walk`.
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError>;
}

impl<'ast> Check<'ast> for &'ast Ast<'ast> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        mut ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        visitor.visit_term(self, ty.clone());

        // When checking against a polymorphic type, we immediately instantiate potential heading
        // foralls. Otherwise, this polymorphic type wouldn't unify much with other types. If we infer
        // a polymorphic type for `ast`, the subsumption rule will take care of instantiating this type
        // with unification variables, such that terms like `(fun x => x : forall a. a -> a) : forall
        // b. b -> b` typecheck correctly.
        let ty = instantiate_foralls(state, &mut ctxt, ty, ForallInst::Constant);

        match &self.node {
            Node::ParseError(_) => Ok(()),
            // null is inferred to be of type Dyn
            Node::Null => ty
                .unify(mk_uniftype::dynamic(), state, &ctxt)
                .map_err(|err| err.into_typecheck_err(state, self.pos)),
            Node::Bool(_) => ty
                .unify(mk_uniftype::bool(), state, &ctxt)
                .map_err(|err| err.into_typecheck_err(state, self.pos)),
            Node::Number(_) => ty
                .unify(mk_uniftype::num(), state, &ctxt)
                .map_err(|err| err.into_typecheck_err(state, self.pos)),
            Node::String(_) => ty
                .unify(mk_uniftype::str(), state, &ctxt)
                .map_err(|err| err.into_typecheck_err(state, self.pos)),
            Node::StringChunks(chunks) => {
                ty.unify(mk_uniftype::str(), state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                for chunk in chunks.iter() {
                    if let StringChunk::Expr(t, _) = chunk {
                        t.check(state, ctxt.clone(), visitor, mk_uniftype::str())?;
                    }
                }

                Ok(())
            }
            Node::IfThenElse {
                cond,
                then_branch,
                else_branch,
            } => {
                cond.check(state, ctxt.clone(), visitor, mk_uniftype::bool())?;
                then_branch.check(state, ctxt.clone(), visitor, ty.clone())?;
                else_branch.check(state, ctxt, visitor, ty)
            }
            // Fun is an introduction rule for the arrow type. The target type is thus expected to be
            // of the form `T1 -> ... -> Tn -> U`, which we enforce by unification. We then check the
            // body of the function against `U`, after adding the relevant argument types in the
            // environment.
            Node::Fun { args, body } => {
                let codomain = state.table.fresh_type_uvar(ctxt.var_level);
                // The args need to be reversed: for a function `fun s n b => ...` taking a string,
                // a number and a bool as arguments, we must build the type `String -> Number ->
                // Boolean -> ?a`. Building this type by folding needs to visit `b` first, then `n`
                // and finally `s`.
                let fun_type = args.iter().rev().try_fold(
                    codomain.clone(),
                    |fun_type, arg| -> Result<_, TypecheckError> {
                        // See [^separate-alias-treatment].
                        let pat_types =
                            arg.data
                                .pattern_types(state, &ctxt, TypecheckMode::Enforce)?;
                        // In the destructuring case, there's no alternative pattern, and we must thus
                        // immediately close all the row types.
                        pattern::close_all_enums(pat_types.enum_open_tails, state);
                        let arg_type = pat_types.typ;

                        if let Some(id) = arg.alias {
                            visitor.visit_ident(&id, arg_type.clone());
                            ctxt.type_env.insert(id.ident(), arg_type.clone());
                        }

                        for (id, typ) in pat_types.bindings {
                            visitor.visit_ident(&id, typ.clone());
                            ctxt.type_env.insert(id.ident(), typ);
                        }

                        Ok(mk_uty_arrow!(arg_type, fun_type))
                    },
                )?;

                ty.unify(fun_type, state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                body.check(state, ctxt, visitor, codomain)
            }
            Node::Array(elts) => {
                let ty_elts = state.table.fresh_type_uvar(ctxt.var_level);

                ty.unify(mk_uniftype::array(ty_elts.clone()), state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                for elt in elts.iter() {
                    elt.check(state, ctxt.clone(), visitor, ty_elts.clone())?;
                }

                Ok(())
            }
            Node::Let {
                bindings,
                body,
                rec,
            } => {
                // For a recursive let block, shadow all the names we're about to bind, so
                // we aren't influenced by variables defined in an outer scope.
                if *rec {
                    for binding in bindings.iter() {
                        for pat_binding in binding.pattern.bindings() {
                            ctxt.type_env.insert(
                                pat_binding.id.ident(),
                                state.table.fresh_type_uvar(ctxt.var_level),
                            );
                        }
                    }
                }

                let start_ctxt = ctxt.clone();

                let typed_bindings: Result<Vec<_>, _> = bindings
                    .iter()
                    .map(|binding| -> Result<_, TypecheckError> {
                        // The inferred type of the expr being bound
                        let ty_bound = binding_type(state, binding, &start_ctxt, true);

                        let mut register_binding = |id: &LocIdent, uty: UnifType<'ast>| {
                            visitor.visit_ident(id, uty.clone());
                            ctxt.type_env.insert(id.ident(), uty.clone());
                            // See [^term-env-rec-bindings] for why we use `start_ctxt` independently
                            // from `rec`.
                            ctxt.term_env.0.insert(
                                id.ident(),
                                (binding.value.clone(), start_ctxt.term_env.clone()),
                            );
                        };

                        // In the case of a simple binding (a variable), we want to use the binding
                        // type directly for this variable without going through unification.
                        //
                        // Currently, it doesn't make a whole lot of difference (we could get rid
                        // of the `if` branch and only keep the `else` branch to mostly the same
                        // effect), because we happily unify unification variables with polymorphic
                        // types. However this situation isn't ideal and might change.
                        // Distinguishing the two cases is more future-proof.
                        if let Some(id) = binding.pattern.try_as_any() {
                            if let Some(alias) = &binding.pattern.alias {
                                register_binding(alias, ty_bound.clone());
                            }

                            register_binding(&id, ty_bound.clone());
                        } else {
                            // We treat the alias separately, so we only call `pattern_types` on
                            // the underlying `data` here.
                            let pat_types = binding.pattern.data.pattern_types(
                                state,
                                &start_ctxt,
                                TypecheckMode::Enforce,
                            )?;

                            // In the destructuring case, there's no alternative pattern, and we must thus
                            // immediately close all the row types.
                            pattern::close_all_enums(pat_types.enum_open_tails, state);

                            pat_types
                                .typ
                                .unify(ty_bound.clone(), state, &start_ctxt)
                                .map_err(|e| e.into_typecheck_err(state, binding.value.pos))?;

                            if let Some(alias) = &binding.pattern.alias {
                                register_binding(alias, ty_bound.clone());
                            }

                            for (id, typ) in pat_types.bindings {
                                register_binding(&id, typ);
                            }
                        }

                        Ok((&binding.value, ty_bound, &binding.metadata.annotation))
                    })
                    .collect();

                let re_ctxt = if *rec { &ctxt } else { &start_ctxt };

                for (value, ty_bound, annot) in typed_bindings? {
                    // If the binding is annotated, we implement the same behavior as for a
                    // free-standing annotation `foo | T`, or any other annotated value: the mode
                    // is switched to infer and we let `infer_with_annot` handles the rest.
                    if !annot.is_empty() {
                        // Note that the loop above already checked that `ty_bound` agrees with the
                        // type inferred from the pattern. In the case of an annotated binding,
                        // `ty_bound` is coming from the annotation. So we don't have to check the
                        // inferred type against anything else here; we call `infer_with_annot` so
                        // that it correctly handles checking (or walking, if the annotation is a
                        // contract annotation) the underlying term, but we don't actually use the
                        // result of inference.
                        let _ =
                            infer_with_annot(state, re_ctxt.clone(), visitor, annot, Some(value))?;
                    } else {
                        value.check(state, re_ctxt.clone(), visitor, ty_bound)?;
                    }
                }

                body.check(state, ctxt, visitor, ty)
            }
            Node::Match(data) => {
                // [^typechecking-match-expression]: We can associate a type to each pattern of each
                // case of the match expression. From there, the type of a valid argument for the match
                // expression is ideally the union of each pattern type.
                //
                // For record types, we don't have a good way to express union: for example, what could
                // be the type of something that is either `{x : a}` or `{y : a}`? In the case of
                // record types, we thus just take the intersection of the types, which amounts to
                // unify all pattern types together. While it might fail most of the time (including
                // for the `{x}` and `{y}` example), it can still typecheck interesting expressions
                // when the record patterns are compatible:
                //
                // ```nickel
                // x |> match {
                //  {foo, bar: 'Baz} => <branch1>
                //  {foo, bar: 'Qux} => <branch2>
                // }
                // ```
                //
                // We can definitely find a type for `x`: `{foo: a, bar: [| 'Baz, 'Qux |]}`.
                //
                // For enum types, we can express unions: for example, the union of `[|'Foo, 'Bar|]` and
                // `[|'Bar, 'Baz|]` is `[|'Foo, 'Bar, 'Baz|]`. We can even turn this into a unification
                // problem: "open" the initial row types as `[| 'Foo, 'Bar; ?a |]` and `[|'Bar, 'Baz;
                // ?b |]`, unify them together, and close the result (unify the tail with an empty row
                // tail). The advantage of this approach is that unification takes care of descending
                // into record types and sub-patterns to perform this operation, and we're back to the
                // same procedure (almost) than for record patterns: simply unify all pattern types.
                // Although we have additional bookkeeping to perform (remember the tail variables
                // introduced to open enum rows and close the corresponding rows at the end of the
                // procedure).

                // We zip the pattern types with each branch
                let with_pat_types = data
                    .branches
                    .iter()
                    .map(|branch| -> Result<_, TypecheckError> {
                        Ok((
                            branch,
                            branch
                                .pattern
                                .pattern_types(state, &ctxt, TypecheckMode::Enforce)?,
                        ))
                    })
                    .collect::<Result<Vec<(&MatchBranch, PatternTypeData<_>)>, _>>()?;

                // A match expression is a special kind of function. Thus it's typed as `a -> b`, where
                // `a` is a type determined by the patterns and `b` is the type of each match arm.
                let arg_type = state.table.fresh_type_uvar(ctxt.var_level);
                let return_type = state.table.fresh_type_uvar(ctxt.var_level);

                // Express the constraint that all the arms of the match expression should have a
                // compatible type and that each guard must be a boolean.
                for (
                    MatchBranch {
                        pattern,
                        guard,
                        body,
                    },
                    pat_types,
                ) in with_pat_types.iter()
                {
                    if let Some(alias) = &pattern.alias {
                        visitor.visit_ident(alias, return_type.clone());
                        ctxt.type_env.insert(alias.ident(), return_type.clone());
                    }

                    for (id, typ) in pat_types.bindings.iter() {
                        visitor.visit_ident(id, typ.clone());
                        ctxt.type_env.insert(id.ident(), typ.clone());
                    }

                    if let Some(guard) = guard {
                        guard.check(state, ctxt.clone(), visitor, mk_uniftype::bool())?;
                    }

                    body.check(state, ctxt.clone(), visitor, return_type.clone())?;
                }

                let pat_types = with_pat_types.into_iter().map(|(_, pat_types)| pat_types);

                // Unify all the pattern types with the argument's type, and build the list of all open
                // tail vars
                let mut enum_open_tails = Vec::with_capacity(
                    pat_types
                        .clone()
                        .map(|pat_type| pat_type.enum_open_tails.len())
                        .sum(),
                );

                // Build the list of all wildcard pattern occurrences
                let mut wildcard_occurrences = HashSet::with_capacity(
                    pat_types
                        .clone()
                        .map(|pat_type| pat_type.wildcard_occurrences.len())
                        .sum(),
                );

                // We don't immediately return if an error occurs while unifying the patterns together.
                // For error reporting purposes, it's best to first close the tail variables (if
                // needed), to avoid cluttering the reported types with free unification variables
                // which are mostly an artifact of our implementation of typechecking pattern matching.
                let pat_unif_result: Result<(), UnifError> =
                    pat_types.into_iter().try_for_each(|pat_type| {
                        arg_type.clone().unify(pat_type.typ, state, &ctxt)?;

                        for (id, typ) in pat_type.bindings {
                            visitor.visit_ident(&id, typ.clone());
                            ctxt.type_env.insert(id.ident(), typ);
                        }

                        enum_open_tails.extend(pat_type.enum_open_tails);
                        wildcard_occurrences.extend(pat_type.wildcard_occurrences);

                        Ok(())
                    });

                // Once we have accumulated all the information about enum rows and wildcard
                // occurrences, we can finally close the tails that need to be.
                pattern::close_enums(enum_open_tails, &wildcard_occurrences, state);

                // And finally fail if there was an error.
                pat_unif_result.map_err(|err| err.into_typecheck_err(state, self.pos))?;

                // We unify the expected type of the match expression with `arg_type -> return_type`.
                //
                // This must happen last, or at least after having closed the tails: otherwise, the
                // enum type inferred for the argument could be unduly generalized. For example, take:
                //
                // ```
                // let exp : forall r. [| 'Foo; r |] -> Dyn = match { 'Foo => null }
                // ```
                //
                // This must not typecheck, as the match expression doesn't have a default case, and
                // its type is thus `[| 'Foo |] -> Dyn`. However, during the typechecking of the match
                // expression, before tails are closed, the working type is `[| 'Foo; _erows_a |]`,
                // which can definitely unify with `[| 'Foo; r |]` while the tail is still open. If we
                // close the tail first, then the type becomes [| 'Foo |] and the generalization fails
                // as desired.
                //
                // As a safety net, the tail closing code panics (in debug mode) if it finds a rigid
                // type variable at the end of the tail of a pattern type, which would happen if we
                // somehow generalized an enum row type variable before properly closing the tails
                // before.
                ty.unify(
                    mk_uty_arrow!(arg_type.clone(), return_type.clone()),
                    state,
                    &ctxt,
                )
                .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                Ok(())
            }
            // Elimination forms (variable, function application and primitive operator application)
            // follow the inference discipline, following the Pfennig recipe and the current type
            // system specification (as far as typechecking is concerned, primitive operator
            // application is the same as function application).
            Node::Var(_) | Node::App { .. } | Node::PrimOpApp { .. } | Node::Annotated { .. } => {
                let inferred = self.infer(state, ctxt.clone(), visitor)?;

                // We apply the subsumption rule when switching from infer mode to checking mode.
                inferred
                    .subsumed_by(ty, state, ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))
            }
            Node::EnumVariant { tag, arg: None } => {
                let row = state.table.fresh_erows_uvar(ctxt.var_level);
                ty.unify(mk_uty_enum!(*tag; row), state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))
            }
            Node::EnumVariant {
                tag,
                arg: Some(arg),
            } => {
                let tail = state.table.fresh_erows_uvar(ctxt.var_level);
                let ty_arg = state.table.fresh_type_uvar(ctxt.var_level);

                // We match the expected type against `[| 'id ty_arg; row_tail |]`, where `row_tail` is
                // a free unification variable, to ensure it has the right shape and extract the
                // components.
                ty.unify(mk_uty_enum!((*tag, ty_arg.clone()); tail), state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                // Once we have a type for the argument, we check the variant's data against it.
                arg.check(state, ctxt, visitor, ty_arg)
            }
            Node::Record(record) => record
                .resolve()
                .with_pos(self.pos)
                .check(state, ctxt, visitor, ty),
            // We use the apparent type of the import for checking. This function doesn't
            // recursively typecheck imports: this is the responsibility of the caller.
            Node::Import(import) => {
                let imported = state.resolver.resolve(import, &self.pos)?;

                let ty_import: UnifType<'ast> = if let Some(ast) = imported {
                    let ty_import = UnifType::from_apparent_type(
                        apparent_type_move(state.ast_alloc, ast),
                        &ctxt.term_env,
                    );

                    // Since the interface of `AstImportResolver` doesn't guarantee that the
                    // resulting AST and associated types live for `'ast`, as they might be
                    // allocated in a different arena, we deep-copy the obtained apparent type to
                    // the current arena.
                    state.ast_alloc.clone_from::<UnifType>(ty_import)
                } else {
                    mk_uniftype::dynamic()
                };

                ty.unify(ty_import, state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos))?;

                Ok(())
            }
            Node::Type(typ) => {
                if let Some(contract) = typ.find_contract() {
                    Err(Box::new(TypecheckErrorData::new(
                        AstAlloc::new(),
                        |alloc| TypecheckErrorKind::CtrTypeInTermPos {
                            contract: Ast::clone_to(contract.clone(), alloc),
                            pos_type: self.pos,
                        },
                    )))
                } else {
                    Ok(())
                }
            }
        }
    }
}

/// Metadata can be combined using [crate::combine::CombineAlloc]. However, this requires to
/// allocate a fresh annotation object. During record resolution and typechecking, we just want to
/// walk the annotations as if they were combined, but without actually allocating. This trait
/// provides a common interface to either a single annotation or a sequence of annotations, as used
/// by the typechecker.
// We take ownership of `self`: see [^self-owned] in `Walk`.
pub trait AnnotSeqRef<'ast>: Copy {
    /// Returns the first type annotation, if any.
    fn typ(self) -> Option<&'ast Type<'ast>>;

    /// Return the sequence of contracts, that is all annotations but the first type annotation, if
    /// any.
    fn contracts(self) -> impl Iterator<Item = &'ast Type<'ast>>;

    /// Returns the main annotation, which is either the type annotation if any, or the first
    /// contract annotation.
    fn first(self) -> Option<&'ast Type<'ast>>;

    /// Iterates over the annotations, starting by the type and followed by the contracts.
    fn iter(self) -> impl Iterator<Item = &'ast Type<'ast>>;
}

impl<'ast> AnnotSeqRef<'ast> for &'ast Annotation<'ast> {
    fn first(self) -> Option<&'ast Type<'ast>> {
        self.typ.as_ref().or(self.contracts.iter().next())
    }

    fn iter(self) -> impl Iterator<Item = &'ast Type<'ast>> {
        self.typ.iter().chain(self.contracts.iter())
    }

    fn typ(self) -> Option<&'ast Type<'ast>> {
        self.typ.as_ref()
    }

    fn contracts(self) -> impl Iterator<Item = &'ast Type<'ast>> {
        self.contracts.iter()
    }
}

// Implementation used for a piecewise definition, where at most one value is defined. This can be
// considered the same as a single field definition with all annotations combined.
impl<'ast> AnnotSeqRef<'ast> for &[&'ast FieldDef<'ast>] {
    fn typ(self) -> Option<&'ast Type<'ast>> {
        self.iter()
            .find_map(|def| def.metadata.annotation.typ.as_ref())
    }

    fn first(self) -> Option<&'ast Type<'ast>> {
        self.iter().find_map(|def| def.metadata.annotation.first())
    }

    fn iter(self) -> impl Iterator<Item = &'ast Type<'ast>> {
        self.iter().flat_map(|def| def.metadata.annotation.iter())
    }

    fn contracts(self) -> impl Iterator<Item = &'ast Type<'ast>> {
        self.iter()
            .flat_map(|def| def.metadata.annotation.typ.as_ref())
            .skip(1)
            .chain(
                self.iter()
                    .flat_map(|def| def.metadata.annotation.contracts.iter()),
            )
    }
}

/// Common structure for checking either a standard field definition, or a field definition
/// reconstituted from record resolution.
struct FieldDefCheckView<'ast, S> {
    /// The annotation or sequence of annotations.
    annots: S,
    /// The position of the identifier (the last of the field path).
    pos_id: TermPos,
    /// The field value, if any.
    value: Option<&'ast Ast<'ast>>,
}

impl<'ast, S: AnnotSeqRef<'ast>> Check<'ast> for &FieldDefCheckView<'ast, S> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        // If there's no annotation, we simply check the underlying value, if any.
        if self.annots.iter().next().is_none() {
            if let Some(value) = self.value.as_ref() {
                value.check(state, ctxt, visitor, ty)
            } else {
                // It might make sense to accept any type, i.e. generate a unification variable,
                // for a value without definition (which would act a bit like a function
                // parameter). But for now, we play safe and implement a more restrictive rule,
                // which is that a value without a definition has type `Dyn`
                ty.unify(mk_uniftype::dynamic(), state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, self.pos_id))
            }
        } else {
            let pos = self.value.as_ref().map(|v| v.pos).unwrap_or(self.pos_id);

            let inferred = infer_with_annot(state, ctxt.clone(), visitor, self.annots, self.value)?;

            inferred
                .subsumed_by(ty, state, ctxt)
                .map_err(|err| err.into_typecheck_err(state, pos))
        }
    }
}

impl<'ast> Check<'ast> for &'ast FieldDef<'ast> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        FieldDefCheckView {
            annots: &self.metadata.annotation,
            pos_id: self.path.last().unwrap().pos(),
            value: self.value.as_ref(),
        }
        .check(state, ctxt, visitor, ty)
    }
}

/// Function handling the common part of inferring the type of terms with type or contract
/// annotations, with or without definitions. This encompasses both standalone type annotation
/// (where `value` is always `Some(_)`) as well as field definitions (where `value` may or may not
/// be defined).
///
/// The annotations are walked as well.
fn infer_with_annot<'ast, V: TypecheckVisitor<'ast>, S: AnnotSeqRef<'ast>>(
    state: &mut State<'ast, '_>,
    ctxt: Context<'ast>,
    visitor: &mut V,
    annots: S,
    value: Option<&'ast Ast<'ast>>,
) -> Result<UnifType<'ast>, TypecheckError> {
    for ty in annots.iter() {
        ty.walk(state, ctxt.clone(), visitor)?;
    }

    let typ = annots.typ();
    let mut contracts = annots.contracts().peekable();

    match (typ, value) {
        (Some(ty2), Some(value)) => {
            let uty2 = UnifType::from_type(ty2.clone(), &ctxt.term_env);

            visitor.visit_term(value, uty2.clone());
            value.check(state, ctxt, visitor, uty2.clone())?;

            Ok(uty2)
        }
        // An annotation without a type but with a contract switches the typechecker back to walk
        // mode. If there are several contracts, we arbitrarily chose the first one as the apparent
        // type (the most precise type would be the intersection of all contracts, but Nickel's
        // type system doesn't feature intersection types).
        (None, value_opt) if contracts.peek().is_some() => {
            let ty2 = contracts.next().unwrap();
            let uty2 = UnifType::from_type(ty2.clone(), &ctxt.term_env);

            if let Some(value) = &value_opt {
                visitor.visit_term(value, uty2.clone());
            }

            // If there's an inner value, we have to walk it, as it may contain statically typed
            // blocks.
            if let Some(value) = value_opt {
                value.walk(state, ctxt, visitor)?;
            }

            Ok(uty2)
        }
        // A non-empty value without a type or a contract annotation is typechecked in the same way
        // as its inner value. This case should only happen for record fields, as the parser can't
        // produce an annotated term without an actual annotation. Still, such terms could be
        // produced programmatically, and aren't necessarily an issue.
        (None, Some(value)) => value.infer(state, ctxt, visitor),
        // An empty value is a record field without definition. We don't check anything, and infer
        // its type to be either the first annotation defined if any, or `Dyn` otherwise.
        // We can only hit this case for record fields.
        (_, None) => {
            let inferred = annots
                .first()
                .map(|ty| UnifType::from_type(ty.clone(), &ctxt.term_env))
                .unwrap_or_else(mk_uniftype::dynamic);
            Ok(inferred)
        }
    }
}

trait Infer<'ast> {
    /// Infer a type for an expression.
    ///
    /// `infer` corresponds to the inference mode of bidirectional typechecking. Nickel uses a mix of
    /// bidirectional typechecking and traditional ML-like unification.
    // Note that [^self-owned] of `Walk` doesn't apply here, so we can take implement this trait
    // directly on the types of interest.
    fn infer<V: TypecheckVisitor<'ast>>(
        &'ast self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<UnifType<'ast>, TypecheckError>;
}

impl<'ast> Infer<'ast> for Ast<'ast> {
    fn infer<V: TypecheckVisitor<'ast>>(
        &'ast self,
        state: &mut State<'ast, '_>,
        mut ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<UnifType<'ast>, TypecheckError> {
        match &self.node {
            Node::Var(x) => {
                let x_ty = ctxt.get_type(*x)?;
                visitor.visit_term(self, x_ty.clone());
                Ok(x_ty)
            }
            // Theoretically, we need to instantiate the type of the head of the primop application,
            // that is, the primop itself. In practice,
            // [crate::typecheck::operation::PrimOpType::primop_type] returns types that are
            // already instantiated with free unification variables, to save building a polymorphic
            // type that would be instantiated immediately. Thus, the type of a primop is currently
            // always monomorphic.
            Node::PrimOpApp { op, args } => {
                let (tys_args, ty_res) = op.primop_type(state, ctxt.var_level)?;

                visitor.visit_term(self, ty_res.clone());

                for (ty_arg, arg) in tys_args.into_iter().zip(args.iter()) {
                    arg.check(state, ctxt.clone(), visitor, ty_arg)?;
                }

                Ok(ty_res)
            }
            Node::App { head, args } => {
                // If we go the full Quick Look route (cf [quick-look] and the Nickel type system
                // specification), we will have a more advanced and specific rule to guess the
                // instantiation of the potentially polymorphic type of the head of the application.
                // Currently, we limit ourselves to predicative instantiation, and we can get away
                // with eagerly instantiating heading `foralls` with fresh unification variables.
                let head_poly = head.infer(state, ctxt.clone(), visitor)?;
                let head_type =
                    instantiate_foralls(state, &mut ctxt, head_poly, ForallInst::UnifVar);

                let arg_types: Vec<_> =
                    std::iter::repeat_with(|| state.table.fresh_type_uvar(ctxt.var_level))
                        .take(args.len())
                        .collect();

                let codomain = state.table.fresh_type_uvar(ctxt.var_level);
                let fun_type = mk_uniftype::nary_arrow(arg_types.clone(), codomain.clone());

                // "Match" the type of the head with `arg1 -> ... -> argn -> codom`
                fun_type
                    .unify(head_type, state, &ctxt)
                    .map_err(|err| err.into_typecheck_err(state, head.pos))?;

                visitor.visit_term(self, codomain.clone());

                for (arg, arg_type) in args.iter().zip(arg_types.into_iter()) {
                    arg.check(state, ctxt.clone(), visitor, arg_type)?;
                }

                Ok(codomain)
            }
            Node::Annotated { annot, inner } => {
                infer_with_annot(state, ctxt, visitor, *annot, Some(inner))
            }
            _ => {
                // The remaining cases can't produce polymorphic types, and thus we can reuse the
                // checking code. Inferring the type for those rules is equivalent to checking against
                // a free unification variable. This saves use from duplicating all the remaining
                // cases.
                let inferred = state.table.fresh_type_uvar(ctxt.var_level);

                visitor.visit_term(self, inferred.clone());

                self.check(state, ctxt, visitor, inferred.clone())?;
                Ok(inferred.into_root(state.table))
            }
        }
    }
}

/// Determine the type of a let-bound expression.
///
/// Call [`apparent_type`] to see if the binding is annotated. If it is, return this type as a
/// [`UnifType<'ast>`]. Otherwise:
///
/// - in walk mode, we won't (and possibly can't) infer the type of `bound_exp`: just return `Dyn`.
/// - in typecheck mode, we will typecheck `bound_exp`: return a new unification variable to be
///   associated to `bound_exp`.
///
/// As this function is always called in a context where an `ImportResolver` is present, expect it
/// passed in arguments.
///
/// If the annotated type contains any wildcard:
///
/// - in non strict mode, wildcards are assigned `Dyn`.
/// - in strict mode, the wildcard is typechecked, and we return the unification variable
///   corresponding to it.
fn binding_type<'ast>(
    state: &mut State<'ast, '_>,
    binding: &'ast LetBinding<'ast>,
    ctxt: &Context<'ast>,
    strict: bool,
) -> UnifType<'ast> {
    let uty = binding.apparent_type(state.ast_alloc, Some(&ctxt.type_env), Some(state.resolver));
    apparent_or_infer(state, uty, ctxt, strict)
}

/// Either returns the exact type annotation extracted as an apparent type, or return a fresh
/// unification variable, for the type to be inferred by the typechecker, in enforce mode.
///
/// In walk mode, returns the type as approximated by [`apparent_type`].
fn apparent_or_infer<'ast>(
    state: &mut State<'ast, '_>,
    aty: ApparentType<'ast>,
    ctxt: &Context<'ast>,
    strict: bool,
) -> UnifType<'ast> {
    match aty {
        ApparentType::Annotated(ty) if strict => {
            replace_wildcards_with_var(state.table, ctxt, state.wildcard_vars, ty)
        }
        ApparentType::Approximated(_) if strict => state.table.fresh_type_uvar(ctxt.var_level),
        ty_apt => UnifType::from_apparent_type(ty_apt, &ctxt.term_env),
    }
}

/// Substitute wildcards in a type for their unification variable, and converts the result to a
/// [UnifType].
fn replace_wildcards_with_var<'ast>(
    table: &mut UnifTable<'ast>,
    ctxt: &Context<'ast>,
    wildcard_vars: &mut Vec<UnifType<'ast>>,
    ty: Type<'ast>,
) -> UnifType<'ast> {
    fn replace_rrows<'ast>(
        table: &mut UnifTable<'ast>,
        ctxt: &Context<'ast>,
        wildcard_vars: &mut Vec<UnifType<'ast>>,
        rrows: RecordRows<'ast>,
    ) -> UnifRecordRows<'ast> {
        UnifRecordRows::concrete(rrows.0.map_state(
            |ty, (table, wildcard_vars)| {
                Box::new(replace_wildcards_with_var(
                    table,
                    ctxt,
                    wildcard_vars,
                    ty.clone(),
                ))
            },
            |rrows, (table, wildcard_vars)| {
                Box::new(replace_rrows(table, ctxt, wildcard_vars, rrows.clone()))
            },
            &mut (table, wildcard_vars),
        ))
    }

    fn replace_erows<'ast>(
        table: &mut UnifTable<'ast>,
        ctxt: &Context<'ast>,
        wildcard_vars: &mut Vec<UnifType<'ast>>,
        erows: EnumRows<'ast>,
    ) -> UnifEnumRows<'ast> {
        UnifEnumRows::concrete(erows.0.map_state(
            |ty, (table, wildcard_vars)| {
                Box::new(replace_wildcards_with_var(
                    table,
                    ctxt,
                    wildcard_vars,
                    ty.clone(),
                ))
            },
            |erows, (table, wildcard_vars)| {
                Box::new(replace_erows(table, ctxt, wildcard_vars, erows.clone()))
            },
            &mut (table, wildcard_vars),
        ))
    }

    match ty.typ {
        TypeF::Wildcard(i) => get_wildcard_var(table, ctxt.var_level, wildcard_vars, i),
        _ => UnifType::concrete(ty.typ.map_state(
            |ty, (table, wildcard_vars)| {
                Box::new(replace_wildcards_with_var(
                    table,
                    ctxt,
                    wildcard_vars,
                    ty.clone(),
                ))
            },
            |rrows, (table, wildcard_vars)| replace_rrows(table, ctxt, wildcard_vars, rrows),
            // Enum rows contain neither wildcards nor contracts
            |erows, (table, wildcard_vars)| replace_erows(table, ctxt, wildcard_vars, erows),
            |ctr, _| (ctr, ctxt.term_env.clone()),
            &mut (table, wildcard_vars),
        )),
    }
}

/// Different kinds of apparent types (see [HasApparentType]).
///
/// Indicate the nature of an apparent type. In particular, in enforce mode, the typechecker throws
/// away approximations as it can do better and infer the actual type of an expression.  In walk
/// mode, however, the approximation is the best we can do. Thanks to [ApparentType], callers of
/// [HasApparentType::apparent_type] can make an informed decision.
#[derive(Debug)]
pub enum ApparentType<'ast> {
    /// The apparent type is given by a user-provided annotation.
    Annotated(Type<'ast>),
    /// The apparent type has been inferred from a simple expression.
    Inferred(Type<'ast>),
    /// The term is a variable and its type was retrieved from the typing environment.
    FromEnv(UnifType<'ast>),
    /// The apparent type wasn't trivial to determine, and an approximation (most of the time,
    /// `Dyn`) has been returned.
    Approximated(Type<'ast>),
}

impl Default for ApparentType<'_> {
    fn default() -> Self {
        ApparentType::Approximated(Type::from(TypeF::Dyn))
    }
}

impl<'ast> TryConvert<'ast, ApparentType<'ast>> for Type<'ast> {
    type Error = std::convert::Infallible;

    fn try_convert(alloc: &'ast AstAlloc, at: ApparentType<'ast>) -> Result<Self, Self::Error> {
        Ok(match at {
            ApparentType::Annotated(ty) if has_wildcards(&ty) => Type::from(TypeF::Dyn),
            ApparentType::Annotated(ty)
            | ApparentType::Inferred(ty)
            | ApparentType::Approximated(ty) => ty,
            ApparentType::FromEnv(uty) => Type::try_convert(alloc, uty)
                .ok()
                .unwrap_or(Type::from(TypeF::Dyn)),
        })
    }
}

pub trait HasApparentType<'ast> {
    /// Determine the apparent type of a let-bound expression.
    ///
    /// When a let-binding `let x = bound_exp in body` is processed, the type of `bound_exp` must be
    /// determined in order to be bound to the variable `x` in the typing environment.
    /// Then, future occurrences of `x` can be given this type when used in a statically typed block.
    ///
    /// The role of `apparent_type` is precisely to determine the type of `bound_exp`:
    /// - if `bound_exp` is annotated by a type or contract annotation, return the user-provided type,
    ///   unless that type is a wildcard.
    /// - if `bound_exp` is a constant (string, number, boolean or symbol) which type can be deduced
    ///   directly without unfolding the expression further, return the corresponding exact type.
    /// - if `bound_exp` is an array, return `Array Dyn`.
    /// - if `bound_exp` is a resolved import, return the apparent type of the imported term. Returns
    ///   `Dyn` if the resolver is not passed as a parameter to the function.
    /// - Otherwise, return an approximation of the type (currently `Dyn`, but could be more precise in
    ///   the future, such as `Dyn -> Dyn` for functions, `{ | Dyn}` for records, and so on).
    // We take ownership of `self`: see [^self-owned] in `Walk`.
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast>;
}

// Common implementation for FieldDef and LetBinding.
impl<'ast> HasApparentType<'ast> for &(&'ast Annotation<'ast>, Option<&'ast Ast<'ast>>) {
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        self.0
            .first()
            .cloned()
            .map(ApparentType::Annotated)
            .or_else(|| {
                self.1
                    .as_ref()
                    .map(|v| v.apparent_type(ast_alloc, env, resolver))
            })
            .unwrap_or_default()
    }
}

impl<'ast> HasApparentType<'ast> for &'ast FieldDef<'ast> {
    // Return the apparent type of a field, by first looking at the type annotation, if any, then at
    // the contracts annotation, and if there is none, fall back to the apparent type of the value. If
    // there is no value, `Approximated(Dyn)` is returned.
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        (&self.metadata.annotation, self.value.as_ref()).apparent_type(ast_alloc, env, resolver)
    }
}

impl<'ast> HasApparentType<'ast> for &'ast LetBinding<'ast> {
    // Return the apparent type of a binding, by first looking at a potential type annotation, if
    // any, then at the contracts annotation, and if there is none, fall back to the apparent type
    // of the value. If there is no value, `Approximated(Dyn)` is returned.
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        (&self.metadata.annotation, Some(&self.value)).apparent_type(ast_alloc, env, resolver)
    }
}

// Specialized for retrieving the apparent type of an imported AST. This is similar to `<Ast as
// HasApparentType>::apparent_type`, but:
//
// 1. There is no environment or resolver, since we're checking a fresh import in an empty
//    environment.
// 2. The input AST is allowed to have a different lifetime than the output apparent type. The
//    output is either copied to `ast_alloc` or directly allocated there, when generateing e.g. an
//    array type.
//
// It's annoying to have a partial duplication of `apparent_type` here, but it's the simplest way
// forward. It's not clear how to factor out the common code while maintaining that the normal
// version of `apparent_type` should not pay an additional cost (if we used this function for
// `apparent_type`, we might unduly copy stuff that is already in `ast_alloc`)
fn apparent_type_move<'from, 'to>(
    ast_alloc: &'to AstAlloc,
    ast: &'from Ast<'from>,
) -> ApparentType<'to> {
    match &ast.node {
        Node::Annotated { annot, inner } => annot
            .first()
            .map(|typ| ApparentType::Annotated(ast_alloc.clone_from::<Type>(typ.clone())))
            .unwrap_or_else(|| apparent_type_move(ast_alloc, inner)),
        Node::Number(_) => ApparentType::Inferred(Type::from(TypeF::Number)),
        Node::Bool(_) => ApparentType::Inferred(Type::from(TypeF::Bool)),
        Node::String(_) | Node::StringChunks(_) => {
            ApparentType::Inferred(Type::from(TypeF::String))
        }
        Node::Array(_) => ApparentType::Approximated(Type::from(TypeF::Array(
            ast_alloc.alloc(Type::from(TypeF::Dyn)),
        ))),
        _ => ApparentType::default(),
    }
}

impl<'ast> HasApparentType<'ast> for &'ast Ast<'ast> {
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        match &self.node {
            Node::Annotated { annot, inner } => annot
                .first()
                .map(|typ| ApparentType::Annotated(typ.clone()))
                .unwrap_or_else(|| inner.apparent_type(ast_alloc, env, resolver)),
            Node::Number(_) => ApparentType::Inferred(Type::from(TypeF::Number)),
            Node::Bool(_) => ApparentType::Inferred(Type::from(TypeF::Bool)),
            Node::String(_) | Node::StringChunks(_) => {
                ApparentType::Inferred(Type::from(TypeF::String))
            }
            Node::Array(_) => ApparentType::Approximated(Type::from(TypeF::Array(
                ast_alloc.alloc(Type::from(TypeF::Dyn)),
            ))),
            Node::Var(id) => env
                .and_then(|envs| envs.get(&id.ident()).cloned())
                .map(ApparentType::FromEnv)
                .unwrap_or_default(),
            Node::Import(import) => {
                let Some(resolver) = resolver else {
                    return ApparentType::default();
                };

                // We don't handle import errors here. it's just too annoying to have
                // `apparent_type` return a `Result`.
                //
                // The import error will be bubbled up anyway by typechecking, because either
                // we're in walk mode and the import will be walked just after, or we're in
                // check mode and the import will be assigned to a pretty liberal type `?a`.
                //
                // What's important is that we don't create a spurious typechecking error
                // "expected Foo, got Dyn" that would be reported first and hide the actual,
                // underlying import error.
                let imported = resolver.resolve(import, &self.pos).unwrap_or_default();

                if let Some(ast) = imported {
                    apparent_type_move(ast_alloc, ast)
                } else {
                    ApparentType::default()
                }
            }
            _ => ApparentType::Approximated(Type::from(TypeF::Dyn)),
        }
    }
}

/// Infer the type of a non-annotated record by recursing inside gathering the apparent type of the
/// fields. It's currently used essentially to type the stdlib.
///
/// # Parameters
///
/// - `ast`: the term to infer a type for
/// - `term_env`: the current term environment, used for contracts equality
/// - `max_depth`: the max recursion depth. `infer_record_type` descends into sub-records, as long
///   as it only encounters nested record literals. `max_depth` is used to control this behavior
///   and cap the work that `infer_record_type` might do.
///
/// # Preconditions
///
/// The recourd shouldn't have any dynamic fields. They are ignored anyway, so if the record has
/// some, the inferred type could be wrong.
pub fn infer_record_type<'ast>(
    ast_alloc: &'ast AstAlloc,
    ast: &'ast Ast<'ast>,
    term_env: &TermEnv<'ast>,
    max_depth: u8,
) -> UnifType<'ast> {
    match &ast.node {
        Node::Record(record) if max_depth > 0 => UnifType::from(TypeF::Record(
            UnifRecordRows::concrete(record.field_defs.iter().fold(
                RecordRowsF::Empty,
                |rtype, field_def| {
                    if let Some(id) = field_def.path.first().unwrap().try_as_ident() {
                        let uty = match field_def.apparent_type(ast_alloc, None, None) {
                            ApparentType::Annotated(ty) => UnifType::from_type(ty, term_env),
                            ApparentType::FromEnv(uty) => uty,
                            // Since we haven't reached max_depth yet, and the type is only
                            // approximated, we try to recursively infer a better type.
                            ApparentType::Inferred(ty) | ApparentType::Approximated(ty) => {
                                field_def
                                    .value
                                    .as_ref()
                                    .map(|v| {
                                        infer_record_type(ast_alloc, v, term_env, max_depth - 1)
                                    })
                                    .unwrap_or(UnifType::from_type(ty, term_env))
                            }
                        };

                        RecordRowsF::Extend {
                            row: UnifRecordRow {
                                id,
                                typ: Box::new(uty),
                            },
                            tail: Box::new(rtype.into()),
                        }
                    } else {
                        rtype
                    }
                },
            )),
        )),
        _ => {
            UnifType::from_apparent_type(ast.apparent_type(ast_alloc, None, None), &TermEnv::new())
        }
    }
}

/// Deeply check whether a type contains a wildcard.
fn has_wildcards(ty: &Type<'_>) -> bool {
    ty.find_map(&mut |ty: &Type| ty.typ.is_wildcard().then_some(()))
        .is_some()
}

/// Type of the parameter controlling instantiation of foralls.
///
/// See [`instantiate_foralls`].
#[derive(Copy, Clone, Debug, PartialEq)]
enum ForallInst {
    Constant,
    UnifVar,
}

/// Instantiate the type variables which are quantified in head position with either unification
/// variables or type constants.
///
/// For example, if `inst` is `Constant`, `forall a. forall b. a -> (forall c. b -> c)` is
/// transformed to `cst1 -> (forall c. cst2 -> c)` where `cst1` and `cst2` are fresh type
/// constants.  This is used when typechecking `forall`s: all quantified type variables in head
/// position are replaced by rigid type constants, and the term is then typechecked normally. As
/// these constants cannot be unified with anything, this forces all the occurrences of a type
/// variable to be the same type.
///
/// # Parameters
///
/// - `state`: the unification state
/// - `ty`: the polymorphic type to instantiate
/// - `inst`: the type of instantiation, either by a type constant or by a unification variable
fn instantiate_foralls<'ast>(
    state: &mut State<'ast, '_>,
    ctxt: &mut Context<'ast>,
    mut ty: UnifType<'ast>,
    inst: ForallInst,
) -> UnifType<'ast> {
    ty = ty.into_root(state.table);

    // We are instantiating a polymorphic type: it's precisely the place where we have to increment
    // the variable level, to prevent already existing unification variables to unify with the
    // rigid type variables introduced here.
    //
    // As this function can be called on monomorphic types, we only increment the level when we
    // really introduce a new block of rigid type variables.
    if matches!(
        ty,
        UnifType::Concrete {
            typ: TypeF::Forall { .. },
            ..
        }
    ) {
        ctxt.var_level.incr();
    }

    while let UnifType::Concrete {
        typ: TypeF::Forall {
            var,
            var_kind,
            body,
        },
        ..
    } = ty
    {
        let kind: VarKindDiscriminant = (&var_kind).into();

        match var_kind {
            VarKind::Type => {
                let fresh_uid = state.table.fresh_type_var_id(ctxt.var_level);
                let uvar = match inst {
                    ForallInst::Constant => UnifType::Constant(fresh_uid),
                    ForallInst::UnifVar => UnifType::UnifVar {
                        id: fresh_uid,
                        init_level: ctxt.var_level,
                    },
                };
                state.names.insert((fresh_uid, kind), var.ident());
                ty = body.subst(&var, &uvar);
            }
            VarKind::RecordRows { excluded } => {
                let fresh_uid = state.table.fresh_rrows_var_id(ctxt.var_level);
                let uvar = match inst {
                    ForallInst::Constant => UnifRecordRows::Constant(fresh_uid),
                    ForallInst::UnifVar => UnifRecordRows::UnifVar {
                        id: fresh_uid,
                        init_level: ctxt.var_level,
                    },
                };
                state.names.insert((fresh_uid, kind), var.ident());
                ty = body.subst(&var, &uvar);

                if inst == ForallInst::UnifVar {
                    state.constr.insert(fresh_uid, excluded);
                }
            }
            VarKind::EnumRows { excluded } => {
                let fresh_uid = state.table.fresh_erows_var_id(ctxt.var_level);
                let uvar = match inst {
                    ForallInst::Constant => UnifEnumRows::Constant(fresh_uid),
                    ForallInst::UnifVar => UnifEnumRows::UnifVar {
                        id: fresh_uid,
                        init_level: ctxt.var_level,
                    },
                };
                state.names.insert((fresh_uid, kind), var.ident());
                ty = body.subst(&var, &uvar);

                if inst == ForallInst::UnifVar {
                    state.constr.insert(fresh_uid, excluded);
                }
            }
        };
    }

    ty
}

/// Get the type unification variable associated with a given wildcard ID.
fn get_wildcard_var<'ast>(
    table: &mut UnifTable<'ast>,
    var_level: VarLevel,
    wildcard_vars: &mut Vec<UnifType<'ast>>,
    id: VarId,
) -> UnifType<'ast> {
    // If `id` is not in `wildcard_vars`, populate it with fresh vars up to `id`
    if id >= wildcard_vars.len() {
        wildcard_vars.extend((wildcard_vars.len()..=id).map(|_| table.fresh_type_uvar(var_level)));
    }
    wildcard_vars[id].clone()
}

/// Convert a mapping from wildcard ID to type var, into a mapping from wildcard ID to concrete
/// type.
fn wildcard_vars_to_type<'ast>(
    alloc: &'ast AstAlloc,
    wildcard_vars: Vec<UnifType<'ast>>,
    table: &UnifTable<'ast>,
) -> Wildcards<'ast> {
    wildcard_vars
        .into_iter()
        .map(|var| var.into_type(alloc, table))
        .collect()
}

/// A visitor trait for receiving callbacks during typechecking.
pub trait TypecheckVisitor<'ast> {
    /// Record the type of a term.
    ///
    /// It's possible for a single term to be visited multiple times, for example, if type
    /// inference kicks in.
    fn visit_term(&mut self, _ast: &'ast Ast<'ast>, _ty: UnifType<'ast>) {}

    /// Record the type of a bound identifier.
    fn visit_ident(&mut self, _ident: &LocIdent, _new_type: UnifType<'ast>) {}
}

/// A do-nothing `TypeCheckVisitor` for when you don't want one.
impl TypecheckVisitor<'_> for () {}

impl CloneTo for UnifType<'_> {
    type Data<'a> = UnifType<'a>;

    fn clone_to<'to>(data: Self::Data<'_>, dest: &'to AstAlloc) -> Self::Data<'to> {
        match data {
            UnifType::Concrete {
                typ,
                var_levels_data,
            } => UnifType::Concrete {
                typ: dest.clone_from::<UnifTypeUnr>(typ),
                var_levels_data,
            },
            UnifType::Constant(var_id) => UnifType::Constant(var_id),
            UnifType::UnifVar { id, init_level } => UnifType::UnifVar { id, init_level },
        }
    }
}

impl CloneTo for TermEnv<'_> {
    type Data<'a> = TermEnv<'a>;

    fn clone_to<'to>(data: Self::Data<'_>, dest: &'to AstAlloc) -> Self::Data<'to> {
        TermEnv(
            data.0
                .iter_elems()
                .map(|(k, (ast, env))| {
                    (
                        *k,
                        (
                            dest.clone_from::<Ast>(ast.clone()),
                            dest.clone_from::<TermEnv>(env.clone()),
                        ),
                    )
                })
                .collect(),
        )
    }
}

impl CloneTo for UnifEnumRows<'_> {
    type Data<'ast> = UnifEnumRows<'ast>;

    fn clone_to<'to>(data: Self::Data<'_>, dest: &'to AstAlloc) -> Self::Data<'to> {
        match data {
            UnifEnumRows::Concrete {
                erows,
                var_levels_data,
            } => UnifEnumRows::Concrete {
                erows: dest.clone_from::<UnifEnumRowsUnr>(erows),
                var_levels_data,
            },
            UnifEnumRows::Constant(var_id) => UnifEnumRows::Constant(var_id),
            UnifEnumRows::UnifVar { id, init_level } => UnifEnumRows::UnifVar { id, init_level },
        }
    }
}

impl CloneTo for UnifRecordRows<'_> {
    type Data<'a> = UnifRecordRows<'a>;

    fn clone_to<'to>(data: Self::Data<'_>, dest: &'to AstAlloc) -> Self::Data<'to> {
        match data {
            UnifRecordRows::Concrete {
                rrows,
                var_levels_data,
            } => UnifRecordRows::Concrete {
                rrows: dest.clone_from::<UnifRecordRowsUnr>(rrows),
                var_levels_data,
            },
            UnifRecordRows::Constant(var) => UnifRecordRows::Constant(var),
            UnifRecordRows::UnifVar { id, init_level } => {
                UnifRecordRows::UnifVar { id, init_level }
            }
        }
    }
}//! Typing of primitive operations.
use super::*;
use crate::{
    ast::{AstAlloc, builder, primop::PrimOp},
    label::{Polarity, TypeVarData},
    typ::TypeF,
};

use crate::{mk_uty_arrow, mk_uty_enum, mk_uty_record};

pub trait PrimOpType {
    fn primop_type<'ast>(
        &self,
        state: &mut State<'ast, '_>,
        var_level: VarLevel,
    ) -> Result<(Vec<UnifType<'ast>>, UnifType<'ast>), TypecheckError>;
}

impl PrimOpType for PrimOp {
    fn primop_type<'ast>(
        &self,
        state: &mut State<'ast, '_>,
        var_level: VarLevel,
    ) -> Result<(Vec<UnifType<'ast>>, UnifType<'ast>), TypecheckError> {
        Ok(match self {
            // Dyn -> [| 'Number, 'Bool, 'String, 'Enum, 'Function, 'Array, 'Record, 'Label,
            // 'ForeignId, 'Type, 'Other |]
            PrimOp::Typeof => (
                vec![mk_uniftype::dynamic()],
                mk_uty_enum!(
                    "Number",
                    "Bool",
                    "String",
                    "Enum",
                    "Function",
                    "CustomContract",
                    "Array",
                    "Record",
                    "Label",
                    "ForeignId",
                    "Type",
                    "Other"
                ),
            ),
            // Dyn -> [|
            //   'Number Number, 'Bool Bool, 'String String, 'Enum Dyn,
            //   'Function (Dyn -> Dyn), 'Array (Array Dyn), 'Record {_: Dyn}, 'Label Dyn,
            //   'ForeignId Dyn, 'Type Dyn, 'Other Dyn
            // |]
            PrimOp::Cast => (
                vec![mk_uniftype::dynamic()],
                mk_uty_enum!(
                    ("Number", TypeF::Number),
                    ("Bool", TypeF::Bool),
                    ("String", TypeF::String),
                    ("Enum", TypeF::Dyn),
                    ("Function", mk_uty_arrow!(TypeF::Dyn, TypeF::Dyn)),
                    ("CustomContract", TypeF::Dyn),
                    ("Array", mk_uniftype::array(TypeF::Dyn)),
                    ("Record", mk_uniftype::dict(TypeF::Dyn)),
                    ("Label", TypeF::Dyn),
                    ("ForeignId", TypeF::Dyn),
                    ("Type", TypeF::Dyn),
                    ("Other", TypeF::Dyn)
                ),
            ),
            // Bool -> Bool -> Bool
            PrimOp::BoolAnd | PrimOp::BoolOr => (
                vec![mk_uniftype::bool()],
                mk_uty_arrow!(TypeF::Bool, TypeF::Bool),
            ),
            // Bool -> Bool
            PrimOp::BoolNot => (vec![mk_uniftype::bool()], mk_uniftype::bool()),
            // forall a. Dyn -> a
            PrimOp::Blame => {
                let res = state.table.fresh_type_uvar(var_level);

                (vec![mk_uniftype::dynamic()], res)
            }
            // Dyn -> Polarity
            PrimOp::LabelPol => (
                vec![mk_uniftype::dynamic()],
                mk_uty_enum!("Positive", "Negative"),
            ),
            // forall rows. [| ; rows |] -> [| id ; rows |]
            PrimOp::EnumEmbed(id) => {
                let row_var_id = state.table.fresh_erows_var_id(var_level);
                let row = UnifEnumRows::UnifVar {
                    id: row_var_id,
                    init_level: var_level,
                };

                let domain = mk_uty_enum!(; row.clone());
                let codomain = mk_uty_enum!(*id; row);

                (vec![domain], codomain)
            }
            // Morally, Label -> Label
            // Dyn -> Dyn
            PrimOp::LabelFlipPol
            | PrimOp::LabelGoDom
            | PrimOp::LabelGoCodom
            | PrimOp::LabelGoArray
            | PrimOp::LabelGoDict => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            // forall rows a. { id: a | rows} -> a
            PrimOp::RecordStatAccess(id) => {
                let rows = state.table.fresh_rrows_uvar(var_level);
                let res = state.table.fresh_type_uvar(var_level);

                (vec![mk_uty_record!((*id, res.clone()); rows)], res)
            }
            // forall a b. Array a -> (a -> b) -> Array b
            PrimOp::ArrayMap => {
                let a = state.table.fresh_type_uvar(var_level);
                let b = state.table.fresh_type_uvar(var_level);

                let f_type = mk_uty_arrow!(a.clone(), b.clone());
                (
                    vec![mk_uniftype::array(a)],
                    mk_uty_arrow!(f_type, mk_uniftype::array(b)),
                )
            }
            // forall a. Num -> (Num -> a) -> Array a
            PrimOp::ArrayGen => {
                let a = state.table.fresh_type_uvar(var_level);

                let f_type = mk_uty_arrow!(TypeF::Number, a.clone());
                (
                    vec![mk_uniftype::num()],
                    mk_uty_arrow!(f_type, mk_uniftype::array(a)),
                )
            }
            // forall a b. { _ : a} -> (Str -> a -> b) -> { _ : b }
            PrimOp::RecordMap => {
                // Assuming f has type Str -> a -> b,
                // this has type Dict(a) -> Dict(b)

                let a = state.table.fresh_type_uvar(var_level);
                let b = state.table.fresh_type_uvar(var_level);

                let f_type = mk_uty_arrow!(TypeF::String, a.clone(), b.clone());
                (
                    vec![mk_uniftype::dict(a)],
                    mk_uty_arrow!(f_type, mk_uniftype::dict(b)),
                )
            }
            // forall a b. a -> b -> b
            PrimOp::Seq | PrimOp::DeepSeq => {
                let fst = state.table.fresh_type_uvar(var_level);
                let snd = state.table.fresh_type_uvar(var_level);

                (vec![fst], mk_uty_arrow!(snd.clone(), snd))
            }
            // forall a. Array a -> Num
            PrimOp::ArrayLength => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                (vec![mk_uniftype::array(ty_elt)], mk_uniftype::num())
            }
            // forall a. { _: a } -> Array Str
            PrimOp::RecordFields(_) => {
                let ty_a = state.table.fresh_type_uvar(var_level);

                (
                    vec![mk_uniftype::dict(ty_a)],
                    mk_uniftype::array(mk_uniftype::str()),
                )
            }
            // forall a. { _: a } -> Array a
            PrimOp::RecordValues => {
                let ty_a = state.table.fresh_type_uvar(var_level);

                (
                    vec![mk_uniftype::dict(ty_a.clone())],
                    mk_uniftype::array(ty_a),
                )
            }
            // Str -> Str
            PrimOp::StringTrim => (vec![mk_uniftype::str()], mk_uniftype::str()),
            // Str -> Array Str
            PrimOp::StringChars => (
                vec![mk_uniftype::str()],
                mk_uniftype::array(mk_uniftype::str()),
            ),
            // Str -> Str
            PrimOp::StringUppercase => (vec![mk_uniftype::str()], mk_uniftype::str()),
            // Str -> Str
            PrimOp::StringLowercase => (vec![mk_uniftype::str()], mk_uniftype::str()),
            // Str -> Num
            PrimOp::StringLength => (vec![mk_uniftype::str()], mk_uniftype::num()),
            // Dyn -> Str
            PrimOp::ToString => (vec![mk_uniftype::dynamic()], mk_uniftype::str()),
            // Str -> Num
            PrimOp::NumberFromString => (vec![mk_uniftype::str()], mk_uniftype::num()),
            // Str -> < | a> for a rigid type variable a
            PrimOp::EnumFromString => (
                vec![mk_uniftype::str()],
                mk_uty_enum!(; state.table.fresh_erows_const(var_level)),
            ),
            // Str -> Str -> Bool
            PrimOp::StringIsMatch => (
                vec![mk_uniftype::str()],
                mk_uty_arrow!(mk_uniftype::str(), mk_uniftype::bool()),
            ),
            // Str -> Str -> {matched: Str, index: Num, groups: Array Str}
            PrimOp::StringFind => (
                vec![mk_uniftype::str()],
                mk_uty_arrow!(
                    mk_uniftype::str(),
                    mk_uty_record!(
                        ("matched", TypeF::String),
                        ("index", TypeF::Number),
                        ("groups", mk_uniftype::array(TypeF::String))
                    )
                ),
            ),
            // String -> String -> Array { matched: String, index: Number, groups: Array String }
            PrimOp::StringFindAll => (
                vec![mk_uniftype::str()],
                mk_uty_arrow!(
                    mk_uniftype::str(),
                    mk_uniftype::array(mk_uty_record!(
                        ("matched", TypeF::String),
                        ("index", TypeF::Number),
                        ("groups", mk_uniftype::array(TypeF::String))
                    ))
                ),
            ),
            // Dyn -> Dyn
            PrimOp::Force { .. } => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            PrimOp::RecordEmptyWithTail => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            // forall a. { _ : a} -> { _ : a }
            PrimOp::RecordFreeze => {
                let dict = mk_uniftype::dict(state.table.fresh_type_uvar(var_level));
                (vec![dict.clone()], dict)
            }
            // forall a. Str -> a -> a
            PrimOp::Trace => {
                let ty = state.table.fresh_type_uvar(var_level);
                (vec![mk_uniftype::str()], mk_uty_arrow!(ty.clone(), ty))
            }
            // Morally: Lbl -> Lbl
            // Actual: Dyn -> Dyn
            PrimOp::LabelPushDiag => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            // Str -> Dyn
            #[cfg(feature = "nix-experimental")]
            PrimOp::EvalNix => (vec![mk_uniftype::str()], mk_uniftype::dynamic()),
            // Because the tag isn't fixed, we can't really provide a proper static type for this
            // primop.
            // This isn't a problem, as this operator is mostly internal and pattern matching should be
            // used to destructure enum variants.
            // Dyn -> Dyn
            PrimOp::EnumGetArg => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            // String -> (Dyn -> Dyn)
            PrimOp::EnumMakeVariant => (
                vec![mk_uniftype::str()],
                mk_uniftype::arrow(mk_uniftype::dynamic(), mk_uniftype::dynamic()),
            ),
            // Same as `EnumGetArg` just above.
            // Dyn -> Dyn
            PrimOp::EnumGetTag => (vec![mk_uniftype::dynamic()], mk_uniftype::dynamic()),
            // Note that is_variant breaks parametricity, so it can't get a polymorphic type.
            // Dyn -> Bool
            PrimOp::EnumIsVariant => (vec![mk_uniftype::dynamic()], mk_uniftype::bool()),
            // <custom_contract_type()> -> Dyn
            PrimOp::ContractCustom => (
                vec![custom_contract_type(state.ast_alloc)],
                mk_uniftype::dynamic(),
            ),
            // Number -> Number
            PrimOp::NumberCos
            | PrimOp::NumberSin
            | PrimOp::NumberTan
            | PrimOp::NumberArcCos
            | PrimOp::NumberArcSin
            | PrimOp::NumberArcTan => (vec![mk_uniftype::num()], mk_uniftype::num()),

            // Binary ops

            // Number -> Number -> Number
            PrimOp::Plus | PrimOp::Sub | PrimOp::Mult | PrimOp::Div | PrimOp::Modulo => (
                vec![mk_uniftype::num(), mk_uniftype::num()],
                mk_uniftype::num(),
            ),
            // Sym -> Dyn -> Dyn -> Dyn
            PrimOp::Seal => (
                vec![mk_uniftype::sym(), mk_uniftype::dynamic()],
                mk_uty_arrow!(TypeF::Dyn, TypeF::Dyn),
            ),
            // String -> String -> String
            PrimOp::StringConcat => (
                vec![mk_uniftype::str(), mk_uniftype::str()],
                mk_uniftype::str(),
            ),
            // Ideally: Contract -> Label -> Dyn -> Dyn
            // Currently: Dyn -> Dyn -> (Dyn -> Dyn)
            PrimOp::ContractApply => (
                vec![mk_uniftype::dynamic(), mk_uniftype::dynamic()],
                mk_uty_arrow!(mk_uniftype::dynamic(), mk_uniftype::dynamic()),
            ),
            // Ideally: Contract -> Label -> Dyn -> <custom_contract_ret_type()>
            // Currently: Dyn -> Dyn -> (Dyn -> <custom_contract_ret_type()>)
            PrimOp::ContractCheck => (
                vec![mk_uniftype::dynamic(), mk_uniftype::dynamic()],
                mk_uty_arrow!(
                    mk_uniftype::dynamic(),
                    custom_contract_ret_type(state.ast_alloc)
                ),
            ),
            // Ideally: <error_data_type()> -> Label -> Dyn
            // Currently: <error_data_type()> -> Dyn -> Dyn
            PrimOp::LabelWithErrorData => (
                vec![error_data_type(state.ast_alloc), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // Sym -> Dyn -> Dyn -> Dyn
            PrimOp::Unseal => (
                vec![mk_uniftype::sym(), mk_uniftype::dynamic()],
                mk_uty_arrow!(TypeF::Dyn, TypeF::Dyn),
            ),
            // forall a b. a -> b -> Bool
            PrimOp::Eq => (
                vec![
                    state.table.fresh_type_uvar(var_level),
                    state.table.fresh_type_uvar(var_level),
                ],
                mk_uniftype::bool(),
            ),
            // Num -> Num -> Bool
            PrimOp::LessThan | PrimOp::LessOrEq | PrimOp::GreaterThan | PrimOp::GreaterOrEq => (
                vec![mk_uniftype::num(), mk_uniftype::num()],
                mk_uniftype::bool(),
            ),
            // Str -> Dyn -> Dyn
            PrimOp::LabelGoField => (
                vec![mk_uniftype::str(), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // forall a. Str -> { _ : a} -> a
            PrimOp::RecordGet => {
                let res = state.table.fresh_type_uvar(var_level);

                (
                    vec![mk_uniftype::str(), mk_uniftype::dict(res.clone())],
                    res,
                )
            }
            // forall a. Str -> {_ : a} -> a -> {_ : a}
            PrimOp::RecordInsert(_) => {
                let res = state.table.fresh_type_uvar(var_level);
                (
                    vec![mk_uniftype::str(), mk_uniftype::dict(res.clone())],
                    mk_uty_arrow!(res.clone(), mk_uniftype::dict(res)),
                )
            }
            // forall a. Str -> { _ : a } -> { _ : a}
            PrimOp::RecordRemove(_) => {
                let res = state.table.fresh_type_uvar(var_level);
                (
                    vec![mk_uniftype::str(), mk_uniftype::dict(res.clone())],
                    mk_uniftype::dict(res),
                )
            }
            // forall a. Str -> {_: a} -> Bool
            PrimOp::RecordHasField(_) => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                (
                    vec![mk_uniftype::str(), mk_uniftype::dict(ty_elt)],
                    mk_uniftype::bool(),
                )
            }
            // forall a. Str -> {_: a} -> Bool
            PrimOp::RecordFieldIsDefined(_) => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                (
                    vec![mk_uniftype::str(), mk_uniftype::dict(ty_elt)],
                    mk_uniftype::bool(),
                )
            }
            // forall a. Array a -> Array a -> Array a
            PrimOp::ArrayConcat => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                let ty_array = mk_uniftype::array(ty_elt);
                (vec![ty_array.clone(), ty_array.clone()], ty_array)
            }
            // forall a. Array a -> Num -> a
            PrimOp::ArrayAt => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                (
                    vec![mk_uniftype::array(ty_elt.clone()), mk_uniftype::num()],
                    ty_elt,
                )
            }
            // Dyn -> Dyn -> Dyn
            PrimOp::Merge(_) => (
                vec![mk_uniftype::dynamic(), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // <Md5, Sha1, Sha256, Sha512> -> Str -> Str
            PrimOp::Hash => (
                vec![
                    mk_uty_enum!("Md5", "Sha1", "Sha256", "Sha512"),
                    mk_uniftype::str(),
                ],
                mk_uniftype::str(),
            ),
            // forall a. [| 'Json, 'Toml, 'Yaml, 'YamlDocuments |] -> a -> String
            PrimOp::Serialize => {
                let ty_input = state.table.fresh_type_uvar(var_level);
                (
                    vec![
                        mk_uty_enum!("Json", "Toml", "Yaml", "YamlDocuments"),
                        ty_input,
                    ],
                    mk_uniftype::str(),
                )
            }
            // [| 'Json, 'Toml, 'Yaml, 'YamlDocuments |] -> String -> Dyn
            PrimOp::Deserialize => (
                vec![
                    mk_uty_enum!("Json", "Toml", "Yaml", "YamlDocuments"),
                    mk_uniftype::str(),
                ],
                mk_uniftype::dynamic(),
            ),
            // Num -> Num -> Num
            PrimOp::NumberArcTan2 | PrimOp::NumberLog | PrimOp::Pow => (
                vec![mk_uniftype::num(), mk_uniftype::num()],
                mk_uniftype::num(),
            ),
            // Str -> Str -> Bool
            PrimOp::StringContains => (
                vec![mk_uniftype::str(), mk_uniftype::str()],
                mk_uniftype::bool(),
            ),
            // Str -> Str -> <Lesser, Equal, Greater>
            PrimOp::StringCompare => (
                vec![mk_uniftype::str(), mk_uniftype::str()],
                mk_uty_enum!("Lesser", "Equal", "Greater"),
            ),
            // Str -> Str -> Array Str
            PrimOp::StringSplit => (
                vec![mk_uniftype::str(), mk_uniftype::str()],
                mk_uniftype::array(TypeF::String),
            ),
            // [| 'Standard, 'UrlSafe, 'NoPad, 'UrlSafeNoPad |] -> String -> String
            PrimOp::StringBase64Encode => (
                vec![
                    mk_uty_enum!("Standard", "UrlSafe", "NoPad", "UrlSafeNoPad"),
                    mk_uniftype::str(),
                ],
                mk_uniftype::str(),
            ),
            // [| 'Standard, 'UrlSafe, 'NoPad, 'UrlSafeNoPad |] -> String -> [| 'Ok String, 'Error { message : String } |]
            PrimOp::StringBase64Decode => (
                vec![
                    mk_uty_enum!("Standard", "UrlSafe", "NoPad", "UrlSafeNoPad"),
                    mk_uniftype::str(),
                ],
                mk_uty_enum!(
                    ("Ok", TypeF::String),
                    ("Error", mk_uty_record!(("message", TypeF::String)))
                ),
            ),
            // The first argument is a contract, the second is a label.
            // forall a. Dyn -> Dyn -> Array a -> Array a
            PrimOp::ContractArrayLazyApp => {
                let ty_elt = state.table.fresh_type_uvar(var_level);
                let ty_array = mk_uniftype::array(ty_elt);
                (
                    vec![mk_uniftype::dynamic(), mk_uniftype::dynamic()],
                    mk_uty_arrow!(ty_array.clone(), ty_array),
                )
            }
            // The first argument is a label, the third is a contract.
            // forall a. Dyn -> {_: a} -> Dyn -> {_: a}
            PrimOp::ContractRecordLazyApp => {
                let ty_field = state.table.fresh_type_uvar(var_level);
                let ty_dict = mk_uniftype::dict(ty_field);
                (
                    vec![mk_uniftype::dynamic(), ty_dict.clone()],
                    mk_uty_arrow!(mk_uniftype::dynamic(), ty_dict),
                )
            }
            // Morally: Str -> Lbl -> Lbl
            // Actual: Str -> Dyn -> Dyn
            PrimOp::LabelWithMessage => (
                vec![mk_uniftype::str(), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // Morally: Array Str -> Lbl -> Lbl
            // Actual: Array Str -> Dyn -> Dyn
            PrimOp::LabelWithNotes => (
                vec![mk_uniftype::array(TypeF::String), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // Morally: Str -> Lbl -> Lbl
            // Actual: Str -> Dyn -> Dyn
            PrimOp::LabelAppendNote => (
                vec![mk_uniftype::str(), mk_uniftype::dynamic()],
                mk_uniftype::dynamic(),
            ),
            // Morally: Sym -> Lbl -> TypeVarData
            // Actual: Sym -> Dyn -> TypeVarData
            PrimOp::LabelLookupTypeVar => (
                vec![mk_uniftype::sym(), mk_uniftype::dynamic()],
                TypeVarData::unif_type(),
            ),
            // {_ : a} -> {_ : a}
            // -> {
            //  left_only: {_ : a},
            //  right_only: {_ : a},
            //  left_center: {_ : a},
            //  right_center: {_ : a},
            // }
            PrimOp::RecordSplitPair => {
                let elt = state.table.fresh_type_uvar(var_level);
                let dict = mk_uniftype::dict(elt.clone());

                let split_result = mk_uty_record!(
                    ("left_only", dict.clone()),
                    ("right_only", dict.clone()),
                    ("left_center", dict.clone()),
                    ("right_center", dict.clone())
                );

                (vec![dict.clone(), dict], split_result)
            }
            // {_ : a} -> {_ : a} -> {_ : a}
            PrimOp::RecordDisjointMerge => {
                let elt = state.table.fresh_type_uvar(var_level);
                let dict = mk_uniftype::dict(elt.clone());

                (vec![dict.clone(), dict.clone()], dict)
            }
            // Str -> Str -> Str -> Str
            PrimOp::StringReplace | PrimOp::StringReplaceRegex => (
                vec![mk_uniftype::str(), mk_uniftype::str(), mk_uniftype::str()],
                mk_uniftype::str(),
            ),
            // Str -> Num -> Num -> Str
            PrimOp::StringSubstr => (
                vec![mk_uniftype::str(), mk_uniftype::num(), mk_uniftype::num()],
                mk_uniftype::str(),
            ),
            // Dyn -> Dyn -> Dyn -> Dyn -> Dyn
            PrimOp::RecordSealTail => (
                vec![
                    mk_uniftype::dynamic(),
                    mk_uniftype::dynamic(),
                    mk_uniftype::dict(mk_uniftype::dynamic()),
                    mk_uniftype::dict(mk_uniftype::dynamic()),
                ],
                mk_uniftype::dynamic(),
            ),
            // Dyn -> Dyn -> Dyn -> Dyn
            PrimOp::RecordUnsealTail => (
                vec![
                    mk_uniftype::dynamic(),
                    mk_uniftype::dynamic(),
                    mk_uniftype::dict(mk_uniftype::dynamic()),
                ],
                mk_uniftype::dynamic(),
            ),
            // Num -> Num -> Array a -> Array a
            PrimOp::ArraySlice => {
                let element_type = state.table.fresh_type_uvar(var_level);

                (
                    vec![
                        mk_uniftype::num(),
                        mk_uniftype::num(),
                        mk_uniftype::array(element_type.clone()),
                    ],
                    mk_uniftype::array(element_type),
                )
            }
            // Morally: Label -> Record -> Record -> Record
            // Actual: Dyn -> Dyn -> Dyn -> Dyn
            PrimOp::MergeContract => (
                vec![
                    mk_uniftype::dynamic(),
                    mk_uniftype::dynamic(),
                    mk_uniftype::dynamic(),
                ],
                mk_uniftype::dynamic(),
            ),
            // Morally: Sym -> Polarity -> Lbl -> Lbl
            // Actual: Sym -> Polarity -> Dyn -> Dyn
            PrimOp::LabelInsertTypeVar => (
                vec![
                    mk_uniftype::sym(),
                    Polarity::unif_type(),
                    mk_uniftype::dynamic(),
                ],
                mk_uniftype::dynamic(),
            ),
        })
    }
}

/// The type of a custom contract. In nickel syntax, the returned type is:
///
/// ```nickel
/// Dyn -> Dyn -> [|
///   'Ok Dyn,
///   'Error { message | String | optional, notes | Array String | optional }
/// |]
/// ```
pub fn custom_contract_type(alloc: &AstAlloc) -> UnifType<'_> {
    mk_uty_arrow!(
        mk_uniftype::dynamic(),
        mk_uniftype::dynamic(),
        custom_contract_ret_type(alloc)
    )
}

/// The return type of a custom contract. See [custom_contract_type].
///
/// ```nickel
/// [|
///   'Ok Dyn,
///   'Error { message | String | optional, notes | Array String | optional }
/// |]
/// ```
pub fn custom_contract_ret_type(alloc: &AstAlloc) -> UnifType<'_> {
    mk_uty_enum!(
        ("Ok", mk_uniftype::dynamic()),
        ("Error", error_data_type(alloc))
    )
}

/// The type of error data that can be returned by a custom contract:
///
/// ```nickel
/// {
///   message
///     | String
///     | optional,
///   notes
///     | Array String
///     | optional
/// }
/// ```
fn error_data_type(alloc: &AstAlloc) -> UnifType<'_> {
    let error_data = builder::Record::new()
        .field("message")
        .optional(true)
        .contract(TypeF::String)
        .no_value(alloc)
        .field("notes")
        .contract(TypeF::Array(alloc.alloc(Type::from(TypeF::String))))
        .optional(true)
        .no_value(alloc)
        .field("blame_location")
        .optional(true)
        .contract(TypeF::Dyn)
        .no_value(alloc);

    UnifType::concrete(TypeF::Contract((
        alloc.alloc(error_data.build(alloc)),
        TermEnv::new(),
    )))
}use crate::{
    ast::pattern::*,
    identifier::{Ident, LocIdent},
    mk_uty_record_row,
    typ::{EnumRowsF, RecordRowsF, TypeF},
};

use super::*;

/// A list of pattern variables and their associated type.
pub type TypeBindings<'ast> = Vec<(LocIdent, UnifType<'ast>)>;

/// An element of a pattern path. A pattern path is a sequence of steps that can be used to
/// uniquely locate a sub-pattern within a pattern.
///
/// For example, in the pattern `{foo={bar='Baz arg}}`:
///
/// - The path of the full pattern within itself is the empty path.
/// - The path of the `arg` pattern is `[Field("foo"), Field("bar"), Variant]`.
#[derive(Debug, Clone, PartialEq, Eq, Copy, Hash)]
pub enum PatternPathElem {
    Field(Ident),
    Array(usize),
    Variant,
}

pub type PatternPath = Vec<PatternPathElem>;

/// The working state of [PatternType::pattern_types_inj].
pub(super) struct PatTypeState<'ast, 'a> {
    /// The list of pattern variables introduced so far and their inferred type.
    bindings: &'a mut TypeBindings<'ast>,
    /// The list of enum row tail variables that are left open when typechecking a match expression.
    enum_open_tails: &'a mut Vec<(PatternPath, UnifEnumRows<'ast>)>,
    /// Record, as a field path, the position of wildcard pattern encountered in a record. This
    /// impact the final type of the pattern, as a wildcard pattern makes the corresponding row
    /// open.
    wildcard_pat_paths: &'a mut HashSet<PatternPath>,
}

/// Return value of [PatternTypes::pattern_types], which stores the overall type of a pattern,
/// together with the type of its bindings and additional information for the typechecking of match
/// expressions.
#[derive(Debug, Clone)]
pub struct PatternTypeData<'ast, T> {
    /// The type of the pattern.
    pub typ: T,
    /// A list of pattern variables and their associated type.
    pub bindings: Vec<(LocIdent, UnifType<'ast>)>,
    /// A list of enum row tail variables that are left open when typechecking a match expression.
    ///
    /// Those variables (or their descendent in a row type) might need to be closed after the type
    /// of all the patterns of a match expression have been unified, depending on the presence of a
    /// wildcard or an _any_ pattern. The path of the corresponding sub-pattern is stored as well,
    /// since enum patterns in different positions might need different treatment. For example:
    ///
    /// ```nickel
    /// match {
    ///   'Foo ('Bar x) => <exp>,
    ///   'Foo ('Qux x) => <exp>,
    ///   _ => <exp>
    /// }
    /// ```
    ///
    /// The presence of a default case means that the row variables of top-level enum patterns
    /// might stay open. However, the type corresponding to the sub-patterns `'Bar x` and `'Qux x`
    /// must be closed, because this match expression can't handle `'Foo ('Other 0)`. The type of
    /// the match expression is thus `[| 'Foo [| 'Bar: a, 'Qux: b |]; c|] -> d`.
    ///
    /// Wildcards and any patterns can occur anywhere, so the previous case can also happen within
    /// a record pattern:
    ///
    /// ```nickel
    /// match {
    ///   {foo = 'Bar x} => <exp>,
    ///   {foo = 'Qux x} => <exp>,
    ///   {foo = _} => <exp>,
    /// }
    /// ```
    ///
    /// Similarly, the type of the match expression is `{ foo: [| 'Bar: a, 'Qux: b; c |] } -> e`.
    ///
    /// See [^typechecking-match-expression] in [typecheck] for more details.
    pub enum_open_tails: Vec<(PatternPath, UnifEnumRows<'ast>)>,
    /// Paths of the occurrence of wildcard or any patterns encountered. This is used to determine
    /// which tails in [Self::enum_open_tails] should be left open.
    pub wildcard_occurrences: HashSet<PatternPath>,
}
/// Close all the enum row types left open when typechecking a match expression. Special case of
/// `close_enums` for a single destructuring pattern (thus, where wildcard occurrences are not
/// relevant).
pub fn close_all_enums<'ast>(
    enum_open_tails: Vec<(PatternPath, UnifEnumRows<'ast>)>,
    state: &mut State<'ast, '_>,
) {
    close_enums(enum_open_tails, &HashSet::new(), state);
}

/// Close all the enum row types left open when typechecking a match expression, unless we recorded
/// a wildcard pattern somewhere in the same position.
pub fn close_enums<'ast>(
    enum_open_tails: Vec<(PatternPath, UnifEnumRows<'ast>)>,
    wildcard_occurrences: &HashSet<PatternPath>,
    state: &mut State<'ast, '_>,
) {
    // Note: both for this function and for `close_enums`, for a given pattern path, all the tail
    // variables should ultimately be part of the same enum type, and we just need to close it
    // once. We might thus save a bit of work if we kept equivalence classes of tuples (path, tail)
    // (equality being given by the equality of paths). Closing one arbitrary member per class
    // should then be enough. It's not obvious that this would make any difference in practice,
    // though.
    for tail in enum_open_tails
        .into_iter()
        .filter_map(|(path, tail)| (!wildcard_occurrences.contains(&path)).then_some(tail))
    {
        close_enum(tail, state);
    }
}

/// Take an enum row, find its final tail (in case of multiple indirection through unification
/// variables) and close it if it's a free unification variable.
fn close_enum<'ast>(tail: UnifEnumRows<'ast>, state: &mut State<'ast, '_>) {
    let root = tail.into_root(state.table);

    if let UnifEnumRows::UnifVar { id, .. } = root {
        // We don't need to perform any variable level checks when unifying a free
        // unification variable with a ground type
        state
            .table
            .assign_erows(id, UnifEnumRows::concrete(EnumRowsF::Empty));
    } else {
        let tail = root.iter().find_map(|row_item| {
            match row_item {
                EnumRowsElt::TailUnifVar { id, init_level } => {
                    Some(UnifEnumRows::UnifVar { id, init_level })
                }
                EnumRowsElt::TailVar(_) | EnumRowsElt::TailConstant(_) => {
                    // While unifying open enum rows coming from a pattern, we expect to always
                    // extend the enum row with other open rows such that the result should always
                    // stay open. So we expect to find a unification variable at the end of the
                    // enum row.
                    //
                    // But in fact, all the tails for a given pattern path will point to the same
                    // enum row, so it might have been closed already by a previous call to
                    // `close_enum`, and that's fine. On the other hand, we should never encounter
                    // a rigid type variable here (or a non-substituted type variable, although it
                    // has nothing to do with patterns), so if we reach this point, something is
                    // wrong with the typechecking of match expression.
                    debug_assert!(false);

                    None
                }
                _ => None,
            }
        });

        if let Some(tail) = tail {
            close_enum(tail, state)
        }
    }
}

pub(super) trait PatternTypes<'ast> {
    /// The type produced by the pattern. Depending on the nature of the pattern, this type may
    /// vary: for example, a record pattern will produce record rows, while a general pattern will
    /// produce a general [super::UnifType<'ast>]
    type PatType;

    /// Builds the type associated to the whole pattern, as well as the types associated to each
    /// binding introduced by this pattern. When matching a value against a pattern in a statically
    /// typed code, either by destructuring or by applying a match expression, the type of the
    /// value will be checked against the type generated by `pattern_type` and the bindings will be
    /// added to the type environment.
    ///
    /// The type of each "leaf" identifier will be assigned based on the `mode` argument. The
    /// current possibilities are for each leaf to have type `Dyn`, to use their explicit type
    /// annotation if any, or to be assigned a fresh unification variable.
    fn pattern_types(
        &self,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<PatternTypeData<'ast, Self::PatType>, TypecheckError> {
        let mut bindings = Vec::new();
        let mut enum_open_tails = Vec::new();
        let mut wildcard_pat_paths = HashSet::new();

        let typ = self.pattern_types_inj(
            &mut PatTypeState {
                bindings: &mut bindings,
                enum_open_tails: &mut enum_open_tails,
                wildcard_pat_paths: &mut wildcard_pat_paths,
            },
            Vec::new(),
            state,
            ctxt,
            mode,
        )?;

        Ok(PatternTypeData {
            typ,
            bindings,
            enum_open_tails,
            wildcard_occurrences: wildcard_pat_paths,
        })
    }

    /// Same as `pattern_types`, but inject the bindings in a working vector instead of returning
    /// them. Implementors should implement this method whose signature avoids creating and
    /// combining many short-lived vectors when walking recursively through a pattern.
    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError>;
}

impl<'ast> PatternTypes<'ast> for RecordPattern<'ast> {
    type PatType = UnifRecordRows<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        let tail = if self.is_open() {
            match mode {
                // We use a dynamic tail here since we're in walk mode,
                // but if/when we remove dynamic record tails this could
                // likely be made an empty tail with no impact.
                TypecheckMode::Walk => mk_uty_record_row!(; RecordRowsF::TailDyn),
                TypecheckMode::Enforce => state.table.fresh_rrows_uvar(ctxt.var_level),
            }
        } else {
            UnifRecordRows::Concrete {
                rrows: RecordRowsF::Empty,
                var_levels_data: VarLevelsData::new_no_uvars(),
            }
        };

        if let TailPattern::Capture(rest) = self.tail {
            pt_state
                .bindings
                .push((rest, UnifType::concrete(TypeF::Record(tail.clone()))));
        }

        self.patterns
            .iter()
            .map(|field_pat| field_pat.pattern_types_inj(pt_state, path.clone(), state, ctxt, mode))
            .try_fold(tail, |tail, row: Result<UnifRecordRow, TypecheckError>| {
                Ok(UnifRecordRows::concrete(RecordRowsF::Extend {
                    row: row?,
                    tail: Box::new(tail),
                }))
            })
    }
}

impl<'ast> PatternTypes<'ast> for ArrayPattern<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        // We allocate a fresh unification variable and unify it with the type of each element
        // pattern in enforce mode.
        //
        // In walk mode, we still iterate through the sub patterns to populate the bindings, but we
        // eschew unification, which might fail if the elements are heterogeneous (say two record
        // patterns with different shapes). In this case, we just return `Dyn` as the element type.
        let elem_type = match mode {
            TypecheckMode::Enforce => state.table.fresh_type_uvar(ctxt.var_level),
            TypecheckMode::Walk => mk_uniftype::dynamic(),
        };

        for (idx, subpat) in self.patterns.iter().enumerate() {
            let mut path = path.clone();
            path.push(PatternPathElem::Array(idx));

            let subpat_type = subpat.pattern_types_inj(pt_state, path, state, ctxt, mode)?;

            if let TypecheckMode::Enforce = mode {
                elem_type
                    .clone()
                    .unify(subpat_type, state, ctxt)
                    .map_err(|e| e.into_typecheck_err(state, self.pos))?;
            }
        }

        if let TailPattern::Capture(rest) = &self.tail {
            pt_state
                .bindings
                .push((*rest, mk_uniftype::array(elem_type.clone())));
        }

        Ok(elem_type)
    }
}

impl<'ast> PatternTypes<'ast> for Pattern<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        let typ = self
            .data
            .pattern_types_inj(pt_state, path, state, ctxt, mode)?;

        if let Some(alias) = self.alias {
            pt_state.bindings.push((alias, typ.clone()));
        }

        Ok(typ)
    }
}

// Depending on the mode, returns the type affected to patterns that match any value (`Any` and
// `Wildcard`): `Dyn` in walk mode, a fresh unification variable in enforce mode.
fn any_type<'ast>(
    mode: TypecheckMode,
    state: &mut State<'ast, '_>,
    ctxt: &Context<'ast>,
) -> UnifType<'ast> {
    match mode {
        TypecheckMode::Walk => mk_uniftype::dynamic(),
        TypecheckMode::Enforce => state.table.fresh_type_uvar(ctxt.var_level),
    }
}

impl<'ast> PatternTypes<'ast> for PatternData<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        match self {
            PatternData::Wildcard => {
                pt_state.wildcard_pat_paths.insert(path);
                Ok(any_type(mode, state, ctxt))
            }
            PatternData::Any(id) => {
                pt_state.wildcard_pat_paths.insert(path);
                let typ = any_type(mode, state, ctxt);
                pt_state.bindings.push((*id, typ.clone()));

                Ok(typ)
            }
            PatternData::Record(record_pat) => Ok(UnifType::concrete(TypeF::Record(
                record_pat.pattern_types_inj(pt_state, path, state, ctxt, mode)?,
            ))),
            PatternData::Array(array_pat) => Ok(mk_uniftype::array(
                array_pat.pattern_types_inj(pt_state, path, state, ctxt, mode)?,
            )),
            PatternData::Enum(enum_pat) => {
                let row = enum_pat.pattern_types_inj(pt_state, path.clone(), state, ctxt, mode)?;
                // We elaborate the type `[| row; a |]` where `a` is a fresh enum rows unification
                // variable registered in `enum_open_tails`.
                let tail = state.table.fresh_erows_uvar(ctxt.var_level);
                pt_state.enum_open_tails.push((path, tail.clone()));

                Ok(UnifType::concrete(TypeF::Enum(UnifEnumRows::concrete(
                    EnumRowsF::Extend {
                        row,
                        tail: Box::new(tail),
                    },
                ))))
            }
            PatternData::Constant(constant_pat) => {
                constant_pat.pattern_types_inj(pt_state, path, state, ctxt, mode)
            }
            PatternData::Or(or_pat) => or_pat.pattern_types_inj(pt_state, path, state, ctxt, mode),
        }
    }
}

impl<'ast> PatternTypes<'ast> for ConstantPattern<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        self.data
            .pattern_types_inj(pt_state, path, state, ctxt, mode)
    }
}

impl<'ast> PatternTypes<'ast> for ConstantPatternData<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        _pt_state: &mut PatTypeState<'ast, '_>,
        _path: PatternPath,
        _state: &mut State,
        _ctxt: &Context,
        _mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        Ok(match self {
            ConstantPatternData::Bool(_) => UnifType::concrete(TypeF::Bool),
            ConstantPatternData::Number(_) => UnifType::concrete(TypeF::Number),
            ConstantPatternData::String(_) => UnifType::concrete(TypeF::String),
            ConstantPatternData::Null => UnifType::concrete(TypeF::Dyn),
        })
    }
}

impl<'ast> PatternTypes<'ast> for FieldPattern<'ast> {
    type PatType = UnifRecordRow<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        mut path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        path.push(PatternPathElem::Field(self.matched_id.ident()));

        // If there is a static type annotation in a nested record patterns then we need to unify
        // them with the pattern type we've built to ensure (1) that they're mutually compatible
        // and (2) that we assign the annotated types to the right unification variables.
        let ty_row = match (&self.annotation.typ, &self.pattern.data, mode) {
            // However, in walk mode, we only do that when the nested pattern isn't a leaf (i.e.
            // `Any` or `Wildcard`) for backward-compatibility reasons.
            //
            // Before this function was refactored, Nickel has been allowing things like `let {foo
            // : Number} = {foo = 1} in foo` in walk mode, which would fail to typecheck with the
            // generic approach: the pattern is parsed as `{foo : Number = foo}`, the second
            // occurrence of `foo` gets type `Dyn` in walk mode, but `Dyn` fails to unify with
            // `Number`. In this case, we don't recursively call `pattern_types_inj` in the first
            // place and just declare that the type of `foo` is `Number`.
            //
            // This special case should probably be ruled out, requiring the users to use `let {foo
            // | Number}` instead, at least outside of a statically typed code block. But before
            // this happens, we special case the old behavior and eschew unification.
            (Some(annot_ty), PatternData::Any(id), TypecheckMode::Walk) => {
                let ty_row = UnifType::from_type(annot_ty.clone(), &ctxt.term_env);
                pt_state.bindings.push((*id, ty_row.clone()));
                ty_row
            }
            (Some(annot_ty), PatternData::Wildcard, TypecheckMode::Walk) => {
                UnifType::from_type(annot_ty.clone(), &ctxt.term_env)
            }
            (Some(annot_ty), _, _) => {
                let pos = annot_ty.pos;
                let annot_uty = UnifType::from_type(annot_ty.clone(), &ctxt.term_env);

                let ty_row = self
                    .pattern
                    .pattern_types_inj(pt_state, path, state, ctxt, mode)?;

                ty_row
                    .clone()
                    .unify(annot_uty, state, ctxt)
                    .map_err(|e| e.into_typecheck_err(state, pos))?;

                ty_row
            }
            _ => self
                .pattern
                .pattern_types_inj(pt_state, path, state, ctxt, mode)?,
        };

        Ok(UnifRecordRow {
            id: self.matched_id,
            typ: Box::new(ty_row),
        })
    }
}

impl<'ast> PatternTypes<'ast> for EnumPattern<'ast> {
    type PatType = UnifEnumRow<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        mut path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        let typ_arg = self
            .pattern
            .as_ref()
            .map(|pat| {
                path.push(PatternPathElem::Variant);
                pat.pattern_types_inj(pt_state, path, state, ctxt, mode)
            })
            .transpose()?
            .map(Box::new);

        Ok(UnifEnumRow {
            id: self.tag,
            typ: typ_arg,
        })
    }
}

impl<'ast> PatternTypes<'ast> for OrPattern<'ast> {
    type PatType = UnifType<'ast>;

    fn pattern_types_inj(
        &self,
        pt_state: &mut PatTypeState<'ast, '_>,
        path: PatternPath,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
        mode: TypecheckMode,
    ) -> Result<Self::PatType, TypecheckError> {
        // When checking a sequence of or-patterns, we must combine their open tails and wildcard
        // pattern positions - in fact, when typechecking a whole match expression, this is exactly
        // what the typechecker is doing: it merges all those data. And a match expression is,
        // similarly to an or-pattern, a disjunction of patterns.
        //
        // However, the treatment of bindings is different. If any of the branch in an or-pattern
        // matches, the same code path (the match branch) will be run, and thus they must agree on
        // pattern variables. Which means:
        //
        // 1. All pattern branches must have the same set of variables
        // 2. Each variable must have a compatible type across all or-pattern branches
        //
        // To do so, we call to `pattern_types_inj` with a fresh vector of bindings, so that we can
        // post-process them afterward (enforcing 1. and 2. above) before actually adding them to
        // the original overall bindings.
        //
        // `bindings` stores, for each or-pattern branch, the inferred type of the whole branch,
        // the generated bindings and the position (the latter for error reporting).
        let bindings: Result<Vec<_>, _> = self
            .patterns
            .iter()
            .map(|pat| -> Result<_, TypecheckError> {
                let mut fresh_bindings = Vec::new();

                let mut local_state = PatTypeState {
                    bindings: &mut fresh_bindings,
                    enum_open_tails: pt_state.enum_open_tails,
                    wildcard_pat_paths: pt_state.wildcard_pat_paths,
                };

                let typ =
                    pat.pattern_types_inj(&mut local_state, path.clone(), state, ctxt, mode)?;

                // We sort the bindings to check later that they are the same in all branches
                fresh_bindings.sort_by_key(|(id, _typ)| *id);

                Ok((typ, fresh_bindings, pat.pos))
            })
            .collect();

        let mut it = bindings?.into_iter();

        // We need a reference set of variables (and their types for unification). We just pick the
        // first bindings of the list.
        let Some((model_typ, model, _pos)) = it.next() else {
            // We should never generate empty `or` sequences (it's not possible to write them in
            // the source language, at least). However, it doesn't cost much to support them: such
            // a pattern never matches anything. Thus, we return the bottom type encoded as `forall
            // a. a`.
            let free_var = Ident::from("a");

            return Ok(UnifType::concrete(TypeF::Forall {
                var: free_var.into(),
                var_kind: VarKind::Type,
                body: Box::new(UnifType::concrete(TypeF::Var(free_var))),
            }));
        };

        for (typ, pat_bindings, pos) in it {
            if model.len() != pat_bindings.len() {
                // We need to arbitrary choose a variable to report. We take the last one of the
                // longest list, which is guaranteed to not be present in all branches
                let witness = if model.len() > pat_bindings.len() {
                    // unwrap(): model.len() > pat_bindings.len() >= 0
                    model.last().unwrap().0
                } else {
                    // unwrap(): model.len() <= pat_bindings.len() and (by the outer-if)
                    // pat_bindings.len() != mode.len(), so:
                    // 0 <= model.len() < pat_bindings.len()
                    pat_bindings.last().unwrap().0
                };

                return Err(Box::new(TypecheckErrorData::new(
                    AstAlloc::new(),
                    |_alloc| TypecheckErrorKind::OrPatternVarsMismatch {
                        var: witness,
                        pos: self.pos,
                    },
                )));
            }

            // We unify the type of the first or-branch with the current or-branch, to make sure
            // all the subpatterns are matching values of the same type
            if let TypecheckMode::Enforce = mode {
                model_typ
                    .clone()
                    .unify(typ, state, ctxt)
                    .map_err(|e| e.into_typecheck_err(state, pos))?;
            }

            // Finally, we unify the type of the bindings
            for (idx, (id, typ)) in pat_bindings.into_iter().enumerate() {
                let (model_id, model_ty) = &model[idx];

                if *model_id != id {
                    // Once again, we must arbitrarily pick a variable to report. We take the
                    // smaller one, which is guaranteed to be missing (indeed, the greater one
                    // could still appear later in the other list, but the smaller is necessarily
                    // missing in the list with the greater one)
                    return Err(Box::new(TypecheckErrorData::new(
                        AstAlloc::new(),
                        |_alloc| TypecheckErrorKind::OrPatternVarsMismatch {
                            var: std::cmp::min(*model_id, id),
                            pos: self.pos,
                        },
                    )));
                }

                if let TypecheckMode::Enforce = mode {
                    model_ty
                        .clone()
                        .unify(typ, state, ctxt)
                        .map_err(|e| e.into_typecheck_err(state, id.pos))?;
                }
            }
        }

        // Once we have checked that all the bound variables are the same and we have unified their
        // types, we can add them to the overall bindings (since they are unified, it doesn't
        // matter which type we use - so we just reuse the model, which is still around)
        pt_state.bindings.extend(model);

        Ok(model_typ)
    }
}//! Typechecking records.
//!
//! Because record literal definitions are flexible in Nickel (piecewise definitions), they need
//! a bit of preprocessing before they can be typechecked. Preprocessing and typechecking of
//! records is handled in this module.
//!
//! # Include expressions
//!
//! Record fields can be declared in two ways: as a direct field definition, or as a field included
//! from the outer environment, as in `{include foo, [..]}`. The semantics of the latter is to be
//! equivalent to `{foo = %<foo from outer env>, [..]}`. Thus, for a static record type, we add the
//! included fields as rows `{foo: %<type of foo from outer from env>, [..]}`. For a dictionary
//! type, the type of `foo` in the environment is checked against the type of fields.
//!
//! We don't bother adding included fields in the recursive environment: they would just be a proxy
//! for the same field in the outer environment. That would still be correct, albeit useless,
//! because we can let recursive references to `foo` look into the outer environment directly.
use super::*;
use crate::{
    ast::record::{FieldDef, FieldPathElem, Include, Record},
    combine::Combine,
    position::TermPos,
};
use std::iter;

use indexmap::{IndexMap, map::Entry};

/// Records and their subcomponents that can be resolved.
pub(super) trait Resolve<'ast> {
    type Resolved;

    fn resolve(&'ast self) -> Self::Resolved;
}

/// Similar to [super::Check] but with a finer interface splitting the context between the outer
/// environment and the recursive environment. This machinery is mainly useful to properly handle
/// include expressions.
pub(super) trait CheckSplit<'ast> {
    fn check_split<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: RecordContext<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError>;
}

/// Similar to [super::Walk] but with a finer interface splitting the context between the outer
/// environment and the recursive environment. This machinery is mainly useful to properly walk
/// include expressions.
trait WalkSplit<'ast>: Copy {
    fn walk_split<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: RecordContext<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError>;
}

/// A resolved record literal, without field paths or piecewise definitions. Piecewise definitions
/// of fields have been grouped together, paths have been broken into proper levels and top-level
/// fields are partitioned between static and dynamic.
pub(super) struct ResolvedRecord<'ast> {
    /// The result of the record resolution.
    content: ShallowRecord<'ast>,
    /// The `include` expressions of the original record literal, unchanged. We need them to
    /// properly implement [super::Check] and [super::Walk] on [ResolvedRecord].
    includes: &'ast [Include<'ast>],
}

/// The content of a resolved record, with fields split between static and dynamic fields, and
/// where every definition is only a single field (no field paths).
#[derive(Default, Debug)]
pub(super) struct ShallowRecord<'ast> {
    /// The static fields of the record.
    pub stat_fields: IndexMap<LocIdent, ResolvedField<'ast>>,
    /// The dynamic fields of the record.
    ///
    /// This should not include any fields where the field name is a parser error, as those
    /// fields should be ignored for typechecking purposes. Instances created through the
    /// [ShallowRecord::new] constructor will filter out such fields.
    dyn_fields: Vec<(&'ast Ast<'ast>, ResolvedField<'ast>)>,
    /// The position of the resolved record.
    pub pos: TermPos,
}

impl<'ast> ShallowRecord<'ast> {
    /// Creates an instance of [ShallowRecord].
    ///
    /// This constructor will exclude fields where the field name is a parser error, so that
    /// those fields will be ignored for typechecking purposes.
    pub fn new(
        stat_fields: IndexMap<LocIdent, ResolvedField<'ast>>,
        dyn_fields: Vec<(&'ast Ast<'ast>, ResolvedField<'ast>)>,
        pos: TermPos,
    ) -> Self {
        ShallowRecord {
            stat_fields,
            dyn_fields: dyn_fields
                .into_iter()
                .filter(|(key, _)| !matches!(key.node, Node::ParseError(_)))
                .collect(),
            pos,
        }
    }
    pub fn empty() -> Self {
        Self::default()
    }

    pub fn is_empty(&self) -> bool {
        self.stat_fields.is_empty() && self.dyn_fields.is_empty()
    }

    /// Checks a record with dynamic fields (and potentially static fields as well) against a type.
    ///
    /// # Preconditions
    ///
    /// This method assumes that [Self::dyn_fields] is non-empty. Currently, violating this
    /// invariant shouldn't cause panic or unsoundness, but will unduly enforce that `ty` is a
    /// dictionary type.
    fn check_dyn<V: TypecheckVisitor<'ast>>(
        &self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        includes: &'ast [Include<'ast>],
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        let mut ctxt = RecordContext::from_outer(ctxt);
        let ty_elts = state.table.fresh_type_uvar(ctxt.outer.var_level);

        ty.unify(mk_uniftype::dict(ty_elts.clone()), state, &ctxt.outer)
            .map_err(|err| err.into_typecheck_err(state, self.pos))?;

        for id in self
            .stat_fields
            .keys()
            .chain(includes.iter().map(|incl| &incl.ident))
        {
            // We don't bind recursive fields in the term environment used to check for contract.
            // See [^term-env-rec-bindings] in `./mod.rs`.
            ctxt.inner.type_env.insert(id.ident(), ty_elts.clone());
            visitor.visit_ident(id, ty_elts.clone())
        }

        for (expr, field) in &self.dyn_fields {
            expr.check(state, ctxt.outer.clone(), visitor, mk_uniftype::str())?;
            field.check(state, ctxt.inner.clone(), visitor, ty_elts.clone())?;
        }

        for (_, field) in self.stat_fields.iter() {
            field.check(state, ctxt.inner.clone(), visitor, ty_elts.clone())?;
        }

        for incl in includes.iter() {
            incl.check_split(state, ctxt.clone(), visitor, ty_elts.clone())?;
        }

        Ok(())
    }

    /// Checks a record with only static fields against a type.
    ///
    /// # Preconditions
    ///
    /// This method assumes that `self.dyn_fields` is empty. Currently, violating this invariant
    /// shouldn't cause panic or unsoundness, but will unduly enforce that `ty` is a dictionary
    /// type.
    fn check_stat<V: TypecheckVisitor<'ast>>(
        &self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        includes: &'ast [Include<'ast>],
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        let root_ty = ty.clone().into_root(state.table);
        let mut ctxt = RecordContext {
            inner: ctxt.clone(),
            outer: ctxt,
        };

        if let UnifType::Concrete {
            typ: TypeF::Dict { type_fields, .. },
            ..
        } = root_ty
        {
            // Checking mode for a dictionary
            for (_, field) in self.stat_fields.iter() {
                field.check(state, ctxt.inner.clone(), visitor, (*type_fields).clone())?;
            }

            // We check that the types of field included from the outer environment match the dict
            // element types.
            for incl in includes.iter() {
                incl.check_split(state, ctxt.clone(), visitor, (*type_fields).clone())?;
            }

            Ok(())
        } else {
            // As records are recursive, we look at the apparent type of each field and bind it in
            // the inner context before actually typechecking the content of fields.
            //
            // Fields defined by interpolation are ignored, because they can't be referred to
            // recursively.
            //
            // When we build the recursive environment, there are two different possibilities for each
            // field:
            //
            // 1. The field is annotated. In this case, we use this type to build the type environment.
            //    We don't need to do any additional check that the field respects this annotation:
            //    this will be handled by `check` when processing the field.
            // 2. The field isn't annotated. We are going to infer a concrete type later, but for now,
            //    we allocate a fresh unification variable in the type environment. In this case, once
            //    we have inferred an actual type for this field, we need to unify what's inside the
            //    environment with the actual type to ensure that they agree.
            //
            //  `need_unif_step` stores the list of fields corresponding to the case 2, which require
            //  this additional unification step. Note that performing the additional unification in
            //  case 1. should be harmless, but it's wasteful, and is also not entirely trivial because
            //  of polymorphism (we need to make sure to instantiate polymorphic type annotations). At
            //  the end of the day, it's simpler to skip unneeded unifications.
            let mut need_unif_step = HashSet::new();

            for (id, field) in &self.stat_fields {
                let uty_apprt = field.apparent_type(
                    state.ast_alloc,
                    Some(&ctxt.outer.type_env),
                    Some(state.resolver),
                );

                // `Approximated` corresponds to the case where the type isn't obvious (annotation
                // or constant), and thus to case 2. above
                if let ApparentType::Approximated(_) = uty_apprt {
                    need_unif_step.insert(*id);
                }

                let uty = apparent_or_infer(state, uty_apprt, &ctxt.outer, true);
                ctxt.inner.type_env.insert(id.ident(), uty.clone());
                visitor.visit_ident(id, uty);
            }

            for incl in includes.iter() {
                let ty_outer = ctxt.outer.get_type(incl.ident)?;

                let uty = if let ApparentType::Annotated(ty_annot) =
                    incl.apparent_type(state.ast_alloc, Some(&ctxt.outer.type_env), None)
                {
                    let uty_annot = UnifType::from_type(ty_annot, &ctxt.outer.term_env);

                    // If the include expression has a type annotation, we'll use this annotation for the
                    // recursive environment, but first we need to make sure that the annotation
                    // and the type of the included variable in the outer environment agree.
                    //
                    // Note that if the annotation is a contract annotation (there's no type
                    // annotation), as per our semantics of include expressions seen as being
                    // equivalent to introducing a fresh variable, this places no constraint on the
                    // type of the included variable from the outer environment.
                    if incl.metadata.annotation.typ.is_some() {
                        subsumed_by_instantiated(
                            ty_outer,
                            uty_annot.clone(),
                            state,
                            ctxt.outer.clone(),
                        )
                        .map_err(|err| err.into_typecheck_err(state, incl.ident.pos))?;
                    }

                    uty_annot
                } else {
                    ty_outer
                };

                visitor.visit_ident(&incl.ident, uty.clone());
                ctxt.inner.type_env.insert(incl.ident.ident(), uty);
            }

            // We build a vector of unification variables representing the type of the fields of
            // the record.
            let field_types: Vec<UnifType<'ast>> =
                iter::repeat_with(|| state.table.fresh_type_uvar(ctxt.outer.var_level))
                    .take(self.stat_fields.len())
                    .collect();

            // Build the type {id1 : ?a1, id2: ?a2, .., idn: ?an}, which is the type of the whole
            // record.
            let rows = self
                .stat_fields
                .keys()
                .rev()
                .zip(field_types.iter().rev())
                .fold(
                    mk_uty_record_row!(),
                    |acc, (id, row_ty)| mk_uty_record_row!((*id, row_ty.clone()); acc),
                );

            // We chain the types of potential included fields to the front of the record type.
            let rows =
                includes
                    .iter()
                    .rev()
                    .try_fold(rows, |acc, incl| -> Result<_, TypecheckError> {
                        Ok(mk_uty_record_row!((incl.ident, ctxt.inner.get_type(incl.ident)?); acc))
                    })?;

            ty.unify(mk_uty_record!(; rows), state, &ctxt.outer)
                .map_err(|err| err.into_typecheck_err(state, self.pos))?;

            for ((id, field), field_type) in self.stat_fields.iter().zip(field_types) {
                // For a recursive record and a field which requires the additional unification
                // step (whose type wasn't known when building the recursive environment), we
                // unify the actual type with the type affected in the typing environment
                // (which started as a fresh unification variable, but might have been unified
                // with a more concrete type if the current field has been used recursively
                // from other fields).
                if need_unif_step.contains(id) {
                    // unwrap(): if the field is in `need_unif_step`, it must be in the context.
                    let affected_type = ctxt.inner.type_env.get(&id.ident()).cloned().unwrap();

                    field_type
                        .clone()
                        .unify(affected_type, state, &ctxt.outer)
                        .map_err(|err| {
                            err.into_typecheck_err(
                                state,
                                field.pos(),
                                // field.value.as_ref().map(|v| v.pos).unwrap_or_default(),
                            )
                        })?;
                }

                field.check(state, ctxt.inner.clone(), visitor, field_type)?;
            }

            for annot in includes
                .iter()
                .flat_map(|incl| incl.metadata.annotation.iter())
            {
                annot.walk(state, ctxt.inner.clone(), visitor)?;
            }

            Ok(())
        }
    }

    /// Generates a [RecordContext] for this shallow record in walk mode.
    fn walk_ctxt<V: TypecheckVisitor<'ast>>(
        &self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> RecordContext<'ast> {
        let outer = ctxt.clone();
        let mut inner = ctxt;

        for (id, field) in self.stat_fields.iter() {
            let field_type = UnifType::from_apparent_type(
                field.apparent_type(state.ast_alloc, Some(&outer.type_env), Some(state.resolver)),
                &outer.term_env,
            );

            visitor.visit_ident(id, field_type.clone());
            inner.type_env.insert(id.ident(), field_type);
        }

        RecordContext { inner, outer }
    }
}

impl<'ast> Check<'ast> for &ResolvedRecord<'ast> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        // If we have no dynamic fields, we can check the record against a record type or a
        // dictionary type, depending on `ty`.
        if self.content.dyn_fields.is_empty() {
            self.content
                .check_stat(state, ctxt, self.includes, visitor, ty)
        }
        // If some fields are defined dynamically, the only potential type that works is `{_ : a}`
        // for some `a`.
        else {
            self.content
                .check_dyn(state, ctxt, self.includes, visitor, ty)
        }
    }
}

impl<'ast> CheckSplit<'ast> for &'ast Include<'ast> {
    fn check_split<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: RecordContext<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        let ty_outer = ctxt.outer.get_type(self.ident)?;
        let ty_annot = self.metadata.annotation.iter().next().cloned();

        for ty in self.metadata.annotation.iter() {
            ty.walk(state, ctxt.inner.clone(), visitor)?;
        }

        if let Some(ty_annot) = ty_annot {
            let uty_annot = UnifType::from_type(ty_annot, &ctxt.inner.term_env);

            // If the annotation is a type annotation, we enforce that the type of the included
            // variable in the outer environment agrees with the annotation.
            //
            // However, we skip this check in case of a pure contract annotation: following our
            // semantics that `{include foo | T}` is equivalent to `let _fresh = foo in {foo | T =
            // _fresh}`, in the latter form `_fresh` isn't statically typechecked.
            if self.metadata.annotation.typ.is_some() {
                subsumed_by_instantiated(ty_outer, uty_annot.clone(), state, ctxt.outer.clone())
                    .map_err(|err| err.into_typecheck_err(state, self.ident.pos))?;
            }

            uty_annot
                .subsumed_by(ty, state, ctxt.outer)
                .map_err(|err| err.into_typecheck_err(state, self.ident.pos))
        } else {
            // We use subsumption here, since `ty_outer` is taken from the environment, it is
            // considered to be inferred, exactly as for a variable.
            ty_outer
                .subsumed_by(ty, state, ctxt.outer)
                .map_err(|err| err.into_typecheck_err(state, self.ident.pos))
        }
    }
}

impl<'ast> Walk<'ast> for &ResolvedRecord<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        let mut ctxt = self.content.walk_ctxt(state, ctxt, visitor);

        for incl in self.includes.iter() {
            // If the include expression has an annotation, we need to add this information to the
            // recursive environment (inner). Otherwise, other fields referring to the included
            // expression will transparently find the identifier in the outer environment (which is
            // included in the inner environment), in which case we don't have to do anything.
            //
            // If the annotation is a static type annotation, the call to `Include::walk_split`
            // below will handle additional checks.
            let ty = if let ApparentType::Annotated(ty) =
                incl.apparent_type(state.ast_alloc, Some(&ctxt.outer.type_env), None)
            {
                let ty = UnifType::from_type(ty, &ctxt.outer.term_env);
                ctxt.inner.type_env.insert(incl.ident.ident(), ty.clone());
                ty
            } else {
                ctxt.outer.get_type(incl.ident)?
            };

            visitor.visit_ident(&incl.ident, ty.clone());
            ctxt.inner.type_env.insert(incl.ident.ident(), ty);

            incl.walk_split(state, ctxt.clone(), visitor)?;
        }

        self.content.walk_split(state, ctxt, visitor)
    }
}

impl<'ast> Check<'ast> for &ShallowRecord<'ast> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        // If we have no dynamic fields, we can check the record against a record type or a
        // dictionary type, depending on `ty`.
        if self.dyn_fields.is_empty() {
            self.check_stat(state, ctxt, &[], visitor, ty)
        }
        // If some fields are defined dynamically, the only potential type that works is `{_ : a}`
        // for some `a`.
        else {
            self.check_dyn(state, ctxt, &[], visitor, ty)
        }
    }
}

impl<'ast> WalkSplit<'ast> for &ShallowRecord<'ast> {
    fn walk_split<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: RecordContext<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        for (ast, field) in self.dyn_fields.iter() {
            ast.walk(state, ctxt.outer.clone(), visitor)?;
            field.walk(state, ctxt.inner.clone(), visitor)?;
        }

        // Then we check the fields in the recursive environment.
        for (_, field) in self.stat_fields.iter() {
            field.walk(state, ctxt.inner.clone(), visitor)?;
        }

        Ok(())
    }
}

impl<'ast> Walk<'ast> for &ShallowRecord<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        let ctxt = self.walk_ctxt(state, ctxt, visitor);
        self.walk_split(state, ctxt, visitor)
    }
}

impl<'ast> Walk<'ast> for &ResolvedField<'ast> {
    fn walk<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        match (self.resolved.is_empty(), self.defs.as_slice()) {
            // This shouldn't happen (fields present in the record should either have a definition
            // or comes from record resolution).
            (true, []) => {
                unreachable!("typechecker internal error: checking a vacant field")
            }
            (false, []) => self.resolved.walk(state, ctxt, visitor),
            // Special case for a piecewise definition where at most one definition has a value.
            // This won't result in a runtime merge. Instead, it's always equivalent to one field
            // definition where the annotations have been combined. We reuse the same logic as for
            // checking a standard single field definition thanks to `FieldDefCheckView`.
            (true, defs) if defs.iter().filter(|def| def.value.is_some()).count() <= 1 => {
                let value = defs.iter().find_map(|def| def.value.as_ref());

                FieldDefCheckView {
                    annots: defs,
                    value,
                    // unwrap():
                    //
                    // 1. We treated the case `(true, [])` in the first branch of this pattern, so
                    //    there must be at least one element in `defs`
                    // 2. The path of a field definition must always be non-empty
                    pos_id: defs
                        .first()
                        .unwrap()
                        .path
                        .last()
                        .expect("empty field path in field definition")
                        .pos(),
                }
                .walk(state, ctxt, visitor)
            }
            // In all other cases, we have either several definitions or at least one definition
            // and a resolved part. Those cases will result in a merge (even if it can be sometimes
            // optimized to a static merge that happens before runtime), so we type everything as
            // `Dyn`.
            (_, defs) => {
                for def in defs.iter() {
                    def.walk(state, ctxt.clone(), visitor)?;
                }

                // If `resolved` is empty, this will be a no-op. We thus don't bother guarding it
                // behind a `if resolved.is_empty()`
                self.resolved.walk(state, ctxt, visitor)?;

                Ok(())
            }
        }
    }
}

impl<'ast> WalkSplit<'ast> for &'ast Include<'ast> {
    fn walk_split<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: RecordContext<'ast>,
        visitor: &mut V,
    ) -> Result<(), TypecheckError> {
        // We reuse some of the logic of `FieldDefCheckView`; in particular, there are some
        // heuristics around contract annotations and visiting identifiers.
        FieldDefCheckView {
            annots: &self.metadata.annotation,
            pos_id: self.ident.pos,
            value: None,
        }
        .walk(state, ctxt.inner, visitor)?;

        // There's a case that `FieldlDefCheckView` above doesn't handle: if there is a static type
        // annotation, as in `{include x : String}`, then we must check that the `x` coming from
        // the environment has the static type `String` (or any compatible type).
        if let Some(ty) = &self.metadata.annotation.typ {
            let uty = UnifType::from_type(ty.clone(), &ctxt.outer.term_env);
            ctxt.outer
                .get_type(self.ident)?
                .subsumed_by(uty, state, ctxt.outer)
                .map_err(|err| err.into_typecheck_err(state, self.ident.pos))?;
        }

        Ok(())
    }
}

impl<'ast> Combine for ShallowRecord<'ast> {
    fn combine(this: ShallowRecord<'ast>, other: ShallowRecord<'ast>) -> Self {
        use crate::eval::merge::split;

        let split::SplitResult {
            left,
            center,
            right,
        } = split::split(this.stat_fields, other.stat_fields);

        let mut stat_fields = IndexMap::with_capacity(left.len() + center.len() + right.len());

        stat_fields.extend(left);
        stat_fields.extend(right);

        for (id, (field1, field2)) in center.into_iter() {
            stat_fields.insert(id, Combine::combine(field1, field2));
        }

        let dyn_fields = this
            .dyn_fields
            .into_iter()
            .chain(other.dyn_fields)
            .collect();

        let pos = match (this.pos, other.pos) {
            // If only one of the two position is defined, we use it
            (pos, TermPos::None) | (TermPos::None, pos) => pos,
            // Otherwise, we don't know how to combine two disjoint positions of a piecewise
            // definition, so we just return `TermPos::None`.
            _ => TermPos::None,
        };

        ShallowRecord::new(stat_fields, dyn_fields, pos)
    }
}

/// A wrapper type around a record that has been resolved but hasn't yet got a position. This is
/// done to force the caller of [Record::resolve] to provide a position before doing anything else.
pub(super) struct PoslessResolvedRecord<'ast>(ResolvedRecord<'ast>);

impl<'ast> PoslessResolvedRecord<'ast> {
    pub(super) fn new(
        stat_fields: IndexMap<LocIdent, ResolvedField<'ast>>,
        dyn_fields: Vec<(&'ast Ast<'ast>, ResolvedField<'ast>)>,
        includes: &'ast [Include<'ast>],
    ) -> Self {
        PoslessResolvedRecord(ResolvedRecord {
            includes,
            content: ShallowRecord::new(stat_fields, dyn_fields, TermPos::None),
        })
    }

    pub(super) fn with_pos(self, pos: TermPos) -> ResolvedRecord<'ast> {
        let PoslessResolvedRecord(mut record) = self;
        record.content.pos = pos;
        record
    }
}

/// The field of a resolved record.
///
/// A resolved field can be either:
///
/// - another resolved record, for the fields coming from elaboration, as
///   `mid` in `{ outer.mid.inner = true }`.
/// - A final value, for the last field of path, as `inner` in `{ outer.mid.inner = true }` or in
///   `fun param => { outer.mid.inner = param}`.
/// - A combination of the previous cases, for a field defined piecewise with multiple
///   definitions, such as `mid` in `fun param => { outer.mid.inner = true, outer.mid = param}`.
///
/// In the combined, the resolved field `mid` will have a resolved part `{inner = true}` and a
/// value part `param`. Values can't be combined statically in all generality (imagine adding
/// another piecewise definition `outer.mid = other_variable` in the previous example), hence we
/// keep accumulating them. However, resolved parts can be merged statically, so we only need one
/// that we update as we collect the pieces of the definition.
///
/// Rather than having an ad-hoc enum with all those cases (that would just take up more memory),
/// we consider the general combined case directly. Others are special cases with an empty
/// `resolved`, or an empty or one-element `values`.
#[derive(Default, Debug)]
pub(super) struct ResolvedField<'ast> {
    /// The resolved part of the field, coming from piecewise definitions where this field appears
    /// in the middle of the path.
    resolved: ShallowRecord<'ast>,
    /// The accumulated values of the field, coming from piecewise definitions where this field
    /// appears last in the path.
    ///
    /// We store the whole [crate::ast::record::FieldDef] here, although we don't need
    /// the path anymore, because it's easier and less costly than creating an ad-hoc structure to
    /// store only the value and the metadata.
    defs: Vec<&'ast FieldDef<'ast>>,
}

impl<'ast> ResolvedField<'ast> {
    /// Return the first type or contract annotation available in the definitions, if any.
    ///
    /// [ResolvedField::first_annot] first looks for a type annotation in all definitions. If we
    /// can't find any, [ResolvedField::first_annot] will look for the first contract annotation.
    /// If there is no annotation at all, `None` is returned.
    ///
    /// [ResolvedField::first_annot] is equivalent to calling
    /// [crate::ast::Annotation::first] on the combined metadata of all definitions.
    pub fn first_annot(&self) -> Option<Type<'ast>> {
        self.defs
            .iter()
            .find_map(|def| def.metadata.annotation.typ.as_ref().cloned())
            .or(self
                .defs
                .iter()
                .find_map(|def| def.metadata.annotation.contracts.first().cloned()))
    }

    /// Returns the position of this resolved field if and only if there is a single defined
    /// position (among both the resolved part and the definitions). Otherwise, returns
    /// [crate::position::TermPos::None].
    pub fn pos(&self) -> TermPos {
        self.defs
            .iter()
            .fold(self.resolved.pos, |acc, def| acc.xor(def.pos))
    }
}

impl<'ast> Check<'ast> for &ResolvedField<'ast> {
    fn check<V: TypecheckVisitor<'ast>>(
        self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
        visitor: &mut V,
        ty: UnifType<'ast>,
    ) -> Result<(), TypecheckError> {
        match (self.resolved.is_empty(), self.defs.as_slice()) {
            // This shouldn't happen (fields present in the record should either have a definition
            // or comes from record resolution).
            (true, []) => {
                unreachable!("typechecker internal error: checking a vacant field")
            }
            // When there's just one classic field definition and no resolved form, we offload the
            // work to `ShallowRecord::check`.
            (false, []) => self.resolved.check(state, ctxt, visitor, ty),
            // Special case for a piecewise definition where at most one definition has a value.
            // This won't result in a runtime merge. Instead, it's always equivalent to one field
            // definition where the annotations have been combined. We reuse the same logic as for
            // checking a standard single field definition thanks to `FieldDefCheckView`.
            (true, defs) if defs.iter().filter(|def| def.value.is_some()).count() <= 1 => {
                let value = defs.iter().find_map(|def| def.value.as_ref());

                FieldDefCheckView {
                    annots: defs,
                    value,
                    // unwrap():
                    //
                    // 1. We treated the case `(true, [])` in the first branch of this pattern, so
                    //    there must be at least one element in `defs`
                    // 2. The path of a field definition must always be non-empty
                    pos_id: defs
                        .first()
                        .unwrap()
                        .path
                        .last()
                        .expect("empty field path")
                        .pos(),
                }
                .check(state, ctxt, visitor, ty)
            }
            // In all other cases, we have either several definitions or at least one definition
            // and a resolved part. Those cases will result in a merge (even if it can be sometimes
            // optimized to a static merge that happens before runtime), so we type everything as
            // `Dyn`.
            (_, defs) => {
                for def in defs.iter() {
                    def.check(state, ctxt.clone(), visitor, mk_uniftype::dynamic())?;
                }

                if !self.resolved.is_empty() {
                    // This will always raise an error, since the resolved part is equivalent to a
                    // record literal which doesn't type against `Dyn` (at least currently). We
                    // could raise the error directly, but it's simpler to call `check` on
                    // `self.resolved`, which will handle that for us.
                    //
                    // Another reason is that the error situation might change in the future, if we
                    // have proper subtyping for `Dyn`.
                    self.resolved
                        .check(state, ctxt, visitor, mk_uniftype::dynamic())?;
                }

                Ok(())
            }
        }
    }
}

impl Combine for ResolvedField<'_> {
    fn combine(this: Self, other: Self) -> Self {
        let mut defs = this.defs;
        defs.extend(other.defs);

        ResolvedField {
            resolved: Combine::combine(this.resolved, other.resolved),
            defs,
        }
    }
}

impl<'ast> From<&'ast FieldDef<'ast>> for ResolvedField<'ast> {
    fn from(def: &'ast FieldDef<'ast>) -> Self {
        ResolvedField {
            resolved: ShallowRecord::empty(),
            defs: vec![def],
        }
    }
}

impl<'ast> From<ShallowRecord<'ast>> for ResolvedField<'ast> {
    fn from(resolved: ShallowRecord<'ast>) -> Self {
        ResolvedField {
            resolved,
            defs: Vec::new(),
        }
    }
}

impl<'ast> Resolve<'ast> for Record<'ast> {
    type Resolved = PoslessResolvedRecord<'ast>;

    fn resolve(&self) -> PoslessResolvedRecord<'ast> {
        fn insert_static_field<'ast>(
            static_fields: &mut IndexMap<LocIdent, ResolvedField<'ast>>,
            id: LocIdent,
            field: ResolvedField<'ast>,
        ) {
            match static_fields.entry(id) {
                Entry::Occupied(mut occpd) => {
                    // temporarily putting an empty field in the entry to take the previous value.
                    let prev = occpd.insert(ResolvedField::default());

                    // unwrap(): the field's identifier must have a position during parsing.
                    occpd.insert(Combine::combine(prev, field));
                }
                Entry::Vacant(vac) => {
                    vac.insert(field);
                }
            }
        }

        let mut stat_fields = IndexMap::new();
        let mut dyn_fields = Vec::new();

        for def in self.field_defs.iter() {
            // expect(): the field path must have at least one element, it's an invariant.
            let toplvl_field = def.path.first().expect("empty field path");
            let rfield = def.resolve();

            if let Some(id) = toplvl_field.try_as_ident() {
                insert_static_field(&mut stat_fields, id, rfield);
                continue;
            } else {
                // unreachable!(): `try_as_ident` returns `None` only if the path element is a
                // `Expr`
                let FieldPathElem::Expr(expr) = toplvl_field else {
                    unreachable!()
                };
                dyn_fields.push((expr, rfield));
            }
        }

        PoslessResolvedRecord::new(stat_fields, dyn_fields, self.includes)
    }
}

// This turns a field definition into potentially nested resolved fields. Note that the top-level
// field is left out, as it's already been processed by the caller: resolving `foo.bar.baz.qux =
// 42` will return nested resolved records of the form `{bar = {baz = {qux = 42}}}`.
impl<'ast> Resolve<'ast> for FieldDef<'ast> {
    type Resolved = ResolvedField<'ast>;

    fn resolve(&'ast self) -> ResolvedField<'ast> {
        self.path[1..]
            .iter()
            .rev()
            .fold(self.into(), |acc, path_elem| {
                if let Some(id) = path_elem.try_as_ident() {
                    let pos_acc = acc.pos();

                    ResolvedField::from(ShallowRecord::new(
                        iter::once((id, acc)).collect(),
                        Vec::new(),
                        id.pos.fuse(pos_acc),
                    ))
                } else {
                    // unreachable!(): `try_as_ident` returns `None` only if the path element is a
                    // `Expr`
                    let FieldPathElem::Expr(expr) = path_elem else {
                        unreachable!()
                    };

                    let pos_acc = acc.pos();

                    ResolvedField::from(ShallowRecord::new(
                        IndexMap::new(),
                        vec![(expr, acc)],
                        expr.pos.fuse(pos_acc),
                    ))
                }
            })
    }
}

impl<'ast> HasApparentType<'ast> for &ResolvedField<'ast> {
    // Return the apparent type of a field, by first looking at the type annotation, if any, then at
    // the contracts annotation, and if there is none, fall back to the apparent type of the value. If
    // there is no value, `Approximated(Dyn)` is returned.
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        match self.defs.as_slice() {
            // If there is a resolved part, the apparent type is `Dyn`: a resolved part itself is a
            // record literal without annotation, whose apparent type is indeed `Dyn`. If there are
            // definitions as well, the result will be merged at runtime, and the apparent type of a
            // merge expression is also `Dyn`.
            _ if !self.resolved.is_empty() => ApparentType::Approximated(Type::from(TypeF::Dyn)),
            [] => ApparentType::Approximated(Type::from(TypeF::Dyn)),
            [def] => def.apparent_type(ast_alloc, env, resolver),
            _ => self
                .first_annot()
                .map(ApparentType::Annotated)
                .unwrap_or(ApparentType::Approximated(Type::from(TypeF::Dyn))),
        }
    }
}

impl<'ast> HasApparentType<'ast> for &'ast Include<'ast> {
    fn apparent_type(
        self,
        ast_alloc: &'ast AstAlloc,
        env: Option<&TypeEnv<'ast>>,
        resolver: Option<&mut dyn AstImportResolver>,
    ) -> ApparentType<'ast> {
        (&self.metadata.annotation, None).apparent_type(ast_alloc, env, resolver)
    }
}

/// This helpers instantiate `uty2` with rigid type variables if needed, and then check if `uty1`
/// is subsumed by `uty2`.
///
/// Instantiation is normally handled by the checking rule, but we somehow short-circuit it in the
/// case of include expressions with a static type annotation, so we have to do it manually.
fn subsumed_by_instantiated<'ast>(
    uty1: UnifType<'ast>,
    uty2: UnifType<'ast>,
    state: &mut State<'ast, '_>,
    mut ctxt: Context<'ast>,
) -> Result<(), UnifError<'ast>> {
    let instantiated = instantiate_foralls(state, &mut ctxt, uty2, ForallInst::Constant);
    uty1.subsumed_by(instantiated, state, ctxt)
}//! Helpers to convert a `TypeWrapper` to a human-readable `Type` representation for error
//! reporting.
use super::*;

/// A name registry used to replace unification variables and type constants with human-readable
/// and distinct names.
pub struct NameReg {
    /// Currently allocated names, including both variables written by the user and generated
    /// names.
    names: NameTable,
    /// A reverse name table, always kept in sync with `names`, in order to efficiently check if a
    /// name is already taken.
    taken: HashSet<Ident>,
    /// Counter used to generate fresh letters for unification variables.
    var_count: usize,
    /// Counter used to generate fresh letters for type constants.
    cst_count: usize,
}

impl NameReg {
    /// Create a new registry from an initial table corresponding to user-written type constants.
    pub fn new(names: NameTable) -> Self {
        let taken = names.values().copied().collect();

        NameReg {
            names,
            taken,
            var_count: 0,
            cst_count: 0,
        }
    }

    pub fn taken(&self, name: &str) -> bool {
        self.taken.contains(&name.into())
    }

    fn insert(&mut self, var_id: VarId, discriminant: VarKindDiscriminant, name: Ident) {
        self.names.insert((var_id, discriminant), name);
        self.taken.insert(name);
    }

    /// Create a fresh name candidate for a type variable or a type constant.
    ///
    /// Used to convert a unification type to a human-readable representation.
    ///
    /// To select a candidate, first check in `names` if the variable or the constant corresponds
    /// to a type variable written by the user. If it is, return the name of the variable.
    /// Otherwise, use the given counter to generate a new single letter.
    ///
    /// A generated name is clearly not necessarily unique. [`select_uniq`] must then be applied.
    fn gen_candidate_name(
        names: &NameTable,
        counter: &mut usize,
        id: VarId,
        kind: VarKindDiscriminant,
    ) -> String {
        match names.get(&(id, kind)) {
            // First check if that constant or variable was introduced by a forall. If it was, try
            // to use the same name.
            Some(orig) => format!("{orig}"),
            None => {
                //Otherwise, generate a new character
                let next = *counter;
                *counter += 1;

                let prefix = match kind {
                    VarKindDiscriminant::Type => "",
                    VarKindDiscriminant::EnumRows => "erows_",
                    VarKindDiscriminant::RecordRows => "rrows_",
                };
                let character = std::char::from_u32(('a' as u32) + ((next % 26) as u32)).unwrap();
                format!("{prefix}{character}")
            }
        }
    }

    /// Select a name distinct from all the others, starting from a candidate name for a type
    /// variable or a type constant. Insert the corresponding name in the name table.
    ///
    /// If the name is already taken, it just iterates by adding a numeric suffix `1`, `2`, .., and
    /// so on until a free name is found. See `var_to_type` and `cst_to_type`.
    fn select_uniq(&mut self, mut name: String, id: VarId, kind: VarKindDiscriminant) -> Ident {
        // To avoid clashing with already picked names, we add a numeric suffix to the picked
        // letter.
        if self.taken(&name) {
            let mut suffix = 1;

            name = format!("{name}{suffix}");
            while self.taken(&name) {
                suffix += 1;
            }
        }

        let sym = Ident::from(name);
        self.insert(id, kind, sym);
        sym
    }

    /// Either retrieve or generate a new fresh name for a unification variable for error reporting,
    /// and wrap it as an identifier. Unification variables are named `_a`, `_b`, .., `_a1`, `_b1`,
    /// .. and so on.
    pub fn gen_var_name(&mut self, id: VarId, kind: VarKindDiscriminant) -> Ident {
        self.names.get(&(id, kind)).cloned().unwrap_or_else(|| {
            // Select a candidate name and add a "_" prefix
            let candidate = format!(
                "_{}",
                Self::gen_candidate_name(&self.names, &mut self.var_count, id, kind)
            );
            // Add a suffix to make it unique if it has already been picked
            self.select_uniq(candidate, id, kind)
        })
    }

    /// Either retrieve or generate a new fresh name for a constant for error reporting, and wrap it
    /// as type variable. Constant are named `a`, `b`, .., `a1`, `b1`, .. and so on.
    pub fn gen_cst_name(&mut self, id: VarId, kind: VarKindDiscriminant) -> Ident {
        self.names.get(&(id, kind)).cloned().unwrap_or_else(|| {
            // Select a candidate name
            let candidate = Self::gen_candidate_name(&self.names, &mut self.cst_count, id, kind);
            // Add a suffix to make it unique if it has already been picked
            self.select_uniq(candidate, id, kind)
        })
    }
}

pub trait ToType<'ast> {
    /// The target type to convert to. If `Self` is `UnifXXX`, then `Target` is `XXX`.
    type Target;

    /// Extract a concrete type corresponding to a unification type for error reporting purpose,
    /// given a registry of currently allocated names.
    ///
    /// As opposed to [`crate::typ::Type::from`], free unification variables and type constants are
    /// replaced by type variables which names are determined by this name registry.
    ///
    /// When reporting error, we want to distinguish occurrences of unification variables and type
    /// constants in a human-readable way.
    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target;
}

impl<'ast> ToType<'ast> for UnifType<'ast> {
    type Target = Type<'ast>;

    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target {
        let ty = self.into_root(table);

        match ty {
            UnifType::UnifVar { id, .. } => {
                TypeF::Var(reg.gen_var_name(id, VarKindDiscriminant::Type)).into()
            }
            UnifType::Constant(id) => {
                TypeF::Var(reg.gen_cst_name(id, VarKindDiscriminant::Type)).into()
            }
            UnifType::Concrete { typ, .. } => typ
                .map_state(
                    |btyp, reg| alloc.alloc(btyp.to_type(alloc, reg, table)),
                    |rrows, reg| rrows.to_type(alloc, reg, table),
                    |erows, reg| erows.to_type(alloc, reg, table),
                    |(ctr, _env), _reg| ctr,
                    reg,
                )
                .into(),
        }
    }
}

impl<'ast> ToType<'ast> for UnifRecordRows<'ast> {
    type Target = RecordRows<'ast>;

    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target {
        let rrows = self.into_root(table);

        match rrows {
            UnifRecordRows::UnifVar { id, .. } => RecordRows(RecordRowsF::TailVar(
                reg.gen_var_name(id, VarKindDiscriminant::RecordRows).into(),
            )),
            UnifRecordRows::Constant(id) => RecordRows(RecordRowsF::TailVar(
                reg.gen_cst_name(id, VarKindDiscriminant::RecordRows).into(),
            )),
            UnifRecordRows::Concrete { rrows, .. } => {
                let mapped = rrows.map_state(
                    |btyp, reg| alloc.alloc(btyp.to_type(alloc, reg, table)),
                    |rrows, reg| alloc.alloc(rrows.to_type(alloc, reg, table)),
                    reg,
                );
                RecordRows(mapped)
            }
        }
    }
}

impl<'ast> ToType<'ast> for UnifEnumRows<'ast> {
    type Target = EnumRows<'ast>;

    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target {
        let erows = self.into_root(table);

        match erows {
            UnifEnumRows::UnifVar { id, .. } => EnumRows(EnumRowsF::TailVar(
                reg.gen_var_name(id, VarKindDiscriminant::EnumRows).into(),
            )),
            UnifEnumRows::Constant(id) => EnumRows(EnumRowsF::TailVar(
                reg.gen_cst_name(id, VarKindDiscriminant::EnumRows).into(),
            )),
            UnifEnumRows::Concrete { erows, .. } => {
                let mapped = erows.map_state(
                    |btyp, reg| alloc.alloc(btyp.to_type(alloc, reg, table)),
                    |erows, reg| alloc.alloc(erows.to_type(alloc, reg, table)),
                    reg,
                );
                EnumRows(mapped)
            }
        }
    }
}

impl<'ast> ToType<'ast> for UnifEnumRow<'ast> {
    type Target = EnumRow<'ast>;

    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target {
        EnumRow {
            id: self.id,
            typ: self
                .typ
                .map(|typ| alloc.alloc(typ.to_type(alloc, reg, table))),
        }
    }
}

impl<'ast> ToType<'ast> for UnifRecordRow<'ast> {
    type Target = RecordRow<'ast>;

    fn to_type(
        self,
        alloc: &'ast AstAlloc,
        reg: &mut NameReg,
        table: &UnifTable<'ast>,
    ) -> Self::Target {
        RecordRow {
            id: self.id,
            typ: alloc.alloc(self.typ.to_type(alloc, reg, table)),
        }
    }
}//! Type subsumption (subtyping)
//!
//! Subtyping is a relation between types that allows a value of one type to be used at a place
//! where another type is expected, because the value's actual type is subsumed by the expected
//! type.
//!
//! The subsumption rule is applied when switching from inference mode to checking mode, as
//! customary in bidirectional type checking.
//!
//! Currently, there is one core subtyping axiom:
//!
//! - Record / Dictionary : `{a1 : T1,...,an : Tn} <: {_ : U}` if for every n `Tn <: U`
//!
//! The subtyping relation is extended to a congruence on other type constructors in the obvious
//! way:
//!
//! - `Array T <: Array U` if `T <: U`
//! - `{_ : T} <: {_ : U}` if `T <: U`
//! - `{a1 : T1,...,an : Tn} <: {b1 : U1,...,bn : Un}` if for every n `Tn <: Un`
//!
//! In all other cases, we fallback to unification (although we instantiate polymorphic types as
//! needed before). That is, we try to apply reflexivity: `T <: U` if `T = U`.
//!
//! The type instantiation corresponds to the zero-ary case of application in the current
//! specification (which is loosely based on [A Quick Look at Impredicativity][quick-look],
//! although we currently don't support impredicative polymorphism).
//!
//! [quick-look]: https://www.microsoft.com/en-us/research/uploads/prod/2020/01/quick-look-icfp20-fixed.pdf
use super::*;

pub(super) trait SubsumedBy<'ast> {
    type Error;

    /// Checks if `self` is subsumed by `t2`, that is if `self <: t2`. Returns an error otherwise.
    ///
    /// For error reporting, note that the order of "expected" and "inferred" type is reversed when
    /// compared to `unify`: in the latter, `self` is the "expected" type (coming from the context)
    /// and "inferred" the type deduced from the expression, while here, the inferred type is
    /// usually `self` and the expected type is `t2`. This is made to match the usual order of
    /// subtyping.
    fn subsumed_by(
        self,
        t2: Self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
    ) -> Result<(), Self::Error>;
}

impl<'ast> SubsumedBy<'ast> for UnifType<'ast> {
    type Error = UnifError<'ast>;

    fn subsumed_by(
        self,
        t2: Self,
        state: &mut State<'ast, '_>,
        mut ctxt: Context<'ast>,
    ) -> Result<(), Self::Error> {
        let inferred = instantiate_foralls(state, &mut ctxt, self, ForallInst::UnifVar);
        let checked = t2.into_root(state.table);

        match (inferred, checked) {
            // {a1 : T1,...,an : Tn} <: {_ : U} if for every n `Tn <: U`
            (
                UnifType::Concrete {
                    typ: TypeF::Record(rrows),
                    ..
                },
                UnifType::Concrete {
                    typ:
                        TypeF::Dict {
                            type_fields,
                            flavour,
                        },
                    var_levels_data,
                },
            ) => {
                let mut prev_row_typ: Option<&UnifType<'_>> = None;
                for row in rrows.iter() {
                    match row {
                        RecordRowsElt::Row(a) => {
                            let row_result =
                                a.typ
                                .clone()
                                .subsumed_by(*type_fields.clone(), state, ctxt.clone());

                            // One way that this row can fail to typecheck is if the record has rows with
                            // differing types. In that case, the dict's field type will unify with the
                            // first row's type, and then it will trigger a type mismatch when it tries
                            // to unify with another row's type. In this case, the `TypeMismatch` error is
                            // confusing: checking whether `{ x: String, y: Number }` is subsumed by
                            // `{ _ : a }` will complain that `String` and `Number` are incompatible, but we
                            // should really be complaining that inhomogeneous records and dicts are incompatible.
                            //
                            // To improve this, we special-case the error message if a previous row
                            // checked successfully and this one failed.
                            match (row_result, prev_row_typ) {
                                (Err(_), Some(prev_ty)) => {
                                     Err(Box::new(UnifErrorKind::InhomogeneousRecord { row_a: prev_ty.clone(), row_b: a.typ.clone() }))
                                }
                                (x, _) => x,
                            }?;
                            prev_row_typ = Some(a.typ);
                        }
                        RecordRowsElt::TailUnifVar { id, .. } =>
                        // We don't need to perform any variable level checks when unifying a free
                        // unification variable with a ground type
                        // We close the tail because there is no guarantee that
                        // { a : Number, b : Number, _ : a?} <= { _ : Number}
                        {
                            state
                                .table
                                .assign_rrows(id, UnifRecordRows::concrete(RecordRowsF::Empty))
                        }
                        RecordRowsElt::TailConstant(id) => {
                            let checked = UnifType::Concrete {
                                typ: TypeF::Dict {
                                    type_fields: type_fields.clone(),
                                    flavour,
                                },
                                var_levels_data,
                            };
                            Err(UnifErrorKind::WithConst {
                                var_kind: VarKindDiscriminant::RecordRows,
                                expected_const_id: id,
                                inferred: checked,
                            })?
                        }
                        _ => (),
                    }
                }
                Ok(())
            }
            // Array T <: Array U if T <: U
            (
                UnifType::Concrete {
                    typ: TypeF::Array(a),
                    ..
                },
                UnifType::Concrete {
                    typ: TypeF::Array(b),
                    ..
                },
            )
            // Dict T <: Dict U if T <: U
            | (
                UnifType::Concrete {
                    typ: TypeF::Dict { type_fields: a, .. },
                    ..
                },
                UnifType::Concrete {
                    typ: TypeF::Dict { type_fields: b, .. },
                    ..
                },
            ) => a.subsumed_by(*b, state, ctxt),
            // {a1 : T1,...,an : Tn} <: {b1 : U1,...,bn : Un} if for every n `Tn <: Un`
            (
                UnifType::Concrete {
                    typ: TypeF::Record(rrows1),
                    ..
                },
                UnifType::Concrete {
                    typ: TypeF::Record(rrows2),
                    ..
                },
            ) => rrows1
                .clone()
                .subsumed_by(rrows2.clone(), state, ctxt)
                .map_err(|err| err.into_unif_err(mk_uty_record!(;rrows2), mk_uty_record!(;rrows1))),
            // T <: U if T = U
            (inferred, checked) => checked.unify(inferred, state, &ctxt),
        }
    }
}

impl<'ast> SubsumedBy<'ast> for UnifRecordRows<'ast> {
    type Error = RowUnifError<'ast>;

    fn subsumed_by(
        self,
        t2: Self,
        state: &mut State<'ast, '_>,
        ctxt: Context<'ast>,
    ) -> Result<(), Self::Error> {
        // This code is almost taken verbatim from `unify`, but where some recursive calls are
        // changed to be `subsumed_by` instead of `unify`, and where missing row and extra row
        // errors have been swapped (since `subsumed_by` and `unify` are reversed with respect to
        // which argument is the expected type and which is the inferred type).
        //
        // We can surely factorize both into a generic function, but this is left for future work.
        let inferred = self.into_root(state.table);
        let checked = t2.into_root(state.table);

        match (inferred, checked) {
            (
                UnifRecordRows::Concrete {
                    rrows: rrows1,
                    var_levels_data: levels1,
                },
                UnifRecordRows::Concrete { rrows: rrows2, .. },
            ) => match (rrows1, rrows2) {
                // We reverse the order of the arguments when compared to `unify`. It shouldn't
                // really matter, but experience shows that the inferred type - here on the left -
                // is often much bigger in a structural type system, than the expected type (coming
                // from constraints or annotations).
                //
                // For example, when checking `array.fold_left` where `array` is `std.array`. The
                // expected type (right hand side of `subsume`) is `{ fold_left : ?a; ?b }`. The
                // inferred type is, on the other hand, quite big: it's the list of all functions
                // in the `array` module.
                //
                // If we started to pop stuff from the inferred type, we would iterate through all
                // array functions - until `fold_left` - and consecutively extend `?b` to match
                // that, which is useless. In the end, we just want to find `fold_left` in the type
                // of `array` and match `?a` to its type. Starting to pop stuff from the expected
                // type instead achieve that in one step.
                (
                    rrows1 @ RecordRowsF::Extend { .. },
                    RecordRowsF::Extend {
                        row: row2,
                        tail: tail2,
                    },
                ) => {
                    let urrows1 = UnifRecordRows::Concrete {
                        rrows: rrows1,
                        var_levels_data: levels1,
                    };

                    let (ty_res, urrows_without_ty_res) = urrows1
                        .remove_row(&row2.id, &row2.typ, state, ctxt.var_level)
                        .map_err(|err| match err {
                            RemoveRowError::Missing => RowUnifErrorKind::MissingRecordRow(row2.id),
                            RemoveRowError::Conflict => {
                                RowUnifErrorKind::RecordRowConflict(row2.clone())
                            }
                        })?;
                    if let RemoveRowResult::Extracted(ty) = ty_res {
                        ty.subsumed_by(*row2.typ, state, ctxt.clone())
                            .map_err(|err| {
                                Box::new(RowUnifErrorKind::RecordRowMismatch {
                                    id: row2.id,
                                    cause: err,
                                })
                            })?;
                    }

                    urrows_without_ty_res.subsumed_by(*tail2, state, ctxt)
                }
                (RecordRowsF::TailVar(id), _) | (_, RecordRowsF::TailVar(id)) => {
                    Err(Box::new(RowUnifErrorKind::UnboundTypeVariable(id)))
                }
                (RecordRowsF::Empty, RecordRowsF::Empty)
                | (RecordRowsF::TailDyn, RecordRowsF::TailDyn) => Ok(()),
                (RecordRowsF::Empty, RecordRowsF::TailDyn)
                | (RecordRowsF::TailDyn, RecordRowsF::Empty) => {
                    Err(Box::new(RowUnifErrorKind::ExtraDynTail))
                }
                (
                    RecordRowsF::Empty,
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                )
                | (
                    RecordRowsF::TailDyn,
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                ) => Err(Box::new(RowUnifErrorKind::MissingRecordRow(id))),
                (
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                    RecordRowsF::TailDyn,
                )
                | (
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                    RecordRowsF::Empty,
                ) => Err(Box::new(RowUnifErrorKind::ExtraRow(id))),
            },
            (UnifRecordRows::UnifVar { id, .. }, urrows)
            | (urrows, UnifRecordRows::UnifVar { id, .. }) => {
                if let UnifRecordRows::Constant(cst_id) = urrows {
                    let constant_level = state.table.get_rrows_level(cst_id);
                    state.table.force_rrows_updates(constant_level);
                    if state.table.get_rrows_level(id) < constant_level {
                        return Err(Box::new(RowUnifErrorKind::VarLevelMismatch {
                            constant_id: cst_id,
                            var_kind: VarKindDiscriminant::RecordRows,
                        }));
                    }
                }
                urrows.propagate_constrs(state.constr, id)?;
                state.table.assign_rrows(id, urrows);
                Ok(())
            }
            (UnifRecordRows::Constant(i1), UnifRecordRows::Constant(i2)) if i1 == i2 => Ok(()),
            (UnifRecordRows::Constant(i1), UnifRecordRows::Constant(i2)) => {
                Err(Box::new(RowUnifErrorKind::ConstMismatch {
                    var_kind: VarKindDiscriminant::RecordRows,
                    expected_const_id: i2,
                    inferred_const_id: i1,
                }))
            }
            (urrows, UnifRecordRows::Constant(i)) | (UnifRecordRows::Constant(i), urrows) => {
                Err(Box::new(RowUnifErrorKind::WithConst {
                    var_kind: VarKindDiscriminant::RecordRows,
                    expected_const_id: i,
                    inferred: UnifType::concrete(TypeF::Record(urrows)),
                }))
            }
        }
    }
}//! Types unification.

use super::{eq::TypeEq, *};

/// Unification variable or type constants unique identifier.
pub type VarId = usize;

/// Variable levels. Levels are used in order to implement polymorphism in a sound way: we need to
/// associate to each unification variable and rigid type variable a level, which depends on when
/// those variables were introduced, and to forbid some unifications if a condition on levels is
/// not met.
#[derive(Clone, Copy, Ord, Eq, PartialEq, PartialOrd, Debug)]
pub struct VarLevel(NonZeroU16);

impl VarLevel {
    /// Special constant used for level upper bound to indicate that a type doesn't contain any
    /// unification variable. It's equal to `1` and strictly smaller than [VarLevel::MIN_LEVEL], so
    /// it's strictly smaller than any concrete variable level.
    pub const NO_VAR: Self = VarLevel(NonZeroU16::MIN);
    /// The first available variable level, `2`.
    // unsafe is required because `unwrap()` is not usable in `const fn` code as of today in stable
    // Rust.
    pub const MIN_LEVEL: Self = VarLevel(NonZeroU16::new(2).unwrap());
    /// The maximum level. Used as an upper bound to indicate that nothing can be said about the
    /// levels of the unification variables contained in a type.
    pub const MAX_LEVEL: Self = VarLevel(NonZeroU16::MAX);

    /// Increment the variable level by one. Panic if the maximum capacity of the underlying
    /// numeric type is reached (currently, `u16::MAX`).
    pub fn incr(&mut self) {
        let new_value = self
            .0
            .checked_add(1)
            .expect("reached the maximum unification variable level");
        self.0 = new_value;
    }
}

/// An element of the unification table. Contains the potential type this variable points to (or
/// `None` if the variable hasn't been unified with something yet), and the variable's level.
pub struct UnifSlot<Ty> {
    value: Option<Ty>,
    level: VarLevel,
}

impl<Ty> UnifSlot<Ty> {
    pub fn new(level: VarLevel) -> Self {
        UnifSlot { value: None, level }
    }
}

/// The unification table.
///
/// Map each unification variable to either another type variable or a concrete type it has been
/// unified with. Each binding `(ty, var)` in this map should be thought of an edge in a
/// unification graph.
///
/// The unification table is really three separate tables, corresponding to the different kinds of
/// types: standard types, record rows, and enum rows.
///
/// The unification table is a relatively low-level data structure, whose consumer has to ensure
/// specific invariants. It is used by the `unify` function and its variants, but you should avoid
/// using it directly, unless you know what you're doing.
#[derive(Default)]
pub struct UnifTable<'ast> {
    types: Vec<UnifSlot<UnifType<'ast>>>,
    rrows: Vec<UnifSlot<UnifRecordRows<'ast>>>,
    erows: Vec<UnifSlot<UnifEnumRows<'ast>>>,
    pending_type_updates: Vec<VarId>,
    pending_rrows_updates: Vec<VarId>,
    pending_erows_updates: Vec<VarId>,
}

impl<'ast> UnifTable<'ast> {
    pub fn new() -> Self {
        UnifTable::default()
    }

    /// Assign a type to a type unification variable.
    ///
    /// This method updates variables level, at least lazily, by pushing them to a stack of pending
    /// traversals.
    ///
    /// # Preconditions
    ///
    /// - This method doesn't check for the variable level conditions. This is the responsibility
    ///   of the caller.
    /// - If the target type is a unification variable as well, it must not be assigned to another
    ///   unification type. That is, `assign` should always be passed a root type. Otherwise, the
    ///   handling of variable levels will be messed up.
    /// - This method doesn't force pending level updates when needed (calling to
    ///   `force_type_updates`), i.e. when `uty` is a rigid type variable. Having pending variable
    ///   level updates and using `assign_type` might make typechecking incorrect in some situation
    ///   by unduly allowing unsound generalization. This is the responsibility of the caller.
    pub fn assign_type(&mut self, var: VarId, uty: UnifType<'ast>) {
        // Unifying a free variable with itself is a no-op.
        if matches!(uty, UnifType::UnifVar { id, ..} if id == var) {
            return;
        }

        debug_assert!({
            if let UnifType::UnifVar { id, init_level: _ } = &uty {
                self.types[*id].value.is_none()
            } else {
                true
            }
        });
        debug_assert!(self.types[var].value.is_none());

        let uty_lvl_updated = self.update_type_level(var, uty, self.types[var].level);
        self.types[var].value = Some(uty_lvl_updated);
    }

    // Lazily propagate a variable level to the unification variables contained in `uty`. Either do
    // a direct update in constant time when possible, or push a stack of delayed updates for
    // composite types.
    fn update_type_level(
        &mut self,
        var: VarId,
        uty: UnifType<'ast>,
        new_level: VarLevel,
    ) -> UnifType<'ast> {
        match uty {
            // We can do the update right away
            UnifType::UnifVar { id, init_level } => {
                if new_level < self.types[id].level {
                    self.types[id].level = new_level;
                }

                UnifType::UnifVar { id, init_level }
            }
            // If a concrete type is a candidate for update, we push the pending update on the
            // stack
            UnifType::Concrete {
                typ,
                var_levels_data,
            } if var_levels_data.upper_bound >= new_level => {
                self.pending_type_updates.push(var);

                UnifType::Concrete {
                    typ,
                    var_levels_data: VarLevelsData {
                        pending: Some(new_level),
                        ..var_levels_data
                    },
                }
            }
            // The remaining types either don't contain unification variables or have all their
            // level greater than the updated level
            _ => uty,
        }
    }

    /// Assign record rows to a record rows unification variable.
    ///
    /// This method updates variables level, at least lazily, by pushing them to a stack of pending
    /// traversals.
    ///
    /// # Preconditions
    ///
    /// - This method doesn't check for the variable level conditions. This is the responsibility
    ///   of the caller.
    /// - If the target type is a unification variable as well, it must not be assigned to another
    ///   unification type. That is, `assign` should always be passed a root type. Otherwise, the
    ///   handling of variable levels will be messed up.
    /// - This method doesn't force pending level updates when needed (calling to
    ///   `force_rrows_updates`), i.e. when `uty` is a rigid type variable. Having pending variable
    ///   level updates and using `assign_type` might make typechecking incorrect in some situation
    ///   by unduly allowing unsound generalization. This is the responsibility of the caller.
    pub fn assign_rrows(&mut self, var: VarId, rrows: UnifRecordRows<'ast>) {
        // Unifying a free variable with itself is a no-op.
        if matches!(rrows, UnifRecordRows::UnifVar { id, ..} if id == var) {
            return;
        }

        self.update_rrows_level(var, &rrows, self.rrows[var].level);
        debug_assert!(self.rrows[var].value.is_none());
        self.rrows[var].value = Some(rrows);
    }

    // cf `update_type_level()`
    fn update_rrows_level(&mut self, var: VarId, uty: &UnifRecordRows<'ast>, new_level: VarLevel) {
        match uty {
            // We can do the update right away
            UnifRecordRows::UnifVar {
                id: var_id,
                init_level: _,
            } => {
                if new_level < self.rrows[*var_id].level {
                    self.rrows[*var_id].level = new_level;
                }
            }
            // If concrete rows are a candidate for update, we push the pending update on the stack
            UnifRecordRows::Concrete {
                var_levels_data, ..
            } if var_levels_data.upper_bound >= new_level => self.pending_rrows_updates.push(var),
            // The remaining rows either don't contain unification variables or have all their
            // level greater than the updated level
            _ => (),
        }
    }

    /// Assign enum rows to an enum rows unification variable.
    ///
    /// This method updates variables level, at least lazily, by pushing them to a stack of pending
    /// traversals.
    ///
    /// # Preconditions
    ///
    /// - This method doesn't check for the variable level conditions. This is the responsibility
    ///   of the caller.
    /// - If the target type is a unification variable as well, it must not be assigned to another
    ///   unification type. That is, `assign` should always be passed a root type. Otherwise, the
    ///   handling of variable levels will be messed up.
    /// - This method doesn't force pending level updates when needed (calling to
    ///   `force_erows_updates`), i.e. when `uty` is a rigid type variable. Having pending variable
    ///   level updates and using `assign_type` might make typechecking incorrect in some situation
    ///   by unduly allowing unsound generalization. This is the responsibility of the caller.
    pub fn assign_erows(&mut self, var: VarId, erows: UnifEnumRows<'ast>) {
        // Unifying a free variable with itself is a no-op.
        if matches!(erows, UnifEnumRows::UnifVar { id, .. } if id == var) {
            return;
        }

        self.update_erows_level(var, &erows, self.erows[var].level);
        debug_assert!(self.erows[var].value.is_none());
        self.erows[var].value = Some(erows);
    }

    // cf `update_type_level()`
    fn update_erows_level(&mut self, var: VarId, uty: &UnifEnumRows<'ast>, new_level: VarLevel) {
        match uty {
            // We can do the update right away
            UnifEnumRows::UnifVar {
                id: var_id,
                init_level: _,
            } => {
                if new_level < self.erows[*var_id].level {
                    self.erows[*var_id].level = new_level;
                }
            }
            // If concrete rows are a candidate for update, we push the pending update on the stack
            UnifEnumRows::Concrete {
                var_levels_data, ..
            } if var_levels_data.upper_bound >= new_level => self.pending_erows_updates.push(var),
            // The remaining rows either don't contain unification variables or have all their
            // level greater than the updated level
            _ => (),
        }
    }

    /// Retrieve the current assignment of a type unification variable.
    pub fn get_type(&self, var: VarId) -> Option<&UnifType<'ast>> {
        self.types[var].value.as_ref()
    }

    /// Retrieve the current level of a unification variable or a rigid type variable.
    pub fn get_level(&self, var: VarId) -> VarLevel {
        self.types[var].level
    }

    /// Retrieve the current assignment of a record rows unification variable.
    pub fn get_rrows(&self, var: VarId) -> Option<&UnifRecordRows<'ast>> {
        self.rrows[var].value.as_ref()
    }

    /// Retrieve the current level of a record rows unification variable or a record rows rigid
    /// type variable.
    pub fn get_rrows_level(&self, var: VarId) -> VarLevel {
        self.rrows[var].level
    }

    /// Retrieve the current assignment of an enum rows unification variable.
    pub fn get_erows(&self, var: VarId) -> Option<&UnifEnumRows<'ast>> {
        self.erows[var].value.as_ref()
    }

    /// Retrieve the current level of an enu rows unification variable or a record rows rigid type
    /// variable.
    pub fn get_erows_level(&self, var: VarId) -> VarLevel {
        self.erows[var].level
    }

    /// Create a fresh type unification variable (or constant) identifier and allocate a
    /// corresponding slot in the table.
    pub fn fresh_type_var_id(&mut self, current_level: VarLevel) -> VarId {
        let next = self.types.len();
        self.types.push(UnifSlot::new(current_level));
        next
    }

    /// Create a fresh record rows variable (or constant) identifier and allocate a corresponding
    /// slot in the table.
    pub fn fresh_rrows_var_id(&mut self, current_level: VarLevel) -> VarId {
        let next = self.rrows.len();
        self.rrows.push(UnifSlot::new(current_level));
        next
    }

    /// Create a fresh enum rows variable (or constant) identifier and allocate a corresponding
    /// slot in the table.
    pub fn fresh_erows_var_id(&mut self, current_level: VarLevel) -> VarId {
        let next = self.erows.len();
        self.erows.push(UnifSlot::new(current_level));
        next
    }

    /// Create a fresh type unification variable and allocate a corresponding slot in the table.
    pub fn fresh_type_uvar(&mut self, current_level: VarLevel) -> UnifType<'ast> {
        UnifType::UnifVar {
            id: self.fresh_type_var_id(current_level),
            init_level: current_level,
        }
    }

    /// Create a fresh record rows unification variable and allocate a corresponding slot in the
    /// table.
    pub fn fresh_rrows_uvar(&mut self, current_level: VarLevel) -> UnifRecordRows<'ast> {
        UnifRecordRows::UnifVar {
            id: self.fresh_rrows_var_id(current_level),
            init_level: current_level,
        }
    }

    /// Create a fresh enum rows unification variable and allocate a corresponding slot in the
    /// table.
    pub fn fresh_erows_uvar(&mut self, current_level: VarLevel) -> UnifEnumRows<'ast> {
        UnifEnumRows::UnifVar {
            id: self.fresh_erows_var_id(current_level),
            init_level: current_level,
        }
    }

    /// Create a fresh type constant and allocate a corresponding slot in the table.
    pub fn fresh_type_const(&mut self, current_level: VarLevel) -> UnifType<'ast> {
        UnifType::Constant(self.fresh_type_var_id(current_level))
    }

    /// Create a fresh record rows constant and allocate a corresponding slot in the table.
    pub fn fresh_rrows_const(&mut self, current_level: VarLevel) -> UnifRecordRows<'ast> {
        UnifRecordRows::Constant(self.fresh_rrows_var_id(current_level))
    }

    /// Create a fresh enum rows constant and allocate a corresponding slot in the table.
    pub fn fresh_erows_const(&mut self, current_level: VarLevel) -> UnifEnumRows<'ast> {
        UnifEnumRows::Constant(self.fresh_erows_var_id(current_level))
    }

    /// Follow the links in the unification table to find the representative of the equivalence
    /// class of the type unification variable `x`.
    ///
    /// This corresponds to the find in union-find.
    // TODO This should be a union find like algorithm
    pub fn root_type(&self, var_id: VarId, init_level: VarLevel) -> UnifType<'ast> {
        // All queried variable must have been introduced by `new_var` and thus a corresponding
        // entry must always exist in `state`. If not, the typechecking algorithm is not correct,
        // and we panic.
        match self.types[var_id].value.as_ref() {
            None => UnifType::UnifVar {
                id: var_id,
                init_level,
            },
            Some(UnifType::UnifVar { id, init_level }) => self.root_type(*id, *init_level),
            Some(ty) => ty.clone(),
        }
    }

    /// Follow the links in the unification table to find the representative of the equivalence
    /// class of the record rows unification variable `x`.
    ///
    /// This corresponds to the find in union-find.
    // TODO This should be a union find like algorithm
    pub fn root_rrows(&self, var_id: VarId, init_level: VarLevel) -> UnifRecordRows<'ast> {
        // All queried variable must have been introduced by `new_var` and thus a corresponding
        // entry must always exist in `state`. If not, the typechecking algorithm is not correct,
        // and we panic.
        match self.rrows[var_id].value.as_ref() {
            None => UnifRecordRows::UnifVar {
                id: var_id,
                init_level,
            },
            Some(UnifRecordRows::UnifVar { id, init_level }) => self.root_rrows(*id, *init_level),
            Some(ty) => ty.clone(),
        }
    }

    /// Follow the links in the unification table to find the representative of the equivalence
    /// class of the enum rows unification variable `x`.
    ///
    /// This corresponds to the find in union-find.
    // TODO This should be a union find like algorithm
    pub fn root_erows(&self, var_id: VarId, init_level: VarLevel) -> UnifEnumRows<'ast> {
        // All queried variable must have been introduced by `new_var` and thus a corresponding
        // entry must always exist in `state`. If not, the typechecking algorithm is not correct,
        // and we panic.
        match self.erows[var_id].value.as_ref() {
            None => UnifEnumRows::UnifVar {
                id: var_id,
                init_level,
            },
            Some(UnifEnumRows::UnifVar { id, init_level }) => self.root_erows(*id, *init_level),
            Some(ty) => ty.clone(),
        }
    }

    /// Return a `VarId` greater than all of the variables currently allocated (unification and
    /// rigid type variables, of all kinds, rows or types). The returned UID is guaranteed to be
    /// different from all the currently live variables. This is currently simply the max of the
    /// length of the various unification tables.
    ///
    /// Used inside [self::eq] to generate temporary rigid type variables that are guaranteed to
    /// not conflict with existing variables.
    pub fn max_uvars_count(&self) -> VarId {
        max(self.types.len(), max(self.rrows.len(), self.erows.len()))
    }

    /// This function forces pending type updates prior to unifying a variable with a rigid type
    /// variable of level `constant_level`. Updates that wouldn't change the outcome of such a
    /// unification are delayed further.
    ///
    /// The whole point of variable levels is to forbid some unsound unifications of a unification
    /// variable with a rigid type variable. For performance reasons, those levels aren't
    /// propagated immediately when unifying a variable with a concrete type, but lazily stored at
    /// the level of types (see [VarLevel]).
    ///
    /// However, unifying with a rigid type variable is an instance that requires levels to be up
    /// to date. In this case, this function must be called before checking variable levels.
    ///
    /// # Parameters
    ///
    /// - `constant_level`: the level of the rigid type variable we're unifying with. While not
    ///   strictly required to propagate levels, it is used to eschew variable level updates that
    ///   wouldn't change the outcome of the unfication, which we can keep for later forced
    ///   updates.
    fn force_type_updates(&mut self, constant_level: VarLevel) {
        fn update_unr_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            uty: UnifTypeUnr<'ast>,
            level: VarLevel,
        ) -> UnifTypeUnr<'ast> {
            uty.map_state(
                |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                |rrows, table| update_rrows_with_lvl(table, rrows, level),
                |erows, table| update_erows_with_lvl(table, erows, level),
                |ctr, _| ctr,
                table,
            )
        }

        fn update_rrows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRows<'ast>,
            level: VarLevel,
        ) -> UnifRecordRows<'ast> {
            let rrows = rrows.into_root(table);

            match rrows {
                UnifRecordRows::Concrete {
                    rrows,
                    var_levels_data,
                } => {
                    let rrows = rrows.map_state(
                        |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                        |rrows, table| Box::new(update_rrows_with_lvl(table, *rrows, level)),
                        table,
                    );

                    // [^var-level-kinds]: Note that for `UnifRecordRows<'ast>` (and for enum rows as
                    // well), the variable levels data are concerned with record rows unification
                    // variables, not type unification variable. We thus let them untouched, as
                    // updating record rows variable levels is an orthogonal concern.
                    UnifRecordRows::Concrete {
                        rrows,
                        var_levels_data,
                    }
                }
                UnifRecordRows::UnifVar { .. } | UnifRecordRows::Constant(_) => rrows,
            }
        }

        fn update_erows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRows<'ast>,
            level: VarLevel,
        ) -> UnifEnumRows<'ast> {
            let erows = erows.into_root(table);

            match erows {
                UnifEnumRows::Concrete {
                    erows,
                    var_levels_data,
                } => {
                    let erows = erows.map_state(
                        |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                        |erows, table| Box::new(update_erows_with_lvl(table, *erows, level)),
                        table,
                    );

                    // see [^var-level-kinds]
                    UnifEnumRows::Concrete {
                        erows,
                        var_levels_data,
                    }
                }
                UnifEnumRows::UnifVar { .. } | UnifEnumRows::Constant(_) => erows,
            }
        }

        fn update_utype_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            uty: UnifType<'ast>,
            level: VarLevel,
        ) -> UnifType<'ast> {
            let uty = uty.into_root(table);

            match uty {
                UnifType::UnifVar { id, init_level } => {
                    if table.types[id].level > level {
                        table.types[id].level = level;
                    }

                    UnifType::UnifVar { id, init_level }
                }
                UnifType::Concrete {
                    typ,
                    var_levels_data,
                } if var_levels_data.upper_bound > level => {
                    let level = var_levels_data
                        .pending
                        .map(|pending_level| max(pending_level, level))
                        .unwrap_or(level);
                    let typ = update_unr_with_lvl(table, typ, level);

                    UnifType::Concrete {
                        typ,
                        var_levels_data: VarLevelsData {
                            upper_bound: level,
                            pending: None,
                        },
                    }
                }
                UnifType::Constant(_) | UnifType::Concrete { .. } => uty,
            }
        }

        fn update_utype<'ast>(
            table: &mut UnifTable<'ast>,
            uty: UnifType<'ast>,
            constant_level: VarLevel,
        ) -> (UnifType<'ast>, bool) {
            match uty {
                UnifType::UnifVar { .. } => {
                    // We should never end up updating the level of a type variable, as this update
                    // is done on the spot.
                    debug_assert!(false);

                    (uty, false)
                }
                UnifType::Concrete {
                    typ,
                    var_levels_data:
                        VarLevelsData {
                            pending: Some(pending_level),
                            upper_bound,
                        },
                } => {
                    // [^irrelevant-level-update]: A level update where the if-condition below is
                    // true wouldn't change the outcome of unifying a variable with a constant of
                    // level `constant_level`.
                    //
                    // Impactful updates are updates that might change the level of a variable from
                    // a value greater than or equals to `constant_level` to a new level strictly
                    // smaller, but:
                    //
                    // 1. If `upper_bound` < `constant_level`, then all unification variable levels
                    //    are already strictly smaller than `constant_level`. An update won't change
                    //    this inequality (level update can only decrease levels)
                    // 2. If `pending_level` >= `constant_level`, then the update might only
                    //    decrease a level that was greater than `constant_level` to a
                    //    `pending_level` which is still greater than `constant_level`. Once again,
                    //    the update doesn't change the inequality with respect to constant_level.
                    //
                    // Thus, such updates might be delayed even more.
                    if upper_bound < constant_level || pending_level >= constant_level {
                        return (
                            UnifType::Concrete {
                                typ,
                                var_levels_data: VarLevelsData {
                                    upper_bound: pending_level,
                                    pending: Some(pending_level),
                                },
                            },
                            true,
                        );
                    }

                    let typ = if upper_bound > pending_level {
                        update_unr_with_lvl(table, typ, pending_level)
                    } else {
                        typ
                    };

                    (
                        UnifType::Concrete {
                            typ,
                            var_levels_data: VarLevelsData {
                                upper_bound: pending_level,
                                pending: None,
                            },
                        },
                        false,
                    )
                }
                // [^ignore-no-pending-level] If there is no pending level, then this update has
                // already been handled (possibly by a forced update on an enclosing type), and
                // there's nothing to do.
                //
                // Note that this type might still contain other pending updates deeper inside, but
                // those are registered as pending updates and will be processed in any case.
                UnifType::Constant(_) | UnifType::Concrete { .. } => (uty, false),
            }
        }

        let rest = std::mem::take(&mut self.pending_type_updates)
            .into_iter()
            .filter(|id| {
                // unwrap(): if a unification variable has been push on the update stack, it
                // has been been by `assign_type`, and thus MUST have been assigned to
                // something.
                let typ = self.types[*id].value.take().unwrap();
                let (new_type, delayed) = update_utype(self, typ, constant_level);
                self.types[*id].value = Some(new_type);

                delayed
            })
            .collect();

        self.pending_type_updates = rest;
    }

    /// See `force_type_updates`. Same as `force_type_updates`, but when unifying a record row
    /// unification variable.
    pub fn force_rrows_updates(&mut self, constant_level: VarLevel) {
        fn update_rrows_unr_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRowsUnr<'ast>,
            level: VarLevel,
        ) -> UnifRecordRowsUnr<'ast> {
            rrows.map_state(
                |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                |rrows, table| Box::new(update_rrows_with_lvl(table, *rrows, level)),
                table,
            )
        }

        fn update_erows_unr_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRowsUnr<'ast>,
            level: VarLevel,
        ) -> UnifEnumRowsUnr<'ast> {
            erows.map_state(
                |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                |erows, table| Box::new(update_erows_with_lvl(table, *erows, level)),
                table,
            )
        }

        fn update_utype_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            utype: UnifType<'ast>,
            level: VarLevel,
        ) -> UnifType<'ast> {
            let utype = utype.into_root(table);

            match utype {
                UnifType::Concrete {
                    typ,
                    var_levels_data,
                } => {
                    let typ = typ.map_state(
                        |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                        |rrows, table| update_rrows_with_lvl(table, rrows, level),
                        |erows, table| update_erows_with_lvl(table, erows, level),
                        |ctr, _| ctr,
                        table,
                    );

                    // See [^var-level-kinds]
                    UnifType::Concrete {
                        typ,
                        var_levels_data,
                    }
                }
                UnifType::UnifVar { .. } | UnifType::Constant(_) => utype,
            }
        }

        fn update_rrows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRows<'ast>,
            level: VarLevel,
        ) -> UnifRecordRows<'ast> {
            let rrows = rrows.into_root(table);

            match rrows {
                UnifRecordRows::UnifVar { id, init_level } => {
                    if table.rrows[id].level > level {
                        table.rrows[id].level = level;
                    }

                    UnifRecordRows::UnifVar { id, init_level }
                }
                UnifRecordRows::Concrete {
                    rrows,
                    var_levels_data,
                } if var_levels_data.upper_bound > level => {
                    let level = var_levels_data
                        .pending
                        .map(|pending_level| max(pending_level, level))
                        .unwrap_or(level);
                    let rrows = update_rrows_unr_with_lvl(table, rrows, level);

                    UnifRecordRows::Concrete {
                        rrows,
                        var_levels_data: VarLevelsData {
                            upper_bound: level,
                            pending: None,
                        },
                    }
                }
                UnifRecordRows::Constant(_) | UnifRecordRows::Concrete { .. } => rrows,
            }
        }

        fn update_erows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRows<'ast>,
            level: VarLevel,
        ) -> UnifEnumRows<'ast> {
            let erows = erows.into_root(table);

            match erows {
                UnifEnumRows::Concrete {
                    erows,
                    var_levels_data,
                } => {
                    let erows = update_erows_unr_with_lvl(table, erows, level);

                    // See [^var-level-kinds]
                    UnifEnumRows::Concrete {
                        erows,
                        var_levels_data,
                    }
                }
                UnifEnumRows::UnifVar { .. } | UnifEnumRows::Constant(_) => erows,
            }
        }

        fn update_rrows<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRows<'ast>,
            constant_level: VarLevel,
        ) -> (UnifRecordRows<'ast>, bool) {
            match rrows {
                UnifRecordRows::UnifVar { .. } => {
                    // We should never end up updating the level of a unification variable, as this
                    // update is done on the spot.
                    debug_assert!(false);

                    (rrows, false)
                }
                UnifRecordRows::Concrete {
                    rrows,
                    var_levels_data:
                        VarLevelsData {
                            pending: Some(pending_level),
                            upper_bound,
                        },
                } => {
                    // See [^irrelevant-level-update]
                    if upper_bound < constant_level || pending_level >= constant_level {
                        return (
                            UnifRecordRows::Concrete {
                                rrows,
                                var_levels_data: VarLevelsData {
                                    upper_bound: pending_level,
                                    pending: Some(pending_level),
                                },
                            },
                            true,
                        );
                    }

                    let rrows = if upper_bound > pending_level {
                        update_rrows_unr_with_lvl(table, rrows, pending_level)
                    } else {
                        rrows
                    };

                    (
                        UnifRecordRows::Concrete {
                            rrows,
                            var_levels_data: VarLevelsData {
                                upper_bound: pending_level,
                                pending: None,
                            },
                        },
                        false,
                    )
                }
                // See [^ignore-no-pending-level]
                UnifRecordRows::Constant(_) | UnifRecordRows::Concrete { .. } => (rrows, false),
            }
        }

        let rest = std::mem::take(&mut self.pending_rrows_updates)
            .into_iter()
            .filter(|id| {
                // unwrap(): if a unification variable has been push on the update stack, it
                // has been been by `assign_rrows`, and thus MUST have been assigned to
                // something.
                let rrows = self.rrows[*id].value.take().unwrap();
                let (new_rrows, delay) = update_rrows(self, rrows, constant_level);
                self.rrows[*id].value = Some(new_rrows);

                delay
            })
            .collect();

        self.pending_rrows_updates = rest;
    }

    /// See `force_type_updates`. Same as `force_type_updates`, but when unifying an enum row
    /// unification variable.
    pub fn force_erows_updates(&mut self, constant_level: VarLevel) {
        fn update_rrows_unr_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRowsUnr<'ast>,
            level: VarLevel,
        ) -> UnifRecordRowsUnr<'ast> {
            rrows.map_state(
                |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                |rrows, table| Box::new(update_rrows_with_lvl(table, *rrows, level)),
                table,
            )
        }

        fn update_erows_unr_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRowsUnr<'ast>,
            level: VarLevel,
        ) -> UnifEnumRowsUnr<'ast> {
            erows.map_state(
                |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                |erows, table| Box::new(update_erows_with_lvl(table, *erows, level)),
                table,
            )
        }

        fn update_utype_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            utype: UnifType<'ast>,
            level: VarLevel,
        ) -> UnifType<'ast> {
            let utype = utype.into_root(table);

            match utype {
                UnifType::Concrete {
                    typ,
                    var_levels_data,
                } => {
                    let typ = typ.map_state(
                        |uty, table| Box::new(update_utype_with_lvl(table, *uty, level)),
                        |rrows, table| update_rrows_with_lvl(table, rrows, level),
                        |erows, table| update_erows_with_lvl(table, erows, level),
                        |ctr, _| ctr,
                        table,
                    );

                    // See [^var-level-kinds]
                    UnifType::Concrete {
                        typ,
                        var_levels_data,
                    }
                }
                UnifType::UnifVar { .. } | UnifType::Constant(_) => utype,
            }
        }

        fn update_rrows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            rrows: UnifRecordRows<'ast>,
            level: VarLevel,
        ) -> UnifRecordRows<'ast> {
            let rrows = rrows.into_root(table);

            match rrows {
                UnifRecordRows::Concrete {
                    rrows,
                    var_levels_data,
                } => {
                    let rrows = update_rrows_unr_with_lvl(table, rrows, level);

                    // See [^var-level-kinds]
                    UnifRecordRows::Concrete {
                        rrows,
                        var_levels_data,
                    }
                }
                UnifRecordRows::UnifVar { .. } | UnifRecordRows::Constant(_) => rrows,
            }
        }

        fn update_erows_with_lvl<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRows<'ast>,
            level: VarLevel,
        ) -> UnifEnumRows<'ast> {
            let erows = erows.into_root(table);

            match erows {
                UnifEnumRows::UnifVar { id, init_level } => {
                    if table.erows[id].level > level {
                        table.erows[id].level = level;
                    }

                    UnifEnumRows::UnifVar { id, init_level }
                }
                UnifEnumRows::Concrete {
                    erows,
                    var_levels_data,
                } if var_levels_data.upper_bound > level => {
                    let level = var_levels_data
                        .pending
                        .map(|pending_level| max(pending_level, level))
                        .unwrap_or(level);
                    let erows = update_erows_unr_with_lvl(table, erows, level);

                    UnifEnumRows::Concrete {
                        erows,
                        var_levels_data: VarLevelsData {
                            upper_bound: level,
                            pending: None,
                        },
                    }
                }
                UnifEnumRows::Constant(_) | UnifEnumRows::Concrete { .. } => erows,
            }
        }

        fn update_erows<'ast>(
            table: &mut UnifTable<'ast>,
            erows: UnifEnumRows<'ast>,
            constant_level: VarLevel,
        ) -> (UnifEnumRows<'ast>, bool) {
            match erows {
                UnifEnumRows::UnifVar { .. } => {
                    // We should never end up updating the level of a unification variable, as this
                    // update is done on the spot.
                    debug_assert!(false);

                    (erows, false)
                }
                UnifEnumRows::Concrete {
                    erows,
                    var_levels_data:
                        VarLevelsData {
                            pending: Some(pending_level),
                            upper_bound,
                        },
                } => {
                    // See [^irrelevant-level-update]
                    if upper_bound < constant_level || pending_level >= constant_level {
                        return (
                            UnifEnumRows::Concrete {
                                erows,
                                var_levels_data: VarLevelsData {
                                    upper_bound: pending_level,
                                    pending: Some(pending_level),
                                },
                            },
                            true,
                        );
                    }

                    let erows = if upper_bound > pending_level {
                        update_erows_unr_with_lvl(table, erows, pending_level)
                    } else {
                        erows
                    };

                    (
                        UnifEnumRows::Concrete {
                            erows,
                            var_levels_data: VarLevelsData {
                                upper_bound: pending_level,
                                pending: None,
                            },
                        },
                        false,
                    )
                }
                // See [^ignore-no-pending-level]
                UnifEnumRows::Constant(_) | UnifEnumRows::Concrete { .. } => (erows, false),
            }
        }

        let rest = std::mem::take(&mut self.pending_erows_updates)
            .into_iter()
            .filter(|id| {
                // unwrap(): if a unification variable has been pushed on the update stack, it must
                // have been done by `assign_erows`, and thus MUST have been assigned to something.
                let erows = self.erows[*id].value.take().unwrap();
                let (new_erows, delay) = update_erows(self, erows, constant_level);
                self.erows[*id].value = Some(new_erows);

                delay
            })
            .collect();

        self.pending_erows_updates = rest;
    }
}

/// Row constraints.
///
/// A row constraint applies to a unification variable appearing inside a row type (such as `r` in
/// `{ someId: SomeType ; r }` or `[| 'Foo Number, 'Baz; r |]`). A row constraint is a set of
/// identifiers that said row must NOT contain, to forbid ill-formed types with multiple
/// declaration of the same id, for example `{ a: Number, a: String}` or `[| 'Foo String, 'Foo
/// Number |]`.
///
/// Note that because the syntax (and pattern matching likewise) distinguishes between `'Foo` and
/// `'Foo some_arg`, the type `[| 'Foo, 'Foo SomeType |]` is unproblematic for typechecking. In
/// some sense, enum tags and enum variants live in a different dimension. It looks like we should
/// use separate sets of constraints for enum tag constraints and enum variants constraints. But a
/// set just for enum tag constraints is useless, because enum tags can never conflict, as they
/// don't have any argument: `'Foo` always "agrees with" another `'Foo` definition. In consequence,
/// we simply record enum variants constraints and ignore enum tags.
///
/// Note that a `VarId` always refer to either a type unification variable, a record row
/// unification variable or an enum row unification variable. Thus, we can use a single constraint
/// set per variable id (which isn't used at all for type unification variables). Because we expect
/// the map to be rather sparse, we use a `HashMap` instead of a `Vec`.
pub type RowConstrs = HashMap<VarId, HashSet<Ident>>;

pub(super) trait PropagateConstrs<'ast> {
    /// Check that unifying a variable with a type doesn't violate rows constraints, and update the
    /// row constraints of the unified type accordingly if needed.
    ///
    /// When a unification variable `UnifVar(p)` is unified with a type `uty` which is either a row type
    /// or another unification variable which could be later unified with a row type itself, the
    /// following operations are required:
    ///
    /// 1. If `uty` is a concrete row, check that it doesn't contain an identifier which is forbidden by
    ///    a row constraint on `p`.
    /// 2. If `uty` is either a unification variable `u` or a row type ending with a unification
    ///    variable `u`, we must add the constraints of `p` to the constraints of `u`. Indeed, take the
    ///    following situation: `p` appears in a row type `{a: Number ; p}`, hence has a constraint that
    ///    it must not contain a field `a`. Then `p` is unified with a fresh type variable `u`. If we
    ///    don't constrain `u`, `u` could be unified later with a row type `{a : String}` which violates
    ///    the original constraint on `p`. Thus, when unifying `p` with `u` or a row ending with `u`,
    ///    `u` must inherit all the constraints of `p`.
    fn propagate_constrs(
        &self,
        constr: &mut RowConstrs,
        var_id: VarId,
    ) -> Result<(), RowUnifError<'ast>>;
}

impl<'ast> PropagateConstrs<'ast> for UnifRecordRows<'ast> {
    fn propagate_constrs(
        &self,
        constr: &mut RowConstrs,
        var_id: VarId,
    ) -> Result<(), RowUnifError<'ast>> {
        fn propagate<'ast>(
            constr: &mut RowConstrs,
            var_id: VarId,
            var_constr: HashSet<Ident>,
            rrows: &UnifRecordRows<'ast>,
        ) -> Result<(), RowUnifError<'ast>> {
            match rrows {
                UnifRecordRows::Concrete {
                    rrows: RecordRowsF::Extend { row, .. },
                    ..
                } if var_constr.contains(&row.id.ident()) => {
                    Err(Box::new(RowUnifErrorKind::RecordRowConflict(row.clone())))
                }
                UnifRecordRows::Concrete {
                    rrows: RecordRowsF::Extend { tail, .. },
                    ..
                } => propagate(constr, var_id, var_constr, tail),
                UnifRecordRows::UnifVar { id, .. } if *id != var_id => {
                    if let Some(tail_constr) = constr.get_mut(id) {
                        tail_constr.extend(var_constr);
                    } else {
                        constr.insert(*id, var_constr);
                    }

                    Ok(())
                }
                _ => Ok(()),
            }
        }

        if let Some(var_constr) = constr.remove(&var_id) {
            propagate(constr, var_id, var_constr, self)
        } else {
            Ok(())
        }
    }
}

impl<'ast> PropagateConstrs<'ast> for UnifEnumRows<'ast> {
    fn propagate_constrs(
        &self,
        constr: &mut RowConstrs,
        var_id: VarId,
    ) -> Result<(), RowUnifError<'ast>> {
        fn propagate<'ast>(
            constr: &mut RowConstrs,
            var_id: VarId,
            var_constr: HashSet<Ident>,
            erows: &UnifEnumRows<'ast>,
        ) -> Result<(), RowUnifError<'ast>> {
            match erows {
                UnifEnumRows::Concrete {
                    // If the row is an enum tag (ie `typ` is `None`), it can't cause any conflict.
                    // See [RowConstrs] for more details.
                    erows:
                        EnumRowsF::Extend {
                            row:
                                row @ UnifEnumRow {
                                    id: _,
                                    typ: Some(_),
                                },
                            ..
                        },
                    ..
                } if var_constr.contains(&row.id.ident()) => {
                    Err(Box::new(RowUnifErrorKind::EnumRowConflict(row.clone())))
                }
                UnifEnumRows::Concrete {
                    erows: EnumRowsF::Extend { tail, .. },
                    ..
                } => propagate(constr, var_id, var_constr, tail),
                UnifEnumRows::UnifVar { id, .. } if *id != var_id => {
                    if let Some(tail_constr) = constr.get_mut(id) {
                        tail_constr.extend(var_constr);
                    } else {
                        constr.insert(*id, var_constr);
                    }

                    Ok(())
                }
                _ => Ok(()),
            }
        }

        if let Some(var_constr) = constr.remove(&var_id) {
            propagate(constr, var_id, var_constr, self)
        } else {
            Ok(())
        }
    }
}

/// Types which can be unified.
pub(super) trait Unify<'ast> {
    type Error;

    /// Try to unify two types. Unification corresponds to imposing an equality constraints on
    /// those types. This can fail if the types can't be matched.
    ///
    /// While unification is symmetric in principle, we make a difference in Nickel between the
    /// expected type (coming from the context, from annotations, etc.) and the inferred type,
    /// corresponding to the type of the expression as determined by its shape or other intrinsic
    /// properties. Note that "inferred" here doesn't really map precisely to the bidirectional
    /// typechecking vocabulary used elsewhere in the typechecker.
    ///
    /// Here, `self` is the expected type, and `t2` is the inferred type.
    fn unify(
        self,
        t2: Self,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
    ) -> Result<(), Self::Error>;
}

impl<'ast> Unify<'ast> for UnifType<'ast> {
    type Error = UnifError<'ast>;

    fn unify(
        self,
        t2: UnifType<'ast>,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
    ) -> Result<(), UnifError<'ast>> {
        let t1 = self.into_root(state.table);
        let t2 = t2.into_root(state.table);

        // t1 and t2 are roots of the type
        match (t1, t2) {
            // If either type is a wildcard, unify with the associated type var
            (
                UnifType::Concrete {
                    typ: TypeF::Wildcard(id),
                    ..
                },
                ty2,
            )
            | (
                ty2,
                UnifType::Concrete {
                    typ: TypeF::Wildcard(id),
                    ..
                },
            ) => {
                let ty1 = get_wildcard_var(state.table, ctxt.var_level, state.wildcard_vars, id);
                ty1.unify(ty2, state, ctxt)
            }
            (
                UnifType::Concrete {
                    typ: s1,
                    var_levels_data: _,
                },
                UnifType::Concrete {
                    typ: s2,
                    var_levels_data: _,
                },
            ) => match (s1, s2) {
                (TypeF::Dyn, TypeF::Dyn)
                | (TypeF::Number, TypeF::Number)
                | (TypeF::Bool, TypeF::Bool)
                | (TypeF::String, TypeF::String)
                | (TypeF::Symbol, TypeF::Symbol) => Ok(()),
                (TypeF::Array(uty1), TypeF::Array(uty2)) => uty1.unify(*uty2, state, ctxt),
                (TypeF::Arrow(s1s, s1t), TypeF::Arrow(s2s, s2t)) => {
                    s1s.clone()
                        .unify((*s2s).clone(), state, ctxt)
                        .map_err(|err| UnifErrorKind::DomainMismatch {
                            expected: UnifType::concrete(TypeF::Arrow(s1s.clone(), s1t.clone())),
                            inferred: UnifType::concrete(TypeF::Arrow(s2s.clone(), s2t.clone())),
                            cause: err,
                        })?;
                    s1t.clone()
                        .unify((*s2t).clone(), state, ctxt)
                        .map_err(|err| {
                            Box::new(UnifErrorKind::CodomainMismatch {
                                expected: UnifType::concrete(TypeF::Arrow(s1s, s1t)),
                                inferred: UnifType::concrete(TypeF::Arrow(s2s, s2t)),
                                cause: err,
                            })
                        })
                }
                (TypeF::Contract((t1, env1)), TypeF::Contract((t2, env2)))
                    if t1.type_eq(t2, &env1, &env2) =>
                {
                    Ok(())
                }
                (TypeF::Enum(erows1), TypeF::Enum(erows2)) => erows1
                    .clone()
                    .unify(erows2.clone(), state, ctxt)
                    .map_err(|err| {
                        err.into_unif_err(mk_uty_enum!(; erows1), mk_uty_enum!(; erows2))
                    }),
                (TypeF::Record(rrows1), TypeF::Record(rrows2)) => rrows1
                    .clone()
                    .unify(rrows2.clone(), state, ctxt)
                    .map_err(|err| {
                        err.into_unif_err(mk_uty_record!(; rrows1), mk_uty_record!(; rrows2))
                    }),
                (
                    TypeF::Dict {
                        type_fields: uty1, ..
                    },
                    TypeF::Dict {
                        type_fields: uty2, ..
                    },
                ) => uty1.unify(*uty2, state, ctxt),
                (
                    TypeF::Forall {
                        var: var1,
                        var_kind: var_kind1,
                        body: body1,
                    },
                    TypeF::Forall {
                        var: var2,
                        var_kind: var_kind2,
                        body: body2,
                    },
                ) if var_kind1 == var_kind2 => {
                    // Very stupid (slow) implementation
                    let (substd1, substd2) = match var_kind1 {
                        VarKind::Type => {
                            let constant_type = state.table.fresh_type_const(ctxt.var_level);
                            (
                                body1.subst(&var1, &constant_type),
                                body2.subst(&var2, &constant_type),
                            )
                        }
                        VarKind::RecordRows { .. } => {
                            let constant_type = state.table.fresh_rrows_const(ctxt.var_level);
                            (
                                body1.subst(&var1, &constant_type),
                                body2.subst(&var2, &constant_type),
                            )
                        }
                        VarKind::EnumRows { .. } => {
                            let constant_type = state.table.fresh_erows_const(ctxt.var_level);
                            (
                                body1.subst(&var1, &constant_type),
                                body2.subst(&var2, &constant_type),
                            )
                        }
                    };

                    substd1.unify(substd2, state, ctxt)
                }
                (TypeF::Var(ident), _) | (_, TypeF::Var(ident)) => {
                    Err(Box::new(UnifErrorKind::UnboundTypeVariable(ident.into())))
                }
                (ty1, ty2) => Err(Box::new(UnifErrorKind::TypeMismatch {
                    expected: UnifType::concrete(ty1),
                    inferred: UnifType::concrete(ty2),
                })),
            },
            (UnifType::UnifVar { id, .. }, uty) | (uty, UnifType::UnifVar { id, .. }) => {
                // [^check-unif-var-level]: If we are unifying a variable with a rigid type
                // variable, force potential unification variable level updates and check that the
                // level of the unification variable is greater or equals to the constant: that is,
                // that the variable doesn't "escape its scope". This is required to handle
                // polymorphism soundly, and is the whole point of all the machinery around variable
                // levels.
                if let UnifType::Constant(cst_id) = uty {
                    let constant_level = state.table.get_level(cst_id);
                    state.table.force_type_updates(constant_level);

                    if state.table.get_level(id) < constant_level {
                        return Err(Box::new(UnifErrorKind::VarLevelMismatch {
                            constant_id: cst_id,
                            var_kind: VarKindDiscriminant::Type,
                        }));
                    }
                }

                state.table.assign_type(id, uty);
                Ok(())
            }
            (UnifType::Constant(i1), UnifType::Constant(i2)) if i1 == i2 => Ok(()),
            (UnifType::Constant(i1), UnifType::Constant(i2)) => {
                Err(Box::new(UnifErrorKind::ConstMismatch {
                    var_kind: VarKindDiscriminant::Type,
                    expected_const_id: i1,
                    inferred_const_id: i2,
                }))
            }
            (ty, UnifType::Constant(i)) | (UnifType::Constant(i), ty) => {
                Err(Box::new(UnifErrorKind::WithConst {
                    var_kind: VarKindDiscriminant::Type,
                    expected_const_id: i,
                    inferred: ty,
                }))
            }
        }
    }
}

impl<'ast> Unify<'ast> for UnifEnumRows<'ast> {
    type Error = RowUnifError<'ast>;

    fn unify(
        self,
        uerows2: UnifEnumRows<'ast>,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
    ) -> Result<(), RowUnifError<'ast>> {
        let uerows1 = self.into_root(state.table);
        let uerows2 = uerows2.into_root(state.table);

        match (uerows1, uerows2) {
            (
                UnifEnumRows::Concrete {
                    erows: erows1,
                    var_levels_data: _,
                },
                UnifEnumRows::Concrete {
                    erows: erows2,
                    var_levels_data: var_levels2,
                },
            ) => match (erows1, erows2) {
                (EnumRowsF::TailVar(id), _) | (_, EnumRowsF::TailVar(id)) => {
                    Err(Box::new(RowUnifErrorKind::UnboundTypeVariable(id)))
                }
                (EnumRowsF::Empty, EnumRowsF::Empty) => Ok(()),
                (
                    EnumRowsF::Empty,
                    EnumRowsF::Extend {
                        row: UnifEnumRow { id, .. },
                        ..
                    },
                ) => Err(Box::new(RowUnifErrorKind::ExtraRow(id))),
                (
                    EnumRowsF::Extend {
                        row: UnifEnumRow { id, .. },
                        ..
                    },
                    EnumRowsF::Empty,
                ) => Err(Box::new(RowUnifErrorKind::MissingEnumRow(id))),
                (EnumRowsF::Extend { row, tail }, erows2 @ EnumRowsF::Extend { .. }) => {
                    let uerows2 = UnifEnumRows::Concrete {
                        erows: erows2,
                        var_levels_data: var_levels2,
                    };

                    let (ty2_result, t2_without_row) =
                        //TODO[adts]: it's ugly to create a temporary Option just to please the
                        //Box/Nobox types, we should find a better signature for remove_row
                        uerows2.remove_row(&row.id, &row.typ.clone().map(|typ| *typ), state, ctxt.var_level).map_err(|err| match err {
                            RemoveRowError::Missing => RowUnifErrorKind::MissingEnumRow(row.id),
                            RemoveRowError::Conflict => RowUnifErrorKind::EnumRowConflict(row.clone()),
                        })?;

                    // The alternative to this if-condition is `RemoveRowResult::Extended`, which
                    // means that `t2` could be successfully extended with the row `id typ`, in
                    // which case we don't have to perform additional unification for this specific
                    // row
                    if let RemoveRowResult::Extracted(ty2) = ty2_result {
                        match (row.typ, ty2) {
                            (Some(typ), Some(ty2)) => {
                                typ.unify(ty2, state, ctxt).map_err(|err| {
                                    RowUnifErrorKind::EnumRowMismatch {
                                        id: row.id,
                                        cause: Some(err),
                                    }
                                })?;
                            }
                            (Some(_), None) | (None, Some(_)) => {
                                return Err(Box::new(RowUnifErrorKind::EnumRowMismatch {
                                    id: row.id,
                                    cause: None,
                                }));
                            }
                            (None, None) => (),
                        }
                    }

                    tail.unify(t2_without_row, state, ctxt)
                }
            },
            (UnifEnumRows::UnifVar { id, init_level: _ }, uerows)
            | (uerows, UnifEnumRows::UnifVar { id, init_level: _ }) => {
                // see [^check-unif-var-level]
                if let UnifEnumRows::Constant(cst_id) = uerows {
                    let constant_level = state.table.get_erows_level(cst_id);
                    state.table.force_erows_updates(constant_level);

                    if state.table.get_erows_level(id) < constant_level {
                        return Err(Box::new(RowUnifErrorKind::VarLevelMismatch {
                            constant_id: cst_id,
                            var_kind: VarKindDiscriminant::EnumRows,
                        }));
                    }
                }

                uerows.propagate_constrs(state.constr, id)?;
                state.table.assign_erows(id, uerows);
                Ok(())
            }
            (UnifEnumRows::Constant(i1), UnifEnumRows::Constant(i2)) if i1 == i2 => Ok(()),
            (UnifEnumRows::Constant(i1), UnifEnumRows::Constant(i2)) => {
                Err(Box::new(RowUnifErrorKind::ConstMismatch {
                    var_kind: VarKindDiscriminant::EnumRows,
                    expected_const_id: i1,
                    inferred_const_id: i2,
                }))
            }
            (uerows, UnifEnumRows::Constant(i)) | (UnifEnumRows::Constant(i), uerows) => {
                //TODO ROWS: should we refactor RowUnifError as well?
                Err(Box::new(RowUnifErrorKind::WithConst {
                    var_kind: VarKindDiscriminant::EnumRows,
                    expected_const_id: i,
                    inferred: UnifType::concrete(TypeF::Enum(uerows)),
                }))
            }
        }
    }
}

impl<'ast> Unify<'ast> for UnifRecordRows<'ast> {
    type Error = RowUnifError<'ast>;

    fn unify(
        self,
        urrows2: UnifRecordRows<'ast>,
        state: &mut State<'ast, '_>,
        ctxt: &Context<'ast>,
    ) -> Result<(), RowUnifError<'ast>> {
        let urrows1 = self.into_root(state.table);
        let urrows2 = urrows2.into_root(state.table);

        match (urrows1, urrows2) {
            (
                UnifRecordRows::Concrete {
                    rrows: rrows1,
                    var_levels_data: _,
                },
                UnifRecordRows::Concrete {
                    rrows: rrows2,
                    var_levels_data: var_levels2,
                },
            ) => match (rrows1, rrows2) {
                (RecordRowsF::TailVar(id), _) | (_, RecordRowsF::TailVar(id)) => {
                    Err(Box::new(RowUnifErrorKind::UnboundTypeVariable(id)))
                }
                (RecordRowsF::Empty, RecordRowsF::Empty)
                | (RecordRowsF::TailDyn, RecordRowsF::TailDyn) => Ok(()),
                (RecordRowsF::Empty, RecordRowsF::TailDyn) => {
                    Err(Box::new(RowUnifErrorKind::ExtraDynTail))
                }
                (RecordRowsF::TailDyn, RecordRowsF::Empty) => {
                    Err(Box::new(RowUnifErrorKind::MissingDynTail))
                }
                (
                    RecordRowsF::Empty,
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                )
                | (
                    RecordRowsF::TailDyn,
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                ) => Err(Box::new(RowUnifErrorKind::ExtraRow(id))),
                (
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                    RecordRowsF::TailDyn,
                )
                | (
                    RecordRowsF::Extend {
                        row: UnifRecordRow { id, .. },
                        ..
                    },
                    RecordRowsF::Empty,
                ) => Err(Box::new(RowUnifErrorKind::MissingRecordRow(id))),
                (RecordRowsF::Extend { row, tail }, rrows2 @ RecordRowsF::Extend { .. }) => {
                    let urrows2 = UnifRecordRows::Concrete {
                        rrows: rrows2,
                        var_levels_data: var_levels2,
                    };

                    let (ty2_result, urrows2_without_ty2) = urrows2
                        .remove_row(&row.id, &row.typ, state, ctxt.var_level)
                        .map_err(|err| match err {
                            RemoveRowError::Missing => RowUnifErrorKind::MissingRecordRow(row.id),
                            RemoveRowError::Conflict => {
                                RowUnifErrorKind::RecordRowConflict(row.clone())
                            }
                        })?;

                    // The alternative to this if-condition is `RemoveRowResult::Extended`, which
                    // means that `t2` could be successfully extended with the row `id typ`, in
                    // which case we don't have to perform additional unification for this specific
                    // row
                    if let RemoveRowResult::Extracted(ty2) = ty2_result {
                        row.typ.unify(ty2, state, ctxt).map_err(|err| {
                            RowUnifErrorKind::RecordRowMismatch {
                                id: row.id,
                                cause: err,
                            }
                        })?;
                    }

                    tail.unify(urrows2_without_ty2, state, ctxt)
                }
            },
            (UnifRecordRows::UnifVar { id, init_level: _ }, urrows)
            | (urrows, UnifRecordRows::UnifVar { id, init_level: _ }) => {
                // see [^check-unif-var-level]
                if let UnifRecordRows::Constant(cst_id) = urrows {
                    let constant_level = state.table.get_rrows_level(cst_id);
                    state.table.force_rrows_updates(constant_level);

                    if state.table.get_rrows_level(id) < constant_level {
                        return Err(Box::new(RowUnifErrorKind::VarLevelMismatch {
                            constant_id: cst_id,
                            var_kind: VarKindDiscriminant::RecordRows,
                        }));
                    }
                }

                urrows.propagate_constrs(state.constr, id)?;
                state.table.assign_rrows(id, urrows);
                Ok(())
            }
            (UnifRecordRows::Constant(i1), UnifRecordRows::Constant(i2)) if i1 == i2 => Ok(()),
            (UnifRecordRows::Constant(i1), UnifRecordRows::Constant(i2)) => {
                Err(Box::new(RowUnifErrorKind::ConstMismatch {
                    var_kind: VarKindDiscriminant::RecordRows,
                    expected_const_id: i1,
                    inferred_const_id: i2,
                }))
            }
            (urrows, UnifRecordRows::Constant(i)) | (UnifRecordRows::Constant(i), urrows) => {
                Err(Box::new(RowUnifErrorKind::WithConst {
                    var_kind: VarKindDiscriminant::RecordRows,
                    expected_const_id: i,
                    inferred: UnifType::concrete(TypeF::Record(urrows)),
                }))
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub(super) enum RemoveRowError {
    // The row to add was missing and the row type was closed (no free unification variable in tail
    // position).
    Missing,
    // The row to add was missing and the row type couldn't be extended because of row constraints.
    Conflict,
}

#[derive(Clone, Debug)]
pub enum RemoveRowResult<RowContent: Clone> {
    Extracted(RowContent),
    Extended,
}

pub(super) trait RemoveRow<'ast>: Sized {
    /// The row data minus the identifier.
    type RowContent: Clone;

    /// Fetch a specific `row_id` from a row type, and return the content of the row together with
    /// the original row type without the found row.
    ///
    /// If the searched row isn't found:
    ///
    /// - If the row type is extensible, i.e. it ends with a free unification variable in tail
    ///   position, this function adds the missing row (with `row.types` as a type for record rows,
    ///   if allowed by row constraints) and then acts as if `remove_row` was called again on
    ///   this extended row type. That is, `remove_row` returns the new row and the extended type
    ///   without the added row).
    /// - Otherwise, raise a missing row error.
    ///
    /// # Motivation
    ///
    /// This method is used as part of row unification: let's say we want to unify `{ r1, ..tail1
    /// }` with `{ ..tail2 }` where `r1` is a row (the head of the left hand side rows), and
    /// `tail1` and `tail2` are sequences of rows.
    ///
    /// For those to unify, we must have either:
    ///
    /// - `r1` is somewhere in `tail2`, and `tail1` unifies with `{..tail2'}` where `tail2'` is
    ///   `tail2` without `r1`.
    /// - `tail2` is extensible, in which case we can extend `tail2` with `r1`, assuming that
    ///   `tail1` unifies with `{..tail2'}`, where `tail2'` is `tail2` after extending with `r1`
    ///   and then removing it. Modulo fresh unification variable shuffling, `tail2'` is in fact
    ///   isomorphic to `tail2` before it was extended.
    ///
    /// When we unify two row types, we destructure the left hand side to extract the head `r1` and
    /// the tail `tail1`. Then, we try to find and extract `r1` from `tail2`. If `r1` was found, we
    /// additionally unify the extracted type found in `tail2` (returned as part of
    /// [RemoveRowResult::Extracted]) with `r1.typ` to make sure they agree. In case of extension,
    /// we were free to chose the type of the new added row, which we set to be `r1.typ` (the
    /// `row_content` parameter of `remove_row`), and there's no additional check to perform (and
    /// indeed [RemoveRowResult::Extended] doesn't carry any information).
    ///
    /// Finally, since `remove_row` returns the initial row type minus the extracted row, we can go
    /// on recursively and unify `tail1` with this rest.
    ///
    /// # Parameters
    ///
    /// - `row_id`: the identifier of the row to extract
    /// - `row_content`: as explained above, `remove_row` is used in the context of unifying two row
    ///   types. If `self` doesn't contain `row_id` but is extensible, we must add a corresponding
    ///   new row: we fill it with `row_content`. In the context of unification, the is the content of
    ///   the row coming from the other row type.
    /// - `state`: the unification state
    /// - `var_level`: the ambient variable level
    fn remove_row(
        self,
        row_id: &LocIdent,
        row_content: &Self::RowContent,
        state: &mut State<'ast, '_>,
        var_level: VarLevel,
    ) -> Result<(RemoveRowResult<Self::RowContent>, Self), RemoveRowError>;
}

impl<'ast> RemoveRow<'ast> for UnifRecordRows<'ast> {
    type RowContent = UnifType<'ast>;

    fn remove_row(
        self,
        target: &LocIdent,
        target_content: &Self::RowContent,
        state: &mut State<'ast, '_>,
        var_level: VarLevel,
    ) -> Result<(RemoveRowResult<Self::RowContent>, UnifRecordRows<'ast>), RemoveRowError> {
        let rrows = self.into_root(state.table);

        match rrows {
            UnifRecordRows::Concrete { rrows, .. } => match rrows {
                RecordRowsF::Empty | RecordRowsF::TailDyn | RecordRowsF::TailVar(_) => {
                    Err(RemoveRowError::Missing)
                }
                RecordRowsF::Extend {
                    row: next_row,
                    tail,
                } => {
                    if target.ident() == next_row.id.ident() {
                        Ok((RemoveRowResult::Extracted(*next_row.typ), *tail))
                    } else {
                        let (extracted_row, rest) =
                            tail.remove_row(target, target_content, state, var_level)?;
                        Ok((
                            extracted_row,
                            UnifRecordRows::concrete(RecordRowsF::Extend {
                                row: next_row,
                                tail: Box::new(rest),
                            }),
                        ))
                    }
                }
            },
            UnifRecordRows::UnifVar { id: var_id, .. } => {
                let tail_var_id = state.table.fresh_rrows_var_id(var_level);
                // We have to manually insert the constraint that `tail_var_id` can't contain a row
                // `target`, to avoid producing ill-formed record rows later
                state
                    .constr
                    .insert(tail_var_id, HashSet::from([target.ident()]));

                let row_to_insert = UnifRecordRow {
                    id: *target,
                    typ: Box::new(target_content.clone()),
                };

                let tail_var = UnifRecordRows::UnifVar {
                    id: tail_var_id,
                    init_level: var_level,
                };

                let tail_extended = UnifRecordRows::concrete(RecordRowsF::Extend {
                    row: row_to_insert,
                    tail: Box::new(tail_var.clone()),
                });

                tail_extended
                    .propagate_constrs(state.constr, var_id)
                    .map_err(|_| RemoveRowError::Conflict)?;
                state.table.assign_rrows(var_id, tail_extended);

                Ok((RemoveRowResult::Extended, tail_var))
            }
            UnifRecordRows::Constant(_) => Err(RemoveRowError::Missing),
        }
    }
}

impl<'ast> RemoveRow<'ast> for UnifEnumRows<'ast> {
    type RowContent = Option<UnifType<'ast>>;

    fn remove_row(
        self,
        target: &LocIdent,
        target_content: &Self::RowContent,
        state: &mut State<'ast, '_>,
        var_level: VarLevel,
    ) -> Result<(RemoveRowResult<Self::RowContent>, UnifEnumRows<'ast>), RemoveRowError> {
        let uerows = self.into_root(state.table);

        match uerows {
            UnifEnumRows::Concrete { erows, .. } => match erows {
                EnumRowsF::Empty | EnumRowsF::TailVar(_) => Err(RemoveRowError::Missing),
                EnumRowsF::Extend {
                    row: next_row,
                    tail,
                } => {
                    // Enum variants and enum tags don't conflict, and can thus coexist in the same
                    // row type (for example, [| 'Foo Number, 'Foo |]). In some sense, they live
                    // inside different dimensions. Thus, when matching rows, we don't only compare
                    // the tag but also the nature of the enum row (tag vs variant)
                    if target.ident() == next_row.id.ident()
                        && target_content.is_some() == next_row.typ.is_some()
                    {
                        Ok((
                            RemoveRowResult::Extracted(next_row.typ.map(|typ| *typ)),
                            *tail,
                        ))
                    } else {
                        let (extracted_row, rest) =
                            tail.remove_row(target, target_content, state, var_level)?;
                        Ok((
                            extracted_row,
                            UnifEnumRows::concrete(EnumRowsF::Extend {
                                row: next_row,
                                tail: Box::new(rest),
                            }),
                        ))
                    }
                }
            },
            UnifEnumRows::UnifVar { id: var_id, .. } => {
                let tail_var_id = state.table.fresh_erows_var_id(var_level);

                // Enum tag are ignored for row conflict. See [RowConstrs]
                if target_content.is_some() {
                    state
                        .constr
                        .insert(tail_var_id, HashSet::from([target.ident()]));
                }

                let row_to_insert = UnifEnumRow {
                    id: *target,
                    typ: target_content.clone().map(Box::new),
                };

                let tail_var = UnifEnumRows::UnifVar {
                    id: tail_var_id,
                    init_level: var_level,
                };

                let tail_extended = UnifEnumRows::concrete(EnumRowsF::Extend {
                    row: row_to_insert,
                    tail: Box::new(tail_var.clone()),
                });

                tail_extended
                    .propagate_constrs(state.constr, var_id)
                    .map_err(|_| RemoveRowError::Conflict)?;
                state.table.assign_erows(var_id, tail_extended);

                Ok((RemoveRowResult::Extended, tail_var))
            }
            UnifEnumRows::Constant(_) => Err(RemoveRowError::Missing),
        }
    }
}//! Various caches for artifacts generated across the whole pipeline: source code, parsed
//! representations, imports data (dependencies and reverse dependencies, etc.)
//!
//! In order to manage the complexity of correctly borrowing such structures, where the arena
//! allocation of ASTs requires usage of self-borrowing structures, the main cache is split in
//! different subcaches that can be borrowed independently.
pub use ast_cache::AstCache;

pub use nickel_lang_parser::ast::InputFormat;

use crate::{
    ast::{
        self, Ast, AstAlloc, TryConvert,
        compat::{ToAst, ToMainline},
    },
    closurize::Closurize as _,
    error::{Error, ImportError, ImportErrorKind, ParseError, ParseErrors, TypecheckError},
    eval::{self, cache::Cache as EvalCache, value::NickelValue},
    files::{FileId, Files},
    identifier::LocIdent,
    metrics::measure_runtime,
    package::PackageMap,
    parser::{self, ErrorTolerantParser, ExtendedTerm, lexer::Lexer},
    position::{PosIdx, PosTable, TermPos},
    program::FieldPath,
    serialize::yaml::Listify,
    stdlib::{self as nickel_stdlib, StdlibModule},
    term::{self},
    transform::{self, Wildcards, import_resolution},
    traverse::TraverseOrder,
    typ::UnboundTypeVariableError,
    typecheck::{self, HasApparentType, TypecheckMode, typecheck},
};

#[cfg(feature = "nix-experimental")]
use crate::nix_ffi;

use std::{
    collections::{HashMap, HashSet, hash_map},
    ffi::{OsStr, OsString},
    fmt, fs,
    io::{self, Read},
    path::{Path, PathBuf},
    result::Result,
    sync::Arc,
    time::SystemTime,
};

use ouroboros::self_referencing;

/// Error when trying to add bindings to the typing context where the given term isn't a record
/// literal.
pub struct NotARecord;

/// The term cache stores the parsed values (the runtime representation) of sources.
#[derive(Debug, Clone)]
pub struct TermCache {
    /// The term table stores parsed terms corresponding to the entries of the file database.
    terms: HashMap<FileId, TermEntry>,
}

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub struct TermNotFound;

impl TermCache {
    pub fn new() -> Self {
        TermCache {
            terms: HashMap::new(),
        }
    }

    /// Updates the state of an entry and returns the previous state, or an error if the entry
    /// isn't in the cache.
    pub fn update_state(
        &mut self,
        file_id: FileId,
        new: TermEntryState,
    ) -> Result<TermEntryState, TermNotFound> {
        self.terms
            .get_mut(&file_id)
            .map(|TermEntry { state, .. }| std::mem::replace(state, new))
            .ok_or(TermNotFound)
    }

    /// Applies program transformations excepted import resolution, implemented in a separate phase.
    fn transform(
        &mut self,
        pos_table: &mut PosTable,
        wildcards: &WildcardsCache,
        import_data: &ImportData,
        file_id: FileId,
    ) -> Result<CacheOp<()>, TermCacheError<UnboundTypeVariableError>> {
        match self.terms.get(&file_id).map(|entry| entry.state) {
            Some(state) if state >= TermEntryState::Transformed => Ok(CacheOp::Cached(())),
            Some(state) => {
                if state < TermEntryState::Transforming {
                    let cached_term = self.terms.remove(&file_id).unwrap();
                    let term = transform::transform(
                        pos_table,
                        cached_term.value,
                        wildcards.wildcards.get(&file_id),
                    )?;
                    self.insert(
                        file_id,
                        TermEntry {
                            value: term,
                            state: TermEntryState::Transforming,
                            ..cached_term
                        },
                    );

                    let imported: Vec<_> = import_data.imports(file_id).collect();
                    for file_id in imported {
                        self.transform(pos_table, wildcards, import_data, file_id)?;
                    }

                    // unwrap(): we re-inserted the entry after removal and transformation, so it
                    // should be in the cache.
                    let _ = self
                        .update_state(file_id, TermEntryState::Transformed)
                        .unwrap();
                }

                Ok(CacheOp::Done(()))
            }
            None => Err(CacheError::IncompatibleState {
                want: TermEntryState::Populated,
            }),
        }
    }

    /// Retrieves the state of an entry. Returns `None` if the entry is not in the term cache. This
    /// might happen if the file hasn't been parsed, or if the term cache hasn't be filled from the
    /// AST cache yet. The latter is supposed to happen right before program transformations.
    pub fn entry_state(&self, file_id: FileId) -> Option<TermEntryState> {
        self.terms
            .get(&file_id)
            .map(|TermEntry { state, .. }| *state)
    }

    /// Replaces a cache entry by a closurized version of itself. If it contains imports,
    /// closurize them recursively.
    ///
    /// Closurization is not required before evaluation, but it has two benefits:
    ///
    /// - the closurized term uses the evaluation cache, so if it is imported in multiple
    ///   places then they will share a cache
    /// - the eval cache's built-in mechanism for preventing infinite recursion will also
    ///   apply to recursive imports.
    ///
    /// The main disadvantage of closurization is that it makes the resulting runtime
    /// representation less useful. You wouldn't want to closurize before pretty-printing, for
    /// example. This isn't as important these days, since we also have the AST representation at
    /// hand.
    pub fn closurize<C: EvalCache>(
        &mut self,
        cache: &mut C,
        import_data: &ImportData,
        file_id: FileId,
    ) -> Result<CacheOp<()>, TermCacheError<()>> {
        match self.entry_state(file_id) {
            Some(state) if state >= TermEntryState::Closurized => Ok(CacheOp::Cached(())),
            Some(_) => {
                let cached_term = self.terms.remove(&file_id).unwrap();
                let term = cached_term.value.closurize(cache, eval::Environment::new());
                self.insert(
                    file_id,
                    TermEntry {
                        value: term,
                        state: TermEntryState::Closurized,
                        ..cached_term
                    },
                );

                let imported: Vec<_> = import_data.imports(file_id).collect();
                for file_id in imported {
                    self.closurize(cache, import_data, file_id)?;
                }

                Ok(CacheOp::Done(()))
            }
            None => Err(CacheError::IncompatibleState {
                want: TermEntryState::Populated,
            }),
        }
    }

    /// Returns an immutable reference to the whole term cache.
    pub fn terms(&self) -> &HashMap<FileId, TermEntry> {
        &self.terms
    }

    /// Retrieves a fresh clone of a cached term.
    pub fn get_owned(&self, file_id: FileId) -> Option<NickelValue> {
        self.terms
            .get(&file_id)
            .map(|TermEntry { value: term, .. }| term.clone())
    }

    /// Retrieves a reference to a cached term.
    pub fn get(&self, file_id: FileId) -> Option<&NickelValue> {
        self.terms
            .get(&file_id)
            .map(|TermEntry { value: term, .. }| term)
    }

    /// Retrieves the whole entry for a given file id.
    pub fn get_entry(&self, file_id: FileId) -> Option<&TermEntry> {
        self.terms.get(&file_id)
    }

    /// Returns `true` if the term cache contains a term for the given file id.
    pub fn contains(&self, file_id: FileId) -> bool {
        self.terms.contains_key(&file_id)
    }

    /// Inserts a new entry in the cache. Usually, this should be handled by [CacheHub] directly,
    /// but there are some use-cases where it is useful to pre-fill the term cache (typically in
    /// NLS).
    pub fn insert(&mut self, file_id: FileId, entry: TermEntry) {
        self.terms.insert(file_id, entry);
    }
}

/// This is a temporary fix for [#2362](https://github.com/tweag/nickel/issues/2362). File paths
/// prefixed with this are treated specially: they can refer to in-memory source. To build an
/// import expression that refers to an in-memory source, append the source name to this prefix and
/// use it as the path: `format!({IN_MEMORY_SOURCE_PATH_PREFIX}{src_name})`.
pub const IN_MEMORY_SOURCE_PATH_PREFIX: &str = "%inmem_src%:";

/// The source cache handles reading textual data from the file system or other sources and storing
/// it in a [Files] instance.
///
/// While not ideal, we have to make most of the fields public to allow the LSP to perform its own
/// import resolution.
#[derive(Clone)]
pub struct SourceCache {
    /// The content of the program sources plus imports.
    pub files: Files,
    /// Reverse map from file ids to source paths.
    pub file_paths: HashMap<FileId, SourcePath>,
    /// The name-id table, holding file ids stored in the database indexed by source names.
    pub file_ids: HashMap<SourcePath, NameIdEntry>,
    /// Paths where to look for imports, as included by the user through either the CLI argument
    /// `--import-path` or the environment variable `$NICKEL_IMPORT_PATH`.
    pub import_paths: Vec<PathBuf>,
    /// A table mapping FileIds to the package that they belong to.
    ///
    /// Path dependencies have already been canonicalized to absolute paths.
    pub packages: HashMap<FileId, PathBuf>,
    /// The map used to resolve package imports.
    pub package_map: Option<PackageMap>,
}

impl SourceCache {
    pub fn new() -> Self {
        let files =
            Files::new(crate::stdlib::modules().map(|m| (m.file_name().to_owned(), m.content())));
        SourceCache {
            files,
            file_paths: HashMap::new(),
            file_ids: HashMap::new(),
            import_paths: Vec::new(),
            packages: HashMap::new(),
            package_map: None,
        }
    }

    /// Retrieves the name of a source given an id.
    pub fn name(&self, file_id: FileId) -> &OsStr {
        self.files.name(file_id)
    }

    /// Add paths to the import path list, where the resolver is looking for imported files.
    pub fn add_import_paths<P>(&mut self, paths: impl Iterator<Item = P>)
    where
        PathBuf: From<P>,
    {
        self.import_paths.extend(paths.map(PathBuf::from));
    }

    /// Sets the package map to use for package import resolution.
    pub fn set_package_map(&mut self, map: PackageMap) {
        self.package_map = Some(map);
    }

    /// Same as [Self::add_file], but assumes that the path is already normalized and takes the
    /// timestamp as a parameter.
    fn add_normalized_file(
        &mut self,
        path: PathBuf,
        format: InputFormat,
        timestamp: SystemTime,
    ) -> io::Result<FileId> {
        let contents = std::fs::read_to_string(&path)?;
        let file_id = self.files.add(&path, contents);

        self.file_paths
            .insert(file_id, SourcePath::Path(path.clone(), format));
        self.file_ids.insert(
            SourcePath::Path(path, format),
            NameIdEntry {
                id: file_id,
                source: SourceKind::Filesystem(timestamp),
            },
        );
        Ok(file_id)
    }

    /// Loads a file and adds it to the name-id table.
    ///
    /// Uses the normalized path and the *modified at* timestamp as the name-id table entry.
    /// Overrides any existing entry with the same name.
    pub fn add_file(
        &mut self,
        path: impl Into<OsString>,
        format: InputFormat,
    ) -> io::Result<FileId> {
        let path = path.into();
        let timestamp = timestamp(&path)?;
        let normalized = normalize_path(&path)?;
        self.add_normalized_file(normalized, format, timestamp)
    }

    /// Try to retrieve the id of a file from the cache.
    ///
    /// If it was not in cache, try to read it and add it as a new entry.
    ///
    /// # In memory sources
    ///
    /// As a temporary fix for [#2362](https://github.com/tweag/nickel/issues/2362), if a file path
    /// starts with [IN_MEMORY_SOURCE_PATH_PREFIX], the suffix is looked up un-normalized value
    /// first, which makes it possible to hit in-memory only sources by importing a path
    /// `"{SOURCE_PATH_PREFX}{src_name}"`. If it can't be found, it is looked up normally, so that
    /// it doesn't break strange file names that happen to contain the source path prefix.
    ///
    /// It is theoretically possible that if both the source "abc" and the file
    /// "{IN_MEMORY_SOURCE_PATH_PREFIX}abc" exist, the source is imported instead of the intended
    /// file. However, given the prefix, it just can't be accidental. As we want to give access to
    /// in-memory sources in any case, although this can be surprising, I don't see any obvious
    /// attack scenario here. This fix is also intended to be temporary. If you still need to make
    /// sure this doesn't happen, one way would be to add some randomness to the name of the
    /// sources, so that they can't be predicted beforehand.
    pub fn get_or_add_file(
        &mut self,
        path: impl Into<OsString>,
        format: InputFormat,
    ) -> io::Result<CacheOp<FileId>> {
        let path = path.into();
        let normalized = normalize_path(&path)?;

        // Try to fetch a generated source if the path starts with a hardcoded prefix
        let generated_entry = path
            .to_str()
            .and_then(|p| p.strip_prefix(IN_MEMORY_SOURCE_PATH_PREFIX))
            .and_then(|src_name| {
                self.file_ids
                    .get(&SourcePath::Path(src_name.into(), format))
            });

        if let Some(entry) = generated_entry {
            return Ok(CacheOp::Cached(entry.id));
        }

        match self.id_or_new_timestamp_of(normalized.as_ref(), format)? {
            SourceState::UpToDate(id) => Ok(CacheOp::Cached(id)),
            SourceState::Stale(timestamp) => self
                .add_normalized_file(normalized, format, timestamp)
                .map(CacheOp::Done),
        }
    }

    /// Load a source and add it to the name-id table.
    ///
    /// Do not check if a source with the same name already exists: if it is the case,
    /// [Self::add_source] will happily will override the old entry in the name-id table.
    pub fn add_source<T>(&mut self, source_name: SourcePath, mut source: T) -> io::Result<FileId>
    where
        T: Read,
    {
        let mut buffer = String::new();
        source.read_to_string(&mut buffer)?;
        Ok(self.add_string(source_name, buffer))
    }

    /// Returns the content of a file.
    ///
    /// Panics if the file id is invalid.
    pub fn source(&self, id: FileId) -> &str {
        self.files.source(id)
    }

    /// Returns a cloned `Arc` to the content of the file.
    ///
    /// The `Arc` is here for the LSP, where the background evaluation is handled by background
    /// threads and processes.
    ///
    /// Panics if the file id is invalid.
    pub fn clone_source(&self, id: FileId) -> Arc<str> {
        self.files.clone_source(id)
    }

    /// Loads a new source as a string and add it to the name-id table.
    ///
    /// Do not check if a source with the same name already exists: if it is the case, this one
    /// will override the old entry in the name-id table but the old `FileId` will remain valid.
    pub fn add_string(&mut self, source_name: SourcePath, s: String) -> FileId {
        let id = self.files.add(source_name.clone(), s);

        self.file_paths.insert(id, source_name.clone());
        self.file_ids.insert(
            source_name,
            NameIdEntry {
                id,
                source: SourceKind::Memory,
            },
        );
        id
    }

    /// Loads a new source as a string, replacing any existing source with the same name.
    ///
    /// As opposed to [CacheHub::replace_string], this method doesn't update the other caches. It
    /// just affects the source cache.
    pub fn replace_string(&mut self, source_name: SourcePath, s: String) -> FileId {
        if let Some(file_id) = self.id_of(&source_name) {
            // The file may have been originally loaded from the filesystem and then
            // updated by the LSP, so the SourceKind needs to be updated to Memory.
            self.file_ids.insert(
                source_name,
                NameIdEntry {
                    id: file_id,
                    source: SourceKind::Memory,
                },
            );
            self.files.update(file_id, s);
            file_id
        } else {
            // We re-use [Self::add_string] here to properly fill the file_paths and file_ids
            // tables.
            self.add_string(source_name, s)
        }
    }

    /// Closes a file that has been opened in memory and reloads it from the filesystem.
    /// Returns the file ID of the replacement file loaded from the filesystem.
    pub fn close_in_memory_file(
        &mut self,
        path: PathBuf,
        format: InputFormat,
    ) -> Result<FileCloseResult, FileCloseError> {
        let entry = self
            .file_ids
            .get_mut(&SourcePath::Path(path.clone(), format))
            .ok_or(FileCloseError::FileIdNotFound)?;
        match &entry.source {
            SourceKind::Memory => {
                let closed_id = entry.id;
                entry.source = SourceKind::MemoryClosed;
                let replacement_id = self.get_or_add_file(path, format).map(|op| op.inner());
                Ok(FileCloseResult {
                    closed_id,
                    replacement_id,
                })
            }
            _ => Err(FileCloseError::FileNotOpen),
        }
    }

    /// Retrieves the id of a source given a name.
    ///
    /// Note that files added via [Self::add_file] are indexed by their full normalized path (cf
    /// [normalize_path]).
    pub fn id_of(&self, name: &SourcePath) -> Option<FileId> {
        match name {
            SourcePath::Path(p, fmt) => match self.id_or_new_timestamp_of(p, *fmt).ok()? {
                SourceState::UpToDate(id) => Some(id),
                SourceState::Stale(_) => None,
            },
            name => Some(self.file_ids.get(name)?.id),
        }
    }

    /// Tries to retrieve the id of a cached source.
    ///
    /// Only returns `Ok` if the source is up-to-date; if the source is stale, returns
    /// either the new timestamp of the up-to-date file or the error we encountered when
    /// trying to read it (which most likely means there was no such file).
    ///
    /// The main point of this awkward signature is to minimize I/O operations: if we accessed
    /// the timestamp, keep it around.
    fn id_or_new_timestamp_of(&self, name: &Path, format: InputFormat) -> io::Result<SourceState> {
        match self
            .file_ids
            .get(&SourcePath::Path(name.to_owned(), format))
        {
            None
            | Some(NameIdEntry {
                source: SourceKind::MemoryClosed,
                ..
            }) => Ok(SourceState::Stale(timestamp(name)?)),
            Some(NameIdEntry {
                id,
                source: SourceKind::Filesystem(ts),
            }) => {
                let new_timestamp = timestamp(name)?;
                if ts == &new_timestamp {
                    Ok(SourceState::UpToDate(*id))
                } else {
                    Ok(SourceState::Stale(new_timestamp))
                }
            }
            Some(NameIdEntry {
                id,
                source: SourceKind::Memory,
            }) => Ok(SourceState::UpToDate(*id)),
        }
    }

    /// Gets a reference to the underlying files. Required by the WASM REPL error reporting code
    /// and LSP functions.
    pub fn files(&self) -> &Files {
        &self.files
    }

    /// Parses a Nickel source without querying nor populating other caches.
    pub fn parse_nickel<'ast>(
        &self,
        // We take the allocator explicitly, to make sure `self.asts` is properly initialized
        // before calling this function, and won't be dropped.
        alloc: &'ast AstAlloc,
        file_id: FileId,
    ) -> Result<Ast<'ast>, ParseErrors> {
        parse_nickel(alloc, file_id, self.files.source(file_id))
    }

    /// Parses a source that isn't Nickel code without querying nor populating the other caches. Support
    /// multiple formats.
    ///
    /// The Nickel/non Nickel distinction is a bit artificial at the moment, due to the fact that
    /// parsing Nickel returns the new [crate::ast::Ast], while parsing other formats
    /// don't go through the new AST first but directly deserialize to the legacy
    /// [crate::term::Term] for simplicity and performance reasons.
    ///
    /// Once RFC007 is fully implemented, we might clean it up.
    ///
    /// # Panic
    ///
    /// This function panics if `format` is [InputFormat::Nickel].
    pub fn parse_other(
        &self,
        pos_table: &mut PosTable,
        file_id: FileId,
        format: InputFormat,
    ) -> Result<NickelValue, ParseError> {
        let whole_span: TermPos = self.files.source_span(file_id).into();
        let pos_idx = pos_table.push(whole_span);

        let source = self.files.source(file_id);

        match format {
            InputFormat::Nickel => {
                // Panicking isn't great, but we expect this to be temporary, until RFC007 is fully
                // implemented. And this case is an internal bug.
                panic!("error: trying to parse a Nickel source with parse_other_nocache")
            }
            InputFormat::Json => {
                crate::serialize::yaml::load_json_value(pos_table, source, Some(file_id))
            }
            InputFormat::Yaml => crate::serialize::yaml::load_yaml_value(
                pos_table,
                source,
                Some(file_id),
                Listify::Auto,
            ),
            InputFormat::Toml => crate::serialize::toml_deser::from_str(pos_table, source, file_id)
                .map(|v: NickelValue| v.with_pos_idx(pos_idx))
                .map_err(|err| ParseError::from_toml(err, file_id)),
            #[cfg(feature = "nix-experimental")]
            InputFormat::Nix => {
                let json = nix_ffi::eval_to_json(source, &self.get_base_dir_for_nix(file_id))
                    .map_err(|e| ParseError::from_nix(e.what(), file_id))?;
                serde_json::from_str(&json)
                    .map(|v: NickelValue| v.with_pos_idx(pos_idx))
                    .map_err(|err| ParseError::from_serde_json(err, Some((file_id, &self.files))))
            }
            InputFormat::Text => Ok(NickelValue::string(source, pos_idx)),
        }
    }

    /// Returns true if a particular file id represents a Nickel standard library file, false
    /// otherwise.
    pub fn is_stdlib_module(&self, file: FileId) -> bool {
        self.files.is_stdlib(file)
    }

    /// Retrieves the file id for a given standard library module.
    pub fn get_submodule_file_id(&self, module: StdlibModule) -> Option<FileId> {
        self.stdlib_modules()
            .find(|(m, _id)| m == &module)
            .map(|(_, id)| id)
    }

    /// Returns the list of file ids corresponding to the standard library modules.
    pub fn stdlib_modules(&self) -> impl Iterator<Item = (StdlibModule, FileId)> + use<> {
        let ids = self.files.stdlib_modules();
        crate::stdlib::modules().into_iter().zip(ids)
    }

    /// Return the format of a given source. Returns `None` if there is no entry in the source
    /// cache for `file_id`, or if there is no well-defined input format (e.g. for REPL inputs,
    /// field assignments, etc.).
    pub fn input_format(&self, file_id: FileId) -> Option<InputFormat> {
        self.file_paths
            .get(&file_id)
            .and_then(|source| match source {
                SourcePath::Path(_, input_format) => Some(*input_format),
                SourcePath::Std(_) => Some(InputFormat::Nickel),
                SourcePath::Snippet(_)
                | SourcePath::Query
                | SourcePath::ReplInput(_)
                | SourcePath::ReplTypecheck
                | SourcePath::ReplQuery
                | SourcePath::CliFieldAssignment
                | SourcePath::Override(_)
                | SourcePath::Generated(_) => None,
            })
    }

    /// Returns the base path for Nix evaluation, which is the parent directory of the source file
    /// if any, or the current working directory, or an empty path if we couldn't find any better.
    #[cfg(feature = "nix-experimental")]
    fn get_base_dir_for_nix(&self, file_id: FileId) -> PathBuf {
        let parent_dir = self
            .file_paths
            .get(&file_id)
            .and_then(|source_path| Path::new(<&OsStr>::try_from(source_path).ok()?).parent());

        parent_dir
            .map(PathBuf::from)
            .or_else(|| std::env::current_dir().ok())
            .unwrap_or_default()
    }
}

/// Stores the mapping of each wildcard id to its inferred type, for each file in the cache.
#[derive(Default, Clone, Debug)]
pub struct WildcardsCache {
    wildcards: HashMap<FileId, Wildcards>,
}

impl WildcardsCache {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn get(&self, file_id: FileId) -> Option<&Wildcards> {
        self.wildcards.get(&file_id)
    }
}

/// Metadata about an imported file.
#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
pub struct ImportTarget {
    pub file_id: FileId,
    pub format: InputFormat,
}

/// Stores dependencies and reverse dependencies data between sources.
#[derive(Default, Clone)]
pub struct ImportData {
    /// A map containing for each FileId a list of files they import (directly).
    pub imports: HashMap<FileId, HashSet<ImportTarget>>,
    /// A map containing for each FileId a list of files importing them (directly). Note that we
    /// don't need to store the format here, as only Nickel files can import other files. We do
    /// however store the position of the first import expression (the same file can be imported
    /// many times from a given file), for error reporting purpose.
    pub rev_imports: HashMap<FileId, HashMap<FileId, TermPos>>,
}

impl ImportData {
    pub fn new() -> Self {
        Self::default()
    }

    /// Returns the set of files that this file imports.
    pub fn imports(&self, file: FileId) -> impl Iterator<Item = FileId> + '_ {
        self.imports
            .get(&file)
            .into_iter()
            .flat_map(|s| s.iter())
            .map(|tgt| tgt.file_id)
    }

    /// Returns the set of files that import this file.
    pub fn rev_imports(&self, file: FileId) -> impl Iterator<Item = FileId> + '_ {
        self.rev_imports
            .get(&file)
            .into_iter()
            .flat_map(|h| h.keys())
            .copied()
    }

    /// Returns the set of files that transitively depend on this file.
    pub fn transitive_rev_imports(&self, file: FileId) -> HashSet<FileId> {
        let mut ret = HashSet::new();
        let mut stack = vec![file];

        while let Some(file) = stack.pop() {
            for f in self.rev_imports(file) {
                if ret.insert(f) {
                    stack.push(f);
                }
            }
        }

        ret
    }

    /// Returns the set of files that this file transitively depends on.
    pub fn transitive_imports(&self, file: FileId) -> HashSet<FileId> {
        let mut ret = HashSet::new();
        let mut stack = vec![file];

        while let Some(file) = stack.pop() {
            for f in self.imports(file) {
                if ret.insert(f) {
                    stack.push(f);
                }
            }
        }

        ret
    }

    /// Returns `true` if those import data are empty.
    pub fn is_empty(&self) -> bool {
        self.imports.is_empty() && self.rev_imports.is_empty()
    }
}

/// The cache hub aggregates the various kind of source-related caches used by Nickel.
///
/// [CacheHub] handles parsing, typechecking and program transformation of sources, as well as
/// caching the corresponding artifacts (text, ASTs, state). This is the central entry point for
/// other modules.
///
/// # RFC007
///
/// As part of the migration to a new AST required by RFC007, as long as we don't have a fully
/// working bytecode virtual machine, the cache needs to keep parsed expressions both as the old
/// representation (dubbed "mainline" or the runtime representation in many places) and as the new
/// AST representation.
pub struct CacheHub {
    pub terms: TermCache,
    pub sources: SourceCache,
    pub asts: AstCache,
    pub wildcards: WildcardsCache,
    pub import_data: ImportData,
    #[cfg(debug_assertions)]
    /// Skip loading the stdlib, used for debugging purpose
    pub skip_stdlib: bool,
}

impl CacheHub {
    pub fn new() -> Self {
        CacheHub {
            terms: TermCache::new(),
            sources: SourceCache::new(),
            asts: AstCache::empty(),
            wildcards: WildcardsCache::new(),
            import_data: ImportData::new(),
            #[cfg(debug_assertions)]
            skip_stdlib: false,
        }
    }

    /// Actual implementation of [Self::parse_ast] which doesn't take `self` as a parameter, so that it
    /// can be reused from other places when we don't have a full [CacheHub] instance at hand.
    fn parse_ast_impl(
        asts: &mut AstCache,
        sources: &mut SourceCache,
        file_id: FileId,
    ) -> Result<CacheOp<()>, ParseErrors> {
        if asts.contains(file_id) {
            Ok(CacheOp::Cached(()))
        } else {
            let _ = asts.parse_nickel(file_id, sources.files.source(file_id))?;
            Ok(CacheOp::Done(()))
        }
    }

    /// Parse a REPL input and populate the corresponding entry in the cache.
    ///
    /// The first component of the tuple in the `Ok` case is the identifier of the toplevel let, if
    /// the input is a toplevel let, or `None` if the input is a standard Nickel expression.
    ///
    /// # RFC007
    ///
    /// This method populates both the ast cache and the term cache at once.
    pub fn parse_repl(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<Option<LocIdent>>, ParseErrors> {
        // Since we need the identifier, we always reparse the input. In any case, it doesn't
        // happen that we the same REPL input twice right now, so caching it is in fact useless.
        // It's just must simpler to reuse the cache infrastructure than to reimplement the whole
        // transformations and import dependencies tracking elsewhere.
        let extd_ast = self
            .asts
            .parse_nickel_repl(file_id, self.sources.files.source(file_id))?;

        let (id, ast) = match extd_ast {
            ExtendedTerm::Term(t) => (None, t),
            ExtendedTerm::ToplevelLet(id, t) => (Some(id), t),
        };

        let term = measure_runtime!("runtime:ast_conversion", ast.to_mainline(pos_table));

        self.terms.insert(
            file_id,
            TermEntry {
                value: term,
                state: TermEntryState::default(),
                format: InputFormat::Nickel,
            },
        );

        Ok(CacheOp::Done(id))
    }

    /// Parses a source and populate the corresponding entry in the AST cache, or do nothing if the
    /// entry has already been parsed. External input formats are currently directly parsed to the
    /// runtime representation, without going through an AST: currently, the format is assumed to
    /// be [InputFormat::Nickel] in this method. See [Self::parse_to_term] for other formats.
    ///
    /// # RFC007
    ///
    /// This method only populates the AST cache. The term cache must be filled separately.
    pub fn parse_to_ast(&mut self, file_id: FileId) -> Result<CacheOp<()>, ParseErrors> {
        Self::parse_ast_impl(&mut self.asts, &mut self.sources, file_id)
    }

    /// Parses a source or compiles an AST into the term cache:
    ///
    /// - if the entry is already in the term cache, do nothing.
    /// - if the format is Nickel and there is a corresponding entry in the AST cache, converts the
    ///   parsed AST to a [NickelValue] and put it in the term cache.
    /// - if the format is Nickel but there is no cached AST, or if the format is not Nickel, parse
    ///   the input directly into the term cache.
    ///
    /// Mostly used during ([NickelValue]-based) import resolution.
    pub fn parse_to_term(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
        format: InputFormat,
    ) -> Result<CacheOp<()>, ParseErrors> {
        if self.terms.contains(file_id) {
            return Ok(CacheOp::Cached(()));
        }

        let term = if let InputFormat::Nickel = format {
            match self.compile(pos_table, file_id) {
                Ok(cache_op) => return Ok(cache_op),
                Err(_) => {
                    let alloc = AstAlloc::new();
                    self.sources
                        .parse_nickel(&alloc, file_id)?
                        .to_mainline(pos_table)
                }
            }
        } else {
            self.sources.parse_other(pos_table, file_id, format)?
        };

        self.terms.insert(
            file_id,
            TermEntry {
                value: term,
                state: TermEntryState::default(),
                format,
            },
        );

        Ok(CacheOp::Done(()))
    }

    /// Typecheck an entry of the cache and update its state accordingly, or do nothing if the
    /// entry has already been typechecked. Require that the corresponding source has been parsed.
    /// If the source contains imports, [Self::typecheck] recursively typechecks the imports as
    /// well.
    ///
    /// # RFC007
    ///
    /// During the transition period between the old VM and the new bytecode VM, this method
    /// performs typechecking on the new representation [crate::ast::Ast].
    pub fn typecheck(
        &mut self,
        file_id: FileId,
        initial_mode: TypecheckMode,
    ) -> Result<CacheOp<()>, AstCacheError<TypecheckError>> {
        let (slice, asts) = self.split_asts();
        asts.typecheck(slice, file_id, initial_mode)
    }

    /// Returns the apparent type of an entry that has been typechecked with wildcards substituted.
    pub fn type_of(
        &mut self,
        file_id: FileId,
    ) -> Result<CacheOp<ast::typ::Type<'_>>, AstCacheError<TypecheckError>> {
        let (slice, asts) = self.split_asts();
        asts.type_of(slice, file_id)
    }

    /// Prepares a source for evaluation: parse, typecheck and apply program transformations, if it
    /// was not already done.
    pub fn prepare(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<()>, Error> {
        self.prepare_impl(pos_table, file_id, true)
    }

    /// Prepare a file for evaluation only. Same as [Self::prepare], but doesn't typecheck the
    /// source.
    pub fn prepare_eval_only(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<()>, Error> {
        self.prepare_impl(pos_table, file_id, false)
    }

    /// Common implementation for [Self::prepare] and [Self::prepare_eval_only], which optionally
    /// skips typechecking. Note that this method doesn't load and prepare the stdlib.
    fn prepare_impl(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
        typecheck: bool,
    ) -> Result<CacheOp<()>, Error> {
        let mut result = CacheOp::Cached(());

        let format = self
            .sources
            .file_paths
            .get(&file_id)
            .and_then(Option::<InputFormat>::from)
            .unwrap_or_default();

        if let InputFormat::Nickel = format {
            if let CacheOp::Done(_) = self.parse_to_ast(file_id)? {
                result = CacheOp::Done(());
            }

            if typecheck {
                let (slice, asts) = self.split_asts();

                let typecheck_res = asts
                    .typecheck(slice, file_id, TypecheckMode::Walk)
                    .map_err(|cache_err| {
                        cache_err.unwrap_error(
                            "cache::prepare(): expected source to be parsed before typechecking",
                        )
                    })?;

                if typecheck_res == CacheOp::Done(()) {
                    result = CacheOp::Done(());
                };
            }
        }
        // Non-Nickel terms are currently not parsed as ASTs, but directly as the runtime
        // representation. While the imports of the main file will be parsed to terms by the
        // `compile_and_transform` automatically, we do need to ensure that the main file is in the
        // term cache if it's an external format, or `compile_and_transform` will complain.
        else if let CacheOp::Done(_) = self.parse_to_term(pos_table, file_id, format)? {
            result = CacheOp::Done(());
        }

        let transform_res =
            self.compile_and_transform(pos_table, file_id)
                .map_err(|cache_err| {
                    cache_err.unwrap_error(
                        "cache::prepare(): expected source to be parsed before transformations",
                    )
                })?;

        if transform_res == CacheOp::Done(()) {
            result = CacheOp::Done(());
        };

        Ok(result)
    }

    /// Prepare an REPL snippet for evaluation: parse, typecheck and apply program transformations,
    /// if it was not already done. The difference with [Self::prepare] is that this method also
    /// accept toplevel binding `let <id> = <value>`.
    ///
    /// Returns the identifier of the toplevel let, if the input is a toplevel let, or `None` if
    /// the input is a standard Nickel expression.
    pub fn prepare_repl(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<Option<LocIdent>>, Error> {
        let mut done = false;

        let parsed = self.parse_repl(pos_table, file_id)?;

        done = done || matches!(parsed, CacheOp::Done(_));

        let id = parsed.inner();

        let (slice, asts) = self.split_asts();
        let typecheck_res = asts
            .typecheck(slice, file_id, TypecheckMode::Walk)
            .map_err(|cache_err| {
                cache_err.unwrap_error(
                    "cache::prepare_repl(): expected source to be parsed before typechecking",
                )
            })?;

        if let Some(id) = id {
            let (slice, asts) = self.split_asts();
            asts
                .add_type_binding(
                    slice,
                    id,
                    file_id,
                ).expect("cache::prepare_repl(): expected source to be parsed before augmenting the type environment");
        }

        done = done || matches!(typecheck_res, CacheOp::Done(_));

        let transform_res =
            self.compile_and_transform(pos_table, file_id)
                .map_err(|cache_err| {
                    cache_err.unwrap_error(
                        "cache::prepare(): expected source to be parsed before transformations",
                    )
                })?;

        done = done || matches!(transform_res, CacheOp::Done(_));

        if done {
            Ok(CacheOp::Done(id))
        } else {
            Ok(CacheOp::Cached(id))
        }
    }

    /// Proxy for [TermCache::transform].
    fn transform(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<()>, TermCacheError<UnboundTypeVariableError>> {
        self.terms
            .transform(pos_table, &self.wildcards, &self.import_data, file_id)
    }

    /// Loads and parse the standard library in the AST cache.
    ///
    /// # RFC007
    ///
    /// This method doesn't populate the term cache. Use [Self::compile_stdlib] afterwards.
    pub fn load_stdlib(&mut self) -> Result<CacheOp<()>, Error> {
        let mut ret = CacheOp::Cached(());

        for (_, file_id) in self.sources.stdlib_modules() {
            if let CacheOp::Done(_) = self.parse_to_ast(file_id)? {
                ret = CacheOp::Done(());
            }
        }

        Ok(ret)
    }

    /// Converts the parsed standard library to the runtime representation.
    pub fn compile_stdlib(
        &mut self,
        pos_table: &mut PosTable,
    ) -> Result<CacheOp<()>, AstCacheError<()>> {
        let mut ret = CacheOp::Cached(());

        for (_, file_id) in self.sources.stdlib_modules() {
            let result = self.compile(pos_table, file_id).map_err(|cache_err| {
                if let CacheError::IncompatibleState { want } = cache_err {
                    CacheError::IncompatibleState { want }
                } else {
                    unreachable!("unexpected parse error during the compilation of stdlib")
                }
            })?;

            if let CacheOp::Done(_) = result {
                ret = CacheOp::Done(());
            }
        }

        Ok(ret)
    }

    /// Typechecks the standard library. Currently only used in the test suite.
    pub fn typecheck_stdlib(&mut self) -> Result<CacheOp<()>, AstCacheError<TypecheckError>> {
        let (slice, asts) = self.split_asts();
        asts.typecheck_stdlib(slice)
    }

    /// Loads, parses, compiles and applies program transformations to the standard library. We
    /// don't typecheck for performance reasons: this is done in the test suite.
    pub fn prepare_stdlib(&mut self, pos_table: &mut PosTable) -> Result<(), Error> {
        #[cfg(debug_assertions)]
        if self.skip_stdlib {
            return Ok(());
        }

        self.load_stdlib()?;
        // unwrap(): we just loaded the stdlib, so it must be parsed in the cache.
        self.compile_stdlib(pos_table).unwrap();

        self.sources
            .stdlib_modules()
            // We need to handle the internals module separately. Each field
            // is bound directly in the environment without evaluating it first, so we can't
            // tolerate top-level let bindings that would be introduced by `transform`.
            .try_for_each(|(_, file_id)| self.transform(pos_table, file_id).map(|_| ()))
            .map_err(|cache_err: TermCacheError<UnboundTypeVariableError>| {
                Error::ParseErrors(
                    cache_err
                        .unwrap_error(
                            "cache::prepare_stdlib(): unexpected unbound type variable error during stdlib loading",
                        )
                        .into(),
                )
            })?;

        Ok(())
    }

    /// Applies a custom transform to an input and its imports. [CacheError::IncompatibleState] is returned
    /// if the file has not yet been typechecked.
    ///
    /// If multiple invocations of `custom_transform` are needed, you must supply `transform_id` with
    /// with a number higher than that of all previous invocations.
    pub fn custom_transform<E>(
        &mut self,
        file_id: FileId,
        transform_id: usize,
        f: &mut impl FnMut(&mut CacheHub, NickelValue) -> Result<NickelValue, E>,
    ) -> Result<(), TermCacheError<E>> {
        match self.terms.entry_state(file_id) {
            None => Err(CacheError::IncompatibleState {
                want: TermEntryState::Populated,
            }),
            Some(state) => {
                if state.needs_custom_transform(transform_id) {
                    let cached_term = self.terms.terms.remove(&file_id).unwrap();
                    let term = f(self, cached_term.value)?;
                    self.terms.insert(
                        file_id,
                        TermEntry {
                            value: term,
                            state: TermEntryState::Transforming,
                            ..cached_term
                        },
                    );

                    let imported: Vec<_> = self.import_data.imports(file_id).collect();
                    for file_id in imported {
                        self.custom_transform(file_id, transform_id, f)?;
                    }

                    // TODO: We're setting the state back to whatever it was.
                    // unwrap(): we inserted the term just above
                    let _ = self
                        .terms
                        .update_state(file_id, TermEntryState::CustomTransformed { transform_id })
                        .unwrap();
                }

                Ok(())
            }
        }
    }

    /// Resolves every imports of a term entry of the cache, and update its state accordingly, or
    /// do nothing if the imports of the entry have already been resolved or if they aren't Nickel
    /// inputs. Require that the corresponding source has been parsed.
    ///
    /// If resolved imports contain imports themselves, resolve them recursively. Returns a tuple
    /// of vectors, where the first component is the imports that were transitively resolved, and
    /// the second component is the errors it encountered while resolving imports in `file_id`,
    /// respectively. Imports that were already resolved before are not included in the first
    /// component: this return value is currently used by the LSP to re-run code analysis on new
    /// files/modified files.
    ///
    /// The resolved imports are ordered by a pre-order depth-first-search. In particular, earlier
    /// elements in the returned list might import later elements but -- unless there are cyclic
    /// imports -- later elements do not import earlier elements.
    ///
    /// It only accumulates errors if the cache is in error tolerant mode, otherwise it returns an
    /// `Err(..)` containing  a `CacheError`.
    ///
    /// # RFC007
    ///
    /// This method is still needed only because the evaluator can't handle un-resolved import, so
    /// we need to replace them by resolved imports. However, actual import resolution (loading and
    /// parsing files for the first time) is now driven by typechecking directly.
    pub fn resolve_imports(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<Vec<FileId>>, TermCacheError<ImportError>> {
        let entry = self.terms.terms.get(&file_id);

        match entry {
            Some(TermEntry {
                state,
                value: term,
                format: InputFormat::Nickel,
            }) if *state < TermEntryState::ImportsResolving => {
                let term = term.clone();

                let import_resolution::strict::ResolveResult {
                    transformed_term,
                    resolved_ids: pending,
                } = import_resolution::strict::resolve_imports(pos_table, term, self)?;

                // unwrap(): we called `unwrap()` at the beginning of the enclosing if branch
                // on the result of `self.terms.get(&file_id)`. We only made recursive calls to
                // `resolve_imports` in between, which don't remove anything from `self.terms`.
                let cached_term = self.terms.terms.get_mut(&file_id).unwrap();
                cached_term.value = transformed_term;
                cached_term.state = TermEntryState::ImportsResolving;

                let mut done = Vec::new();

                // Transitively resolve the imports, and accumulate the ids of the resolved
                // files along the way.
                for id in pending {
                    if let CacheOp::Done(mut done_local) = self.resolve_imports(pos_table, id)? {
                        done.push(id);
                        done.append(&mut done_local)
                    }
                }

                // unwrap(): if we are in this branch, the term is present in the cache
                let _ = self
                    .terms
                    .update_state(file_id, TermEntryState::ImportsResolved)
                    .unwrap();

                Ok(CacheOp::Done(done))
            }
            // There's no import to resolve for non-Nickel inputs. We still update the state.
            Some(TermEntry { state, .. }) if *state < TermEntryState::ImportsResolving => {
                // unwrap(): if we are in this branch, the term is present in the cache
                let _ = self
                    .terms
                    .update_state(file_id, TermEntryState::ImportsResolved)
                    .unwrap();
                Ok(CacheOp::Cached(Vec::new()))
            }
            // [^transitory_entry_state]
            //
            // This case is triggered by a cyclic import. The entry is already
            // being treated by an ongoing call to `resolve_import` higher up in
            // the call chain, so we don't do anything here.
            //
            // Note that in some cases, this intermediate state can be observed by an
            // external caller: if a first call to `resolve_imports` fails in the middle of
            // resolving the transitive imports, the end state of the entry is
            // `ImportsResolving`. Subsequent calls to `resolve_imports` will succeed, but
            // won't change the state to `EntryState::ImportsResolved` (and for a good
            // reason: we wouldn't even know what are the pending imports to resolve). The
            // Nickel pipeline should however fail if `resolve_imports` failed at some
            // point, anyway.
            Some(TermEntry {
                state: TermEntryState::ImportsResolving,
                ..
            }) => Ok(CacheOp::Done(Vec::new())),
            // >= EntryState::ImportsResolved
            Some(_) => Ok(CacheOp::Cached(Vec::new())),
            None => Err(CacheError::IncompatibleState {
                want: TermEntryState::Populated,
            }),
        }
    }

    /// Generate the initial evaluation environment from the list of `file_ids` corresponding to the
    /// standard library parts.
    pub fn mk_eval_env<EC: EvalCache>(&self, eval_cache: &mut EC) -> eval::Environment {
        let mut eval_env = eval::Environment::new();

        for (module, file_id) in self.sources.stdlib_modules() {
            // The internals module needs special treatment: it's required to be a record
            // literal, and its bindings are added directly to the environment
            if let nickel_stdlib::StdlibModule::Internals = module {
                let result = eval::env_add_record(
                    eval_cache,
                    &mut eval_env,
                    self.terms
                        .get_owned(file_id)
                        .expect("cache::mk_eval_env(): can't build environment, stdlib not parsed")
                        .into(),
                );
                if let Err(eval::EnvBuildError::NotARecord(rt)) = result {
                    panic!(
                        "cache::Caches::mk_eval_env(): \
                            expected the stdlib module {} to be a record, got {:?}",
                        self.sources.name(file_id).to_string_lossy().as_ref(),
                        rt
                    )
                }
            } else {
                eval::env_add(
                    eval_cache,
                    &mut eval_env,
                    module.name().into(),
                    self.terms.get_owned(file_id).expect(
                        "cache::Caches::mk_eval_env(): can't build environment, stdlib not parsed",
                    ),
                    eval::Environment::new(),
                );
            }
        }

        eval_env
    }

    /// Loads a new source as a string, replacing any existing source with the same name.
    ///
    /// If there was a previous source with the same name, its `FileId` is reused and the cached
    /// term is deleted.
    ///
    /// Used to store intermediate short-lived generated snippets that needs to have a
    /// corresponding `FileId`, such as when querying or reporting errors.
    pub fn replace_string(&mut self, source_name: SourcePath, s: String) -> FileId {
        if let Some(file_id) = self.sources.id_of(&source_name) {
            self.sources.files.update(file_id, s);
            self.asts.remove(file_id);
            self.terms.terms.remove(&file_id);
            file_id
        } else {
            let file_id = self.sources.files.add(source_name.clone(), s);
            self.sources.file_paths.insert(file_id, source_name.clone());
            self.sources.file_ids.insert(
                source_name,
                NameIdEntry {
                    id: file_id,
                    source: SourceKind::Memory,
                },
            );
            file_id
        }
    }

    pub fn closurize<EC: EvalCache>(
        &mut self,
        eval_cache: &mut EC,
        file_id: FileId,
    ) -> Result<CacheOp<()>, TermCacheError<()>> {
        self.terms.closurize(eval_cache, &self.import_data, file_id)
    }

    /// Add the bindings of a record to the REPL type environment. Ignore fields whose name are
    /// defined through interpolation.
    pub fn add_repl_bindings(
        &mut self,
        pos_table: &PosTable,
        term: &NickelValue,
    ) -> Result<(), NotARecord> {
        let (slice, asts) = self.split_asts();
        asts.add_type_bindings(pos_table, slice, term)
    }

    /// Registers each given identifier in the typing environment as `Dyn`. Used to expose
    /// host-provided top-level names to the typechecker. See
    /// [AstCache::add_dyn_type_bindings] for details.
    pub fn add_dyn_type_bindings<I>(&mut self, idents: I)
    where
        I: IntoIterator<Item = crate::identifier::Ident>,
    {
        self.asts.add_dyn_type_bindings(&self.sources, idents);
    }

    /// Converts an AST and all of its transitive dependencies to the runtime representation,
    /// populating the term cache. `file_id` and any of its Nickel dependencies must be present in
    /// the AST cache, or [CacheError::IncompatibleState] is returned. However, for non-Nickel
    /// dependencies, they are instead parsed directly into the term cache,
    ///
    /// For entries that have been typechecked, the wildcard cache will be populate as well
    /// (converting from `ast::typ::Type` to the runtime representation).
    ///
    /// "Compile" is anticipating a bit on RFC007, although it is a lowering of the AST
    /// representation to the runtime representation.
    ///
    /// Compilation doesn't have a proper state associated, and thus should always be coupled with
    /// program transformations through [Self::compile_and_transform]. It should preferably not be
    /// observable as an atomic transition, although as far as I can tell, this shouldn't cause
    /// major troubles to do so.
    pub fn compile(
        &mut self,
        pos_table: &mut PosTable,
        main_id: FileId,
    ) -> Result<CacheOp<()>, AstCacheError<ImportError>> {
        if self.terms.contains(main_id) {
            return Ok(CacheOp::Cached(()));
        }

        // We set the format of the main `file_id` to `Nickel`, even if it is not, to require its
        // presence in either the term cache or the ast cache.
        let mut work_stack = vec![ImportTarget {
            file_id: main_id,
            format: InputFormat::default(),
        }];

        while let Some(ImportTarget { file_id, format }) = work_stack.pop() {
            if self.terms.contains(file_id) {
                continue;
            }

            let entry = if let InputFormat::Nickel = format {
                let ast_entry =
                    self.asts
                        .get_entry(file_id)
                        .ok_or(CacheError::IncompatibleState {
                            want: AstEntryState::Parsed,
                        })?;

                TermEntry {
                    value: ast_entry.ast.to_mainline(pos_table),
                    format: ast_entry.format,
                    state: TermEntryState::default(),
                }
            } else {
                // We want to maintain the same error message as before the introduction of the two
                // distinct representations, and their processing in two stages (first Nickel files that
                // have an AST, and then others before evaluation).
                //
                // If we find a non-Nickel file here that needs to be parsed, it's because it's
                // been imported from somewhere else. The error used to be an import error, which
                // includes the location of the importing expression. We thus raise an import error
                // here, in case of failure.
                let term = self
                    .sources
                    .parse_other(pos_table, file_id, format)
                    .map_err(|parse_err| {
                        CacheError::Error(Box::new(ImportErrorKind::ParseErrors(
                            parse_err.into(),
                            self.import_data
                                .rev_imports
                                .get(&file_id)
                                .and_then(|map| map.get(&main_id))
                                .copied()
                                .unwrap_or_default(),
                        )))
                    })?;

                TermEntry {
                    value: term,
                    format,
                    state: TermEntryState::default(),
                }
            };

            self.terms.insert(file_id, entry);
            self.wildcards.wildcards.insert(
                file_id,
                self.asts
                    .get_wildcards(file_id)
                    .map(|ws| ws.iter())
                    .unwrap_or_default()
                    .map(|ty| ty.to_mainline(pos_table))
                    .collect(),
            );

            work_stack.extend(
                self.import_data
                    .imports
                    .get(&file_id)
                    .into_iter()
                    .flat_map(|set| set.iter()),
            )
        }

        Ok(CacheOp::Done(()))
    }

    /// Converts an AST entry and all of its transitive dependencies to the runtime representation
    /// (compile), populating the term cache. Applies both import resolution and other program
    /// transformations on the resulting terms.
    pub fn compile_and_transform(
        &mut self,
        pos_table: &mut PosTable,
        file_id: FileId,
    ) -> Result<CacheOp<()>, AstCacheError<Error>> {
        let mut done = false;

        done = matches!(
            self.compile(pos_table, file_id)
                .map_err(|cache_err| cache_err.map_err(Error::ImportError))?,
            CacheOp::Done(_)
        ) || done;

        let imports = self
            .resolve_imports(pos_table, file_id)
            // force_cast(): since we compiled `file_id`, the term cache must be populated, and
            // thus `resolve_imports` should never throw `CacheError::IncompatibleState`.
            .map_err(|cache_err| cache_err.map_err(Error::ImportError).force_cast())?;
        done = matches!(imports, CacheOp::Done(_)) || done;

        let transform = self
            .terms
            .transform(pos_table, &self.wildcards, &self.import_data, file_id)
            // force_cast(): since we compiled `file_id`, the term cache must be populated, and
            // thus `resolve_imports` should never throw `CacheError::IncompatibleState`.
            .map_err(|cache_err| {
                cache_err
                    .map_err(|uvar_err| Error::ParseErrors(ParseErrors::from(uvar_err)))
                    .force_cast()
            })?;
        done = matches!(transform, CacheOp::Done(_)) || done;

        Ok(if done {
            CacheOp::Done(())
        } else {
            CacheOp::Cached(())
        })
    }

    /// Creates a partial copy of this cache for evaluation purposes only. In particular, we don't
    /// copy anything related to arena-allocated ASTs. However, source files, imports data and
    /// terms are copied over, which is useful to make new evaluation caches cheaply, typically for
    /// NLS and benches.
    pub fn clone_for_eval(&self) -> Self {
        Self {
            terms: self.terms.clone(),
            sources: self.sources.clone(),
            asts: AstCache::empty(),
            wildcards: self.wildcards.clone(),
            import_data: self.import_data.clone(),
            #[cfg(debug_assertions)]
            skip_stdlib: self.skip_stdlib,
        }
    }

    /// Split a mutable borrow to self into a mutable borrow of the AST cache and a mutable borrow
    /// of the rest.
    pub fn split_asts(&mut self) -> (CacheHubView<'_>, &mut AstCache) {
        (
            CacheHubView {
                terms: &mut self.terms,
                sources: &mut self.sources,
                wildcards: &mut self.wildcards,
                import_data: &mut self.import_data,
                #[cfg(debug_assertions)]
                skip_stdlib: self.skip_stdlib,
            },
            &mut self.asts,
        )
    }

    /// See [SourceCache::input_format].
    pub fn input_format(&self, file_id: FileId) -> Option<InputFormat> {
        self.sources.input_format(file_id)
    }
}

/// Because ASTs are arena-allocated, the self-referential [ast_cache::AstCache] which holds both
/// the arena and references to this arena often needs special treatment, if we want to make the
/// borrow checker happy. The following structure is basically a view of "everything but the ast
/// cache" into [CacheHub], so that we can separate and pack all the rest in a single structure,
/// making the signature of many [ast_cache::AstCache] methods much lighter.
pub struct CacheHubView<'cache> {
    terms: &'cache mut TermCache,
    sources: &'cache mut SourceCache,
    wildcards: &'cache mut WildcardsCache,
    import_data: &'cache mut ImportData,
    #[cfg(debug_assertions)]
    /// Skip loading the stdlib, used for debugging purpose
    skip_stdlib: bool,
}

impl CacheHubView<'_> {
    /// Make a reborrow of this slice.
    pub fn reborrow(&mut self) -> CacheHubView<'_> {
        CacheHubView {
            terms: self.terms,
            sources: self.sources,
            wildcards: self.wildcards,
            import_data: self.import_data,
            #[cfg(debug_assertions)]
            skip_stdlib: self.skip_stdlib,
        }
    }
}

/// An entry in the term cache. Stores the parsed term together with metadata and state.
#[derive(Debug, Clone, PartialEq)]
pub struct TermEntry {
    pub value: NickelValue,
    pub state: TermEntryState,
    pub format: InputFormat,
}

/// An entry in the AST cache. Stores the parsed term together with metadata and state.
#[derive(Debug, Clone, PartialEq)]
pub struct AstEntry<'ast> {
    pub ast: &'ast Ast<'ast>,
    pub state: AstEntryState,
    pub format: InputFormat,
}

impl<'ast> AstEntry<'ast> {
    /// Creates a new entry with default metadata.
    pub fn new(ast: &'ast Ast<'ast>) -> Self {
        AstEntry {
            ast,
            state: AstEntryState::default(),
            format: InputFormat::default(),
        }
    }
}

/// Inputs can be read from the filesystem or from in-memory buffers (which come, e.g., from
/// the REPL, the standard library, or the language server).
///
/// Inputs read from the filesystem get auto-refreshed: if we try to access them again and
/// the on-disk file has changed, we read it again. Inputs read from in-memory buffers
/// are not auto-refreshed. If an in-memory buffer has a path that also exists in the
/// filesystem, we will not even check that file to see if it has changed.
///
/// An input that was open as an in-memory file may be closed, namely when the file is closed
/// or deleted from an editor using the LSP. In this case, the file will be read from the
/// filesystem again instead of using the in-memory value. Closing a file only makes sense in the
/// case that the [SourcePath] refers to a path on the filesystem. Other types of in-memory files,
/// like the standard library, cannot be closed.
#[derive(Eq, PartialEq, Ord, PartialOrd, Debug, Copy, Clone)]
enum SourceKind {
    Filesystem(SystemTime),
    Memory,
    MemoryClosed,
}

/// The errors that can occur while closing an in memory file.
#[derive(Debug, Clone)]
pub enum FileCloseError {
    /// The file was not closed because no mapping of the source path to a [FileId] could be
    /// found.
    FileIdNotFound,
    /// A file with the given path was found, but it was not open in memory.
    FileNotOpen,
}

impl fmt::Display for FileCloseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self {
            FileCloseError::FileIdNotFound => {
                write!(
                    f,
                    "No file ID could be found for the file path to be closed."
                )
            }
            FileCloseError::FileNotOpen => {
                write!(f, "Attempted to close a file that was not open in-memory.")
            }
        }
    }
}

impl std::error::Error for FileCloseError {}

/// Contains information about the closed in-memory file and its replacement from the filesystem
/// in the case that an in-memory file was closed successfully.
pub struct FileCloseResult {
    /// The [FileId] of the in-memory file that was closed.
    pub closed_id: FileId,
    /// The [FileId] of the file loaded from the filesystem with the same path as the closed
    /// file, or an error indicating why the file could not be opened.
    /// An error would be expected here in the case that the file was deleted, which would
    /// also send a close file notification to the LSP.
    pub replacement_id: Result<FileId, io::Error>,
}

/// Cache entries for sources.
///
/// A source can be either a snippet input by the user, in which case it is only identified by its
/// name in the name-id table, and a unique `FileId`. On the other hand, different versions of the
/// same file can coexist during the same session of the REPL. For this reason, an entry of the
/// name-id table of a file also stores the *modified at* timestamp, such that if a file is
/// imported or loaded again and has been modified in between, the entry is invalidated, the
/// content is loaded again and a new `FileId` is generated.
///
/// Note that in that case, invalidation just means that the `FileId` of a previous version is not
/// accessible anymore in the name-id table. However, terms that contain non evaluated imports or
/// source locations referring to previous version are still able access the corresponding source
/// or term which are kept respectively in `files` and `cache` by using the corresponding `FileId`.
#[derive(Eq, PartialEq, Ord, PartialOrd, Debug, Copy, Clone)]
pub struct NameIdEntry {
    id: FileId,
    source: SourceKind,
}

/// The state of an entry of the term cache.
///
/// # Imports
///
/// Usually, when applying a procedure to a term entry (e.g. program transformations), we process
/// all of its transitive imports as well. We start by processing the entry, updating the state to
/// `XXXing` (ex: `Typechecking`) upon success. Only when all the imports have been successfully
/// processed, the state is updated to `XXXed` (ex: `Typechecked`).
#[derive(Eq, PartialEq, Ord, PartialOrd, Debug, Copy, Clone, Default)]
pub enum TermEntryState {
    /// The initial state. The term is in the cache but hasn't been processed further yet.
    #[default]
    Populated,
    /// A custom transformation of the entry (through `Program::custom_transform`) is underway.
    CustomTransforming,
    /// This entry has completed custom transformations of this ID and lower.
    CustomTransformed { transform_id: usize },
    /// The imports of the entry have been resolved, and the imports of its (transitive) imports are
    /// being resolved.
    ImportsResolving,
    /// The imports of the entry and its transitive dependencies has been resolved.
    ImportsResolved,
    /// The entry have been transformed, and its (transitive) imports are being transformed.
    Transforming,
    /// The entry and its transitive imports have been transformed.
    Transformed,
    /// The entry has been closurized.
    Closurized,
}

impl TermEntryState {
    fn needs_custom_transform(&self, transform_id: usize) -> bool {
        if let TermEntryState::CustomTransformed {
            transform_id: done_transform_id,
        } = self
        {
            transform_id > *done_transform_id
        } else {
            *self < TermEntryState::CustomTransforming
        }
    }
}

/// The state of an entry in the AST cache. Equivalent of [TermEntryState] but for ASTs.
#[derive(Eq, PartialEq, Ord, PartialOrd, Debug, Copy, Clone, Default)]
pub enum AstEntryState {
    /// The initial state. The AST is in the cache but hasn't been processed further yet.
    #[default]
    Parsed,
    /// The entry have been typechecked, and its (transitive) imports are being typechecked.
    Typechecking,
    /// The entry and its transitive imports have been typechecked.
    Typechecked,
}

/// The result of a cache operation, such as parsing, typechecking, etc. which can either have
/// performed actual work, or have done nothing if the corresponding entry was already at a later
/// stage.
#[derive(Eq, PartialEq, Ord, PartialOrd, Debug, Copy, Clone)]
pub enum CacheOp<T> {
    Done(T),
    Cached(T),
}

impl<T> CacheOp<T> {
    pub fn inner(self: CacheOp<T>) -> T {
        match self {
            CacheOp::Done(t) | CacheOp::Cached(t) => t,
        }
    }
}

/// Wrapper around other errors to indicate that typechecking or applying program transformations
/// failed because the source has not been parsed yet.
///
/// # Type parameters
///
/// - `E`: the underlying, wrapped error type
/// - `S`: the entry state, whether [TermEntryState] or [AstEntryState] in practice.
#[derive(Eq, PartialEq, Debug, Clone)]
pub enum CacheError<E, S> {
    Error(E),
    /// The state of the entry in the cache is incompatible with the requested operation.
    IncompatibleState {
        want: S,
    },
}

pub type AstCacheError<E> = CacheError<E, AstEntryState>;
pub type TermCacheError<E> = CacheError<E, TermEntryState>;

impl<E, S> From<E> for CacheError<E, S> {
    fn from(e: E) -> Self {
        CacheError::Error(e)
    }
}

impl<E, S> CacheError<E, S> {
    #[track_caller]
    pub fn unwrap_error(self, msg: &str) -> E {
        match self {
            CacheError::Error(err) => err,
            CacheError::IncompatibleState { .. } => panic!("{}", msg),
        }
    }

    pub fn map_err<O>(self, f: impl FnOnce(E) -> O) -> CacheError<O, S> {
        match self {
            CacheError::Error(e) => CacheError::Error(f(e)),
            CacheError::IncompatibleState { want } => CacheError::IncompatibleState { want },
        }
    }

    /// Assuming that `self` is of the form `CacheError::Error(e)`, cast the error type to another
    /// arbitrary state type `T`.
    ///
    /// # Panic
    ///
    /// This method panics if `self` is [CacheError::IncompatibleState].
    #[track_caller]
    pub fn force_cast<T>(self) -> CacheError<E, T> {
        match self {
            CacheError::Error(e) => CacheError::Error(e),
            CacheError::IncompatibleState { want: _ } => panic!(),
        }
    }
}

/// Input data usually comes from files on the file system, but there are also lots of cases where
/// we want to synthesize other kinds of inputs.
///
/// Note that a [SourcePath] does not uniquely identify a cached input:
///
/// - Some functions (like [SourceCache::add_file]) add a new cached input unconditionally.
/// - [`SourceCache::get_or_add_file`] will add a new cached input at the same `SourcePath` if the file
///   on disk was updated.
///
/// The equality checking of `SourcePath` only affects [SourceCache::replace_string], which
/// overwrites any previous cached input with the same `SourcePath`.
#[derive(Debug, PartialEq, Eq, Hash, Clone)]
pub enum SourcePath {
    /// A file at the given path.
    ///
    /// Note that this does not need to be a real file on the filesystem: it could still be loaded
    /// from memory by, e.g, [`SourceCache::add_string`].
    ///
    /// This is the only `SourcePath` variant that can be resolved as the target of an import
    /// statement.
    Path(PathBuf, InputFormat),
    /// A subrange of a file at the given path.
    ///
    /// This is used by NLS to analyze small parts of files that don't fully parse. The original
    /// file path is preserved, because it's needed for resolving imports.
    Snippet(PathBuf),
    Std(StdlibModule),
    Query,
    ReplInput(usize),
    ReplTypecheck,
    ReplQuery,
    CliFieldAssignment,
    Override(FieldPath),
    Generated(String),
}

impl<'a> TryFrom<&'a SourcePath> for &'a OsStr {
    type Error = ();

    fn try_from(value: &'a SourcePath) -> Result<Self, Self::Error> {
        match value {
            SourcePath::Path(p, _) | SourcePath::Snippet(p) => Ok(p.as_os_str()),
            _ => Err(()),
        }
    }
}

impl From<&SourcePath> for Option<InputFormat> {
    fn from(source_path: &SourcePath) -> Option<InputFormat> {
        if let SourcePath::Path(_p, fmt) = source_path {
            Some(*fmt)
        } else {
            None
        }
    }
}

// [`Files`] needs to have an OsString for each file, so we synthesize names even for sources that
// don't have them. They don't need to be unique; they're just used for diagnostics.
impl From<SourcePath> for OsString {
    fn from(source_path: SourcePath) -> Self {
        match source_path {
            SourcePath::Path(p, _) | SourcePath::Snippet(p) => p.into(),
            SourcePath::Std(StdlibModule::Std) => "<stdlib/std.ncl>".into(),
            SourcePath::Std(StdlibModule::Internals) => "<stdlib/internals.ncl>".into(),
            SourcePath::Query => "<query>".into(),
            SourcePath::ReplInput(idx) => format!("<repl-input-{idx}>").into(),
            SourcePath::ReplTypecheck => "<repl-typecheck>".into(),
            SourcePath::ReplQuery => "<repl-query>".into(),
            SourcePath::CliFieldAssignment => "<cli-assignment>".into(),
            SourcePath::Override(path) => format!("<override {path}>",).into(),
            SourcePath::Generated(description) => format!("<generated {description}>").into(),
        }
    }
}

/// Return status indicating if an import has been resolved from a file (first encounter), or was
/// retrieved from the cache.
///
/// See [ImportResolver::resolve].
#[derive(Debug, PartialEq, Eq)]
pub enum ResolvedTerm {
    FromFile {
        path: PathBuf, /* the loaded path */
    },
    FromCache,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum SourceState {
    UpToDate(FileId),
    /// The source is stale because it came from a file on disk that has since been updated. The
    /// data is the timestamp of the new version of the file.
    Stale(SystemTime),
}

/// Abstract the access to imported files and the import cache. Used by the evaluator and at the
/// [import resolution](crate::transform::import_resolution) phase.
///
/// The standard implementation uses 2 caches, the file cache for raw contents and the term cache
/// for parsed contents, mirroring the 2 steps when resolving an import:
///
/// 1. When an import is encountered for the first time, the content of the corresponding file is
///    read and stored in the file cache (consisting of the file database plus a map between paths
///    and ids in the database, the name-id table). The content is parsed, stored in the term
///    cache, and queued somewhere so that it can undergo the standard
///    [transformations](crate::transform) (including import resolution) later.
/// 2. When it is finally processed, the term cache is updated with the transformed term.
///
/// # RFC007
///
/// Import resolution on the old representation is still needed only because of the evaluator. The
/// typechecker now uses the new AST representation with its own import resolver.
pub trait ImportResolver {
    /// Resolves an import.
    ///
    /// Reads and stores the content of an import, puts it in the file cache (or get it from there
    /// if it is cached), then parses it and returns the corresponding term and file id.
    ///
    /// The term and the path are provided only if the import is processed for the first time.
    /// Indeed, at import resolution phase, the term of an import encountered for the first time is
    /// queued to be processed (e.g. having its own imports resolved). The path is needed to
    /// resolve nested imports relatively to this parent. Only after this processing the term is
    /// inserted back in the cache. On the other hand, if it has been resolved before, it is
    /// already transformed in the cache and do not need further processing.
    fn resolve(
        &mut self,
        pos_table: &mut PosTable,
        import: &term::Import,
        parent: Option<FileId>,
        pos_idx: PosIdx,
    ) -> Result<(ResolvedTerm, FileId), ImportError>;

    /// Return a reference to the file database.
    fn files(&self) -> &Files;

    /// Get a resolved import from the term cache.
    fn get(&self, file_id: FileId) -> Option<NickelValue>;
    /// Return the (potentially normalized) file path corresponding to the ID of a resolved import.
    fn get_path(&self, file_id: FileId) -> Option<&OsStr>;

    /// Returns the base path for Nix evaluation, which is the parent directory of the source file
    /// if any, or the current working directory, or an empty path if we couldn't determine any of
    /// the previous two.
    ///
    /// This method need to be here because the evaluator makes use of it (when evaluating the
    /// `eval_nix` primop), but at this stage it only has access to the `ImportResolver` interface.
    /// We could give a default implementation here just using [Self::get_path], but we also need
    /// `get_base_dir_for_nix` in [SourceCache]. We reuse the latter `implementation instead of
    /// duplicating a more generic variant here.
    #[cfg(feature = "nix-experimental")]
    fn get_base_dir_for_nix(&self, file_id: FileId) -> PathBuf;
}

impl ImportResolver for CacheHub {
    fn resolve(
        &mut self,
        pos_table: &mut PosTable,
        import: &term::Import,
        parent: Option<FileId>,
        pos_idx: PosIdx,
    ) -> Result<(ResolvedTerm, FileId), ImportError> {
        let pos = pos_table.get(pos_idx);

        let (possible_parents, path, pkg_id, format) = match import {
            term::Import::Path { path, format } => {
                // `parent` is the file that did the import. We first look in its containing directory, followed by
                // the directories in the import path.
                let mut parent_path = parent
                    .and_then(|p| self.get_path(p))
                    .map(PathBuf::from)
                    .unwrap_or_default();
                parent_path.pop();

                (
                    std::iter::once(parent_path)
                        .chain(self.sources.import_paths.iter().cloned())
                        .collect(),
                    Path::new(path),
                    None,
                    *format,
                )
            }
            term::Import::Package { id } => {
                let package_map = self
                    .sources
                    .package_map
                    .as_ref()
                    .ok_or(ImportErrorKind::NoPackageMap { pos })?;
                let parent_path = parent
                    .and_then(|p| self.sources.packages.get(&p))
                    .map(PathBuf::as_path);
                let pkg_path = package_map.get(parent_path, *id, pos)?;
                (
                    vec![pkg_path.to_owned()],
                    Path::new("main.ncl"),
                    Some(pkg_path.to_owned()),
                    // Packages are always in nickel format
                    InputFormat::Nickel,
                )
            }
        };

        // Try to import from all possibilities, taking the first one that succeeds.
        let (id_op, path_buf) = possible_parents
            .iter()
            .find_map(|parent| {
                let mut path_buf = parent.clone();
                path_buf.push(path);
                self.sources
                    .get_or_add_file(&path_buf, format)
                    .ok()
                    .map(|x| (x, path_buf))
            })
            .ok_or_else(|| {
                let parents = possible_parents
                    .iter()
                    .map(|p| p.to_string_lossy())
                    .collect::<Vec<_>>();
                ImportErrorKind::IOError(
                    path.to_string_lossy().into_owned(),
                    format!("could not find import (looked in [{}])", parents.join(", ")),
                    pos,
                )
            })?;

        let (result, file_id) = match id_op {
            CacheOp::Cached(id) => (ResolvedTerm::FromCache, id),
            CacheOp::Done(id) => (ResolvedTerm::FromFile { path: path_buf }, id),
        };

        if let Some(parent) = parent {
            self.import_data
                .imports
                .entry(parent)
                .or_default()
                .insert(ImportTarget { file_id, format });
            self.import_data
                .rev_imports
                .entry(file_id)
                .or_default()
                .entry(parent)
                .or_insert(pos);
        }

        self.parse_to_term(pos_table, file_id, format)
            .map_err(|err| ImportErrorKind::ParseErrors(err, pos))?;

        if let Some(pkg_id) = pkg_id {
            self.sources.packages.insert(file_id, pkg_id);
        }

        Ok((result, file_id))
    }

    fn files(&self) -> &Files {
        &self.sources.files
    }

    fn get(&self, file_id: FileId) -> Option<NickelValue> {
        self.terms
            .terms
            .get(&file_id)
            .map(|TermEntry { value, .. }| value.clone())
    }

    fn get_path(&self, file_id: FileId) -> Option<&OsStr> {
        self.sources
            .file_paths
            .get(&file_id)
            .and_then(|p| p.try_into().ok())
    }

    #[cfg(feature = "nix-experimental")]
    fn get_base_dir_for_nix(&self, file_id: FileId) -> PathBuf {
        self.sources.get_base_dir_for_nix(file_id)
    }
}

/// Import resolution for new AST representation (RFC007).
pub trait AstImportResolver {
    /// Resolves an import to an AST.
    ///
    /// Reads and stores the content of an import, puts it in the file cache (or gets it from there
    /// if it is cached), then parses it and returns the corresponding term and file id.
    ///
    /// The term and the path are provided only if the import is processed for the first time.
    /// Indeed, at import resolution phase, the term of an import encountered for the first time is
    /// queued to be processed (e.g. having its own imports resolved). The path is needed to
    /// resolve nested imports relatively to this parent. Only after this processing the term is
    /// inserted back in the cache. On the other hand, if it has been resolved before, it is
    /// already transformed in the cache and do not need further processing.
    ///
    /// # Returns
    ///
    /// [Self::resolve] returns `Ok(None)` if the import is an external format, which can currently
    /// be serialized directly to he runtime representation ([NickelValue]) without going through
    /// an AST. AST import resolution is mostly used by the typechecker, and the typechecker
    /// currently ignores external formats anyway.
    ///
    /// # Lifetimes
    ///
    /// The signature is parametrized by two different lifetimes. This is due mostly to NLS: in the
    /// normal Nickel pipeline, all the ASTs are currently allocated in the same arena, and their
    /// lifetime is the same. However, in NLS, each files needs to be managed separately. At the
    /// import boundary, we're thus not guaranteed to get an AST that lives as long as the one
    /// being currently typechecked.
    fn resolve<'ast_out>(
        &'ast_out mut self,
        import: &ast::Import<'_>,
        pos: &TermPos,
    ) -> Result<Option<&'ast_out Ast<'ast_out>>, ImportErrorKind>;
}

/// Normalize the path of a file for unique identification in the cache.
///
/// The returned path will be an absolute path.
pub fn normalize_path(path: impl Into<PathBuf>) -> std::io::Result<PathBuf> {
    let mut path = path.into();
    if path.is_relative() {
        path = std::env::current_dir()?.join(path);
    }
    Ok(normalize_abs_path(&path))
}

/// Normalize the path (assumed to be absolute) of a file for unique identification in the cache.
///
/// This implementation (including the comment below) was taken from cargo-util.
///
/// CAUTION: This does not resolve symlinks (unlike [`std::fs::canonicalize`]). This may cause
/// incorrect or surprising behavior at times. This should be used carefully. Unfortunately,
/// [`std::fs::canonicalize`] can be hard to use correctly, since it can often fail, or on Windows
/// returns annoying device paths. This is a problem Cargo needs to improve on.
pub fn normalize_abs_path(path: &Path) -> PathBuf {
    use std::path::Component;

    let mut components = path.components().peekable();
    let mut ret = if let Some(c @ Component::Prefix(..)) = components.peek().cloned() {
        components.next();
        PathBuf::from(c.as_os_str())
    } else {
        PathBuf::new()
    };

    for component in components {
        match component {
            Component::Prefix(..) => unreachable!(),
            Component::RootDir => {
                ret.push(component.as_os_str());
            }
            Component::CurDir => {}
            Component::ParentDir => {
                ret.pop();
            }
            Component::Normal(c) => {
                ret.push(c);
            }
        }
    }
    ret
}

/// Normalize a relative path, removing mid-path `..`s.
///
/// Like [`normalize_abs_path`], this works only on the path itself (i.e. not the filesystem) and
/// does not follow symlinks.
pub fn normalize_rel_path(path: &Path) -> PathBuf {
    use std::path::Component;

    let mut components = path.components().peekable();
    let mut parents = PathBuf::new();
    let mut ret = if let Some(c @ Component::Prefix(..)) = components.peek().cloned() {
        components.next();
        PathBuf::from(c.as_os_str())
    } else {
        PathBuf::new()
    };

    for component in components {
        match component {
            Component::Prefix(..) => unreachable!(),
            Component::RootDir => {
                ret.push(component.as_os_str());
            }
            Component::CurDir => {}
            Component::ParentDir => {
                if !ret.pop() {
                    parents.push(Component::ParentDir);
                }
            }
            Component::Normal(c) => {
                ret.push(c);
            }
        }
    }
    parents.extend(ret.components());
    parents
}

/// Returns the timestamp of a file. Return `None` if an IO error occurred.
pub fn timestamp(path: impl AsRef<OsStr>) -> io::Result<SystemTime> {
    fs::metadata(path.as_ref())?.modified()
}

/// As RFC007 is being rolled out, the typechecker now needs to operate on the new AST. We need a
/// structure that implements [AstImportResolver].
///
/// For borrowing reasons, this can't be all of [CacheHub] or all of [ast_cache::AstCache], as we
/// need to split the different things that are borrowed mutably or immutably. `AstResolver` is a
/// structure that borrows some parts of the cache during its lifetime and will retrieve already
/// imported ASTs, or register the newly imported ones in a separate hashmap that can be added back
/// to the original cache once import resolution is done.
pub struct AstResolver<'ast, 'cache> {
    /// The AST allocator used to parse new sources.
    alloc: &'ast AstAlloc,
    /// The AST cache, which is added to as import resolution progresses.
    asts: &'cache mut HashMap<FileId, AstEntry<'ast>>,
    /// The source cache where new sources will be stored.
    sources: &'cache mut SourceCache,
    /// Direct and reverse dependencies of files (with respect to imports).
    import_data: &'cache mut ImportData,
}

impl<'ast, 'cache> AstResolver<'ast, 'cache> {
    /// Create a new `AstResolver` from an allocator, an ast cache and a cache hub slice.
    pub fn new(
        alloc: &'ast AstAlloc,
        asts: &'cache mut HashMap<FileId, AstEntry<'ast>>,
        slice: CacheHubView<'cache>,
    ) -> Self {
        Self {
            alloc,
            asts,
            sources: slice.sources,
            import_data: slice.import_data,
        }
    }
}

impl AstImportResolver for AstResolver<'_, '_> {
    fn resolve(
        &mut self,
        import: &ast::Import<'_>,
        pos: &TermPos,
    ) -> Result<Option<&Ast<'_>>, ImportErrorKind> {
        let parent_id = pos.src_id();

        let (possible_parents, path, pkg_id, format) = match import {
            ast::Import::Path { path, format } => {
                // `parent` is the file that did the import. We first look in its containing
                // directory, followed by the directories in the import path.
                let parent_path = parent_id
                    .and_then(|parent| self.sources.file_paths.get(&parent))
                    .and_then(|path| <&OsStr>::try_from(path).ok())
                    .map(PathBuf::from)
                    .map(|mut path| {
                        path.pop();
                        path
                    })
                    // If the parent isn't a proper file, we look in the current directory instead.
                    // This is useful when importing e.g. from the REPL or the CLI directly.
                    .unwrap_or_default();

                (
                    std::iter::once(parent_path)
                        .chain(self.sources.import_paths.iter().cloned())
                        .collect(),
                    Path::new(path),
                    None,
                    *format,
                )
            }
            ast::Import::Package { id } => {
                let package_map = self
                    .sources
                    .package_map
                    .as_ref()
                    .ok_or(ImportErrorKind::NoPackageMap { pos: *pos })?;
                let parent_path = parent_id
                    .and_then(|p| self.sources.packages.get(&p))
                    .map(PathBuf::as_path);
                let pkg_path = package_map.get(parent_path, *id, *pos)?;
                (
                    vec![pkg_path.to_owned()],
                    Path::new("main.ncl"),
                    Some(pkg_path.to_owned()),
                    // Packages are always in nickel format
                    InputFormat::Nickel,
                )
            }
        };

        // Try to import from all possibilities, taking the first one that succeeds.
        let id_op = possible_parents
            .iter()
            .find_map(|parent| {
                let mut path_buf = parent.clone();
                path_buf.push(path);
                self.sources.get_or_add_file(&path_buf, format).ok()
            })
            .ok_or_else(|| {
                let parents = possible_parents
                    .iter()
                    .map(|p| p.to_string_lossy())
                    .collect::<Vec<_>>();
                ImportErrorKind::IOError(
                    path.to_string_lossy().into_owned(),
                    format!("could not find import (looked in [{}])", parents.join(", ")),
                    *pos,
                )
            })?;

        let file_id = id_op.inner();

        if let Some(parent_id) = parent_id {
            self.import_data
                .imports
                .entry(parent_id)
                .or_default()
                .insert(ImportTarget { file_id, format });
            self.import_data
                .rev_imports
                .entry(file_id)
                .or_default()
                .entry(parent_id)
                .or_insert(*pos);
        }

        if let Some(pkg_id) = pkg_id {
            self.sources.packages.insert(file_id, pkg_id);
        }

        if let InputFormat::Nickel = format {
            if let Some(entry) = self.asts.get(&file_id) {
                Ok(Some(entry.ast))
            } else {
                let ast = parse_nickel(self.alloc, file_id, self.sources.files.source(file_id))
                    .map_err(|parse_err| ImportErrorKind::ParseErrors(parse_err, *pos))?;
                let ast = self.alloc.alloc(ast);
                self.asts.insert(file_id, AstEntry::new(ast));

                Ok(Some(ast))
            }
        } else {
            // Currently, non-Nickel file are just ignored during the AST phase. They are parsed
            // later directly into the runtime
            Ok(None)
        }
    }
}

/// Provide mockup import resolvers for testing purpose.
pub mod resolvers {
    use super::*;
    use crate::term::Import;

    /// A dummy resolver that panics when asked to do something. Used to test code that contains no
    /// import.
    pub struct DummyResolver {}

    impl ImportResolver for DummyResolver {
        fn resolve(
            &mut self,
            _pos_table: &mut PosTable,
            _import: &Import,
            _parent: Option<FileId>,
            _pos_idx: PosIdx,
        ) -> Result<(ResolvedTerm, FileId), ImportError> {
            panic!("cache::resolvers: dummy resolver should not have been invoked");
        }

        fn files(&self) -> &Files {
            panic!("cache::resolvers: dummy resolver should not have been invoked");
        }

        fn get(&self, _file_id: FileId) -> Option<NickelValue> {
            panic!("cache::resolvers: dummy resolver should not have been invoked");
        }

        fn get_path(&self, _file_id: FileId) -> Option<&OsStr> {
            panic!("cache::resolvers: dummy resolver should not have been invoked");
        }

        #[cfg(feature = "nix-experimental")]
        fn get_base_dir_for_nix(&self, _file_id: FileId) -> PathBuf {
            panic!("cache::resolvers: dummy resolver should not have been invoked");
        }
    }

    /// Resolve imports from a mockup file database. Used to test imports without accessing the
    /// file system. File name are stored as strings, and silently converted from/to `OsString`
    /// when needed: don't use this resolver with source code that import non UTF-8 paths.
    #[derive(Clone, Default)]
    pub struct SimpleResolver {
        files: Files,
        file_cache: HashMap<String, FileId>,
        term_cache: HashMap<FileId, NickelValue>,
    }

    impl SimpleResolver {
        pub fn new() -> SimpleResolver {
            SimpleResolver::default()
        }

        /// Add a mockup file to available imports.
        pub fn add_source(&mut self, name: String, source: String) {
            let id = self.files.add(name.clone(), source);
            self.file_cache.insert(name, id);
        }
    }

    impl ImportResolver for SimpleResolver {
        fn resolve(
            &mut self,
            pos_table: &mut PosTable,
            import: &Import,
            _parent: Option<FileId>,
            pos_idx: PosIdx,
        ) -> Result<(ResolvedTerm, FileId), ImportError> {
            let Import::Path { path, .. } = import else {
                panic!("simple resolver doesn't support packages");
            };

            let pos = pos_table.get(pos_idx);

            let file_id = self
                .file_cache
                .get(path.to_string_lossy().as_ref())
                .copied()
                .ok_or_else(|| {
                    ImportErrorKind::IOError(
                        path.to_string_lossy().into_owned(),
                        String::from("Import not found by the mockup resolver."),
                        pos,
                    )
                })?;

            if let hash_map::Entry::Vacant(e) = self.term_cache.entry(file_id) {
                let buf = self.files.source(file_id);
                let alloc = AstAlloc::new();

                let ast = parser::grammar::TermParser::new()
                    .parse_strict(&alloc, file_id, Lexer::new(buf))
                    .map_err(|e| ImportErrorKind::ParseErrors(e, pos))?;
                e.insert(ast.to_mainline(pos_table));

                Ok((
                    ResolvedTerm::FromFile {
                        path: PathBuf::new(),
                    },
                    file_id,
                ))
            } else {
                Ok((ResolvedTerm::FromCache, file_id))
            }
        }

        fn files(&self) -> &Files {
            &self.files
        }

        fn get(&self, file_id: FileId) -> Option<NickelValue> {
            self.term_cache.get(&file_id).cloned()
        }

        fn get_path(&self, file_id: FileId) -> Option<&OsStr> {
            Some(self.files.name(file_id))
        }

        #[cfg(feature = "nix-experimental")]
        fn get_base_dir_for_nix(&self, file_id: FileId) -> PathBuf {
            self.get_path(file_id)
                .and_then(|path| Path::new(path).parent())
                .map(PathBuf::from)
                .unwrap_or_default()
        }
    }
}

/// Parses a Nickel expression from a string.
fn parse_nickel<'ast>(
    alloc: &'ast AstAlloc,
    file_id: FileId,
    source: &str,
) -> Result<Ast<'ast>, ParseErrors> {
    let ast = measure_runtime!(
        "runtime:parse:nickel",
        parser::grammar::TermParser::new().parse_strict(alloc, file_id, Lexer::new(source))?
    );

    Ok(ast)
}

// Parse a Nickel REPL input. In addition to normal Nickel expressions, it can be a top-level let.
fn parse_nickel_repl<'ast>(
    alloc: &'ast AstAlloc,
    file_id: FileId,
    source: &str,
) -> Result<ExtendedTerm<Ast<'ast>>, ParseErrors> {
    let et = measure_runtime!(
        "runtime:parse:nickel",
        parser::grammar::ExtendedTermParser::new().parse_strict(
            alloc,
            file_id,
            Lexer::new(source)
        )?
    );

    Ok(et)
}

/// AST cache (for the new [crate::ast::Ast]) that holds the owned allocator of the AST
/// nodes.
mod ast_cache {
    use super::*;
    use crate::traverse::TraverseAlloc as _;

    /// The AST cache packing together the AST allocator and the cached ASTs.
    #[self_referencing]
    pub struct AstCache {
        /// The allocator hosting AST nodes.
        alloc: AstAlloc,
        /// An AST for each file we have cached.
        #[borrows(alloc)]
        #[covariant]
        asts: HashMap<FileId, AstEntry<'this>>,
        /// The initial typing context. It's morally an option (uninitialized at first), but we just
        /// use an empty context as a default value.
        ///
        /// This context can be augmented through [AstCache::add_repl_binding] and
        /// [AstCache::add_repl_bindings], which is typically used in the REPL to add top-level
        /// bindings.
        #[borrows(alloc)]
        #[not_covariant]
        type_ctxt: typecheck::Context<'this>,
        /// Mapping of each wildcard id to its inferred type, for each file in the cache. This is
        /// the same as [super::WildcardsCache], but in the new AST representation. It is later on
        /// transformed to the runtime representation to populate the wildcard cache.
        #[borrows(alloc)]
        #[covariant]
        wildcards: HashMap<FileId, typecheck::Wildcards<'this>>,
    }

    impl AstCache {
        /// Construct a new, empty, AST cache.
        pub fn empty() -> Self {
            AstCache::new(
                AstAlloc::new(),
                |_alloc| HashMap::new(),
                |_alloc| typecheck::Context::new(),
                |_alloc| HashMap::new(),
            )
        }

        /// Clears the allocator and the cached ASTs.
        pub fn clear(&mut self) {
            *self = Self::empty();
        }

        /// Returns `true` if the AST cache contains an entry for the given file id.
        pub fn contains(&self, file_id: FileId) -> bool {
            self.borrow_asts().contains_key(&file_id)
        }

        /// Returns the underlying allocator, which might be required to call various helpers.
        pub fn get_alloc(&self) -> &AstAlloc {
            self.borrow_alloc()
        }

        /// Returns a reference to a cached AST.
        pub fn get(&self, file_id: FileId) -> Option<&Ast<'_>> {
            self.borrow_asts().get(&file_id).map(|entry| entry.ast)
        }

        /// Returns a reference to a cached AST entry.
        pub fn get_entry(&self, file_id: FileId) -> Option<&AstEntry<'_>> {
            self.borrow_asts().get(&file_id)
        }

        /// Returns the wildcards associated to an entry.
        pub fn get_wildcards(&self, file_id: FileId) -> Option<&typecheck::Wildcards<'_>> {
            self.borrow_wildcards().get(&file_id)
        }

        /// Retrieves the state of an entry. Returns `None` if the entry is not in the AST cache.
        pub fn entry_state(&self, file_id: FileId) -> Option<AstEntryState> {
            self.borrow_asts()
                .get(&file_id)
                .map(|AstEntry { state, .. }| *state)
        }

        /// Updates the state of an entry and returns the previous state, or an error if the entry
        /// isn't in the cache.
        pub fn update_state(
            &mut self,
            file_id: FileId,
            new: AstEntryState,
        ) -> Result<AstEntryState, TermNotFound> {
            self.with_asts_mut(|asts| {
                asts.get_mut(&file_id)
                    .map(|AstEntry { state, .. }| std::mem::replace(state, new))
            })
            .ok_or(TermNotFound)
        }

        /// Parses a Nickel expression and stores the corresponding AST in the cache.
        pub fn parse_nickel<'ast>(
            &'ast mut self,
            file_id: FileId,
            source: &str,
        ) -> Result<&'ast Ast<'ast>, ParseErrors> {
            self.with_mut(|slf| {
                let ast = parse_nickel(slf.alloc, file_id, source)?;
                let ast = slf.alloc.alloc(ast);
                slf.asts.insert(file_id, AstEntry::new(ast));

                Ok(ast)
            })
        }

        /// Same as [Self::parse_nickel] but accepts the extended syntax allowed in the REPL.
        ///
        /// **Caution**: this method doesn't cache the potential id of a top-level let binding,
        /// although it does save the bound expression, which is required later for typechecking,
        /// program transformation, etc.
        pub fn parse_nickel_repl<'ast>(
            &'ast mut self,
            file_id: FileId,
            source: &str,
        ) -> Result<ExtendedTerm<Ast<'ast>>, ParseErrors> {
            self.with_mut(|slf| {
                let extd_ast = parse_nickel_repl(slf.alloc, file_id, source)?;

                let ast = match &extd_ast {
                    ExtendedTerm::Term(t) | ExtendedTerm::ToplevelLet(_, t) => {
                        slf.alloc.alloc(t.clone())
                    }
                };

                slf.asts.insert(file_id, AstEntry::new(ast));

                Ok(extd_ast)
            })
        }

        pub fn remove(&mut self, file_id: FileId) -> Option<AstEntry<'_>> {
            self.with_asts_mut(|asts| asts.remove(&file_id))
        }

        /// Typechecks an entry of the cache and updates its state accordingly, or does nothing if
        /// the entry has already been typechecked. Requires that the corresponding source has been
        /// parsed. Note that this method currently fail on a non-Nickel file, that can't have been
        /// parsed to an AST.
        ///
        /// If the source contains imports, recursively typecheck on the imports too.
        ///
        /// # RFC007
        ///
        /// During the transition period between the old VM and the new bytecode VM, this method
        /// performs typechecking on the new representation [crate::ast::Ast].
        pub fn typecheck(
            &mut self,
            mut slice: CacheHubView<'_>,
            file_id: FileId,
            initial_mode: TypecheckMode,
        ) -> Result<CacheOp<()>, AstCacheError<TypecheckError>> {
            let Some(state) = self.entry_state(file_id) else {
                return Err(CacheError::IncompatibleState {
                    want: AstEntryState::Parsed,
                });
            };

            // If we're already typechecking or we have typechecked the file, we stop right here.
            if state >= AstEntryState::Typechecking {
                return Ok(CacheOp::Cached(()));
            }

            // Protect against cycles in the import graph.
            // unwrap(): we checked at the beginning of this function that the term is in the
            // cache.
            let _ = self
                .update_state(file_id, AstEntryState::Typechecking)
                .unwrap();

            // Ensure the initial typing context is properly initialized.
            self.populate_type_ctxt(slice.sources);
            self.with_mut(|slf| -> Result<(), AstCacheError<TypecheckError>> {
                // unwrap(): we checked at the beginning of this function that the AST cache has an
                // entry for `file_id`.
                let ast = slf.asts.get(&file_id).unwrap().ast;

                let mut resolver = AstResolver::new(slf.alloc, slf.asts, slice.reborrow());
                let type_ctxt = slf.type_ctxt.clone();
                let wildcards_map = measure_runtime!(
                    "runtime:type_check",
                    typecheck(slf.alloc, ast, type_ctxt, &mut resolver, initial_mode)?
                );
                slf.wildcards.insert(file_id, wildcards_map);

                Ok(())
            })?;

            // Typecheck dependencies (files imported by this file).
            if let Some(imports) = slice.import_data.imports.get(&file_id) {
                // Because we need to borrow `import_data` for typechecking, we need to release the
                // borrow by moving the content of `imports` somewhere else.
                //
                // We ignore non-Nickel imports, which aren't typechecked, and are currently not
                // even in the AST cache.
                let imports: Vec<_> = imports
                    .iter()
                    .filter_map(|tgt| {
                        if let InputFormat::Nickel = tgt.format {
                            Some(tgt.file_id)
                        } else {
                            None
                        }
                    })
                    .collect();

                for file_id in imports {
                    self.typecheck(slice.reborrow(), file_id, initial_mode)?;
                }
            }

            // unwrap(): we checked at the beginning of this function that the AST is in the
            // cache.
            let _ = self
                .update_state(file_id, AstEntryState::Typechecked)
                .unwrap();

            Ok(CacheOp::Done(()))
        }

        /// Typechecks the stdlib. This has to be public because it's used in benches. It probably
        /// does not have to be used for something else.
        pub fn typecheck_stdlib(
            &mut self,
            mut slice: CacheHubView<'_>,
        ) -> Result<CacheOp<()>, AstCacheError<TypecheckError>> {
            let mut ret = CacheOp::Cached(());
            self.populate_type_ctxt(slice.sources);

            for (_, stdlib_module_id) in slice.sources.stdlib_modules() {
                let result =
                    self.typecheck(slice.reborrow(), stdlib_module_id, TypecheckMode::Walk)?;

                if let CacheOp::Done(()) = result {
                    ret = CacheOp::Done(());
                }
            }

            Ok(ret)
        }

        /// Typechecks a file (if it wasn't already) and returns the inferred type, with type
        /// wildcards properly substituted.
        pub fn type_of(
            &mut self,
            mut slice: CacheHubView<'_>,
            file_id: FileId,
        ) -> Result<CacheOp<ast::typ::Type<'_>>, AstCacheError<TypecheckError>> {
            self.typecheck(slice.reborrow(), file_id, TypecheckMode::Walk)?;

            self.with_mut(|slf| {
                let ast = slf
                    .asts
                    .get(&file_id)
                    .ok_or(CacheError::IncompatibleState {
                        want: AstEntryState::Parsed,
                    })?
                    .ast;

                let mut resolver = AstResolver::new(slf.alloc, slf.asts, slice.reborrow());
                let type_ctxt = slf.type_ctxt.clone();

                let typ: Result<ast::typ::Type<'_>, _> = TryConvert::try_convert(
                    slf.alloc,
                    ast.apparent_type(slf.alloc, Some(&type_ctxt.type_env), Some(&mut resolver)),
                );

                let typ = typ.unwrap_or(ast::typ::TypeF::Dyn.into());

                // unwrap(): we ensured that the file is typechecked, thus its wildcards and its AST
                // must be populated
                let wildcards = slf.wildcards.get(&file_id).unwrap();

                Ok(CacheOp::Done(
                    typ.traverse(
                        slf.alloc,
                        &mut |ty: ast::typ::Type| -> Result<_, std::convert::Infallible> {
                            if let ast::typ::TypeF::Wildcard(id) = ty.typ {
                                Ok(wildcards
                                    .get(id)
                                    .cloned()
                                    .unwrap_or(ast::typ::Type::from(ast::typ::TypeF::Dyn)))
                            } else {
                                Ok(ty)
                            }
                        },
                        TraverseOrder::TopDown,
                    )
                    .unwrap(),
                ))
            })
        }

        /// If the type context hasn't been created yet, generate and cache the initial typing
        /// context from the list of `file_ids` corresponding to the standard library parts.
        /// Otherwise, do nothing.
        fn populate_type_ctxt(&mut self, sources: &SourceCache) {
            self.with_mut(|slf| {
                if !slf.type_ctxt.is_empty() {
                    return;
                }
                let stdlib_terms_vec: Vec<(StdlibModule, &'_ Ast<'_>)> = sources
                    .stdlib_modules()
                    .map(|(module, file_id)| {
                        let ast = slf.asts.get(&file_id).map(|entry| entry.ast);

                        (
                            module,
                            ast.expect("cache::ast_cache::AstCache::populate_type_ctxt(): can't build environment, stdlib not parsed")
                        )
                    })
                    .collect();

                *slf.type_ctxt = typecheck::mk_initial_ctxt(slf.alloc, stdlib_terms_vec).unwrap();
            });
        }

        /// Adds bindings to the typing environment with type [`ast::typ::TypeF::Dyn`], one per
        /// identifier in `idents`. Used to expose host-provided extras to the typechecker without
        /// committing to a more precise type.
        ///
        /// Ensures that the initial typing context is populated first, so the registrations are
        /// layered on top of stdlib and win on collision.
        pub fn add_dyn_type_bindings<I>(&mut self, sources: &SourceCache, idents: I)
        where
            I: IntoIterator<Item = crate::identifier::Ident>,
        {
            self.populate_type_ctxt(sources);
            self.with_mut(|slf| {
                for ident in idents {
                    slf.type_ctxt
                        .type_env
                        .insert(ident, typecheck::UnifType::concrete(ast::typ::TypeF::Dyn));
                }
            });
        }

        /// Adds a binding to the type environment. The bound term is identified by its file id
        /// `file_id`.
        pub fn add_type_binding(
            &mut self,
            mut slice: CacheHubView<'_>,
            id: LocIdent,
            file_id: FileId,
        ) -> Result<(), AstCacheError<std::convert::Infallible>> {
            self.with_mut(|slf| {
                let Some(entry) = slf.asts.get(&file_id) else {
                    return Err(CacheError::IncompatibleState {
                        want: AstEntryState::Parsed,
                    });
                };

                let ast = entry.ast;
                let mut resolver = AstResolver::new(slf.alloc, slf.asts, slice.reborrow());

                typecheck::env_add(
                    slf.alloc,
                    &mut slf.type_ctxt.type_env,
                    id,
                    ast,
                    &slf.type_ctxt.term_env,
                    &mut resolver,
                );
                //slf.asts.extend(resolver.new_asts.into_iter());

                slf.type_ctxt
                    .term_env
                    .0
                    .insert(id.ident(), (ast.clone(), slf.type_ctxt.term_env.clone()));
                Ok(())
            })?;

            Ok(())
        }

        /// Add the bindings of a record to the type environment. Ignore fields whose name are
        /// defined through interpolation.
        pub fn add_type_bindings(
            &mut self,
            pos_table: &PosTable,
            mut slice: CacheHubView<'_>,
            term: &NickelValue,
        ) -> Result<(), NotARecord> {
            self.with_mut(|slf| {
                // It's sad, but for now, we have to convert the term back to an AST to insert it in
                // the type environment.
                let ast = term.to_ast(slf.alloc, pos_table);
                let mut resolver = AstResolver::new(slf.alloc, slf.asts, slice.reborrow());

                typecheck::env_add_term(
                    slf.alloc,
                    &mut slf.type_ctxt.type_env,
                    ast,
                    &slf.type_ctxt.term_env,
                    &mut resolver,
                )
                .map_err(|_| NotARecord)
            })
        }
    }
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::*;

    #[test]
    fn normalize_rel() {
        assert_eq!(
            &normalize_rel_path(Path::new("../a/../b")),
            Path::new("../b")
        );
        assert_eq!(
            &normalize_rel_path(Path::new("../../a/../b")),
            Path::new("../../b")
        );
    }

    #[test]
    fn get_cached_source_with_relative_path() {
        let mut sources = SourceCache::new();
        let root_path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("nickel-test-rootdir");
        let path = SourcePath::Path(root_path.join("file.ncl"), super::InputFormat::Nickel);
        let file_id = sources.replace_string(path, "1".into());

        // This path should not exist on the host but should
        // match the in memory file that was set up in the cache
        let file = sources
            .get_or_add_file(
                root_path.join("subdir").join("..").join("file.ncl"),
                InputFormat::Nickel,
            )
            .expect("Missed cached file when pulling with relative path");
        assert_eq!(CacheOp::Cached(file_id), file);
    }

    #[test]
    fn close_file() {
        let mut sources = SourceCache::new();
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("closed.ncl");
        let source_path = SourcePath::Path(path.clone(), InputFormat::Nickel);
        sources.add_string(source_path.clone(), "1".to_string());
        sources
            .close_in_memory_file(path.clone(), InputFormat::Nickel)
            .unwrap();
        assert_eq!(
            sources
                .file_ids
                .get(&source_path)
                .map(|it| it.source)
                .unwrap(),
            SourceKind::MemoryClosed
        );

        // Since the closed file should be stale, id_or_new_timestamp_of should not return the
        // file ID for the closed file. Since in this case the file doesn't exist on the
        // filesystem, it should return an error.
        assert!(
            sources
                .id_or_new_timestamp_of(&path, InputFormat::Nickel)
                .is_err()
        );
    }
}//! Closurization of terms.
//!
//! During evaluation, variable substitution is done lazily through the help of
//! [the environment][crate::eval::Environment]. In consequence, the complete data required to
//! evaluate an expression further isn't only the expression itself (the term), but the current
//! environment as well. [crate::eval::Closure] is precisely a tuple of a term together with its
//! environment.
//!
//! We often need to store a closure back into a term (without relying on the environment):
//! typically, when we combine several operands (think merging or array concatenation), each with
//! its own environment. This is what we call closurization: wrap a closure back as a term. By
//! extension, several structures containing term can be closurized as well, which means to
//! closurize all the inner terms.

use crate::{
    eval::{
        Closure, Environment,
        cache::Cache,
        value::{Array, ArrayData, NickelValue, ValueContentRef},
    },
    term::{
        BindingType, RuntimeContract, Term,
        record::{Field, FieldDeps, RecordData, RecordDeps},
    },
};

/// Structures which can be packed together with their environment as a closure.
///
/// The typical implementer is [NickelValue], but structures containing terms can also be
/// closurizable, such as the contract case in a [crate::typ::Type], an array of terms, etc.
///
/// In those cases, the inner terms are closurized.
pub trait Closurize: Sized {
    /// Pack a closurizable together with its environment `env` as a closure.
    ///
    /// By default, this is just `self.closurize_as_btype(cache, env, BindingType::default())`.
    fn closurize<C: Cache>(self, cache: &mut C, env: Environment) -> Self {
        self.closurize_as_btype(cache, env, BindingType::default())
    }

    /// Pack a closurizable together with its environment as a closure and with the dependencies
    /// set according to the given binding type.
    /// An exception is made for constant terms, which should be left untouched (it's useless to to
    /// allocate a closure for them)
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Self;
}

impl Closurize for NickelValue {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> NickelValue {
        // There is no case where closurizing a constant term makes sense, because it's already
        // evaluated, it doesn't have any free variables and doesn't contain any unevaluated terms.
        // Even the merge of recursive records is able to handle non-closurized constant terms, so
        // we just return the original term.
        if self.is_constant() {
            return self;
        }

        // If the term is already a closure, we don't have to allocate a useless intermediate
        // closure. We just transfer the original cache index to the new environment. This is not
        // only an optimization: this is relied upon by recursive record merging when computing the
        // fixpoint.
        //
        // More specifically, the evaluation of a recursive record patches the environment of each
        // field with the indices recursively referring to the other fields of the record. `eval`
        // assumes that a recursive record field is either a constant or a `Term::Closure` whose
        // cache elements *immediately* contain the original unevaluated expression (both
        // properties are true after the first evaluation of a value through
        // `Term::Closurize(value)` and maintained when reverting elements before merging recursive
        // records).
        //
        // To maintain this invariant, `closurize` must NOT introduce an indirection through a
        // additional closure, such as transforming:
        //
        // ```
        // {foo = <closure@1>, bar = 1} | 1 <- 1 + bar
        // ```
        //
        // to:
        //
        // ```
        // {foo = <closure@2>, bar = 1} | 2 <- (<closure@1> | 1 <- 1 + bar)
        // ```
        //
        // In this case, the evaluation of the recursive records will patch the outer environment
        // instead of the inner one, giving:
        //
        // ```
        // {foo = <closure:2>, bar = 1} | 2 <- (<closure:1> | 1 <- 1 + bar), bar <- 1
        // ```
        //
        // Then, evaluating `foo` would unduly raise an unbound identifier error.
        let idx = match self.content_ref() {
            // If we just need a normal closure, and we find a normal closure inside the thunk, we
            // reuse it
            ValueContentRef::Thunk(thunk)
                if thunk.deps().is_empty() && matches!(btype, BindingType::Normal) =>
            {
                self.try_into_thunk().unwrap()
            }
            ValueContentRef::Term(Term::Var(id)) if id.is_generated() => {
                let id = *id;
                // Albeit we should always find a generated variable in the environment,
                // `env.get` is technically fallible, while this method is not. We thus wrap a
                // potential error in a new closure which will propagate the unbound
                // identifier error upon evaluation.
                env.get(&id.ident()).cloned().unwrap_or_else(move || {
                    debug_assert!(false, "missing generated variable {id} in environment");
                    cache.add(Closure { value: self, env }, btype)
                })
            }
            content => {
                // It's suspicious to wrap a closure with existing dependencies in a new closure,
                // although I'm not sure it would actually break anything. We panic in debug mode
                // to catch this case.
                debug_assert!(
                    !matches!((content, &btype), (ValueContentRef::Thunk(thunk), BindingType::Revertible(_)) if !thunk.deps().is_empty()),
                    "wrapping a closure with non-empty deps in a new closure with different deps"
                );

                cache.add(Closure { value: self, env }, btype)
            }
        };

        idx.into()
    }
}

impl Closurize for RuntimeContract {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> RuntimeContract {
        self.map_contract(|ctr| ctr.closurize_as_btype(cache, env, btype.clone()))
    }
}

impl Closurize for Vec<RuntimeContract> {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Vec<RuntimeContract> {
        self.into_iter()
            .map(|pending_contract| {
                pending_contract.closurize_as_btype(cache, env.clone(), btype.clone())
            })
            .collect()
    }
}

impl Closurize for Field {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Field {
        let pending_contracts =
            self.pending_contracts
                .closurize_as_btype(cache, env.clone(), btype.clone());
        let value = self
            .value
            .map(|value| value.closurize_as_btype(cache, env, btype));

        Field {
            metadata: self.metadata,
            value,
            pending_contracts,
        }
    }
}

impl Closurize for Array {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Self {
        self.into_iter()
            .map(|val| {
                if should_share(&val) {
                    val.closurize_as_btype(cache, env.clone(), btype.clone())
                } else {
                    val
                }
            })
            .collect()
    }
}

// Closurize an array together with its pending contracts
impl Closurize for ArrayData {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Self {
        let pending_contracts =
            self.pending_contracts
                .closurize_as_btype(cache, env.clone(), btype.clone());

        ArrayData {
            array: self
                .array
                .closurize_as_btype(cache, env.clone(), btype.clone()),
            pending_contracts,
        }
    }
}

impl Closurize for RecordData {
    fn closurize_as_btype<C: Cache>(
        self,
        cache: &mut C,
        env: Environment,
        btype: BindingType,
    ) -> Self {
        // We don't closurize the sealed tail, if any, because the underlying term is a private
        // field and is supposed to be already closurized.
        // TODO: should we change the type of SealedTail.term to CacheIndex to reflect that?
        RecordData {
            fields: self
                .fields
                .into_iter()
                .map(|(id, field)| {
                    (
                        id,
                        field.closurize_as_btype(cache, env.clone(), btype.clone()),
                    )
                })
                .collect(),
            ..self
        }
    }
}

/// Decides is an expression is worth being wrapped in a thunk. This is almost the same as asking
/// if the expression is a weak head normal form, in which case it's already evaluated and doesn't
/// need to be cached, but with some subtle differences.
pub fn should_share(value: &NickelValue) -> bool {
    match value.content_ref() {
        ValueContentRef::Term(Term::Var(_) | Term::Fun(_)) => false,
        ValueContentRef::Term(_)
        // In general types are WHNF that shouldn't be shared, but currently the have an additional
        // field storing their conversion to a contract. In order to take advantage of this local
        // cache, we need to share them.
        | ValueContentRef::Type(_) => true,
        ValueContentRef::Null
        | ValueContentRef::Bool(_)
        // Now that arrays and records have proper constructors and are assumed to be closurized,
        // they are effectively WHNFs (they used to represent both arrays and records, and the
        // equivalent of today's `Term::Closurize(array_or_record)`, the latter not being a WHNF)
        | ValueContentRef::Array(_)
        | ValueContentRef::Record(_)
        | ValueContentRef::Number(_)
        | ValueContentRef::String(_)
        | ValueContentRef::Label(_)
        | ValueContentRef::SealingKey(_)
        | ValueContentRef::ForeignId(_)
        | ValueContentRef::Thunk(_)
        // a custom contract is a function, and is thus a WHNF
        | ValueContentRef::CustomContract(_) => false,
        ValueContentRef::EnumVariant(enum_variant) => enum_variant.arg.is_some(),
    }
}

/// Closurize all the inner terms of a recursive record, including pending contracts and
/// dynamically defined fields.
pub fn closurize_rec_record<C: Cache>(
    cache: &mut C,
    data: RecordData,
    dyn_fields: Vec<(NickelValue, Field)>,
    deps: Option<RecordDeps>,
    env: Environment,
) -> (RecordData, Vec<(NickelValue, Field)>) {
    let fields = data
        .fields
        .into_iter()
        .map(|(id, field)| {
            let field_deps = deps
                .as_ref()
                .and_then(|deps| deps.stat_fields.get(&id.ident()))
                .cloned();

            (
                id,
                field.closurize_as_btype(cache, env.clone(), mk_binding_type(field_deps.clone())),
            )
        })
        .collect();

    let dyn_fields = dyn_fields
        .into_iter()
        .enumerate()
        .map(|(index, (id_t, field))| {
            let field_deps = deps
                .as_ref()
                .and_then(|deps| deps.dyn_fields.get(index))
                .cloned();
            // Identifier expressions aren't currently allowed to recursively depend on another
            // field, so we closurize them as normal bindings.
            (
                id_t.closurize(cache, env.clone()),
                field.closurize_as_btype(cache, env.clone(), mk_binding_type(field_deps.clone())),
            )
        })
        .collect();

    let data = RecordData { fields, ..data };

    (data, dyn_fields)
}

fn mk_binding_type(field_deps: Option<FieldDeps>) -> BindingType {
    // If the fields has an empty set of dependencies, we can eschew the useless introduction of a
    // revertible element. Note that `field_deps` being `None` doesn't mean "empty dependencies"
    // but rather that the dependencies haven't been computed. In the latter case, we must be
    // conservative and assume the field can depend on any other field.
    let is_non_rec = field_deps
        .as_ref()
        .map(FieldDeps::is_empty)
        .unwrap_or(false);
    if is_non_rec {
        BindingType::Normal
    } else {
        BindingType::Revertible(field_deps.unwrap_or(FieldDeps::Unknown))
    }
}//! Deserialization of an evaluated program to plain Rust types.

use malachite::base::{num::conversion::traits::RoundingFrom, rounding_modes::RoundingMode};
use std::{ffi::OsString, io::Cursor, iter::ExactSizeIterator};

use serde::de::{
    Deserialize, DeserializeSeed, EnumAccess, IntoDeserializer, MapAccess, SeqAccess,
    VariantAccess, Visitor,
};

use crate::{
    error,
    eval::{
        cache::CacheImpl,
        value::{
            Array, ArrayData, Container, InlineValue, NickelValue, RecordData, ValueContent,
            ValueContentRef,
        },
    },
    identifier::LocIdent,
    program::{Program, ProgramBuilder},
    term::{IndexMap, record::Field},
};

macro_rules! deserialize_number {
    ($method:ident, $type:tt, $visit:ident) => {
        fn $method<V>(self, visitor: V) -> Result<V::Value, Self::Error>
        where
            V: Visitor<'de>,
        {
            match self.content_ref() {
                ValueContentRef::Number(n) => {
                    return visitor.$visit($type::rounding_from(n, RoundingMode::Nearest).0);
                }
                _ => Err(RustDeserializationError::InvalidType {
                    expected: "Number".to_string(),
                    occurred: self.type_of().unwrap_or("Other").to_owned(),
                }),
            }
        }
    };
}

// TODO: revisit this lint once the large errors have been dealt with.
#[allow(clippy::large_enum_variant)]
pub enum EvalOrDeserError {
    Nickel {
        error: error::Error,
        files: Option<crate::files::Files>,
    },
    Deser(RustDeserializationError),
}

impl std::error::Error for EvalOrDeserError {}

impl std::fmt::Debug for EvalOrDeserError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Nickel { error, files } => {
                let filenames = files.as_ref().map(|f| f.filenames().collect::<Vec<_>>());
                f.debug_struct("Nickel")
                    .field("error", error)
                    .field("files", &filenames)
                    .finish()
            }
            Self::Deser(arg0) => f.debug_tuple("Deser").field(arg0).finish(),
        }
    }
}

impl std::fmt::Display for EvalOrDeserError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            EvalOrDeserError::Nickel { error, files } => {
                let mut files = files.clone().unwrap_or_default();
                write!(
                    f,
                    "{}",
                    crate::error::report::report_as_str(
                        &mut files,
                        error.clone(),
                        error::report::ColorOpt::Never
                    )
                )
            }
            EvalOrDeserError::Deser(e) => e.fmt(f),
        }
    }
}

impl EvalOrDeserError {
    fn new<E>(error: E, files: crate::files::Files) -> Self
    where
        E: Into<error::Error>,
    {
        Self::Nickel {
            error: error.into(),
            files: Some(files),
        }
    }
}

impl<E: Into<error::Error>> From<E> for EvalOrDeserError {
    fn from(err: E) -> Self {
        Self::Nickel {
            error: err.into(),
            files: None,
        }
    }
}

impl From<RustDeserializationError> for EvalOrDeserError {
    fn from(err: RustDeserializationError) -> Self {
        Self::Deser(err)
    }
}

fn from_builder<'a, T>(builder: ProgramBuilder) -> Result<T, EvalOrDeserError>
where
    T: serde::Deserialize<'a>,
{
    let mut program: Program<CacheImpl> = builder.with_trace(std::io::stderr()).build()?;

    Ok(T::deserialize(program.eval_full_for_export().map_err(
        |err| EvalOrDeserError::new(err, program.files()),
    )?)?)
}

pub fn from_str<'a, T>(s: &'a str) -> Result<T, EvalOrDeserError>
where
    T: serde::Deserialize<'a>,
{
    from_builder(ProgramBuilder::new().add_source_string(s.to_owned(), "string"))
}

pub fn from_slice<'a, T>(v: &'a [u8]) -> Result<T, EvalOrDeserError>
where
    T: serde::Deserialize<'a>,
{
    from_builder(ProgramBuilder::new().add_source(Cursor::new(v.to_owned()), "slice"))
}

pub fn from_path<T>(path: impl Into<OsString>) -> Result<T, EvalOrDeserError>
where
    T: serde::de::DeserializeOwned,
{
    from_builder(ProgramBuilder::new().add_path(path))
}

pub fn from_reader<R, T>(rdr: R) -> Result<T, EvalOrDeserError>
where
    R: std::io::Read + 'static,
    T: serde::de::DeserializeOwned,
{
    from_builder(ProgramBuilder::new().add_source(rdr, "reader"))
}

/// An error occurred during deserialization to Rust.
#[derive(Debug, PartialEq, Eq, Clone)]
pub enum RustDeserializationError {
    InvalidType { expected: String, occurred: String },
    MissingValue,
    EmptyRecordField,
    UnimplementedType { occurred: String },
    InvalidRecordLength(usize),
    InvalidArrayLength(usize),
    Other(String),
}

impl<'de> serde::Deserializer<'de> for NickelValue {
    type Error = RustDeserializationError;

    /// Catch-all deserialization
    fn deserialize_any<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::Null(_) => visitor.visit_unit(),
            ValueContent::Bool(lens) => visitor.visit_bool(lens.take()),
            ValueContent::Number(lens) => {
                visitor.visit_f64(f64::rounding_from(lens.take(), RoundingMode::Nearest).0)
            }
            ValueContent::String(lens) => visitor.visit_string(lens.take().into_inner()),
            ValueContent::EnumVariant(lens) => {
                let enum_variant = lens.take();

                visitor.visit_enum(EnumDeserializer {
                    tag: enum_variant.tag.into_label(),
                    value: enum_variant.arg,
                })
            }
            ValueContent::Record(lens) => visit_record_container(lens.take(), visitor),
            ValueContent::Array(lens) => visit_array_container(lens.take(), visitor),
            lens => Err(RustDeserializationError::UnimplementedType {
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    deserialize_number!(deserialize_i8, i8, visit_i8);
    deserialize_number!(deserialize_i16, i16, visit_i16);
    deserialize_number!(deserialize_i32, i32, visit_i32);
    deserialize_number!(deserialize_i64, i64, visit_i64);
    deserialize_number!(deserialize_i128, i128, visit_i128);
    deserialize_number!(deserialize_u8, u8, visit_u8);
    deserialize_number!(deserialize_u16, u16, visit_u16);
    deserialize_number!(deserialize_u32, u32, visit_u32);
    deserialize_number!(deserialize_u64, u64, visit_u64);
    deserialize_number!(deserialize_u128, u128, visit_u128);
    deserialize_number!(deserialize_f32, f32, visit_f32);
    deserialize_number!(deserialize_f64, f64, visit_f64);

    /// Deserialize nullable field.
    fn deserialize_option<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        if self.is_null() {
            visitor.visit_none()
        } else {
            visitor.visit_some(self)
        }
    }

    /// deserialize an enum variant or a record with a single item.
    fn deserialize_enum<V>(
        self,
        _name: &str,
        _variants: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        let (tag, arg) = match self.content() {
            ValueContent::EnumVariant(lens) => {
                let enum_var = lens.take();

                (enum_var.tag.into_label(), enum_var.arg)
            }
            ValueContent::Record(lens) => {
                let record = lens.take().unwrap_or_alloc();

                let mut iter = record.fields.into_iter();
                let (tag, arg) = match iter.next() {
                    Some((id, Field { value, .. })) => (id, value),
                    None => {
                        return Err(RustDeserializationError::InvalidType {
                            expected: "Record with single key".to_string(),
                            occurred: "Record without keys".to_string(),
                        });
                    }
                };

                if iter.next().is_some() {
                    return Err(RustDeserializationError::InvalidType {
                        expected: "Record with single key".to_string(),
                        occurred: "Record with multiple keys".to_string(),
                    });
                }

                (tag.into_label(), arg)
            }
            lens => {
                let value = lens.restore();

                return Err(RustDeserializationError::InvalidType {
                    expected: "Enum or Record".to_string(),
                    occurred: value.type_of().unwrap_or("Other").to_owned(),
                });
            }
        };

        visitor.visit_enum(EnumDeserializer { tag, value: arg })
    }

    /// Deserialize pass-through tuples/structs.
    fn deserialize_newtype_struct<V>(
        self,
        _name: &'static str,
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        visitor.visit_newtype_struct(self)
    }

    /// Deserialize a boolean value.
    fn deserialize_bool<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.as_inline() {
            Some(InlineValue::True) => visitor.visit_bool(true),
            Some(InlineValue::False) => visitor.visit_bool(false),
            _ => Err(RustDeserializationError::InvalidType {
                expected: "Bool".to_string(),
                occurred: self.type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize a string as a char.
    fn deserialize_char<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_string(visitor)
    }

    /// Deserialize a string (borrowed).
    fn deserialize_str<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.as_string() {
            Some(s) => visitor.visit_str(s),
            _ => Err(RustDeserializationError::InvalidType {
                expected: "String".to_string(),
                occurred: self.type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize a string (owned).
    fn deserialize_string<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::String(lens) => visitor.visit_string(lens.take().into_inner()),
            lens => Err(RustDeserializationError::InvalidType {
                expected: "String".to_string(),
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize a string value or an array as bytes.
    fn deserialize_bytes<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_byte_buf(visitor)
    }

    /// Deserialize a string value or an array as bytes.
    fn deserialize_byte_buf<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::String(lens) => visitor.visit_string(lens.take().into_inner()),
            ValueContent::Array(lens) => visit_array(lens.take().unwrap_or_alloc().array, visitor),
            lens => {
                let value = lens.restore();

                Err(RustDeserializationError::InvalidType {
                    expected: "Str or Array".to_string(),
                    occurred: value.type_of().unwrap_or("Other").to_owned(),
                })
            }
        }
    }

    /// Deserialize `null` as `()`.
    fn deserialize_unit<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.as_inline() {
            Some(InlineValue::Null) => visitor.visit_unit(),
            _ => Err(RustDeserializationError::InvalidType {
                expected: "Null".to_string(),
                occurred: self.type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize `null` as a unit struct.
    fn deserialize_unit_struct<V>(
        self,
        _name: &'static str,
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_unit(visitor)
    }

    /// Deserialize an array as `Vec<T>`.
    fn deserialize_seq<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::Array(lens) => visit_array_container(lens.take(), visitor),
            lens => Err(RustDeserializationError::InvalidType {
                expected: "Array".to_string(),
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize an array as a tuple.
    fn deserialize_tuple<V>(self, _len: usize, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_seq(visitor)
    }

    /// Deserialize an array as a tuple struct.
    fn deserialize_tuple_struct<V>(
        self,
        _name: &'static str,
        _len: usize,
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_seq(visitor)
    }

    /// Deserialize a record as a map.
    fn deserialize_map<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::Record(lens) => visit_record_container(lens.take(), visitor),
            lens => Err(RustDeserializationError::InvalidType {
                expected: "Record".to_string(),
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
        }
    }

    /// Deserialize a record as a struct.
    fn deserialize_struct<V>(
        self,
        _name: &'static str,
        _fields: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.content() {
            ValueContent::Array(lens) => visit_array_container(lens.take(), visitor),
            ValueContent::Record(lens) => visit_record_container(lens.take(), visitor),
            lens => {
                let value = lens.restore();

                Err(RustDeserializationError::InvalidType {
                    expected: "Record".to_string(),
                    occurred: value.type_of().unwrap_or("Other").to_owned(),
                })
            }
        }
    }

    /// Deserialize an identifier as a string.
    fn deserialize_identifier<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        self.deserialize_string(visitor)
    }

    fn deserialize_ignored_any<V>(self, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        drop(self);
        visitor.visit_unit()
    }
}

struct ArrayDeserializer {
    iter: <Array as IntoIterator>::IntoIter,
}

impl ArrayDeserializer {
    fn new(array: Array) -> Self {
        ArrayDeserializer {
            iter: array.into_iter(),
        }
    }
}

impl<'de> SeqAccess<'de> for ArrayDeserializer {
    type Error = RustDeserializationError;

    fn next_element_seed<T>(&mut self, seed: T) -> Result<Option<T::Value>, Self::Error>
    where
        T: DeserializeSeed<'de>,
    {
        match self.iter.next() {
            Some(value) => seed.deserialize(value).map(Some),
            None => Ok(None),
        }
    }

    fn size_hint(&self) -> Option<usize> {
        match self.iter.size_hint() {
            (lower, Some(upper)) if lower == upper => Some(upper),
            _ => None,
        }
    }
}

fn visit_array_container<'de, V>(
    container: Container<ArrayData>,
    visitor: V,
) -> Result<V::Value, RustDeserializationError>
where
    V: Visitor<'de>,
{
    visit_array(container.unwrap_or_alloc().array, visitor)
}

fn visit_array<'de, V>(array: Array, visitor: V) -> Result<V::Value, RustDeserializationError>
where
    V: Visitor<'de>,
{
    let len = array.len();
    let mut deserializer = ArrayDeserializer::new(array);
    let seq = visitor.visit_seq(&mut deserializer)?;
    if deserializer.iter.next().is_none() {
        Ok(seq)
    } else {
        Err(RustDeserializationError::InvalidArrayLength(len))
    }
}

struct RecordDeserializer {
    iter: <IndexMap<LocIdent, Field> as IntoIterator>::IntoIter,
    field: Option<Field>,
}

impl RecordDeserializer {
    fn new(map: IndexMap<LocIdent, Field>) -> Self {
        RecordDeserializer {
            iter: map.into_iter(),
            field: None,
        }
    }
}

impl<'de> MapAccess<'de> for RecordDeserializer {
    type Error = RustDeserializationError;

    fn next_key_seed<T>(&mut self, seed: T) -> Result<Option<T::Value>, Self::Error>
    where
        T: DeserializeSeed<'de>,
    {
        match self.iter.next() {
            Some((key, value)) => {
                self.field = Some(value);
                seed.deserialize(key.label().into_deserializer()).map(Some)
            }
            None => Ok(None),
        }
    }

    fn next_value_seed<T>(&mut self, seed: T) -> Result<T::Value, Self::Error>
    where
        T: DeserializeSeed<'de>,
    {
        match self.field.take() {
            Some(Field {
                value: Some(value), ..
            }) => seed.deserialize(value),
            // TODO: what to do about fields without definition is not totally clear (should an
            // empty optional be considered as `None` or just disappear from the serialization?
            // Probably the former). For now, we implement the same behavior as before the
            // implementation of RFC005, which is to always fail on a field without definition.
            //
            // This should be relaxed in the future.
            Some(Field { value: None, .. }) => Err(RustDeserializationError::EmptyRecordField),
            _ => Err(RustDeserializationError::MissingValue),
        }
    }

    fn size_hint(&self) -> Option<usize> {
        match self.iter.size_hint() {
            (lower, Some(upper)) if lower == upper => Some(upper),
            _ => None,
        }
    }
}

fn visit_record_container<'de, V>(
    container: Container<RecordData>,
    visitor: V,
) -> Result<V::Value, RustDeserializationError>
where
    V: Visitor<'de>,
{
    visit_record(container.unwrap_or_alloc().fields, visitor)
}

fn visit_record<'de, V>(
    record: IndexMap<LocIdent, Field>,
    visitor: V,
) -> Result<V::Value, RustDeserializationError>
where
    V: Visitor<'de>,
{
    let len = record.len();
    let mut deserializer = RecordDeserializer::new(record);
    let map = visitor.visit_map(&mut deserializer)?;
    let remaining = deserializer.iter.len();
    if remaining == 0 {
        Ok(map)
    } else {
        Err(RustDeserializationError::InvalidRecordLength(len))
    }
}

struct VariantDeserializer {
    value: Option<NickelValue>,
}

impl<'de> VariantAccess<'de> for VariantDeserializer {
    type Error = RustDeserializationError;

    fn unit_variant(self) -> Result<(), Self::Error> {
        match self.value {
            Some(value) => Deserialize::deserialize(value),
            None => Ok(()),
        }
    }

    fn newtype_variant_seed<T>(self, seed: T) -> Result<T::Value, Self::Error>
    where
        T: DeserializeSeed<'de>,
    {
        match self.value {
            Some(value) => seed.deserialize(value),
            None => Err(RustDeserializationError::MissingValue),
        }
    }

    fn tuple_variant<V>(self, _len: usize, visitor: V) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.value.map(|v| v.content()) {
            Some(ValueContent::Array(lens)) => {
                let v = lens.take().unwrap_or_alloc().array;

                if v.is_empty() {
                    visitor.visit_unit()
                } else {
                    visit_array(v, visitor)
                }
            }
            Some(lens) => Err(RustDeserializationError::InvalidType {
                expected: "Array variant".to_string(),
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
            None => Err(RustDeserializationError::MissingValue),
        }
    }

    fn struct_variant<V>(
        self,
        _fields: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, Self::Error>
    where
        V: Visitor<'de>,
    {
        match self.value.map(|v| v.content()) {
            Some(ValueContent::Record(lens)) => visit_record_container(lens.take(), visitor),
            Some(lens) => Err(RustDeserializationError::InvalidType {
                expected: "Array variant".to_string(),
                occurred: lens.restore().type_of().unwrap_or("Other").to_owned(),
            }),
            None => Err(RustDeserializationError::MissingValue),
        }
    }
}

struct EnumDeserializer {
    tag: String,
    value: Option<NickelValue>,
}

impl<'de> EnumAccess<'de> for EnumDeserializer {
    type Error = RustDeserializationError;
    type Variant = VariantDeserializer;

    fn variant_seed<V>(self, seed: V) -> Result<(V::Value, VariantDeserializer), Self::Error>
    where
        V: DeserializeSeed<'de>,
    {
        let variant = self.tag.into_deserializer();
        let visitor = VariantDeserializer { value: self.value };
        seed.deserialize(variant).map(|v| (v, visitor))
    }
}

impl std::fmt::Display for RustDeserializationError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            RustDeserializationError::InvalidType { expected, occurred } => {
                write!(f, "invalid type: {occurred}, expected: {expected}")
            }
            RustDeserializationError::MissingValue => write!(f, "missing value"),
            RustDeserializationError::EmptyRecordField => write!(f, "empty Metavalue"),
            RustDeserializationError::InvalidRecordLength(len) => {
                write!(f, "invalid record length, expected {len}")
            }
            RustDeserializationError::InvalidArrayLength(len) => {
                write!(f, "invalid array length, expected {len}")
            }
            RustDeserializationError::UnimplementedType { occurred } => {
                write!(f, "unimplemented conversion from type: {occurred}")
            }
            RustDeserializationError::Other(err) => write!(f, "{err}"),
        }
    }
}

impl std::error::Error for RustDeserializationError {}

impl serde::de::Error for RustDeserializationError {
    fn custom<T>(msg: T) -> Self
    where
        T: std::fmt::Display,
    {
        RustDeserializationError::Other(msg.to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::{from_path, from_reader, from_slice, from_str};
    use std::io::Cursor;

    use nickel_lang_utils::{
        nickel_lang_core::{
            deserialize::RustDeserializationError, eval::value::NickelValue,
            program::ProgramBuilder,
        },
        test_program::TestProgram,
    };
    use serde::Deserialize;

    fn eval(source: &str) -> NickelValue {
        let mut program: TestProgram = ProgramBuilder::new()
            .add_source_string(source.to_owned(), "source")
            .with_trace(std::io::stderr())
            .build()
            .expect("program shouldn't fail");
        program.eval_full().expect("evaluation shouldn't fail")
    }

    #[test]
    fn rust_deserialize_struct_with_fields() {
        #[derive(Debug, PartialEq, Deserialize)]
        #[serde(rename_all = "lowercase")]
        enum E {
            Foo,
            Bar,
        }

        #[derive(Debug, PartialEq, Deserialize)]
        #[serde(rename_all = "lowercase")]
        enum H {
            Foo(u16),
            Bar(String),
        }

        #[derive(Debug, PartialEq, Deserialize)]
        struct A {
            a: f64,
            b: String,
            c: (),
            d: bool,
            e: E,
            f: Option<bool>,
            g: i16,
            h: H,
        }

        assert_eq!(
            A::deserialize(eval(
                r#"{ a = 10, b = "test string", c = null, d = true, e = 'foo, f = null,
                g = -10, h = { bar = "some other string" } }"#
            ))
            .expect("deserialization shouldn't fail"),
            A {
                a: 10.0,
                b: "test string".to_string(),
                c: (),
                d: true,
                e: E::Foo,
                f: None,
                g: -10,
                h: H::Bar("some other string".to_string())
            }
        )
    }

    #[test]
    fn rust_deserialize_array_of_numbers() {
        assert_eq!(
            Vec::<f64>::deserialize(eval(r#"[1, 2, 3, 4]"#))
                .expect("deserialization shouldn't fail"),
            vec![1.0, 2.0, 3.0, 4.0]
        )
    }

    #[test]
    fn rust_deserialize_fail_non_data() {
        #[derive(Debug, PartialEq, Deserialize)]
        struct A;

        assert_eq!(
            A::deserialize(eval(r#"fun a b => a + b"#)),
            Err(RustDeserializationError::InvalidType {
                expected: "Null".to_string(),
                occurred: "Function".to_string()
            })
        )
    }

    #[test]
    fn rust_deserialize_ignore_annotation() {
        #[derive(Debug, PartialEq, Deserialize)]
        struct A {
            a: f64,
        }

        assert_eq!(
            A::deserialize(eval(r#"{ a = (10 | Number) }"#))
                .expect("deserialization shouldn't fail"),
            A { a: 10.0 }
        )
    }

    #[test]
    fn rust_deserialize_wrappers() {
        #[derive(Debug, Clone, PartialEq, Deserialize)]
        struct A {
            a: f64,
            b: Vec<String>,
        }

        let a = A {
            a: 10.0,
            b: vec!["a".into(), "b".into()],
        };

        assert_eq!(
            from_str::<A>(r#"{ a = (10 | Number), b = ["a", "b"] }"#).unwrap(),
            a.clone()
        );

        assert_eq!(
            from_slice::<A>(br#"{ a = (10 | Number), b = ["a", "b"] }"#).unwrap(),
            a.clone()
        );

        assert_eq!(
            from_reader::<_, A>(Cursor::new(r#"{ a = (10 | Number), b = ["a", "b"] }"#)).unwrap(),
            a.clone()
        );

        assert_eq!(
            from_reader::<_, A>(Cursor::new(br#"{ a = (10 | Number), b = ["a", "b"] }"#)).unwrap(),
            a.clone()
        );

        assert_eq!(
            from_path::<f64>(
                nickel_lang_utils::project_root::project_root()
                    .join("examples/fibonacci/fibonacci.ncl")
            )
            .unwrap(),
            55.0
        );

        assert!(from_str::<String>("will not parse").is_err());
        assert!(from_str::<String>("1 | String").is_err());
    }
}//! An environment for storing variables with scopes.
use std::collections::HashMap;
use std::hash::Hash;
use std::iter::FromIterator;
use std::rc::Rc;

use crate::metrics::{increment, sample};

/// An environment as a linked-list of hashmaps.
///
/// Each node of the linked-list corresponds to what is called
/// "a layer", where only the current layer can be modified, the
/// previous ones are only accessible for lookup.
///
/// For the generic parameters, `K` is the type for the environment
/// keys, and `V` are their value.
///
/// The linked list is composed of the current layer and the previous layers.
/// The current layer is stored as an `Rc<Hashmap>`.
///
/// Insertions are made by "split-on-write": if the current layer has no other
/// references, it is mutated. If it has other references, the current layer is
/// pushed down as the new "previous" layer, and a new layer is started.
#[derive(Debug, PartialEq)]
pub struct Environment<K: Hash + Eq, V: PartialEq> {
    current: Rc<HashMap<K, V>>,
    previous: Option<Rc<Environment<K, V>>>,
}

impl<K: Hash + Eq, V: PartialEq> Clone for Environment<K, V> {
    /// Clone has to create a new environment, while ensuring that previous
    /// defined layers are accessible but not modifiable anymore.
    fn clone(&self) -> Self {
        increment!("Environment::clone");
        Self {
            current: self.current.clone(),
            previous: self.previous.clone(),
        }
    }
}

impl<K: Hash + Eq, V: PartialEq> Default for Environment<K, V> {
    fn default() -> Self {
        Self {
            current: Rc::new(HashMap::new()),
            previous: None,
        }
    }
}

impl<K: Hash + Eq, V: PartialEq> Environment<K, V> {
    /// Creates a new empty Environment.
    pub fn new() -> Self {
        Self::default()
    }

    /// Inserts a key-value pair into the Environment.
    pub fn insert(&mut self, key: K, value: V) {
        increment!("Environment::insert");
        match Rc::get_mut(&mut self.current) {
            Some(cur) => {
                cur.insert(key, value);
            }
            None => {
                let mut new = HashMap::new();
                new.insert(key, value);
                self.set_current(new);
            }
        }
    }

    /// Tries to find the value of a key in the Environment.
    pub fn get(&self, key: &K) -> Option<&V> {
        increment!("Environment::get");

        let mut layer_count = 0;
        // See https://github.com/rust-lang/rust-clippy/issues/15987.
        #[allow(clippy::let_and_return)]
        let result = self.iter_layers().find_map(|hmap| {
            sample!("Environment.hashmap_size_get", hmap.len() as f64);
            layer_count += 1;
            hmap.get(key)
        });

        sample!("Environment.get_layers_traversed", layer_count as f64);
        result
    }

    /// Creates an iterator that visits all layers from the most recent one to the oldest.
    /// The element iterator type is `Rc<HashMap<K, V>>`.
    pub fn iter_layers(&self) -> EnvLayerIter<'_, K, V> {
        EnvLayerIter { env: Some(self) }
    }

    /// Creates an iterator that visits all elements from the Environment, from the oldest layer to
    /// the most recent one. It uses this order, so calling `collect` on this iterator to create a
    /// hashmap would have the same values as the Environment. The element iterator type is `(&'env
    /// K, &'env V)`, with `'env` being the lifetime of the Environment.
    pub fn iter_elems(&self) -> impl Iterator<Item = (&K, &V)> {
        let env: Vec<&HashMap<K, V>> = self.iter_layers().collect();
        env.into_iter().rev().flatten()
    }

    /// Checks quickly if two environments are obviously equal (when their components are
    /// physically equal as pointers or obviously equal such as being both empty).
    pub(crate) fn ptr_eq(this: &Self, that: &Self) -> bool {
        let prev_layers_eq = match (&this.previous, &that.previous) {
            (Some(ptr_this), Some(ptr_that)) => Rc::ptr_eq(ptr_this, ptr_that),
            (None, None) => true,
            _ => false,
        };

        let curr_layers_eq = (this.current.is_empty() && that.current.is_empty())
            || Rc::ptr_eq(&this.current, &that.current);

        prev_layers_eq && curr_layers_eq
    }

    /// Returns `true` if this environment is empty, that is if the current layer is empty and
    /// there's no previous layer.
    pub fn is_empty(&self) -> bool {
        self.current.is_empty() && self.previous.is_none()
    }

    /// Sets a new value for the current hashmap, pushing the old "current" value
    /// down the chain.
    fn set_current(&mut self, new_current: HashMap<K, V>) {
        let old_current = std::mem::replace(&mut self.current, Rc::new(new_current));
        if !old_current.is_empty() {
            self.previous = Some(Rc::new(Environment {
                current: old_current,
                previous: self.previous.clone(),
            }));
        }
    }
}

impl<K: Hash + Eq, V: PartialEq> FromIterator<(K, V)> for Environment<K, V> {
    fn from_iter<T: IntoIterator<Item = (K, V)>>(iter: T) -> Self {
        Self {
            current: Rc::new(HashMap::from_iter(iter)),
            previous: None,
        }
    }
}

impl<K: Hash + Eq, V: PartialEq> Extend<(K, V)> for Environment<K, V> {
    fn extend<T: IntoIterator<Item = (K, V)>>(&mut self, iter: T) {
        // if can mut. borrow current, then we just extend, otherwise it means
        // it was cloned, and we recreate a new map from iter for current
        match Rc::get_mut(&mut self.current) {
            Some(current) => current.extend(iter),
            None => {
                self.set_current(HashMap::from_iter(iter));
            }
        }
    }
}

/// An iterator over the layers of `Environment`.
///
/// Created by the [`iter_layers`] method on [`Environment`].
///
/// [`iter_layers`]: Environment::iter_layers
///
pub struct EnvLayerIter<'a, K: 'a + Hash + Eq, V: 'a + PartialEq> {
    env: Option<&'a Environment<K, V>>,
}

impl<'a, K: 'a + Hash + Eq, V: 'a + PartialEq> Iterator for EnvLayerIter<'a, K, V> {
    type Item = &'a HashMap<K, V>;

    fn next(&mut self) -> Option<Self::Item> {
        self.env.map(|env| {
            let res = &*env.current;
            self.env = env.previous.as_deref();
            res
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    impl<K: Hash + Eq, V: PartialEq> Environment<K, V> {
        pub fn depth(&self) -> usize {
            1 + self.previous.as_ref().map_or(0, |p| p.depth())
        }
    }

    #[test]
    fn test_env_base() {
        let mut env_base = Environment::new();
        env_base.insert(1, 'a');
        assert_eq!(env_base.get(&1), Some(&'a'));
        assert_eq!(env_base.get(&5), None);
        assert_eq!(env_base.depth(), 1);
    }

    #[test]
    fn test_clone() {
        let mut env_base = Environment::new();
        env_base.insert(1, 'a');

        let mut env2 = env_base.clone();
        env2.insert(2, 'b');
        assert_eq!(env2.get(&1), Some(&'a'));
        assert_eq!(env2.get(&2), Some(&'b'));
        env_base.insert(3, 'c');
        assert_eq!(env2.get(&3), None);
        assert_eq!(env_base.get(&3), Some(&'c'));
        env_base.insert(2, 'z');
        assert_eq!(env_base.get(&2), Some(&'z'));

        assert_eq!(env_base.depth(), 2);
        assert_eq!(env2.depth(), 2);
    }

    #[test]
    fn test_deepness() {
        let mut env_base = Environment::<u8, char>::new();
        assert_eq!(env_base.depth(), 1);

        let mut env2 = env_base.clone();
        assert_eq!(env_base.depth(), 1);
        assert_eq!(env2.depth(), 1);

        env2.insert(1, 'a');
        let env3 = env2.clone();
        assert_eq!(env_base.depth(), 1);
        assert_eq!(env2.depth(), 1);
        assert_eq!(env3.depth(), 1);

        env2.insert(1, 'b');
        assert_eq!(env2.depth(), 2);
        assert_eq!(env3.depth(), 1);

        let mut env4 = env2.clone();
        assert_eq!(env_base.depth(), 1);
        assert_eq!(env4.depth(), 2);
        env4.insert(1, 'y');
        assert_eq!(env4.depth(), 3);

        env_base.insert(1, 'z');
        assert_eq!(env_base.depth(), 1);
        assert_eq!(env2.depth(), 2);
        assert_eq!(env3.depth(), 1);
        assert_eq!(env4.depth(), 3);
    }

    #[test]
    fn test_iter_layer() {
        let mut env_base = Environment::<u8, char>::new();
        assert_eq!(env_base.iter_layers().count(), 1);
        env_base.insert(1, 'a');
        assert_eq!(env_base.iter_layers().count(), 1);
        assert_eq!(env_base.iter_layers().next().unwrap().get(&1), Some(&'a'));
        assert_eq!(env_base.iter_layers().nth(1), None);
        let _ = env_base.clone();
        assert_eq!(env_base.iter_layers().count(), 1);
        env_base.insert(2, 'b');
        assert_eq!(env_base.iter_layers().count(), 1);

        let _env2 = env_base.clone();
        env_base.insert(3, 'c');
        assert_eq!(env_base.iter_layers().count(), 2);
        let mut iter = env_base.iter_layers();
        let map1 = iter.next().unwrap();
        assert_eq!(map1.get(&3), Some(&'c'));
        assert_eq!(map1.get(&2), None);
        assert_eq!(map1.get(&1), None);
        let map2 = iter.next().unwrap();
        assert_eq!(map2.get(&3), None);
        assert_eq!(map2.get(&2), Some(&'b'));
        assert_eq!(map2.get(&1), Some(&'a'));
        assert!(iter.next().is_none());
    }

    #[test]
    fn test_iter_elem() {
        let env_base = Environment::<u8, char>::new();
        assert!(env_base.iter_elems().next().is_none());

        let mut env_base = Environment::new();
        env_base.insert(1, 'a');
        env_base.insert(2, 'b');
        let mut iter_elems = env_base.iter_elems();
        assert!(iter_elems.next().is_some());
        assert!(iter_elems.next().is_some());
        assert!(iter_elems.next().is_none());
        assert!({
            let mut vec: Vec<_> = env_base.iter_elems().collect();
            vec.sort_unstable();
            vec == vec![(&1, &'a'), (&2, &'b')]
        });
        drop(iter_elems);

        let mut env2 = env_base.clone();
        env_base.insert(1, 'z');
        env2.insert(1, 'y');
        assert_eq!(env_base.iter_elems().count(), 3);
        assert_eq!(env2.iter_elems().count(), 3);
        assert_eq!(env_base.iter_elems().nth(2), Some((&1, &'z')));
        assert_eq!(env2.iter_elems().nth(2), Some((&1, &'y')));

        let mut iter_elems_base = env_base.iter_elems();
        let _ = iter_elems_base.next();
        let mut iter_elems2 = env2.iter_elems();
        let _ = iter_elems_base.next();
        let _ = iter_elems2.next();

        let mut env_base = Environment::new();
        env_base.insert(1, 'a');
        env_base.insert(2, 'b');
        let _ = env_base.clone();
        env_base.insert(1, 'z');
        env_base.insert(3, 'c');
        let hmap: HashMap<_, _> = env_base.iter_elems().collect();
        assert_eq!(hmap.len(), 3);
        assert_eq!(hmap[&1], &'z');
        assert_eq!(hmap[&2], &'b');
        assert_eq!(hmap[&3], &'c');
    }
}//! Utility module for formatting Nickel files using Topiary

use std::{
    fmt::Display,
    io::{Read, Write},
};

use topiary_core::{Language, Operation, TopiaryQuery, formatter};

#[derive(Debug)]
/// Errors that may be encountered during formatting
pub struct FormatError(topiary_core::FormatterError);

impl Display for FormatError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(f)
    }
}

/// Format a Nickel file being read from `input`, writing the result to `output`.
pub fn format(mut input: impl Read, mut output: impl Write) -> Result<(), FormatError> {
    let grammar = tree_sitter_nickel::LANGUAGE.into();
    let query = TopiaryQuery::new(&grammar, topiary_queries::nickel()).map_err(FormatError)?;
    let language = Language {
        name: "nickel".to_owned(),
        query,
        grammar,
        indent: None,
    };

    formatter(
        &mut input,
        &mut output,
        &language,
        Operation::Format {
            // We only enable the idempotency check in debug mode: it's useful to detect bugs in
            // the Nickel formatter, but we don't want to report an error or to make production
            // users pay the cost of the check, although this cost should be fairly low.
            skip_idempotence: !cfg!(debug_assertions),
            tolerate_parsing_errors: false,
        },
    )
    .map_err(FormatError)
}//! Define the type of labels.
//!
//! A label is a value holding metadata relative to contract checking. It gives the user useful
//! information about the context of a contract failure.
use std::{iter, rc::Rc};

use crate::{
    ast::MergeKind,
    eval::{
        cache::{Cache as EvalCache, CacheIndex},
        value::NickelValue,
    },
    identifier::LocIdent,
    position::PosIdx,
    term::{
        SealingKey,
        record::{Field, RecordData},
    },
    typ::{Type, TypeF},
};

use smallvec::SmallVec;

pub mod ty_path {
    //! Type paths.
    //!
    //! Checking higher-order contracts can involve a good share of intermediate contract checking.
    //! Take the following example:
    //! ```text
    //! (fun ev => fun cst => ev (fun x => cst))
    //!   | ((Number -> Number) -> Number) -> Number -> Number,
    //! ```
    //! Once called, various checks will be performed on the arguments of functions and their return
    //! values:
    //!
    //! 1. Check that `ev` provides a `Number` to `(fun x => cst)`
    //! 2. Check that `(fun x => cst)` returns a `Number`
    //! 3. Check that `ev (fun x => cst)` return a `Number`
    //! 4. etc.
    //!
    //! Each check can be linked to a base type occurrence (here, a `Number`) in the original type:
    //! ```text
    //! ((Number -> Number) -> Number) -> Number -> Number
    //!   ^^^^^1    ^^^^^^2    ^^^^^^3    etc.
    //! ```
    //!
    //! This is the information encoded by a type path: what part of the original type is currently
    //! being checked by this label. It is then reported to the user in case of a blame.
    //!
    //! Paths are encoded as lists of elements, specifying if the next step is either to go to the
    //! **domain** or to the **codomain**.
    //!
    //! When reporting a blame error on a record type, one faces the same situation as with
    //! higher-order functions: the precise cause of an error can correspond to a small subtype of
    //! the original record type. Type path elements can thus also consist of a record field,
    //! indicating that the path leading to the subtype of interest goes through a record via a
    //! particular field.

    use crate::{
        identifier::LocIdent,
        position::RawSpan,
        typ::{RecordRowF, RecordRowsIteratorItem, Type, TypeF},
    };

    use nickel_lang_vector::Vector;

    /// An element of a path type.
    #[derive(Debug, Clone, PartialEq, Eq, Copy)]
    pub enum Elem {
        Domain,
        Codomain,
        Field(LocIdent),
        Array,
        Dict,
    }

    /// We use an inline vector up to `n` elements, as paths as assumed to be reasonably small, and
    /// labels (thus paths) are cloned a lot. For small but non-empty paths, which we expect to be
    /// common, this avoids having a to copy a separate heap-allocation. We do pay a price that an
    /// empty path is bigger than an empty `Vec`.
    pub type Path = Vector<Elem, 4>;

    /// Determine if the path has no `Domain` arrow component in it.
    pub fn has_no_dom(p: &Path) -> bool {
        !p.iter().any(|elt| matches!(*elt, Elem::Domain))
    }

    /// Determine if the path is not higher order, that is, if it doesn't contain any arrow.
    pub fn has_no_arrow(p: &Path) -> bool {
        !p.iter()
            .any(|elt| matches!(*elt, Elem::Domain | Elem::Codomain))
    }

    #[derive(Clone, Debug)]
    /// Represent the span of a type path in the string representation of the corresponding type,
    /// together with additional data useful to error reporting.
    ///
    /// Produced by [`span`]. The last element of the path that could be matched with the type is
    /// returned, as well as the last element of the part of the path that could be matched which
    /// is an arrow element (`Domain` or `Codomain`).
    ///
    /// In the general case, this should be respectively the last element of the path and the last
    /// element of the path filtered by keeping only `Domain` and `Codomain`. But sometimes the
    /// `span` function couldn't make further progress:
    ///
    /// ```nickel
    /// let Foo = Array Num in
    /// let f : Num -> Foo = fun x => ["a"] in
    /// f 0
    /// ```
    ///
    /// This code will blame with path `[Codomain, Array]`. However, because the "alias" `Foo` is
    /// used for `Array Num`, we can't descend further inside `Foo` which doesn't have the shape
    /// `Array _`. `span` will stop here, and the last elements saved in `PathSpan` will both be
    /// `Codomain`, instead of `Array` and `Codomain`. This helps specializing the error message
    /// accordingly.
    pub struct PathSpan {
        /// The span of the subtype corresponding to the path.
        pub span: RawSpan,
        pub last: Option<Elem>,
        pub last_arrow_elem: Option<Elem>,
    }

    /// Return the span encoded (as well as additional data: see [PathSpan]) by a type path in the
    /// string representation of the corresponding type.
    ///
    /// Used in the error reporting of blame errors (see `crate::error::report_ty_path`).
    ///
    /// # Returns
    ///
    /// The function returns `None` if the position of the found subtype is not defined.
    ///
    /// # Example
    ///
    /// - Type path: `[Codomain, Domain]`
    /// - Type : `Num -> Num -> Num`
    /// - Return: `{start: 7, end: 10, last: Some(Domain), last_arrow_elem: Some(Domain)}`. The
    ///   span `(7, 10)` corresponds to the second `Num` occurrence.
    ///
    /// # Mismatch between `path` and `ty`
    ///
    /// If at some point the shape of the type `ty` doesn't correspond to the path (e.g. if the
    /// next element is `Array`, but the type isn't of the form `Array _`), `span` just reports the
    /// span of the whole current subtype.
    ///
    /// ```nickel
    /// let Foo = Array Num in
    /// ["a"] | Foo
    /// ```
    ///
    /// Here, the type path will contain an `Array` (added by the builtin implementation of the
    /// `Array` contract), but the original type will be `Foo`, which isn't of the form `Array _`.
    /// Thus we can't underline the subtype `_`, and stops at the whole `Array T`.
    pub fn span<'a, I>(mut path_it: std::iter::Peekable<I>, mut ty: &Type) -> Option<PathSpan>
    where
        I: Iterator<Item = &'a Elem>,
        I: std::clone::Clone,
    {
        while let TypeF::Forall { body, .. } = &ty.typ {
            ty = body.as_ref();
        }

        match (&ty.typ, path_it.next()) {
            (TypeF::Arrow(dom, codom), Some(next)) => match next {
                Elem::Domain => {
                    let path_span = span(path_it, dom.as_ref())?;
                    Some(PathSpan {
                        last: path_span.last.or(Some(*next)),
                        last_arrow_elem: path_span.last_arrow_elem.or(Some(*next)),
                        ..path_span
                    })
                }
                Elem::Codomain => {
                    let path_span = span(path_it, codom.as_ref())?;
                    Some(PathSpan {
                        last: path_span.last.or(Some(*next)),
                        last_arrow_elem: path_span.last_arrow_elem.or(Some(*next)),
                        ..path_span
                    })
                }
                _ => panic!(
                    "span(): \
                    seeing an arrow type, but the type path is neither domain nor codomain"
                ),
            },
            (TypeF::Record(rows), next @ Some(Elem::Field(ident))) => {
                for row_item in rows.iter() {
                    match row_item {
                        RecordRowsIteratorItem::Row(RecordRowF { id, typ: ty }) if id == *ident => {
                            let path_span = span(path_it, ty)?;

                            return Some(PathSpan {
                                last: path_span.last.or_else(|| next.copied()),
                                last_arrow_elem: path_span.last_arrow_elem,
                                ..path_span
                            });
                        }
                        RecordRowsIteratorItem::Row(RecordRowF { .. }) => (),
                        RecordRowsIteratorItem::TailDyn | RecordRowsIteratorItem::TailVar(_) => (),
                    }
                }

                panic!(
                    "span: current type path element indicates to go to field `{}`, \
                     but this field doesn't exist in {}",
                    ident,
                    Type::from(TypeF::Record(rows.clone())),
                )
            }
            (TypeF::Array(ty), Some(Elem::Array)) if ty.as_ref().typ == TypeF::Dyn =>
            // Dyn shouldn't be the target of any blame
            {
                panic!("span(): unexpected blame of a dyn contract inside an array")
            }
            (TypeF::Array(ty), next @ Some(Elem::Array)) => {
                let path_span = span(path_it, ty)?;

                Some(PathSpan {
                    last: path_span.last.or_else(|| next.copied()),
                    last_arrow_elem: path_span.last_arrow_elem,
                    ..path_span
                })
            }
            (TypeF::Dict { type_fields, .. }, next @ Some(Elem::Dict)) => {
                let path_span = span(path_it, type_fields)?;

                Some(PathSpan {
                    last: path_span.last.or_else(|| next.copied()),
                    last_arrow_elem: path_span.last_arrow_elem,
                    ..path_span
                })
            }
            // The type and the path don't match, or the path is empty. We stop here.
            _ => ty.pos.into_opt().map(|span| PathSpan {
                span,
                last: None,
                last_arrow_elem: None,
            }),
        }
    }
}

/// A blame label.
///
/// A label is associated to a contract check (introduced by an explicit contract annotation, or
/// implicitly by a merge expression) and contains information to report to the user when a
/// contract fails and a blame occurs.
/// It includes in particular a [type path][ty_path::Path] and a **polarity**.
///
/// # Polarity
///
/// One crucial aspect of first class contracts is to be able to check higher-order types, which
/// are types with arrows in it. Consider the simplest example:
///
/// ```text
/// f | Number -> Number
/// ```
///
/// This does not entail that `f` returns a `Number` in *every* situation. The identity function
/// `id = fun x => x` can certainly be given the type `Number -> Number`, but `id "a" = "a"` is not
/// a `Number`.
///
/// To satisfy the contract `Number -> Number` for `f` is to satisfy the predicate "if you give me
/// a `Number` as an argument, I give you a `Number` as a result". There is an additional contract
/// to be checked, which is not the responsibility of `f`, but the caller's (or context) one.
///
/// `f | Number -> Number` should thus be evaluated as `fun arg => ((f (arg | Number)) | Number)`,
/// but we want to report the failures of the two introduced subcontracts in a different way:
///
///  - The inner one (on the argument) says that `f` has been misused: it has been applied to
///    something that is not a `Number`.
///  - The outer one says that `f` failed to satisfy its contract, as it has been provided with a
///    `Number` (otherwise the inner contracts would have failed before) but failed to deliver a
///    `Number`.
///
/// This duality caller/callee or function/context is indicated by the polarity: the outer
/// corresponds to a *positive* polarity (the contract is on the term), while the inner corresponds
/// to a *negative* one (the contact is on the context). The polarity always starts as `true` in
/// user-written contracts, but is toggled in the argument contract when the interpreter decomposes
/// an higher order-contract. This also generalizes to higher types such as `((Number -> Number) ->
/// Number) -> Number` where the polarity alternates each time.
#[derive(Debug, Clone, PartialEq)]
pub struct Label {
    /// The type checked by the original contract.
    pub typ: Rc<Type>,

    /// Custom diagnostics set by user code. There might be several diagnostics stacked up, as some
    /// contracts might in turn apply other subcontracts.
    ///
    /// The last diagnostic of the stack is usually the current working diagnostic (the one mutated
    /// by corresponding primops), and the latest/most precise when a blame error is raised.
    pub diagnostics: SmallVec<[ContractDiagnostic; 1]>,

    /// The position of the original contract.
    pub span: PosIdx,

    /// The index corresponding to the value being checked. Set at run-time by the interpreter.
    pub arg_idx: Option<CacheIndex>,

    /// The original position of the value being checked. Set at run-time by the interpreter.
    pub arg_pos: PosIdx,

    /// The polarity, used for higher-order contracts, that specifies if the current contract is
    /// on the environment (ex, the argument of a function) or on the term.
    pub polarity: Polarity,

    /// The path of the type being currently checked in the original type.
    pub path: ty_path::Path,

    /// An environment mapping type variables to [`TypeVarData`]. Used by polymorphic contracts to
    /// decide which actions to take when encountering a `forall`.
    ///
    /// We use an associative map here instead of a proper hashmap because we never expect more
    /// than a few type variables in an expression. The locality of an array makes it competitive,
    /// and the empty case (which is overwhelmingly common) is smaller.
    pub type_environment: Vec<(SealingKey, TypeVarData)>,

    /// The name of the record field to report in blame errors. This is set
    /// while first transforming a record as part of the pending contract generation.
    /// Contract applications outside of records will have this field set to `None`.
    pub field_name: Option<LocIdent>,
}

/// Data about type variables that is needed for polymorphic contracts to decide which actions to
/// take.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TypeVarData {
    pub polarity: Polarity,
}

impl From<&TypeVarData> for NickelValue {
    fn from(value: &TypeVarData) -> Self {
        NickelValue::record_posless(RecordData {
            fields: [(
                LocIdent::new("polarity"),
                Field::from(NickelValue::from(value.polarity)),
            )]
            .into(),
            attrs: Default::default(),
            sealed_tail: None,
        })
    }
}

/// A polarity. See [`Label`]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Polarity {
    Positive,
    Negative,
}

impl Polarity {
    pub fn flip(self) -> Self {
        match self {
            Polarity::Positive => Polarity::Negative,
            Polarity::Negative => Polarity::Positive,
        }
    }
}

impl From<Polarity> for NickelValue {
    fn from(value: Polarity) -> Self {
        match value {
            Polarity::Positive => NickelValue::enum_tag_posless(LocIdent::new("Positive")),
            Polarity::Negative => NickelValue::enum_tag_posless(LocIdent::new("Negative")),
        }
    }
}

impl TryFrom<&NickelValue> for Polarity {
    type Error = ();

    fn try_from(value: &NickelValue) -> Result<Self, Self::Error> {
        match value.as_enum_tag().ok_or(())? {
            tag if tag.label() == "Positive" => Ok(Self::Positive),
            tag if tag.label() == "Negative" => Ok(Self::Negative),
            _ => Err(()),
        }
    }
}

/// Custom reporting diagnostic that can be set by user-code through the `label` API. Used to
/// customize contract error messages, and provide more context than "a contract has failed".
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ContractDiagnostic {
    /// The main error message tag to be printed together with the error message.
    pub message: Option<String>,
    /// Additional notes printed at the end of the message.
    pub notes: Vec<String>,
}

impl ContractDiagnostic {
    pub fn new() -> Self {
        Self::default()
    }

    /// Attach a message to this diagnostic, and return the updated value. Erase potential previous
    /// message.
    pub fn with_message(mut self, message: impl Into<String>) -> Self {
        self.message = Some(message.into());
        self
    }

    /// Attach notes to this diagnostic, and return the updated value. Erase potential previous
    /// notes.
    pub fn with_notes(mut self, notes: Vec<String>) -> Self {
        self.notes = notes;
        self
    }

    /// Append a note to this diagnostic.
    pub fn append_note(&mut self, note: impl Into<String>) {
        self.notes.push(note.into());
    }

    /// Return `true` if this diagnostic is empty, that is if `message` is either not set (`None`)
    /// or is set but empty, AND notes are empty.
    pub fn is_empty(&self) -> bool {
        self.message.as_ref().map(String::is_empty).unwrap_or(true) && self.notes.is_empty()
    }
}

impl Label {
    /// Generate a dummy label for testing purpose.
    pub fn dummy() -> Label {
        Label {
            typ: Rc::new(Type::from(TypeF::Number)),
            diagnostics: iter::once(
                ContractDiagnostic::new().with_message(String::from("testing")),
            )
            .collect(),
            polarity: Polarity::Positive,
            ..Default::default()
        }
    }

    pub fn get_evaluated_arg<EC: EvalCache>(&self, cache: &EC) -> Option<NickelValue> {
        self.arg_idx.clone().map(|idx| cache.get(idx).value)
    }

    /// Same as [`Self::with_diagnostic_message`], but mutate `self` in place.
    pub fn set_diagnostic_message(&mut self, message: impl Into<String>) {
        if let Some(current) = self.diagnostics.last_mut() {
            current.message = Some(message.into());
        } else {
            self.diagnostics
                .push(ContractDiagnostic::new().with_message(message));
        };
    }

    /// Set the message of the current diagnostic (the last diagnostic of the stack). Potentially
    /// erase the previous value.
    ///
    /// If the diagnostic stack is empty, this method pushes a new diagnostic with the given notes.
    pub fn with_diagnostic_message(mut self, message: impl Into<String>) -> Self {
        self.set_diagnostic_message(message);
        self
    }

    /// Same as [`Self::with_diagnostic_notes`], but mutate `self` in place.
    pub fn set_diagnostic_notes(&mut self, notes: Vec<String>) {
        if let Some(current) = self.diagnostics.last_mut() {
            current.notes = notes;
        } else {
            self.diagnostics
                .push(ContractDiagnostic::new().with_notes(notes));
        };
    }

    /// Set the notes of the current diagnostic (the last diagnostic of the stack). Potentially
    /// erase the previous value.
    ///
    /// If the diagnostic stack is empty, this method pushes a new diagnostic with the given notes.
    pub fn with_diagnostic_notes(mut self, notes: Vec<String>) -> Self {
        self.set_diagnostic_notes(notes);
        self
    }

    /// Appends a note to the current diagnostic (the last diagnostic of the stack). Potentially
    /// erases the previous value.
    ///
    /// If the diagnostic stack is empty, this method pushes a new diagnostic with the given note.
    pub fn with_append_diagnostic_note(mut self, note: impl Into<String>) -> Self {
        self.append_diagnostic_note(note);
        self
    }

    /// Same as [Self::with_append_diagnostic_note], but mutates `self` in place.
    pub fn append_diagnostic_note(&mut self, note: impl Into<String>) {
        if let Some(current) = self.diagnostics.last_mut() {
            current.append_note(note);
        } else {
            self.diagnostics
                .push(ContractDiagnostic::new().with_notes(vec![note.into()]));
        }
    }

    /// Return a reference to the current contract diagnostic, which is the last element of the
    /// stack, if any.
    pub fn current_diagnostic(&self) -> Option<&ContractDiagnostic> {
        self.diagnostics.last()
    }

    /// Push a new, fresh diagnostic on the stack if the current diagnostic isn't empty. This has
    /// the effect of saving the current diagnostic, that can't then be mutated anymore by the
    /// label's API.
    pub fn push_diagnostic(&mut self) {
        if matches!(self.current_diagnostic(), Some(diag) if !diag.is_empty()) {
            self.diagnostics.push(ContractDiagnostic::new());
        }
    }

    pub fn with_field_name(self, field_name: Option<LocIdent>) -> Self {
        Label { field_name, ..self }
    }

    /// Tests if the contract associated to this label might have polymorphic subcontracts
    /// (equivalently, if the contract is derived from a type which has free type variables). Such
    /// contracts are special, in particular because they aren't idempotent and thus can't be
    /// freely deduplicated.
    ///
    /// This check is an over approximation and might return `true` even if the contract is not
    /// polymorphic, in exchange of being fast (constant time).
    pub fn can_have_poly_ctrs(&self) -> bool {
        // Checking that the type environment is not empty is a bit coarse: what it actually checks
        // is that this contract is derived from the body of a `forall`. For example, in `forall a.
        // a -> Number`, `Number` isn't polymorphic, but `has_polymorphic_ctrs` will return `true`.
        !self.type_environment.is_empty()
    }
}

impl Default for Label {
    fn default() -> Label {
        Label {
            typ: Rc::new(Type::from(TypeF::Dyn)),
            span: PosIdx::NONE,
            polarity: Polarity::Positive,
            diagnostics: Default::default(),
            arg_idx: Default::default(),
            arg_pos: Default::default(),
            path: Default::default(),
            type_environment: Default::default(),
            field_name: None,
        }
    }
}

/// A merge label.
///
/// Like [`Label`], a merge label is used to carry and propagate error reporting data during the
/// evaluation. While [`Label`] is used for contracts, `MergeLabel` is used for merging. The latter
/// track less information than the former, but this information is still important. Indeed,
/// recursive merging of records usually can't track original positions very well. The merge label
/// allows to at least remember the original position of the merge, as written somewhere in a
/// Nickel source.
///
/// Additionally, merging arrays currently generates a contract and its associated label for which
/// we don't necessarily have a defined span at hand. The merge label makes it possible to fallback
/// to the original position of the merge.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub struct MergeLabel {
    /// The span of the original merge (which might then decompose into many others).
    pub span: PosIdx,
    pub kind: MergeKind,
}

impl From<Label> for MergeLabel {
    fn from(label: Label) -> Self {
        MergeLabel {
            span: label.span,
            kind: Default::default(),
        }
    }
